import { parseValue } from './hash-util.js';

/** @param {string} value @param {2|8|10|16|36} [radix=36] */
export default function fnv1a(value, radix = 36) {
    const str = parseValue(value);
    let h = 0x811c9dc5;
    for (let i = 0; i < str.length; i++) {
        h ^= str.codePointAt(i);
        h = (h >>> 0) * 0x01000193;
    }
    const result = h >>> 0;
    return result.toString(radix);
}
