import { AriaAttr2Prop } from '../../util/arias.js';

import AuiElementEntry from './index.js';

const AriaMapping = {};
for (const [k, v] of Object.entries(AriaAttr2Prop)) {
    if (v.endsWith('Element') || v.endsWith('Elements')) AriaMapping[k] = v;
}

const queryRef = ($box, query, cross) => {
    const args = cross ? { crossSlot: true, crossShadow: true, directChildren: true } : null;
    /** ref width id by default, some cases using another element without id, so using the node name as selector. */
    return $box.find('#' + query, args).get() || (query.startsWith('aui-') && $box.find(query, args).get());
};

/**
 * @template {'aria-activedescendant'|'aria-controls'|'aria-describedby'|'aria-details'|'aria-errormessage'|'aria-flowto'|'aria-labelledby'|'aria-owns'} T
 * @param {Element} element
 * @param {T} attr
 * @param {{$root?: AuiElement, ignoreSameScope?: boolean, preferNative?: boolean}} options
 * @param options.$root Root $element for reference lookup; falls back to global body.
 * @param options.ignoreSameScope Whether to ignore references in the element's scope.
 * @param options.preferNative Whether to prefer the element's native property when available.
 * @returns {T extends 'aria-activedescendant' ? Element : Array<Element>} Referenced element(s), based on the ARIA property type.
 * @returns {null} Invalid or ignored.
 * @returns {undefined} Not found.
 */
export default function getElementRef(element, attr, options = {}) {
    const prop = AriaMapping[attr];
    if (!prop) return null;

    if (options.preferNative && Reflect.has(element, prop)) return element[prop];
    const attrValue = (element.getAttribute(attr) ?? '').trim();
    if (!attrValue) return null;

    const getRef = (id) => {
        if (options.$root?.length) {
            const localRef = queryRef(options.$root, id, true);
            if (localRef) return localRef;
        }
        return queryRef(AuiElementEntry.$body, id, false);
    };
    const single = !prop.endsWith('s'),
        currentScope = element.getRootNode(),
        results = [],
        scopeRefs = [];
    let { ignoreSameScope } = options;
    for (const id of attrValue.split(/\s+/)) {
        if (!id) continue;
        const scopeRef = currentScope.getElementById(id);
        if (scopeRef) {
            scopeRefs.push(scopeRef);
        } else {
            const ref = getRef(id);
            if (ref) {
                ignoreSameScope = false;
                results.push(ref);
                if (single) break;
            }
        }
    }
    if (ignoreSameScope) return null;

    results.push(...scopeRefs);
    return results.length ? (single ? results[0] : results) : undefined;
}
