/** @jsxImportSource @gui/aui-devops */
import { define, Widget, Types } from '../../widget/widget.js';

import arrayAt from '../../util/array/at.js';
import { percent } from '../../util/number/percent.js';

import { TooltipNode } from './modules/index.js';
import { NS, Colors, TooltipClassName, Format, TabloopArgs, Action } from './modules/utils.js';

import style from './linear.less';

export class LinearData extends Widget {
    #cache = {};
    dataReceiver = (action, from, ...args) => {
        if (this.action?.[action]) {
            this.action[action](...args);
        }
    };
    didMount() {
        this.action = Action(this.$element, 'name');
    }
    setOption(name, value, oldValue) {
        if (name === 'items') {
            this.dispatcher('legend?', 'clearData');
        }
    }

    parseData() {
        const { items, color, nameField, valueField, colorField } = this.options,
            { valueFormat } = this.state,
            { error } = this.console,
            colors = Colors(color),
            _items = [],
            names = new Map(); // cache name item data.

        let total = 0,
            count = 0,
            colorIndex = 0;
        // 1n: create cache data, check color, create legend data (set total as first).
        items.forEach((item, i) => {
            const name = item[nameField],
                value = item[valueField],
                color = item[colorField] || arrayAt(colors, colorIndex++, true);
            const exist = names.get(name);
            if (exist) return error('Duplicate name will be ignored.', item);
            if (typeof value !== 'number' || value < 0) return error('Negative value will be ignored.', item);

            const _item = { name, acc: total, value, val: valueFormat(value), color, original: item };
            _items.push(_item);
            names.set(name, _item);
            total += value;
            if (value > 0) count++;
        });

        this.#cache.byName = names;
        this.dispatcher('legend?', 'setData', [total, valueFormat(total)], _items);
        return { items: _items, total, count };
    }

    itemArgs({ name, value, val, color }, i) {
        return {
            className: ['item', TooltipClassName.Item, TooltipClassName.FocusTarget],
            data: { type: 'circle', name, value, val },
            style: { color },
            tabIndex: i ? -1 : 0,
            onClick: this.onDataClick,
        };
    }

    onDataClick = (e) => {
        const { name } = e.target.dataset,
            { byName } = this.#cache,
            values = byName.get(name);
        this.dispatcher('box', 'onDataClick', values[0]);
    };
}

/** @extends {Widget<typeof Linear.options>} */
@define(`${NS}-linear`)
export class Linear extends LinearData {
    static options = {
        items: Types.array,
        color: Types.Union([Types.array, Types.Color]),
        valueFormat: Types.Union([Types.string, Types.function]),

        nameField: 'name',
        valueField: 'value',
        colorField: 'color',
    };
    static observers = ['items', 'color'];
    static styles = style;

    init() {
        const { valueFormat } = this.options;
        this.state = {
            valueFormat: Format(valueFormat),
        };
        this.dispatcher = this.useUnicom(['box', 'linear'], this.dataReceiver);
    }

    render() {
        const { items, total } = this.parseData();

        // 2n: create dom
        return (
            <>
                <aui-tabloop className="linear stack-box" {...TabloopArgs}>
                    <div className={['graph-box', TooltipClassName.Stack]}>
                        {items.map((item, i) => {
                            const args = this.itemArgs(item, i);
                            args.style['--size'] = total > 0 ? percent(item.value / total, 4) : null;
                            return <div {...args} />;
                        })}
                    </div>
                </aui-tabloop>
                <TooltipNode />
            </>
        );
    }
}
