import React, { cloneElement } from 'react';

import { WR } from '../../widget/widget.jsx';

export const Popover = $$.shell.wrapComponent(function (props) {
    const { children, disabled, ...args } = props,
        [trigger, ...contents] = $$.shell.flatArray(children),
        _disabled = disabled || trigger?.props?.disabled || false;
    return (
        <WR.Popover {...args} disabled={_disabled}>
            {cloneElement(trigger, { disabled: _disabled, slot: 'trigger' })}
            {contents}
        </WR.Popover>
    );
});

$$.shell.define('Popover', Popover);
