import React, { PureComponent } from 'react';

import { WR } from '../../widget/widget.jsx';

const { Tab } = WR;

export class TabList extends PureComponent {
    static defaultProps = {
        lazyLoad: false,
        destroy: false,
        active: 0,
        shrink: false,
    };

    constructor(props) {
        super(props);
        const { active } = props;
        this.state = {
            isAdding: false,
            active,
            prevActive: active,
            loaded: {
                [active]: true,
            },
        };
    }
    static getDerivedStateFromProps(nextProps, prevState) {
        const { active } = nextProps;
        if (active === prevState.prevActive) return null;
        return {
            active,
            prevActive: active,
            loaded: {
                ...prevState.loaded,
                [active]: true,
            },
        };
    }
    loaded(index) {
        const { loaded } = this.state;
        loaded[index] = true;
    }
    doTabChange = (args) => {
        switch (args.type) {
            case 'createNew':
                return this.setState({ isAdding: true });
            case 'cancelNew':
                return this.setState({ isAdding: false });
            case 'add':
            case 'edit':
            case 'remove':
                return this.setState({ isAdding: false }, () => {
                    this.props.doTabChange(args);
                });
        }
    };
    willChange = (index) => {
        if (this.props.willChange?.(index) === false) return false;
        this.loaded(index);
        if (this.props.lazyLoad || this.props.destroy) {
            const { promise, resolve } = Promise.withResolvers();
            this.setState({ active: index }, resolve);
            return promise;
        }
    };

    render() {
        const { children, lazyLoad, destroy, ...rest } = this.props,
            { isAdding, active, loaded } = this.state,
            scrollable = !rest.shrink && !rest.wrap && rest.type !== 'vertical';
        const dynamic = rest.dynamic && typeof rest.doTabChange === 'function',
            doTabChange = dynamic ? this.doTabChange : null;
        const mapping = (child, index) => {
            const isActive = index === active,
                contentLoaded = destroy ? isActive : lazyLoad ? isActive || loaded[index] : true;
            return { index, scrollable, loaded: contentLoaded };
        };
        const childNodes = $$.shell.flatArray(children, mapping),
            count = childNodes.length;

        return (
            <WR.Tablist {...rest} dynamic={dynamic} doTabChange={doTabChange} willChange={this.willChange}>
                {childNodes}
                {isAdding && (
                    <>
                        <Tab dynamic editable index={count} />
                        <div slot={count}>{rest.dynamic}</div>
                    </>
                )}
            </WR.Tablist>
        );
    }
}
export class TabPanel extends PureComponent {
    render() {
        const { index, scrollable, loaded, tab, style, children, ...rest } = this.props,
            Tag = $$.shell.htmlTagFromChildren(children) ?? 'div';

        return (
            <>
                <Tab {...rest} index={index}>
                    {tab}
                </Tab>
                {scrollable && (
                    <button slot="popup" type="button" value={index} disabled={rest.disabled} hidden={rest.hidden}>
                        {tab}
                    </button>
                )}
                <Tag slot={index} style={style}>
                    {loaded && children}
                </Tag>
            </>
        );
    }
}

// $$.shell.define('TabList', TabList);
$$.shell.define('Tabcontrol', TabList);
$$.shell.define('TabPanel', TabPanel);
