export const structure = {
    // mutex:true -> allow only one symbol display in a group;
    Before: {
        // useless
        mutex: true,
        reg: false,
    },
    Text: {
        mutex: true,
        reg: /\"(\^|\_|\<|\>).+\"/,
    },
    Grace: {
        mutex: true,
        reg: /{\/?[a-gA-G]}/,
    },
    Chord: {
        // useless now
        mutex: false,
        reg: false,
    },
    Decoration: {
        mutex: false,
        reg: /(H|L|\.|!tenuto!|!marcato!|!turn!|!uppermordent!|!lowermordent!|T|S|O|!fine!|!D.C.!|!D.S.!)(?!.*\")/g,
    },
    Dynamic: {
        mutex: true,
        reg: /(!ppp!|!pp!|!p!|!mp!|!mf!|!f!|!ff!|!fff!)(?!.*\")/,
    },
    SlurLeft: {
        mutex: true,
        reg: /\((?!\!)/,
    },
    Accidental: {
        mutex: true,
        reg: /(\^\^|__|\^|_|=)(?!.*\")/,
    },
    Note: {
        mutex: true,
        reg: /[a-gA-G](?!((.*\")|\}|(m?[pf]*!)))[,|']*\/*\d*/g,
        list: [/[^\/{}\|\]:!]?[a-gA-G](?![}!])/g],
    },
    Octave: {
        mutex: true,
        reg: /[,|']*(?!.*\")/g,
    },
    NoteLength: {
        mutex: true,
        reg: /\/*\d*(?!.*(\"|\}))/g,
    },
    SlurRight: {
        mutex: true,
        reg: /\)(?!\!)/,
    },
    After: {
        // useless
        mutex: true,
        reg: false,
    },
};

