const cache = new Map();
const getter = (el, name) => String(getComputedStyle(el).getPropertyValue(name) || '').trim();

/** @type {typeof $$.css.getValue} */
export default function getValue(name, element) {
    if (element) return getter(element, name);

    const _cache = cache.get(name);
    if (_cache != null) return _cache;

    const value = getter(document.documentElement, name);
    if (name.startsWith('--')) cache.set(name, value);
    return value;
}
