import { UIComponent } from '../../core/base/component.jsx';

export class RichCombobox extends UIComponent {
    widgetName = 'richcombobox';

    clear(clearboth) {
        return this.method('clear', clearboth === undefined || clearboth === true);
    }

    clearInput() {
        return this.method('clearInput');
    }

    getValue() {
        return this.method('getValue');
    }

    setValue() {
        return this.method('setValue');
    }

    checkValidation() {
        return this.method('checkValidation');
    }
}

$$.shell.define('RichCombobox', RichCombobox);
