import { error } from '../../core/base/log.js';

const _FIELDS = {
    textField: 'text',
    valueField: 'value',
    checkedField: 'checked',
    tooltipField: 'tooltip',
    disabledField: 'disabled',
    readonlyField: 'readonly',
    statusField: 'status',
    groupField: undefined,
    iconField: undefined,
    classField: undefined,
};

const _getFieldsObj = function (options) {
    const fieldsObj = {};
    Object.keys(_FIELDS).forEach(function (key) {
        fieldsObj[key] = options[key] || fieldsObj[key];
    });
    return fieldsObj;
};
function deepCopy(val) {
    if (val == null || Number.isNaN(val)) return val;
    try {
        return structuredClone(val);
    } catch (e) {
        return JSON.parse(JSON.stringify(val));
    }
}
const deepCopyArray = function (items) {
    if (items) return Array.isArray(items) ? deepCopy(items) : deepCopy([items])[0];
    return items === null ? null : undefined;
};
const randomId = function () {
    // eslint-disable-next-line aui/no-direct-$$
    return $$.string.xid('optionlist');
};
const formatSpace = function (text) {
    return text ? String(text).replaceAll(/\s/g, ' ') : '';
};
const checkSpace = function (text) {
    text = formatSpace(text);
    return String(text).includes(' ');
};
const getValueField = function (item, valueField) {
    return item ? String(item[valueField]).replaceAll(/\s+/g, '&nbsp') : '';
};
const formatItems = function (options, items) {
    items = items ? deepCopyArray(items) : [];
    const fieldsObj = _getFieldsObj(options),
        singleMode = options.type === 'single' || options.singleMode === true,
        unique = options.unique || false,
        itemsObj = {},
        list = [];
    let singleSelected = false;

    if (items?.length) {
        for (const item of items) {
            const textField = item[fieldsObj.textField],
                valueField = item[fieldsObj.valueField],
                checkedField = item[fieldsObj.checkedField],
                tooltipField = item[fieldsObj.tooltipField],
                disabledField = item[fieldsObj.disabledField],
                readonlyField = item[fieldsObj.readonlyField],
                statusField = item[fieldsObj.statusField],
                groupField = item[fieldsObj.groupField],
                iconField = item[fieldsObj.iconField],
                classField = item[fieldsObj.classField];

            if (!textField && textField !== 0) item[fieldsObj.textField] = '';
            if ((!valueField && typeof valueField !== 'number') || (typeof valueField === 'number' && String(valueField).length < 1)) item[fieldsObj.valueField] = randomId();
            if (!checkedField) item[fieldsObj.checkedField] = false;
            if (!tooltipField) item[fieldsObj.tooltipField] = '';
            if (!disabledField) item[fieldsObj.disabledField] = false;
            if (!readonlyField) item[fieldsObj.readonlyField] = false;
            if (!statusField) item[fieldsObj.statusField] = '';
            if (fieldsObj.groupField !== undefined && !groupField) item[fieldsObj.groupField] = '';
            if (fieldsObj.iconField !== undefined && !iconField) item[fieldsObj.iconField] = '';
            if (fieldsObj.classField !== undefined && !classField) item[fieldsObj.classField] = '';
            if (singleMode === true) {
                if (singleSelected === false && item[fieldsObj.checkedField] === true) {
                    singleSelected = true;
                } else if (singleSelected === true) {
                    item[fieldsObj.checkedField] = false;
                }
            }
            if (unique === true) {
                if (!itemsObj[getValueField(item, fieldsObj.valueField)]) {
                    itemsObj[getValueField(item, fieldsObj.valueField)] = item;
                    list.push(item);
                }
            } else {
                const value = getValueField(item, fieldsObj.valueField);
                if (itemsObj[value]) {
                    error('the value of items are repeated,please reset your items.');
                }
                itemsObj[value] = item;
                list.push(item);
            }
        }
    }

    return list;
};
const replaceSpace = function (text) {
    return text ? String(text).replaceAll(/\s+/g, '&nbsp') : '';
};
const uniqueData = function (items, fieldName) {
    const hash = {};

    return items.reduce(function (item, next) {
        if (!hash[next[fieldName]]) {
            hash[next[fieldName]] = true;
            item.push(next);
        }
        return item;
    }, []);
};
const checkMatch = function (item, searchKey, matchFields) {
    let isPass = false;
    if (typeof item === 'string') {
        if (item.replaceAll(/\s/g, ' ').toLowerCase().includes(searchKey.replaceAll(/\s/g, ' ').toLowerCase())) isPass = true;
    } else if (item.constructor === Object) {
        Object.keys(matchFields).forEach((key) => {
            const value = String(item[key]);
            if (matchFields[key] === true) {
                if (value.replaceAll(/\s/g, ' ').toLowerCase().includes(searchKey.replaceAll(/\s/g, ' ').toLowerCase())) isPass = true;
            } else {
                if (value === searchKey) isPass = true;
            }
        });
    }
    return isPass;
};
const getRegText = function (key, inputReg) {
    let result = key[key.length - 1].match(inputReg);
    result = !result || result.length === 0 ? key.slice(0, -1) : false;

    return result;
};
const mergeValueAndItems = function (options, items, value) {
    items = items ? deepCopyArray(items) : [];
    const fieldsObj = _getFieldsObj(options),
        singleMode = options.type === 'single' || options.singleMode === true,
        valueField = fieldsObj.valueField,
        checkedField = fieldsObj.checkedField,
        textField = fieldsObj.textField;
    let selected = [],
        unselected = [];

    if (value === null || (value && value.constructor === Array && value.length < 1)) {
        for (const item of items) {
            item[checkedField] = false;
            unselected.push(item);
        }
    } else if (value && typeof value === 'string') {
        let isMate = false;

        for (const item of items) {
            if (item[textField] === value) {
                isMate = true;
                item[checkedField] = true;
                selected.push(item);
            } else {
                item[checkedField] = false;
                unselected.push(item);
            }
        }

        if (isMate === false) {
            selected = {};
            selected[valueField] = randomId();
            selected[checkedField] = true;
            selected[textField] = value;
            selected = formatItems(options, [selected]);
            // items.push(selected[0]);
        }
    } else if (value && value.constructor === Object) {
        let isMate = false;

        for (const item of items) {
            if (item[valueField] === value[valueField]) {
                isMate = true;
                item[checkedField] = true;
                selected.push(item);
            } else {
                item[checkedField] = false;
                unselected.push(item);
            }
        }

        if (isMate === false) {
            selected = value;
            selected[checkedField] = true;
            selected = formatItems(options, [value]);
            //  items.push(selected[0]);
        }
    } else if (value && value.constructor === Array && value.length > 0) {
        const mateValue = [];

        for (const item of items) {
            let isMate = false;

            for (let j = 0; j < value.length; j++) {
                if (item[valueField] === value[j][valueField]) {
                    isMate = true;
                    item[checkedField] = true;
                    selected.push(item);
                    mateValue.push(value[j]);
                }
            }

            if (isMate === false) {
                item[checkedField] = false;
                unselected.push(item);
            }
        }

        for (let i = 0; i < value.length; i++) {
            let isMate = false;

            for (let j = 0; j < mateValue.length; j++) {
                if (value[i][valueField] === mateValue[j][valueField]) {
                    isMate = true;
                }
            }

            if (isMate === false) {
                value[i][checkedField] = true;
                selected.push(value[i]);
                //    items.push(value[i]);
            }
        }
    } else {
        for (const item of items) {
            if (item[checkedField] === true) {
                item[checkedField] = true;
                selected.push(item);
            } else {
                item[checkedField] = false;
                unselected.push(item);
            }
        }
    }
    if (selected.length < 1) {
        selected = options.type === 'single' ? null : [];
    } else if (singleMode === true) {
        selected = options.type === 'single' ? selected[0] : [selected[0]];
    }

    return {
        all: items,
        selected: selected,
        unselected: unselected,
    };
};
const checkSelectedChange = function (options, oldSelectedItems, selectedItems) {
    const fieldsObj = _getFieldsObj(options);
    let isChange = false;

    oldSelectedItems = !oldSelectedItems ? [] : oldSelectedItems.constructor === Object ? [oldSelectedItems] : oldSelectedItems;
    selectedItems = !selectedItems ? [] : selectedItems.constructor === Object ? [selectedItems] : selectedItems;

    if (oldSelectedItems.length === selectedItems.length) {
        let l = 0;

        for (const oldSelectedItem of oldSelectedItems) {
            for (const selectedItem of selectedItems) {
                if (oldSelectedItem[fieldsObj.valueField] === selectedItem[fieldsObj.valueField]) {
                    if (oldSelectedItem[fieldsObj.checkedField] === selectedItem[fieldsObj.checkedField]) {
                        l++;
                    }
                }
            }
        }

        if (oldSelectedItems.length !== l) isChange = true;
    } else {
        isChange = true;
    }

    return isChange;
};
const getCheckValue = function (items, options) {
    let selected = [];
    const fieldsObj = _getFieldsObj(options),
        checkedField = fieldsObj.checkedField;
    const value = options.value;
    if (value) {
        if (value.constructor === Object) {
            selected.push(value);
        } else if (value.constructor === Array) {
            selected = value;
        }
    } else if (items && items.constructor === Array) {
        selected = items.filter((item) => {
            return item[checkedField];
        });
    }
    return selected;
};
export {
    _getFieldsObj,
    deepCopyArray as deepcopy,
    randomId,
    checkSpace,
    formatSpace,
    formatItems,
    getValueField,
    replaceSpace,
    uniqueData,
    checkMatch,
    getRegText,
    mergeValueAndItems,
    checkSelectedChange,
    getCheckValue,
};
