import tinycolor from 'tinycolor2';

(function () {
    const options = {
        hueStep: 2, // Hue ladder
        saturationStep: 16, // Saturation ladder, light color
        saturationStep2: 5, // Saturation ladder, darker
        brightnessStep1: 5, // Brightness ladder, light color part
        brightnessStep2: 15, // Brightness ladder, dark color
        lightColorCount: 5, // Light color quantity, main color
        darkColorCount: 4, // Dark quantity, main color
        basicPalette: {
            // Basic swatches
            red: '#FF6666',
            orange: '#FF9922',
            blue: '#4499DD',
            green: '#33BF6F',
            purple: '#7E7EDD',
            gray: ['#FFFFFF', '#FAFAFA', '#F5F5F5', '#E8E8E8', '#D9D9D9', '#BFBFBF', '#8C8C8C', '#595959', '#262626', '#000000'],
        },
    };

    const method = {
        _getHue: function (hsv, i, light) {
            let hue;
            // Depending on the hue, the hue turns differently.
            if (Math.round(hsv.h) >= 60 && Math.round(hsv.h) <= 240) {
                hue = light ? Math.round(hsv.h) - options.hueStep * i : Math.round(hsv.h) + options.hueStep * i;
            } else {
                hue = light ? Math.round(hsv.h) + options.hueStep * i : Math.round(hsv.h) - options.hueStep * i;
            }
            if (hue < 0) {
                hue += 360;
            } else if (hue >= 360) {
                hue -= 360;
            }
            return hue;
        },

        _getSaturation: function (hsv, i, light) {
            // grey color don't change saturation
            if (hsv.h === 0 && hsv.s === 0) {
                return hsv.s;
            }
            let saturation;
            if (light) {
                saturation = Math.round(hsv.s * 100) - options.saturationStep * i;
            } else if (i === options.darkColorCount) {
                saturation = Math.round(hsv.s * 100) + options.saturationStep;
            } else {
                saturation = Math.round(hsv.s * 100) + options.saturationStep2 * i;
            }
            // Boundary value correction.
            if (saturation > 100) {
                saturation = 100;
            }
            // The s in the first cell is limited to between 6 and 10.
            if (light && i === options.lightColorCount && saturation > 10) {
                saturation = 10;
            }
            if (saturation < 6) {
                saturation = 6;
            }
            return saturation;
        },

        // lightness
        _getValue: function (hsv, i, light) {
            if (light) {
                return Math.round(hsv.v * 100) + options.brightnessStep1 * i;
            }
            return Math.round(hsv.v * 100) - options.brightnessStep2 * i;
        },

        // Generate the swatches.
        _colors: function (color) {
            const patterns = [],
                pColor = tinycolor(color),
                hsv = pColor.toHsv();
            for (let i = options.lightColorCount; i > 0; i -= 1) {
                const colorString = tinycolor({
                    h: this._getHue(hsv, i, true),
                    s: this._getSaturation(hsv, i, true),
                    v: this._getValue(hsv, i, true),
                }).toHexString();
                patterns.push(colorString);
            }
            patterns.push(pColor.toHexString());
            for (let i = 1; i <= options.darkColorCount; i += 1) {
                const colorString = tinycolor({
                    h: this._getHue(hsv, i),
                    s: this._getSaturation(hsv, i),
                    v: this._getValue(hsv, i),
                }).toHexString();
                patterns.push(colorString);
            }
            return patterns;
        },

        // Replace the swatches.
        _change: function (colors, type) {
            const style = document.documentElement.style;
            colors.forEach(function (color, i) {
                style.setProperty('--' + type + '-' + (i + 1), color);
            });
        },
    };

    Object.assign($$, {
        tinycolor: tinycolor,
        color: function (a, b) {
            const colorStr = Array.isArray(b) ? [a, '(', b.join(','), ')'].join('') : a.toString(),
                color = tinycolor(colorStr);
            const rgb = color.toRgb(),
                hsl = color.toHsl(),
                hsv = color.toHsv(),
                hex = color.toHex();
            if (/hs(l|v)a?\(360/i.test(colorStr)) {
                hsl.h = hsv.h = 360;
            }
            const obj = {
                _ok: color._ok,
                Opacity: Number.parseFloat(color._roundA.toFixed(2)),
                HEX: hex,
                RGB_R: rgb.r,
                RGB_G: rgb.g,
                RGB_B: rgb.b,
                HSL_H: Math.round(hsl.h),
                HSL_S: Number.parseFloat(hsl.s.toFixed(2)),
                HSL_L: Number.parseFloat(hsl.l.toFixed(2)),
                HSV_H: Math.round(hsv.h),
                HSV_S: Number.parseFloat(hsv.s.toFixed(2)),
                HSV_V: Number.parseFloat(hsv.v.toFixed(2)),
            };
            Object.assign(obj, {
                hex: '#' + obj.HEX,
                rgb: 'rgb(' + [obj.RGB_R, obj.RGB_G, obj.RGB_B].join(',') + ')',
                rgba: 'rgba(' + [obj.RGB_R, obj.RGB_G, obj.RGB_B, obj.Opacity].join(',') + ')',
                hsl: 'hsl(' + [obj.HSL_H, obj.HSL_S, obj.HSL_L].join(',') + ')',
                hsla: 'hsla(' + [obj.HSL_H, obj.HSL_S, obj.HSL_L, obj.Opacity].join(',') + ')',
                hsv: 'hsv(' + [obj.HSV_H, obj.HSV_S, obj.HSV_V].join(',') + ')',
                hsva: 'hsva(' + [obj.HSV_H, obj.HSV_S, obj.HSV_V, obj.Opacity].join(',') + ')',
            });
            return obj;
        },
        // palette
        colors: function (mainColor, isChange) {
            mainColor = (options.basicPalette[mainColor] && mainColor !== 'gray' ? options.basicPalette[mainColor] : mainColor) || 'blue';
            const colors = mainColor === 'gray' ? options.basicPalette.gray : method._colors(mainColor);
            if (isChange) {
                // replace color palette
                method._change(colors, 'theme');
            }

            return colors;
        },

        // getHue: (color) => tinycolor(color).toHsv().h,

        // getSaturation: (color) => tinycolor(color).toHsv().s * 100,

        // getLightness: (color) => tinycolor(color).toHsv().v * 100,
    });

    Object.assign($$.color, {
        /**
         * convert HSV to RGB.
         * @param {number} H 0~360
         * @param {number} S 0~1
         * @param {number} V 0~1
         * @returns {Array<number>} [R, G, B]
         */
        hsv2rgb: function (H, S, V) {
            const C = V * S,
                X = C * (1 - Math.abs(((H / 60) % 2) - 1)),
                m = V - C;
            const map = [
                [C, X, 0],
                [X, C, 0],
                [0, C, X],
                [0, X, C],
                [X, 0, C],
                [C, 0, X],
            ];
            let result = map[Math.floor(H / 60)];
            result = result.map(function (item) {
                return (item + m) * 255;
            });
            return result;
        },
        /**
         * convert RGB to HSV.
         * @param {number} R 0~255
         * @param {number} G 0~255
         * @param {number} B 0~255
         * @returns {Array<number>} [H, S, V]
         */
        rgb2hsv: function (R, G, B) {
            const max = Math.max(R, G, B),
                min = Math.min(R, G, B),
                diff = max - min,
                result = [0, 0, max / 255];
            if (diff === 0) {
                result[0] = 0;
            } else if (max === R) {
                result[0] = 60 * ((G - B) / diff);
            } else if (max === G) {
                result[0] = 60 * ((B - R) / diff + 2);
            } else if (max === B) {
                result[0] = 60 * ((R - G) / diff + 4);
            }
            result[1] = max === 0 ? 0 : diff / max;
            return result;
        },
    });
})();
