/** @jsxImportSource @gui/aui-devops */
/* eslint-disable unicorn/dom-node-dataset */
import { define, Widget } from '../../widget/widget.js';
import { error } from '../base/log.js';
import { onload, idleLoad } from '../base/onload.js';
import $ from '../element/index.js';
import { textContents } from '../element/text-contents.js';

import { isEvent } from '../../util/type/types.js';

import '../../features/popup/pop.js';

import style from './tooltip.less';

const { touchable } = $$.browser;
const types = new Set([true, 'diff', 'ifneed', 'diffneed']);

/// Add custom tooltip function interface in show.
// if (typeof $$.tooltip === 'function') {
//     content = content.replaceAll('\\n', '\n');
//     hide = $$.tooltip(element, content);
// }

/**
 * Get related attributes of tooltip option.
 * @param {string} val the tooltip option value.
 * @param {"label"|"description"} aria aria attribute name.
 */
export function tooltipAttr(val, aria = 'description') {
    if (types.has(val)) return { 'data-tooltip': String(val) };
    if (typeof val === 'string' && val) {
        return { 'data-tooltip': 'diffneed', ['aria-' + aria]: val };
    }
    return {};
}

let Pop,
    Locked = false;
const InitQueue = [];
const ExtraCached = new Map();
const StateKey = 'tooltipRegistered';
const Delegator = '[data-tooltip]';
const _Delegator = `${Delegator},[title]`;
const PopEventArgs = { directTree: true, checkDisabled: false };

export function addTooltip(host) {
    const root = host.shadowRoot || host;
    if (Pop) {
        if (!ExtraCached.has(root)) {
            ExtraCached.set(root, true);
            idleLoad(() => {
                $$.fn(host.setState, host)({ [StateKey]: true }, false);
                Pop.method('bindTriggerEvent', null, $(root), _Delegator, PopEventArgs);
            });
        }
    } else {
        InitQueue.push(root);
    }
}

function getContent(element, type, title) {
    function innerText(element, useQuery) {
        if (!element) return '';
        return textContents(element, useQuery === false ? '*' : ':not([data-tooltip])').join('');
    }
    function pseudoContent(pseudo) {
        const v = getComputedStyle(element, pseudo).content.replaceAll(`"`, '');
        return (v !== 'none' && v) || '';
    }
    function getRef(idlRef, idRef) {
        if (idlRef?.length) return idlRef;
        if (idRef?.length) {
            const root = element.getRootNode();
            return idRef.split(' ').flatMap((id) => root.getElementById(id) || []);
        }
        return [];
    }
    function getBy(attr, idl, refAttr) {
        const isDiff = type.includes('diff'),
            val = element.getAttribute(attr),
            ref = getRef(element[idl], element.getAttribute(refAttr));
        if (ref.length) {
            const contents = ref.flatMap((ref) => {
                const attrVal = ref.getAttribute('aria-label') || (attr !== 'aria-label' && ref.getAttribute(attr)),
                    textVal = innerText(ref);
                if (attrVal && (!textVal || textVal !== attrVal)) return attrVal;
                if (textVal && (!isDiff || !ref.checkVisibility({ visibilityProperty: true, opacityProperty: true }))) return textVal;
                return [];
            });
            if (contents.length) return contents.join('\n');
            if (isDiff) return '';
        }
        return val || '';
    }

    // content must exists.
    function diff(content, text) {
        if (!content) return false;
        const div = document.createElement('div');
        div.textContent = content;
        $.$body.append(div);
        const v = div.textContent !== text;
        div.remove();
        return v;
    }
    const join = (arr) => arr.join('\n').trim();

    const $element = $(element);
    let text = innerText(element),
        content = '',
        overflow = String(type).endsWith('need') && $element.textOverflow();

    if (!text) {
        if (overflow === true) {
            text = join([pseudoContent('::before'), pseudoContent('::after')]);
        } else if (overflow && typeof overflow === 'string') {
            text = overflow;
            overflow = true;
        }
    }

    if (type !== 'ifneed') {
        // label & label-by.
        content = getBy('aria-label', 'ariaLabelledByElements', 'aria-labelledby');
        // non-label(by) & title => set label.
        if (!content && title) {
            content = title;
            element.setAttribute('aria-label', content);
        }
        // placeholder
        if (!content && element.localName === 'input') content = element.getAttribute('placeholder');
        // aria-description & aria-describedby
        if (!content) content = getBy('aria-description', 'ariaDescribedByElements', 'aria-describedby');
        if (!content) {
            const reference = element.getAttribute('data-tooltip-reference');
            if (reference) {
                const target = $element.find(reference, { crossShadow: true, crossSlot: true }).get();
                content = innerText(target, false);
            }
        }
        content = (content || '').trim();
    }
    switch (type) {
        case 'true':
            return content || text;
        case 'diff':
            return diff(content, text) ? content : null;
        case 'ifneed':
            if (overflow) {
                return text;
            } else if (text) {
                // only in ifneed mode.
                if (Number.parseFloat($element.css('font-size')) === 0) return text;
            }
            break;
        case 'diffneed': {
            const arr = [];
            if (diff(content, text)) arr.push(content);
            if (overflow) {
                if (text) {
                    arr.push(text);
                } else {
                    error('Unexpected overflow element with empty innerText:', element);
                }
            }
            return join(arr);
        }
    }
    return null;
}

const GlobalTarget = $.$body;
onload(() => GlobalTarget.append(<aui-tooltip />));
function initPop(pop, shouldInit) {
    if (!shouldInit) return;
    Pop = pop;
    while (InitQueue.length) {
        addTooltip(InitQueue.shift());
    }
    const $tooltip = $(Pop.firstChild);
    const lockClose = (...args) => Pop.method('tryLockClose', ...args);
    const delegateStack = new Set();
    function currentElement(of) {
        const event = isEvent(of);
        let target = $(of).get();
        if (!target) return {};
        let root = target.getRootNode(),
            inSlot = 0;
        const inShadow = root.nodeType === Node.DOCUMENT_FRAGMENT_NODE;
        if (event) {
            const { delegateTarget } = of;
            if (delegateTarget && (!inShadow || root !== delegateTarget)) {
                inSlot = delegateTarget === GlobalTarget.get() ? delegateStack.size : $(target).closest('slot', of.delegateTarget).length;
            }
        }
        while (root.nodeType === Node.DOCUMENT_FRAGMENT_NODE) {
            target = root.host;
            if ($$.fn(target.getState, target)(StateKey)) {
                delegateStack.add(root);
                break;
            } else {
                root = target.getRootNode();
            }
        }
        const global = root.nodeType === Node.DOCUMENT_NODE,
            delegator = global ? Delegator : _Delegator;
        return { global, element: inSlot > 0 ? null : $(of).closest(delegator, root).get() };
    }
    function preventShow(v) {
        delegateStack.clear();
        return v || false;
    }
    function tryToggle(isShow, args) {
        const { ofElement } = args,
            { global, element } = currentElement(ofElement);
        if (ofElement != null && (!element || Locked)) return preventShow();
        if (isShow) {
            const useMousePosition = element.getAttribute('data-tooltip-anchor');
            if (!touchable && String(useMousePosition).startsWith('element(') && useMousePosition.at(-1) === ')') {
                args.ofElement = element;
                const params = useMousePosition.slice(8, -1);
                params.split(';').forEach((param) => {
                    const [k, v] = param.split('=');
                    if (k && v) args[k.trim()] = v.trim();
                });
            }
            if (element.title) {
                if (global) {
                    element.dataset.title = element.title;
                } else {
                    // force convert non-global title to aria.
                    const type = element.dataset.tooltip;
                    if (type == null) {
                        element.setAttribute('data-tooltip', 'diffneed');
                        element.setAttribute('aria-label', element.title);
                    } else if (type === 'false' || type === 'true') {
                        element.setAttribute(element.role || $.is(element, ':tabbable') ? 'aria-label' : 'aria-description', element.title);
                    }
                }
                element.removeAttribute('title');
            }
        }
        return true;
    }
    function willShow({ ofElement }) {
        const { element } = currentElement(ofElement),
            type = element?.getAttribute('data-tooltip');
        // ignore nested tooltip
        if (!element || !type) return preventShow();

        const wrap = element.getAttribute('data-tooltip-wrap') ?? 'true',
            title = element.dataset.title,
            content = getContent(element, type, title);
        if (!content) return preventShow();

        let children = wrap === 'true' ? content.split(/\\n|\n/g) : [content];
        children = children.flatMap((child, i) => (i > 0 ? [<br />] : []).concat(<span>{child}</span>));
        $tooltip.attr('data-wrap', wrap).setChildren(children);
        lockClose(true);
        Locked = true;
        setTimeout(() => (Locked = false));
    }
    function onShow() {
        idleLoad(() => delegateStack.clear());
    }
    function onHide() {
        $tooltip.setChildren();
        lockClose(false, true);
    }
    Pop.setOptions({
        blockClose: true,
        classify: 'gray',
        delegate: Delegator,
        enableLongTouch: true,
        eventArgs: PopEventArgs,
        eventScope: 'body',
        focusable: false,
        mobileView: false,
        modalable: false,
        tabloop: false,
        triggerEvent: 'hover',
        usePointer: !touchable,
        at: `${touchable ? 'left' : 'right'} ${touchable ? 'top' : 'bottom'}`,
        my: `left+8 ${touchable ? 'bottom-' : 'top+'}16`,
        width: ['1em', 'revert', 'min(528px,80%)'],
        _tryToggle: tryToggle,
        _tryHint: true,
        willShow,
        onShow,
        onHide,
    });
}

@define('tooltip')
export class Tooltip extends Widget {
    static styles = style;
    render() {
        return (
            <>
                <aui-pop id="tooltip" ref={this.ref(initPop)}>
                    <div className="tooltip" />
                </aui-pop>
                <slot />
            </>
        );
    }
}
