import kebabCase from '../string/kebab-case.js';

import { _parser } from './_parser.js';

/** @type {typeof $$.css.stringify} */
export default function stringify(value) {
    const parser = _parser();
    const list = Object.entries(value).flatMap(([k, v]) => {
        v = parser(v, k);
        return v == null ? [] : `${kebabCase(k)}:${v};`;
    });
    return list.join('');
}
