import { _parser } from './_parser.js';

/** @type {typeof $$.css.clamp} */
export default function clamp(value, processor) {
    const result = Array.from({ length: 3 });
    if (value == null) return result;

    const parser = _parser(processor, 'width');
    if (Array.isArray(value)) {
        let range = value;
        if (range.length > 2) {
            const [min, prefer, max] = range;
            range = [min, max];
            result[1] = parser(prefer);
        }
        result[0] = parser(range[0]);
        result[2] = parser(range[1]);
    } else {
        result[1] = parser(value);
    }
    return result;
}
