import React, { cloneElement, PureComponent } from 'react';

import { WR } from '../../widget/widget.jsx';

const Clone = (child) => (child.props.slot ? child : cloneElement(child, { role: 'menuitem', type: 'bald' }));
export class ButtonGroup extends PureComponent {
    render() {
        const { children, ...rest } = this.props;
        return <WR.ButtonGroup {...rest}>{$$.shell.flatArray(children, Clone)}</WR.ButtonGroup>;
    }
}

$$.shell.define('ButtonGroup', ButtonGroup);
