/** @jsxImportSource @gui/aui-devops */
import { callbackResult } from '../../core/base/internal.js';
import { error } from '../../core/base/log.js';
import { widget } from '../../core/extend/widget.js';

import '../comboboxshell/comboboxshell.js';
import '../selection/selection-old.js';
import * as _$ from '../selection/dataset-old.js';

const ComboboxShellArgs = { popupWidth: [0], scrollable: false, resetScroll: false };

(function () {
    const noop = $$.fn();
    const ClassName = {
        Widget: 'aui-combobox',
        Content: 'aui-combobox-content',
        Ellipsis: 'aui-combobox-ellipsis',
        Icon: 'aui-combobox-icon',
        Listbox: 'aui-selection-listbox',
        None: 'aui-combobox-none',
    };
    widget('aui5.combobox', {
        options: {
            // data
            items: [],
            // Properties that display content
            textField: 'text',
            // value properties
            valueField: 'value',
            // Whether the property is selected or not
            checkedField: 'checked',
            // tooltip properties
            tooltipField: 'tooltip',
            // Whether to disable the property
            disabledField: 'disabled',
            // Grouping attributes
            groupField: undefined,
            iconField: undefined,
            matchFields: undefined,
            // Whether search is enabled or not
            searchable: true,
            // Searchbox watermark text
            searchPlaceholder: $$.I18N.combobox.placeholder,
            // CreateNew is enabled or not, if undefined, it will not be enabled by default
            createNewText: undefined,
            // Maximum number of displays per page
            lazyStep: 50,
            // For check options, assignments
            value: undefined,
            // Whether to weight based on a textField·
            unique: false,
            // No options included
            excludeChecked: false,
            // The width of a popup, by default or when set to "100%", is the same width as the control
            popupWidth: 'auto',
            // The maximum height of popup
            popupMaxHeight: 410,
            // width
            width: 220,
            // height
            height: undefined,
            // Control disabled
            disabled: false,
            // Control readonly
            readonly: false,
            // Displays text when not selected
            noneText: null,
            // Display text when selecting all
            allText: null,
            formatText: '',
            // According to the template
            prefix: '',
            // The minimalist model
            mini: false,
            // Compact model
            compact: false,
            template: '',
            groupTemplate: '',
            contentTemplate: '',
            filter: false,
            clearable: false,
            groupToggleable: false,
            icon: 'faui-caret-down',
            tooltip: undefined,
            customTrigger: false,
            maxlength: 255,
            searchDelay: 350,
            searchMinChars: 0,
            // A callback when search/lazyLoad
            doLoad: noop,
            // Click on the createNew callback
            doCreateNew: noop,
            willChange: noop,
            // This callback is triggered when the selected middle item changes
            onChange: noop,
            willShow: noop,
            willHide: noop,
            onShow: noop,
            onHide: noop,
        },
        _initMember: function () {
            this._deepcopy = _$.deepcopy;
            this._getCheckValue = _$.getCheckValue;
            this._uniqueData = _$.uniqueData;
            this._formatItems = _$.formatItems;
            this._doLoad = this.options.doLoad !== noop;
            this._oldValue = this.options.value;
            this.contentTemplate = this.options.contentTemplate;
            this._items = [];

            return this;
        },
        _create: function () {
            this._initMember();
            this._items = this._deepcopy(this.options.items);
            this._items = this._formatItems(this.options, this._items);

            if (this._items.length > this._uniqueData(this._items, this.options.valueField).length) {
                error('Value cannot be repeated.');
            }
            this._initPopup()._initList();
        },
        _initPopup: function () {
            this.$element.addClass(ClassName.Widget);
            const { aria, compact, customTrigger, disabled, icon, height, width, mini, popupWidth, popupMaxHeight, tooltip } = this.options,
                args = { aria, compact, disabled, icon, height, width, mini, tooltip };
            // const forwardArgs = forwardOptions(args);
            this.comboboxShell = (
                <aui-combobox-shell
                    part="combobox-shell"
                    {...ComboboxShellArgs}
                    {...args}
                    dynamicSize={this._doLoad !== false}
                    popupHeight={[, popupMaxHeight]} // eslint-disable-line no-sparse-arrays
                    popupWidth={[, popupWidth, '50vw']} // eslint-disable-line no-sparse-arrays
                    onClear={this.onClear.bind(this)}
                    willShow={this.willShow.bind(this)}
                    willHide={() => this._callback('willHide') !== false}
                    onShow={this.onShow.bind(this)}
                    onHide={this.onHide.bind(this)}
                >
                    <div id={'aui_combobox_' + this.uuid}></div>
                    <div slot="content" id={'aui_combobox_content_' + this.uuid} className={ClassName.Content}></div>
                    {customTrigger && <div slot="trigger">{this.$element.children().eq(0)}</div>}
                </aui-combobox-shell>
            );

            this.element.append(this.comboboxShell);
            return this;
        },
        _initList: function () {
            const options = this.options,
                id = 'aui_combobox_' + this.uuid;
            this.$listElement = this.$element.find(`#${id}`);

            this.$listElement.selection({
                type: 'single',
                focus: true,
                items: this._deepcopy(this._items),
                textField: options.textField,
                checkedField: options.checkedField,
                tooltipField: options.tooltipField,
                disabledField: options.disabledField,
                iconField: options.iconField,
                valueField: options.valueField,
                groupField: options.groupField,
                matchFields: options.matchFields,
                searchable: options.searchable,
                placeholder: options.searchPlaceholder,
                createNewText: options.createNewText,
                lazyStep: options.lazyStep,
                readonly: options.readonly,
                value: this._deepcopy(options.value),
                unique: options.unique,
                excludeChecked: options.excludeChecked,
                defaultActive: false,
                searchDelay: options.searchDelay,
                searchMinChars: options.searchMinChars,
                maxlength: options.maxlength,
                template: options.template,
                groupTemplate: options.groupTemplate,
                groupToggleable: options.groupToggleable,
                status: { show: false },
                singleMode: true,
                forceMatchStep: options.forceMatchStep,
                doLoad: options.doLoad,
                doCreateNew: options.doCreateNew,
                onChange: this._onChange.bind(this),
                onSelected: (value) => {
                    this.comboboxShell.setOption('status', { show: false });
                },
            });

            this.$listElement.attr('tabindex', '-1');
            this._items = this._deepcopy(this.$listElement.selection('getAllItems'));
            this._oldValue = this._deepcopy(this.getValue());
            this._updateContent(this._oldValue);
            this._updateButton(this._oldValue);

            return this;
        },
        willShow: function () {
            if (this._callback('willShow') === false) {
                return false;
            } else {
                // this.$popup.css('min-width', this.$element.outerWidth());
                this.$listElement.selection('option', { status: { show: true } });
                return true;
            }
        },

        onShow: function (e) {
            this.$listElement.find('.' + ClassName.Listbox).height('auto');
            if (!$$.browser.touchable) {
                if (this.options.searchable === true) {
                    this.$listElement.find('aui-searchbox').focus();
                } else {
                    this.$listElement.focus();
                }
            }
            this.comboboxShell.setOption('status', { show: true });
            this.$listElement.selection('handleLoading');
            this._callback('onShow');
        },
        _isPopMobile: function () {
            return $$.mobileView && $$.browser.touchable;
        },
        onHide: function (e) {
            if (this.options.searchable === true) this.$listElement.selection('updateSearchboxValue', '');
            this.$listElement.selection('setStatus', false);
            this.$listElement.selection('option', { value: this._deepcopy(this._oldValue) });
            this.$element.focus();
            this._callback('onHide');
        },
        _onChange: function (args) {
            const oldValue = this._deepcopy(this.options.filter === true && !args.oldValue ? 'all' : args.oldValue),
                newValue = this._deepcopy(this.options.filter === true && !this.getValue() ? 'all' : args.newValue);

            callbackResult(this._callback('willChange', { oldValue: oldValue, newValue: newValue }), (isChange) => {
                this._oldValue = isChange === false ? oldValue : args.newValue;
                this.comboboxShell.setOption('status', { show: false });
                if (isChange === false) {
                    return false;
                }
                this._items = this._deepcopy(args.all);
                this._updateContent(this._oldValue);
                this._updateButton(this._oldValue);

                if (this.options.onChange !== noop) {
                    this.$element[0].dataset.dirty = true;
                    this._handler('onChange', { oldValue: oldValue, newValue: newValue });
                }
            });
        },
        onClear: function (e) {
            this.$listElement.selection('clearSelection', true, this.options.clearable === 'force');
            this._updateContent(null);
            this._updateButton(null);
        },
        _updateButton: function (value) {
            const check = value || this.getValue();
            if (this.options.clearable !== false) {
                this.comboboxShell.setAttribute('clearable', check ? (this.options.clearable === 'force' ? true : check[this.options.disabledField] ? 'disabled' : true) : false);
                this.comboboxShell.setAttribute(
                    'clearTooltip',
                    this.options.clearable === true && check?.[this.options.disabledField] ? $$.I18N.comboboxshell.disableClear : $$.I18N.comboboxshell.clear
                );
            }
        },
        _updateContent: function (check) {
            if (this.options.customTrigger === false) {
                this.$element.find(`#aui_combobox_content_${this.uuid}`).empty();

                const isNone = !check && this.options.filter === false,
                    icon = check ? check[this.options.iconField] : undefined;
                let text = check
                    ? check[this.options.textField]
                    : this.options.filter === true
                      ? (this.options.allText ?? $$.I18N.combobox.allText)
                      : (this.options.noneText ?? $$.I18N.combobox.none);

                const formatTextValue = this.options.formatText || $$.I18N.combobox.format;
                if (this.options.prefix.length > 0) {
                    text = formatTextValue.replace('{1}', text);
                    text = text.replace('{0}', this.options.prefix);
                }
                const content = (
                    <div data-placeholder={isNone} className={isNone ? ClassName.None : ClassName.Ellipsis}>
                        {icon && icon.length > 0 && <span className={`${ClassName.Icon} ${icon}`}></span>}
                        {this.contentTemplate || text}
                    </div>
                );
                this.$element.find(`#aui_combobox_content_${this.uuid}`).append(content);
            }
            return this;
        },
        getValue: function () {
            const value = this.$listElement.selection('getSelectedItems');
            return value instanceof jQuery ? null : value;
        },
        verify: function () {
            const value = this.getValue();
            return [value];
        },
        clear: function () {
            this.$listElement.selection('clearSelection', true, true);
            this._updateContent(null);
            this._updateButton(null);

            return this;
        },
        _setOption: function (key, value) {
            const oldValue = this.options[key];
            if (value === oldValue) return false;
            this.options[key] = value;
            switch (key) {
                case 'items':
                    if (this._doLoad === false) {
                        const val = this._getCheckValue(value, this.options),
                            newValue = value?.length === 0 ? undefined : this.options.value || (val?.length > 0 ? val[0] : undefined);
                        this.$listElement.selection('option', { value: this._deepcopy(newValue) });
                        this.$listElement.selection('option', { items: this._deepcopy(value) });
                        this._items = this._deepcopy(value);
                        this._oldValue = this.getValue();
                        this._updateContent(this._oldValue);
                        this._updateButton(this._oldValue);

                        if (this._items.length > this._uniqueData(this._items, this.options.valueField).length) {
                            error('Value cannot be repeated.');
                        }
                    } else if (this._doLoad === true && this.options.items.length > 0) {
                        error('After the doLoad is configured, the items are invalid.');
                    }
                    break;
                case 'disabled':
                    this.comboboxShell.setAttribute('disabled', !!value);
                    break;
                case 'readonly':
                    this.comboboxShell.setAttribute('readonly', !!value);
                    this.$listElement.selection('option', { readonly: !!value });
                    break;
                case 'tooltip':
                    this.comboboxShell.setAttribute('tooltip', value ?? null);
                    break;
                case 'prefix':
                    this._updateContent(this._oldValue);
                    break;
                case 'value':
                    this._items = this._deepcopy(this.$listElement.selection('getAllItems'));
                    this.$listElement.selection('option', { value: this._deepcopy(value) });

                    this._oldValue = this._deepcopy(this.getValue());
                    this._updateContent(this._oldValue);
                    this._updateButton(this._oldValue);
                    break;
                case 'contentTemplate':
                    this.contentTemplate = value;
                    this._updateContent(this._oldValue);
                    break;
                case 'searchPlaceholder':
                    this.$listElement.selection('option', { searchPlaceholder: value });
                    break;
                default:
                    break;
            }
        },
    });
})();
