import React, { PureComponent } from 'react';

import { info } from '../../core/base/log.js';
import { WR } from '../../widget/widget.jsx';

export class Accordion extends PureComponent {
    static defaultProps = {
        lazyLoad: true,
        status: { show: false },
    };

    constructor(props) {
        super(props);

        this.state = {
            contentLoaded: props.status.show,
        };
    }

    getHeader(children) {
        return Array.isArray(children) ? children[0] : null;
    }

    getBody(children) {
        return Array.isArray(children) ? children[1] : children;
    }

    handleWillShow = () => {
        this.setState({
            contentLoaded: true,
        });
    };

    render() {
        const { children, ...args } = this.props,
            header = this.getHeader(children),
            body = this.getBody(children);
        let { lazyLoad } = args;
        const Tag = $$.shell.htmlTagFromChildren(body, (type, isNative) => {
            if (lazyLoad && !isNative) {
                info('Got a non-native element as Accordion body; lazyLoad has been invalidated.', type?.displayName || type?.name || type);
                lazyLoad = false;
            }
            return type;
        });

        return (
            <WR.Accordion {...args} lazyLoad={lazyLoad} willShow={this.handleWillShow}>
                {header && React.cloneElement(header, { slot: 'header' })}
                {!lazyLoad || this.state.contentLoaded ? React.cloneElement(body, { slot: 'body' }) : <Tag slot="body" />}
            </WR.Accordion>
        );
    }
}

$$.shell.define('Accordion', Accordion);
