/** @jsxImportSource @gui/aui-devops */
import { widget } from '../../core/extend/widget.js';

import clearTime from '../../util/date/clear-time.js';
import dateFormat from '../../util/date/format.js';
import { keyName } from '../../util/event/key-name.js';
import { navigation2D } from '../../util/event/navigation.js';
import swipe from '../../util/event/swipe.js';
import { isDate, isEmpty } from '../../util/type/types.js';

import * as calendarUtil from './calendarutil.js';
import './basecalendar.js';

(function () {
    'use strict';
    const noop = $$.fn();
    const I18N = $$.I18N.calendar;
    const _view = {
        month: 0,
        year: 1,
        decade: 2,
        century: 3,
    };
    const _constant = {
        CALENDAR_CLASS: 'aui-calendar',
        HEADER_CLASS: 'aui-calendar-header',
        BODY_CLASS: 'aui-calendar-body',
        TITLE_CLASS: 'aui-calendar-title',
        Button_Group_Class: 'aui-calendar-button-group',
        ARROW_CLASS: 'aui-calendar-arrow',
        LEFT_ICON_CLASS: 'faui-angle-left-s',
        RIGHT_ICON_CLASS: 'faui-angle-right-s',
        LEFT_DOUBLE_ICON_CLASS: 'faui-angle-double-left',
        RIGHT_DOUBLE_ICON_CLASS: 'faui-angle-double-right',
        Cross_Swipe_Class: 'aui-calendar-cross-swipe',
        MONTH_ITEM_SHADOW: 'aui-calendar-shadow',
        MONTHVIEW_CLASS: 'aui-calendar-month',
        YEARVIEW_CLASS: 'aui-calendar-year',
        DECADEVIEW_CLASS: 'aui-calendar-decade',
        CELL_CLASS: 'aui-calendar-cell',
        DISABLED_CLASS: 'disabled',
        ACTIVE_CLASS: 'active',
        CONTENT_CLASS: 'aui-basecalendar-content',
        BASE_CELL_CLASS: 'aui-basecalendar-cell',
        TODAY_CLASS: 'aui-calendar-today',
        CENTURY_VIEW_CLASS: 'aui-calendar-century',
        withEvent: 'aui-calendar-with-event',
    };

    widget('aui5.calendar', {
        section: true,
        _prefix: 'aui_calendar_',
        optionOrder: ['selectedDate', 'displayDate', 'enableDates'],
        options: {
            displayMode: 0, // month 0 year 1 decade 2
            firstDayOfWeek: 0, // Sunday
            selectedDate: null,
            displayDate: null,
            titleFormat: null,
            width: null,
            height: null,
            hasToday: true,
            type: 'single', // 'single'|'multiple'|'range'
            enableDates: {
                start: new Date(1900, 0, 1),
            },
            limitViewCrossEdge: true,
            items: null,
            lockView: false,
            withEvent: false,

            doRangeChange: noop,
            dayClick: noop,
            onChange: noop,
            todayClick: noop,
        },
        _create: function () {
            this._initData()._render()._initMember()._initEvent();
            this._updateDisplayMode(this._displayMode, null, false);
        },
        _initData: function () {
            this.leftArrowId = this._prefix + '_left_' + this.uuid;
            this.rightArrowId = this._prefix + '_right_' + this.uuid;
            this.cache = {};
            this.lockView = [_view.month, _view.year, _view.decade];

            this._updateDisplayDate(calendarUtil.displayDate(this.options.type, this.options.selectedDate, this.options.displayDate));
            this._getDisplayModeByLockView();

            if (this.options.lockView === true) {
                this.lockView = [this.options.displayMode];
            } else if (Array.isArray(this.options.lockView)) {
                this.lockView = this.options.lockView;
            }
            this.view = this._displayMode;
            this._syncCacheEnableDates();
            if (this.options.type === 'single' && isDate(this.options.selectedDate)) {
                this.cache.selectedDate = clearTime(this.options.selectedDate);
            }
            this.itemSource(this.options.items);
            return this;
        },
        _getDisplayModeByLockView: function () {
            this._displayMode = this.options.displayMode;
            if (Array.isArray(this.options.lockView)) {
                this.lockView = this.options.lockView;
                if (!this.options.lockView.includes(this.view)) this._displayMode = Math.min(...this.lockView);
            }
        },
        _syncCacheEnableDates: function () {
            let enableDates = this.options.enableDates;
            if (!enableDates) return false;
            if (Array.isArray(enableDates)) {
                const enableDatetime = {};
                enableDates = enableDates.sort((a, b) => a - b);
                enableDates.forEach(function (d) {
                    const y = d.getFullYear(),
                        m = d.getMonth(),
                        t = d.getDate();
                    if (!enableDatetime[y]) {
                        enableDatetime[y] = {};
                    }
                    if (!enableDatetime[y][m]) {
                        enableDatetime[y][m] = {};
                    }
                    enableDatetime[y][m][t] = 1;
                });
                this.cache.enableDatesObj = enableDatetime;
                this._min = enableDates[0];
                this._max = enableDates.at(-1);
            } else {
                const start = enableDates.start,
                    end = enableDates.end;
                this._min = start;
                this._max = end;

                this.cache.minDate = {
                    year: start?.getFullYear(),
                    month: start?.getMonth() || 0,
                    date: start?.getDate() || 1,
                };
                this.cache.maxDate = {
                    year: end?.getFullYear(),
                    month: end?.getMonth() || 0,
                    date: end?.getDate() || 1,
                };
            }
        },
        _initMember: function () {
            this.$year = this.$element.find(`.${_constant.YEARVIEW_CLASS}`);
            this.$decade = this.$element.find(`.${_constant.DECADEVIEW_CLASS}`);
            this.$view = this.$element.find('.view');
            this.$today = this.$element.find(`.${_constant.TODAY_CLASS}`);
            this.$century = this.$element.find(`.${_constant.CENTURY_VIEW_CLASS}`);
            return this;
        },
        _initEvent: function () {
            this.$left.on('click', this._onDateChange.bind(this, 'left'));
            this.$right.on('click', this._onDateChange.bind(this, 'right'));
            this.$cross.on('click', this._onDateChange.bind(this, 'cross'));
            this.$title.on('click', 'button', this._onViewChange.bind(this, 'title'));
            this.$year
                .on('click', `div.${_constant.CELL_CLASS}`, this._cellClick.bind(this, 'cellclick'))
                .on('keydown', `div.${_constant.CELL_CLASS}`, this._cellKeydown.bind(this))
                .on('keyup', `div.${_constant.CELL_CLASS}`, this._cellKeyup.bind(this));
            this.$decade
                .on('click', `div.${_constant.CELL_CLASS}`, this._cellClick.bind(this, 'cellclick'))
                .on('keydown', `div.${_constant.CELL_CLASS}`, this._cellKeydown.bind(this))
                .on('keyup', `div.${_constant.CELL_CLASS}`, this._cellKeyup.bind(this));
            this.$century
                .on('click', `div.${_constant.CELL_CLASS}`, this._cellClick.bind(this, 'cellclick'))
                .on('keydown', `div.${_constant.CELL_CLASS}`, this._cellKeydown.bind(this))
                .on('keyup', `div.${_constant.CELL_CLASS}`, this._cellKeyup.bind(this));

            this.$month?.on('click', `.${_constant.BASE_CELL_CLASS}`, this._onDayClick.bind(this));
            this.$month?.on('keyup', `.${_constant.BASE_CELL_CLASS}`, this._onDayKeyUp.bind(this));
            swipe(
                this.$body.eq(0),
                'h',
                (e, offset) => {
                    this._onDateChange(offset < 0 ? 'right' : 'left');
                },
                false
            );
        },
        _setOption: function (key, value) {
            const oldValue = this.options[key];
            if (value === oldValue) return false;
            this.options[key] = value;
            if (this.lockView.includes(_view.month) && ['enableDates', 'selectedDate'].includes(key)) {
                this.$month.basecalendar('option', key, value);
            }
            switch (key) {
                case 'enableDates':
                    this._syncCacheEnableDates();
                    this._updateDisplayMode(this._displayMode, key, false);
                    break;
                case 'selectedDate':
                    if (this.options.type === 'single') {
                        if (isDate(value)) {
                            this._updateDisplayDate(clearTime(value));
                        }
                        this.cache.selectedDate = isDate(value) ? clearTime(value) : null;
                    } else {
                        this.cache.selectedDate = value;
                    }
                    this._updateDisplayMode(this._displayMode, key, false);
                    break;
                case 'items':
                    this.itemSource(value);
                    break;
                case 'displayMode':
                    this._getDisplayModeByLockView();
                    this._updateDisplayMode(this._displayMode, key, false);
                    break;
                case 'displayDate': {
                    const d = calendarUtil.displayDate(this.options.type, this.options.selectedDate, value);
                    this._updateDisplayDate(d);
                    this.$month?.basecalendar('option', 'displayDate', this._displayDate.date());
                    this._setTitleContent();
                    break;
                }
            }
        },
        _setTitleContent: function () {
            let content = '';
            const button = (view, content) => `<button type="button" value="${_view[view]}" aria-label="${I18N.views[view]}">${content}</button>`;
            switch (this.view) {
                case _view.month: {
                    const date = this._displayDate.date(),
                        format = I18N.titleFormat,
                        yearF = format.match(/y{2,4}/)?.[0],
                        monthF = format.match(/M{1,4}/)?.[0];
                    content = format;
                    if (yearF) {
                        content = content.replace(yearF, button('year', dateFormat(date, yearF)));
                    }
                    if (monthF) {
                        content = content.replace(monthF, button('month', dateFormat(date, monthF)));
                    }
                    break;
                }
                case _view.year:
                    content = button('year', this._displayDate.year);
                    break;
                case _view.decade: {
                    const from = this._decadeStart + 1,
                        to = from + 10 - 1;
                    content = button('decade', `${from} - ${to}`);
                    break;
                }
                case _view.century: {
                    const from = this._centuryStart + 10,
                        to = from + 100 - 1;
                    content = button('century', `${from} - ${to}`);
                    break;
                }
            }
            this.$title.html(content);
            if (this.options.limitViewCrossEdge) this._updatePageBtnState();
        },
        _render: function () {
            const header = (
                <div className={_constant.HEADER_CLASS}>
                    <div className={_constant.Button_Group_Class}>
                        <aui-button
                            className={[_constant.ARROW_CLASS, _constant.Cross_Swipe_Class]}
                            type="bald"
                            value="left"
                            icon={_constant.LEFT_DOUBLE_ICON_CLASS}
                            tooltip={I18N.prevYear}
                        />
                        <aui-button className={_constant.ARROW_CLASS} type="bald" value="left" icon={_constant.LEFT_ICON_CLASS} id={this.leftArrowId} tooltip={I18N.prev} />
                    </div>
                    <div className={_constant.TITLE_CLASS} />
                    <div className={_constant.Button_Group_Class}>
                        <aui-button className={_constant.ARROW_CLASS} type="bald" value="right" icon={_constant.RIGHT_ICON_CLASS} id={this.rightArrowId} tooltip={I18N.next} />
                        <aui-button
                            className={[_constant.ARROW_CLASS, _constant.Cross_Swipe_Class]}
                            type="bald"
                            value="right"
                            icon={_constant.RIGHT_DOUBLE_ICON_CLASS}
                            tooltip={I18N.nextYear}
                        />
                    </div>
                </div>
            );
            const body = <div className={_constant.BODY_CLASS} />;
            this.$element.attr({ role: 'group', 'data-type': this.options.type }).append(header).append(body).addClass(_constant.CALENDAR_CLASS);
            if (this.options.width) this.$element.width(this.options.width);
            if (this.options.height) this.$element.height(this.options.height);
            if (this.options.withEvent) this.$element.addClass(_constant.withEvent);
            this.$title = this.$element.find(`.${_constant.TITLE_CLASS}`);
            this.$left = this.$element.find(`#${this.leftArrowId}`);
            this.$right = this.$element.find(`#${this.rightArrowId}`);
            this.$cross = this.$element.find(`.${_constant.Cross_Swipe_Class}`);
            this.$body = this.$element.find(`.${_constant.BODY_CLASS}`);
            this.$body.append(<div className={[_constant.MONTHVIEW_CLASS, 'view']} />);
            if (this.lockView.includes(_view.month)) {
                this._renderMonthView();
                this.$month.addClass('aui-calendar-hide');
            }
            if (this.lockView.includes(_view.year)) {
                this._renderView(_view.year, 'create');
            }
            if (this.lockView.includes(_view.decade)) {
                this._renderView(_view.decade, 'create');
            }
            if (this.lockView.includes(_view.century)) {
                this._renderCenturyView('create');
            }
            return this;
        },
        _renderView: function (view, operation) {
            this._decadeStart = this._getDecadeStart(this._displayDate.year);

            const trs = [],
                clazz = view === _view.year ? _constant.YEARVIEW_CLASS : _constant.DECADEVIEW_CLASS,
                cellData = view === _view.year ? I18N.shortMonths : this._decadeStart,
                element = view === _view.year ? this.$year : this.$decade;
            let args = {},
                index = -1;

            for (let row = 0; row < 3; row++) {
                const tds = [];
                for (let col = 0; col < 4; col++) {
                    index = row * 4 + col;
                    if (view === _view.year) {
                        args = { data: index, txt: cellData[index], label: I18N.months[index] };
                    } else {
                        args = { data: cellData + index, txt: cellData + index, index: index, label: cellData + index };
                    }

                    if (operation === 'create') {
                        const attrs = { role: 'gridcell', 'data-cell': `${row + 1},${col + 1}` };
                        Object.assign(attrs, this._setCellAttrs(view, args));
                        tds.push(
                            <td role="none">
                                <div {...attrs}>{args.txt}</div>
                            </td>
                        );
                    } else {
                        jQuery(`div[data-cell='${row + 1},${col + 1}']`, element)
                            .attr(this._setCellAttrs(view, args))
                            .text(args.txt);
                    }
                }
                if (operation === 'create') trs.push(<tr role="row">{tds}</tr>);
            }
            if (operation === 'create') {
                this.$body.append(
                    <div className={[clazz, 'view']}>
                        <table role="grid" cellSpacing={0} cellPadding={0}>
                            <tbody>{trs}</tbody>
                        </table>
                    </div>
                );
            }
            this._setSelectedCell()._setTabble(operation);

            return this;
        },
        _renderMonthView: function () {
            this.$month = this.$element.find('.' + _constant.MONTHVIEW_CLASS).basecalendar({
                enableDates: this.options.enableDates,
                selectedDate: this.options.selectedDate,
                displayDate: this.options.displayDate,
                firstDayOfWeek: this.options.firstDayOfWeek,
                type: this.options.type,
                callbackBySource: true,
                swipe: this.options.swipe,
                doRangeChange: (args) => {
                    const d = new Date(args.start);
                    this._updateDisplayDate(d);
                    this._setTitleContent();
                    return this._callback('doRangeChange', args);
                },
                onChange: (args) => {
                    if (this.options.selectedDate === null) {
                        this.options.selectedDate = args.newValue;
                    }
                    this.cache.selectedDate = args.newValue;
                    this.$element.attr('data-dirty', true);
                    this._handler('onChange', args);
                },
                onTodayStateChange: (args) => {
                    this.$today?.attr('disabled', args);
                    this._callback('onTodayStateChange', args);
                },
                onKeyUp: this.options.onKeyUp,
                onMouseChange: this.options.onMouseChange,
            });
            if (this.options.hasToday && this.options.type !== 'range') {
                this.$month.append(<aui-button className={_constant.TODAY_CLASS} type="link" text={I18N.today} onClick={this.gotoToday.bind(this, true)} />);
            }
        },
        _renderCenturyView: function (operation) {
            this._centuryStart = this._getCenturyStart(this._displayDate.year);

            const trs = [],
                clazz = _constant.CENTURY_VIEW_CLASS,
                cellData = this._centuryStart,
                element = this.$century;
            let args = {},
                index = -1;

            for (let row = 0; row < 4; row++) {
                const tds = [];
                for (let col = 0; col < 3; col++) {
                    index = row * 3 + col;

                    const start = cellData + index * 10;

                    args = { data: start, txt: `${start}-${start + 9}`, index: index, label: `${start}-${start + 9}` };

                    if (operation === 'create') {
                        const attrs = { role: 'gridcell', 'data-cell': `${row + 1},${col + 1}` };
                        Object.assign(attrs, this._setCellAttrs(_view.century, args));
                        tds.push(
                            <td role="none">
                                <div {...attrs}>{args.txt}</div>
                            </td>
                        );
                    } else {
                        jQuery(`div[data-cell='${row + 1},${col + 1}']`, element)
                            .attr(this._setCellAttrs(_view.century, args))
                            .text(args.txt);
                    }
                }
                if (operation === 'create') trs.push(<tr role="row">{tds}</tr>);
            }
            if (operation === 'create') {
                this.$body.append(
                    <div className={[clazz, 'view']}>
                        <table role="grid" cellSpacing={0} cellPadding={0}>
                            <tbody>{trs}</tbody>
                        </table>
                    </div>
                );
            }
            this._setSelectedCell()._setTabble(operation);

            return this;
        },
        _setCellAttrs: function (view, args) {
            let disabled = false,
                param = {},
                clazz = _constant.CELL_CLASS;
            if (view === _view.year) {
                param.year = this._displayDate.year;
                param.month = args.data;
                clazz += ' inview';
            } else if (view === _view.decade || view === _view.century) {
                param.year = args.data;
                if (args.index === 0) {
                    clazz += ' prev';
                } else if (args.index === 11) {
                    clazz += ' next';
                } else {
                    clazz += ' inview';
                }
            } else {
                param = null;
            }
            disabled = param && this._checkDisabled(param);
            if (disabled) clazz += ` ${_constant.DISABLED_CLASS}`;
            return {
                'data-start': args.data,
                'aria-disabled': disabled,
                'aria-label': args.label,
                'aria-selected': false,
                class: clazz,
                tabindex: disabled ? null : '-1',
                disabled: disabled,
            };
        },
        itemSource: function (items) {
            if (this.$month) {
                jQuery(`.${_constant.CONTENT_CLASS}`, this.$month).empty();
                jQuery(`.${_constant.BASE_CELL_CLASS}`, this.$month).removeClass('highlight').css('--highlight', '').attr('data-status', null);
            }
            if (!items?.length || this.view !== _view.month) return;

            items.forEach((item) => {
                const date = new Date(item.date),
                    timestamp = new Date(date.getFullYear(), date.getMonth(), date.getDate()).getTime(),
                    $cell = jQuery(`div[data-start=${timestamp}]`, this.$month);
                if (Array.isArray(item.color)) {
                    const events = item.color.map((item, index) => {
                        if (index < 3) {
                            const event = document.createElement('span');
                            event.dataset.index = index;
                            event.style.backgroundColor = item;
                            return event;
                        }
                        return '';
                    });
                    jQuery(`div[data-start=${timestamp}] .${_constant.CONTENT_CLASS}`, this.$month).append(events).show();
                }
                if (item.highlight) $cell.addClass('highlight').css('--highlight', item.highlight);
                if (item.status) $cell.attr('data-status', item.status);
            });
        },
        _clearSelectedCell: function () {
            jQuery(`.${_constant.CELL_CLASS}`, this.$element).removeClass(_constant.ACTIVE_CLASS).attr('aria-selected', false);
            jQuery(`.${_constant.CELL_CLASS}:not(.${_constant.DISABLED_CLASS})`, this.$element).attr('tabindex', -1);
        },
        _setSelectedCell: function () {
            this._clearSelectedCell();
            this._addSelectedCell(this._getSelectedCell());
            return this;
        },
        _addSelectedCell: function ($item) {
            if ($item) {
                $item.addClass(_constant.ACTIVE_CLASS).attr({
                    'aria-selected': true,
                    'aria-current': 'date',
                });
                // this.$body.attr({
                //     'aria-activedescendant': $item.attr('id')
                // });
            }
        },
        _dateForObject: function (date) {
            return isDate(date) ? { year: date.getFullYear(), month: date.getMonth() } : {};
        },
        _checkDisabled: function (args, edge) {
            if (args == null || isEmpty(this.options.enableDates)) {
                return false;
            }
            const { minDate, maxDate, enableDatesObj: enableObj } = this.cache;
            let disabled = false;
            if (minDate && maxDate) {
                if (args.year && args.month != null) {
                    const date = new Date(args.year, args.month, 1);
                    const min = minDate.year ? new Date(minDate.year, minDate.month, 1) - 0 : Number.MIN_VALUE,
                        max = maxDate.year ? new Date(maxDate.year, maxDate.month + 1, 1) - 1 : Number.MAX_VALUE;
                    // eslint-disable-next-line unicorn/prefer-number-properties
                    disabled = !isNaN(min) && !isNaN(max) && (min > date || date > max);
                } else if (args.year) {
                    disabled = minDate.year > args.year || args.year > maxDate.year;
                } else {
                    disabled = minDate.year > args + 11 || maxDate.year < args;
                }
            } else if (enableObj) {
                const checkDecadeEnable = () => Object.keys(enableObj).some((d) => Number(d) > args && Number(d) < args + 9);
                if (edge) {
                    const fn = Math[edge],
                        compare = (a, b) => fn(a, b) === a;
                    const getEdgeValue = (obj) => fn(...Object.keys(obj).map(Number));
                    const year = getEdgeValue(enableObj),
                        month = getEdgeValue(enableObj[year] || {});
                    if (!year || year < 0) {
                        disabled = true;
                    } else if (args.year && args.month != null) {
                        disabled = !compare(year, args.year) || (args.year === year && !compare(month, args.month));
                    } else if (args.year) {
                        disabled = !compare(year, args.year);
                    } else {
                        disabled = !checkDecadeEnable();
                    }
                } else {
                    const year = enableObj[args.year];
                    if (args.year && args.month != null) {
                        disabled = !year || !year[args.month];
                    } else if (args.year) {
                        disabled = year === undefined;
                    } else {
                        disabled = !checkDecadeEnable();
                    }
                }
            }
            return disabled;
        },
        _setTabble: function (operation) {
            const $body = this.view === _view.year ? this.$year : this.$decade;
            let $active = jQuery(`.${_constant.ACTIVE_CLASS}`, $body);
            if ($active.length === 0) {
                $active = jQuery(`.${_constant.CELL_CLASS}:not(.next,.prev,.${_constant.DISABLED_CLASS})`, $body);
            }
            if ($active.length > 0) {
                $active.first().attr('tabindex', 0);
                if (['cellclick', 'cellkeyup'].includes(operation)) $active.get(0).focus();
            }
            return this;
        },
    });
    Object.assign(jQuery.aui5.calendar.prototype, {
        _updateDisplayDate: function (date) {
            date = new Date(date);
            const y = date.getFullYear(),
                m = date.getMonth();
            this._displayDate = {
                year: y,
                month: m,
                date: () => {
                    return new Date(this._displayDate.year, this._displayDate.month, 1);
                },
            };
            return this;
        },
        _getDecadeStart: function (year) {
            return Math.floor(year / 10) * 10 - 1;
        },
        _getCenturyStart: function (year) {
            return Math.floor(year / 100) * 100 - 10;
        },
        _onDateChange: function (operation, e) {
            let year = this._displayDate.year;

            if (this.view === _view.month) {
                let d;
                if (operation === 'cross') {
                    const { value } = e.target.closest('button');
                    d = this.$month.basecalendar('gotoNearYear', value === 'left');
                } else {
                    d = this.$month.basecalendar('gotoNearMonth', operation === 'left');
                }
                this._updateDisplayDate(d);
            } else {
                if (this.view === _view.year) {
                    year = operation === 'left' ? year - 1 : year + 1;
                } else if (this.view === _view.decade) {
                    year = operation === 'left' ? this._decadeStart : this._decadeStart + 11;
                } else if (this.view === _view.century) {
                    year = operation === 'left' ? this._centuryStart : this._centuryStart + 110;
                }
                this._displayDate.year = year;
                if (this.view === _view.century) {
                    this._renderCenturyView(operation);
                } else {
                    this._renderView(this.view, operation);
                }
            }
            this._setTitleContent();
        },
        _updatePageBtnState: function () {
            const y = this._displayDate.year,
                m = this._displayDate.month;
            let prevData = null,
                nextData = null;
            switch (this.view) {
                case _view.month:
                    prevData = [m > 0 ? { year: y, month: m - 1 } : { year: y - 1, month: 11 }, { year: y - 1, month: m }];
                    nextData = [m < 11 ? { year: y, month: m + 1 } : { year: y + 1, month: 0 }, { year: y + 1, month: m }];
                    break;
                case _view.year:
                    prevData = [{ year: y - 1 }];
                    nextData = [{ year: y + 1 }];
                    break;
                case _view.decade: {
                    const data = this._decadeStart;
                    prevData = [this._getDecadeStart(data)];
                    nextData = [this._getDecadeStart(data + 11)];
                    break;
                }
                case _view.century: {
                    const data = this._centuryStart;
                    prevData = this._getCenturyStart(data);
                    nextData = this._getCenturyStart(data + 101);
                    break;
                }
            }
            this.$left.attr({ disabled: this._checkDisabled(prevData[0], 'min') });
            this.$left.siblings().attr({ disabled: this._checkDisabled(prevData[1], 'min') });
            this.$right.attr({ disabled: this._checkDisabled(nextData[0], 'max') });
            this.$right.siblings().attr({ disabled: this._checkDisabled(nextData[1], 'max') });
        },
        _onViewChange: function (operation, e) {
            e.stopPropagation();
            const button = e.currentTarget,
                { value } = button,
                target = Number(value) + 1;
            if (this.lockView.includes(target)) {
                this._updateDisplayMode(target, operation, true);
            } else {
                e.preventDefault();
            }
        },
        _updateDisplayMode: function (view, operation, focused) {
            let { prev, next } = I18N;
            this.$view.hide();
            this.$month?.show().addClass('aui-calendar-hide');
            this.view = view;
            switch (view) {
                case _view.month:
                    this.$element.attr('data-view', 'month');
                    this.$month?.removeClass('aui-calendar-hide');
                    this.$month?.basecalendar('setDisplayDate', this._displayDate.date());
                    focused && this.$month.basecalendar('setFocus');
                    prev = I18N.prevMonth;
                    next = I18N.nextMonth;
                    break;
                case _view.year:
                    this.$element.attr('data-view', 'year');
                    this.$year.show();
                    this._renderView(_view.year, operation);
                    break;
                case _view.decade:
                    this.$element.attr('data-view', 'decade');
                    this.$decade.show();
                    this._renderView(_view.decade, operation);
                    break;
                case _view.century:
                    this.$element.attr('data-view', 'century');
                    this.$century.show();
                    this._renderCenturyView(operation);
                    break;
            }
            this.$left.attr('tooltip', prev);
            this.$right.attr('tooltip', next);
            this._setTitleContent();
            if (['title', 'displayMode', 'cellclick', 'cellkeyup'].includes(operation)) {
                this.$element.triggerHandler('ViewChange', this.view);
            }
        },
        resetView: function (view) {
            this._updateDisplayMode(view || this._displayMode, null, true);
        },
        _cellClick: function (operation, e) {
            const $target = jQuery(e.target),
                data = $target.attr('data-start') - 0;
            let nextView;
            if ($target.hasClass(_constant.DISABLED_CLASS)) return;
            switch (this.view) {
                case _view.year:
                    nextView = _view.month;
                    this._displayDate.month = data;
                    break;
                case _view.decade:
                    nextView = _view.year;
                    this._displayDate.year = data;
                    break;
                case _view.century:
                    nextView = _view.decade;
                    this._displayDate.year = data;
                    break;
            }
            if (this.lockView.includes(nextView)) {
                this._updateDisplayMode(nextView, operation, true);
            } else {
                const oldValue = clearTime(this.cache.selectedDate);
                let date = this._displayDate.date();
                this._clearSelectedCell();
                this._addSelectedCell($target);
                this._callback('onDayClick');
                if (this.view === _view.year || this.view === _view.decade) {
                    if (this.options.enableDates) {
                        date = new Date(Math.max(date, this._min) || Math.min(date, this._max));
                    }
                }
                if (date.getTime() !== oldValue.getTime()) {
                    this.cache.selectedDate = date;
                    this._callback('onChange', {
                        oldValue: oldValue,
                        newValue: date,
                    });
                }
            }
        },
        _onDayClick: function (e) {
            if (jQuery(e.currentTarget).attr('disabled')) return;
            this._callback('onDayClick');
        },
        _onDayKeyUp: function (e) {
            if (jQuery(e.currentTarget).attr('disabled') || keyName(e) !== 'Space') return;
            this._callback('onDayClick');
        },
        _getSelectedCell: function () {
            if (!isDate(this.cache.selectedDate)) return;
            const selectedYear = this.cache.selectedDate.getFullYear(),
                displayYear = this._displayDate.year,
                selectedMonth = this.cache.selectedDate.getMonth();
            let $item = null;
            if (this.view === _view.year && displayYear === selectedYear) {
                $item = jQuery(`div.${_constant.CELL_CLASS}[data-start=${selectedMonth}]:not(.${_constant.DISABLED_CLASS})`, this.$year);
            }
            if (this.view === _view.decade) {
                $item = jQuery(`div.${_constant.CELL_CLASS}[data-start=${selectedYear}]:not(.${_constant.DISABLED_CLASS})`, this.$decade);
            }
            if (this.view === _view.century) {
                $item = jQuery(`div.${_constant.CELL_CLASS}[data-start=${Math.floor(selectedYear / 10) * 10}]:not(.${_constant.DISABLED_CLASS})`, this.$century);
            }
            return $item;
        },
        _cellKeydown: function (e) {
            const key = keyName(e),
                offset = calendarUtil.arrowOffset[key];
            if (offset || ['Space', 'Home', 'End', 'PageUp', 'PageDown'].includes(key)) {
                e.preventDefault();
            }
        },
        _cellKeyup: function (e) {
            const key = keyName(e),
                offset = calendarUtil.arrowOffset[key],
                target = e.currentTarget,
                active = document.activeElement,
                $body = this.view === _view.year ? this.$year : this.$decade;
            if (offset) {
                navigation2D(e, 'data-cell', $body.get(0));
            }
            if (active === target && key === 'Space') {
                this._cellClick('cellkeyup', e);
            } else if (key === 'Home' || key === 'End') {
                jQuery(`.${_constant.CELL_CLASS}.inview:${key === 'Home' ? 'first' : 'last'}`, $body)
                    .get(0)
                    ?.focus();
            } else if (key === 'PageUp' || key === 'PageDown') {
                this._onDateChange(key === 'PageUp' ? 'left' : 'right');
            }
        },
        gotoToday: function () {
            this.resetView();
            const date = clearTime(new Date());
            this._updateDisplayDate(date);
            this.$month.basecalendar('gotoToday');
            this._callback('todayClick', {
                newValue: this.cache.selectedDate,
            });
        },
        setFocus: function () {
            let _cls = _constant.MONTHVIEW_CLASS;
            switch (this.options.displayMode) {
                case 1:
                    _cls = _constant.YEARVIEW_CLASS;
                    break;
                case 2:
                    _cls = _constant.DECADEVIEW_CLASS;
                    break;
            }
            const item = this.$element.find(`.${_cls} [tabindex=0]`);
            if (item.length > 0) {
                item.get(0).focus();
            }
        },
        selectedDate: function (value) {
            if (value === undefined) {
                return this.cache.selectedDate || null;
            } else {
                this._setOption('selectedDate', value);
            }
        },
        setDisplayDate: function (date) {
            let d = null;
            if (isDate(date)) {
                d = date;
            } else {
                d = calendarUtil.displayDate(this.options.type, this.options.selectedDate, date);
            }
            this._updateDisplayDate(d);
            this.$month?.basecalendar('setDisplayDate', this._displayDate.date());
            this._setTitleContent();
            this.setFocus();
        },
        getDisplayDate: function () {
            return this.$month?.basecalendar('getDisplayDate') || this._displayDate;
        },
        allMonthDisabled: function (date) {
            const year = date.getFullYear(),
                month = date.getMonth(),
                length = clearTime(new Date(year, month + 1, 1).setDate(0)).getDate();
            let disabled = true;
            const cache = calendarUtil.calcEnableDate(this.options.enableDates);

            for (let i = 0; i < length; i++) {
                const d = new Date(year, month, i + 1).getTime();

                if (!calendarUtil.checkDateDisabled(d, null, cache)) {
                    disabled = false;
                    break;
                }
            }
            return disabled;
        },
        displayView: function () {
            return this.view;
        },
    });
})();
