import { RegUploadPlugin } from '../module/upload.plugin.js';

RegUploadPlugin('Image', (UploadButton, I18N) => {
    return class ImageSplitButton extends UploadButton {
        icon = true;
        internal = true;
        type = 'Image';
        name = I18N.pictureTag;
        tooltip = [I18N.pictureTag];

        menuMapping = (item) => {
            return { ...item, icon: this.icon };
        };
    };
});
