/** @jsxImportSource @gui/aui-devops */
import { define, Widget, Types } from '../widget.js';

import stringFormat from '../../util/string/format.js';

import style from './select.less';

/** @extends {Widget<typeof Select.options>} */
@define('select-lite')
export class Select extends Widget {
    static options = {
        items: '',
        splitter: '/',
        name: Types.string,
        disabled: false,
        readonly: false,
        required: false,
        value: Types.string,
        format: Types.Union([Types.string, Types.function]),
        onChange: Types.function,
    };
    static shadow = { delegatesFocus: true, referenceTarget: 'select' };
    static observers = ['items', 'name', 'value', 'disabled', 'readonly'];
    static formAssociated = true;
    static ariaTarget = '#select';
    static styles = style;

    create() {
        this.hostProto = { getValue: this.getValue, setValue: this.setValue };
    }
    didMount() {
        const action = this.element.querySelector('select');
        action.dispatchEvent(new InputEvent('input', { bubbles: true, composed: true }));
    }
    getValue = () => {
        const target = this.element.querySelector('select');
        return target.value;
    };
    setValue = (v) => {
        const target = this.element.querySelector('select');
        target.value = v;
    };
    onChange = (e) => {
        const { value } = e.target,
            { onChange } = this.options;
        if (onChange) {
            onChange(value, e);
        } else {
            this._setOption('value', value);
        }
    };
    item = (val) => {
        const { value, splitter, format } = this.options;
        let [v, content] = val.split(splitter);
        if (!content) content = format ? stringFormat(format, v) : v;
        return (
            <option value={v} selected={value != null && v === value}>
                {content}
            </option>
        );
    };
    render() {
        const { items, name, disabled, readonly, required } = this.options,
            args = { name, disabled: disabled || readonly, required, ...this.arias({ disabled, readonly: readonly && !disabled }) },
            list = items.split(';').filter((x, i) => !i || x);
        return (
            <label>
                <slot className="block start" name="block-start" />
                <slot className="inline start" name="inline-start" />
                <div className="select">
                    <select id="select" className="action" {...args} autoComplete="off" onChange={this.onChange}>
                        {list.map(this.item)}
                    </select>
                </div>
                <slot className="inline end" name="inline-end" />
                <slot className="block end" name="block-end" />
            </label>
        );
    }
}
