/** @jsxImportSource @gui/aui-devops */
import { callbackResult } from '../../core/base/internal.js';
import { omit, error } from '../../core/base/log.js';
import $ from '../../core/element/index.js';
import { widget } from '../../core/extend/widget.js';

import cssZindex from '../../util/css/zindex.js';
import objectForEach from '../../util/object/for-each.js';
import kebabCase from '../../util/string/kebab-case.js';
import { isDeferred, isElement, isEmpty, isEvent } from '../../util/type/types.js';
import { getValue } from '../../util/value-path.js';

const _constant = {
    CLASSNAME: 'aui-validation',
    FAKER_CLASS: 'aui-validation-faker',
    MESSAGE_CLASS: 'aui-validation-message',
    MESSAGE_ID_PREFIX: 'aui-validation-message-',
    POPUP_CLASS: 'aui-validation-message-popup',
    POPUP_CLASSIFY_CLASS: 'aui-classify-error',
    POPUP_CONTENT_CLASS: 'aui-validation-message-popup-content',
};

(function () {
    Object.assign($$, {
        // verify main function.
        verify: function (target, cb, pending) {
            let $target;
            if (typeof target === 'string') {
                // default set as id selector.
                target = $$.getUniqueElement(target);
                $target = jQuery(target);
            } else {
                if (isElement(target)) {
                    $target = jQuery(target);
                } else if (isEvent(target)) {
                    $target = jQuery(target.target);
                }
                if ($target?.length) {
                    let _target = $target.closest('.' + _constant.CLASSNAME);
                    // get "dialog" element, e.g. Dialog, Panel etc.
                    if (!_target.length)
                        _target = $($target)
                            .closest('dialog,[role="dialog"]')
                            .find('.' + _constant.CLASSNAME, { crossShadow: true, crossSlot: true });
                    $target = jQuery(_target);
                }
            }
            if (!$target?.length) return error('[validation]', 'The verify target invalid!');
            $target = $target.eq(0);
            $target.validation();
            // clear verify
            if (cb === false) {
                const force = pending;
                return $target.validation('verify', true, force);
            }
            const result = $target.validation('verify');
            if (typeof cb === 'function') {
                if (isDeferred(result)) {
                    $$.fn(pending)(true);
                    return callbackResult(result, (data) => cb(data.every((v) => v === true))).finally(() => $$.fn(pending)(false));
                } else {
                    cb(result);
                }
            }
            return result;
        },
    });
})();

function getMessage(value, initial, element) {
    const I18N = $$.I18N.validation;
    if (element && I18N[initial + '_' + element]) {
        initial = I18N[initial + '_' + element];
    } else if (I18N[initial]) {
        initial = I18N[initial];
    } else if (I18N.rules[initial]) {
        initial = I18N.rules[initial];
    }
    if (typeof value === 'string' && value.length > 0) {
        if (value === 'false') {
            // bad usage, disable the verify.
            return true;
        } else if (value !== 'true') {
            return value;
        }
    }
    return initial;
}

// init validation when focused;
$.$body.on('focusin', '.' + _constant.CLASSNAME, { capture: true }, function (e) {
    const element = e.currentTarget;
    queueMicrotask(() => jQuery(element).validation());
});

// update: The real-time update event name.
// recheck: The event name to recheck after checked invalid.
// valuePath: The valuePath or function-called-string for get value of it.
const dictionary = {
    input: { recheck: 'blur', valuePath: 'val()' },
    'input:number': { recheck: 'blur', valuePath: 'val()' },
    'input:email': { recheck: 'blur', valuePath: 'val()' },
    'input:checkbox': { recheck: 'change', valuePath: 'prop("checked")', type: 'Boolean' },
    'input:radio': { recheck: 'change', valuePath: 'prop("checked")', type: 'Boolean' },
    textarea: { recheck: 'blur', valuePath: 'val()' },
    Input: { recheck: 'change', valuePath: 'method("checkValidation")' },
    Checkbox: { recheck: 'change', valuePath: 'method("getValue")', type: 'Boolean' },
    'Radio.Group': { recheck: 'change', valuePath: 'method("getValue")' },
    'Checkbox.Group': { recheck: 'change', valuePath: 'method("getValue")' },
    Combobox: { recheck: 'onChange', valuePath: 'combobox("getValue")', shell: 'jQuery' },
    Datepicker: { recheck: 'onChange', valuePath: 'datepicker("getValue")', shell: 'jQuery' },
    Rangepicker: { recheck: 'onChange onBlur', valuePath: 'rangepicker("checkValidation")', shell: 'jQuery' },
    Multicombobox: { recheck: 'onChange', valuePath: 'multicombobox("getValue")', shell: 'jQuery' },
    RichCombobox: { recheck: 'onChange', valuePath: 'richcombobox("checkValidation")', shell: 'jQuery' },
    Timepicker: { recheck: 'onChange', valuePath: 'method("getValue")' },
    Editor: { recheck: 'onChange', valuePath: 'method("getValue")' },
    Uploader: { recheck: 'onChange', valuePath: 'method("checkValidation")' },
    ImgUploader: { alias: 'Uploader', errorby: ':scope #validation-message' },
};

widget('aui5.validation', {
    valid: true,
    ruleDataPrefix: 'rule_',
    supportInputTypes: ['text', 'number', 'password', 'checkbox', 'radio', 'email', 'file', 'search', 'tel'],
    _popup: false,
    _widget: null,
    $target: null,
    $message: null,
    isFaker: false,
    multiple: false, // for multi checkbox/radio.
    loaded: false,
    rules: {},
    options: {
        rules: {},
        errorby: '',
        invalidby: '',
        related: '',
    },
    _create: function () {
        this.I18N = $$.I18N.validation;
        if (this._createBase()) {
            this._initRules();
            this._initMember();
            this._initEvent();
        }
        this.loaded = true;
    },
    _init: function () {},
    _createBase: function () {
        const supportInputTypes = this.supportInputTypes,
            data = this.$element.data();
        let $target,
            target = data.element || '',
            widget = dictionary[target.split(':', 1)[0]];
        if (widget?.alias) {
            target = widget.alias;
            widget = { ...widget, ...dictionary[target] };
        }
        const first = target[0],
            errorby = data.errorby || widget?.errorby || '',
            invalidby = data.invalidby || '';
        if (errorby) this.options.errorby = errorby;
        if (invalidby) this.options.invalidby = invalidby;
        this.options.related = data.related || '';
        this.$element.attr('data-uuid', this.uuid);
        if (!target) {
            // only validation container
            this.verifyElement = function () {
                return true;
            };
            return;
        }
        if (/[a-z]/.test(first)) {
            if (target.startsWith('input:')) {
                const type = target.replace('input:', '');
                $target = this.$element.find(`input[type=${type}]`).filter(() => supportInputTypes.includes(type));
                if ($target.length === 0) {
                    $target = null;
                    error('[validation]', 'The input type is not support!');
                } else {
                    if (dictionary['input:' + type]) {
                        widget = dictionary['input:' + type];
                    }
                    if (type === 'checkbox' && $target.parent().hasClass(_constant.FAKER_CLASS)) this.isFaker = true;
                    if ($target.length > 1 && !this.isFaker && (type === 'radio' || type === 'checkbox')) {
                        this.multiple = true;
                        this.element.dataset.multiple = true;
                    }
                }
            } else {
                $target = this.$element.find(target);
            }
        } else if (/[A-Z]/.test(first)) {
            const query = (tag) => this.$element.find(tag).get(0) || this.$element.find('.' + tag).get(0);
            $target = jQuery(query('aui' + kebabCase(target, true)) || query('aui-' + target.toLowerCase()));
            if (!widget) widget = this._ShellBridge(this.$element, 'getDictionary')[target];
        }
        if (!$target?.length) return error('[validation]', `The validation target invalid by: "${target}"!`);
        if (!this.multiple) $target = $target.eq(0);
        this.$target = $target;
        this.$actionElement = $target;
        if (this.isFaker) {
            const of = this.$actionElement.data('of');
            this.$actionElement = this._actionElement(
                this.$element
                    .parent()
                    .closest('.' + _constant.CLASSNAME)
                    .find(of)
            );
        }
        this.$actionElement = this._actionElement(this.$actionElement);
        if (data.require) this._setAria({ 'aria-required': true });
        this._widget = widget;
        return this._widget;
    },
    _findElement: function (query) {
        if (!query) return null;
        if (typeof query !== 'string') return query;
        if (query === 'self') return this.element;
        if (!query.startsWith(':scope')) return $(query).get();
        query = query.replace(':scope', '').trim();
        return $(this.element).find(query, { crossShadow: true, crossSlot: true }).get();
    },
    _actionElement: function ($el, findTabbable) {
        if ($el === 'self') return $(this.$element);
        const findArgs = { crossShadow: true, crossSlot: true };
        $el = $($el);
        if ($el.get(0)?.shadowRoot) {
            $el = $($el.get(0).shadowRoot);
        }

        const active = $el.is(':focusable');
        if (!active) $el = $($el).find(':focusable', findArgs);
        if (findTabbable) {
            const search = active ? 'find' : 'filter';
            let $tabbable = $($el)[search](':tabbable', findArgs);
            if ($tabbable.length) {
                const tabbable = $tabbable.get(0);
                if (tabbable.localName !== 'iframe') return $tabbable;
                try {
                    const { documentElement } = tabbable.contentDocument;
                    $tabbable = $(documentElement)[search](':tabbable');
                    if ($tabbable.length) return $tabbable;
                } catch (e) {
                    return null;
                }
            }
        }
        return this.multiple ? $el : $el.eq(0);
    },
    _setAria: function (val) {
        let $action = $(this.$actionElement);
        const $target = $(this.$target),
            crossRoot = this.isFaker || ($action.length && $action.origin('getRootNode')() !== $target.origin('getRootNode')()),
            wrapper = (crossRoot ? $action.closest(':widget', this.element) : $target).get(0);
        if (typeof wrapper?.method === 'function') {
            wrapper.method('setAria', val);
        } else {
            if (!$action.is(':tabbable') && !$action.is('[tabindex]')) $action = $action.find(':tabbable', { crossSlot: true }).add($action).eq(0);
            $action.attrs(val);
        }
    },
    _initRules: function () {
        const { ...rules } = this.options.rules,
            dataPrefix = this.ruleDataPrefix,
            data = this.$element.data();
        Object.keys(data).forEach(function (name) {
            if (name.indexOf(dataPrefix) === 0) {
                rules[name.slice(dataPrefix.length)] = data[name];
            }
        });
        this.rules = rules;
    },
    _initMember: function () {
        const { element } = this;
        let $message = jQuery(this._findElement(this.options.errorby));
        if ($message.length) {
            $message.addClass(_constant.MESSAGE_CLASS);
        } else {
            $message = this.$element.find('.' + _constant.MESSAGE_CLASS).filter(function () {
                return jQuery(this).closest('.' + _constant.CLASSNAME)[0] === element;
            });
        }
        if (element.dataset.popup === 'true') {
            // popup message
            // init popup
            this._popup = true;
            const $popup = jQuery(
                <div className={[_constant.POPUP_CLASS, _constant.POPUP_CLASSIFY_CLASS]}>
                    <div className={_constant.POPUP_CONTENT_CLASS} />
                </div>
            );
            this.$element.append($popup);
            $popup.popup({
                arrow: true,
                focusable: false,
                classify: 'error',
                zIndex: cssZindex('popover'),
            });
            this.$message = $popup.find('.' + _constant.POPUP_CONTENT_CLASS);
        } else {
            if ($message.length === 0) {
                $message = jQuery('<div/>').addClass(_constant.MESSAGE_CLASS);
                this.$element.append($message);
            }
            this.$message = $message.eq(0);
        }
        if (!this.$message.attr('id')) this.$message.attr('id', _constant.MESSAGE_ID_PREFIX + this.uuid);
    },
    _initEvent: function () {
        const { recheck, shell } = this._widget;
        if (recheck) {
            const onReCheck = (e) => {
                const _target = e.currentTarget;
                setTimeout(() => {
                    const { element } = this,
                        $related = jQuery(this.options.related).not(element);
                    this.verifyElement('recheck', _target);
                    for (const el of $related) {
                        jQuery(el).validation().validation('verifyElement', 'recheck', _target);
                    }
                    if (element.dataset.popup === 'true') this._invalidFocus($related.add(element));
                }, 50);
            };
            if (this.$target.length) {
                if (shell) {
                    this._on(this.$target, recheck, onReCheck);
                } else {
                    for (const el of this.$target) {
                        Element.prototype.addEventListener.call(el, recheck, onReCheck, false);
                    }
                }
            }
        }

        if (this._popup) {
            this._on(this.$actionElement, 'focus', function (e) {
                if (this.$actionElement.attr('aria-invalid') === 'true') {
                    this._togglePopup(true);
                }
            });
            this._on(this.$actionElement, 'blur', function (e) {
                if (!e.currentTarget.contains(e.relatedTarget)) this._togglePopup(false);
            });
        }
    },
    _togglePopup: function (isShow) {
        const $popup = this.$message.closest('.aui-popup');
        if (isShow) {
            for (const el of jQuery('.' + _constant.POPUP_CLASS)) {
                jQuery(el).popup('hide');
            }
            $popup.popup('hoverShow', this.$actionElement, 99);
        } else {
            $popup.popup('hide');
        }
    },
    _getValue: function () {
        const fnReg = /(\w+)\((.*)\)/,
            valuePath = this._widget.valuePath || '',
            fnMatch = valuePath.match(fnReg);
        if (this._widget.shell === 'React') {
            return this._ShellBridge(this.$target, valuePath);
        } else if (fnMatch) {
            if (this.multiple) {
                const obj = {};
                for (const { name, checked } of this.$target) {
                    obj[name] = !!(obj[name] || checked);
                }
                const result = [];
                objectForEach(obj, function (k, v) {
                    if (v === false) result.push(k);
                });
                // return all unchecked name list.
                return result;
            } else {
                const target = this.$target.get(0),
                    fnName = fnMatch[1];
                let args = fnMatch[2].split(',');
                args = args.map((f) => f.trim().replaceAll(/('|")/g, '')).filter(Boolean);
                if (target[fnName]) return target[fnName](...args);
                return this.$target[fnName](...args);
            }
        } else {
            return getValue(this.$target, valuePath);
        }
    },
    _checkRules: function (value, ignoreSimple) {
        const valid = [];
        if (this.rules?.length < 1) return value;
        objectForEach(this.rules, function (rule, fn) {
            let ruleValid = true,
                isNot = false,
                message = fn;
            const type = typeof message;
            if (type === 'boolean' || type === 'string') {
                if (ignoreSimple) {
                    fn = () => true;
                } else {
                    if (message === false || rule.startsWith('!')) isNot = true;
                    // eslint-disable-next-line aui/no-direct-$$
                    fn = $$.type[rule.replace('!', '')];
                }
            }
            if (type === 'function') message = null;
            if (typeof fn === 'function') {
                ruleValid = fn(value);
                if (isNot) ruleValid = !ruleValid;
                if (ruleValid !== true && !isDeferred(ruleValid)) {
                    ruleValid = getMessage(message == null ? ruleValid : message, rule);
                }
            } else {
                ruleValid = null;
                error('[validation]', 'The validation rule: ' + rule + ' is not support!');
            }
            valid.push(ruleValid);
        });

        return valid;
    },
    _setValidState: function (valid, value) {
        const oldValue = this.valid,
            invalid = !valid || typeof valid === 'string';
        this.valid = invalid ? valid : true;
        this.$element.data('invalid', invalid);
        if (invalid) $(this.element).trigger('Open');
        // do nothing when the new & old valid value both true.
        if (oldValue === true && this.valid === true) return true;
        if (valid === null) return error('[validation]', 'Validation checked failed!');
        const $message = this.$message,
            msgId = $message.attr('id');
        let $actionElement = this.$actionElement;
        if (this.options.invalidby) {
            const target = this._actionElement(this.options.invalidby).get(0);
            if (target) {
                const explicitRole = target.hasAttribute('role');
                target.setAttribute(explicitRole ? 'aria-invalid' : 'data-verify-invalid', invalid);
            }
        } else if (this.$target.get(0) !== $actionElement.get(0)) {
            this.$target.attr('aria-invalid', invalid);
        }
        const arias = (invalid) => ({ 'aria-invalid': invalid, 'aria-errormessage': invalid ? msgId : '' });
        if (this.multiple) {
            for (const el of $actionElement) {
                const _invalid = invalid && value.includes(el.name);
                $(el).attrs(arias(_invalid));
                if (!_invalid) $actionElement = $actionElement.not(el);
            }
        } else {
            this._setAria(arias(invalid));
        }
        if (invalid) $actionElement.trigger('invalid');
        $message.attr('aria-live', invalid ? 'assertive' : 'off');
        if (this._popup) {
            $message.text(invalid ? valid : '');
            this._togglePopup(invalid);
        } else {
            const message = $message.get(0);
            $(message).toggleVisible(invalid);
            $$.syntheticClickCallback(() => {
                $message.text(invalid ? valid : '').toggle(invalid);
                if (!invalid) $(message).toggleVisible(!invalid);
            });
        }
    },
    _getLabelByElements: function (element) {
        if (element) {
            const value = element.ariaLabelledByElements;
            if (value !== undefined) return value || [];
            const refs = element.getAttribute('aria-labelledby');
            if (refs?.length) {
                const doc = element.getRootNode();
                return refs.split(' ').flatMap((id) => doc.getElementById(id) || []);
            }
        }
        return [];
    },
    invalidFocus: function ($actionElement) {
        if (!$actionElement) $actionElement = this.$actionElement;
        $actionElement.trigger('focus');
        $actionElement = this._actionElement($actionElement, true);
        const _actionElement = $actionElement.get(0);
        if (_actionElement && (_actionElement !== document.activeElement || $actionElement.find(document.activeElement).length === 0)) {
            _actionElement.focus({ preventScroll: true });
        }
        let targets = [this.element, !this._popup && Array.from(this.$message || []), _actionElement, this._getLabelByElements(_actionElement)[0]];
        const args = { bubbles: true, block: 'center', inline: this._popup ? 'nearest' : false };
        targets = targets.flatMap((x) => x || []);
        $$.scrollTo(targets, args);
    },
    _invalidFocus: function ($element) {
        const element = Array.prototype.find.call($element, (el) => jQuery(el).data('invalid') === true);
        if (element != null) {
            setTimeout(() => jQuery(element).validation('invalidFocus'));
        }
    },
    _verifyResult: function (valid, value) {
        let hasDeferred = false,
            first;
        const invalid = valid.filter(function (item) {
            const v = item !== true && item !== null;
            if (isDeferred(item)) {
                hasDeferred = true;
            } else if (v && first === undefined) {
                // non-deferred has invalid, set as the invalid state.
                first = item;
            }
            return v;
        });
        try {
            if (invalid.length && first !== undefined) {
                this._setValidState(first, value);
                return false;
            } else if (hasDeferred) {
                callbackResult(valid[0], (data, errMessage) => this._setValidState(data === false ? errMessage : data, value));
                return valid[0];
            } else {
                this._setValidState(true, value);
                return true;
            }
        } catch (e) {
            omit(e);
            return valid;
        }
    },
    _verifySkip: function () {
        if (!this._widget) return true;
        const $element = $(this.element),
            $target = this.$target,
            $actionElement = this.$actionElement;

        const $partialBoxes = $element.parents(`.aui-box-partial, :state(box_partial)`, $.$body);
        let invisible = !$element.is(':visible');
        // Get all partial boxes, the topmost one must be visible, parents to the nearest one don't contains invisible element.
        // Treat as visible if nearest visible partial box exist: for trigger the boxes opens.
        if (invisible && $partialBoxes.length && $partialBoxes.eq(-1).is(':visible')) {
            let hasHidden = false;
            const $paths = $element.parents('*', $partialBoxes.get(0));
            for (let i = 0; i < $paths.length - 1; i++) {
                const { display } = getComputedStyle($paths.get(i));
                if (display === 'none') {
                    hasHidden = true;
                    break;
                }
            }
            if (!hasHidden) {
                const list = $partialBoxes.toArray();
                invisible = list.some((el) => getComputedStyle(el).display === 'none' && !$(el).hasClass('aui-box-partial-content'));
            }
        }
        if (invisible) return true;

        let disabled = $element.is(':disable') || $target.is(':disable') || $actionElement.is(':disable');
        if (!disabled && !$target.is(':focusable')) {
            if ($actionElement.length === 0) this.$actionElement = this._actionElement($target);
            disabled = this.$actionElement.length === 0;
        }

        return disabled;
    },
    clear: function (force) {
        this._setValidState(true);
        if (force) {
            this.forceDestroy = true;
            this.destroy();
        }
    },
    verifyElement: function (type, target) {
        if (type === 'recheck' && !this.loaded) return;
        const skip = this._verifySkip();
        let value,
            valid = true;
        if (!skip) {
            const require = this.$element.attr('data-require'),
                element = this.$element.attr('data-element');
            value = this._getValue();
            if (require) {
                if (this.multiple) {
                    valid = !value.length;
                    if (!valid && type === 'recheck' && !value.includes(target.name)) return null;
                } else if (isEmpty(value) || (this._widget.type === 'Boolean' && (Array.isArray(value) ? !value.some((v) => !v) : value === false))) {
                    valid = false;
                }
            }
            if (Error.isError(value)) {
                valid = value.message;
            }
            if (isDeferred(value)) {
                valid = value.then((v) => (Error.isError(v) ? v.message : this._checkRules(v)));
            } else if (this.isFaker || valid === true) {
                valid = this._checkRules(value, !require && !value && valid === true);
            } else if (valid === false) {
                valid = getMessage(require, 'require', element);
            }
        }
        if (!Array.isArray(valid)) valid = [valid];
        return this._verifyResult(valid, value);
    },
    verify: function (clear, force) {
        const result = [],
            $element = jQuery(this.$element),
            group = $element.attr('data-group');
        let hasDeferred = false,
            $elements = $element.add($(this.$element).findAll('.' + _constant.CLASSNAME, { crossShadow: true, crossSlot: true }));
        if (group) $elements = $elements.filter('[data-group="' + group + '"]');
        Array.prototype.forEach.call(Array.prototype.reverse.call(jQuery($elements)), function (item) {
            const $item = jQuery(item),
                uninitialized = !$item.data('aui5Validation');
            let valid;
            if (uninitialized) {
                const validAttr = $item.attr('data-valid');
                if (validAttr) {
                    valid = validAttr === 'true';
                } else {
                    $item.validation();
                }
            }

            if (valid == null) {
                if (clear) return $item.validation('clear', force);
                valid = $item.validation('verifyElement');
            }
            if (isDeferred(valid)) hasDeferred = true;
            result.push(valid);
        });
        if (hasDeferred) {
            return Promise.all(result).finally(() => this._invalidFocus($elements));
        } else {
            this._invalidFocus($elements);
            return result.every((v) => v === true);
        }
    },
    _destroy: function () {
        const rules = this.rules,
            dataPrefix = this.ruleDataPrefix,
            element = this.$element;
        this.loaded = false;
        if (this.forceDestroy) {
            // cache rules into element data.
            Object.keys(rules).forEach(function (name) {
                element.data(dataPrefix + name, rules[name]);
            });
        }
    },
});
