import $ from '../../core/element/index.js';

import getValue from '../css/get-value.js';
import fixFloat from '../number/fix-float.js';
import objectEmpty from '../object/empty.js';

import { touchable, touchEvent, touchList } from './_touch.js';

/** @type {typeof $$.event.swipe} */
export default function swipe(element, orient, callback, sync) {
    if (!touchable) return;
    let min = Number.parseFloat(getValue('--widget-height-m'));
    min = fixFloat(min * 0.75);
    const data = touchEvent(element, 'swipeEvent', {
        touchstart: function (e) {
            const { target, currentTarget } = e,
                touches = touchList(e);
            if (touches.length === 1) {
                const touch = touches[0];
                data.id = touch.identifier;
                data.pageX = touch.pageX;
                data.pageY = touch.pageY;

                const scrollBox = $(target).closest(':scrollable', currentTarget).get();
                if (scrollBox) {
                    const precision = 3;
                    const { scrollTop, scrollLeft } = scrollBox,
                        // t r b l
                        scroll = [scrollTop === 0, false, false, scrollLeft === 0];
                    if (!scroll[0]) {
                        const { scrollHeight, clientHeight } = scrollBox;
                        scroll[2] = scrollHeight - clientHeight - scrollTop < precision;
                    }
                    if (!scroll[3]) {
                        const { scrollWidth, clientWidth } = scrollBox;
                        scroll[1] = scrollWidth - clientWidth - scrollLeft < precision;
                    }
                    data.scroll = scroll;
                } else {
                    data.scroll = false;
                }
            }
        },
        touchend: function (e) {
            const [offset, orient] = touchCallback(e, touchList(e));
            if (Math.abs(offset) > min) callback(e, offset, orient);
            objectEmpty(data);
        },
        touchcancel: function (e) {
            objectEmpty(data);
        },
        touchmove: (e) => {
            const [offset, orient] = touchCallback(e, touchList(e));
            if (offset) {
                e.preventDefault();
                if (sync) callback(e, offset, orient);
            }
        },
    });

    function arrowData(angle) {
        const result = [0, 0, 0, 0];
        if (angle > -135 && angle <= -45) {
            if (!data.scroll || data.scroll[2]) result[0] = 1; // up
        } else if (angle > -45 && angle <= 45) {
            if (!data.scroll || data.scroll[3]) result[1] = 1; // right
        } else if (angle > 45 && angle < 135) {
            if (!data.scroll || data.scroll[0]) result[2] = 1; // down
        } else {
            // eslint-disable-next-line no-lonely-if
            if (!data.scroll || data.scroll[1]) result[3] = 1; // left
        }
        return result;
    }
    function touchCallback(e, touches) {
        const touch = touches[0];
        if (touches.length === 1 && touch.identifier === data.id) {
            const changeX = touch.pageX - data.pageX,
                changeY = touch.pageY - data.pageY,
                length = Math.hypot(changeX, changeY);
            if (length > 2) {
                const angle = (Math.atan2(changeY, changeX) * 180) / Math.PI,
                    result = arrowData(angle);
                if ((orient === 'hv' || orient === 'h') && (result[1] || result[3])) {
                    return [changeX, 'h'];
                } else if ((orient === 'hv' || orient === 'v') && (result[0] || result[2])) {
                    return [changeY, 'v'];
                }
            }
        }
        return [];
    }
}
