            parentInfo = parent.getBoundingClientRect(),
            focusInfo = focusElement.getBoundingClientRect(),
            targetWidth = targetInfo.width,
            targetHeight = targetInfo.height,
            targetTop = targetInfo.top,
            targetRight = targetInfo.right,
            targetBottom = targetInfo.bottom,
            targetLeft = targetInfo.left,
            parentWidth = parentInfo.width,
            parentHeight = parentInfo.height,
            parentTop = parentInfo.top,
            parentRight = parentInfo.right,
            parentBottom = parentInfo.bottom,
            parentLeft = parentInfo.left,
            focusWidth = focusInfo.width,
            focusHeight = focusInfo.height,
            focusTop = focusInfo.top,
            focusRight = focusInfo.right,
            focusBottom = focusInfo.bottom,
            focusLeft = focusInfo.left,
