/** @jsxImportSource @gui/aui-devops */
import { define, Types, Widget } from '../../widget/widget.js';

import cssLength from '../../util/css/length.js';
import numberClamp from '../../util/number/clamp.js';
import stringFormat from '../../util/string/format.js';
import { isEmpty as typeIsEmpty } from '../../util/type/types.js';
import { isEqual } from '../../util/value-path.js';

import style from './style.less';

const I18N = $$.I18N.slider;

/** @extends {Widget<typeof Slider.options>} */
@define('slider')
export class Slider extends Widget {
    static options = {
        disabled: false,
        format: Types.Union([Types.string, Types.function], '{0}'),
        max: 100,
        markStep: Types.number,
        min: 0,
        name: '',
        orient: Types.Enum(['h', 'v'], 'h'),
        priorities: Types.Union([Types.array, Types.object]),
        range: false,
        readonly: false,
        reverse: false,
        size: Types.Length,
        step: 1,
        value: Types.Union([Types.array, Types.number]),
        onChange: Types.function,
    };
    static observers = ['disabled', 'max', 'min', 'readonly', 'size', 'step', 'value', 'name'];
    static upcasts = ['orient'];
    static shadow = { delegatesFocus: true, referenceTarget: 'input' };
    static formAssociated = true;
    static ariaTarget = 'input';
    static styles = style;

    optionsGetter = {
        orient: (v) => this.state.orient ?? v,
    };
    init() {
        const { orient, reverse, value } = this.options,
            isHorizontal = orient === 'h';

        this.state = {
            activeInputIndex: -1,
            dirty: false,
            orient,
            /**
             * Whether the input dir is "rtl".
             * If orient is "h" and reverse is true, return true.
             * If orient is "v" and reverse is false, return true.
             * Otherwise, return false.
             */
            isRtl: isHorizontal === reverse,
            // isRtl: isHorizontal ? (this.isRtl() ? reverse : !reverse) : !reverse,
            value,
        };
    }
    didMount() {
        if (this.state.orient === 'v') {
            const input = this.shadowRoot.querySelector('input'),
                { writingMode } = getComputedStyle(input);
            if (writingMode.startsWith('vertical')) {
                this.host._.ariaOrientation = 'vertical';
            } else {
                this.console.error('Vertical slider is not supported in this browser.');
                this._setOption('orient', 'h');
                this.setState({ orient: 'h', isRtl: false });
            }
        }
    }

    setOption(name) {
        switch (name) {
            case 'max':
            case 'min':
            case 'value': {
                const { max, min, range, value } = this.options;
                this.setState({
                    value: range ? value : numberClamp(min, value, max),
                });
                return false;
            }
        }
    }

    handleInput = (e) => {
        const value = Number(e.target.value);

        this.setState({ dirty: true, value });
        this.callback('onChange', value);
    };

    renderMarks(marks) {
        if (!marks?.length) return <></>;

        const { max, min } = this.options,
            { isRtl } = this.state,
            sortedMarks = isRtl ? marks.toReversed() : marks;

        return (
            <ol>
                {sortedMarks.map(({ content, value }, index, array) => {
                    const { value: previousMarkValue } = array[index - 1] ?? { value: isRtl ? max : min };
                    const size = this.getPercentage(Math.abs(value - previousMarkValue));

                    return (
                        <li style={{ inlineSize: size }}>
                            <div className="mark">{content}</div>
                        </li>
                    );
                })}
            </ol>
        );
    }

    /**
     * Get the percentage of the distance to the total length of the slider.
     * @returns The percentage.
     */
    getPercentage(distance) {
        const { max, min } = this.options;
        return `${(distance / (max - min)) * 100}%`;
    }

    getPriorities() {
        const { max, min, priorities } = this.options;
        if (typeIsEmpty(priorities)) return [];

        if (Array.isArray(priorities)) {
            const step = (max - min) / (priorities.length - 1);

            return priorities.map((priority, index) => ({
                content: priority,
                value: min + step * index,
            }));
        } else {
            return Object.entries(priorities)
                .flatMap(([key, value]) => (key <= max && key >= min ? [{ content: value, value: key }] : []))
                .sort(({ value: a }, { value: b }) => a - b);
        }
    }

    getTrackSize() {
        const { reverse } = this.options,
            { value } = this.state;
        const start = Math.min(...value),
            end = Math.max(...value);
        const inset = this.getPercentage(start),
            size = this.getPercentage(end - start);

        return { ...(reverse ? { insetInlineEnd: inset } : { insetInlineStart: inset }), inlineSize: size };
    }

    renderInput({ index, hasThumb = true, value: propsValue, ...rest }) {
        const { disabled, format, max, min, name, range, readonly, step } = this.options,
            { dirty, isRtl } = this.state,
            { label } = I18N,
            value = range ? propsValue : (propsValue ?? min),
            valueText = stringFormat(format, value);
        const tooltipId = `tooltip-${index}`,
            anchorName = `--${tooltipId}`; // eslint-disable-line no-unused-vars
        const args = { dir: isRtl ? 'rtl' : 'ltr', disabled: disabled || readonly, max, min, name, step, value, tabindex: -1, ...rest },
            arias = { disabled };
        if (hasThumb) {
            Object.assign(args, { tabindex: 0 });
            Object.assign(arias, { valueText });
        }

        return (
            <>
                <input type="range" className="input" autoComplete="off" data-dirty={dirty} {...args} {...this.arias(arias, { label, roleDescription: label })} />
                {hasThumb && (
                    <div className="thumb" style={this.getElementInset(value)}>
                        <div id={tooltipId} className="tooltip">
                            <div>{valueText}</div>
                        </div>
                    </div>
                )}
            </>
        );
    }

    getElementInset(value) {
        const { max, min } = this.options,
            { isRtl } = this.state;
        const inset = this.getPercentage(isRtl ? max - value : value - min);
        return { insetInlineStart: inset };
    }

    updateRangeValue = (value, index) => {
        const { max, min, step } = this.options;
        const oldValue = [...this.state.value];
        const previousValue = oldValue[index - 1];
        const nextValue = oldValue[index + 1];
        const floor = previousValue == null ? min : previousValue + step;
        const ceil = nextValue == null ? max : nextValue - step;
        const newValue = [...oldValue];

        if (value >= floor && value <= ceil) {
            newValue[index] = value;
        } else if (value < floor) {
            newValue[index] = floor;
        } else if (value > ceil) {
            newValue[index] = ceil;
        }

        if (!isEqual(oldValue, newValue)) {
            this.setState({ dirty: true, value: newValue });
            this.callback('onChange', newValue);
        }
    };

    handleRangeChange = (e) => {
        const value = Number(e.target.value);

        if (this.state.activeInputIndex === -1) {
            let minDistance = Infinity;
            this.state.value.forEach((val, index) => {
                const distance = Math.abs(value - val);

                if (distance < minDistance) {
                    minDistance = distance;
                    this.state.activeInputIndex = index;
                }
            });
        }

        this.updateRangeValue(value, this.state.activeInputIndex);
    };

    resetActiveInputIndex = () => {
        this.state.activeInputIndex = -1;
    };
    stopBubbling = (e) => e.stopPropagation();

    getMarks() {
        const { format, max, markStep, min } = this.options;
        if (markStep <= 0) return [];

        return Array.from({ length: Math.ceil((max - min) / markStep) + 1 }, (element, index) => {
            const value = min + markStep * index;
            return { content: stringFormat(format, value), value };
        });
    }

    render() {
        const { size, disabled, readonly } = this.options,
            { value } = this.state;

        return (
            <div className="box" style={{ inlineSize: cssLength(size) }}>
                {this.renderMarks(this.getPriorities())}
                <div className={['container', disabled ? 'disabled' : readonly && 'readonly']}>
                    {/* eslint-disable-next-line aui/jsx-list-identifier */}
                    {this.options.range ? (
                        <>
                            <div className="track" style={this.getTrackSize()} />
                            {value.map((value, index) =>
                                this.renderInput({
                                    id: index ? `input-${index}` : 'input',
                                    index,
                                    value,
                                    onInput: (e) => {
                                        this.updateRangeValue(Number(e.target.value), index);
                                        e.target.value = this.state.value[index];
                                    },
                                })
                            )}
                            {this.renderInput({
                                index: -1,
                                hasThumb: false,
                                value: value[0],
                                onInput: this.handleRangeChange,
                                onMouseUp: this.resetActiveInputIndex,
                                onTouchCancel: this.resetActiveInputIndex,
                                onTouchEnd: this.resetActiveInputIndex,
                                onTouchMove: this.stopBubbling,
                            })}
                        </>
                    ) : (
                        this.renderInput({ id: 'input', index: 0, value, onInput: this.handleInput, onTouchMove: this.stopBubbling })
                    )}
                </div>
                {this.renderMarks(this.getMarks())}
            </div>
        );
    }
}
