/** @type {typeof $$.string.htmlText2Entity} */
export default function htmlText2Entity(val) {
    let list = val.toLowerCase().split('');
    list = list.map(function (char) {
        if (/\w/.test(char)) {
            return char;
        }
        return '&#' + char.codePointAt(0) + ';';
    });
    return list.join('');
}
