/** @type {typeof $$.img.valid} */
export default function valid(element) {
    if (!element || element.complete === false) return false;
    switch (element.localName) {
        case 'img':
            return !!element.currentSrc && element.naturalWidth * element.naturalHeight > 0;
        case 'picture':
            return valid(element.querySelector('img'));
        case 'svg': {
            const { width, height } = element.getBBox();
            return width * height > 0;
        }
        default:
            return false;
    }
}
