import React, { PureComponent, createRef } from 'react';

import $ from '../../core/element/index.js';

import objectForEach from '../../util/object/for-each.js';

const LabelClass = 'aui-validation-label';
const RuleDataPrefix = 'rule_';
export class Validation extends R.Component {
    static dictionary = {};
    componentCreate() {
        this.labelId = LabelClass + '-' + this.uuid;
    }
    componentInit() {
        const hostQuery = '.aui-validation',
            $host = $(this.element).children(hostQuery).eq(0);
        if (this.props.rules) {
            const host = $host.get();
            objectForEach(this.props.rules, function (k, v) {
                jQuery(host).data(RuleDataPrefix + k, v);
            });
        }
        for (const el of $host.findAll('[aria="#validation.label"]', { crossShadow: true, crossSlot: true, until: hostQuery })) {
            const wrapper = $(el).closest(':widget', this.element).get();
            if (wrapper) {
                wrapper.method('setAria', '#' + this.labelId);
            } else {
                el.setAttribute('aria-labelledby', this.labelId);
            }
        }
    }
    getDictionary() {
        // event will add to widget element.
        return {
            RichEditor: { shell: 'React', recheck: 'onChange', valuePath: 'getValue' },
            Table: { shell: 'React', recheck: 'onChange', valuePath: 'getValue' },
            ...Validation.dictionary,
        };
    }
    getValue(widget, target) {
        const instance = $$.shell?.getInstance(target),
            fnName = widget.valuePath;
        return instance?.[fnName]();
    }
    args() {
        const { id, className = '', style = {}, slot, children, element, require, display, group, related, errorby, invalidby, popup } = this.props,
            _className = String('aui-validation ' + className).trim();
        if (display) style.display = display;
        const attrs = { id, className: _className, style, slot, children };
        return Object.assign(attrs, {
            'data-popup': popup ? true : null,
            'data-element': element,
            'data-group': group,
            'data-related': related,
            'data-require': require,
            'data-errorby': errorby,
            'data-invalidby': invalidby,
        });
    }
    label(v) {
        if (!v) return null;
        const className = ['label', LabelClass];
        if (this.props.require) className.push('require');
        return (
            <label id={this.labelId} className={className.join(' ')}>
                {v}
            </label>
        );
    }
    render() {
        const { slot, display, block, label } = this.props,
            args = this.args(),
            Tag = block ? 'div' : 'span';
        if (!label && display === 'contents') return <Tag {...args} slot={slot} />;
        return (
            <Tag style={{ display: display }} slot={slot}>
                {this.label(label)}
                <Tag {...args} />
            </Tag>
        );
    }
}

export class ValidationFaker extends PureComponent {
    ref = createRef();
    constructor(props) {
        super(props);
        this.isFn = typeof this.props.valid === 'function';
    }
    componentDidMount() {
        if (!this.isFn && !this.props.valid) {
            $$.verify(this.ref.current);
        }
    }
    componentDidUpdate(prevProps) {
        if (!this.isFn && (this.props.valid !== prevProps.valid || this.props.message !== prevProps.message)) {
            setTimeout(() => {
                $$.verify(this.ref.current);
            });
        }
    }
    customValid = () => {
        return this.isFn ? this.props.valid() : this.props.valid ? true : this.props.message;
    };
    render() {
        const { of, popup, children, ...args } = this.props;
        return (
            <Validation {...args} element="input:checkbox" require rules={{ customValid: this.customValid }} popup={popup}>
                <div className="aui-validation-faker" ref={this.ref}>
                    <input type="checkbox" defaultChecked tabIndex="-1" aria-hidden="true" data-of={of} />
                </div>
                {!popup && (children || <ValidationMessage />)}
            </Validation>
        );
    }
}

export function ValidationMessage() {
    return <div className="aui-validation-message" />;
}

$$.shell.define('Validation', Validation);
$$.shell.define('ValidationMessage', ValidationMessage, { pure: true });
$$.shell.define('ValidationFaker', ValidationFaker);
