/** @jsxImportSource @gui/aui-devops */
// cSpell:ignore Asize
import { define, Widget, Types } from '../../widget/widget.js';

import { keyName } from '../../util/event/key-name.js';
import numberClamp from '../../util/number/clamp.js';
import { isNumber as typeIsNumber } from '../../util/type/types.js';

import style from './style.less';

/** @extends {Widget<typeof Splitter.options>} */
@define('splitter')
export class Splitter extends Widget {
    static options = {
        orient: Types.Enum(['h', 'v'], 'h'),
        minAsize: '',
        minBsize: '200',
        defaultAsize: '',
        disabled: false,
        onResize: Types.function,
    };
    static styles = style;
    static observers = ['orient', 'disabled', 'minAsize', 'minBsize', 'defaultAsize'];

    init() {
        const { disabled, orient } = this.options;
        this.state = {
            disabled: disabled,
            orient: orient,
        };
        this.isMobile = $$.mobileView && $$.browser.touchable;
    }
    didRender() {
        const { defaultAsize } = this.options;
        this.bar = this.$element.find('.bar').get(0);
        this.firstElement = this.$element.find('.first-slot').get(0);
        this.lastElement = this.$element.find('.last-slot').get(0);
        this.setMinSize();
        this.setSize(this.firstElementSize ? this.firstElementSize : defaultAsize || (this.state.orient === 'h' ? '15%' : '200'));
    }
    method = {
        resizeTo: (numA, numB) => {
            const elementSize = this.state.orient === 'h' ? this.element.offsetWidth : this.element.offsetHeight;
            if (numA) {
                this.firstElementSize = numA;
                this.setSize(numA);
            } else {
                if (/%/.test(numB)) {
                    this.firstElementSize = 100 - Number.parseFloat(numB) + '%';
                    this.setSize(100 - Number.parseFloat(numB) + '%');
                } else {
                    this.firstElementSize = elementSize - numB;
                    this.setSize(elementSize - numB);
                }
            }
        },
    };
    setOption(name, value, oldValue) {
        switch (name) {
            case 'disabled':
                this.setState({ disabled: value });
                break;
            case 'orient':
                this.firstElementSize = '';
                this.setState({ orient: value });
                break;
            case 'defaultAsize':
                this.firstElementSize = '';
                break;
        }
    }
    setMinSize() {
        const { minAsize, minBsize } = this.options;
        const { orient } = this.state;
        const minSizeA = minAsize || (orient === 'h' ? '10%' : '200');
        this.minAsize = this.percentSize(minSizeA);
        this.maxAsize = 100 - this.percentSize(minBsize);
        this.firstElement.style['min-' + (orient === 'h' ? 'width' : 'height')] = this.handleSize(minSizeA);
        this.lastElement.style['min-' + (orient === 'h' ? 'width' : 'height')] = this.handleSize(minBsize);
        if (this.state.orient === 'h') {
            this.bar.setAttribute('aria-valuemin', this.minAsize);
            this.bar.setAttribute('aria-valuemax', this.maxAsize);
        }
    }
    percentSize(size) {
        const elementSize = this.state.orient === 'h' ? this.element.offsetWidth : this.element.offsetHeight;
        if (/px/.test(size) || typeIsNumber(size)) {
            return (Number.parseFloat(size) / elementSize).toFixed(2) * 100;
        } else if (/%/.test(size)) {
            return Number.parseFloat(size);
        }
    }
    handleSize(size) {
        return size + (typeIsNumber(size) ? 'px' : '');
    }
    setSize(size) {
        const { orient } = this.state;
        this.firstElement.style.flexBasis = this.handleSize(size);
        this.bar.style[orient === 'h' ? 'left' : 'top'] = '0px';
        this.bar.setAttribute('aria-valuenow', orient === 'h' || (orient === 'v' && this.options.defaultAsize.includes('%')) ? this.percentSize(size) : size);
        this.bar.setAttribute('aria-valuetext', size);
    }
    calculateSize = (e) => {
        const { minAsize } = this.options;
        const { orient } = this.state;
        const elementSize = orient === 'h' ? this.element.offsetWidth : this.element.offsetHeight,
            barSize = orient === 'h' ? this.bar.offsetWidth : this.bar.offsetHeight;
        let size;
        const moveHorizontal = e.pageX - this.$element.offset().left - barSize,
            moveVertical = e.pageY - this.$element.offset().top - barSize;
        if (orient === 'h' || (orient === 'v' && minAsize.includes('%'))) {
            const move = orient === 'h' ? moveHorizontal : moveVertical;
            const moveSize = Number.parseFloat(move / elementSize).toFixed(2) * 100;
            size = numberClamp(this.minAsize, moveSize, this.maxAsize) + '%';
        } else {
            size = Math.max(moveVertical, minAsize);
        }
        this.firstElementSize = size;
        this.setSize(size);
        this.callback('onResize', {
            aSize: orient === 'h' ? this.firstElement.offsetWidth : this.firstElement.offsetHeight,
            bSize: orient === 'h' ? this.lastElement.offsetWidth : this.lastElement.offsetHeight,
        });
    };
    onDragStart = (e) => {
        this.bar.classList.add('drag-move');
        this.element.classList.add('forbid-actions');
    };
    onDragging = (e) => {
        this.calculateSize(e);
    };
    onDragEnd = (e) => {
        this.bar.classList.remove('drag-move');
        this.element.classList.remove('forbid-actions');
    };
    onKeyDown = (e) => {
        const { orient } = this.state,
            name = keyName(e);
        switch (name) {
            case 'ArrowLeft':
            case 'Alt+ArrowLeft':
                e.preventDefault();
                if (orient === 'h') this.arrowResize();
                break;
            case 'ArrowUp':
            case 'Alt+ArrowUp':
                e.preventDefault();
                if (orient === 'v') this.arrowResize();
                break;
            case 'ArrowRight':
            case 'Alt+ArrowRight':
                e.preventDefault();
                if (orient === 'h') this.arrowResize('add');
                break;
            case 'ArrowDown':
            case 'Alt+ArrowDown':
                e.preventDefault();
                if (orient === 'v') this.arrowResize('add');
                break;
            case 'Home':
                e.preventDefault();
                this.setSize(this.minAsize + '%');
                break;
            case 'End':
                e.preventDefault();
                this.setSize(this.maxAsize + '%');
                break;
        }
    };
    arrowResize(str) {
        const { minAsize } = this.options;
        if (this.state.orient === 'h' || (this.state.orient === 'v' && minAsize.includes('%'))) {
            const flexBasis = this.percentSize(this.firstElement.style.flexBasis);
            let distance = str === 'add' ? flexBasis + 1 : flexBasis - 1;
            distance = numberClamp(this.minAsize, distance, this.maxAsize);
            this.setSize(distance + '%');
        } else {
            const flexBasis = Number.parseFloat(this.firstElement.style.flexBasis);
            let distance = str === 'add' ? flexBasis + 50 : flexBasis - 50;
            distance = Math.max(distance, minAsize);
            this.setSize(distance);
        }
    }
    render() {
        const { orient, disabled } = this.state;
        return (
            <div className={['splitter', 'splitter-' + orient, this.isMobile && 'mobile-view']}>
                <slot name="a" className="first-slot"></slot>
                <aui-drag
                    axis={orient === 'h' ? 'x' : 'y'}
                    within="parent"
                    cursor={orient === 'h' ? 'col-resize' : 'row-resize'}
                    disabled={disabled}
                    onDragStart={this.onDragStart}
                    onDragging={this.onDragging}
                    onDragEnd={this.onDragEnd}
                >
                    <div className={['bar', disabled && 'disabled']} role="separator" tabIndex={0} onKeyDown={this.onKeyDown}>
                        <span className={this.fontIcon(orient === 'h' ? 'faui-ellipsis-dot-v' : 'faui-ellipsis-dot')}></span>
                    </div>
                </aui-drag>
                <slot name="b" className="last-slot"></slot>
            </div>
        );
    }
}
