import { warn, error } from './log.js';
import { onloading, onload } from './onload.js';

/**
 * @example
 * <meta name="aui.config" content="theme=#007c8c">
 * <meta name="aui.config" content="colorScheme=auto&theme=#007c8c&injectStyles=#inject&mobileViewEnable=true&skin=Apollo">
 */
const DefaultConfig = {
    /** @type {'auto' | 'light' | 'dark'} @todo `[Updatable]` Color scheme. */
    colorScheme: 'light',

    /** @type {string | null} `[Updatable]` theme color, only apply to dynamic theme feature. */
    theme: null,

    /** @type {string | null} `[Non-Updatable]` The selector query of injected styles resource element. */
    injectStyles: null,

    /** `[Non-Updatable]` Whether to enable mobileView in mobile devices. */
    mobileViewEnable: false,

    /** @type {'Apollo' | 'Allure'} `[Non-Updatable]` Skin name. */
    skin: 'Apollo',
};

const config = { ...DefaultConfig };
const MetaName = 'aui.config',
    Observers = new Set(['theme']);
const CssVars = {
    skin: '--skin-name',
    theme: '--theme-value',
};

const root = document.documentElement;
const getBody = () => (config.body = document.body);
Object.assign(config, { root, body: getBody() });
if (!config.body) onloading(getBody);

function setColorScheme() {}

const setTheme = (function (relativeThemeColorSupports) {
    // Chrome ≥ 125; Firefox ≥ 135; Safari ≥ 18.2
    return function (theme) {
        if (!theme) return;

        if (relativeThemeColorSupports) {
            root.style.setProperty(CssVars.theme, theme);
        } else {
            const currentTheme = getComputedStyle(root).getPropertyValue('--theme-6');
            if (theme !== currentTheme) {
                root.style.setProperty(`--theme-6`, theme);
                warn('Dynamic theme color is not supported in current env browser.');
            }
        }
    };
})(CSS.supports('color', 'oklch(from #000 l c h)') && CSS.supports('selector(:state(x))'));

function setInjectStyles(queries) {
    if (!queries) return;
    const callback = new Map();
    config.injectStyles = queries;
    config.injectStylesData = { _blocking: (id, fn) => callback.set(id ?? '__' + callback.size, fn) };

    const styleResponse = (css) => {
        const sheet = new CSSStyleSheet();
        sheet.replaceSync(css);
        const injectStylesData = {};
        for (const rule of sheet.cssRules) {
            if (rule.constructor.name === 'CSSLayerBlockRule') {
                const { name } = rule,
                    styles = Array.prototype.map.call(rule.cssRules, (r) => r.cssText);
                if (styles.length && !injectStylesData[name]) {
                    injectStylesData[name] = styles;
                }
            }
        }
        return injectStylesData;
    };
    const loadInjectStyle = (href) => {
        return fetch(href, { priority: 'high' })
            .then((res) => res.text())
            .then(styleResponse)
            .catch(error);
    };

    onload(function () {
        const elements = document.querySelectorAll(queries);
        const list = Array.prototype.flatMap.call(elements, (el) => {
            if (el.localName === 'link' && el.href) {
                const attrValid = el.rel === 'preload' && el.as === 'fetch' && el.crossOrigin === 'anonymous';
                if (!attrValid) error('Inject style link attributes error!', 'Template:', `<link rel="preload" as="fetch" crossorigin href="x.css">`);
                return loadInjectStyle(el.href);
            }
            return [];
        });
        Promise.allSettled(list).then((results) => {
            for (const { status, value, reason } of results) {
                if (status === 'fulfilled' && value) {
                    for (const [name, styles] of Object.entries(value)) {
                        if (!config.injectStylesData[name]) config.injectStylesData[name] = [];
                        config.injectStylesData[name].push(...styles);
                    }
                } else {
                    error(reason);
                }
            }

            delete config.injectStylesData._blocking;
            for (const fn of callback.values()) fn();
            callback.clear();
        });
    });
}

function setSkin(skin) {
    if (!skin) config.skin = getComputedStyle(root).getPropertyValue(CssVars.skin) || 'Apollo';
    CSS.registerProperty({ name: CssVars.skin, syntax: '<custom-ident>', inherits: true, initialValue: config.skin });
}

const Updater = { colorScheme: setColorScheme, theme: setTheme },
    listeners = new Set(),
    metaConfig = document.head?.querySelector(`meta[name="${MetaName}"]`);
let lockObserver = false;

setInjectStyles(config.injectStyles);
setSkin(config.skin);

/** For updatable config. */
(function useMetaConfig() {
    if (!metaConfig) return;
    let initialized = false;

    function parseMetaConfig(content) {
        if (!content) return;
        for (const [key, value] of new URLSearchParams(content)) {
            setConfig(key, value, { initialized, useMeta: false });
        }
        initialized = true;
    }

    const observer = new MutationObserver((mutations) => {
        mutations.forEach((mutation) => !lockObserver && mutation.type === 'attributes' && parseMetaConfig(mutation.target.content));
    });
    observer.observe(metaConfig, { attributes: true, attributeFilter: ['content'] });

    parseMetaConfig(metaConfig.content);
})();

function listenConfig(isAdd, cb) {
    if (typeof cb === 'function') return void (isAdd ? listeners.add(cb) : listeners.delete(cb));
}

function setConfig(key, value, { initialized, quiet, silent, useMeta }) {
    if (value == null || !key || !value) return;
    if (!Object.hasOwn(DefaultConfig, key)) return quiet || silent ? false : warn(`Config "${key}" is not a valid config key!`);
    if (initialized !== false) {
        if (config[key] === value) return;
        if (!Observers.has(key)) return silent ? false : warn(`Config "${key}" is not support to update!`);
    }
    lockObserver = true;
    if (useMeta !== false && metaConfig) {
        const params = new URLSearchParams(metaConfig.content);
        params.set(key, value);
        metaConfig.content = params.toString();
    }
    config[key] = value;
    const updater = Updater[key];
    if (typeof updater === 'function') updater(value);
    listeners.forEach((fn) => fn(key, value));
    lockObserver = false;

    return true;
}

export { config, setConfig, listenConfig };
