/** @jsxImportSource @gui/aui-devops */
import { addInternalPlugin } from '../loader.js';
import '../music/music.js';

const I18N = $$.I18N.music;

addInternalPlugin('Music', ({ Plugin, Toolbar, Dialog }) => {
    class MusicButton extends Toolbar.Button {
        icon = true;
        willMount() {
            this.tooltip = I18N.tooltip;
        }
        onClick() {
            this.showDialog(true);
        }
    }

    class MusicDialog extends Dialog {
        header = I18N.header;
        width = 1200;
        resizeable = true;

        didMount() {
            this.music = this.element;
        }
        onShow = (data) => {
            if (data) {
                this.music.method('setValue', data.value);
            }
        };
        onHide = () => {
            this.music.method('hide');
        };
        onSubmit = () => {
            const obj = this.music.method('getValue'),
                html = obj.svg.innerHTML ?? '';
            this.setValue(html, {
                value: obj.value,
            });
        };
        onOkClick = () => {
            if (!this.submitter.disabled) {
                this.submit();
                this.hide();
            }
        };
        updateButtonStatus = (bool) => {
            this.submitter.disabled = bool;
        };
        render() {
            return <aui-music okClick={this.onOkClick} updateButtonStatus={this.updateButtonStatus} />;
        }
    }

    return class Music extends Plugin {
        static toolbar = MusicButton;
        partable = true;

        create() {
            this.addDialog(MusicDialog);
        }
        onData(data) {
            this.showDialog(true, data);
        }
    };
});
