/** @jsxImportSource @gui/aui-devops */
import { FocusPush, FocusPop } from '../../core/module/stack-focus/stack-focus.js';
import { define, Widget, Types } from '../../widget/widget.js';

import dateSince from '../../util/date/date-since.js';
import dateFormat from '../../util/date/format.js';
import { getFormat } from '../../util/date/formats.js';

import '../progressbar/progressbar.js';

import { getOrCreateToaster } from './utils.js';

import style from './style.less';

const Icons = {
    bell: 'faui-notification icon-link',
    info: 'faui-comment icon-info',
    warn: 'faui-warning-solid icon-warn',
    error: 'faui-error-solid icon-error',
    success: 'faui-ok icon-success',
};

/** @type {HTMLElement} */
let Toaster = null;
const Toasts = new Set();

export function toast(value, query) {
    Toaster = getOrCreateToaster();
    if (value == null) return;

    const appendToast = ({ content, ...rests }) => {
        const toast = <aui-toast {...rests}>{content}</aui-toast>;
        Toaster.append(toast);
        toast.method('toggle', true);
        return toast.id;
    };

    switch (typeof value) {
        case 'object':
            return appendToast(value);
        case 'string':
            return appendToast({ content: value });
        case 'boolean': {
            const isShow = value,
                toggleToast = (target) => target?.method('toggle', isShow);
            if (query) {
                const selector = Toasts.has(query) ? '#' + query : query,
                    target = Toaster.querySelector(selector);
                toggleToast(target);
                if (target.id) return target.id;
            } else if (!isShow) {
                const [...list] = Toaster.children;
                list.forEach(toggleToast);
            }
            return null;
        }
    }
}

Object.assign($$, { toast });

/** @extends {Widget<typeof Toast.options>} */
@define('toast')
export class Toast extends Widget {
    static options = {
        classify: Types.Enum(['bell', 'info', 'warn', 'error', 'success'], 'info'),
        closeable: true,
        content: Types.Content.value(''),
        date: Types.Union([Types.date, Types.string, Types.number]),
        dateTimeFormat: Types.Union([Types.function, Types.Enum(['since'])], null),
        delayClose: 0,
        focusable: true,
        icon: Types.string,
        progress: Types.Union([Types.boolean, Types.number], false),
        stable: false,
        state: Types.Enum(['default', 'read', 'unread', 'highlight'], 'default'),
        timeout: 5,
        onClose: Types.function,
    };
    static observers = ['closeable', 'content', 'progress'];
    static upcasts = ['stable'];
    static styles = style;

    method = { toggle: this.toggle };

    init() {
        const { closeable, delayClose, id } = this.options;

        this.host.id = id || `toast-${this.uuid}`;

        this.state = {
            canShowClose: !delayClose,
            isShow: false,
            progressBarValue: this.getProgressBarValue(),
            showClose: closeable && !delayClose,
        };
    }

    getProgressBarValue = () => {
        const { progress } = this.options;

        if (typeof progress === 'number') {
            return progress === -1 ? null : progress;
        }

        return progress ? 0 : null;
    };

    didMount() {
        if (this.options.focusable) this.doFocus();
    }

    toggle(isShow) {
        return isShow ? this.show() : this.hide();
    }

    doFocus() {
        const { element } = this;
        if (element && this.state.isShow) {
            FocusPush(this);
            element.focus({ preventScroll: true });
            $$.scrollTo(element, { block: 'nearest', inline: false, offsetY: 16 });
        }
    }

    setOption(name, value) {
        switch (name) {
            case 'closeable':
                this.setState({
                    showClose: value && this.state.canShowClose,
                });
                break;
            case 'progress':
                if (this.progressTimer) {
                    clearInterval(this.progressTimer);
                }
                if (value === true) {
                    this.setProgressTimer(Date.now() - this.startTime - 1000);
                }
                this.setState({ progressBarValue: this.getProgressBarValue() });
                break;
            default:
                break;
        }
    }

    setProgressTimer(duration) {
        const delay = duration / 100; // The duration(unit: ms) is the time that spent for progress bar value increase form 0 to 100.

        this.progressTimer = setInterval(() => {
            const { progressBarValue } = this.state;

            if (progressBarValue < 100) {
                this.setState({ progressBarValue: progressBarValue + 1 });
            }
        }, delay);
    }

    hide() {
        if (this.state.isShow) {
            this.setShow(false);
            this.setState({ progressBarValue: 0 });
            this.clearTimers();

            if (!this.options.stable) {
                this.host.remove();
            }

            Toasts.delete(this.host.id);

            if (Toasts.size === 0) {
                Toaster.hidePopover();
                Toaster.toggleAttribute('inert', true);
                FocusPop(this);
            }
        }
    }

    setShow = (isShow) => {
        this.host.style.display = isShow ? 'block' : 'none';
        this.setState({ isShow }, false);
    };

    clearTimers = () => {
        clearTimeout(this.delayCloseTimer);
        clearTimeout(this.closeTimer);
        clearInterval(this.progressTimer);
    };

    show() {
        if (!this.state.isShow) {
            this.setShow(true);

            if (Toaster) {
                Toaster.toggleAttribute('inert', false);
                Toaster.append(this.host);
                Toaster.showPopover();
                Toasts.add(this.host.id);
            }

            // Reset progress bar value.
            this.setState({ progressBarValue: this.getProgressBarValue() });
            this.setTimers();
            this.doFocus();
        }
    }

    setTimers() {
        const { closeable, delayClose, progress, timeout } = this.options;

        if (delayClose) {
            this.delayCloseTimer = setTimeout(() => {
                this.setState({ showClose: closeable, canShowClose: true });
            }, delayClose * 1000);
        }

        if (timeout > 0) {
            this.remainingTime = timeout * 1000;
            this.setCloseTimer();

            if (progress === true) {
                this.setProgressTimer((timeout - 1) * 1000);
            }
        }
    }

    setCloseTimer = () => {
        this.closeTimer = setTimeout(() => {
            this.callback('onClose');
            this.hide();
        }, this.remainingTime);

        this.startTime = Date.now();
    };

    onMouseEnter = () => {
        if (this.options.timeout > 0) {
            clearTimeout(this.closeTimer);
            this.endTime = Date.now();
        }
    };

    onMouseLeave = () => {
        if (this.state.isShow) {
            this.resetCloseTimer();
        }
    };

    resetCloseTimer = () => {
        if (this.options.timeout > 0) {
            this.remainingTime = this.remainingTime - (this.endTime - this.startTime);
            this.setCloseTimer();
        }
    };

    formatDate = (date) => {
        const { dateTimeFormat: format } = this.options;
        const newDate = new Date(date);

        if (typeof format === 'function') {
            return format(newDate);
        } else if (format === 'since') {
            return dateSince(newDate);
        } else if (!format) {
            return dateFormat(newDate, getFormat());
        }
    };

    handleClose = () => {
        this.callback('onClose');
        this.hide();
    };

    render() {
        const { classify, content, date, closeable, icon, progress, state, timeout } = this.options;
        const { progressBarValue, showClose } = this.state;
        const hasProgressBar = typeof progress === 'number' || (progress === true && timeout > 0);

        return (
            <div className="toast" role="alert" tabIndex={0} data-classify={classify} data-state={state} onMouseEnter={this.onMouseEnter} onMouseLeave={this.onMouseLeave}>
                {hasProgressBar && <aui-progressbar classify={classify === 'bell' ? 'info' : classify} value={progressBarValue} weight="xs" />}
                <div className="body">
                    <slot className="icon" name="icon">
                        <span className={this.fontIcon(icon ?? Icons[classify], true)} />
                    </slot>
                    <div className="main">
                        <slot className="title" name="title" />
                        <slot className="content" name="content">
                            {content}
                        </slot>
                        <slot />
                        {date && <div className="date">{this.formatDate(date)}</div>}
                    </div>
                    {closeable && <aui-button-lite className="close" hidden={!showClose} icon="faui-close" tooltip={$$.I18N.toast.close} type="plain" onClick={this.handleClose} />}
                </div>
            </div>
        );
    }
}
