/** @jsxImportSource @gui/aui-devops */
import { addTooltip } from '../../core/module/tooltip.js';
import { define, Types, Widget } from '../../widget/widget.js';

import downloadFile from '../../util/io/download-file.js';
import { fileIconContent as ioFileIconContent } from '../../util/io/file-icon.js';
import numberFixFloat from '../../util/number/fix-float.js';

import { confirm } from '../messagedialog/messagedialog.js';

import { DeleteService, FileEntity, findFile, fileId } from './utils.js';
import '../progressbar/progressbar.js';

import buttonStyle from '../button/button.less';
import style from './echo.less';

const I18N = $$.I18N.uploader;
const CommonOptions = {
    deleteable: true,
    downloadable: false,
    showProgress: false,
    customizeField: Types.Component,
    doDownload: Types.function,
};

/** @extends {Widget<typeof Echo.options>} */
@define('uploader-echo')
export class Echo extends Widget {
    static downstreamContext = ['overwrite', ['uploader-echo-item'], Object.keys(CommonOptions)];
    static options = {
        ...CommonOptions,

        disabled: Types.boolean,
        files: Types.array,

        doDelete: Types.function,
        onDelete: Types.function,
    };
    static observers = ['customizeField', 'deleteable', 'downloadable', 'files'];
    static styles = [style, { button: buttonStyle }];
    static internals = { role: 'list' };

    /** @type {DeleteService} */
    #deleteService = {};
    init() {
        this.dispatcher = this.useUnicom(['uploader', 'echo'], this.receiver);
    }
    didMount() {
        addTooltip(this.host);
        this.updateFiles(this.options.files);

        this.dispatcher('uploader', 'getService').then((service) => {
            const deleteService = service.delete;
            deleteService.init(this.options);
            this.#deleteService = deleteService;
        });
    }
    setOption(name, value) {
        switch (name) {
            case 'files':
                this.updateFiles(value);
                return false;
            default:
                break;
        }
    }
    receiver = (action, from, ...args) => {
        switch (action) {
            case 'getFiles':
                // Trigger by uploader, get current files.
                return this.options.files ?? [];
            case 'fileProgress': {
                // Trigger by picker, called when uploaded file piece.
                this.setProgress(...args);
                return false;
            }
        }
    };

    updateFiles = (files) => {
        return this.dispatcher('uploader', 'updateFiles', files);
    };
    doAbort = (file) => {
        return this.dispatcher('picker?', 'abortUpload', file).then(() => {
            const files = this.#deleteService.filter(file, this.options.files);
            this.updateFiles(files);
        });
    };
    doDeleteFile = (file) => {
        return this.#deleteService.exec(this.options.files, file, I18N.removeFailed).then(this.updateFiles);
    };

    setProgress(fileEntity, percent) {
        const { files, showProgress } = this.options;
        if (showProgress && files?.length) {
            const index = findFile(files, fileEntity, (f) => f.status === 'uploading');
            if (index == null) {
                this.console.error(`No file matches "${fileEntity.fileName}" for progress update.`);
            } else {
                const file = files[index];
                let progress;
                if (percent === 'indeterminate') {
                    progress = percent;
                } else {
                    const p = numberFixFloat(percent);
                    progress = p === 100 ? 100 : (fileEntity.progress ?? p);
                }
                file.progress = progress;
                if (!file.fileId) file.fileId = fileEntity.fileId;
                this.setState();
            }
        }
    }

    render() {
        const { files, disabled } = this.options;
        return files?.map((file) => (
            <aui-uploader-echo-item
                className="item"
                id={fileId(file)}
                disabled={disabled === true}
                file={file}
                fontIcon={this.fontIcon}
                doAbort={this.doAbort}
                doDelete={this.doDeleteFile}
            />
        ));
    }
}

/** @extends {Widget<typeof EchoItem.options>} */
@define('uploader-echo-item')
export class EchoItem extends Widget {
    static options = {
        ...CommonOptions,
        disabled: Types.boolean,
        file: Types.object,

        fontIcon: Types.function,
        doAbort: Types.function,
        doDelete: Types.function,
    };
    static observers = ['disabled', 'downloadable', 'file'];
    static shadow = false;
    static internals = { role: 'listitem' };

    init() {
        this.state = { disabled: false };
    }

    onDelete = (e) => {
        const { file, doAbort, doDelete } = this.options;
        const cb = () => {
            const { status } = file;
            file.status = 'deleting';
            this.setState({ disabled: true });
            return status === 'uploading' ? doAbort(file) : doDelete(file);
        };
        if (file.isSucceed || file.fileId) {
            confirm(true, { title: I18N.deleteFileTitle, content: I18N.removeMessage, onClose: (v) => v && cb() });
        } else {
            cb();
        }
    };
    onDownload = (e) => {
        const { file, doDownload } = this.options;
        if (doDownload) {
            e.preventDefault();
            const { fileId, fileName } = file;
            this.callbackResult(doDownload(fileId, fileName), (data) => {
                if (data) {
                    downloadFile(data, file.fileName);
                }
            });
        } else if (!file.url) {
            e.preventDefault();
        }
    };

    renderName(downloadable, { fileName, url }) {
        if (!downloadable) return <span>{fileName}</span>;
        return (
            <a download={fileName} href={url || '###'} target="_blank" rel="noopener noreferrer" onClick={this.onDownload}>
                {fileName}
            </a>
        );
    }
    renderContent({ status, isSucceed, fileSize, message }) {
        if (status && I18N[status]) return <span className={['status', status]}>{I18N[status]}</span>;
        if (isSucceed) return <span className="size">{fileSize}</span>;
        return <span className="message">{message || I18N.uploadFailed}</span>;
    }
    render() {
        const { file, deleteable, downloadable, showProgress, customizeField, fontIcon } = this.options,
            disabled = this.state.disabled || this.options.disabled,
            fileEntity = new FileEntity(file),
            { status, fileExtension, fileSize } = fileEntity,
            progress = fileEntity.progress ?? (status === 'uploading' ? 0 : null),
            invalid = fileEntity.isSucceed === false,
            valid = !invalid,
            [icon, iconContent] = ioFileIconContent(fileExtension);

        /// The `.aui-validation` and `[data-valid]` is workaround for validation. Pending https://jira.avepoint.net/browse/AUI-2781
        return (
            <>
                <div className={['box', 'aui-validation']} data-valid={valid} data-status={status}>
                    <div className={['icon', fontIcon(icon, iconContent ? { content: iconContent, style: 'base64' } : false)]} />
                    <div className="main">
                        <div className="name text-overflow" data-tooltip="ifneed" data-tooltip-wrap="force" aria-description={fileSize}>
                            {this.renderName(valid && downloadable, fileEntity)}
                        </div>
                        <div className="content">{this.renderContent(fileEntity)}</div>
                    </div>
                    <div className="action">
                        {deleteable && (
                            <aui-button-lite type="bald" tooltip={I18N.delete} disabled={disabled} icon={invalid ? 'faui-cancel' : 'faui-remove'} onClick={this.onDelete} />
                        )}
                        <section className="customize-field empty-hidden">{valid && $$.fn(customizeField)({ disabled, file: fileEntity.file })}</section>
                    </div>
                </div>
                {showProgress && <aui-progressbar value={progress === 'indeterminate' ? null : progress} hidden={progress == null} weight="xs" />}
            </>
        );
    }
}
