// cSpell:ignore rowchecker
/* eslint-disable complexity, no-param-reassign */
import React, { Component, PureComponent, createRef, createContext, Children, cloneElement, useContext, useState, useEffect, useInstance } from 'react';

import { callbackResult } from '../../core/base/internal.js';
import { warn, error } from '../../core/base/log.js';
import $ from '../../core/element/index.js';
import { resize as resizeObserver } from '../../core/module/observer/observer.js';

import { concat } from '../../util/array/concat.js';
import { map as arrayMap } from '../../util/array/map.js';
import cssClamp from '../../util/css/clamp.js';
import cssLength from '../../util/css/length.js';
import replaceSheet from '../../util/css/replace-sheet.js';
import eventIsKey from '../../util/event/is-key.js';
import { keyName } from '../../util/event/key-name.js';
import { navigation2D } from '../../util/event/navigation.js';
import { isNumber } from '../../util/type/types.js';

import { ButtonGroup } from '../buttongroup/buttongroup.jsx';
import { Checkbox } from '../checkbox/checkbox.jsx';
import { Drag } from '../dragdrop/dragdrop.jsx';
import { elementLoading } from '../loading/loading.js';

import './puretable.jsx';

const I18N = $$.I18N.table;
const ArrowOffset = { ArrowUp: [-1, 0], ArrowDown: [1, 0], ArrowLeft: [0, -1], ArrowRight: [0, 1] };
const TableContext = createContext({});
let winWidth = null;
let uuid = 0;

export class Table extends PureComponent {
    static defaultProps = {
        frozenCount: 0,
        columns: [],
        items: [],
        flexible: true,
        rowKeyField: 'id',
    };
    id = 'aui-table-' + uuid++;
    ref = createRef();
    constructor(props) {
        super(props);
        if (winWidth == null) winWidth = document.documentElement.clientWidth;
        this.member = {};
    }
    componentDidMount() {
        if (this.props.id) $$.getUniqueElement('#' + this.props.id);
        // Only allow validation in verifiable case.
        if (this.props.verifiable) this.verify = () => [this.getValue()];
    }
    getValue = () => {
        return this.props.items;
    };
    keyEvent = (e) => {
        const target = e.target;
        if (target === e.currentTarget || e.currentTarget.contains(target)) {
            const root = this.ref.current.closest('.aui-table'),
                $active = $.$activeElement(),
                $path = $active.parents(null, root);
            if (!$path.length || $path.filter(':moveable, :toplayer').length) return;
            const cellAttr = 'data-cell',
                key = keyName(e),
                offset = ArrowOffset[key];
            if (offset) {
                e.preventDefault();
                navigation2D(e, cellAttr, root);
            } else if (/(home|end)/i.test(key)) {
                const k = RegExp.$1.toLowerCase(),
                    selector = `[tabindex][${cellAttr}]`;
                let list;
                e.preventDefault();
                if (e.ctrlKey) {
                    list = root.querySelectorAll(selector);
                } else {
                    const current = target.closest(selector);
                    list = current.parentElement.querySelectorAll(':scope>' + selector);
                }
                const _target = Array.prototype.at.call(list, k === 'home' ? 0 : -1);
                _target?.focus({ focusVisible: true });
            }
        }
    };
    style() {
        const { props } = this,
            obj = {};
        if (props.height) {
            if (Array.isArray(props.height)) {
                obj.minHeight = props.height[0] || null;
                obj.maxHeight = props.height[1] || null;
            } else {
                obj.height = props.height;
            }
        }
        if (props.width) {
            if (Array.isArray(props.width)) {
                obj.minWidth = props.width[0] || null;
                obj.maxWidth = props.width[1] || null;
            } else {
                obj.width = props.width;
            }
        }
        return obj;
    }
    loading = (isShow, args = {}) => {
        const box = this.ref.current;
        if (!args.focus) args.focus = null;
        if (box) elementLoading(box.parentNode, isShow, args);
    };
    scrollTo(...args) {
        if (!args.length) args = [0, 0];
        const box = this.ref.current;
        box?.scrollTo(...args);
    }
    columnVisible = (...args) => {
        const [data, visible] = args;
        const columns = this.props.columns.slice();
        if (args.length === 1) {
            for (const k of Object.keys(data)) {
                const i = Number(k),
                    v = data[k];
                if (typeof v === 'boolean') {
                    if (Number.isNaN(i)) {
                        error('[table]', 'Argument invalid!');
                    } else {
                        columns[i]['visible'] = v;
                    }
                }
            }
        } else {
            columns[data]['visible'] = visible;
        }
        this.forceUpdate(() => this.member.grid.updateColumns(columns));
    };
    clearSort = () => {
        return this.method('clearSort');
    };
    selectAll(checked) {
        return this.method('selectAll', checked);
    }
    method = (type, ...args) => {
        const { member } = this;
        switch (type) {
            case 'clearSort':
                return member.header.clearSort();
            case 'checkedCallback':
            case 'selectAll':
            case 'trySelectAll':
                return member.header[type](...args);
        }
    };
    render() {
        const { slot, ...props } = this.props,
            { verifiable } = props,
            id = props.id || this.id;
        return (
            <div
                slot={slot}
                className="aui-table"
                id={id}
                role={verifiable ? 'listbox' : 'table'}
                aria-label={verifiable && typeof verifiable === 'string' ? verifiable : null}
                aria-multiselectable={verifiable ? true : null}
                tabIndex="0"
                data-zindex="3"
                onKeyDown={this.keyEvent}
            >
                <div className="aui-table-box" ref={this.ref} style={this.style()}>
                    <div className="aui-table-freezer" />
                    <style />
                    <TableGrid {...props} id={id} root={this.ref} method={this.method} member={this.member} />
                </div>
            </div>
        );
    }
}

function isFrozen(col, frozenCount, checkable) {
    if ($$.mobileView) {
        return frozenCount > 0 && col === 1 && checkable;
    } else {
        const count = frozenCount - col;
        return count < 0 ? false : count + 1;
    }
}

function frozenObserverX(box, cb) {
    return new IntersectionObserver(
        (records, observer) => {
            for (const record of records) {
                const targetInfo = record.boundingClientRect;
                const rootBoundsInfo = record.rootBounds;
                const ratio = record.intersectionRatio; // eslint-disable-line no-unused-vars
                // error buffer 1px
                if (rootBoundsInfo.left - targetInfo.left > 1) {
                    cb(true);
                } else {
                    cb(false);
                }
            }
        },
        {
            threshold: [1],
            root: box,
        }
    );
}

function TableGrid(props) {
    const ref = createRef();
    const _ = useInstance({
        mounted: false,
        // init columns width data [min, max, prev, flexRatio].
        data: [],
        // init total change-able width.
        stretchTotal: 0,
        // fix columns width to static px.
        fixedWidth: !props.flexible,
        columns: props.columns,
        style: null,
    });
    // eslint-disable-next-line no-var
    var [template, setTemplate] = useState(() => updateWidth([], setColumns()));
    useEffect(() => {
        const element = ref.current,
            root = props.root.current;
        // Chrome ≥ 133; firefox ≥ null; Safari ≥ null
        if (props.frozenCount > 0 && !CSS.supports('container-type', 'scroll-state')) {
            if (!_.observer) {
                _.observer = frozenObserverX(root, function (value) {
                    $(element).toggleClass('sticked', value);
                });
            }
            _.observer.observe(root.querySelector('.aui-table-freezer'));
        } else if (_.observer) {
            _.observer.disconnect();
        }
    }, [props.frozenCount]);
    function setColumns(columns = props.columns) {
        const oldData = _.data,
            // visible columns count.
            lOld = template?.filter((c) => Number.parseFloat(String(c).match(/(\d+)/)?.[0]) > 0).length || 0,
            lNew = columns.filter((c) => c.visible !== false).length;
        /**
         * Column count change(T/F). Or visible columns change:
         * true: new > old => reset columns.
         * false: new === old => do nothing.
         * null: new < old => fixed columns width.
         */
        let change = oldData.length !== columns.length || (lNew < lOld ? null : lNew > lOld),
            stretchTotal = 0;
        if (!props.flexible && !change) change = false;
        const data = columns.map(function (col, i) {
            const oldItem = oldData[i],
                show = col.visible !== false,
                width = col.width;
            let item = _.data[i] || []; // eslint-disable-line no-useless-assignment
            const showVal = (v) => (show ? v : i === 0 ? 'fit-content(0)' : 0);
            const percent = (v) => (String(v).endsWith('%') ? Number.parseInt(v, 10) : null);
            if (Array.isArray(width)) {
                const [min, prefer, max] = cssClamp(width, (v) => {
                    if (v == null) return undefined;
                    if (v.endsWith('px')) {
                        v = Number.parseFloat(v);
                        return Number.isNaN(v) ? undefined : v;
                    }
                    return v;
                });
                item = [min, showVal(prefer), max, percent(prefer) ?? percent(max) ?? percent(min)];
                if (show) {
                    const stretch = min > 0 ? Number.parseFloat(min) : prefer > 0 ? Number.parseFloat(prefer) : 0;
                    stretchTotal += Number.isNaN(stretch) ? error('Table column width stretch acc error.') || 0 : stretch;
                }
            } else {
                item = [width, showVal(width), undefined, percent(width)];
            }

            // change: width changed.
            if (!change && (oldItem[0] !== item[0] || oldItem[1] !== item[1])) change = true;
            return item;
        });
        _.stretchTotal = stretchTotal;
        _.data = data;
        return change;
    }
    function updateColumns(columns = props.columns) {
        _.columns = columns;
        if (_.mounted === true) setTemplate((t) => updateWidth(t, setColumns(columns)));
    }
    useEffect(() => {
        updateColumns();
    }, [props.columns]);
    useEffect(() => {
        const root = props.root.current;
        if (!props.member.grid) props.member.grid = _;
        _.element = ref.current;
        _.style = _.element.previousElementSibling;
        _.updateColumns = updateColumns;
        function onResize(rect, prevRect, overSize) {
            const _winWidth = document.documentElement.clientWidth;
            if (winWidth !== _winWidth) {
                if (overSize && _.fixedWidth && root?.clientWidth > 0) {
                    setTemplate((t) => updateWidth(t, setColumns(_.columns) || true));
                }
                winWidth = _winWidth;
            }
        }
        if (props.flexible) resizeObserver(root, onResize, { width: true, ifneed: false });
        _.mounted = true;
        return function () {
            _.mounted = false;
        };
    }, []);

    useEffect(() => {
        $(_.element).trigger('onChange');
    }, [!props.items?.length]);

    useEffect(() => {
        const { id } = props,
            hidden = [],
            num = props.checkable ? 2 : 1;
        props.columns.forEach((col, i) => {
            if (col.visible === false) {
                const scope = `#${id} .aui-table-cell[data-col="${i + num}"]`;
                hidden.push(`${scope}{visibility:hidden}`, `${scope}>*{display:none}`);
            }
        });
        replaceSheet(_.style.sheet, hidden);
    });

    function updateWidth(template, change) {
        let state;
        if (change == null) {
            state = fixColumnsWidth();
        } else {
            const length = (v) => (v == null ? null : typeof v === 'number' ? v + 'px' : v);
            const clamp = (min, prefer, max) => {
                min = length(min);
                prefer = length(prefer);
                max = length(max);
                if (prefer == null || prefer === min || prefer === max) return `minmax(${min},${max})`;
                return `clamp(${min},${prefer},${max})`;
            };
            const isHidden = (v) => v === 0 || v === 'fit-content(0)' || Number.isNaN(v);
            state = _.data.map(function ([min, prefer, max, ratio], i) {
                if (isHidden(prefer)) return prefer;
                const prev = template[i],
                    prevNum = Number.parseFloat(prev);
                if (!change && prev != null && prevNum > $$.scrollSize.max) return prev;

                if (ratio == null) {
                    ratio = (max !== min && prefer !== min && _.stretchTotal > 0 && Math.floor((min * 100) / _.stretchTotal)) || 0;
                    _.data[i][3] = ratio;
                }
                const percentMin = String(min).endsWith('%'),
                    percentMax = String(max).endsWith('%'),
                    _min = min == null ? 'auto' : percentMin ? ratio + 'fr' : Number.parseFloat(min) + 'px',
                    _prefer = prefer == null ? null : cssLength(prefer),
                    _prev = isHidden(prevNum) ? null : prev;
                let item = min == null ? null : _min;
                if (ratio > 0) {
                    let _max;
                    if (props.flexible) {
                        _max = max == null ? ratio + 'fr' : max + 'px';
                    } else {
                        _max = max == null ? (_prefer ?? (item && 'max-content') ?? _prev) : _prev == null ? max : Math.min(max, prevNum);
                    }
                    if (percentMax) {
                        item = clamp(_min, _prefer, max);
                    } else if (percentMin) {
                        item = Number.parseInt(min, 10) + 'fr';
                        if (_prefer != null) item = clamp(_prefer, null, item);
                    } else {
                        item = _min === _max ? _min : clamp(_min, _prefer, _max);
                    }
                } else if (item == null) {
                    item = _prefer == null ? clamp('min-content', null, max) : max ? clamp(_prefer, null, max) : _prefer;
                }
                template[i] = item;
                return item;
            });
            _.fixedWidth = false;
        }
        if (change) {
            /// Change logic without event.
            $(_.element).findAll('.aui-table-cell-frozen').trigger('Frozen');
        }
        const style = getTemplate(state),
            test = _.element || document.createElement('div');
        test.style.gridTemplateColumns = style;
        if (!test.style.gridTemplateColumns) {
            state = Array.from({ length: state.length }, () => 'auto');
            error(`Error while calculate columns width in table: ${props.id}!`);
        }
        return template.join('') === state.join('') ? template : state;
    }

    function fixColumnsWidth(col, width) {
        const cells = _.element.querySelectorAll('.aui-table-header-cell');
        _.fixedWidth = true;
        return arrayMap(cells, function (cell, index) {
            const visible = _.columns[index].visible !== false;
            let _width = 0;
            if (col === index) {
                _.data[col][1] = width + 'px';
                _width = width;
            } else if (visible) {
                _width = cell.getBoundingClientRect().width || 0;
            }
            _width = _width > 0 ? _width + 'px' : 0;
            template[index] = _width;
            return _width;
        });
    }

    function columnResize(col, width) {
        setTemplate(fixColumnsWidth(col, width));
        const { onColumnResize } = props;
        if (onColumnResize) {
            if (props.flexible) error('onColumnResize callback is disabled in flexible layout.');
            Promise.resolve(props.columns[col]).then((column) => onColumnResize(column, width));
        }
    }
    function getTemplate(template, fill = $$.scrollSize.max) {
        let t = template.map((t) => (t === 'auto' ? 'minmax(max-content, auto)' : t)).join(' ');
        // first checkbox column.
        if (props.checkable) t = '50px ' + t;
        // last -2 fill column.
        t += ` minmax(${fill}px, auto)`;
        // last -1 row action column.
        t += ' 0';
        return '[row-start] ' + t + ' [row-end]';
    }
    const className = ['aui-table-grid'];
    if (props.compact) className.push('aui-table-compact');
    return (
        <TableContext.Provider value={props}>
            <div className={className.join(' ')} style={{ gridTemplateColumns: getTemplate(template) }} ref={ref}>
                <TableHeader columns={props.columns} columnResize={columnResize} />
                <TableBody />
                {props.footer && <TableFooter />}
            </div>
        </TableContext.Provider>
    );
}

function TableHeader(props) {
    const { member, method, items, checkable, onCheckByItems, verifiable, onCheck } = useContext(TableContext);
    const [checked, setChecked] = useState(false);
    const [disabled, setDisabled] = useState(false);
    const _ = useInstance();
    useEffect(() => {
        if (!member.header) member.header = _;
        if (onCheck && onCheckByItems === false) warn('The onCheck callback will not trigger when onCheckByItems disabled, it may cause mistake cache data.');
    }, []);
    useEffect(() => {
        if (checkable) {
            const [checked] = getChecked();
            if (onCheckByItems !== false) checkedCallback(null, checked);
        }
    }, [items]);
    function getChecked() {
        let isAll = false,
            disabled = true,
            hasChecked = false;

        if (items?.length) {
            isAll = true;
            for (const item of items) {
                if (item.checked) {
                    hasChecked = true;
                } else {
                    isAll = false;
                }
                if (!item.disabled) disabled = false;
            }
        }

        const checked = isAll ? true : hasChecked ? 'mixed' : false;
        setChecked(checked);
        setDisabled(disabled);
        return [checked, disabled];
    }
    function checkedCallback(value, isAll) {
        if (typeof onCheck === 'function') {
            if (value == null) value = items.filter((item) => item.checked);
            onCheck(value, isAll);
        }
    }
    _.clearSort = function () {
        for (const column of props.columns) {
            if (typeof column.sortable === 'number') column.sortable = true;
        }
        _.forceUpdate();
    };
    _.checkedCallback = function (...args) {
        checkedCallback.apply(this, args);
    };
    _.trySelectAll = function () {
        const [checked] = getChecked();
        checkedCallback(null, checked);
    };
    _.selectAll = function (val) {
        if (checked === 'mixed') {
            const state = { disabled: true, all: true };
            for (const item of items) {
                if (!item.checked) {
                    state[item.disabled ? 'disabled' : 'all'] = false;
                }
                if ((state.disabled || state.all) === false) {
                    val = 'mixed';
                    break;
                }
            }
            if (state.all) val = false;
        }
        for (const item of items) {
            if (!item.disabled) item.checked = !!val;
        }
        [val] = getChecked();
        member.body.forceUpdate();
        return val;
    };
    function onSelectAllChange(checked) {
        const result = method('selectAll', checked);
        checkedCallback(null, result);
        return result;
    }
    // use INFINITY value to enable checkbox without checkAll.
    const useCheckAll = checkable === true || (typeof checkable === 'number' && checkable > 1 && Number.isFinite(checkable));
    return (
        <div className="aui-table-header" role={verifiable ? 'group' : 'rowgroup'}>
            <div className="aui-table-row aui-table-row-group" role={verifiable ? 'none' : 'row'}>
                <TableGroupCells columns={props.columns} />
            </div>
            <Row type="header" index={-1}>
                {checkable && (
                    <CellBox index={-1} role={verifiable ? 'none' : 'columnheader'}>
                        {useCheckAll && <Checkbox className="aui-table-rowchecker" checked={checked} disabled={disabled} willChange={onSelectAllChange} aria={I18N.selectAll} />}
                    </CellBox>
                )}
                {props.columns.map((column, i) => (
                    <TableHeaderCell column={column} index={i} columnResize={props.columnResize} key={'col-' + i} />
                ))}
            </Row>
        </div>
    );
}

function TableGroupCells(props) {
    const { checkable, verifiable } = useContext(TableContext);
    const [data, setData] = useState(null);
    const acc = checkable ? 1 : 0;
    useEffect(() => {
        const obj = new Map();
        let order = 1;
        for (const { group } of props.columns) {
            const i = order++;
            if (!group) continue;
            const cur = obj.get(group);
            if (cur) {
                cur[1] = i;
            } else {
                obj.set(group, [i]);
            }
        }
        setData(obj);
    }, [props.columns]);

    return arrayMap(data, ([group, range]) => {
        let [start, end] = range;
        if (!end) end = props.columns.length;
        // column-start, column-end.
        const colspan = `${start + acc}/${end + acc + 1}`;
        return (
            <div className="aui-table-cell" role={verifiable ? 'none' : 'columnheader'} tabIndex={-1} style={{ gridColumn: colspan }} key={'group-' + colspan}>
                <div className="aui-table-cell-content">{group}</div>
            </div>
        );
    });
}

const AriaSort = { 1: 'ascending', '-1': 'descending' };
function TableHeaderCell(props) {
    const ref = createRef();
    const _ = useInstance({
        $element: null,
        $parent: null,
        resizing: null,
        sorting: false,
    });
    const { id, root, doSort, method, frozenCount, verifiable } = useContext(TableContext);
    const [sortState, setSortState] = useState(props.column.sortable);
    useEffect(() => setSortState(props.column.sortable), [props.column.sortable]);
    useEffect(() => {
        const element = ref.current,
            col = props.column;
        _.$element = $(element);
        if (col.resizeable && !isFrozen(props.col, frozenCount)) {
            setResize();
        }
    }, [props.column, frozenCount]);

    function setResize() {
        _.$parent = $(root.current);
    }

    function dragStart() {
        _.resizing = _.$element.origin('offsetWidth');
    }
    // eslint-disable-next-line unicorn/consistent-function-scoping
    function dragHelper() {
        const helper = document.createElement('div');
        helper.classList.add('aui-table-header-dragger');
        return helper;
    }
    function dragStop(e, ui) {
        const { offsetWidth: cellWidth } = e.currentTarget.closest('.aui-table-header-cell');
        const start = ui.originalPosition.left,
            end = ui.position.left,
            width = Math.round(cellWidth + end - start);
        props.columnResize(props.index, Math.floor(width));
        setTimeout(() => (_.resizing = null), 20);
    }

    function getDragBoundary() {
        const { width } = props.column,
            offsetLeft = (el) => el.getBoundingClientRect().left + window.pageXOffset;
        let [minWidth] = concat(width);
        minWidth = isNumber(minWidth) ? minWidth - 0 : 80;
        const x1 = offsetLeft(_.$element.get()) + minWidth,
            // eslint-disable-next-line no-unused-vars
            x2 = 0;
        // x2 = offsetLeft(_.$parent.get()) + _.$parent.origin('offsetWidth'); // right side of table
        // [x1, y1, x2, y2], relative to .aui-table
        return [x1, 0, Number.MAX_SAFE_INTEGER, Number.MAX_SAFE_INTEGER];
    }

    function onSort(e) {
        let state = sortState;
        if (_.sorting === true) return;
        _.sorting = true;
        if (typeof state === 'number') {
            state = state * -1;
        } else {
            state = 1;
        }
        method('clearSort');
        setSortState(state);
        props.column.sortable = state;
        const result = $$.fn(doSort)({ column: props.column, state, columnIndex: props.col, status: state > 0 ? 'asc' : 'desc' });
        callbackResult(result, () => setTimeout(() => (_.sorting = false)));
    }

    function onClick(e) {
        const cell = e.currentTarget,
            target = e.target;
        if (props.column.sortable && _.resizing == null && (target === cell || $(target).closest(':focusable', cell).equal(cell))) {
            onSort();
        }
    }
    function onKeyPress(e) {
        if (e.target === e.currentTarget && eventIsKey(e, 'Space')) {
            e.preventDefault();
            if (props.column.sortable) onSort();
        }
    }

    const column = props.column,
        frozen = isFrozen(props.col, frozenCount),
        ariaSortable = !verifiable && column.sortable,
        visible = column.visible !== false,
        resizeable = column.resizeable && !frozen && !$$.mobileView && visible,
        style = {},
        cellID = id + '_' + props.col;
    if (column.stateColor) style['--state-color'] = column.stateColor;

    const className = ['aui-table-header-cell'];
    if (column.group) className.push('aui-table-group-cell');
    return (
        <Cell
            id={cellID}
            className={className}
            role={verifiable ? 'none' : 'columnheader'}
            ariaSort={(ariaSortable && AriaSort[sortState]) || null}
            ariaDescription={ariaSortable ? I18N.supportSort : null}
            col={props.col}
            row={props.row}
            tabIndex={visible && (column.headerTemplate || column.header) ? 0 : -1}
            style={style}
            childRef={ref}
            onCellClick={onClick}
            onCellKeyPress={onKeyPress}
        >
            <div className={'aui-table-header-box justify-' + (column.align || 'start')}>
                <div className="aui-table-cell-content" data-tooltip="ifneed">
                    {props.content || column.headerTemplate || column.header || ''}
                </div>
                <div className="aui-table-header-action">
                    {column.sortable && (
                        <div className="aui-table-header-sort" data-state={String(sortState)}>
                            <div className="faui-triangle-up" />
                            <div className="faui-triangle-down" />
                        </div>
                    )}
                </div>
            </div>
            {resizeable && (
                <Drag
                    axis="x"
                    cursor="col-resize"
                    coordinate={getDragBoundary}
                    helper={dragHelper}
                    helperBox=":parent(.aui-table-box)"
                    distance={3}
                    onDragStart={dragStart}
                    onDragEnd={dragStop}
                    helperOffset={{ left: -1, top: -1 }}
                >
                    <div className="aui-table-header-drag" />
                </Drag>
            )}
        </Cell>
    );
}

function TableFooter() {
    const { footer, rootData, checkable, member, items, verifiable } = useContext(TableContext);
    const _ = useInstance(),
        contents = footer(items, rootData),
        rows = items.length;
    useEffect(() => {
        if (!member.footer) member.footer = _;
    }, []);
    return (
        <div className="aui-table-footer" role={verifiable ? 'group' : 'rowgroup'}>
            <Row type="footer" index={Math.max(1, rows)}>
                {checkable && <Cell index={-1} gridColumn={[1]} />}
                {contents.map((content, i) => (
                    <Cell index={i} key={'footer-' + i}>
                        <div className="aui-table-cell-content">{content}</div>
                    </Cell>
                ))}
            </Row>
        </div>
    );
}

function TableBody() {
    const { rowTemplate: Child, items, rootData, onRowEvent, member, noneMessage, valign, rowKeyField, verifiable } = useContext(TableContext);
    const _ = useInstance();
    useEffect(() => {
        if (!member.body) member.body = _;
    }, []);
    const keys = {};
    function key(rowData, i) {
        const k = rowData[rowKeyField] || i;
        if (keys[k]) {
            error(`Duplicate row key [${k}] with item: `, rowData);
        } else {
            keys[k] = 1;
        }
        return 'row-' + k;
    }
    const className = ['aui-table-body'];
    if (valign) className.push('aui-table-v-' + valign);
    return (
        <div className={className.join(' ')} role={verifiable ? 'group' : items?.length > 0 ? 'rowgroup' : null}>
            {items?.map((rowData, i) => (
                <Child {...{ rowData, rootData, onRowEvent }} index={i} key={key(rowData, i)} />
            ))}
            {items?.length === 0 && (
                <div className="aui-table-message">
                    <div className="aui-table-message-content">
                        <div data-tooltip="ifneed">{noneMessage || I18N.noneMessage}</div>
                    </div>
                </div>
            )}
        </div>
    );
}

const allowStyle = (function () {
    const whiteList = new Set(['backgroundColor']);
    return function (obj) {
        const style = {};
        if (obj != null && typeof obj === 'object') {
            for (const rule of Object.keys(obj)) {
                if (whiteList.has(rule) || rule.startsWith('--')) {
                    style[rule] = obj[rule];
                }
            }
        }
        return style;
    };
})();

function CheckCell(props) {
    const { checkable, id, method, items } = useContext(TableContext);
    const ref = createRef();
    const single = checkable === 1,
        type = single ? 'Radio' : 'Checkbox',
        Tag = R[type],
        name = id + '-' + type;
    const _ = useInstance();
    function onChange(checked) {
        if (single) {
            checked = true;
            for (const item of items) item.checked = false;
        }
        props.item.checked = checked;
        props.onCheck(checked);
        if (single) {
            method('checkedCallback', props.item);
        } else {
            method('trySelectAll', checked, true);
            _.forceUpdate();
        }
    }
    return (
        <CellBox col={1} row={props.row}>
            <Tag
                className="aui-table-rowchecker"
                checked={props.item.checked || false}
                name={name}
                onChange={onChange}
                disabled={props.item.disabled || false}
                aria={I18N.checkbox}
                ref={ref}
            />
        </CellBox>
    );
}

function Row(props) {
    const ref = createRef();
    const { checkable, columns, id, verifiable } = useContext(TableContext);
    const [children, hasFragment] = $$.shell.flatArray(props.children, true);
    useEffect(() => {
        if (props.index === 0) {
            const count = columns.length;
            let i = 0;
            for (const cell of children) {
                i += Number(cell.props.colspan || 1);
            }
            if (count > 0 && i !== count) error(`The count of columns:${count} and rowTemplate:${i} isn't equal for table: ${id}!`);
        }
    }, [children.length, columns.length]);
    function rowAction(action) {
        if (typeof action === 'function') action = action();
        if (!action) return false;
        const isMulti = action.length > 0 || (action.type === Symbol.for('react.fragment') && action.props.children.length > 0);
        if (isMulti) {
            return (
                <ButtonGroup type="action" round align="end" tooltip={I18N.actions}>
                    {action}
                </ButtonGroup>
            );
        }
        return cloneElement(action, { round: true, text: null, tooltip: action.props.tooltip || action.props.text });
    }
    const style = allowStyle(props.style),
        row = props.index - 0 + 1;
    if (props.stateColor) style['--state-color'] = props.stateColor;
    function cellList(children) {
        let colAcc = props.checkable !== false && checkable ? 2 : 1;
        return Children.map(children, (child, i) => {
            const index = child.props.index ?? i,
                col = index + colAcc,
                args = { row, index, col },
                { key } = child;
            if (child.props.colspan) colAcc += child.props.colspan - 1;
            if (hasFragment && (!key || !/^[a-z]/i.test(key))) args.key = `cell-${row}-${col}`;
            return cloneElement(child, args);
        });
    }
    return (
        <div
            className="aui-table-row"
            role={verifiable ? 'option' : 'row'}
            aria-selected={verifiable ? true : null}
            data-row={row}
            {...(props.events || {})}
            style={style}
            ref={ref}
        >
            {checkable && props.item && <CheckCell item={props.item} row={row} onCheck={props.onCheck} />}
            {cellList(children)}
            <div className="aui-table-cell aui-table-cell-last" />
            <div className="aui-table-cell aui-table-row-action" data-cell={`${row},`} role={verifiable ? null : 'cell'}>
                {props.type !== 'header' && <div className="aui-table-row-action-box empty-hidden">{rowAction(props.action)}</div>}
            </div>
        </div>
    );
}

function Cell(props) {
    const { id, frozenCount, root, columns, checkable, verifiable } = useContext(TableContext);
    const [left, setLeft] = useState(null);
    const ref = props.childRef || createRef();
    const _ = useInstance({
        table: null,
        frozen: null,
    });
    function frozen(element, enable, refresh) {
        if (!enable || refresh) element.style.left = null;
        const $element = $(element);
        if (enable && $element.is(':visible')) {
            setTimeout(() => {
                const _left = element.style.left;
                let offset = $element.offset(_.table).left;
                if (_left === '' || _left === 'auto') offset += _.table.scrollLeft;
                offset = Number(offset.toFixed(0));
                offset = Math.max(offset, 0) + 'px';
                if (left === offset) {
                    // force update with same state.
                    element.style.left = offset;
                } else {
                    setLeft(() => offset);
                }
            }, 1);
        }
    }
    useEffect(() => {
        if (!_.table) _.table = root.current;
        const _frozen = isFrozen(props.col, frozenCount, checkable);
        frozen(ref.current, _frozen, _.frozen !== _frozen);
        _.frozen = _frozen;
    });
    useEffect(() => {
        $(ref.current).on('Frozen', (e) => frozen(e.currentTarget, true));
    }, []);
    function events() {
        const obj = {},
            click = [],
            keyPress = [];
        if (typeof props.onCellClick === 'function') click.push(props.onCellClick);
        if (typeof props.events?.onClick === 'function') click.push(props.events.onClick);
        if (click.length > 0) {
            obj.onClick = function (...args) {
                for (const handler of click) handler(...args);
            };
        }
        if (typeof props.onCellKeyPress === 'function') keyPress.push(props.onCellKeyPress);
        if (typeof props.events?.onKeyPress === 'function') keyPress.push(props.events.onKeyPress);
        if (keyPress.length > 0) {
            obj.onKeyPress = function (...args) {
                for (const handler of keyPress) handler(...args);
            };
        }
        return { ...props.events, ...obj };
    }
    let className = ['aui-table-cell'];
    const col = props.col,
        column = columns[props.index] || {},
        style = allowStyle(props.style);
    const attrs = {
        role: props.role || (verifiable ? null : 'cell'),
        tabIndex: props.tabIndex ?? -1,
        'data-col': col,
        'data-cell': props.row + ',' + col,
        'aria-sort': props.ariaSort || null,
    };
    if (props.ariaDescription) {
        attrs['aria-description'] = props.ariaDescription;
    } else {
        attrs['aria-describedby'] = props.ariaDescribedby || (verifiable && id + '_' + col) || null;
    }
    if (props.role === 'columnheader') attrs['data-zindex'] = '';
    if (props.className) className = className.concat(props.className);

    if (isFrozen(col, frozenCount, checkable)) {
        className.push('aui-table-cell-frozen');
        style.left = left;
    }
    if (props.colspan) {
        style.gridColumnEnd = 'span ' + props.colspan;
        attrs['aria-colspan'] = props.colspan;
    } else if (props.gridColumn) {
        const [start, end] = props.gridColumn;
        if (start != null) style.gridColumnStart = start;
        if (end != null) style.gridColumnEnd = end;
    }
    if (column.align) className.push('text-' + column.align);
    return (
        <div id={props.id} className={className.join(' ')} {...attrs} style={style} ref={ref} {...events()}>
            {props.children}
        </div>
    );
}

function CellBox(props) {
    const { children, ...args } = props;
    return (
        <Cell {...args}>
            <div className="aui-table-cell-content">{children}</div>
        </Cell>
    );
}

export class TableRow extends Component {
    constructor(props) {
        super(props);
        this.render = this.render.bind(this, this.RowTreat.bind(this), this.Cell);
        this.onCheck = this.onCheck.bind(this);
    }
    onCheck() {}
    RowTreat(...args) {
        return this.Row(...args);
    }
    dispatch(type, ...args) {
        const { rowData, index, onRowEvent } = this.props;
        args = [{ type: type, rowData, rowIndex: index }].concat(args || []);
        $$.fn(onRowEvent)(...args);
    }
    Row = (props) => <Row {...props} onCheck={this.onCheck} item={this.props.rowData} index={this.props.index} />;
    Cell = CellBox;
}

$$.shell.define('TableRow', TableRow);
$$.shell.define('Table', Table);
$$.shell.define('TablePart', { Row, Cell: CellBox });
