import { error } from '../../core/base/log.js';

const support = $$.sameOrigin && window.showOpenFilePicker;
let input, busy;
if (!support) {
    input = document.createElement('input');
    input.setAttribute('type', 'file');
}

/** @type {typeof $$.io.filePicker} */
export default function filePicker(accepts, multiple) {
    return new Promise(function (resolve, reject) {
        const acceptTypes = [],
            acceptList = [];
        if (accepts) {
            for (let [mime, types] of Object.entries(accepts)) {
                types = types.map((t) => (t.startsWith('.') ? '' : '.') + t.toLowerCase());
                const [description] = mime.split('/'),
                    accept = { 'Unknown/Unknown': types };
                acceptTypes.push({ description, accept });
                acceptList.push(...types);
            }
        }
        if (support) {
            if (busy) return void reject(error('Current file picking, cannot pick another!') || false);
            const args = { excludeAcceptAllOption: !!acceptList.length, multiple: !!multiple };
            if (acceptList.length) args.types = acceptTypes;
            busy = true;
            window
                .showOpenFilePicker(args)
                .then((files) => Promise.all(files.map((f) => f.getFile())))
                .catch((e) => reject(true))
                .then(resolve)
                .finally(() => (busy = false));
        } else {
            const element = input.cloneNode();
            if (acceptList.length) element.setAttribute('accept', acceptList.join(','));
            if (multiple) element.toggleAttribute('multiple', true);

            element.onchange = (e) => resolve(Array.from(e.target.files));
            element.showPicker();
        }
    });
}
