import forEach from './for-each.js';

/** @type {typeof $$.object.extendNull} */
export default function extendNull(target, ...sources) {
    for (const obj of sources) {
        if (!obj) continue;
        forEach(obj, function (k, v) {
            if (target[k] == null) target[k] = v;
        });
    }
    return target;
}
