/** @jsxImportSource @gui/aui-devops */
import { define, Widget, Types } from '../../widget/widget.js';

import '../popup/pop.js';

import style from './style.less';

const I18N = $$.I18N.buttongroup;
const PrimaryClassify = new Set(['alt', 'theme']);
const Icon = {
    ellipsis: 'faui-ellipsis-dot',
    dropdown: 'faui-caret-down',
    arrow: 'faui-angle-right-s',
};
const PopOptions = { delegate: '.trigger', ofElement: ':parent(2)', eventScope: 'parent', triggerEvent: 'click', width: ['100%', 500] };

/** @extends {Widget<typeof ButtonGroup.options>} */
@define('button-group')
export class ButtonGroup extends Widget {
    static options = {
        align: Types.Enum(['start', 'end'], 'start'),
        classify: Types.Enum(['default', 'alt', 'blank', 'theme'], 'default'),
        disabled: false,
        icon: Types.string,
        /** @private */
        nested: Types.object,
        round: false,
        text: Types.string,
        tooltip: Types.string,
        type: Types.Enum(['action', 'bald', 'button', 'plain'], 'button'),
        onClick: Types.function,
    };
    static observers = ['classify', 'disabled', 'icon', 'text', 'tooltip'];
    static styles = style;
    static ariaTarget = '.trigger';

    init() {
        const { align, nested, round, type, onClick } = this.options,
            _align = align === 'start' ? 'left' : 'right',
            isAction = type === 'action',
            positionArgs = nested || { my: `${_align} top`, at: `${_align} bottom` };
        this.state = {
            align: _align,
            combine: nested ? true : isAction || typeof onClick !== 'function',
            dropIcon: nested ? Icon.arrow : Icon.dropdown,
            isAction,
            popOptions: { ...PopOptions, ...positionArgs },
            round,
            type: isAction ? (round ? null : 'bald') : type,
        };
    }
    onToggle = (isShow) => {
        this.customState('expanded', isShow);
    };
    render() {
        const { classify, disabled, icon, text, tooltip, onClick } = this.options,
            { combine, isAction, popOptions, round, type, dropIcon } = this.state,
            _icon = this.fontIcon(isAction ? icon || Icon.ellipsis : icon),
            dropdownIcon = ['icon', this.fontIcon(dropIcon)];
        const args = { disabled, type, classify: type === 'button' ? classify : null, primary: PrimaryClassify.has(classify) },
            mainArgs = { ...args, text: isAction ? null : text, tooltip },
            triggerAria = this.arias({ expanded: false, hasPopup: true, [combine ? 'description' : 'label']: I18N.dropdown });

        return (
            <div id="group" role="group" aria-label={I18N.label} aria-disabled={disabled}>
                {combine ? (
                    <aui-button-lite {...mainArgs} className={['trigger', 'button-combine']} shrink={isAction ? 's' : null} round={round} aria={triggerAria}>
                        <slot name="icon" slot="icon">
                            <span className={_icon} />
                        </slot>
                        {!isAction && <span className={dropdownIcon} slot="icon-end" />}
                    </aui-button-lite>
                ) : (
                    <>
                        <aui-button-lite {...mainArgs} className="button-main" onClick={onClick}>
                            <slot name="icon" slot="icon">
                                <span className={_icon} />
                            </slot>
                        </aui-button-lite>
                        <hr className={args.classify} />
                        <aui-button-lite {...args} className={['trigger', 'button-dropdown']} shrink="xs" text="" aria={triggerAria}>
                            <span className={dropdownIcon} slot="icon" />
                        </aui-button-lite>
                    </>
                )}

                <aui-pop {...popOptions} onToggle={this.onToggle}>
                    <aui-overflow-menu>
                        <slot id="menu" onClick={$$.close} />
                    </aui-overflow-menu>
                </aui-pop>
            </div>
        );
    }
}
