/** @jsxImportSource @gui/aui-devops */
import { addTooltip, tooltipAttr } from '../../core/module/tooltip.js';
import { define, Widget, Types } from '../../widget/widget.js';

import swipe from '../../util/event/swipe.js';

import style from './style.less';

const I18N = $$.I18N.switch;
const ModeMap = {
    io: [String.fromCodePoint(10073), String.fromCodePoint(9711)],
    on: [I18N.on, I18N.off],
};

/** @extends {Widget<typeof Switch.options>} */
@define('switch')
export class Switch extends Widget {
    static options = {
        checked: false,
        disabled: false,
        mode: Types.Enum([null, 'io', 'on'], null),
        size: Types.Enum(['m', 's'], 'm'),
        tooltip: Types.string,
        willChange: Types.function,
        onChange: Types.function,
    };
    static observers = ['checked', 'disabled', 'tooltip'];
    static upcasts = ['size'];
    static shadow = { delegatesFocus: true, referenceTarget: 'button' };
    static formAssociated = true;
    static ariaTarget = '#button';
    static styles = style;

    init() {
        this.state = {
            checked: this.options.checked,
            dirty: false,
        };
    }

    didMount() {
        addTooltip(this.host);
        this.actionElement = this.element.querySelector('button');
        swipe(this.actionElement, 'h', (e) => this.onChange(e));
    }
    onChange = (e) => {
        const checked = !this.state.checked;
        if (this.callback('willChange', checked) !== false) {
            this.actionElement.ariaChecked = checked;
            this.setState({ checked: checked, dirty: true });
            this.callback('onChange', checked);
        }
    };
    setOption(name, value, oldValue) {
        if (name === 'checked') {
            this.setState({ checked: value });
        }
    }
    render() {
        const { mode, disabled, size, tooltip } = this.options,
            { checked } = this.state,
            [on, off] = Array.isArray(mode) ? mode : ModeMap[mode] || [];
        const arias = this.arias({ role: 'switch', roleDescription: I18N.label, ariaChecked: checked, ariaDisabled: disabled });
        return (
            <label className="switch" data-dirty={this.state.dirty}>
                <slot className="block start" name="block-start" />
                <slot className="inline start" name="inline-start" />
                <slot className="inline start" />
                <button
                    id="button"
                    className={['button', 'action', 'size-' + size]}
                    type="button"
                    disabled={disabled}
                    {...arias}
                    {...tooltipAttr(tooltip, 'label')}
                    onClick={this.onChange}
                >
                    <div className="box">
                        <span className="on" aria-hidden>
                            {on}
                        </span>
                        <span className="handle" />
                        <span className="off" aria-hidden>
                            {off}
                        </span>
                    </div>
                </button>
                <slot className="inline end" name="inline-end" />
                <slot className="block end" name="block-end" />
            </label>
        );
    }
}
