import { error } from '../../core/base/log.js';

const vKB = 1024,
    vMB = vKB * 1024,
    vGB = vMB * 1024,
    vTB = vGB * 1024;

/** @type {typeof $$.string.fileSize2Byte} */
export default function fileSize2Byte(size, unit) {
    let floatSize = Number.parseFloat(size);
    if (Number.isNaN(floatSize) || floatSize < 0) return Number.NaN;
    if (floatSize === 0) return 0;

    const Size = String(size).toUpperCase();
    if (Size.includes('B')) {
        if (Size.includes('TB')) {
            floatSize = floatSize * vTB;
        } else if (Size.includes('GB')) {
            floatSize = floatSize * vGB;
        } else if (Size.includes('MB')) {
            floatSize = floatSize * vMB;
        } else if (Size.includes('KB')) {
            floatSize = floatSize * vKB;
        }
    }

    if (!unit) return floatSize;
    switch (unit.toUpperCase()) {
        case 'TB':
            return floatSize / vTB;
        case 'GB':
            return floatSize / vGB;
        case 'MB':
            return floatSize / vMB;
        case 'KB':
            return floatSize / vKB;
        case 'B':
            return floatSize;
        default:
            error('Unknown unit:', unit);
    }
    return floatSize;
}
