import { RegUploadPlugin } from '../module/upload.plugin.js';

RegUploadPlugin('Video', (UploadButton, I18N) => {
    return class VideoSplitButton extends UploadButton {
        icon = true;
        internal = true;
        type = 'Video';
        name = I18N.videoTag;
        tooltip = [I18N.videoTag];

        menuMapping(item) {
            return { ...item, icon: this.icon };
        }
    };
});
