import { throws } from '../../core/base/log.js';

export function parseValue(value) {
    if (value == null) return throws('Nullable value cannot be hashed!');

    switch (typeof value) {
        case 'string':
            return value;
        case 'object': {
            try {
                const params = new URLSearchParams(value);
                return params.toString();
            } catch (e) {
                return throws('Value cannot be hashed!', value, e);
            }
        }
        default:
            return String(value);
    }
}
