/** @jsxImportSource @gui/aui-devops */
import { define, Widget, Types, inherit } from '../../widget/widget.js';

import { isHour12 as dateIsHour12 } from '../../util/date/formats.js';
import { hour12to24, hour24to12 } from '../../util/date/hour-convert.js';
import objectEmpty from '../../util/object/empty.js';

import '../tabbutton/tabbutton.js';

import { LoopList } from './loop-list.js';

import style from './timepart.less';

const { options, observers, forwardOptions } = inherit(LoopList, ['disabled', 'size']);
const I18N = $$.I18N.timepicker;
const ViewInfo = {
    hour: {
        getter: 'getHours',
        setter: 'setHours',
        max: 24,
    },
    minute: {
        getter: 'getMinutes',
        setter: 'setMinutes',
        max: 60,
    },
    second: {
        getter: 'getSeconds',
        setter: 'setSeconds',
        max: 60,
    },
    millisecond: {
        getter: 'getMilliseconds',
        setter: 'setMilliseconds',
        max: 1000,
    },
};
const ViewList = Object.keys(ViewInfo);
const HeaderSplitter = ':';

/** @extends {Widget<typeof TimePart.options>} */
@define('time-part')
export class TimePart extends Widget {
    static options = {
        ...options,
        precision: Types.Enum(ViewList, 'minute'),
        hour12: Types.Enum([true, false, 'auto'], 'auto'),
        value: Types.time,
        refDate: Types.date,
        preciseGap: 1,
        startTime: Types.time,
        endTime: Types.time,
        mobileView: false,
        onChange: Types.function,
    };
    static observers = [...observers, 'value', 'preciseGap', 'mobileView'];
    static upcasts = ['mobileView'];
    static styles = style;

    create() {
        this.hostProto = { getValue: this.getValue };
    }
    init() {
        const { hour12 } = this.options;
        this.state = {
            hour12: hour12 === 'auto' ? dateIsHour12() : hour12,
            ttList: [I18N.am, I18N.pm],
            ttIndex: 0,
            time: null,
            headers: [],
            views: {
                hour: { max: null, step: null },
                // And m, s, ms ...
            },
        };
        this.updateBySource();
    }
    updateBySource() {
        const { precision, value, preciseGap } = this.options,
            { hour12, ttList, headers, views } = this.state,
            time = new Time(value);
        this.state.time = new Time(0); // create empty time.
        objectEmpty(views);
        headers.splice(0);
        for (const view of ViewList) {
            const accuracy = view === precision,
                info = ViewInfo[view];
            let val = time[info.getter](),
                min = 0,
                max = info.max,
                defaultValue = null;
            this.state.time[info.setter](val);
            if (view === 'hour' && hour12) {
                min = 1;
                max = 12;
                defaultValue = 12;
                const [v, tt] = hour24to12(val);
                val = v;
                this.state.ttIndex = ttList.indexOf(tt);
            }
            const header = I18N['header-' + view], // e.g. header-minute
                ariaLabel = I18N['aria-' + view]; // e.g. aria-second
            views[view] = { value: value == null ? defaultValue : val, min, max, step: accuracy ? preciseGap : 1, aria: ariaLabel };

            if (headers.length) headers.push(<span>{HeaderSplitter}</span>);
            headers.push(<div>{header}</div>);

            if (accuracy) break;
        }
    }
    setOption(name, value, oldValue) {
        switch (name) {
            case 'value':
            case 'preciseGap':
            case 'startTime':
            case 'endTime':
                this.updateBySource();
                return true;
        }
    }
    getValue = () => {
        const { refDate } = this.options,
            { time } = this.state;
        const t = time && new Time(this.state.time);
        if (refDate) t.setDate(refDate);
        return t;
    };

    triggerCallback = () => {
        const value = this.getValue();
        this.callback('onChange', value);
    };
    #callbackAsync = $$.debounce(this.triggerCallback);
    onTabChange = (i) => {
        const { time, ttList } = this.state,
            [hour] = hour24to12(time.getHours()),
            fullHour = hour12to24(hour, ttList[i]);
        time.setHours(fullHour);
        this.state.ttIndex = i;
        this.shadowRoot.getElementById('hour-mode').setAttribute('active', i);
        this.triggerCallback();
    };
    #dataChangeProcessor = {
        hour: (v) => {
            const { hour12, ttList, ttIndex } = this.state;
            return hour12 ? hour12to24(v, ttList[ttIndex]) : v;
        },
    };
    onDataChange(view) {
        const { setter } = ViewInfo[view],
            processor = this.#dataChangeProcessor[view] || Number;
        return (value) => {
            const { time } = this.state;
            time[setter](processor(Number(value)));
            this.#callbackAsync();
        };
    }
    loopList = ([view, data]) => {
        if (!data) return null;
        const args = forwardOptions(this.options);
        return <aui-loop-list id={view} {...data} {...args} onChange={this.onDataChange(view)} />;
    };
    render() {
        const { disabled, mobileView } = this.options,
            { hour12, ttList, ttIndex, headers, views } = this.state,
            _views = Object.entries(views);

        return (
            <>
                <div className="tt">
                    {hour12 ? (
                        <aui-tabbutton id="hour-mode" items={ttList} disabled={disabled} active={ttIndex} orient={mobileView ? 'v' : 'h'} onChange={this.onTabChange} />
                    ) : (
                        <div />
                    )}
                </div>
                <div className="header" aria-hidden={true}>
                    {headers}
                </div>
                <div className="time-part" aria-description={I18N.ariaList}>
                    {_views.map(this.loopList)}
                </div>
            </>
        );
    }
}
