import { isObject } from '../type/types.js';

import forEach from './for-each.js';

const { isArray } = Array;

/** @type {typeof $$.object.merge} */
export default function merge(target, ...sources) {
    let checkProp = true;
    if (typeof sources.at(-1) === 'boolean') checkProp = sources.pop();

    function doMerge(k, v) {
        const current = target[k];
        if (isObject(v)) {
            target[k] = merge({}, isObject(current) ? current : {}, v);
        } else if (isArray(v)) {
            target[k] = (isArray(current) ? current : []).concat(v);
        } else if (checkProp || v !== undefined) {
            target[k] = v;
        }
    }
    for (const source of sources) {
        forEach(source, doMerge, checkProp);
    }
    return target;
}
