const MonthDays = [31, 28, 31, 30, 31, 30, 31, 31, 30, 31, 30, 31];

/** @type {typeof $$.date.maxMonthDays} */
export default function maxMonthDays(month, year) {
    if (month == null || Number.isNaN(month)) {
        return 31;
    } else if (year) {
        const d = new Date(new Date(year, month + 1, 1) - 1);
        return d.getDate();
    } else {
        return MonthDays[month];
    }
}
