const ValidationData = new Map();

export function setValidation(info, context) {
    const { name, hostQuery, changeEvent, actionQuery, sensitiveEvent, multiple, shell, verify } = info;
    const data = {
        // context,
        name,
        hostQuery,
        changeEvent,
        actionQuery: actionQuery || context?.ariaTarget || ':tabbable', ///
        sensitiveEvent: sensitiveEvent || null,
        multiple: multiple || false,
        shell: shell || (/^[A-Z]$/.test(name[0]) ? 'CustomElement' : /^[a-z]$/.test(name[0]) && 'Element') || null,
        verify: verify || context?.verify || null, ///
    };
    ValidationData.set(name, data);
    return data;
}

export function getValidation() {
    return ValidationData;
}
