import { log } from '../base/log.js';
import { onload, idleLoad } from '../base/onload.js';
import $ from '../element/index.js';

onload(function () {
    const [performanceNavigationTiming] = performance.getEntriesByType('navigation');
    if (performanceNavigationTiming) {
        const { type, redirectCount } = performanceNavigationTiming;
        if (redirectCount === 0 && type === 'back_forward') {
            idleLoad(function () {
                log('Duplicate tab, reset state for all form elements.');
                $('input,textarea,select').reset();
            });
        }
    }
});

function stopBubble(e) {
    e.stopPropagation();
}
function preventDefault(e) {
    e.preventDefault();
}

// global mouse event cache;
onload(function () {
    const { touchable } = $$.browser,
        { $body } = $;
    const add = (name, callback) => $body.on(name, { capture: true }, callback);
    add(touchable ? 'touchmove' : 'pointermove', (e) => ($$.event.mouseMove = e));

    const clickCallbackQueue = [];
    add(touchable ? 'touchstart' : 'pointerdown', function (e) {
        $$.event.mouseUp = null;
        $$.event.mouseDown = e;
        $$.event.mouseMove = e;
    });
    add(touchable ? 'touchend' : 'pointerup', function (e) {
        $$.event.mouseDown = null;
        $$.event.mouseUp = e;
        $$.event.mouseMove = e;
        while (clickCallbackQueue.length > 0) {
            clickCallbackQueue.shift()();
        }
    });
    $$.syntheticClickCallback = function (fn) {
        if ($$.event.mouseDown) {
            clickCallbackQueue.push(fn);
        } else {
            fn();
        }
    };

    // prevent event bubbling.
    $body.on('click', '.aui-scope-click', stopBubble);
    $body.on('mouseenter', '.aui-scope-mouseenter', stopBubble);
    $body.on('click', 'a[disabled]', preventDefault);
});
