import fixFloat from '../number/fix-float.js';
import objectEmpty from '../object/empty.js';

import { touchable, touchEvent, touchList, distance } from './_touch.js';

/** @type {typeof $$.event.touchZoom} */
export default function touchZoom(box, start, move, end) {
    const args = {};
    if (!touchable) return args;
    const callback = (v, ...param) => $$.fn(v)(...param);
    function angle(e1, e2) {
        const x = e1.pageX - e2.pageX,
            y = e1.pageY - e2.pageY;
        return fixFloat((Math.atan2(y, x) * 180) / Math.PI);
    }
    const data = touchEvent(box, 'touchZoomEvent', {
        touchstart: function (e) {
            const touches = touchList(e);
            if (touches.length > 1) {
                const [a, b] = touches,
                    { offsetLeft, offsetTop } = box;
                data.enable = true;
                data.start = touches;
                objectEmpty(args);
                callback(start, e, [fixFloat((a.pageX + b.pageX) / 2 - offsetLeft), fixFloat((a.pageY + b.pageY) / 2 - offsetTop)]);
            }
        },
        touchmove: (e) => {
            const touches = touchList(e);
            if (touches.length > 1 && data.enable) {
                e.preventDefault();
                const { start } = data,
                    [a, b] = touches,
                    scale = distance(a, b) / distance(start[0], start[1]),
                    rotate = angle(a, b) - angle(start[0], start[1]);
                data.scale = fixFloat(scale);
                data.rotate = fixFloat(rotate);
                if (data.scale !== 1 && Math.abs(data.rotate) > 2) callback(move, e, data.scale, data.rotate);
            }
        },
        touchend: function (e) {
            if (data.enable) callback(end, e);
            data.enable = false;
        },
        touchcancel: function (e) {
            if (data.enable) callback(end, e);
            data.enable = false;
        },
    });
    return args;
}
