import { I18N } from '../../core/base/i18n.js';

import clamp from '../number/clamp.js';

// 12AM=0, 12pm=12.

/** @type {typeof $$.date.hour12to24} */
export function hour12to24(val, tt) {
    const { pm } = I18N.calendar;
    let hour;
    val = Math.max(0, val - 0);
    if (tt === pm) {
        hour = val < 12 ? val + 12 : 12;
    } else if (val === 12) {
        hour = 0;
    } else {
        hour = val;
    }
    return clamp(0, hour, 23);
}

/** @type {typeof $$.date.hour24to12} */
export function hour24to12(val) {
    const { am, pm } = I18N.calendar;
    if (val < 12) {
        return [val === 0 ? 12 : val, am];
    } else {
        return [val > 12 ? val - 12 : val, pm];
    }
}
