export const isSucceedStatus = (status) => status >= 200 && status < 300;

export const useAbort = function (abort) {
    return function attachAbort(promise) {
        promise.abort = abort;
        const originalThen = promise.then;
        const originalFinally = promise.finally;

        // eslint-disable-next-line unicorn/no-thenable
        promise.then = function (...args) {
            return attachAbort(originalThen.apply(this, args));
        };
        promise.finally = function (...args) {
            return attachAbort(originalFinally.apply(this, args));
        };
        return promise;
    };
};

export const parseHeaders = function (args) {
    const { useTimezone } = args || {};
    const headers = {};
    if (useTimezone) {
        const field = typeof useTimezone === 'string' ? useTimezone : 'Ua-Timezone',
            region = new Intl.DateTimeFormat(),
            { timeZone } = region.resolvedOptions();
        headers[field] = timeZone;
    }
    return headers;
};
