export const EventTypeMap = (function () {
    const mouseEvents = ['mousedown', 'mouseup', 'mousemove', 'mouseenter', 'mouseleave', 'mouseover', 'mouseout'],
        pointerEvents = ['pointerdown', 'pointerup', 'pointermove', 'pointerover', 'pointerout', 'pointerenter', 'pointerleave'];
    const mapping = new Map([
        [PointerEvent, [...mouseEvents, ...pointerEvents, 'click', 'dblclick', 'contextmenu', 'auxclick', 'pointerrawupdate']],
        [WheelEvent, ['wheel']],
        [KeyboardEvent, ['keydown', 'keypress', 'keyup']],
        [InputEvent, ['input', 'beforeinput']],
        [SubmitEvent, ['submit']],
        [FocusEvent, ['focus', 'blur']],
        [UIEvent, ['resize']],
        [Event, ['change', 'reset', 'invalid', 'load', 'error', 'abort', 'scroll', 'visibilitychange', 'fullscreenchange', 'readystatechange']],
        [DragEvent, ['drag', 'dragstart', 'dragend', 'dragenter', 'dragover', 'dragleave', 'drop']],
        [ProgressEvent, ['progress', 'timeout', 'loadstart', 'loadend']],
        [HashChangeEvent, ['hashchange']],
        [PopStateEvent, ['popstate']],
        [BeforeUnloadEvent, ['beforeunload']],
        [CompositionEvent, ['compositionstart', 'compositionupdate', 'compositionend']],
        [AnimationEvent, ['animationstart', 'animationend', 'animationiteration']],
        [TransitionEvent, ['transitionstart', 'transitionend']],
    ]);
    if (window.TouchEvent) mapping.set(TouchEvent, ['touchstart', 'touchmove', 'touchend', 'touchcancel']);
    return mapping;
})();

export const EventName2Type = (function (data) {
    for (const [EventProto, events] of EventTypeMap) {
        for (const event of events) {
            data[event] = EventProto;
        }
    }
    return data;
})({});
