export function _filter(target, test, callback, unMatchCB) {
    const map = {
        Function: (k, v) => test(k, v),
        RegExp: (k, v) => k.match(test),
        Array: (k) => test.includes(k),
        Set: (k) => test.has(k),
    };
    const fn = $$.fn(map[$$.getClassBuiltIn(test)]);

    if (target) {
        for (const [k, v] of Object.entries(target)) {
            $$.fn(fn(k, v) ? callback : unMatchCB)(k, v);
        }
    }
}
