import React, { PureComponent } from 'react';

import { concat } from '../../util/array/concat.js';
import findDOMNode from '../../util/shell/find-dom-node.jsx';
import { createElement } from '../../util/shell/index.js';
import { nonEmptyObject } from '../../util/type/types.js';

import { ErrorBoundary } from '../render-case.js';

import { error } from './log.js';

const ErrorReport = ErrorBoundary(createElement);
const isStaleCommunicate = (component, element) => !!component && (!component._loaded || element?.isConnected === false);
const reportStaleCommunicate = (id) => error(`Target component "#${id}" is stale / destroyed. Maybe the componentDidMount / componentWillUnmount lifecycle id overridden.`);

const EventBus = new Map();
let uuid = 0;
export class Component extends PureComponent {
    /** temp API for debug. */
    static findDOMNode = findDOMNode;

    #loaded = false;
    #originName = null;

    constructor(props) {
        super(props);
        this.#originName = this.constructor.name;
        Object.defineProperty(this, 'uuid', { enumerable: true, value: uuid++ });
        this.componentCreate();
    }
    get _loaded() {
        return this.#loaded;
    }
    #communicate = (...args) => {
        if (!this.#loaded) return reportStaleCommunicate(this.props.id);
        try {
            this.componentReceive(...args);
        } catch (e) {
            error(e);
        }
    };
    #addCommunicate(id) {
        if (!id) return;
        const { element } = this,
            exists = EventBus.get(id);
        if (exists) {
            const { component, el } = exists,
                activeElement = component?.element || el;
            if (isStaleCommunicate(component, activeElement)) {
                EventBus.delete(id);
            } else if ((element && el && element !== el) || (component && component !== this)) {
                return error(`Duplicate id "${id}" found in component '${this.#originName}'. ID must be unique across all loaded components.`);
            }
        }
        EventBus.set(id, { receiver: this.#communicate, el: element, component: this });
    }
    #removeCommunicate(id) {
        const exists = EventBus.get(id);
        if (!exists || exists.component === this) EventBus.delete(id);
    }

    //#region Private Lifecycle
    componentDidMount(triggerInit) {
        if (!this.element) {
            try {
                this.element = findDOMNode(this);
            } catch (e) {
                return error(this.#originName, e);
            }
        }
        Object.defineProperty(this, 'element', { enumerable: true, configurable: false, writable: false });
        this.#addCommunicate(this.props.id);
        this.#loaded = true;
        if (triggerInit !== false) {
            this.componentDidRender();
            this.componentInit();
        }
    }
    componentWillUnmount() {
        this.#removeCommunicate(this.props.id);
        this.#loaded = false;
        this.componentDestroy();
    }
    componentDidUpdate(prevProps, prevState) {
        if (prevProps.id !== this.props.id) {
            this.#removeCommunicate(prevProps.id);
            this.#addCommunicate(this.props.id);
        }
        this.componentDidRender();
        this.componentUpdate(prevProps, prevState);
    }
    componentDidCatch(error, info) {
        this.render = ErrorReport(error.stack);
        this.forceUpdate();
    }
    //#endregion

    //#region Public Methods
    /** Used to bind this to a function field. */
    bind(...args) {
        const arg = args[0],
            list = args.length > 1 ? args : typeof arg === 'string' ? arg.split(',') : arg;
        if (Array.isArray(list)) {
            for (const fn of list) {
                if (typeof this[fn] === 'function') {
                    this[fn] = this[fn].bind(this);
                } else {
                    error(`Binding failed, the "${fn}" is not a function!`);
                }
            }
        }
    }

    /**
     * Used for one-way communication to the target component.
     * @param {string|Array<string>} target Target component `id` (or `id list array`). When an array, target components responds by array order.
     */
    dispatch(target, ...args) {
        const targets = concat(target);
        if (!targets.length || !targets.join('')) return error('Empty target id.');
        for (const id of targets) {
            const { receiver, component, el } = EventBus.get(id) || {};
            if (receiver) {
                if (isStaleCommunicate(component, component?.element || el)) {
                    EventBus.delete(id);
                    reportStaleCommunicate(id);
                } else {
                    receiver(...args);
                }
            } else {
                error(`The target component "#${id}" is not exist!`);
            }
        }
    }
    //#endregion

    /**
     * @abstract Used to receive communication from the source component.
     */
    componentReceive() {}

    /**
     * @abstract The interface is invoked when constructor is constructed.
     * It is often used to define state, initialize bind, initialize component related parameters, etc.
     */
    componentCreate() {}

    /**
     * @abstract The interface is called at componentDidMount.
     * It is often used to request initial data.
     */
    componentInit() {}

    /**
     * @abstract This interface is called when the component is updated.
     * It is often used to request updates of data.
     */
    componentUpdate(prevProps, prevState) {}

    /**
     * @abstract This interface is called before componentInit / componentUpdate.
     * It is often used to modify / get dom elements after rendered.
     */
    componentDidRender() {}

    /**
     * @abstract The interface is called at the componentWillUnmount construct.
     * Implementation of the associated logic used to destroy the component.
     */
    componentDestroy() {}
}

export class UIComponent extends Component {
    /** set widget name(jQuery UI widget). */
    widgetName = null;
    /**
     * The hide callback name for widget(Container widget).
     * rerender(destroy mode) && change props.status.show=false when the widget hidden.
     */
    hideControl = null;
    tooltip = true;
    useAria = true;
    ref = React.createRef();
    constructor(props) {
        super(props);
        this.method = this.method.bind(this);
        if (this.props.destroy === true) {
            // destroy mode render.
            this.render = this.destroyRender;
        }
    }
    /** hideControl function. */
    #hideControlFn() {
        this.props.status.show = false;
        if (this.props.destroy === true) this.forceUpdate();
        const hideControl = this.props[this.hideControl];
        if (typeof hideControl === 'function') hideControl();
    }
    /** @abstract */
    widgetArgs() {}
    /** get args for widget when create && update. */
    getWidgetArgs() {
        const hideControl = {};
        if (this.hideControl) hideControl[this.hideControl] = this.#hideControlFn.bind(this);
        return { ...this.props, ...hideControl, ...this.widgetArgs() };
    }
    componentDidMount() {
        this.element = this.ref.current;
        super.componentDidMount(false);
        if (!this.element) return error(this.widgetName, 'Failed to find widget root element.', this);
        this.$element = jQuery(this.element);
        this.componentDidRender();
        this.componentInit();
        const { id, slot, tooltip, widgetRef, aria } = this.props;
        if (typeof id === 'string') this.element.id = id;
        if (slot) this.element.setAttribute('slot', slot);
        if (this.tooltip !== false && typeof tooltip === 'string') {
            this.$element.attr({ 'data-tooltip': 'true', 'aria-label': tooltip });
        }
        if (this.widgetName) {
            this.widget = this.$element[this.widgetName].bind(this.$element);
            this.widget(this.getWidgetArgs());
            if (typeof widgetRef === 'function') widgetRef(this.widget);
        }
        if (this.useAria) this.$element.attr($$.arias(aria));
    }
    componentDidUpdate(prevProps, prevState) {
        const args = {};
        super.componentDidUpdate(prevProps, prevState);
        if (this.widget) {
            for (const arg in this.props) {
                if (arg !== 'children' && this.props[arg] !== prevProps[arg]) {
                    if (arg === 'tooltip') this.$element.attr({ 'aria-label': this.props.tooltip });
                    args[arg] = this.props[arg];
                }
            }
            if (nonEmptyObject(args)) this.widget(args);
        }
    }
    componentWillUnmount() {
        super.componentWillUnmount();
        $$.fn(this.widget, this)('destroy');
    }
    /** public method function, for calling widget method in react. */
    method(...args) {
        if (this.widget) {
            if (args.length > 0) {
                return this.widget.apply(this.$element, args);
            } else {
                return this.widget(this.getWidgetArgs());
            }
        }
    }
    render() {
        return <div ref={this.ref}>{this.props.children}</div>;
    }
    /** @abstract */
    destroyRender() {
        return false;
    }
}

R.Component = Component;
