/** @jsxImportSource @gui/aui-devops */
import { onloading } from '../../core/base/onload.js';
import $ from '../../core/element/index.js';
import { define, Widget, Types } from '../../widget/widget.js';

import style from './style.less';

const visibleStack = {
    val: [],
    add(v) {
        this.delete(v);
        this.val.push(v);
    },
    delete(v) {
        const i = this.val.indexOf(v);
        if (i >= 0) this.val.splice(i, 1);
    },
    toggle(force, v) {
        return force ? this.add(v) : this.delete(v);
    },
    get(i) {
        return this.val.at(i);
    },
};

const isVisible = (view) => {
    if (!view?.length) return true;
    const { mobileView, mobileEnv } = $$;
    return view.some((v) => {
        switch (v) {
            case 'desktop':
                return !mobileEnv;
            case 'mobile':
                return mobileView && mobileEnv > 0;
            case 'phone':
                return mobileView && mobileEnv > 1;
        }
        return false;
    });
};

/** @extends {Widget<typeof Backdrop.options>} */
@define('backdrop')
export class Backdrop extends Widget {
    static options = {
        view: Types.EnumList(['desktop', 'mobile', 'phone']),
        global: Types.Enum([true, false, '_similar'], false),
        colorScheme: Types.Enum(['normal', 'light', 'dark']),
        onClick: Types.function,
    };
    static styles = style;

    #target = null;
    #shouldPreventScroll = $$.mobileView && $$.browser.os.name === 'ios' ? [] : null;

    init() {
        const { view, global, colorScheme } = this.options;
        this.state = { view, global, colorScheme };
    }
    didMount() {
        queueMicrotask(this.initEvent);
    }
    initEvent = () => {
        const { view, global } = this.state,
            { $host } = this,
            selector = 'dialog,[role="dialog"],nav',
            target = $host.parent().is(selector) || $host.siblings(selector).get();
        this.#target = target;
        if (view) {
            this.addGlobalEventListener('ViewChange', () => this.#onViewChange());
        }
        if (global) {
            if (target) {
                target.addEventListener('toggle', this.#onToggle);
            } else {
                this.console.error('backdrop', `Can't find related dialog box.`);
            }
        }
    };
    #onViewChange = () => {
        const visible = isVisible(this.state.view);
        this.element.toggleAttribute('hidden', !visible);
    };
    #onToggle = (e) => {
        const isShow = $.is(e.target, ':visible');
        visibleStack.toggle(isShow, this);

        const scroll = this.#shouldPreventScroll;
        if (scroll != null) {
            if (isShow) {
                if (!scroll.length) this.#preventScroll();
            } else if (!visibleStack.get()) {
                this.#resumeScroll();
            }
        }
    };
    #preventScroll() {
        const data = { box: null, posY: 0, scrollY: 0, maxScroll: 0 };
        const onTouchStart = (e) => {
            const box = $(e.target).parents(':scrollable', this.#target, { matchSelf: true }).toArray();
            if (box.length) {
                data.box = box;
                data.posX = e.pageX;
                data.posY = e.pageY;
                data.scrollY = box.map((el) => el.scrollTop);
                data.maxScroll = box.map((el) => el.scrollHeight - el.clientHeight);
            }
        };
        const onTouchMove = (e) => {
            let stuck = true;
            if (data.box?.length) {
                stuck = data.box.every(function (el, index) {
                    if (['html', 'body'].includes(el.localName)) return true;
                    const scrollTop = el.scrollTop,
                        maxScroll = data.maxScroll[index],
                        distanceX = e.pageX - data.posX,
                        distanceY = e.pageY - data.posY,
                        angle = Math.abs(Math.atan2(distanceX, distanceY) * 180) / Math.PI;
                    return Math.abs(angle - 90) > 45 && (maxScroll <= 0 || (distanceY > 0 ? scrollTop === 0 : scrollTop + 1 >= maxScroll));
                });
            }
            if (stuck) e.preventDefault();
        };
        const onCancel = (e) => (data.box = null);

        const listen = (t, cb) => $.$root.on(t, { passive: false }, cb);
        this.#shouldPreventScroll = [listen('touchstart', onTouchStart), listen('touchmove', onTouchMove), listen('touchend touchcancel', onCancel)];
    }
    #resumeScroll() {
        while (this.#shouldPreventScroll.length) {
            this.#shouldPreventScroll.pop().abort();
        }
    }
    tryFocus = () => {
        const $active = $.$activeElement();
        if (!$(this.#target).contains($active, true)) {
            this.#target.focus();
        }
    };
    onClick = (e) => {
        this.#target?.focus({ focusVisible: false });
        this.callback('onClick', e);
    };
    render() {
        const { view, global, colorScheme } = this.state,
            visible = isVisible(view),
            className = ['backdrop', colorScheme && 'color-scheme-' + colorScheme];
        return <div className={className} data-global={global || null} hidden={!visible} tabIndex={-1} onClick={this.onClick} />;
    }
}

onloading(function () {
    window.addEventListener('focus', function (e) {
        const win = e.target;
        if (win.top === win) {
            const current = visibleStack.get(-1);
            current?.tryFocus();
        }
    });
});
