import React, { PureComponent, createRef } from 'react';
import { createPortal } from 'react-dom';

import { error } from '../../core/base/log.js';
import $ from '../../core/element/index.js';
import { WR } from '../../widget/widget.jsx';

import { Button } from '../button/button.jsx';

export class ModalWidget extends PureComponent {
    name = 'Dialog';
    ref = createRef();
    state = { isShow: false };

    show(...args) {
        this.ref.current?.show(...args);
    }
    hide(...args) {
        this.ref.current?.hide(...args);
    }
    loading(...args) {
        this.ref.current?.loading(...args);
    }

    componentDidMount() {
        const { element } = this.ref.current,
            $dialog = $(element).find('dialog', { crossShadow: true });
        $dialog.on('toggle', (e) => this.#onToggle(e.currentTarget.open));
        if (this.props.buttons?.length) error(this.name, 'buttons property is deprecated, use slot="buttons" instead.', element);
    }
    #onToggle = (isShow) => {
        this.setState({ isShow });
    };
    #renderLegacyButtons(buttons = []) {
        const onClick = (name, callback) => (e) => $$.fn(callback)(e, name);
        return buttons.map((item) => {
            const name = item.name || item.text;
            return <Button {...item} onClick={onClick(name, item.onClick)} name={name} slot="buttons" key={name} />;
        });
    }
    children() {
        return false;
    }

    render() {
        const { props, state } = this,
            { header, buttons, destroy, children, ...args } = props,
            Tag = WR[this.name],
            renderChildren = !destroy || (props.status?.show ?? state.isShow);

        const Content = (
            <Tag {...args} ref={this.ref}>
                {this.children()}
                {header && <h3 slot="header">{header}</h3>}
                {renderChildren && children}
                {this.#renderLegacyButtons(buttons)}
            </Tag>
        );
        return args.global === false ? Content : createPortal(Content, $.$body.get());
    }
}
