/** @jsxImportSource @gui/aui-devops */
import { define, Widget, Types } from '../widget.js';

import { keyName } from '../../util/event/key-name.js';

import style from './input.less';

function matchPattern(val, pattern) {
    const v = val.match(pattern);
    let result = '';
    if (v?.length) result = pattern.global ? v.join('') : v[0];
    return result;
}

/** @extends {Widget<typeof Input.options>} */
@define('input-lite')
export class Input extends Widget {
    static options = {
        type: 'text',
        name: Types.string,
        value: Types.string,
        disabled: false,
        readonly: false,
        required: false,
        placeholder: Types.string,
        pattern: Types.string,
        block: false,
        min: Types.number,
        max: Types.number,
        step: Types.number,
        maxLength: Types.number,
        align: Types.Enum(['start', 'center', 'end']),
        onChange: Types.function,
        onInput: Types.function,
        onEnter: Types.function,
    };
    static shadow = { delegatesFocus: true, referenceTarget: 'input' };
    static observers = ['value', 'disabled', 'readonly'];
    static upcasts = ['block'];
    static formAssociated = true;
    static ariaTarget = '#input';
    static styles = style;

    #locked = false;
    #lastKey = null;
    create() {
        this.hostProto = { getValue: () => this.getValue(this.element.querySelector('input')), setValue: this.setValue };
    }
    didMount() {
        const action = this.element.querySelector(':scope>input');
        action.dispatchEvent(new InputEvent('input', { bubbles: true, composed: true }));
    }
    getValue = (input) => {
        let val = input.value;
        const { type, pattern } = this.options;
        if (type === 'number') val = matchPattern(val, /\d+(\.\d+)?/g);
        if (pattern) val = matchPattern(val, new RegExp(pattern, 'g'));
        return val;
    };
    setValue = (v) => {
        this._setOptions({ value: v });
    };
    onChange = (e) => {
        const { value } = e.target,
            { onChange } = this.options;
        if (onChange) {
            onChange(value, e);
        } else {
            this._setOption('value', value);
        }
    };
    onClick = (e) => {
        e.stopPropagation();
    };
    onKeyDown = (e) => {
        const name = keyName(e);
        this.#lastKey = name;
        if (name === 'Enter' || name === 'Space' || name.startsWith('Arrow')) {
            e.stopPropagation();
        }
    };
    onKeyUp = (e) => {
        const name = keyName(e, true);
        if (name === this.#lastKey) {
            // eslint-disable-next-line unicorn/no-lonely-if
            if (name === 'Enter') {
                this.callback('onEnter', e.target.value, e);
            }
        }
        this.#lastKey = null;
    };
    onInput = (e) => {
        const val = this.getValue(e.target);
        if (e.target.value !== val) e.target.value = val;
        if (!this.#locked) this.callback('onInput', val, e);
    };
    onCompositionStart = (e) => {
        this.#locked = true;
    };
    onCompositionEnd = (e) => {
        this.#locked = false;
        this.onInput(e);
    };
    render() {
        const { type, name, value, disabled, readonly, required, placeholder, pattern, maxLength, align } = this.options,
            args = { type, name, value, disabled, readonly, required, placeholder, pattern, maxLength, ...this.arias({ disabled, readonly }) };
        if (type === 'number') {
            const { min, max, step } = this.options;
            Object.assign(args, { type: 'text', role: 'spinbutton', 'aria-valuemin': min, 'aria-valuemax': max, step });
        }
        Object.assign(args, { style: { 'text-align': align } });
        return (
            <label>
                <slot className="block start" name="block-start" />
                <slot className="inline start" name="inline-start" />
                <input
                    id="input"
                    className="action aui-input-target"
                    {...args}
                    autoComplete="off"
                    onChange={this.onChange}
                    onClick={this.onClick}
                    onKeyDown={this.onKeyDown}
                    onKeyUp={this.onKeyUp}
                    onInput={this.onInput}
                    onCompositionStart={this.onCompositionStart}
                    onCompositionEnd={this.onCompositionEnd}
                />
                <slot className="inline end" name="inline-end" />
                <slot className="block end" name="block-end" />
            </label>
        );
    }
}
