import { getValue } from '../value-path.js';

/** @type {typeof $$.array.sort} */
export default function sort(array, isASC = true, valuePath = null, parser = true) {
    if (!Array.isArray(array)) return;
    array.sort(function (a, b) {
        const x = getValue(a, valuePath, parser),
            y = getValue(b, valuePath, parser),
            compare = isASC ? x > y : x < y;
        return x == y ? 0 : compare ? 1 : -1; // eslint-disable-line eqeqeq
    });
    return array;
}
