import { RegUploadPlugin } from '../module/upload.plugin.js';

RegUploadPlugin('Attachment', (UploadButton, I18N) => {
    return class FileSplitButton extends UploadButton {
        icon = true;
        internal = true;
        type = 'Attachment';
        name = I18N.attachment;
        tooltip = [I18N.attachment];

        menuMapping(item) {
            return { ...item };
        }
    };
});
