import { error } from '../../core/base/log.js';

import fileByte2Size from '../../util/string/file-byte2size.js';
import fileSize2Byte from '../../util/string/file-size2byte.js';
import format from '../../util/string/format.js';
import hash from '../../util/string/hash-fnv1a.js';

export const defaultFileMaxSize = '1 GB';

export const callbackFallback = (file) => Object.assign(file, { isSucceed: true });

export function fileId(fileEntity) {
    if (fileEntity.fileId) return fileEntity.fileId;
    const prefix = 'ufh', // u: uploader; f: file; h: hash;
        { fileName, size, file } = fileEntity,
        params = new URLSearchParams({ fileName, size, lastModified: file.lastModified, type: file.type }),
        hash32 = hash(params.toString());
    return `${prefix}-${hash32}`;
}

export function byte2Size(value) {
    if (value == null) return null;
    return fileByte2Size(fileSize2Byte(value), 2, ' ');
}

export function maxLengthByMultiple(value) {
    if (!value) return 1;
    return Number.isInteger(value) ? value : Infinity;
}

const I18N = (v) => $$.I18N.uploader[v];

export const fileTypeSplitter = ', ';
/** @param {string[]} types @param {boolean} [useEntry] */
export function formatFileTypes(types, useEntry) {
    if (Array.isArray(types) && types.length > 0) {
        const content = types.join(fileTypeSplitter).toUpperCase();
        return useEntry ? format(I18N('supportTypes'), content) : content;
    }
    return null;
}

export function formatMaxSize(size, entry) {
    return format(entry || I18N('maxFileDisplay'), byte2Size(size));
}

/** @returns {File|Blob|Record<'fileId'|(string & {}), any>|null} */
const pickFile = (data) => {
    if (!data) return null;
    const checkValid = (value) => {
        const t = $$.getClassBuiltIn(value);
        if (t === 'File' || t === 'Blob') return [true, t];
        if (t === 'Object' && value?.fileId) return [true, t];
        return [false, t];
    };
    const [valid, t] = checkValid(data);
    if (valid) return data;
    if (t === 'FormData') {
        for (const value of data.values()) {
            if (checkValid(value)[0]) return value;
        }
    }
    return null;
};
const extByName = (name) => {
    if (name) {
        const ext = name.split('.').at(-1);
        if (ext) return ext.toLowerCase();
    }
    return null;
};
export function FileEntity(data) {
    const rawFile = pickFile(data) || pickFile(data.file);
    const getField = (name) => {
        const value = typeof data.get === 'function' ? data.get(name) : data[name];
        return value ?? rawFile?.[name] ?? null;
    };
    const name = getField('name'),
        size = getField('size'),
        fileId = getField('fileId');
    const result = {
        fileId,
        isSucceed: getField('isSucceed') ?? (fileId ? true : null),
        url: getField('url'),
        status: getField('status'),
        file: rawFile,
        fileExtension: getField('fileExtension') ?? extByName(name),
        fileName: getField('fileName') ?? name,
        fileSize: getField('fileSize') ?? byte2Size(size),
        message: getField('message'),
        progress: getField('progress'),
        size: getField('size') ?? size,
    };
    Object.assign(this, result);
    return result;
}

/** @param {File|object} file @param {Array<string>} fileTypes */
export function checkFileType(file, fileTypes) {
    if (!fileTypes?.length) return true;

    let { name, fileExtension } = file;
    if (!fileExtension && name?.includes('.')) fileExtension = name.split('.').at(-1);
    if (!fileExtension) return false;

    const ext = (t) => t.trim().toLowerCase().replace(/^\./, ''),
        extension = ext(fileExtension);
    return fileTypes.some((type) => {
        const t = type && ext(type);
        return t && t === extension;
    });
}

/** @param {File|object} file @param {number|string} maxSize @param {string} [entry]  */
export function checkFileSize(file, maxSize, entry) {
    const max = fileSize2Byte(maxSize),
        { size } = file,
        valid = !max || max < 1 || size < max || size === max;
    if (valid || !entry) return valid;
    return format(entry, byte2Size(max));
}

export function findFile(files, fileEntity, matchFilter = () => true) {
    const { fileId } = fileEntity,
        matches = [];
    for (let i = 0; i < files.length; i++) {
        const file = files[i];
        if (fileId != null && file.fileId === fileId) return i;
        if (file.fileName === fileEntity.fileName && matchFilter(file)) matches.push(i);
    }
    const { length } = matches;
    if (length === 1) return matches[0];
    if (!length) return null;
    error(`Multiple files matches "${fileEntity.fileName}". The data may be incorrect.`);
    return matches.at(-1) ?? null;
}

export class DeleteService {
    #files = [];
    #doDelete = null;
    #onDelete = null;
    #loading;

    constructor({ loading }) {
        this.#loading = loading || (() => null);
    }
    init(args) {
        if (args.doDelete) this.#doDelete = args.doDelete;
        if (args.onDelete) this.#onDelete = args.onDelete;
        return this;
    }
    exec = (files, fileEntity, errorMessage) => {
        this.#files = files || [];
        if (!fileEntity.fileId) return this.onDeleteFile(fileEntity);
        return this.doDeleteFile(fileEntity, errorMessage);
    };
    #fileMatch(file) {
        return file.fileId ? (other) => file.fileId === other.fileId : (other) => file.fileName === other.fileName;
    }
    filter = (file, files) => {
        const list = files || this.#files || [],
            match = this.#fileMatch(file);
        return list.filter((f) => !match(f));
    };

    onDeleteFile(file) {
        const files = this.filter(file);
        $$.fn(this.#onDelete)({ isSucceed: true, file, files });
        return Promise.resolve(files);
    }
    doDeleteFile(file, errorMessage) {
        const doDelete = this.#doDelete || callbackFallback;
        const deleteFailed = (e) => {
            const msg = e.message || errorMessage;
            error('Delete file failed.', msg);
            file.isSucceed = false;
            file.message = msg;
            return [...this.#files];
        };

        this.#loading(true);
        return Promise.try(doDelete, file)
            .then((result) => {
                const data = { ...file, ...result };
                return data.isSucceed === false ? deleteFailed(data) : this.onDeleteFile(file);
            }, deleteFailed)
            .finally(() => this.#loading(false));
    }
}
