/** @jsxImportSource @gui/aui-devops */
// cSpell:ignore stavepop staveecho abselem staffsep sysstaffsep
/* global ABCJS */
import $ from '../../../core/element/index.js';
import { define, Widget, Types } from '../../../widget/widget.js';

import ioBase64Url from '../../../util/io/base64-url.js';
import numberInt from '../../../util/number/int.js';
import formatString from '../../../util/string/format.js';
import { isEvent as typeIsEvent } from '../../../util/type/types.js';

import '../../popup/pop.js';

const I18N = $$.I18N.music;
const legerTopList = ["b'", "a'", "g'", "f'", "e'", "d'", "c'", 'b', 'a', 'g'],
    trebleList = ['f', 'e', 'd', 'c', 'B', 'A', 'G', 'F', 'E', 'D'],
    legerBottomList = ['C', 'B,'],
    bassList = ['A,', 'G,', 'F,', 'E,', 'D,', 'C,', 'B,,', 'A,,', 'G,,', 'F,,'];

/** @extends {Widget<typeof MusicStavepop.options>} */
@define('music-stavepop')
export class MusicStavepop extends Widget {
    static options = {
        symbol: Types.string,
        denominator: Types.number,
        notationClick: Types.function,
    };
    static shadow = false;
    static observers = [];
    init() {
        this.state = {
            symbol: '',
            denominator: '',
        };
    }
    initPop = (pop) => {
        pop.setOptions({
            triggerEvent: 'hover:0',
            delegate: '.pop-icon',
            eventScope: ':parent(2)',
            enableLongTouch: true,
            mobileView: false,
            modalable: false,
        });
    };
    notationClick = (e) => {
        const item = e.currentTarget;
        this.callback('notationClick', { note: item.dataset.note, symbol: this.symbol, denominator: this.denominator });
    };
    willShow = ({ ofElement }) => {
        const element = typeIsEvent(ofElement) ? ofElement.currentTarget : ofElement;
        const { symbol, denominator } = element.dataset;
        this.symbol = symbol;
        this.denominator = denominator;
    };
    renderStavePopupList(className, arr, icon) {
        return (
            <ul className={className}>
                {/* eslint-disable-next-line aui/jsx-list-identifier */}
                {icon && ABCJS.parseIcon(icon)}
                {arr.map((item) => (
                    <li data-note={item} onClick={this.notationClick} />
                ))}
            </ul>
        );
    }
    render() {
        return (
            <aui-pop ref={this.ref(this.initPop)} willShow={this.willShow}>
                <div className="notestave-popup">
                    {this.renderStavePopupList('leger-line-top', legerTopList)}
                    {this.renderStavePopupList(['icon', 'treble'], trebleList, 'Treble')}
                    {this.renderStavePopupList('leger-line-bottom', legerBottomList)}
                    {this.renderStavePopupList(['icon', 'bass'], bassList, 'Bass')}
                </div>
            </aui-pop>
        );
    }
}

function initSoundData(args, audioContext) {
    if (args?.data) {
        const instrument = Object.keys(args.cache)[0],
            cache = args.cache[instrument];
        for (const [k, v] of Object.entries(args.data)) {
            cache[k] = new Promise(function (resolve, reject) {
                const url = ioBase64Url(v),
                    info = { instrument, name: k, status: 'loaded' };
                fetch(url)
                    .then((res) => res.arrayBuffer())
                    .then((buffer) => {
                        const onLoad = (audioBuffer) => resolve({ ...info, audioBuffer });
                        audioContext.decodeAudioData(buffer, onLoad, reject);
                    });
            });
        }
        delete args.data;
    }
}

/** @extends {Widget<typeof MusicStaveEcho.options>} */
@define('music-staveecho')
export class MusicStaveEcho extends Widget {
    static options = {
        uid: Types.number,
        midiDownload: false,
        onSelectionChange: Types.function,
        staveKeyDown: Types.function,
    };
    static shadow = false;
    static observers = ['midiDownload'];
    defaultHeaders = new Map([
        ['X', 1],
        ['T', I18N.defaultTitle],
        ['M', '4/4'],
        ['L', '1/' + '4'],
        ['K', 'C'],
        ['V', 'V1 clef=treble'],
        ['Q', null],
    ]);
    base = '[V:V1][|]';
    splitter = '`\n';
    method = {
        getTextAreaValue: this.getTextAreaValue,
        setEditorValue: this.setEditorValue,
        updateVirtualEditor: this.updateVirtualEditor,
        setRange: this.setRange,
        setValue: this.setValue,
        getValue: this.getValue,
        highlightNearby: this.highlightNearby,
    };
    didMount() {
        this.textarea = this.host.querySelector('.textarea');
        this.warningArea = this.host.querySelector('.warning');
        this.editor = this.host.querySelector('.editor');
        this.midiArea = this.host.querySelector('.midi');
        this.stave = this.host.querySelector('.staveecho');
        this.audioContext = new AudioContext();
        if (window.ABCJS) {
            const args = {
                paper_id: this.stave,
                generate_warnings: this.options.showWarning,
                warnings_id: this.options.showWarning ? this.warningArea : undefined,
                synth: {
                    el: this.midiArea,
                    options: {
                        displayPlay: true,
                        displayRestart: true,
                        audioContext: this.audioContext,
                    },
                },
                indicate_changed: true,
                abcjsParams: {
                    generateDownload: false,
                    add_classes: true,
                    responsive: 'resize',
                    paddingtop: 5,
                    paddingbottom: 10,
                    clickListener: this.onSelectionChange,
                    selectTypes: true,
                },
            };
            this.abc_editor = new ABCJS.Editor(new ABCJS.EditArea(this.textarea), args);
            initSoundData(ABCJS['__sound'], this.audioContext);
        } else {
            return this.console.error('Get ABCjs library failed!');
        }
        for (const item of this.host.querySelectorAll('.abcjs-inline-audio button')) {
            item.setAttribute('data-tooltip', 'false');
        }
    }
    onSelectionChange = (args) => {
        const headLength = this.getHeaderLength(),
            range = [args.startChar - headLength, args.endChar - headLength];
        $$.fn(this.options.onSelectionChange)({
            type: args.el_type || args.type,
            elemType: args.abselem?.type,
            headerLength: headLength,
            range: range,
            value: this.editor.value,
        });
    };
    /**
     * ABC Directive Fields
     * @description %%staffsep space between lines.
     * @description %%sysstaffsep space between grand stave two lines.
     */
    initBaseNote() {
        const fields = ['%%staffsep 100', '%%sysstaffsep 100'];
        for (const [k, v] of this.defaultHeaders) {
            if (v != null) fields.push(k + ':' + v);
        }
        fields.push(this.splitter);
        return fields.join('\n') + this.base;
    }
    getHeaderLength() {
        return this.getTextAreaValue().split(this.splitter)[0].length + this.splitter.length;
    }
    getTextAreaValue() {
        return this.textarea.value;
    }
    setEditorValue({ k, v }) {
        const val = this.textarea.value,
            reg = new RegExp(k + ':.*\n');
        let [header] = val.split(this.splitter);
        if (v) {
            if (v.slice(-1) !== '\n') v += '\n';
            const str = k + ':' + v;
            header = reg.test(header) ? header.replace(reg, str) : header + str;
        } else {
            header = header.replace(reg, ''); // delete
        }
        this.setValue({ val: header, body: true });
    }
    setValue({ val, body }) {
        const cur = this.textarea.value;
        if (body === true) {
            // update header only
            val = [val, cur.split(this.splitter)[1]].join(this.splitter);
        } else if (body) {
            val = [typeof val === 'string' ? val : cur.split(this.splitter)[0], body].join(this.splitter);
        }
        this.editor.textContent = val.split(this.splitter)[1];
        this.textarea.textContent = val;
        $(this.textarea).trigger('change');
    }
    updateVirtualEditor(val) {
        this.editor.textContent = val;
        const old = this.textarea.value;
        val = old.split(this.splitter)[0] + this.splitter + val;
        if (val === old) return;
        this.textarea.textContent = val;
        this.abc_editor.parseABC();
        this.abc_editor.modelChanged();
    }
    setRange(args) {
        setTimeout(() => {
            const _args = args.range.length > 1 ? args.range.slice(0, 2) : args.range[0];
            this.textarea.setSelectionRange(..._args);
            $(this.textarea).trigger('mousedown', false);
            this.stave.focus({ preventScroll: true });
        }, args.delay || 0);
    }
    highlightNearby(param) {
        const element = this.getSelectedElement(param),
            type = '';
        if (element) {
            const e = new MouseEvent('mousedown', { bubbles: true, composed: true, button: 0 });
            element.dispatchEvent(e);
            $(element).trigger('mouseup');
            this.stave.focus({ preventScroll: true });
        }
        $$.fn(param.callback)({ type: type, mode: element ? 1 : 0 });
    }
    getSelectedElement(param) {
        const all = this.getAllElement(),
            selectedIndex = all.findIndex((item) => item.classList.contains('abcjs-note_selected'));
        let ele;
        if (param.toLast) {
            if (selectedIndex < all.length - 1) {
                ele = all.at(-1);
            }
        } else {
            const direction = param.operate ?? param.direction,
                isDelete = param.operate != null;
            if (isDelete) this.updateVirtualEditor(param.selection);
            const currentAll = this.getAllElement();
            ele = currentAll[direction > 0 ? (isDelete ? selectedIndex : selectedIndex + 1) : selectedIndex - 1];
        }
        return ele;
    }
    getAllElement() {
        const allEle = Array.from(this.stave.querySelectorAll('g'));
        return allEle.filter((item) => {
            const cls = item.classList;
            return cls.contains('abcjs-note') || cls.contains('abcjs-rest') || cls.contains('abcjs-bar');
        });
    }
    staveKeyDown = (e) => {
        this.callback('staveKeyDown', e);
    };
    getValue(title) {
        const maxWidth = 650, // max width for A4.
            val = this.getTextAreaValue();
        const setOrRemove = (el, attr, condition, value) => (condition ? el.setAttribute(attr, value) : el.removeAttribute(attr));
        let svg = this.stave.querySelector('svg'),
            data = svg.getAttribute('viewBox');
        // viewBox: [x,y,width,height].
        data = data.split(data.indexOf(',') > 0 ? ',' : ' ');
        let width = Math.ceil(numberInt(data[2])),
            height = Math.ceil(numberInt(data[3]));
        if (width > maxWidth) {
            height = Math.round((height * maxWidth) / width);
            width = maxWidth;
        }
        width = width > 0 ? width : maxWidth;
        height = height > 0 ? height : 230;
        svg = svg.cloneNode(true);
        svg.querySelector('title')?.remove();
        svg.removeAttribute('style');
        const selected = svg.querySelector('.abcjs-note_selected');
        if (selected) {
            selected.removeAttribute('fill');
            selected.classList.remove('abcjs-note_selected');
        }
        svg.removeAttribute('data-music');
        setOrRemove(svg, 'aria-label', title, formatString(I18N.titleFormat, title));
        svg.setAttribute('width', width);
        svg.setAttribute('height', height);
        return <div>{svg}</div>;
    }
    render() {
        return (
            <>
                <textarea className="textarea" hidden readOnly>
                    {this.initBaseNote()}
                </textarea>
                <textarea className="editor" readOnly disabled data-tooltip={true} data-disabled={false} aria-label={I18N.editorTitle}>
                    {this.base}
                </textarea>
                {this.options.showWarning && <div className="warning"></div>}
                <div className="midi"></div>
                {this.options.midiDownload && <div className="download"></div>}
                <div className="stave">
                    <div className="staveecho" tabIndex={0} onKeyDown={this.staveKeyDown}></div>
                </div>
            </>
        );
    }
}
