// src/instance-map.ts
function get(key) {
    return key == null ? undefined : key._reactInternals;
}

// src/fiber-flags.ts
const NoFlags = 0;
const Placement = 2;
const Hydrating = 4096;

// src/work-flags.ts
const HostRoot = 3;
const HostComponent = 5;
const HostText = 6;
const HostHoistable = 26;
const HostSingleton = 27;

const Errors = {
    Unmount: 'Unable to find node on an unmounted component.',
    Internal: 'React internal error.',
};

// src/fiber.ts
function findCurrentHostFiber(parent) {
    const currentParent = findCurrentFiberUsingSlowPath(parent);
    return currentParent == null ? null : findCurrentHostFiberImpl(currentParent);
}
function findCurrentHostFiberImpl(node) {
    const tag = node.tag;
    if ([HostComponent, HostHoistable, HostSingleton, HostText].includes(tag)) {
        return node;
    }
    let child = node.child;
    while (child !== null) {
        const match = findCurrentHostFiberImpl(child);
        if (match !== null) {
            return match;
        }
        child = child.sibling;
    }
    return null;
}
function loopFind(fiber, alternate) {
    let a = fiber,
        b = alternate;
    while (true) {
        const parentA = a.return;
        if (parentA === null) {
            break;
        }
        const parentB = parentA.alternate;
        if (parentB === null) {
            const nextParent = parentA.return;
            if (nextParent !== null) {
                a = b = nextParent;
                continue;
            }
            break;
        }
        if (parentA.child === parentB.child) {
            let child = parentA.child;
            while (child) {
                if (child === a) {
                    assertIsMounted(parentA);
                    return fiber;
                }
                if (child === b) {
                    assertIsMounted(parentA);
                    return alternate;
                }
                child = child.sibling;
            }
            throw new Error(Errors.Unmount);
        }
        if (a.return === b.return) {
            let didFindChild = false,
                child = parentA.child;
            while (child) {
                if (child === a) {
                    didFindChild = true;
                    a = parentA;
                    b = parentB;
                    break;
                }
                if (child === b) {
                    didFindChild = true;
                    b = parentA;
                    a = parentB;
                    break;
                }
                child = child.sibling;
            }
            if (!didFindChild) {
                child = parentB.child;
                while (child) {
                    if (child === a) {
                        didFindChild = true;
                        a = parentB;
                        b = parentA;
                        break;
                    }
                    if (child === b) {
                        didFindChild = true;
                        b = parentB;
                        a = parentA;
                        break;
                    }
                    child = child.sibling;
                }
                if (!didFindChild) {
                    throw new Error(Errors.Internal); // Child was not found in either parent set.
                }
            }
        } else {
            a = parentA;
            b = parentB;
        }
        if (a.alternate !== b) {
            throw new Error(Errors.Internal); // Return fibers should always be each others' alternates.
        }
    }
    return a;
}

function findCurrentFiberUsingSlowPath(fiber) {
    const alternate = fiber.alternate;
    if (!alternate) {
        const nearestMounted = getNearestMountedFiber(fiber);
        if (nearestMounted === null) {
            throw new Error(Errors.Unmount);
        }
        if (nearestMounted !== fiber) {
            return null;
        }
        return fiber;
    }

    const fiberNode = loopFind(fiber, alternate);
    if (fiberNode.tag !== HostRoot) {
        throw new Error(Errors.Unmount);
    }
    if (fiberNode.stateNode.current === fiberNode) {
        return fiber;
    }
    return alternate;
}
function getNearestMountedFiber(fiber) {
    let node = fiber,
        nearestMounted = fiber;
    if (fiber.alternate) {
        while (node.return) {
            node = node.return;
        }
    } else {
        let nextNode = node;
        do {
            node = nextNode;
            if ((node.flags & (Placement | Hydrating)) !== NoFlags) {
                nearestMounted = node.return;
            }
            nextNode = node.return;
        } while (nextNode);
    }
    if (node.tag === HostRoot) {
        return nearestMounted;
    }
    return null;
}
function assertIsMounted(fiber) {
    if (getNearestMountedFiber(fiber) !== fiber) {
        throw new Error(Errors.Unmount);
    }
}

// src/index.ts
export default function findDOMNode(component) {
    if (component === null) return null;
    const fiber = get(component);
    if (fiber === undefined) {
        if (typeof (component == null ? undefined : component.render) === 'function') {
            throw new TypeError(Errors.Unmount);
        } else {
            const keys = Object.keys(component).join(',');
            throw new Error(`Argument appears to not be a ReactComponent. Keys: ${keys}`);
        }
    }
    const hostFiber = findCurrentHostFiber(fiber);
    if (hostFiber === null) {
        return null;
    }
    return hostFiber.stateNode;
}
