import React from 'react';

import { WR } from '../../widget/widget.jsx';

import { concat } from '../../util/array/concat.js';

export const NavPanel = $$.shell.wrapComponent(function (props) {
    const { useNavigate, useHistory } = $$.fn($$.useRouter)() || {};
    let navigate, history;
    try {
        navigate = $$.fn(useNavigate)();
        history = $$.fn(useHistory)(); // compat with 5.x
    } catch (e) {
        $$.fn();
    }

    const _redirect = navigate || history?.push;

    function onChange(args, e) {
        const cb = props.onChange,
            url = typeof cb === 'function' ? cb(...arguments) : args.url;
        if (typeof url === 'boolean') return url;
        if (url) {
            if (!_redirect || Array.isArray(url)) {
                const [_url, target, windowFeatures] = concat(url);
                if (e.ctrlKey) {
                    window.open(_url, target, windowFeatures);
                    return target === '_self';
                }
                location.href = _url;
                return false;
            } else if (!/^#[a-z]/i.test(url)) {
                // hashRouter: #/xxx
                e.preventDefault();
                _redirect(url);
            }
        }
        return url;
    }
    const { Navpanel } = WR,
        slots = ['header', 'footer'];
    const [headerChild, footerChild] = $$.shell.flatArray(props.children, (n, i) => ({ slot: slots[i] }));
    return (
        <Navpanel {...props} onChange={onChange}>
            {headerChild}
            {footerChild}
        </Navpanel>
    );
});

function Group({ children }) {
    function onToggle(e) {}
    return (
        <div className="aui-navpanel-groups" role="group">
            <aui-backdrop view="mobile" global="_similar" onClick={onToggle} />
            {children}
        </div>
    );
}

NavPanel._Group = Group;
$$.shell.define('NavPanel', NavPanel);
