/** @jsxImportSource @gui/aui-devops */
import { define, Widget, Types } from '../../widget/widget.js';

import loop from '../../util/array/loop.js';

import style from './group.less';

const maxCount = 5;

/** @extends {Widget<typeof AvatarGroup.options>} */
@define('avatar-group')
export class AvatarGroup extends Widget {
    static options = {
        size: Types.Enum(['xs', 's', 'm'], 's'),
        max: maxCount,
    };
    static styles = style;
    static upcasts = ['size'];
    static downstreamContext = ['overwrite', ['avatar', 'profile'], ['size']];

    init() {
        this.state = {
            count: 0,
        };
    }
    onSlotChange = () => {
        this.setState({ count: this.host.children.length });
    };
    render() {
        const { max } = this.options,
            { count } = this.state;
        const popHeight = [, , 400]; // eslint-disable-line no-sparse-arrays
        return (
            <>
                {loop(max, (i) => (
                    <slot className="outer" name={i} />
                ))}
                <aui-button-lite id="more" hidden={count <= max} shrink="xs" round>
                    <span slot="text">+{count - max}</span>
                </aui-button-lite>
                <aui-pop height={popHeight} triggerEvent="click" eventScope="parent" delegate="#more">
                    <slot id="popup-body" data-from={max} onSlotChange={this.onSlotChange} />
                </aui-pop>
            </>
        );
    }
}
