import $ from '../../core/element/index.js';

import objectEmpty from '../object/empty.js';

import { touchable, touchEvent, touchList } from './_touch.js';
import pointerValid from './pointer-valid.js';

let currentTimestamp = null;

/** @type {typeof $$.event.touch} */
export default function touch(element, selector, callback, args) {
    if (!touchable || typeof callback !== 'function') return false;
    const { aborts, hold, bubbles, ..._options } = args || {},
        options = { ..._options, selector, key: 'touchEvent', aborts };
    const data = touchEvent(element, options, {
        touchstart: function (e) {
            const touches = touchList(e);
            if (touches.length === 1) {
                const touch = touches[0];
                data.id = touch.identifier;
                data.pageX = touch.pageX;
                data.pageY = touch.pageY;
                if (bubbles === false) e.stopPropagation();
                if (hold) {
                    data.timer = setTimeout(function () {
                        data.longPress = true;
                        // Filter long press event to fired only once.
                        if (currentTimestamp !== e.timeStamp && pointerValid(data)) {
                            currentTimestamp = e.timeStamp;
                            // Due to fired only once, so remove delegateTarget to enable the event for every listeners.
                            e.delegateTarget = null;
                            callback(e, true);
                            data.longPressFired = true;
                        }
                        setTimeout(() => (currentTimestamp = null), 20);
                    }, 500);
                }
            }
        },
        touchmove: (e) => {
            if (data.longPressFired) {
                const touches = touchList(e),
                    touch = touches[0];
                let valid = false;
                if (touches.length === 1 && touch.identifier === data.id) {
                    valid = pointerValid(data, touch);
                }
                if (!valid) callback(e, false);
            }
        },
        touchend: function (e) {
            const touches = touchList(e),
                touch = touches[0];
            clearTimeout(data.timer);
            if (data.longPress) {
                e.preventDefault();
            } else if (touches.length === 1 && touch.identifier === data.id) {
                // eslint-disable-next-line unicorn/no-lonely-if
                if (pointerValid(data, touch, 2) && (hold || !$.is(e.currentTarget, ':disable'))) callback(e, false);
            }
            objectEmpty(data, ['selector']);
        },
        touchcancel: function (e) {
            clearTimeout(data.timer);
            objectEmpty(data, ['selector']);
        },
    });
    return true;
}
