import { warn, error } from '../core/base/log.js';
import $ from '../core/element/index.js';
/** @import { SelectorExtendsKeywords, SelectorExtendsParent } from "./widget-types.d.ts" */

/** @see {@link SelectorExtendsKeywords} */
const keywords = new Set(['host', 'shadow', 'parent', 'body', 'root', 'document', 'window']);
/** @see {@link SelectorExtendsParent} */
const parentReg = /^:parent\(([\w\-\#\.]+)\)/;

function isValidSelector(selector) {
    try {
        document.querySelector(selector);
        return true;
    } catch (e) {
        error(e.message);
        return false;
    }
}

/** @returns {boolean|[parentQuery:string|null, restQuery:string]} */
export function verifySelector(query) {
    if (!query || typeof query !== 'string') return false;
    if (keywords.has(query)) return true;

    // convert :scope to :parent(0)
    const matchParent = query.startsWith(':scope') ? [':scope', '0'] : query.match(parentReg);
    if (matchParent) {
        const [parent, parentQuery] = matchParent,
            rests = query.replace(parent, '').trim();
        if (!rests) return [parentQuery];
        if (isValidSelector(rests)) return [parentQuery, rests];
    } else if (isValidSelector(query)) {
        return [null, query];
    }
    return false;
}

/** @param {string} query @param {Element} host  */
function parseParent(query, host) {
    if (!query) return host;

    if (/^\d+$/.test(query)) {
        /** @example :parent(2) */
        let power = Number(query),
            el = host;
        while (power > 0) {
            el = $(el).parent().get();
            if (!el) return null;
            power--;
        }
        return el;
    } else {
        /** @example :parent(.box) */
        return $(host).closest(query).get();
    }
}

/** @param {string} query @param {Element} host @param {Element} baseOn  */
export function parseSelector(query, host, baseOn) {
    const result = verifySelector(query);
    if (result === true) {
        if (query === 'host') return host;
        if (query === 'shadow') return host.shadowRoot || warn('Current element is not a shadow host: ', host) || null;
        if (query === 'parent') return host.parentNode;
        if (query === 'body') return $.$body.get();
        if (query === 'root') return $.$root.get();
        if (query === 'document') return host.ownerDocument;
        if (query === 'window') return host.ownerDocument.defaultView;
    } else if (result) {
        const [parentQuery, restQuery] = result;
        // global find.
        if (parentQuery == null) return $(restQuery).get();

        const current = parseParent(parentQuery, baseOn || host);
        if (!current) return null;
        if (!restQuery) return current;
        return $(current).find(restQuery, { crossShadow: true, crossSlot: true, directChildren: true }).get();
    }
    return null;
}
