import eventOrigin from '../event/origin.js';
import stringTrim from '../string/trim.js';

/** @type {typeof $$.type.isDeferred} */
export function isDeferred(value) {
    if (!value) return false;
    return value instanceof Promise || value?.constructor?.name === 'Promise';
}

/** @type {typeof $$.type.isObject} */
export const isObject = (function (proto) {
    return function isObject(obj) {
        if (!obj) return false;
        return $$.getClassBuiltIn(obj) === 'Object' && Object.getPrototypeOf(obj).constructor === proto;
    };
})(new Object().constructor);

/** @type {typeof $$.type.emptyObject} */
export function emptyObject(obj, fuzzing) {
    try {
        const valid = fuzzing ? !!obj : isObject(obj);
        return valid && Reflect.ownKeys(obj).length === 0;
    } catch (e) {
        return false;
    }
}

/** @type {typeof $$.type.nonEmptyObject} */
export function nonEmptyObject(obj) {
    return isObject(obj) && !emptyObject(obj, true);
}

/** @type {typeof $$.type.isClass} */
export function isClass(value) {
    if (!value || typeof value !== 'function') return false;
    try {
        value();
        return false;
    } catch (err) {
        if (!err?.message) return false;
        const msg = err.message.toLowerCase(),
            words = ['class', 'constructor', 'invoke', 'new'];
        // Expected message: `Class constructor XXX cannot be invoked without 'new'`
        return words.every((w) => msg.includes(w));
    }
}

/** @type {typeof $$.type.isPrimitive} */
export function isPrimitive(value, type) {
    const t = type || typeof value;
    return t === 'string' || t === 'number' || t === 'bigint' || t === 'boolean';
}

/** @type {typeof $$.type.isDate} */
export function isDate(date, ignoreInvalid) {
    // eslint-disable-next-line unicorn/prefer-number-properties
    return date instanceof Date && (ignoreInvalid || !isNaN(date));
}

/** @type {typeof $$.type.isNumber} */
export function isNumber(value) {
    return typeof value === 'number' || (typeof value === 'string' && !Number.isNaN(value - Number.parseFloat(value)));
}

/** @type {typeof $$.type.isEmpty} */
export function isEmpty(value, stringTrim = true) {
    if (value == null) return true;
    if (typeof value === 'string') return isEmptyString(value, stringTrim);
    if (Array.isArray(value)) return !value.length;
    return emptyObject(value);
}

/** @type {typeof $$.type.isEmptyString} */
export function isEmptyString(str, trim) {
    if (str == null) return true;
    if (trim) str = stringTrim(str);
    // eslint-disable-next-line eqeqeq
    return str == '';
}

/** @type {typeof $$.type.isContent} */
export function isContent(value) {
    const t = typeof value;
    return t === 'string' || t === 'number' || isElement(value);
}

/** @type {typeof $$.type.isElement} */
export function isElement(value, allowNodeTypes) {
    if (value == null || typeof value !== 'object') return false;
    if (value instanceof window.Element) return true;
    const t = value.nodeType,
        doc = t === Node.DOCUMENT_NODE ? value : value.ownerDocument,
        win = doc?.defaultView;
    if (!win) return false;
    if (value instanceof win.Element) return true;
    if (allowNodeTypes && allowNodeTypes.includes(t) && value instanceof win.Node) return true;
    return t === Node.ELEMENT_NODE && /^(HTML|SVG|Math)[a-zA-Z]{0,15}Element$/.test(value.constructor?.name || '');
}

/** @type {typeof $$.type.isHTMLElement} */
export function isHTMLElement(value) {
    if (value == null || typeof value !== 'object' || value.nodeType !== Node.ELEMENT_NODE) return false;
    if (value instanceof window.HTMLElement) return true;
    return /^HTML[a-zA-Z]{0,15}Element$/.test(value.constructor?.name || '');
}

/** @type {typeof $$.type.isCustomElement} */
export function isCustomElement(value, registry = window.customElements) {
    const name = value?.localName;
    if (!name || typeof name !== 'string') return false;
    if (!registry?.get) return name.includes('-');
    return !!registry.get(name);
}

/** @type {typeof $$.type.isEvent} */
export function isEvent(e) {
    if (!e) return false;
    e = eventOrigin(e);
    return e instanceof Event ? e : false;
}
