import { percentValue } from '../number/percent.js';

import { isSucceedStatus, parseHeaders, useAbort } from './utils.js';

function xhrRequest(method, url, data, args) {
    const { credentials, headers, timeout, useTimezone, onProgress } = args || {},
        _headers = { ...headers, ...parseHeaders({ useTimezone }) },
        { promise, resolve, reject } = Promise.withResolvers();
    const xhr = new XMLHttpRequest(),
        attachAbort = useAbort(() => xhr.abort());
    xhr.open(method, url);

    for (const [key, value] of Object.entries(_headers)) {
        xhr.setRequestHeader(key, value);
    }
    xhr.timeout = timeout > 1 ? timeout : 0;
    xhr.withCredentials = credentials === 'include';
    if (typeof onProgress === 'function') {
        xhr.upload.onprogress = (e) => {
            const value = e.lengthComputable ? percentValue(e.loaded / e.total) : 'indeterminate';
            onProgress(value);
        };
    }

    let body = null;
    if (data) {
        const dataType = $$.getClassBuiltIn(data);
        if (dataType === 'FormData') {
            body = data;
        } else {
            body = new URLSearchParams(data);
        }
    }

    xhr.onload = () => {
        if (isSucceedStatus(xhr.status)) {
            try {
                const res = JSON.parse(xhr.responseText);
                resolve(res);
            } catch (e) {
                resolve(xhr.responseText);
            }
        } else {
            reject(new Error(`Upload failed, status code: ${xhr.status}`));
        }
    };
    xhr.onerror = () => reject(new Error('Upload error'));

    xhr.send(body);
    return attachAbort(promise);
}

/** @type {typeof $$.fetch.xhrUpload} */
export function xhrUpload(url, data, args) {
    return xhrRequest('POST', url, data, args);
}
