/* eslint-disable unicorn/prefer-string-replace-all, unicorn/prefer-includes */
import { arrayFind } from './polyfill-utils.js';

export default function language() {
    const languageList = [],
        defaultLanguage = document.documentElement.getAttribute('lang') || navigator.language || '';
    let data;
    function init() {
        function nonEmptyObject(v) {
            return String(v) === '[object Object]' && Object.keys(v).length > 1;
        }
        Object.keys(data).forEach(function (item) {
            if (nonEmptyObject(data[item])) {
                languageList.push(item.replace('_', '-'));
            }
        });
    }
    function getLang(val) {
        if (!languageList.length) init();
        val = val.toLowerCase();
        if (languageList.indexOf(val) < 0) {
            const region = val.split('-', 1)[0];
            val = arrayFind(languageList, true, (item) => item.indexOf(region) === 0);
        }
        if (val != null) {
            const v = val.split('-');
            val = v[0] + '-' + v[1].toUpperCase();
        }
        return val;
    }
    function findLang(lang, source) {
        if (!data) data = source || window._I18NResources;
        return getLang(lang || defaultLanguage) || getLang('en-US');
    }
    function getSource(lang) {
        const language = lang.replace(/-/g, '_').toLowerCase();
        return data[language] || {};
    }
    return { findLang, getSource };
}
