/** @jsxImportSource @gui/aui-devops */
import $ from '../../../core/element/index.js';
import { define, Widget, Types } from '../../../widget/widget.js';

import { keyPress } from '../../../util/event/key-press.js';

import { IdentifierNode } from './identifier.js';
import { NS, TooltipClassName } from './utils.js';

import style from './tooltip.less';

const tooltipName = `${NS}-tooltip`;
export const TooltipNode = 'aui-' + tooltipName;

const TooltipPosition = {
    hover: { my: 'left+8 top+8', at: 'left bottom' },
    focus: { my: 'left+4 top', at: 'right top' },
};
const popOptions = { width: [150], tabloop: false, focusable: false, mobileView: false, modalable: false, usePointer: true, blockClose: true };

/** @extends {Widget<typeof Tooltip.options>} */
@define(tooltipName)
export class Tooltip extends Widget {
    static options = {
        field: 'name',
        groupMode: false,
        groupTabLoop: true,
        throttle: true,
        useStack: false,
        onShow: Types.function,
        onHide: Types.function,
    };
    static observers = ['field', 'groupMode'];
    static styles = style;

    init() {
        this.state = {
            header: null,
            items: [],
            current: null,
        };
    }
    setOption() {
        return false;
    }
    didMount() {
        const { useStack, groupTabLoop } = this.options,
            { os, touchable } = $$.browser,
            groupMode = groupTabLoop && this.options.groupMode,
            isDesktop = os.device === 'desktop',
            [context] = this.$host.siblings(),
            $context = $(context),
            stackRoot = useStack ? context.getRootNode() : null;

        const stackQuery = '.' + TooltipClassName.Stack,
            itemQuery = '.' + TooltipClassName.Item,
            focusQuery = '.' + TooltipClassName.FocusTarget;

        if (isDesktop) {
            $context.on('mouseenter', stackQuery, { stackRoot, capture: true }, this.#showTooltip);
            $context.on('mouseleave', stackQuery, { capture: true }, this.#hideTooltip);
            $context.on('mouseleave', this.#hideTooltip); // add fallback for special cases.
            $context.on('mousemove', stackQuery, { stackRoot }, this.#moveTooltip);

            $context.on('mouseleave', itemQuery, { capture: true }, (e) => {
                const { delegateTarget, currentTarget } = e;
                $(delegateTarget).find('.current').removeClass('current');
                if (currentTarget.matches(':focus-visible')) currentTarget.focus({ focusVisible: false });
            });
            if (groupMode) {
                $context.on('click', itemQuery, { capture: true }, (e) => {
                    this.setState({ current: e.currentTarget });
                });
            }
        }

        keyPress(context, 'Escape', null, this.#hideTooltip);
        $context.on('focus', itemQuery, { capture: true }, (e) => {
            const { delegateTarget, currentTarget } = e,
                ofElement = $(currentTarget).find(focusQuery, { matchSelf: true }).get(),
                stackElement = currentTarget.closest(stackQuery),
                { key } = currentTarget.dataset;

            currentTarget.setAttribute('aria-describedby', 'tooltip-box');
            if (groupMode) $$.fn(delegateTarget.setOptions, delegateTarget)({ filterQuery: `[data-key="${key}"]` });

            if (isDesktop) {
                if (currentTarget.matches(':focus-visible')) {
                    this.element.setOptions(TooltipPosition.focus);
                    this.#showTooltip(ofElement || currentTarget, stackElement, currentTarget);
                }
            } else {
                this.#moveTooltip(currentTarget, stackElement, currentTarget, !touchable);
            }
        });
        $context.on('blur', itemQuery, { capture: true }, (e) => {
            const { currentTarget, relatedTarget } = e;
            currentTarget.removeAttribute('aria-describedby');
            this.element.setOptions(TooltipPosition.hover);
            if (!relatedTarget?.matches(itemQuery)) this.#hideTooltip(e);
        });
    }

    #getData(currentTarget, current) {
        const items = this.callback('onShow', currentTarget) ?? Array.from(currentTarget.querySelectorAll('.item')),
            header = (this.options.groupMode && items[0]?.dataset.stack) || null;
        this.setState({ header, items, current });
    }
    #showTooltip = (e, currentTarget, current) => {
        if (!currentTarget) currentTarget = e.currentTarget;
        if (this.options.throttle) this.#getData(currentTarget, current);
        this.#moveTooltip(e);
    };
    #moveTooltip = (e, currentTarget, trigger, throttle = this.options.throttle) => {
        if (!currentTarget) currentTarget = e?.currentTarget;
        if (!throttle) this.#getData(currentTarget, trigger);
        this.element.toggle(true, e, trigger || currentTarget);
    };
    #hideTooltip = (e) => {
        this.element.toggle(false);
        this.callback('onHide');
    };

    initPop(pop) {
        pop.setOptions({ ...popOptions, ...TooltipPosition.hover });
    }

    render() {
        const { field } = this.options,
            /** @type { {items:Array<Element>} } */
            { header, items, current } = this.state;

        return (
            <aui-pop id="tooltip" ref={this.ref(this.initPop)}>
                <div id="tooltip-box">
                    {header && <h4 className="tooltip-header">{header}</h4>}
                    <div className="tooltip-list">
                        {items.map((item) => {
                            const { dataset, style } = item,
                                useHighlight = current && current === item,
                                className = ['tooltip-item', useHighlight && 'current'];
                            return <IdentifierNode className={className} type={dataset.type} name={dataset[field]} color={dataset.color || style.color} val={dataset.val} />;
                        })}
                    </div>
                </div>
            </aui-pop>
        );
    }
}
