import React, { PureComponent } from 'react';

import { WR } from '../../widget/widget.jsx';

import { concat } from '../../util/array/concat.js';

import '../imgcrop/imgcrop.jsx';

const I18N = $$.I18N.uploader;

function getDerivedFiles(file) {
    if (!file) return [];
    if (typeof file === 'string') return file ? [{ base64: file }] : [];
    return file.base64 ? [file] : [];
}

export class ImgUploader extends PureComponent {
    static defaultProps = {
        deleteable: false,
        fileTypes: ['PNG', 'JPG'],
        maxSize: `20 MB`,
        showMaxSize: true,
    };

    constructor(props) {
        super(props);
        this.imageView = new ImageView(this);
    }

    onDelete = ({ files, ...fileEntity }) => $$.fn(this.props.onDelete)(fileEntity);
    onUpload = ({ files, ...fileEntity }) => $$.fn(this.props.onUpload)(fileEntity);

    render() {
        const { children, file, onDelete, onUpload, ...args } = this.props,
            files = getDerivedFiles(file);
        return this.imageView.render({ ...args, files, onDelete: this.onDelete, onUpload: this.onUpload });
    }
}

export class ImageView {
    constructor(instance) {
        Object.defineProperty(this, 'props', { get: () => instance.props });
    }

    cropBox(children) {
        const { crop } = this.props;
        if (!crop) return children;

        const { shape } = this.props;
        /** Using directly `shape` prop as fallback when `crop.shape` is not defined. */
        const cropOptions = { shape, dataType: 'base64', ...crop };
        return (
            <R.ImgCrop {...cropOptions} onChange={this.onImgCrop}>
                {children}
            </R.ImgCrop>
        );
    }
    render({ disabled, text, tooltip, crop, skipVerify, shape, radius, userName, ...args }) {
        /** @type {typeof R.Uploader} */
        const PureUploader = WR.Uploader,
            { Detail, Img, Picker } = R.Uploader;
        Object.assign(args, { disabled, skipVerify: concat(['overwrite'], skipVerify || []) });

        return (
            <PureUploader {...args} accept="image/*" multiple={false} internalMessage view="image">
                <Img className="gap-m" shape={shape} radius={radius} userName={userName}>
                    <div className="flex-column justify-center gap-s">
                        {this.cropBox(
                            <Picker>
                                <R.Button classify="theme" disabled={disabled} primary tooltip={tooltip} text={text || I18N.imgBrowser} />
                            </Picker>
                        )}
                        <Detail />
                    </div>
                </Img>
            </PureUploader>
        );
    }
}

$$.shell.define('ImgUploader', ImgUploader);
