import exportPlainFile from '../../util/io/export-plain-file.js';
import pascalCase from '../../util/string/pascal-case.js';

let logIndex = 1,
    onDev = document.readyState === 'complete' ? false : null;
const hiddenLogs = [],
    logHistory = [];
// eslint-disable-next-line no-console
const output = (type, args) => console[type](...args);

function logUtil(type, color, messages) {
    const [v, ...args] = messages,
        useTag = typeof v === 'string',
        index = logIndex++;
    let omit = false;
    if (type === 'omit') {
        omit = true;
        type = 'log';
    }
    const list = [
        `%c[${index}]%c ${useTag ? v + ' %c' : ''} ${!useTag || args.length ? '%o' : ''}`,
        `background:${color};border:1px solid ${color}; border-radius: 4px ${useTag ? '0 0 4px' : ''}; color: #fff;`,
        `border:1px solid ${color}; border-radius: 0 4px 4px 0; ${type === 'log' ? '' : `color: ${color};`}`, // useTag
        'background:transparent',
        v, // don't useTag
        ...args,
    ];
    list.splice(useTag ? 4 : 2, 1);

    if (onDev) {
        output(type, list);
    } else {
        hiddenLogs.push({ type: type, omit, content: list });
    }
    cacheLog(pascalCase(type), messages, index);
}
function cacheLog(type, logs, index) {
    logHistory[index ?? logIndex++] = [type, String(new Date()), logs];
}

export function omit(...args) {
    logUtil('omit', 'gray', args);
}
export function log(...args) {
    logUtil('log', '#31996c', args);
}
export function info(...args) {
    logUtil('info', '#2d8fc4', args);
}
export function warn(...args) {
    logUtil('warn', '#c76e20', args);
}
export function error(...args) {
    logUtil('error', '#c91d1d', args);
}
export function throws(v, errorType = Error) {
    const { name } = errorType,
        args = [`[Uncaught ${name}]`, v];
    if (onDev) {
        const error = new errorType(v);
        cacheLog('Throw', args);
        throw error;
    } else {
        error(...args);
    }
}

export function dev(value) {
    if (arguments.length === 0) return onDev;
    const prev = onDev;
    onDev = !!value;
    if (value) {
        while (hiddenLogs.length) {
            const { type, omit, content } = hiddenLogs.pop();
            if (!omit || prev == null) output(type, content);
        }
    }
}

function wrapLog(v) {
    if (typeof v === 'object') {
        try {
            v = JSON.stringify(v);
        } catch (e) {
            if ($$.getClassBuiltIn(v).endsWith('Element')) {
                v = v.cloneNode(false).outerHTML;
            } else {
                error(`Can't convert storable value`, v);
            }
        }
    }
    v = String(v).replaceAll(`"`, `'`);
    return `\"${v}\"`;
}
export function exportLog() {
    const content = logHistory.map(([type, date, messages], i) => `${i},${date},[${type}],` + messages.map(wrapLog).join(','));
    content[0] = `0,-,Env:,${wrapLog($$.browser)}`;
    exportPlainFile(content.join('\n'), 'log.csv');
    logHistory.splice(0);
}
