import { I18N } from '../../core/base/i18n.js';
import { error } from '../../core/base/log.js';

import { _parse } from './_parse.js';

/** @type {typeof $$.number.local} */
export default function local(val, locales = I18N.lang) {
    const num = _parse(val);
    if (Number.isFinite(num)) return num.toLocaleString(locales);

    error('The value is invalid number!');
    return '';
}
