import React, { PureComponent, createRef } from 'react';

import { WR } from '../../widget/widget.jsx';

import { ImageView } from './imguploader.jsx';

export class Uploader extends PureComponent {
    static defaultProps = {
        view: 'default',
    };

    static Detail = WR.UploaderDetail;
    static Echo = WR.UploaderEcho;
    static Img = WR.UploaderImg;
    static Picker = WR.UploaderPicker;

    constructor(props) {
        super(props);
        this.uploader = createRef();
        this.imageView = new ImageView(this);
    }

    clear = () => this.uploader.current.method('clear');

    render() {
        /** @type {typeof R.Uploader} */
        const PureUploader = WR.Uploader;
        const { children, view, ...rests } = this.props;
        Object.assign(rests, { ref: this.uploader });

        if (view === 'image') return this.imageView.render(rests);
        if (view !== 'default' || children) return <PureUploader {...rests}>{children}</PureUploader>;

        // default view
        return (
            <PureUploader {...rests} view="default" droppable={rests.droppable ?? '.drop-box'}>
                <section className="drop-box">
                    <span className="aui-uploader-icon faui-cloud-upload" />
                    <div>
                        <Uploader.Picker />
                        <Uploader.Detail />
                    </div>
                </section>
                <Uploader.Echo />
            </PureUploader>
        );
    }
}

export class UploaderEcho extends PureComponent {
    static defaultProps = {
        deleteable: false,
    };
    render() {
        const { children, ...args } = this.props;
        return (
            <WR.Uploader {...args}>
                <Uploader.Echo />
            </WR.Uploader>
        );
    }
}

$$.shell.define('Uploader', Uploader);
$$.shell.define('UploaderEcho', UploaderEcho);
