/** @jsxImportSource @gui/aui-devops */
// cSpell: ignore eqnarray mtable mathml mtext mathop xlink
/* global MathJax */
import $ from '../../../core/element/index.js';
import { addTooltip } from '../../../core/module/tooltip.js';
import { define, Widget, Types } from '../../../widget/widget.js';

import { keyName } from '../../../util/event/key-name.js';
import { navigation as eventNavigation } from '../../../util/event/navigation.js';
import stopEvent from '../../../util/event/stop.js';
import numberInt from '../../../util/number/int.js';

import '../../popup/pop.js';
import '../quick-table.js';

import * as util from './math.base.js';

import style from './style.less';

const I18N = $$.I18N.math;

/** @extends {Widget<typeof Math.options>} */
@define('math')
export class Math extends Widget {
    static options = {
        fontSizes: [8, 10, 12, 14, 18, 24, 36],
        fontSizeDefault: 12,
        matrixRow: 10,
        okClick: Types.function,
        updateButtonStatus: Types.function,
        setVerifyMsg: Types.function,
    };
    static styles = style;
    static observers = ['matrixRow'];

    method = {
        setFontSize: this.setFontSize,
        setValue: this.setValue,
        checkFormula: this.checkFormula,
        getInstance: this.getInstance,
        willShow: this.willShow,
        show: this.show,
        hide: this.hide,
    };
    init() {
        this.createBasicView = !!this.initBasic;
        this.initState();
    }
    initState() {
        this.state = {
            activeCategory: 0,
            fontSize: this.options.fontSizeDefault,
            fontUnit: 'pt',
            latex: '',
            showMatrix: false,
            currentSymbol: '',
            error: null,
        };
    }
    didMount() {
        if (this.initBasic) this.initBasic(); // only for leoGcc
        this.category = this.query('.category');
        this.symbolContainer = this.query('.symbols-container');
        this.advanceFormula = this.query('.formula-advanceview');
        this.matrixPicker = this.query('#matrix-picker');
        this.advanceTextarea = this.query('.advance-editarea');
        this.basicTextarea = this.createBasicView ? this.query('aui-mathquill', '.basic-view textarea') : null;

        this.dialog = window.CKEDITOR?.dialog.getCurrent();
        this.ok = this.dialog?._.buttons.ok;

        this.initEvent();
        addTooltip(this.host);

        setTimeout(() => {
            this.setState({ loadAllSymbols: true });
        }, 10);
    }

    initEvent() {
        // symbol click
        $(this.symbolContainer).on('click', 'li', (e) => {
            this.onSymbolClick(e);
        });
        $(this.symbolContainer).on('keydown', 'li', (e) => {
            const name = keyName(e);
            if (name === 'Enter') {
                stopEvent(e);
                this.onSymbolClick(e, name);
            } else {
                eventNavigation(e);
            }
        });
    }
    setFontSize(value) {
        if (value) {
            this.setState({ fontSize: Number(value) });
        }
    }
    onSymbolClick = (e, name) => {
        const symbol = e.currentTarget;
        this.state.needUseWrite = symbol.getAttribute('data-mq');
        if (!$(symbol).hasClass('matrix')) {
            this.setLaTeXValue(symbol.getAttribute('data-advance'));
        } else if (name === 'Enter') {
            $(symbol).trigger('click');
            this.query('aui-math-popup', 'aui-editor-quicktable', 'tbody').focus();
        }
    };

    onMatrixTableChange = (row, col, matrixLatexType) => {
        const latex = util.matrixLatex[matrixLatexType];
        if (latex) {
            const eqnarrayType = matrixLatexType === 'eqnarray';
            let result = '',
                placeholder;
            for (let r = 0; r < row; r++) {
                placeholder = String.fromCodePoint(97 + r);
                for (let c = 0; c < col - 1; c++) {
                    result += placeholder + (c + 1);
                    result += eqnarrayType ? ' & = & ' : ' & ';
                }
                result += placeholder + col;
                if (r < row - 1) result += ' \\\\\n';
            }
            this.setLaTeXValue(latex.replace(util.matrixSplitter, result));
            this.refs.pop.method('hide');
            this.focusTextArea();
        }
    };
    stop = (e) => {
        e.stopPropagation();
    };
    onCategoryChange = (e) => {
        const target = e?.target,
            activeCategory = numberInt(target.value);
        this.setState({ activeCategory: activeCategory });
    };
    onKeyDown = (e) => {
        switch (keyName(e)) {
            case 'ArrowLeft':
                stopEvent(e);
                break;
            case 'ArrowRight':
            case 'Enter':
                stopEvent(e);
                this.symbolContainer.querySelector('.active').firstElementChild.focus();
                break;
            default:
                e.stopPropagation();
        }
    };

    onPasteFormulaValue = (e) => {
        this.onFormulaValueChange(e);
    };
    onFormulaValueChange = (e) => {
        const latex = e.currentTarget.value;
        this.state.currentSymbol = latex;
        this.state.latex = latex;
        this.state.error = null;
        $$.throttle(() => {
            this.setState();
            this.updateFormulaView(this.state.latex);
        })();
    };
    onFormulaKeyup = (e) => {
        const name = keyName(e);
        if (name === 'Alt') {
            this.category.querySelector(':checked').focus();
            e.preventDefault();
        } else if (name === 'Control+Enter') {
            return this.ok ? this.ok.click() : $$.fn(this.options.okClick)();
        }
    };
    onFontSizeChange = (v) => {
        this.setState({ fontSize: Number(v) });
    };
    updateFormulaView = () => {
        if (this.state.latex) {
            this.ok?.enable();
            const svg = this.advanceFormula.querySelector('svg'),
                mtable = svg.querySelectorAll('g[data-mml-node=mtable]>line[data-line]'),
                dataTable = svg.querySelectorAll('svg[data-table]>g>line[data-line]');
            svg.setAttribute('role', 'math');
            this.setLineAttr(mtable);
            this.setLineAttr(dataTable);
        } else {
            this.ok?.disable();
        }
        $$.fn(this.options.updateButtonStatus)(this.state.latex);
        $$.fn(this.options.setVerifyMsg)(this.state.error);
        $$.fn(this.dialog?.error)(this.state.error);
    };
    setLineAttr(lines) {
        Array.from(lines, (item) => item.setAttribute('stroke-width', '70px'));
    }
    updateLatex = (string) => {
        this.setState({ latex: string }, () => {
            this.updateFormulaView();
        });
    };
    onSwitchViewClick = () => {
        this.handleSwitchViewClick();
    };
    setLaTeXValue(string, replace, noFocus) {
        this.state.currentSymbol = string;
        const val = replace ? '' : this.state.latex,
            start = this.advanceTextarea.selectionStart,
            end = this.advanceTextarea.selectionEnd;
        const latex = val.slice(0, start) + string + (val || string ? ' ' : '') + val.slice(end, end + val.length);
        this.setState({ latex: latex }, () => {
            this.symbolContainer = this.query('.symbols-container'); // need restructure
            this.updateFormulaView();
            if (this.isBasic) this.refs.mq.method('setLatex', this.state);
            this.advanceTextarea.selectionStart = string.length + start + 1;
            this.advanceTextarea.selectionEnd = this.advanceTextarea.selectionStart;
        });

        if (!noFocus) this.focusTextArea();
    }
    willShow() {
        this.initState();
    }
    show() {
        if (this.dialog) {
            setTimeout(() => {
                this.focusTextArea();
            });
        } else {
            this.focusTextArea();
        }
        this.symbolContainer.firstChild.scrollTop = 0;
    }
    focusTextArea() {
        if (!$$.browser.touchable) {
            this.advanceTextarea.focus();
        }
    }
    hide() {
        if (this.resetBasic) this.resetBasic();
        this.category.scrollTop = 0;
        this.setState({ latex: '', activeCategory: 0, fontSize: this.options.fontSizeDefault, error: null }, () => {
            for (const x of this.element.querySelectorAll('textarea')) x.value = '';
        });
    }
    setValue(val) {
        let latex = val || '';
        if (/data-latex=\S*/.test(latex)) {
            latex = $(val).attr('data-latex');
        }
        // compatible with old usage.
        latex = latex.replaceAll(/ \\oi{2,3}nt/g, function (match) {
            return ' \\mathop' + match.trim(); // eslint-disable-line unicorn/prefer-string-raw
        });
        this.setLaTeXValue(latex, true);
    }
    checkFormula() {
        const $redText = [];
        for (const ele of this.advanceFormula.querySelectorAll('.mjx-mtext')) {
            if (ele.style.color === 'red') $redText.push(ele);
        }
        if (!$redText || ($redText && $redText.length < 1)) {
            for (const ele of this.advanceFormula.querySelectorAll('g')) {
                if (ele.getAttribute('fill') === 'red') $redText.push(ele);
            }
        }
        if (MathJax.invalid() || $redText.length > 0) {
            const error = I18N.invalidFormula;
            this.state.error = error;
            $$.fn(this.dialog?.error)(error);
            return this.dialog ? false : error;
        }
        return true;
    }
    getFormula(latex) {
        let dom = <span>{latex ? MathJax.tex2svg(latex).firstChild : this.advanceFormula.querySelector('svg').cloneNode(true)}</span>;
        dom.getAttributeNode('data-mathml')?.removeAttribute('data-mathml');
        dom = this.svgHandle(dom, !latex);
        if (this.state.fontSize) dom.style.fontSize = this.state.fontSize + this.state.fontUnit;
        $(dom).attrs({ 'data-latex': latex }).find('.MJX_Assistive_MathML').remove();
        return dom;
    }
    svgHandle(element, setSize) {
        const svgEle = element.querySelector('svg');
        if (!svgEle) return element;
        if (setSize) {
            const $source = $(this.advanceFormula.querySelector('svg')),
                width = $source.css('width'),
                height = $source.css('height');
            $(svgEle).attr({ width: width, height: height });
        }
        for (const item of svgEle.querySelectorAll('use')) {
            const id = item.getAttribute('xlink:href') || item.getAttribute('href'),
                x = item.getAttribute('x'),
                y = item.getAttribute('y');
            let def = document.getElementById(id) ?? svgEle.querySelector(id),
                transform = item.getAttribute('transform') || '';
            if (def != null) {
                def = def.cloneNode(true);
                if (x && y) transform = (transform ? transform + ' ' : '') + 'translate(' + [x, y].join(',') + ')';
                if (transform) def.setAttribute('transform', transform);
                item.replaceWith(def);
            }
        }
        svgEle.setAttribute('role', 'math');
        svgEle.querySelector('defs').remove();
        svgEle.getAttributeNode('id')?.removeAttribute('id');
        element.outerHTML.replace('<div', '<span');
        return element;
    }

    getInstance() {
        return {
            latex: this.state.latex,
            formulaDom: this.getFormula(),
            fontSizeValue: this.state.fontSize,
        };
    }

    createFontSizeSelector() {
        const { fontSizes } = this.options,
            { fontUnit } = this.state,
            format = `{0} ${fontUnit}`;
        return (
            <aui-select-lite className="fontsize-selector" items={fontSizes.join(';')} value={this.state.fontSize} format={format} onChange={this.onFontSizeChange}>
                <aui-i18n slot="inline-start" entry={I18N.fontLabel} />
            </aui-select-lite>
        );
    }
    initSymbols() {
        return util.categoryList.flatMap((item, index) => {
            const attrs = {
                id: 'aui-math-symbol-' + item.name,
                className: ['symbol', item.name.toLowerCase(), index === this.state.activeCategory && 'active'],
                role: 'listbox',
                'aria-label': item.content,
            };
            if (index === this.state.activeCategory || this.state.loadAllSymbols) {
                const symbols = util.symbolList[item.name].map((symbol, i) => {
                    const li = symbol.createTemplate(this.isBasic);
                    return Object.assign(li, { role: 'option', tabIndex: i === 0 ? 0 : -1 });
                });
                return <ul {...attrs}>{symbols}</ul>;
            }
            return [];
        });
    }
    render() {
        const { activeCategory, latex, fontSize, fontUnit } = this.state,
            categoryAttrs = { type: 'radio', name: 'math-category', onChange: this.onCategoryChange, onKeyDown: this.onKeyDown };
        return (
            <div className="math" onKeyDown={this.stop}>
                <section className="category">
                    {util.categoryList.map((item, index) => (
                        <label tabIndex="-1" data-tooltip="ifneed" className={index === activeCategory ? 'active' : ''}>
                            <input {...categoryAttrs} value={index} checked={index === activeCategory} autoComplete="off" />
                            <aui-math-symbol latex={item.symbol} />
                            {!$$.mobileView && item.content}
                        </label>
                    ))}
                </section>
                <div className="content body-scroll" disabled={this.options.disabled}>
                    {this.createBasicView && (
                        <div className="flex-end">
                            <aui-button-lite type="link" className="view-switch" onClick={this.onSwitchViewClick}>
                                <span slot="text">{this.isBasic ? I18N.switchToAdvanced : I18N.switchToBasic}</span>
                            </aui-button-lite>
                        </div>
                    )}
                    <div className="symbols-container">{this.initSymbols()}</div>
                    <div className="editor" />
                    <div className="advanced-view" hidden={this.isBasic}>
                        <textarea
                            className="advance-editarea"
                            placeholder={I18N.editorLabel}
                            autoComplete="off"
                            spellCheck="false"
                            onChange={this.onFormulaValueChange}
                            onPaste={this.onPasteFormulaValue}
                            onInput={this.onFormulaValueChange}
                            onKeyUp={this.onFormulaKeyup}
                        >
                            {latex}
                        </textarea>

                        <div className="formula-advance">
                            <div className="header">
                                <div hidden>{I18N.formula}</div>
                                <div className="align-end">{this.createFontSizeSelector()}</div>
                            </div>

                            <div className="formula-advanceview" style={{ 'font-size': fontSize + fontUnit, 'padding-right': $$.scrollSize.width + 'px' }}>
                                {latex && MathJax.tex2svg(latex)}
                            </div>
                        </div>
                    </div>
                    {this.createBasicView && <aui-mathquill className="basic-view" hidden={!this.isBasic} ref={this.ref('mq')} updateLatex={this.updateLatex} />}
                    <aui-math-popup onMatrixTableChange={this.onMatrixTableChange} ref={this.ref('pop')} />
                </div>
            </div>
        );
    }
}

/** @extends {Widget<typeof MathSymbol.options>} */
@define('math-symbol')
class MathSymbol extends Widget {
    static options = {
        latex: Types.string,
    };
    static shadow = false;

    didMount() {
        const svg = MathJax.tex2svg(this.options.latex);
        svg.querySelector('svg').setAttribute('role', 'math');
        this.host.append(svg);
    }
    render() {
        return <></>;
    }
}

/** @extends {Widget<typeof MathPop.options>} */
@define('math-popup')
class MathPop extends Widget {
    static options = {
        onMatrixTableChange: Types.function,
    };
    static shadow = false;
    method = { hide: this.hide };

    initPop = (pop) => {
        pop.setOptions({
            status: { show: false },
            triggerEvent: 'click',
            delegate: '.matrix.advance',
            eventScope: ':parent(2)',
            mobileView: false,
            modalable: false,
        });
    };
    init() {
        this.state = {
            show: true,
        };
    }
    willShow = ({ ofElement }) => {
        this.currentElement = ofElement;
        this.matrixLatexType = ofElement.getAttribute('aria-label');
        ofElement.setAttribute('data-popup', true);
        this.setState({ show: true });
    };
    hide() {
        this.refs.pop.setOptions({ status: { show: false } });
    }
    onHidePop = () => {
        this.matrixLatexType = null;
        this.currentElement.removeAttribute('data-popup');
        this.setState({ show: false });
    };
    onMatrixTableChange = (row, col) => {
        $$.fn(this.options.onMatrixTableChange)(row, col, this.matrixLatexType);
    };
    onMatrixClick = (e) => {
        e.stopPropagation();
    };
    closeTable = () => {
        const [row, col] = this.refs.pop.querySelector('aui-editor-quicktable')?.method('getPosition') ?? [1, 1];
        this.onMatrixTableChange(row, col);
    };
    render() {
        return (
            <aui-pop ref={this.ref('pop', this.initPop)} willShow={this.willShow} onHide={this.onHidePop}>
                <div id="matrix-picker" onClick={this.onMatrixClick}>
                    {this.state.show && <aui-editor-quicktable caption={I18N.selectSize} onChange={this.onMatrixTableChange} ref={this.ref('quicktable')} />}
                    {$$.mobileView && (
                        <>
                            <hr />
                            <div className="footer">
                                <aui-button-lite type="link" text={I18N.ok} onClick={this.closeTable} />
                            </div>
                        </>
                    )}
                </div>
            </aui-pop>
        );
    }
}
