import forEach from '../object/for-each.js';

import keyMap from './key-map.js';
import origin from './origin.js';

// https://www.w3.org/TR/uievents-key/#named-key-attribute-values
/** @type {typeof $$.event.keyName} */
export function keyName(e, pure) {
    e = origin(e);
    const code = e.which || e.keyCode;
    let name = e.key;
    if (!name || name === 'Unidentified') name = e.code || e.data || '';
    name = name.trim();
    if (name) name = name[0].toUpperCase() + name.slice(1);
    // Non-DOM_KEY_LOCATION_NUMPAD
    const NumPad = e.location === 3;
    if (NumPad || !name || keyMap[name] == null) {
        forEach(keyMap, function (k, v) {
            if (NumPad ? k === 'NUM_' + name : v === code) {
                name = k;
                return false;
            }
        });
    }
    if (pure) return name;
    const modifier = [];
    if (e.ctrlKey && !name.includes('Control')) modifier.push('Control');
    if (e.altKey && !name.includes('Alt')) modifier.push('Alt');
    if (e.shiftKey && !name.includes('Shift')) modifier.push('Shift');
    modifier.push(name);
    const fullName = modifier.join('+');
    return fullName;
}

/** @type {typeof $$.event.keyNamePure} */
export function keyNamePure(name) {
    return name.replaceAll(/(Control|Alt|Shift)\+/g, '');
}
