import { throws } from '../../core/base/log.js';

import { _parse } from './_parse.js';

/** @type {typeof $$.number.minmax} */
export default function minmax(...args) {
    const l = args.length;
    if (l > 0) {
        const first = _parse(args[0]);
        if (Number.isFinite(first)) {
            let finite = true,
                min = first,
                max = first;
            for (let i = 1; i < l; i++) {
                const v = _parse(args[i]);
                if (Number.isFinite(v)) {
                    if (v > max) {
                        max = v;
                    } else if (v < min) {
                        min = v;
                    }
                } else {
                    finite = false;
                    break;
                }
            }
            if (finite) return [min, max];
        }
    }

    throws(`Require number arguments.`, TypeError);
    return [Number.NaN, Number.NaN];
}
