import { _filter } from './_filter.js';

/** @type {typeof $$.object.filter} */
export default function filter(target, test, withRest) {
    const data = {},
        rests = {};
    const setter = (obj) => (k, v) => (obj[k] = v);
    _filter(target, test, setter(data), setter(rests));
    return withRest ? [data, rests] : data;
}
