import { isPrimitive } from '../type/types.js';

/** @type {typeof $$.string.key4Map} */
export default function key4Map(key) {
    if (key == null) return null;
    if (typeof key !== 'string') return isPrimitive(key) ? String(key) : key;
    const k = key.trim();
    return k.length ? k : null;
}
