/** @jsxImportSource @gui/aui-devops */
import { define, Widget, Types } from '../widget.js';

const Reg = /\{\d{1,3}\}/g;

/** @extends {Widget<typeof I18N.options>} */
@define('i18n')
export class I18N extends Widget {
    static options = {
        entry: Types.string,
        block: Types.boolean,
    };
    static observers = ['entry'];
    static requires = ['entry'];
    static styles = ':host{ display:inline; vertical-align:unset; }';

    render() {
        const { entry, block } = this.options,
            Tag = block ? 'div' : 'span',
            slots = entry.match(Reg);
        // if no replace slots, display the entry as plain text directly.
        if (!slots) return <Tag>{entry}</Tag>;
        return entry.split(Reg).flatMap((str, i) => {
            const slot = slots[i];
            return [str ? <Tag>{str}</Tag> : null, slot ? <slot name={slot.slice(1, -1)} /> : null];
        });
    }
}
