/** @jsxImportSource @gui/aui-devops */
import $ from '../../core/element/index.js';
import { addTooltip } from '../../core/module/tooltip.js';
import { define, Widget, Types, inherit } from '../../widget/widget.js';

import cssClamp from '../../util/css/clamp.js';
import length from '../../util/css/length.js';
import { keyName } from '../../util/event/key-name.js';
import { keyPress as eventKeyPress } from '../../util/event/key-press.js';
import objectExtendNull from '../../util/object/extend-null.js';

import { Pop } from '../popup/pop.js';

import style from './style.less';

const PopOptions = ['status', 'offClose', 'dynamicSize', 'scrollable', 'resetScroll', 'willHide', 'onHide', 'willShow', 'onShow'];
const { options, observers, forwardOptions } = inherit(Pop, PopOptions);

const I18N = $$.I18N.comboboxshell;
const FieldSizingPolyfill = !CSS.supports('field-sizing', 'content');

/** @extends {Widget<typeof ComboboxShell.options>} */
@define('combobox-shell')
export class ComboboxShell extends Widget {
    static options = {
        triggerType: Types.Enum(['all', 'icon', 'none'], 'all'),
        icon: Types.Union([Types.boolean, Types.string, Types.Object({ className: [Types.string], tooltip: [Types.string] })], true),
        editable: false,
        clearable: Types.Enum([true, false, 'disabled'], false),
        clearTooltip: Types.string,

        content: Types.string,
        contentScrollable: Types.boolean,
        placeholder: Types.string,
        tooltip: Types.string,

        disabled: false,
        readonly: false,
        width: Types.Length,
        height: Types.Length,
        block: false,
        compact: false,
        mini: false,

        popupWidth: Types.Lengths,
        popupHeight: Types.Lengths,
        ...options,

        onClear: Types.function,
        onInput: Types.function,
        onKeyTrigger: Types.function,
    };
    static observers = ['clearable', 'clearTooltip', 'content', 'disabled', 'readonly', 'popupWidth', 'popupHeight', ...observers];
    static shadow = { delegatesFocus: true, referenceTarget: 'input' };
    static styles = style;
    static ariaTarget = '#input';

    #iconInfo() {
        const { icon } = this.options,
            { dropdown } = I18N;
        if (icon === true) {
            return { icon: 'faui-caret-down', aria: dropdown };
        } else if (icon) {
            if (typeof icon === 'string') return { icon, aria: dropdown };
            if (typeof icon === 'object') {
                const { className, tooltip } = icon;
                if (className) return { icon: className, aria: dropdown, tooltip };
            }
        }
        return null;
    }
    #clearable() {
        const { readonly, disabled, clearable, triggerType } = this.options;
        return triggerType !== 'icon' && !disabled && !readonly && clearable;
    }
    #editable() {
        const { readonly, disabled, editable } = this.options;
        return editable && !readonly && !disabled && !$$.mobileView;
    }
    init() {
        const { width, height, mini } = this.options;
        this.state = {
            iconInfo: this.#iconInfo(),
            isShow: false,
            clearable: this.#clearable(),
            editable: this.#editable(),
            width: mini ? null : length(width),
            height: length(height),
        };
    }
    didMount() {
        addTooltip(this.host);
        const pressKeys = ['Backspace', 'Delete', 'Escape', 'Enter', 'Alt+ArrowDown'];
        eventKeyPress(this.element, pressKeys, null, this.onKeyPress, { preventDefault: false, strict: true });
        this.$element.on('click', '.trigger', this.onClick);
        this.addGlobalEventListener('MobileToggle', () => this.setState({ editable: this.#editable() }));
    }
    setOption(name, value, oldValue) {
        switch (name) {
            case 'content':
                return true;
            case 'clearable':
                this.state.clearable = this.#clearable();
                return true;
            case 'disabled':
            case 'readonly':
                this.state.clearable = this.#clearable();
                this.state.editable = this.#editable();
                return true;
            case 'status':
                if (value.show !== (oldValue?.show ?? this.state.isShow)) {
                    this.refs.pop.setAttribute('status', value);
                    this.#togglePop(value.show);
                }
                return false;
            default:
                return !this.options.status.show;
        }
    }

    onToggle = (isShow) => {
        const { status } = this.options;
        if (status) status.show = isShow;
        this.setState({ isShow }, !isShow);
        this.element.querySelector('[aria-expanded]').setAttribute('aria-expanded', isShow);
        this.customState('expanded', isShow);
    };
    #togglePop(isShow) {
        if (!this.options.disabled) this.refs.pop.toggle(isShow, null, this.element);
    }

    onInputInput = (e) => {
        const { value } = e.target;
        if (this.callback('onInput', value) === false) e.preventDefault();
    };
    /** async input value attribute with its real value. */
    onInputChange = (e) => {
        const input = e.target;
        input.setAttribute('value', input.value);
    };
    onInputFocus = (e) => {
        /** @type {HTMLInputElement} Prevent input content selected on focus. */
        const input = e.target,
            { selectionStart, selectionEnd } = input;
        if (selectionStart !== selectionEnd) input.setSelectionRange(selectionEnd, selectionEnd);
    };
    onClear = (e) => {
        if (!this.state.clearable) return;
        e.stopPropagation();
        this.callback('onClear');
    };

    onClick = (e) => {
        if (this.options.disabled) return;
        // editable ? show : toggle
        const isShow = this.#editableTarget(e) ? true : undefined;
        this.#togglePop(isShow);
    };
    #editableTarget(e) {
        const { target, currentTarget } = e;
        return $(target).closest(':read-write', currentTarget).length ? target : null;
    }
    #keyTrigger(e, keyName, editableTarget) {
        const result = this.callback('onKeyTrigger', e, keyName, editableTarget?.value ?? null);
        if (editableTarget != null && typeof result === 'string') editableTarget.value = result;
        return result !== false;
    }
    onKeyPress = (e, keyName) => {
        if (this.options.disabled) return;
        const editableTarget = this.#editableTarget(e),
            trigger = $(e.target).closest('.trigger', e.currentTarget).length > 0;
        switch (keyName) {
            case 'Backspace':
            case 'Delete':
                return this.#keyTrigger(e, keyName) && !editableTarget && this.onClear(e);
            case 'Escape':
                return (!editableTarget || this.#keyTrigger(e, keyName, editableTarget)) && this.#togglePop(false);
            case 'Enter':
                return (!editableTarget || this.#keyTrigger(e, keyName, editableTarget)) && trigger && this.#togglePop(true);
            case 'Alt+ArrowDown':
                return trigger && this.#togglePop(true);
        }
    };
    onKeyDown = (e) => {
        if (this.options.disabled) return;
        const key = keyName(e);
        switch (key) {
            case 'ArrowUp':
            case 'ArrowRight':
            case 'ArrowDown':
            case 'ArrowLeft':
                return this.#keyTrigger(e, key);
            case 'Space':
                return this.#editableTarget(e) || e.preventDefault();
        }
    };

    #renderDropdown() {
        const { iconInfo, clearable } = this.state;
        if (!iconInfo) return null;

        const { triggerType, clearTooltip, disabled } = this.options,
            { icon, ...iconArgs } = iconInfo,
            iconTrigger = triggerType === 'icon',
            btnArgs = { type: 'plain', shrink: 'xs', text: '', disabled };
        return (
            <div id="icon-box" role="application" aria-label={clearable === true ? I18N.clearIconLabel : null}>
                {!iconTrigger && (
                    <div className="contents clear" hidden={!clearable}>
                        <aui-button-lite
                            id="clear"
                            className="icon"
                            {...btnArgs}
                            disabled={clearable === 'disabled'}
                            tooltip={clearTooltip ?? I18N.clear}
                            readonly
                            onClick={this.onClear}
                        >
                            <span slot="icon" className={this.fontIcon('faui-close-circle')} />
                        </aui-button-lite>
                    </div>
                )}
                <div className="contents">
                    <aui-button-lite className={['icon', 'dropdown', iconTrigger && 'trigger']} {...btnArgs} readonly={!iconTrigger} {...iconArgs}>
                        <span slot="icon" className={this.fontIcon(icon)} />
                    </aui-button-lite>
                </div>
            </div>
        );
    }
    render() {
        const { triggerType, content, contentScrollable, placeholder, tooltip, disabled, readonly, block, compact, mini, popupWidth, popupHeight, ...args } = this.options,
            { editable, isShow, width, height } = this.state,
            popArgs = Object.assign(forwardOptions(args), { width: objectExtendNull(cssClamp(popupWidth), { 0: '100%' }), height: popupHeight });
        const arias = this.arias({
            role: 'combobox',
            label: tooltip,
            readonly: readonly || null,
            hasPopup: 'dialog',
            controls: 'main',
            describedBy: 'tooltip icon-box content',
            expanded: isShow,
            // autocomplete: "both"
        });
        return (
            <>
                <slot
                    name="trigger"
                    className={[
                        'box',
                        contentScrollable && 'scrollable',
                        block && 'block',
                        compact && 'compact',
                        mini && 'mini',
                        $$.browser.touchable && 'touchable',
                        triggerType === 'all' && 'trigger',
                    ]}
                    data-interactive="focusable"
                    aria-describedby="tooltip"
                    data-tooltip={tooltip ? true : 'ifneed'}
                    data-readonly={readonly}
                    data-disabled={disabled}
                    style={{ width, height }}
                    onKeyDown={this.onKeyDown}
                >
                    <section>
                        {FieldSizingPolyfill && (
                            <div className="fake-input" aria-hidden="true">
                                {content}
                            </div>
                        )}
                        <div id="tooltip">{tooltip}</div>
                        <slot name="content" id="content" />
                        <input
                            id="input"
                            type="text"
                            readOnly={readonly || !editable}
                            disabled={disabled}
                            placeholder={placeholder}
                            autoCapitalize="off"
                            autoComplete="off"
                            spellCheck="false"
                            tabIndex={triggerType === 'icon' ? -1 : null}
                            value={content}
                            {...arias}
                            onInput={this.onInputInput}
                            onChange={this.onInputChange}
                            onFocus={this.onInputFocus}
                        />
                    </section>
                    {this.#renderDropdown()}
                </slot>
                <aui-pop id="popup" tabloop triggerEvent="click" focusBack={editable && 'input'} ref={this.ref('pop')} {...popArgs} onToggle={this.onToggle}>
                    <slot id="main" />
                    <slot slot="footer" name="footer" />
                    <slot slot="buttons" name="buttons" />
                </aui-pop>
            </>
        );
    }
}
