/** @jsxImportSource @gui/aui-devops */
import { define, Widget, Types } from '../../widget/widget.js';

import style from './style.less';

/** @extends {Widget<typeof Badge.options>} */
@define('badge')
export class Badge extends Widget {
    static options = {
        value: Types.number,
        max: 99,
        type: Types.Enum(['number', 'dot'], 'number'),
        mode: Types.Enum(['nav']),
        classify: Types.Classify(true, 'extends', 'error'),
    };
    static styles = style;
    static observers = ['value', 'classify'];
    static upcasts = ['mode'];

    render() {
        const { type, classify, value, max, mode } = this.options,
            dot = type === 'dot',
            length = (dot ? 0.5 : String(max).length + 1) / 2 + 'ch';
        return (
            <>
                <slot part="none" />
                <div className="content" data-mode={mode} classify={classify} style={{ '--length': length }}>
                    <div className={['box', type]} data-count={value}>
                        {!dot && <span>{value > max ? max + '+' : value}</span>}
                    </div>
                </div>
            </>
        );
    }
}
