import { fileType, iconMapping } from './file-type.js';

const iconPrefix = 'fi-file-',
    defaultFileIcon = 'fi-file';

/** @type {typeof $$.io.fileIcon} */
export function fileIcon(type) {
    const _type = String(type || '')
        .toLowerCase()
        .trim()
        .split('.')
        .at(-1);
    const defaults = this && typeof this === 'string' ? this : defaultFileIcon;
    if (!_type) return defaults;

    const types = Object.keys(fileType),
        t = types.find((k) => fileType[k].includes(_type)) || (types.includes(_type) && _type),
        className = t ? iconMapping[t] ?? iconPrefix + t : defaults;
    return className;
}

const ContentCache = {};

/** @type {typeof $$.io.fileIconContent} */
export function fileIconContent(type) {
    const context = this?.nodeType === Node.ELEMENT_NODE ? this : document.body,
        className = fileIcon(type),
        varName = `--${className}`,
        varExists = ContentCache[varName] ?? Boolean(getComputedStyle(context).getPropertyValue(varName)),
        content = varExists ? `var(${varName})` : null;
    ContentCache[varName] = varExists;
    return [className, content];
}
