import { keyName } from './key-name.js';

/** @type {typeof $$.event.isKey} */
export default function isKey(val, name, strict) {
    const _name = typeof val === 'string' ? val : keyName(val);
    /** @param {string} key */
    const match = function (key) {
        if (_name === key) return true;
        const names = _name.split('+'),
            keys = key.split('+');
        if (names.pop() === keys.pop()) {
            if (!strict) return true;
            return keys.every((k) => names.includes(k));
        }
        return false;
    };
    return Array.isArray(name) ? name.find(match) || false : match(name) && name;
}
