import base64Url from './base64-url.js';
import blobFromFunction from './blob-from-fn.js';

/** @type {typeof $$.io.blobUrl} */
export default function blobUrl(data, contentType) {
    if (data == null) return null;

    if (data && typeof data === 'string' && data.includes(';base64,')) {
        return base64Url(data, contentType);
    } else {
        const type = $$.getClassBuiltIn(data);
        let blob;
        if (type === 'Function') {
            blob = blobFromFunction(data);
        } else if (type === 'Blob' || data instanceof Blob) {
            blob = data;
        } else {
            blob = new Blob([String(data)], { type: `${contentType || 'text/plain'},charset=UTF-8` });
        }
        return URL.createObjectURL(blob);
    }
}
