/** @jsxImportSource @gui/aui-devops */
import { define, Widget, Types } from '../../widget/widget.js';

import { ItemOptions, ItemObservers, GroupOptions, GroupObservers, Render, Group } from './choice.js';

/** @extends {Widget<typeof Checkbox.options>} */
@define('checkbox')
export class Checkbox extends Widget {
    static options = {
        ...ItemOptions,
        checked: Types.Enum(['mixed', true, false], false),
        willChange: Types.function,
    };
    static shadow = false; /// TD { delegatesFocus: true };
    // static formAssociated = true;
    static observers = [...ItemObservers];
    static requires = ['options._inGroup && value'];
    static upcasts = ['separate'];

    init() {
        this.state = { checked: this.options.checked };
        this.method = { getValue: this.getValue };
    }
    target() {
        return this.renderBox.querySelector('input');
    }
    didRender() {
        this.target().indeterminate = this.state.checked === 'mixed';
    }
    getValue = () => {
        const attr = this.target().getAttribute('aria-checked');
        return attr === 'mixed' ? attr : this.state.checked;
    };
    verify = () => {
        const value = this.getValue();
        return [value, value !== false];
    };
    onChange = (e) => {
        const { checked: lastChecked, value } = this.options;
        let { checked } = e.target,
            dirty = this.state.dirty;
        if (lastChecked === 'mixed') checked = true;
        const willChecked = this.callback('willChange', checked, value);
        if (willChecked != null && willChecked !== checked) {
            e.target.checked = willChecked;
            checked = willChecked;
        } else {
            dirty = true;
            this.callback('onChange', checked, value);
        }
        this.setState({ checked, dirty });
    };
    setOption(name, value) {
        if (name === 'checked') {
            if (this.state.checked === value) return false;
            this.state.checked = value;
        }
    }
    render() {
        return Render('checkbox', this, this.onChange);
    }
}

/** @extends {Widget<typeof CheckboxGroup.options>} */
@define('checkbox-group')
export class CheckboxGroup extends Group {
    static options = {
        ...GroupOptions,
    };
    static observers = [...GroupObservers];
    static requires = ['items'];
    static upcasts = ['block'];
    static shadow = false;

    onChange = (checked, value) => {
        const values = [];
        for (const item of this.state.items) {
            if (String(item.value) === String(value)) {
                item.checked = checked;
            }
            if (item.checked) values.push(item.value);
        }
        this.callback('onChange', values, this.oldValue);
        this.setState({
            dirty: true,
        });
        this.oldValue = values;
    };
    getValue() {
        const values = [];
        for (const item of this.state.items) {
            if (item.checked) {
                values.push(item.value);
            }
        }
        return values;
    }
    verify = () => {
        const value = this.getValue();
        return [value];
    };
    render() {
        return super.render('aui-checkbox', { role: 'group' });
    }
}
