/** @jsxImportSource @gui/aui-devops */
import $ from '../../core/element/index.js';
import { define, Widget } from '../../widget/widget.js';

import '../popup/pop.js';

import './overflow-menu.js';

import style from './overflow.less';

const MoreArias = { hasPopup: true };

/** @extends {Widget<typeof Overflow.options>} */
@define('overflow')
export class Overflow extends Widget {
    static styles = style;

    /** @abstract */
    I18N = $$.I18N.buttonfitbox;
    /** @abstract */
    classList = [];
    /** @abstract */
    clearOnHide = true;

    #resizeObserver;
    #slot;
    #popup;
    #menu;
    hiddenItemStyle = 'opacity: 0 !important; visibility: hidden !important; pointer-events: none !important;';

    init() {
        this.state = {
            gap: 0,
            moreSize: 0,

            overflow: false,
            boxSize: 0,
            mainSize: 0,
        };
    }
    didMount() {
        const root = this.shadowRoot,
            slot = root.querySelector('slot.main'),
            resizeObserver = new ResizeObserver(this.#onResize);
        resizeObserver.observe(this.host);
        resizeObserver.observe(slot);
        this.#resizeObserver = resizeObserver;
        this.#slot = slot;

        const more = root.getElementById('more');
        this.setState({ gap: Number.parseFloat(getComputedStyle(slot).rowGap), moreSize: this.getSize(more) }, false);
        this.#checkOverflow(this.getSize(this.host), this.getSize(slot));

        // delay to wait rendered finish.
        Promise.resolve(root.querySelector('slot[name="popup"]')).then((popupSlot) => {
            const $slot = $(popupSlot),
                $popup = $slot.find('aui-pop', { crossSlot: true });
            if (!$popup.length) return this.console.throws('Requires a <aui-pop slot="popup"> element, but not found.');
            const $menu = $popup.find('aui-overflow-menu', { crossShadow: true, crossSlot: true });
            this.#popup = $popup.get(0);
            this.#menu = $menu.get(0);
            $slot.on('Toggle', this.#onToggle);
        });
    }
    didUnmount() {
        this.#resizeObserver.disconnect();
    }

    /** @abstract */
    onMoreClick(e) {
        return true;
    }
    /** @abstract */
    onMenuItemClick(eventPath) {
        return true;
    }
    /** @abstract */
    clearOverflow() {
        this.dynamicStyle('');
    }
    /** @abstract */
    setOverflow(boxSize, mainSize) {
        this.setState({ overflow: true });
    }
    /** @abstract */
    cloneChild(child) {
        return child.cloneNode(true);
    }

    setMenuList(...children) {
        this.#menu.replaceChildren(...children);
    }
    menuItem(child, index) {
        child.setAttribute('role', 'menuitem');
        child.dataset.index = index;
        return child;
    }
    getSize(element) {
        // Maybe support for height with a new option, and ↑(rowGap).
        return element.getBoundingClientRect().width;
    }
    getChildren() {
        return this.#slot.assignedElements({ flatten: true });
    }
    togglePopup(isShow, trigger) {
        return this.#popup.toggle(isShow, trigger, trigger);
    }

    #onResize = (entries) => {
        const { boxSize, mainSize } = this.state,
            state = { boxSize, mainSize };
        for (const { target } of entries) {
            state[target.dataset.size ?? 'boxSize'] = this.getSize(target);
        }
        if (state.boxSize !== boxSize || state.mainSize !== mainSize) this.#checkOverflow(state.boxSize, state.mainSize);
    };
    #checkOverflow(boxSize, mainSize) {
        this.setState({ boxSize, mainSize }, false);
        return mainSize > boxSize ? this.setOverflow(boxSize, mainSize) : this.#clearOverflow();
    }
    #clearOverflow() {
        this.clearOverflow();
        if (!this.state.overflow) return false;
        this.setState({ overflow: false });
        return true;
    }
    #onToggle = (e) => {
        if (e.newState === 'closed' && this.clearOnHide) {
            const $popup = $(e.target).closest(':widget');
            if ($popup.length && $popup.is(this.#popup)) this.setMenuList();
        }
    };

    #onMoreClick = (e) => {
        if (this.onMoreClick(e)) this.togglePopup(true, e.currentTarget);
    };
    #onMenuClick = (e) => {
        const paths = e.composedPath(),
            menuIndex = paths.findIndex((p) => p.nodeType === Node.ELEMENT_NODE && p.localName === 'aui-overflow-menu');
        if (menuIndex > 0) {
            const eventPath = paths.slice(0, menuIndex);
            if (this.onMenuItemClick(eventPath)) this.togglePopup(false);
        }
    };

    render() {
        const { classList, I18N } = this,
            { overflow } = this.state;
        return (
            <>
                <div id="box" className={['box', ...classList]}>
                    <slot className="main" data-size="mainSize" />
                </div>
                <aui-button-lite
                    id="more"
                    type="bald"
                    icon="faui-ellipsis-dot"
                    tooltip={I18N.more}
                    disabled={!overflow}
                    aria-hidden={!overflow}
                    aria={MoreArias}
                    onClick={this.#onMoreClick}
                />
                <slot name="popup" onClick={this.#onMenuClick} />
            </>
        );
    }
}
