/** @jsxImportSource @gui/aui-devops */
import { define, Widget, Types } from '../widget.js';

/** @extends {Widget<typeof Form.options>} */
@define('form-lite')
export class Form extends Widget {
    static options = {
        name: Types.string,
        method: Types.string,
    };
    static observers = [];
    static styles = ':host{ display:block; }';

    #formData = {};
    create() {
        this.hostProto = { formData: this.getFormData };
    }
    getFormData = () => {
        return { ...this.#formData };
    };
    didMount() {
        this.element.addEventListener('input', this.onInput);
    }
    value(target) {
        const name = target.localName;
        if (name === 'select' || name === 'textarea') return target.value;
        if (name === 'input') {
            const { type } = target;
            switch (type) {
                case 'checkbox':
                case 'radio':
                    return target.checked;
                default:
                    return target.value;
            }
        }
        return null;
    }
    onChange = () => {
        this.host.dispatchEvent(new Event('change'));
    };
    onInput = (e) => {
        const [target] = e.composedPath(),
            name = target.name || target.getAttribute('name'),
            value = this.value(target);
        this.#formData[name] = value;
        $$.throttle(this.onChange)();
    };
    render() {
        const { name, method } = this.options;
        return (
            <form autoComplete="off" name={name} method={method}>
                <slot />
            </form>
        );
    }
}
