/** polyfill of Array.prototype.find */
export function arrayFind(arr, asc, cb) {
    const l = arr.length,
        acc = asc ? 1 : -1;
    let i = asc ? 0 : l - 1;
    for (i; i < l && i >= 0; i += acc) {
        const v = arr[i],
            match = cb(v, i);
        if (match) return v;
    }
    return null;
}

/** loop array until return a boolean result, always returns boolean value. */
export function arrayResult(arr, cb) {
    const l = arr.length;
    for (let i = 0; i < l; i++) {
        const v = cb(arr[i], i, l);
        if (typeof v === 'boolean') return v;
    }
    return false;
}
