import { error } from '../../core/base/log.js';

import { isNumber, isObject } from '../type/types.js';

import load from './load.js';

/** @type {typeof $$.img.scaleBase64} */
export default function scaleBase64(options, callback) {
    const { data, shape = 'rect', size, keepFormat, ifNeed } = options,
        canvas = document.createElement('canvas'),
        context = canvas.getContext('2d');
    let type = keepFormat ? data.split(';', 1)[0].split(':', 2)[1] : 'image/png';
    if (type.includes('jpg')) type = 'image/jpeg';

    function drawRect(img, width, height) {
        canvas.width = width;
        canvas.height = height;
        context.drawImage(img, 0, 0, width, height);
    }

    function shouldResize(ratios) {
        switch (ifNeed) {
            case 1:
                return ratios.some((r) => r > 1);
            case -1:
                return ratios.some((r) => r < 1);
            default:
                return true;
        }
    }
    const drawByShape = {
        rect(size, img, imgWidth, imgHeight) {
            const targetWidth = size.width;
            const targetHeight = size.height;

            if (targetWidth && targetHeight) {
                const ratioW = targetWidth / imgWidth,
                    ratioH = targetHeight / imgHeight;
                if (shouldResize([ratioW, ratioH])) {
                    imgWidth = targetWidth;
                    imgHeight = targetHeight;
                }
            } else if (targetWidth) {
                const ratio = targetWidth / imgWidth;
                if (shouldResize([ratio])) {
                    imgHeight = ratio * imgHeight;
                    imgWidth = targetWidth;
                }
            } else if (targetHeight) {
                const ratio = targetHeight / imgHeight;
                if (shouldResize([ratio])) {
                    imgWidth = ratio * imgWidth;
                    imgHeight = targetHeight;
                }
            }
            drawRect(img, imgWidth, imgHeight);
        },
        square(size, img, imgWidth, imgHeight) {
            const _size = size.width,
                min = Math.min(imgWidth, imgHeight),
                ratio = _size / min;
            imgWidth = imgHeight = !ifNeed || (ifNeed === 1 && ratio > 1) || (ifNeed === -1 && ratio < 1) ? _size : min;

            drawRect(img, imgWidth, imgHeight);
        },
        circle(size, img, imgWidth, imgHeight) {
            const _size = size.width,
                min = Math.min(imgWidth, imgHeight),
                ratio = _size / (min / 2);
            const diameter = !ifNeed || (ifNeed === 1 && ratio > 1) || (ifNeed === -1 && ratio < 1) ? _size : min / 2;
            const r = diameter / 2;
            canvas.width = canvas.height = diameter;
            context.clearRect(0, 0, diameter, diameter);
            context.save();
            context.beginPath();
            context.arc(r, r, r, 0, Math.PI * 2);
            context.clip();
            context.drawImage(img, 0, 0, diameter, diameter);
            context.restore();
        },
    };

    function onLoad(img) {
        const _size = isNumber(size) && size > 0 ? { width: size } : isObject(size) ? size : null;
        if (!_size) return error('The size is incorrect, please modify the value!');

        const draw = drawByShape[shape];
        if (draw) draw(_size, img, img.width, img.height);
        if (callback) callback(canvas.toDataURL(type));
    }
    load(data).then(onLoad);
}
