class Datepicker extends R.Datepicker {
    constructor(props) {
        super(props);
        this.timezones = [];
        this.setSelectedTimezone(this.props.selectedTimeZone);
        this.oldZone = null;
        this.state = {
            selectedTimeZone: this.props.selectedTimeZone,
            timezones: [].concat(this.timezones),
        };
    }
    componentUpdate(prevProps) {
        if (prevProps.selectedTimeZone != this.props.selectedTimeZone) {
            this.setSelectedTimezone(this.props.selectedTimeZone);
            this.setState({
                timezones: [].concat(this.timezones),
                selectedTimeZone: this.props.selectedTimeZone,
            });
        }
    }
    setSelectedTimezone(selectedTimeZone) {
        this.timezones = $.extend(true, [], $$.I18N.timezones);
        this.timezones.forEach((t) => {
            t.checked = t.checked || false;
            if (selectedTimeZone && t.id === selectedTimeZone.id) {
                t.checked = true;
            }
        });
    }
    timzoneChange = (args) => {
        $.extend(true, this.oldZone, this.state.selectedTimeZone);
        this.setState({
            selectedTimeZone: Object.assign({}, args.newValue),
        });
    };
    savingTimeChanged = (e) => {
        $.extend(true, this.oldZone, this.state.selectedTimeZone);
        this.state.selectedTimeZone.autoAdjustClock = e.target.checked;

        this.setState({ selectedTimeZone: Object.assign({}, this.state.selectedTimeZone) });
    };
    getExtendFieldValue() {
        if (!this.props.hasTimeZone) return false;
        return {
            newValue: { zone: this.state.selectedTimeZone },
            oldValue: { zone: this.props.selectedTimeZone },
        };
    }
    getExtendField() {
        return (
            <>
                {this.props.hasTimeZone && (
                    <>
                        <div className="">{$$.I18N.datepicker.timeZone}</div>
                        <R.Combobox textField="displayName" items={this.state.timezones} onChange={this.timzoneChange} />
                        {this.state.selectedTimeZone?.supportsDaylightSavingTime && (
                            <label className="">
                                <input type="checkbox" checked={this.state.selectedTimeZone?.autoAdjustClock || false} onChange={this.savingTimeChanged} />
                                {$$.I18N.datepicker.savingTime}
                            </label>
                        )}
                    </>
                )}
            </>
        );
    }
}

R.Datepicker = Datepicker;
