/** @jsxImportSource @gui/aui-devops */
import { define, Widget, Types } from '../../widget/widget.js';

/** @extends {Widget<typeof Icon.options>} */
@define('icon')
export class Icon extends Widget {
    static options = {
        icon: Types.string,
        circle: Types.boolean,
        color: Types.string,
        loading: Types.Enum([true, false, 'replace'], false),
        shadow: Types.boolean,
        size: Types.Enum(['s', 'm', 'l', 'xl'], 's'),
        solid: Types.boolean,
        tooltip: Types.string,
    };

    static shadow = false;
    static observers = ['icon', 'color', 'loading', 'size', 'solid', 'tooltip'];
    static requires = ['icon'];
    static upcasts = ['circle', 'size', 'shadow', 'solid'];

    colorArgs(color) {
        const args = { classList: [], style: {} };
        if (typeof color === 'string' && color) {
            const cssKey = 'text-' + color;
            if (/^[a-z]{3,}/.test(color)) {
                args.classList.push(cssKey);
            } else {
                Object.assign(args.style, { color });
            }
        }
        return args;
    }

    loading() {
        const { loading } = this.options;
        if (!loading) return null;
        return <div className="aui-icon-loading" role="progressbar" aria-busy={!!loading} aria-live="assertive" data-mode={loading} />;
    }

    render() {
        const { icon, color, tooltip } = this.options,
            { classList, style } = this.colorArgs(color);

        return (
            <div className={['aui-icon', ...classList]} aria-description={tooltip} data-tooltip={tooltip ? true : null} style={style}>
                <span className={icon} />
                {this.loading()}
            </div>
        );
    }
}
