import React, { PureComponent } from 'react';

import boxSizeStyle from '../../util/css/box-size-style.js';

export class PureTable extends PureComponent {
    header() {
        const cols = [],
            ths = [];
        this.props.columns.forEach((col, i) => {
            let { width } = col;
            if (!Number.isNaN(Number(width))) width += 'px';
            cols.push(<col style={{ width }} key={'col-' + i} />);
            ths.push(<th key={'th-' + i}>{col.headerTemplate ?? col.header ?? ''}</th>);
        });
        return { cols, ths };
    }
    render() {
        const props = this.props,
            className = ['aui-puretable'],
            style = boxSizeStyle(props.width, props.height);
        const { cols, ths } = this.header();
        if (props.compact) className.push('aui-puretable-compact');
        return (
            <div className="aui-puretable-box" style={style} tabIndex="0">
                <table className={[className.join(' ')]}>
                    <colgroup>
                        {cols}
                        <col />
                    </colgroup>
                    <thead>
                        <tr>
                            {ths}
                            <th role="cell" />
                        </tr>
                    </thead>
                    <tbody>
                        {props.items.map((item, i) => (
                            <tr key={'row-' + i} {...(item.tr || {})}>
                                {props.columns.map((col, j) => (
                                    <td data-col={j + 1} data-cell={i + 1 + ',' + (j + 1)} key={`row-${i}-cell-${j}`}>
                                        {$$.fn(col.render)(item, col)}
                                    </td>
                                ))}
                                <td />
                            </tr>
                        ))}
                    </tbody>
                </table>
            </div>
        );
    }
}

$$.shell.define('PureTable', PureTable);
