export default function classList(...args) {
    const val = args[0];
    // eslint-disable-next-line aui/ternary-nesting
    let list = args.length > 1 ? args : typeof val === 'string' ? val.split(' ') : Array.isArray(val) ? val : [];
    list = list.flatMap((x) => (Array.isArray(x) ? x : [x]).filter((y) => !!y));
    list = list.flatMap((x) => (typeof x === 'string' ? x.replaceAll('.', '').trim().split(' ') : [x.replaceAll('.', '')]));
    return list;
}
