import { error, throws } from '../../core/base/log.js';

const MaxUint32 = 0xffffffff,
    MaxRange = MaxUint32 + 1;

function toInt(val) {
    if (Number.isInteger(val)) return val;
    const intVal = Number.parseInt(val, 10);
    error(new TypeError(`Converted non-integer value "${val}" to "${intVal}" for random range.`));
    return intVal;
}

/** @type {typeof $$.number.random} */
export default function random(min, max) {
    if (!Number.isFinite(min) || !Number.isFinite(max)) return throws('Range values must be finite numbers.', TypeError);
    min = toInt(min);
    max = toInt(max);
    if (min === max) return min;

    if (min > max) [min, max] = [max, min];
    const range = max - min + 1;
    if (range > MaxRange) return throws('Range is too large.', RangeError);

    const limit = Math.floor(MaxRange / range) * range,
        arr = new Uint32Array(1);
    let x;
    do {
        crypto.getRandomValues(arr);
        x = arr[0];
    } while (x >= limit);

    return min + (x % range);
}
