import React, { PureComponent } from 'react';
import { createPortal } from 'react-dom';

import { WR } from '../../widget/widget.jsx';

import { getOrCreateToaster } from './utils.js';

export class Toast extends PureComponent {
    constructor(props) {
        super(props);
        this.toaster = getOrCreateToaster();
    }

    render() {
        const { children, ...rest } = this.props;
        const toast = (
            <WR.Toast {...rest} stable>
                {children}
            </WR.Toast>
        );

        return createPortal(toast, this.toaster);
    }
}

$$.shell.define('Toast', Toast);
