import { I18N } from '../../core/base/i18n.js';

import padStart from '../string/pad-start.js';

import { getFormat } from './formats.js';

const Char = {
    left: '\u169C',
    right: '\u169B',
};
const _parseDate = (date) => ({
    D: date.getDate(),
    d: date.getDay(),
    M: date.getMonth(),
    Y: date.getFullYear(),
    h: date.getHours(),
    m: date.getMinutes(),
    s: date.getSeconds(),
});

/** @type {typeof $$.date.format} */
export default function format(date, f) {
    const _I18N = I18N.calendar,
        result = [],
        data = _parseDate(new Date(date));
    let format = String(f || getFormat()),
        start = -1;

    const doMatch = (reg, cb) => {
        const match = format.match(reg);
        if (match) {
            const m = match[0],
                v = cb(m.length);
            if (v) {
                start++;
                format = format.replace(m, Char.left + start + Char.right);
                result[start] = v;
            }
        }
    };

    // Hour: h=>1~12, hh=>01~12.
    doMatch(/(h+)/, (l) => {
        let hour = data.h;
        if (hour > 12) hour = data.h % 12;
        if (hour === 0) hour = 12;
        return padStart(hour, l);
    });
    // Hour: H=>0~23, HH=>00~23.
    doMatch(/(H+)/, (l) => padStart(data.h, l));
    // Minute: m=>0~59, mm=>00~59.
    doMatch(/(m+)/, (l) => padStart(data.m, l));
    // Second: s=>0~59, ss=>00~59.
    doMatch(/(s+)/, (l) => padStart(data.s, l));
    // Year: yy=>sortYear@deprecated, yyyy=>fullYear.
    doMatch(/(yy+)/, (l) => String(data.Y).slice(4 - l));
    // Week: ddd=>shortWeek, dddd=>fullWeek.
    doMatch(/(ddd+)/, (l) => _I18N[l > 3 ? 'weeks' : 'middleWeeks'][data.d]);
    // Day: d=>1~31, dd=>01~31.
    doMatch(/(d+)/, (l) => l < 3 && padStart(data.D, l));
    // Month: M=>1~12, MM=>01~12, MMM=>shortMonth, MMMM=>fullMonth.
    doMatch(/(M+)/, (l) => [data.M + 1, padStart(data.M + 1), _I18N['shortMonths'][data.M], _I18N['months'][data.M]][l - 1]);
    // AM or PM. 12AM=0, 12pm=12.
    doMatch(/(tt+)/, (l) => (data.h >= 12 ? _I18N.pm : _I18N.am));

    format = format.replaceAll(new RegExp(Char.left + String.raw`(\d)` + Char.right, 'g'), (str, p1) => result[Number.parseFloat(p1)]);
    return format;
}
