import AriaProp2Attr from '../misc/aria-map.json';

import objectForEach from './object/for-each.js';
import { isPrimitive } from './type/types.js';

const AriaProperties = [],
    AriaAttributes = [],
    AriaAttr2Prop = {};
for (const [key, value] of Object.entries(AriaProp2Attr)) {
    AriaProperties.push(key);
    AriaAttributes.push(value);
    AriaAttr2Prop[value] = key;
}

export { AriaProperties, AriaAttributes, AriaAttr2Prop, AriaProp2Attr };

/** @type {typeof $$.arias} */
export function arias(val, force) {
    const obj = {};
    if (val != null) {
        const valid = (v) => v || v === false;
        if (typeof val === 'object') {
            objectForEach(val, function (k, v) {
                if (k === 'role') {
                    obj.role = v;
                } else {
                    if (AriaProp2Attr[k]) {
                        if (isPrimitive(v)) {
                            k = AriaProp2Attr[k];
                        } else {
                            obj[k] = v;
                            return true;
                        }
                    } else {
                        k = 'aria-' + k.toLowerCase().replace(/^aria-?/, '');
                    }
                    if ((force || valid(v)) && AriaAttributes.includes(k)) obj[k] = String(v);
                }
            });
        } else if (isPrimitive(val) && valid(val)) {
            val = String(val);
            if (val.startsWith('#')) {
                obj['aria-labelledby'] = val.replaceAll('#', ' ').trim();
            } else {
                obj['aria-label'] = val;
            }
        }
    }
    return obj;
}
