/** @jsxImportSource @gui/aui-devops */
import { addTooltip } from '../../core/module/tooltip.js';
import { define, Widget, Types } from '../../widget/widget.js';

import arrayAt from '../../util/array/at.js';
import loop from '../../util/array/loop.js';
import arraySort from '../../util/array/sort.js';
import { keyName } from '../../util/event/key-name.js';
import fixFloat from '../../util/number/fix-float.js';
import round from '../../util/number/round.js';
import extendNull from '../../util/object/extend-null.js';

import { TooltipNode } from './modules/index.js';
import { NS, Colors, TooltipClassName, Format, Action, TabloopArgs, CoordPlane2CSS, TagObject } from './modules/utils.js';

import style from './radar.less';

const DefaultAxisRows = 5,
    Diameter = 200,
    Radius = Diameter / 2,
    BaseSize = 240, // the default size of main part
    SeriesRadius = BaseSize / 2,
    CircleRadius = 4,
    SeriesMargin = 16;
const Pos = (v, basis = Radius) => (v === basis ? 'center' : v < basis ? 'start' : 'end');

/** @extends {Widget<typeof Radar.options>} */
@define(`${NS}-radar`)
export class Radar extends Widget {
    static options = {
        items: Types.array,
        grid: Types.Enum(['polygon', 'circle'], 'polygon'),
        color: Types.Union([Types.array, Types.Color]),

        maxValue: Types.number,
        axisInterval: Types.number,
        axisLabelFormat: Types.Union([Types.string, Types.function]),
        valueFormat: Types.Union([Types.string, Types.function]),
        showSeries: true,

        groupField: 'group',
        nameField: 'name',
        valueField: 'value',
        colorField: 'color',
    };
    static observers = ['items', 'color', 'maxValue', 'axisInterval'];
    static styles = style;

    #cache = {
        byName: null,
        byGroup: null,
        tooltip: {},
        pointerItem: null,
    };

    init() {
        const { valueFormat } = this.options;
        this.state = {
            valueFormat: Format(valueFormat),
            callback: {},
            useSeriesClick: false,
        };
        this.dispatcher = this.useUnicom(['box', 'radar'], this.dataReceiver);
        this.dispatcher('box', 'getCallback').then((callback) => this.setState({ callback, useSeriesClick: !!callback.onSeriesClick }));
    }
    dataReceiver = (action, from, ...args) => {
        $$.fn(this.action?.[action])(...args);
    };
    didMount() {
        addTooltip(this.host);
        this.action = Action(this.$element, 'key');
    }
    setOption(name, value, oldValue) {
        if (name === 'items') {
            this.dispatcher('legend?', 'clearData');
        }
    }

    onDataClick(target) {
        const { key } = target.dataset,
            { byGroup } = this.#cache,
            values = byGroup.get(key);
        this.dispatcher('box', 'onDataClick', TagObject('ChartItemGroup', { group: key, values }));
    }
    onItemPointerDown = (e) => {
        this.#cache.pointerItem = e.currentTarget;
    };
    onItemPointerUp = (e) => {
        const target = e.currentTarget,
            cache = this.#cache;
        if (cache.pointerItem === e.currentTarget) this.onDataClick(target);
        cache.pointerItem = null;
    };
    onSeriesClick = (e) => {
        if (!this.state.useSeriesClick) return;
        const content = e.target.textContent,
            { byGroup } = this.#cache;
        const [...allData] = byGroup.values(),
            values = allData.flat().filter((item) => item.name === content);
        this.dispatcher('box', 'onSeriesClick', values);
    };
    onSeriesKeyDown = (e) => {
        if (!this.state.useSeriesClick) return;
        const name = keyName(e, true);
        if (name === 'Space' || name === 'Enter') {
            e.preventDefault();
            e.target.waitUptoClick = true;
        }
    };
    onSeriesKeyUp = (e) => {
        if (this.state.useSeriesClick && e.target.waitUptoClick) {
            delete e.target.waitUptoClick;
            this.onSeriesClick(e);
        }
    };

    #moveTo(item, index) {
        const { parentElement } = item,
            { children } = parentElement,
            target = Array.from(children).at(index);
        if (target === item) return false;
        parentElement.insertBefore(item, index >= 0 ? target : null);
        return true;
    }
    onItemFocus = (e) => {
        const item = e.currentTarget;
        if (this.#moveTo(item, -1)) item.focus({ focusVisible: true });
    };
    onItemBlur = (e) => {
        const item = e.currentTarget,
            { index } = item.dataset;
        this.#moveTo(item, Number(index));
    };
    onSeriesFocus = (e) => {
        const { name } = e.currentTarget.dataset;
        this.#highlightSeries(name);
    };
    onSeriesBlur = (e) => {
        this.#highlightSeries();
    };
    #highlightSeries(name) {
        this.$element.findAll('.hover').removeClass('hover');
        if (name) {
            this.$element.find(`.tooltip-stack[data-name="${name}"]`).addClass('hover');
            const $items = this.$element.findAll(`.graph-coord[data-name="${name}"]`).addClass('hover');
            return $items.toArray();
        }
    }
    onTooltipShow = (tooltipStack) => {
        const { name } = tooltipStack.dataset,
            cache = this.#cache.tooltip[name];
        if (cache) return cache;
        this.onTooltipHide();
        const items = this.#highlightSeries(name);
        this.#cache.tooltip[name] = items;
        return items;
    };
    onTooltipHide = () => {
        this.#highlightSeries();
        this.#cache.tooltip = {};
    };

    #parseData() {
        const { items, color, maxValue, axisInterval, groupField, nameField, valueField, colorField } = this.options,
            { valueFormat } = this.state,
            { error } = this.console,
            colors = Colors(color),
            types = ['solid', 'dashed'],
            legends = [],
            _maxValue = Math.max(Number(maxValue) || 0, 0),
            groupData = new Map(),
            names = new Map(); // cache name item data (color only for now).

        let total = 0,
            colorIndex = 0;
        // 1n: create group data.
        items.forEach((item, i) => {
            const group = item[groupField],
                name = item[nameField],
                value = item[valueField],
                color = item[colorField];
            if (typeof value !== 'number') return error('Data value type must be number, it will be ignored.', item);
            total += value;
            const _item = { name, value, color, group, type: types.find((t) => t === item.type) ?? 'solid', original: item };
            groupData.set(group, (groupData.get(group) || []).concat(_item));
            names.set(name, extendNull(names.get(name) || {}, _item));
        });

        let __maxValue = _maxValue;
        // 2n: get max value from group (stack maybe).
        groupData.forEach((arr, key) => {
            const values = [0],
                item = arr[0];
            if (!item.color) item.color = arrayAt(colors, colorIndex++, true);
            legends.push(Object.assign(item, { val: valueFormat(item.value) }));
            arr.forEach((x) => {
                x.color = item.color;
                values.push(x.value);
            });
            __maxValue = Math.max(__maxValue, ...values);
        });

        // 3n: sort.
        // eslint-disable-next-line unicorn/consistent-function-scoping
        function calcAreaByItems([name, items]) {
            let area = 0;
            const { length } = items;
            for (let i = 1; i < length; i++) {
                const { value: prev } = items[i - 1],
                    { value } = items[i];
                area += prev + value;
            }
            return area;
        }
        const sortedGroupData = new Map(arraySort([...groupData.entries()], false, null, calcAreaByItems)),
            [..._items] = sortedGroupData.values();

        let tickCount = DefaultAxisRows;
        // part3: adjust max value by interval.
        if (axisInterval) {
            if (__maxValue > _maxValue) {
                __maxValue = round(__maxValue, axisInterval, 'up');
            } else if (__maxValue === 0) {
                __maxValue = axisInterval;
            }
            tickCount = __maxValue / axisInterval;
        } else {
            __maxValue = round(__maxValue, DefaultAxisRows, 'up');
            if (__maxValue === 0) tickCount = __maxValue = 1;
        }

        this.#cache.byName = names;
        this.#cache.byGroup = sortedGroupData;
        this.dispatcher('legend?', 'setData', [total, valueFormat(total)], legends, 'group');

        // items: Array<Item[]>, grouped by group; non-group is Array<[Item]>.
        return { items: _items, dimensions: names.size, maxValue: __maxValue, tickCount };
    }
    #coordByIndex(index, count, r = Radius) {
        const rad = (2 * Math.PI) / count,
            angle = rad * index,
            x = r * Math.cos(angle),
            y = r * Math.sin(angle);
        return [fixFloat(x) || 0, fixFloat(y) || 0];
    }
    #graphCoords(n, maxValue) {
        return (items) => items.map(({ value }, i) => this.#coordByIndex(i, n, (value / maxValue) * Radius));
    }
    #polygonCoords(n, showSeries) {
        const polygon = [],
            series = [];
        loop(n, (i) => {
            polygon.push(this.#coordByIndex(i, n));
            if (showSeries) series.push(CoordPlane2CSS(this.#coordByIndex(i, n, SeriesRadius + SeriesMargin), SeriesRadius));
        });
        return { polygon, series };
    }
    #polygonLinePath(coords) {
        if (!coords.length) return null;
        const [start, ...points] = coords;
        if (!points.length) points.push([0, 0]);
        const path = `M${start.join(',')} L${points.join(' ')} Z`,
            result = { d: path };
        if (/^M0,0 L(0,0 ){2,}Z$/.test(path)) {
            const r = CircleRadius + 1,
                d = r * 2;
            result.d = `M0,0 m-${r},0 a${r},${r} 0 1,1 ${d},0 a${r},${r} 0 1,1 -${d},0`;
            result['fill-opacity'] = 0.5;
        }
        return result;
    }
    #rhombusPath(midPrev, point, midNext) {
        const path = `M0,0 L${midPrev[0]},${midPrev[1]} ${point[0]},${point[1]} ${midNext[0]},${midNext[1]} Z`;
        return <svg:path className="rhombus" d={path} />;
    }
    #loopDimensions(n, polygon, items) {
        const [firstGroup] = items,
            midPoints = [],
            rhombuses = [];
        loop(n, (i) => {
            const { name } = firstGroup[i],
                point = polygon[i],
                pointNext = arrayAt(polygon, i + 1, true),
                midNext = [(point[0] + pointNext[0]) / 2, (point[1] + pointNext[1]) / 2];
            const rhombus = (
                <svg:g className={['rhombus-stack', TooltipClassName.Stack]} data-name={name}>
                    <svg:line className="radial-line grid-line" x1="0" y1="0" x2={point[0]} y2={point[1]} />
                </svg:g>
            );
            if (midPoints.length) {
                const midPrev = midPoints.at(-1),
                    path = this.#rhombusPath(midPrev, point, midNext);
                rhombus.append(path);
            }
            midPoints.push(midNext);
            rhombuses.push(rhombus);
        });
        rhombuses[0].append(this.#rhombusPath(midPoints.at(-1), polygon[0], midPoints[0]));
        return { radialRhombuses: rhombuses };
    }
    #loopTicks(n, maxValue) {
        const { axisLabelFormat } = this.options;
        const tickLabels = [],
            tickLines = [];
        const labelFormat = Format(axisLabelFormat);

        loop(n, (i) => {
            const value = (maxValue / n) * (n - i);
            tickLabels.push(
                <svg:text x={Radius} y={fixFloat((Radius * i) / n)}>
                    {labelFormat(value)}
                </svg:text>
            );
            const size = (Diameter / n) * (i + 1);
            tickLines.push(<svg:use className="grid-line" href="#polygon" width={size} height={size} />);
        });
        tickLabels.push(
            <svg:text x={Radius} y={Radius}>
                {labelFormat(0)}
            </svg:text>
        );
        return { tickLabels, tickLines };
    }

    render() {
        const { items, dimensions, maxValue, tickCount } = this.#parseData(),
            { grid, groupField, showSeries } = this.options,
            { valueFormat, useSeriesClick } = this.state,
            { polygon, series } = this.#polygonCoords(dimensions, showSeries),
            graphCoords = this.#graphCoords(dimensions, maxValue),
            { radialRhombuses } = this.#loopDimensions(dimensions, polygon, items),
            { tickLabels, tickLines } = this.#loopTicks(tickCount, maxValue);

        const viewBox = `0 0 ${Diameter} ${Diameter}`;
        // transform from Plane-CoordinateSystem to CSS-CoordinateSystem.
        const transform = `rotate(-90) translate(${Radius},${Radius})`;

        // 3n: create dom
        // Set axis at last to keep sticky context order.
        return (
            <>
                <aui-tabloop className="radar" {...TabloopArgs} filterQuery=".series-label">
                    <svg:svg className={['stack-box', showSeries && 'show-series']} style={{ '--size': BaseSize + 'px', '--gap': Math.max(0, SeriesRadius - Radius) + 'px' }}>
                        {showSeries && (
                            <svg:svg className={['series-box', useSeriesClick && 'with-callback']} viewBox={`0 0 ${BaseSize} ${BaseSize}`}>
                                {series.map(([x, y], i) => {
                                    const { name } = items[0][i];
                                    return (
                                        <svg:foreignObject width="1" height="1" x={x} y={y}>
                                            <section className={['series-point', 'x-' + Pos(x, SeriesRadius), 'y-' + Pos(y, SeriesRadius)]}>
                                                <div
                                                    className="series-label ellipsis"
                                                    data-tooltip="ifneed"
                                                    tabIndex={useSeriesClick ? (i ? -1 : 0) : null}
                                                    data-name={name}
                                                    onFocus={this.onSeriesFocus}
                                                    onBlur={this.onSeriesBlur}
                                                    onClick={this.onSeriesClick}
                                                    onKeyDown={this.onSeriesKeyDown}
                                                    onKeyUp={this.onSeriesKeyUp}
                                                >
                                                    {name}
                                                </div>
                                            </section>
                                        </svg:foreignObject>
                                    );
                                })}
                            </svg:svg>
                        )}
                        <svg:svg className="main" viewBox={viewBox}>
                            <svg:symbol id="polygon" viewBox={viewBox}>
                                {grid === 'circle' ? (
                                    <svg:circle vector-effect="non-scaling-stroke" cx={0} cy={0} r={Radius} />
                                ) : (
                                    <svg:path vector-effect="non-scaling-stroke" {...this.#polygonLinePath(polygon)} />
                                )}
                            </svg:symbol>

                            <svg:g className="axis-line" transform={transform}>
                                {tickLines}
                            </svg:g>
                            <svg:g className="radial-rhombus" transform={transform}>
                                {radialRhombuses}
                            </svg:g>
                            <svg:g className="axis-label">{tickLabels}</svg:g>
                            <svg:foreignObject className="stack-graph" width="100%" height="100%">
                                <aui-tabloop {...TabloopArgs} bubbles={false} orderAttr="data-order">
                                    <svg:svg viewBox={viewBox}>
                                        <svg:g transform={transform}>
                                            {items.map((group, i, { length: count }) => {
                                                const order = i + 1,
                                                    first = group?.[0] || {},
                                                    coords = graphCoords(group);
                                                return (
                                                    <svg:g
                                                        className="item"
                                                        tabIndex={count - order > 0 ? -1 : 0}
                                                        data-index={i}
                                                        data-order={count - i}
                                                        data-key={first.group}
                                                        style={{ color: first.color }}
                                                        onFocus={this.onItemFocus}
                                                        onBlur={this.onItemBlur}
                                                        onPointerDown={this.onItemPointerDown}
                                                        onPointerUp={this.onItemPointerUp}
                                                    >
                                                        <svg:path className="graph" data-type={first.type} {...this.#polygonLinePath(coords)} />
                                                        <svg:g>
                                                            {coords.map(([x, y], j) => {
                                                                const data = {
                                                                    name: group[j].name,
                                                                    value: group[j].value,
                                                                    group: first.group,
                                                                    type: first.type,
                                                                    color: first.color,
                                                                };
                                                                Object.assign(data, { stack: data.name, val: valueFormat(data.value) });
                                                                return <svg:circle className="graph-coord" cx={x} cy={y} r={CircleRadius} data={data} />;
                                                            })}
                                                        </svg:g>
                                                    </svg:g>
                                                );
                                            })}
                                        </svg:g>
                                    </svg:svg>
                                </aui-tabloop>
                            </svg:foreignObject>
                        </svg:svg>
                    </svg:svg>
                </aui-tabloop>
                <TooltipNode field={groupField} groupMode groupTabLoop={false} useStack throttle={false} onShow={this.onTooltipShow} onHide={this.onTooltipHide} />
            </>
        );
    }
}
