import { I18N } from '../../core/base/i18n.js';

import converter from './converter.js';

/** @type {typeof $$.date.dateDuration} */
export default function dateDuration(start, end) {
    const since = end - start,
        _I18N = I18N.core.duration;

    if (since < converter.second) {
        return since + ' ' + _I18N.ms;
    } else if (since < converter.min) {
        return Math.floor(since / converter.second) + ' ' + _I18N.second;
    } else if (since < converter.hour) {
        return Number.parseFloat((since / converter.min).toFixed(1)) + ' ' + _I18N.min;
    } else if (since + 1 < converter.day || since < converter.day) {
        return Number.parseFloat((since / converter.hour).toFixed(1)) + ' ' + _I18N.hour;
    } else if (since < converter.week) {
        return Number.parseFloat((since / converter.day).toFixed(1)) + ' ' + _I18N.day;
    } else {
        return Number.parseFloat((since / converter.week).toFixed(1)) + ' ' + _I18N.week;
    }
}
