import { warn, error } from '../core/base/log.js';

import arrayLike from './array/is-like.js';

/** @type {typeof $$.getUniqueElement} */
export default function getUniqueElement(query, crossFrame) {
    if (!query) return null;
    const type = $$.getClassBuiltIn(query);
    if (type === 'Element' || /^HTML[a-zA-Z]*Element$/.test(type)) return query;
    if (type === 'String') {
        const selector = (query[0] === '#' || query[0] === '.' ? '' : '#') + query;
        let result = document.querySelectorAll(selector);
        if (result.length === 1) return result[0];
        if (result.length) {
            error(`The query element of:"${query}" is not unique in the whole document! Please check your code.`);
        } else {
            if (crossFrame) {
                warn('You are about to get element cross frame insecurely. Requires [allow-top-navigation] policy at least!');
                const frames = window.top.frames;
                // eslint-disable-next-line @typescript-eslint/prefer-for-of
                for (let i = 0; i < frames.length; i++) {
                    result = frames[i]?.document?.querySelectorAll(selector);
                    if (result?.length) return result[0];
                }
            }
            error(`The query element of:"${query}" is not exist! Please check your code.`);
        }
    } else if (arrayLike(query)) {
        let result;
        for (const item of query) {
            result = getUniqueElement(item, crossFrame);
            if (result) return result;
        }
    }
    return null;
}
