import forEach from './for-each.js';

/** @type {typeof $$.object.extendScope} */
export default function extendScope(target, ...sources) {
    forEach(target, function (k, v) {
        for (const obj of sources) {
            if (obj && Object.hasOwn(obj, k)) target[k] = obj[k];
        }
    });
    return target;
}
