/** @jsxImportSource @gui/aui-devops */
import $ from '../../core/element/index.js';
import { define, Widget, Types } from '../../widget/widget.js';

import fixFloat from '../../util/number/fix-float.js';
import { percent } from '../../util/number/percent.js';

import { LinearData } from './linear.js';
import { TooltipNode } from './modules/index.js';
import { NS, TooltipClassName, Format, TabloopArgs } from './modules/utils.js';

import style from './pie.less';

const I18N = $$.I18N.chart;

/**
 * sweep-flag of path arc curve.
 * - `1`: clockwise turning.
 * - `0`: counterclockwise turning.
 */
const PathTurn = (v) => (v ? 1 : 0);
const GapRad = 0.02;

/** @extends {Widget<typeof Pie.options>} */
@define(`${NS}-pie`)
export class Pie extends LinearData {
    static options = {
        items: Types.array,
        type: Types.Enum(['pie', 'donut'], 'pie'),
        color: Types.Union([Types.array, Types.Color]),
        size: 200,
        thickness: 40,

        seriesTick: Types.Enum([true, false, 'content'], 'content'),
        valueFormat: Types.Union([Types.string, Types.function]),
        centralHeader: Types.Union([Types.boolean, Types.string], false),
        centralFormat: Types.Union([Types.string, Types.function]),
        showSeries: false,

        nameField: 'name',
        valueField: 'value',
        colorField: 'color',
    };
    static observers = ['items', 'color'];
    static styles = style;

    init() {
        const { type, size, thickness, valueFormat, centralFormat } = this.options,
            radius = size / 2;
        this.state = {
            isDonut: type === 'donut',
            size,
            radius,
            thickness: Math.min(thickness, radius),
            valueFormat: Format(valueFormat),
            centralFormat: Format(centralFormat ?? valueFormat),
        };
        this.dispatcher = this.useUnicom(['box', 'pie'], this.dataReceiver);
    }

    #arcPath(total, useGap) {
        /** @returns {[x:number, y:number]} */
        const pointByAngle = (r, rad) => [fixFloat(r * Math.cos(rad)), fixFloat(r * Math.sin(rad))];
        const gapRad = useGap ? GapRad / 2 : 0;
        const rad = (v, gapTurn) => (v / total) * Math.PI * 2 + gapRad * gapTurn;
        const largeArc = (v) => (v * 2 > total ? 1 : 0);
        const fixOverlap = ([startX, startY], [endX, endY]) => {
            let end = `${endX},${endY}`;
            if (startX === endX && startY === endY) {
                const positive = !Object.is(endY, -0) && endY >= 0,
                    _endY = 0.001 * (positive ? 1 : -1);
                end = `${endX},${_endY} L${end}`;
            }
            return [`${startX},${startY}`, end];
        };

        return {
            pie: (basic, value) => {
                if (!value) return null;
                const { radius } = this.state,
                    large = largeArc(value),
                    turn = PathTurn(true);
                const m = pointByAngle(radius, rad(basic, 1)),
                    n = pointByAngle(radius, rad(basic + value, -1)),
                    [start, end] = fixOverlap(m, n);

                const path = `M${start} A${radius},${radius} 0 ${large},${turn} ${end}`;
                return path + (useGap ? ' L0,0' : '') + ' Z';
            },
            donut: (basic, value) => {
                if (!value) return null;
                const { radius, thickness } = this.state,
                    r1 = radius - thickness,
                    large = largeArc(value),
                    turn = PathTurn(false);
                const m = pointByAngle(radius, rad(basic, 1)),
                    n = pointByAngle(radius, rad(basic + value, -1)),
                    [start1, end1] = fixOverlap(m, n),
                    p = pointByAngle(r1, rad(basic, 1)),
                    q = pointByAngle(r1, rad(basic + value, -1)),
                    [start2, end2] = fixOverlap(q, p);

                const path = `M${start1} A${radius},${radius} 0 ${large},1 ${end1} L${start2} A${r1},${r1} 0 ${large},${turn} ${end2} Z`;
                return path;
            },
        };
    }

    #renderCentral(total) {
        const { centralHeader } = this.options,
            { size, thickness } = this.state;
        if (centralHeader === false) return null;

        const { centralFormat } = this.state,
            header = typeof centralHeader === 'string' ? centralHeader || null : I18N.total;
        return (
            <dl className="central" style={{ inset: percent(thickness / size) }}>
                <div>
                    {header && <dt className="central-header">{header}</dt>}
                    <dd className="central-value">{centralFormat(total)}</dd>
                </div>
            </dl>
        );
    }
    render() {
        const { items, total, count } = this.parseData(),
            { type, showSeries } = this.options,
            { isDonut, size, radius } = this.state,
            ArcPath = this.#arcPath(total, count > 1)[type];

        // 2n: create dom
        return (
            <>
                <aui-tabloop className={['pie', showSeries && 'show-series']} {...TabloopArgs}>
                    <div className="stack-box">
                        <svg:svg viewBox={`0 0 ${size} ${size}`}>
                            <svg:g className="stack-graph" transform={`translate(${radius},${radius}) rotate(-90)`}>
                                {items.map((item, i) => {
                                    const args = this.itemArgs(item, i);
                                    return (
                                        <svg:g className={['graph-box', TooltipClassName.Stack]}>
                                            <svg:path d={ArcPath(item.acc, item.value)} {...args} />
                                        </svg:g>
                                    );
                                })}
                            </svg:g>
                        </svg:svg>
                        {isDonut && this.#renderCentral(total)}
                    </div>
                </aui-tabloop>
                <TooltipNode />
            </>
        );
    }
}
