import arrayLike from '../../util/array/is-like.js';

import matchSelector from './match-selector.js';

export default function is(query) {
    const node = this;
    if (node.nodeType === Node.ELEMENT_NODE) {
        if (query == null || query === '*') return node;
        if (typeof query === 'string') return matchSelector(node, query) && node;
        if (arrayLike(query)) return Array.prototype.find.call(query, (item) => is.call(node, item)) || false;
        if (query instanceof Element) return node === query && node;
    }
    // eslint-disable-next-line unicorn/prefer-number-properties
    return NaN;
}
