import origin from './origin.js';

/** @type {typeof $$.event.wheelable} */
export default function wheelable(element, e) {
    if (!element) return false;
    const { deltaX, deltaY } = origin(e);
    const { scrollLeft: SL, scrollTop: ST, clientWidth: cW, clientHeight: cH, scrollWidth: sW, scrollHeight: sH } = element;
    let x, y;
    if (deltaX !== 0) {
        x = (deltaX < 0 && SL > 0) || (deltaX > 0 && Math.round(SL + cW - sW) < 0);
    }
    if (deltaY !== 0) {
        y = (deltaY < 0 && ST > 0) || (deltaY > 0 && Math.round(ST + cH - sH) < 0);
    }
    return x || y;
}
