/** @jsxImportSource @gui/aui-devops */
import $ from '../../core/element/index.js';
import { addTooltip } from '../../core/module/tooltip.js';
import { define, Widget, Types } from '../../widget/widget.js';

import cssGetValue from '../../util/css/get-value.js';
import cssLength from '../../util/css/length.js';
import ioUrlGuid from '../../util/io/url-guid.js';
import objectFilter from '../../util/object/filter.js';
import { isEmpty as typeIsEmpty } from '../../util/type/types.js';

import '../dialog/modal.js';
import { htmlPurify } from '../htmlpurify/purify.js';
import { loading, elementLoading } from '../loading/loading.js';
import '../tablist/tablist.js';
import '../wordcount/wordcount.js';

import './toolbar.js';
import './quick-table.js';
import { BlockPlugins, ClassName, DefaultFontNames, DefaultFontSizes, DefaultToolbar, LanguageMap, ToolbarGroup } from './constants.js';
import './plugins/index.mjs';
import '../editorecho/editorecho.js';

import { loader, addPlugin, loadPlugins } from './loader.js';
import { normalizeContent } from './method.js';

import reset from './reset.less';
import skin from './skin.css';
import style from './style.less';
import toolbarStyle from './toolbar.less';

const I18N = $$.I18N.editor;

/** @extends {Widget<typeof Editor.options>} */
@define('editor')
export class Editor extends Widget {
    static options = {
        autocompleter: '',
        contentStyle: '',
        defaultStyle: {},
        disabled: false,
        fontNames: Types.function,
        fontSizes: Types.array,
        forbiddenCopy: false,
        height: Types.Length.value(200),
        label: Types.string,
        nativeContextMenu: false,
        nativeSpellChecker: true,
        pasteAsText: false,
        placeholder: '',
        plainText: false,
        plugins: Types.function,
        readonly: false,
        resizeable: true,
        startupFocus: false,
        statusbar: true,
        toolbar: Types.Union([Types.array, Types.string]).value('default'),
        value: '',
        verifyAll: false,
        width: Types.Length.value('auto'),
        wordcount: Types.Union([Types.boolean, Types.number, Types.PlainObject]),
        args_help: Types.Union([Types.boolean, Types.PlainObject], false),
        args_upload: Types.Any,
        doAutocomplete: Types.function,
        doCopyUpload: Types.function,
        onBlur: Types.function,
        onChange: Types.function,
        onFocus: Types.function,
        onInput: Types.function,
        onLoad: Types.function,
        onPaste: Types.function,
    };
    static observers = ['disabled', 'readonly', 'value', 'args_upload'];
    static shadow = { delegatesFocus: true };
    static styles = [style, { skin, reset, toolbar: toolbarStyle }];
    static toolbar = DefaultToolbar;
    static fontNames = DefaultFontNames;
    static fontSizes = DefaultFontSizes;
    static addPlugin = addPlugin;

    /** @type {Promise<AuiEditor>} */
    #loader = null;
    /** @type {AuiEditor} */
    #editor = null;
    /** @type {Promise<void>} */
    #initPromise = null;
    blockPlugins = [];
    cache = {
        copyUploadData: [],
        lastChangeValue: '',
        lastInputValue: '',
    };
    config = {};
    dirty = false;
    method = {
        deleteSpan: this.deleteSpan,
        focus: this.focus,
        getAttachments: this.getAttachments,
        getSpan: this.getSpan,
        getText: this.getText,
        getValue: this.getValue,
        getWordCount: () => this.#getValue({ format: 'raw' }),
        insertSpan: this.insertSpan,
        insertText: this.insertText,
        insertValue: this.insertValue,
        isDirty: this.isDirty,
        setValue: this.setValue,
    };

    create() {
        this.#loader = loader('aui.editor.js').then(() => {
            this.#editor = window.AuiEditor;
            return loadPlugins(this.#editor);
        });
        this.hostProto = { fontIcon: this.fontIcon };
    }

    init() {
        const { help, startupFocus, statusbar, value, width, height } = this.options;
        this.labelBoxId = this.defaultId + '-label-box';
        this.state = {
            initialized: !startupFocus,
            statusbar: statusbar || help,
            value: this.preprocessValue(value),
            width: cssLength(width),
            height: cssLength(height),
        };
    }

    purifyValue(val) {
        return htmlPurify(val, { scheme: 'Editor' });
    }
    preprocessValue(value) {
        return this.isPlainText() ? this.htmlToString(value) : this.purifyValue(value);
    }

    isPlainText() {
        return this.options.plainText;
    }

    htmlToString(html) {
        return html.replaceAll('<', '&lt;').replaceAll('>', '&gt;');
    }

    didMount() {
        if (this.state.initialized) {
            this.initEditor();
        } else {
            const { value } = this.state;
            // eslint-disable-next-line aui/inner-html
            this.host.innerHTML = value;
        }
    }

    getConfig() {
        const { label, nativeContextMenu, nativeSpellChecker, pasteAsText, placeholder, wordcount } = this.options;
        const toolbar = this.getToolbar();
        const toolbarButtons = this.getToolbarButtons(toolbar);
        const plugins = this.getPlugins(toolbarButtons);

        this.blockPlugins = BlockPlugins.filter((blockPlugin) => {
            const { name } = blockPlugin;

            return !toolbarButtons.includes(name);
        });

        return {
            browser_spellcheck: nativeSpellChecker,
            content_style: this.getContentStyle(),
            contextmenu_never_use_native: !nativeContextMenu,
            font_family_formats: this.getFontFamilyFormats(),
            font_size_formats: this.getFontSizeFormats(),
            height: 'auto',
            iframe_aria_text: label,
            iframe_aria_labelledby: this.labelBoxId,
            language: LanguageMap[$$.I18N.lang],
            paste_as_text: this.isPlainText() || pasteAsText,
            paste_data_images: toolbarButtons.includes('Image') && plugins.includes('Image'),
            placeholder: placeholder,
            plugins: plugins,
            resize: false,
            statusbar: false,
            toolbar: toolbar,
            wordcount: wordcount, // Custom options.
            setup: (editor) => {
                this.handleSetup(editor);
            },
            ...objectFilter(this.options, (option) => option.startsWith('args_')), // Custom options.
        };
    }

    getToolbar() {
        if (this.isPlainText()) {
            return [];
        } else {
            const { toolbar } = this.options;
            const toolbarGroups = typeof toolbar === 'string' ? (Editor.toolbar[toolbar] ?? DefaultToolbar['default']) : toolbar;

            if (!Array.isArray(toolbarGroups)) return [];

            return toolbarGroups.map((toolbarGroup) => {
                if (typeof toolbarGroup === 'string') {
                    return ToolbarGroup[toolbarGroup];
                }

                if (typeof toolbarGroup === 'object') {
                    const { group } = toolbarGroup;

                    if (group) {
                        return { ...ToolbarGroup[group], ...toolbarGroup };
                    } else {
                        return toolbarGroup;
                    }
                }
                return null;
            });
        }
    }

    getToolbarButtons(toolbar) {
        return toolbar.reduce((accumulator, currentValue) => {
            const { items } = currentValue;

            return accumulator.concat(items);
        }, []);
    }

    getPlugins(toolbarButtons) {
        if (this.isPlainText()) return [];

        const defaultPlugins = this.#editor.Plugin.getList(toolbarButtons);

        if (this.options.pasteAsText) {
            const index = defaultPlugins.indexOf('Paster');
            if (index !== -1) {
                defaultPlugins.splice(index, 1);
            }
        }

        const { plugins } = this.options;
        return $$.fn(plugins)(defaultPlugins.slice()) || defaultPlugins;
    }

    getContentStyle() {
        const { contentStyle } = this.options;

        return [this.#editor.defaultOptions.content_style, this.getCSSVariables(), contentStyle].join('');
    }

    getCSSVariables() {
        const variableNames = ['--body-color', '--disabled-color', '--focusable-border', '--info-color', '--link-color', '--placeholder-color'];

        return `:root { ${variableNames.map((variableName) => `${variableName}: ${cssGetValue(variableName)};`).join(' ')} --font-family: ${this.getDefaultFontFamily()}; --font-size: ${this.getDefaultFontSize()}pt; }`;
    }

    getDefaultFontFamily() {
        const { fontFamily } = this.options.defaultStyle;

        return fontFamily ?? cssGetValue('--font-families');
    }

    getDefaultFontSize() {
        const { fontSize } = this.options.defaultStyle;

        return fontSize ?? (cssGetValue('--font-size-base') / 4) * 3;
    }

    getFontFamilyFormats() {
        const fontNames = this.options.fontNames?.({ ...DefaultFontNames }) ?? DefaultFontNames;
        const defaultFontFamily = this.getDefaultFontFamily();
        const defaultFontFamilyName = defaultFontFamily.split(',', 1).at(0).replaceAll(/["']/g, '');

        fontNames[defaultFontFamilyName] = `${defaultFontFamily.replaceAll(/["']/g, '')};`;

        return Object.entries(fontNames)
            .map((fontName) => {
                const [key, value] = fontName;

                return value ? `${key}=${value}` : '';
            })
            .sort()
            .join('');
    }

    getFontSizeFormats() {
        const { fontSizes } = this.options,
            list = fontSizes?.length ? fontSizes : DefaultFontSizes;
        const defaultFontSize = this.getDefaultFontSize();

        if (!list.includes(defaultFontSize)) {
            list.push(defaultFontSize);
        }

        return list
            .sort((a, b) => a - b)
            .map((size) => `${size}pt`)
            .join(' ');
    }

    handleSetup(editor) {
        editor.options.register('wordcount', {
            processor: (value) => {
                switch (typeof value) {
                    case 'boolean':
                    case 'number':
                    case 'object':
                        return {
                            valid: true,
                            value,
                        };
                    default:
                        return {
                            valid: false,
                        };
                }
            },
            default: true,
        });

        const { autocompleter, doAutocomplete } = this.options;

        if (autocompleter && doAutocomplete) {
            editor.ui.registry.addAutocompleter('autocompleter', {
                trigger: autocompleter,
                minChars: 0,
                columns: 1,
                matches: (rng, text, pattern) => {
                    return doAutocomplete(pattern).length > 0;
                },
                fetch: (pattern) => {
                    const results = doAutocomplete(pattern).map((item) => Object.assign(item, { type: 'autocompleteitem' }));
                    return Promise.resolve(results);
                },
                onAction: (api, rng, value) => {
                    this.editor.selection.setRng(rng);
                    this.insertContent(value);
                    api.hide();
                },
            });
        }

        editor.on('LoadContent', () => {
            this.setValueCache();
        });

        editor.on('init', (e) => {
            this.editor = editor;

            this.setMode();
            this.setValue(this.state.value);

            const { startupFocus } = this.options;
            if (startupFocus) {
                this.editor.focus();
            }

            addTooltip(this.host);

            this.callback('onLoad');
        });

        editor.on('focus', () => {
            this.callback('onFocus', { currentTarget: this.host, target: this.host });
        });

        editor.on('blur', () => {
            this.callback('onBlur', { currentTarget: this.host, target: this.host });
        });

        editor.on('input ExecCommand ObjectResized', () => {
            new Promise((resolve) => {
                let lock = 0;

                this.editor
                    .getBody()
                    .querySelectorAll('img, video')
                    .forEach((media) => {
                        const cell = media.closest('td, th');

                        if (cell) {
                            lock++;
                            const cellWidth = cell.clientWidth;

                            const refresh = (width) => {
                                if (width >= cellWidth) {
                                    media.setAttribute('width', cellWidth);
                                    media.setAttribute('height', null);
                                } else {
                                    media.setAttribute('width', media.getAttribute('width') || null);
                                    media.setAttribute('height', null);
                                }

                                lock--;

                                if (lock === 0) {
                                    resolve();
                                }
                            };

                            if (media.nodeName === 'IMG') {
                                if (media.getAttribute('width')) {
                                    refresh(media.getAttribute('width'));
                                } else if (media.complete) {
                                    refresh(media.clientWidth);
                                } else {
                                    media.onload = () => refresh(media.clientWidth);
                                }
                            } else if (media.nodeName === 'VIDEO') {
                                if (media.getAttribute('width')) {
                                    refresh(media.getAttribute('width'));
                                } else if (media.readyState > 0) {
                                    refresh(media.clientWidth);
                                } else {
                                    media.loadeddata = () => refresh(media.clientWidth);
                                }
                            }
                        }
                    });
                if (lock === 0) {
                    resolve();
                }
            }).then(() => {
                const value = this.editor.getContent();
                const { lastInputValue: cache } = this.cache;

                if (value !== cache) {
                    this.setValueCache('input');
                    this.callback('onInput', value);
                }
            });
        });

        editor.on('Dirty', () => {
            this.dirty = true;
            this.element.setAttribute('data-dirty', true);
        });

        editor.on(
            'input ExecCommand ObjectResized',
            $$.debounce(() => {
                this.handleChange();
            })
        );

        editor.on('GetContent', (e) => {
            const { content, format } = e;
            const { defaultStyle } = this.options;

            if (!typeIsEmpty(defaultStyle) && content && format === 'html') {
                const { body } = Document.parseHTMLUnsafe(content);
                const { fontFamily, fontSize } = defaultStyle;

                for (const element of body.querySelectorAll(`:not([style*="font-family"])`)) {
                    if (!element.closest('span[style*="font-family"]')) {
                        element.style.fontFamily = fontFamily;
                    }
                }

                for (const element of body.querySelectorAll(`:not([style*="font-size"])`)) {
                    if (!element.closest('span[style*="font-size"]')) {
                        element.style.fontSize = `${fontSize}pt`;
                    }
                }

                e.content = body.innerHTML;
            }
        });

        editor.on('SetContent', (e) => {
            const body = editor.getBody();

            if (normalizeContent(body, 'editor')) {
                this.callback('onChange', editor.getContent());
            }
        });

        editor.on('SetValueUnsafe', ({ data }) => {
            data.dataValue = this.purifyValue(data.dataValue);
        });

        editor.on('click', (e) => {
            const { target } = e;
            const { tagName } = target;

            if (tagName === 'A') {
                e.preventDefault();
                return false;
            }

            const { doCopyUpload } = this.options;
            if (doCopyUpload && tagName === 'IMG' && target.classList.contains('img-copy-upload-failed')) {
                const img = target;
                const originalSrc = this.getImgBase64Src(target);

                this.startCopyUpload();
                doCopyUpload(originalSrc).then((result) => {
                    const src = result;

                    if (src) {
                        img.setAttribute('src', src);
                        img.classList.remove('img-copy-upload-failed');
                    }

                    this.startCopyUpload(false);
                });
            }
        });

        editor.on('copy cut', (e) => {
            const { forbiddenCopy } = this.options;

            if (forbiddenCopy) {
                e.preventDefault();
            }
        });

        editor.on('NewRow', ({ node }) => {
            if (node?.tagName === 'TR') {
                node.style.border = 'inherit';
            }
        });

        editor.on('PastePostProcess', this.handlePaste);
    }

    toggleDisabled(isDisabled = true) {
        this.element.classList.toggle(ClassName.Disabled, isDisabled);
        this.editor.getBody().classList.toggle(ClassName.Disabled, isDisabled);
    }
    toggleReadonly(isReadonly = true) {
        this.element.classList.toggle(ClassName.Readonly, isReadonly);
        this.editor.getBody().classList.toggle(ClassName.Readonly, isReadonly);
    }

    setValueCache(type) {
        const value = this.getValue();

        if (type) {
            this.cache[{ change: 'lastChangeValue', input: 'lastInputValue' }[type]] = value;
        } else {
            this.cache.lastChangeValue = value;
            this.cache.lastInputValue = value;
        }
    }

    setMode() {
        const { disabled, readonly } = this.options;
        this.editor.prevMode = this.editor.mode.get();
        this.editor.mode.set(disabled || readonly ? 'readonly' : 'design');
    }

    handleChange = () => {
        const value = this.editor.getContent();
        const { lastChangeValue: cache } = this.cache;
        const { verifyAll } = this.options;

        if (!!value !== !!cache || (value && verifyAll)) {
            this.$element.trigger('onChange');
        }

        if (value !== cache) {
            this.setValueCache('change');
            this.callback('onChange', value);
        }
    };

    handlePaste = (e) => {
        const { node } = e;

        for (const blockPlugin of this.blockPlugins) {
            const { selector, tag } = blockPlugin;

            for (const element of node.querySelectorAll(selector)) {
                const innerText = element.innerText.trim();

                if (tag && innerText) {
                    const span = document.createElement('span');
                    span.innerText = innerText;

                    element.replaceWith(span);
                } else {
                    element.remove();
                }
            }
        }

        const imgs = node.querySelectorAll('img');
        if (imgs.length > 0) {
            const { doCopyUpload } = this.options;

            if (doCopyUpload) {
                this.startCopyUpload();

                for (const img of imgs) {
                    this.handleCopyUpload(img);
                }

                this.handleCopyUploadAllSettled();
            }
        }

        this.callback('onPaste', node);
    };

    startCopyUpload = (isStart = true) => {
        // this.editor.mode.set(isStart ? 'readonly' : 'design');
        this.toggleLoading(isStart);
    };

    toggleLoading = (isShow) => {
        loading(isShow);
    };

    handleCopyUpload = (img) => {
        const { copyUploadData } = this.cache;
        const originalSrc = this.getImgBase64Src(img);
        const id = ioUrlGuid(originalSrc);

        img.setAttribute('data-id', id);

        this.beforeCopyUpload();

        copyUploadData.push(
            this.options.doCopyUpload(originalSrc)?.then(
                (result) => {
                    const src = result;
                    const img = this.editor.getBody().querySelector(`[data-id="${id}"]`);

                    if (src) {
                        img.setAttribute('src', src);
                        img.removeAttribute('data-id');
                    } else {
                        img.classList.add('img-copy-upload-failed');
                    }

                    this.afterCopyUpload();
                },
                (error) => {
                    this.editor.getBody().querySelector(`[data-id="${id}"]`).remove();

                    this.editor.notificationManager.open({
                        icon: 'error',
                        text: error,
                        timeout: 2000,
                        type: 'error',
                    });
                }
            )
        );
    };

    getImgBase64Src(img) {
        const src = img.getAttribute('src');

        if (this.isBase64String(src)) {
            return src;
        } else if (this.isBlobString(src)) {
            return this.convertBlobToBase64(src);
        } else {
            return src;
        }
    }

    isBase64String(string) {
        return string.startsWith('data:') && string.includes(';base64,');
    }

    isBlobString(string) {
        return string.startsWith('blob:');
    }

    convertBlobToBase64(blobUri) {
        const blobInfo = this.editor.editorUpload.blobCache.getByUri(blobUri);
        const blob = blobInfo.blob();

        return 'data:' + blob.type + ';base64,' + blobInfo.base64();
    }

    beforeCopyUpload = () => {};

    afterCopyUpload = () => {};

    handleCopyUploadAllSettled = () => {
        const { copyUploadData } = this.cache;

        Promise.allSettled(copyUploadData).then(() => {
            this.startCopyUpload(false);
            this.cache.copyUploadData = [];
        });
    };

    initEditor() {
        if (this.#initPromise != null) return this.#initPromise;

        if (!this.state.initialized) {
            this.setState({ initialized: true }, () => addTooltip(this.host));
        }

        this.lock(Infinity);
        this.toggleElementLoading(true, { delay: 20 });
        this.#initPromise = this.#loader.then(() => {
            this.config = this.getConfig();

            return this.#editor.init({ ...this.config, target: this.query(`#${this.defaultId}`) }, this.options).then(([editor]) => {
                editor.inited(() => {
                    if (this.state.statusbar) editor.dispatch('UIBottom', { element: this.element.querySelector('.' + ClassName.Footer) });
                    this.toggleElementLoading(false, { destroy: true });
                });
            });
        });

        return this.#initPromise;
    }

    toggleElementLoading(isLoading, args) {
        elementLoading(this.element, isLoading, args);
        return isLoading ? this.element.setAttribute('aria-busy', true) : this.element.removeAttribute('aria-busy');
    }

    loadImage(src, callback) {
        const image = new Image();
        image.src = src;
        image.onload = () => {
            const { width, height } = image;
            const img = `<img src="${src}" width="${width}" height="${height}" data-media="temp" />`;

            if (typeof callback === 'function') {
                callback(img);
            }
        };
    }

    setOption(name, value) {
        switch (name) {
            case 'value':
                if (value !== this.cache.lastChangeValue) {
                    this.setValue(value);
                }
                return false;
            case 'disabled':
                if (this.state.initialized) {
                    this.toggleDisabled(value);
                    this.setMode();
                    return false;
                }
                break;
            case 'readonly':
                if (this.state.initialized) {
                    this.toggleReadonly(value);
                    this.setMode();
                    return false;
                }
                break;
            case 'args_upload':
                return false;
            default:
                break;
        }
    }

    deleteSpan(id) {
        this.getSpan(id).remove();

        this.handleChange();
    }

    getSpan(id) {
        const body = this.editor.getBody();

        return id ? body.querySelector(`span#${id}`) : body.querySelectorAll(`span.${ClassName.Span}`);
    }

    focus() {
        if (this.state.initialized) {
            this.editor.focus();
        } else {
            this.handleActivate();
        }
    }

    getAttachments() {
        const attachments = this.editor.getBody().querySelectorAll('[data-type=RichEditorAttachment]');

        return Array.from(attachments).flatMap((attachment) => {
            const { nodeName } = attachment;

            switch (nodeName) {
                case 'IMG':
                    return attachment.getAttribute('src');
                case 'A':
                    return attachment.getAttribute('href');
                case 'VIDEO':
                case 'AUDIO':
                    return attachment.firstChild.getAttribute('src');
            }
            return [];
        });
    }

    getText(combineNewline = 'space') {
        const text = this.state.initialized ? this.editor.getContent({ format: 'text' }) : this.host.innerText;

        switch (combineNewline) {
            case 'space':
                return text.replaceAll(/\n+/g, ' ');
            case 'trim':
                return text.replaceAll(/\n+/g, '');
            case true:
                return text.replaceAll(/\n+/g, '\n');
            case false:
                return text;
        }
    }

    #getValue(args) {
        return this.state.initialized ? (this.editor ? this.editor.getContent(args) : this.state.value) : this.host.innerHTML;
    }
    getValue() {
        return this.#getValue();
    }
    verify = () => {
        const value = this.getValue();
        return [value];
    };
    insertSpan(html, attributes, callback) {
        const { id, className } = attributes || {},
            classList = [ClassName.Span],
            args = [];
        if (id) args.push(`id="${id}"`);
        if (className?.length) classList.push(className);
        args.push(`class="${classList.join(' ')}"`);
        const v = `<span ${args.join(' ')} contenteditable="false" >${html}</span>`;
        let element;

        return this.insertValue(v, () => (element = this.getSpan(id))).then(() => {
            $$.fn(callback)(element);
            return element;
        });
    }

    insertText(text, callback) {
        return this.insertValue(text, callback, 'text');
    }

    insertValue(value, callback, format = 'html') {
        const { promise, resolve, reject } = Promise.withResolvers();
        if (this.isEditable()) {
            if (this.state.initialized) {
                this.insertContent(value, callback, format);
                resolve();
            } else {
                this.initEditor().then(() => {
                    this.insertContent(value, callback, format);
                    resolve();
                });
            }
        } else {
            reject();
        }
        return promise;
    }

    isEditable() {
        const { disabled, readonly } = this.options;

        return !disabled && !readonly;
    }

    insertContent = (content, callback, format) => {
        if (this.isPlainText() || format === 'text') {
            this.editor.execCommand('InsertText', false, content);
        } else {
            this.editor.insertContent(this.purifyValue(content));
        }
        $$.fn(callback)();
    };

    isDirty() {
        return this.dirty;
    }

    setValue(value) {
        const preprocessedValue = this.preprocessValue(value);

        if (this.state.initialized) {
            if (this.editor) {
                this.editor.setContent(preprocessedValue);
                this.setValueCache();

                this.editor.undoManager.reset();
            } else {
                this.setState({ value: preprocessedValue });
            }
        } else {
            this.setState({ value: preprocessedValue }, false);
            // eslint-disable-next-line aui/inner-html
            this.host.innerHTML = preprocessedValue;
        }
    }

    onFocusInitialize = (e) => {
        if ($$.browser.touchable) {
            setTimeout(this.handleActivate, 99);
        } else {
            this.handleActivate();
        }
    };

    handleActivate = () => {
        if (!this.state.initialized && this.isEditable()) {
            this.initEditor();
        }
    };

    render() {
        const { disabled, readonly, resizeable } = this.options,
            { statusbar, value, width, height } = this.state,
            className = [ClassName.Element, disabled && ClassName.Disabled, readonly && ClassName.Readonly, resizeable && ClassName.Resizeable];

        if (this.state.initialized) {
            return (
                <div className={className} tabIndex={-1} style={{ width, minHeight: height }}>
                    <div id={this.labelBoxId} className="sr-only" />
                    <textarea id={this.defaultId} autoComplete="off" disabled data-disabled="false" aria-hidden="true">
                        {value}
                    </textarea>
                    {statusbar && <div className={ClassName.Footer} />}
                    <slot name="slot" />
                </div>
            );
        } else {
            return (
                <div className={className} tabIndex={-1} style={{ width, height }} onFocusCapture={this.onFocusInitialize}>
                    <div className="header">
                        <aui-button-lite icon={ClassName.Edit} disabled={disabled || readonly} tooltip={I18N.edit} type="plain" />
                    </div>
                    <div
                        className={ClassName.Body}
                        style={{
                            fontFamily: this.getDefaultFontFamily(),
                            fontSize: `${this.getDefaultFontSize()}pt`,
                        }}
                    >
                        <slot />
                    </div>
                    {statusbar && <div className={ClassName.Footer} />}
                </div>
            );
        }
    }
}
