/** @type {typeof $$.object.map} */
export default function map(object, callback, checkProp) {
    const obj = {};
    if (callback === true) callback = (k, v) => v;
    for (const k in object) {
        if (checkProp === false || Object.hasOwn(object, k)) {
            const result = callback(k, object[k]);
            if (result !== undefined) obj[k] = result;
        }
    }
    return obj;
}
