import { I18N } from '../../core/base/i18n.js';

import format from '../string/format.js';

import converter from './converter.js';

/** @type {typeof $$.date.dateSince} */
export default function dateSince(timestamp) {
    const _I18N = I18N.core.since;
    if (typeof timestamp !== 'number') timestamp = new Date(timestamp).getTime();

    const since = Date.now() - timestamp,
        daySince = Date.now() - new Date(new Date(timestamp).toLocaleDateString()).getTime();

    if (since < converter.min) {
        return _I18N.now;
    } else if (since < converter.hour) {
        return format(_I18N.minutes, Math.floor(since / converter.min));
    } else if (since < converter.day) {
        return format(_I18N.hours, Math.floor(since / converter.hour));
    } else if (since >= converter.day && since < 2 * converter.day) {
        return _I18N.yesterday;
    } else if (daySince < 7 * converter.day) {
        return format(_I18N.days, Math.floor(daySince / converter.day));
    } else if (daySince < 14 * converter.day) {
        return _I18N.week;
    } else if (daySince < 31 * converter.day) {
        return _I18N.weeks;
    } else {
        return _I18N.month;
    }
}
