/** @jsxImportSource @gui/aui-devops */
import { idleLoad } from '../../core/base/onload.js';
import $ from '../../core/element/index.js';
import { define, Widget, Types } from '../../widget/widget.js';

import imgCssBase64Value from '../../util/img/css-base64-value.js';

const Styles = `:host{user-select:none;}`;
let currentX = 0,
    currentY = 0,
    trigger = false;
let dragTargetElement = null,
    dropTargetElement = null,
    dropFromElementList = [],
    gridPosition = {};
const PositionTypes = new Set(['fixed', 'absolute', 'relative']);
const Image = <img src={imgCssBase64Value('--image-blank')} alt="" width={1} height={1} />;

/** @extends {Widget<typeof Drag.options>} */
@define('drag')
export class Drag extends Widget {
    static options = {
        axis: Types.Enum(['x', 'y', 'both'], 'both'),
        within: Types.Selector.value('body'),
        coordinate: Types.Union([Types.array, Types.function]),
        cursor: 'move',
        disabled: false,
        agile: false,
        distance: 0,
        handle: Types.Union([Types.Selector, Types.Element]),
        except: Types.Union([Types.Selector, Types.Element]),
        helper: Types.Union([Types.Selector, Types.Element, Types.function]),
        helperBox: Types.Union([Types.Selector, Types.Element]),
        helperOffset: Types.Object({ left: [Types.number, 20], top: [Types.number, 20] }),
        grid: Types.array,
        eventScope: Types.Selector.value('host'),
        target: Types.string,
        dropTarget: Types.Union([Types.Selector, Types.Element]),
        onDragStart: Types.function,
        onDragging: Types.function,
        onDragEnd: Types.function,
        onSetPosition: Types.function,
        willDrag: Types.function,
    };
    static styles = Styles;
    static observers = ['disabled', 'handle', 'except', 'helperBox', 'helperOffset', 'dropTarget'];

    init() {
        this.state = {
            disabled: this.options.disabled,
        };
        this.offset = {
            offsetParent: { left: 0, top: 0 }, // helper parent node position relative to document
            click: { left: 0, top: 0 }, // click offset relative to element
            currentLocal: { left: 0, top: 0 },
            moveDistance: { left: 0, top: 0 },
        };
        this.position = {
            originalPosition: { left: 0, top: 0 }, // helper element position relative before drag
            position: { left: 0, top: 0 }, // helper element position relative after drag
        };
        this.scrollStep = { left: 0, top: 0 };
    }
    setOption(name, value) {
        switch (name) {
            case 'disabled':
                this.setState({ disabled: value });
                this.setDragElementCss();
                break;
            case 'handle':
            case 'except':
            case 'dropTarget':
                this.initElement();
                break;
            default:
                break;
        }
    }
    didMount() {
        idleLoad(() => {
            this.initElement();
            this.initEvent();
        });
    }
    initElement() {
        const { handle, except, dropTarget, eventScope, target } = this.options;
        const crossArg = { crossShadow: true, crossSlot: true, directChildren: true };
        this.eventScopeElement = this.parseElement(eventScope) || this.host;
        this.$eventScopeElement = $(this.eventScopeElement);
        this.dragElement = (target ? this.$eventScopeElement.find(target, crossArg) : this.$eventScopeElement.child(null, crossArg)).get(0);
        if (dropTarget) this.dropElement = this.parseElement(dropTarget);
        const boxStyle = this.dragElement && getComputedStyle(this.dragElement);
        if (!PositionTypes.has(this.dragElement.style.position) && !PositionTypes.has(boxStyle.position)) this.dragElement.style.position = 'relative';
        if (handle) this.$handleElement = this.$eventScopeElement.find(handle, crossArg);
        if (except) this.$exceptElement = (this.$handleElement || this.$eventScopeElement).find(except, crossArg);
        if (dropTarget) dropFromElementList.push(this.$eventScopeElement.parent());
        this.setDragElementCss();
    }
    setDragElementCss() {
        const { disabled } = this.state;
        const { cursor, handle } = this.options;
        if (!this.$dropElement && this.dragElement?.draggable) this.dragElement.removeAttribute('draggable');
        disabled ? this.dragElement.removeAttribute('draggable') : this.dragElement.setAttribute('draggable', 'true');
        const cursorType = disabled ? 'not-allowed' : cursor;
        this.dragElement.style.cursor = !handle ? cursorType : disabled ? 'not-allowed' : 'default';
        this.dragElement.style.userSelect = 'none';
        this.dragElement.style.opacity = disabled ? 'var(--disabled-opacity)' : '1';
        if (this.$handleElement) this.$handleElement.css('cursor', cursorType);
        if (this.$exceptElement) this.$exceptElement.css('cursor', 'default');
    }

    initEvent() {
        const { within, agile, coordinate } = this.options;
        if (within) {
            this.withinElement = this.parseElement(within);
            this.$withinElement = $(this.withinElement);
            this.$scrollElement = $(this.dragElement).scrollBox(this.$withinElement);

            this.withinElement.addEventListener('drop', (e) => {
                e.stopPropagation();
            });
        }
        if (agile && this.withinElement) {
            this.withinElement.addEventListener('mousedown', (e) => {
                if (this.state.disabled || e.button !== 0) return null;
                this.dragElement.setAttribute('draggable', 'true');
                const coordinates = typeof coordinate == 'function' ? coordinate() : coordinate;
                if (coordinates && (e.pageX < coordinates[0] || e.pageX > coordinates[2] || e.pageY < coordinates[1] || e.pageY > coordinates[3])) return null;
                this.offset.click = {
                    left: this.dragElement.offsetWidth / 2,
                    top: this.dragElement.offsetHeight / 2,
                };
                this.pointerDownEvent(e, this.$withinElement, 'pointDownWithin');
            });
            this.withinElement.addEventListener('mouseup', (e) => {
                if (e.button === 0) this.pointerUp(e);
            });
        }
        this.eventScopeElement.addEventListener(
            'mousedown',
            (e) => {
                if (this.state.disabled || e.button !== 0) return null;
                this.dragElement.setAttribute('draggable', 'true');
                const [target] = e.composedPath();
                this.realTarget = target;
                if (this.$handleElement?.contains(this.realTarget) && !this.$exceptElement?.contains(this.realTarget)) $$.fn(this.options.willDrag)(e);
            },
            true
        );
        this.eventScopeElement.addEventListener('dragstart', (e) => {
            if ((this.$handleElement && !this.$handleElement.contains(this.realTarget, true)) || this.$exceptElement?.contains(this.realTarget, true)) {
                e.preventDefault();
            }
            e.dataTransfer.setData('text', e.target.id);
            e.dataTransfer.effectAllowed = 'move';
            dragTargetElement = this.dragElement.parentNode;
            dropTargetElement = this.dropElement;

            const dropHost = $(dropTargetElement).is('aui-drop') || $(dropTargetElement).parents('aui-drop')[0];
            if (dropHost) dropHost.method('highlight', dropTargetElement, true);
            this.offset.click = {
                left: e.pageX - $(this.dragElement).offset().left,
                top: e.pageY - $(this.dragElement).offset().top,
            };
            this.coordinates = typeof coordinate == 'function' ? coordinate() : coordinate;
            this.scroll = { left: this.$scrollElement.get(0)?.scrollLeft ?? 0, top: this.$scrollElement.get(0)?.scrollTop ?? 0 };
            this.pointerDownEvent(e, this.$eventScopeElement.parent());
            this.createHelper(e);
            this.callback('onDragStart', e);

            this.abort = $.$body.on('dragover', { native: true }, (e) => {
                e.preventDefault();
                trigger = true;
                if ($$.browser.name === 'firefox') {
                    // https://bugzilla.mozilla.org/show_bug.cgi?id=505521 | to resolve firefox bug
                    currentX = e.pageX;
                    currentY = e.pageY;
                }
            });
        });
        this.eventScopeElement.addEventListener('drag', (e) => {
            this.dragMoveEvent(e);
        });
        this.eventScopeElement.addEventListener('dragend', (e) => {
            e.stopPropagation();
            trigger = false;
            $('.placeholder').remove();
            $(dropTargetElement).removeClass('bg-green-important');
            if (this.$helper) $('.aui-dragging-helper').remove();
            this.offset.currentLocal = {
                left: Number.parseFloat($(this.dragElement).css('left')),
                top: Number.parseFloat($(this.dragElement).css('top')),
            };
            this.abort?.abort();
            if (this.callback('onDragEnd', e, this.position) === false) {
                this.dragElement.style.left = '0px';
                this.dragElement.style.top = '0px';
            }
        });
    }
    pointerDownEvent(e, parent, str) {
        currentX = this.originX = e.pageX;
        currentY = this.originY = e.pageY;
        this.offset.moveDistance = { left: 0, top: 0 };
        // drag element's original position in scrollable within element
        this.offset.currentOffset ??= {
            left: this.$scrollElement?.length > 0 ? this.dragElement.offsetLeft : 0,
            top: this.$scrollElement?.length > 0 ? this.dragElement.offsetTop : 0,
        };
        this.offset.offsetParent = {
            left: parent.offset().left,
            top: parent.offset().top,
        };
        this.position.originalPosition = {
            left: this.dragElement.offsetLeft,
            top: this.dragElement.offsetTop,
        };
        this.relativeToOrigin = { x: this.dragElement.offsetLeft - this.offset.currentOffset.left, y: this.dragElement.offsetTop - this.offset.currentOffset.top };
        this.boundary = this.getElementBoundary();
        if (this.$handleElement?.length) {
            const beyond = this.getBeyond(e.pageX, e.pageY, e.pageX, e.pageY, this.getBoundary(this.$handleElement));
            if (this.$handleElement.get(0).offsetWidth > this.dragElement.offsetWidth && beyond.x === 0 && beyond.y === 0) return;
        }
        if (str) this.setElementPosition(this.dragElement, e);
    }
    pointerUp(e) {
        if (!trigger) {
            this.position.position = { left: this.dragElement.offsetLeft + this.$withinElement.offset().left, top: this.dragElement.offsetTop + this.$withinElement.offset().top };
            this.callback('onDragEnd', e, this.position);
        }
    }
    dragMoveEvent(e) {
        e.stopPropagation();
        e.preventDefault();
        if ($$.browser.name === 'firefox' && !trigger) return;
        if ($$.browser.name !== 'firefox') {
            currentX = e.pageX;
            currentY = e.pageY;
        }
        if (this.options.helper && !this.options.dropTarget) {
            this.$helper.css({ display: 'block', visibility: 'visible' });
            this.$helper.removeClass('hidden');
            this.setHelperPosition(e);
        }
        if (this.options.dropTarget) {
            this.setSafariScrollbar({ left: e.clientX, top: e.clientY }, $(this.parseElement(this.options.dropTarget)));
        } else {
            this.setElementPosition(this.dragElement, e);
        }
        this.callback('onDragging', e);
    }
    createHelper(e) {
        const { helper, dropTarget, helperBox, helperOffset } = this.options;
        let helperElement = typeof helper == 'function' ? helper() : this.parseElement(helper); // after update,helper value changed,so need re getValue
        if (helperElement) helperElement = helperElement.cloneNode(true);
        if (!dropTarget && !helperElement) helperElement = Image;

        this.$helper = $(helperElement).addClass('aui-dragging-helper').css({ position: 'absolute', left: '-100%', top: '-100%' });
        if (helper && !dropTarget) this.$helper.css({ visibility: 'hidden' });

        if (helperElement) {
            this.$appendToEle = $(helperBox ? this.parseElement(helperBox) : this.$withinElement);
            this.$appendToEle.get(0).append(this.$helper.get(0));
            e.dataTransfer.setDragImage?.(dropTarget ? helperElement : Image, -helperOffset.left, -helperOffset.top);
        }
    }
    setHelperPosition() {
        const { axis, helperBox, helperOffset } = this.options;
        const moveX = currentX - this.originX,
            moveY = currentY - this.originY,
            hl = helperOffset.left,
            ht = helperOffset.top;
        const boxArea = this.getBoundary(this.$appendToEle); // the real appended element boundary,for calculate the position
        const dragArea = this.getBoundary($(this.dragElement));
        const withinBoundary = this.getWithinBoundary(this.$appendToEle); // if coordinator has value,use this.
        const helper = this.$helper.get(0);
        const beyond = this.getBeyond(currentX + hl, currentY + ht, currentX + helper.offsetWidth + hl, currentY + helper.offsetHeight + ht, withinBoundary);
        const left = axis === 'y' ? (helperBox ? 0 : this.originX) : currentX - boxArea[0] - beyond.x + hl,
            top = axis === 'x' ? (helperBox ? 0 : this.originY) : currentY - boxArea[1] - beyond.y + ht;
        this.$helper.css({ left: left, top: top });
        const dragBeyond = this.getBeyond(dragArea[0] + moveX, dragArea[1] + moveY, dragArea[2] + moveX, dragArea[3] + moveY, this.getWithinBoundary(this.$withinElement));
        this.helperMoveX = moveX - dragBeyond.x;
        this.helperMoveY = moveY - dragBeyond.y;
    }
    getElementBoundary() {
        const c = this.withinElement,
            d = this.dragElement,
            s = this.$scrollElement.get(0),
            vBox = $(s)?.length > 0 ? (s.scrollHeight > c.scrollHeight ? s : c) : c,
            hBox = $(s)?.length > 0 ? (s.scrollWidth > c.scrollWidth ? s : c) : c,
            box = { v: vBox, h: hBox },
            dragOffset = { x: $(d).offset().left - $(hBox).offset().left, y: $(d).offset().top - $(vBox).offset().top },
            s2w = $(s)?.length > 0 ? { x: $(s).offset().left - $(c).offset().left, y: $(s).offset().top - $(c).offset().top } : { x: 0, y: 0 };

        return [
            0 - (box.h.scrollLeft + dragOffset.x) - s2w.x + this.relativeToOrigin.x,
            0 - (box.v.scrollTop + dragOffset.y) - s2w.y + this.relativeToOrigin.y,
            box.h.scrollWidth - box.h.scrollLeft - dragOffset.x - d.offsetWidth + this.relativeToOrigin.x,
            box.v.scrollHeight - box.v.scrollTop - dragOffset.y - d.offsetHeight + this.relativeToOrigin.y,
        ];
    }
    getWithinBoundary($within) {
        return this.coordinates || ($within && this.getBoundary($within));
    }
    getBoundary(c) {
        const ce = c.get(0);
        if (ce) {
            return [c.offset().left, c.offset().top, c.offset().left + ce.offsetWidth, c.offset().top + ce.offsetHeight];
        }
    }
    setElementPosition(element, e) {
        const { axis, dropTarget, grid, distance, helper } = this.options;
        if (!dropTarget) {
            if (this.options.onSetPosition) {
                if (currentX > 0) $$.fn(this.options.onSetPosition)(e, currentX, currentY);
            } else {
                if (helper) {
                    this.offset.moveDistance = { left: Math.abs(this.helperMoveX), top: Math.abs(this.helperMoveY) };
                    this.position.position = {
                        left: this.dragElement.offsetLeft + this.helperMoveX,
                        top: this.dragElement.offsetTop + this.helperMoveY,
                    };
                } else {
                    const location = grid?.length ? this.getGridPosition(element, grid) : this.getLocation(element);
                    if (location) {
                        const left = Math.abs(location.left - this.offset.currentLocal.left),
                            top = Math.abs(location.top - this.offset.currentLocal.top);
                        this.offset.moveDistance = { left: left, top: top };
                        this.dragElement.style.left = axis !== 'y' && left >= distance && location.left + 'px';
                        this.dragElement.style.top = axis !== 'x' && top >= distance && location.top + 'px';
                        this.setSafariScrollbar(location, this.$scrollElement?.length > 0 ? this.$scrollElement : this.$withinElement);
                    }
                }
            }
        }
    }
    setSafariScrollbar(location, withinElement) {
        // https://bugs.webkit.org/show_bug.cgi?id=222636 | to resolve safari bug
        if ($$.browser.name === 'safari') {
            const within = withinElement.get(0);
            const position = {
                drag: { left: $(this.dragElement).offset().left, top: $(this.dragElement).offset().top },
                within: { left: withinElement.offset().left, top: withinElement.offset().top },
            };
            if (this.options.dropTarget) {
                const dragHeight = this.$helper.length > 0 ? this.$helper.get(0).offsetHeight : this.dragElement.offsetHeight - this.offset.click.top,
                    dragWidth = this.$helper.length > 0 ? this.$helper.get(0).offsetWidth : this.dragElement.offsetWidth - this.offset.click.left;
                if (location.top + dragHeight >= position.within.top + within.offsetHeight || location.top <= position.within.top) {
                    this.scrollStep.top = location.top <= position.within.top ? this.scrollStep.top - 10 : this.scrollStep.top + 10;
                    within.scrollTop = this.scrollStep.top;
                }
                if (location.left + dragWidth >= position.within.left + within.offsetWidth || location.left <= position.within.left) {
                    this.scrollStep.left = location.left <= position.within.left ? this.scrollStep.left - 10 : this.scrollStep.left + 10;
                    within.scrollLeft = this.scrollStep.left;
                }
            } else {
                setTimeout(() => {
                    if (position.within.top + within.offsetHeight < position.drag.top + this.dragElement.offsetHeight || position.drag.top < position.within.top) {
                        within.scrollTop = location.top + this.offset.currentOffset.top;
                    }
                    if (position.within.left + within.offsetWidth < position.drag.left + this.dragElement.offsetWidth || position.drag.left < position.within.left) {
                        within.scrollLeft = location.left + this.offset.currentOffset.left;
                    }
                }, 100);
            }
        }
    }
    getGridPosition(e, grid) {
        const rangeX = (this.boundary[2] - this.boundary[0]) / grid[0],
            rangeY = (this.boundary[3] - this.boundary[1]) / grid[1];
        const location = this.getLocation(e);
        if (location) {
            let leftEnd, topEnd;
            if (Object.keys(gridPosition).length) {
                const lengthX = Math.abs(location.left - gridPosition.left);
                const lengthY = Math.abs(location.top - gridPosition.top);
                leftEnd = lengthX < rangeX / 2 ? gridPosition.left : location.left > gridPosition.left ? gridPosition.left + rangeX : gridPosition.left - rangeX;
                topEnd = lengthY < rangeY / 2 ? gridPosition.top : location.top > gridPosition.top ? gridPosition.top + rangeY : gridPosition.top - rangeY;
            } else {
                leftEnd = location.left > rangeX / 2 ? rangeX : 0;
                topEnd = location.top > rangeY / 2 ? rangeY : 0;
            }
            gridPosition = { left: leftEnd, top: topEnd };
        }
        return gridPosition;
    }
    getLocation(e) {
        const { click, offsetParent } = this.offset;
        const left = currentX - click.left,
            top = currentY - click.top;
        let clientLeft, clientTop;
        if (this.coordinates) {
            const beyond = this.getBeyond(left, top, left + e.offsetWidth, top + e.offsetHeight, this.coordinates);
            clientLeft = left - beyond.x - offsetParent.left;
            clientTop = top - beyond.y - offsetParent.top;
        } else if (currentX > 0 && currentY > 0) {
            const $within = this.$withinElement,
                $scroll = this.$scrollElement,
                element = ($scroll?.length > 0 ? $scroll : $within).get(0),
                equal = $within.equal($scroll?.get(0));
            const x = left - offsetParent.left - this.offset.currentOffset.left + (element?.scrollLeft ?? 0) - (equal ? 0 : (this.scroll?.left ?? 0)),
                y = top - offsetParent.top - this.offset.currentOffset.top + (element?.scrollTop ?? 0) - (equal ? 0 : (this.scroll?.top ?? 0));

            clientLeft = Math.max(this.boundary[0], Math.min(x, this.boundary[2]));
            clientTop = Math.max(this.boundary[1], Math.min(y, this.boundary[3]));
        }
        if (clientLeft != null && clientTop != null) {
            return {
                left: clientLeft,
                top: clientTop,
            };
        }
    }
    getBeyond(left, top, right, bottom, boundary) {
        let beyondX = 0,
            beyondY = 0;
        if (boundary) {
            beyondX = left < boundary[0] ? left - boundary[0] : right > boundary[2] ? right - boundary[2] : 0;
            beyondY = top < boundary[1] ? top - boundary[1] : bottom > boundary[3] ? bottom - boundary[3] : 0;
        }
        return {
            x: beyondX,
            y: beyondY,
        };
    }
    render() {
        return <slot />;
    }
}

/** @extends {Widget<typeof Drop.options>} */
@define('drop')
export class Drop extends Widget {
    static options = {
        sort: false,
        highlight: Types.Enum(['enter', 'dragging', false], 'dragging'),
        moveElement: true,
        onDragOver: Types.function,
        onDragEnter: Types.function,
        onDragLeave: Types.function,
        onDrop: Types.function,
    };
    static shadow = true;
    static styles = Styles;
    static observers = ['highlight'];
    method = { highlight: this.highlight };
    init() {
        this.initEvent();
    }
    didMount() {
        this.placeholder = <div className="placeholder"></div>;
    }
    insert(dropContainer, dropEle) {
        const dropElementIndex = $(dropEle).index(),
            dragElementIndex = $(dragTargetElement).index();
        if (dragElementIndex > dropElementIndex) {
            dropContainer.insertBefore(this.placeholder, dropEle);
        } else if (dropEle.nextElementSibling) {
            dropContainer.insertBefore(this.placeholder, dropEle.nextElementSibling);
        } else {
            dropContainer.append(this.placeholder);
        }
        $(this.placeholder).css({ outline: '2px solid var(--alt-8)', opacity: '0.9999' });
    }
    initEvent() {
        const $dropElement = $(this.host.children);

        this.host.addEventListener('dragover', (e) => {
            e.stopPropagation();
            e.dataTransfer.dropEffect = 'move';
            if ($dropElement.is($(dropTargetElement))) this.highlight(e.currentTarget.firstChild);
            if (this.callback('onDragOver', e) !== false) e.preventDefault();
        });
        this.host.addEventListener('dragenter', (e) => {
            e.stopPropagation();
            e.preventDefault();
            if ($dropElement.is($(dropTargetElement))) this.highlight(e.currentTarget.firstChild);
            this.callback('onDragEnter', e);
            if (this.options.sort) {
                const dropEle = $(e.target).parents('aui-drag').get(),
                    dropContainer = dropEle?.parentNode;
                if (!$dropElement.is($(dropTargetElement)) && !$dropElement.is(dropFromElementList)) return null;
                if (!$dropElement.is(e.target) && dropContainer && !$.is(dropContainer, this.host)) {
                    $('.placeholder').remove();
                    if (!$.is(dropEle, dragTargetElement)) this.insert(dropContainer, dropEle);
                }
            }
        });
        this.host.addEventListener('dragleave', (e) => {
            e.stopPropagation();
            e.preventDefault();
            if (this.options.highlight === 'enter') $(e.currentTarget.firstChild).removeClass('bg-green-important');
            this.callback('onDragLeave', e);
        });
        this.host.addEventListener('drop', (e) => {
            e.stopPropagation();
            e.preventDefault();
            $(e.currentTarget.firstChild).removeClass('bg-green-important');
            e.dataTransfer.dropEffect = 'move';
            if (!$dropElement.is($(dropTargetElement)) && !$dropElement.is(dropFromElementList)) return null;

            if (this.options.moveElement) {
                let target = e.target;
                if (target.draggable !== true) {
                    const parentList = $(e.target).parents();
                    for (const i in parentList) {
                        if (parentList[i].draggable === true) {
                            target = parentList[i];
                            break;
                        }
                    }
                }
                if ($dropElement.is(target)) {
                    target.append(dragTargetElement);
                } else if (this.options.sort) {
                    $('.placeholder').before(dragTargetElement);
                } else {
                    $dropElement.append(dragTargetElement);
                }
                $('.placeholder').remove();
            }

            const dragIndex = $(dragTargetElement).index(),
                dropIndex = $(e.target).parents('aui-drag').index();
            this.callback('onDrop', e, { from: dragIndex, to: dropIndex, element: dragTargetElement });
        });
    }
    highlight(target, start) {
        const light = start ? this.options.highlight === 'dragging' : this.options.highlight !== false;
        if (light) $(target).addClass('bg-green-important');
    }
    render() {
        return <slot />;
    }
}
