const I18N = $$.I18N.math;

/**
 * Symbol objects constructs
 * @class Symbol
 * @param {String} latex basicView latex
 * @param {String} advance advanceView latex
 * @param {String} group group
 * @param {String} style style
 * @param {Boolean} needUseWrite(true, mean using write)
 * @param {String} iconClass
 */
class MathSymbol {
    constructor(latex, advance, needUseWrite, iconClass, className) {
        this.latex = latex;
        this.advance = advance;
        this.needUseWrite = !!needUseWrite;
        this.iconClass = iconClass;
        this.className = className || '';
    }
    createTemplate(isBasic) {
        const attrs = {
            class: this.className,
            'data-advance': this.advance,
            'data-basic': this.latex,
            'data-tooltip': true,
            'data-tooltip-wrap': false,
            'aria-label': this.advance,
            'data-mq': this.needUseWrite,
        };
        return (
            <li {...attrs}>
                <aui-math-symbol latex={this.advance} />
            </li>
        );
    }
}

class AdvancedSymbol {
    constructor(advance, iconClass, className) {
        this.advance = advance;
        this.iconClass = iconClass;
        this.className = className || '';
    }
    createTemplate(isBasic) {
        let content = this.advance,
            className = this.className + ' advance';
        if (this.iconClass?.length) {
            content = <span className={this.iconClass}></span>;
            className += ' direct-display';
        }
        const titleObj = {
            '\\!': I18N.spaceXS.replace('{0}', '\\!'),
            '\\,': I18N.spaceS.replace('{0}', '\\,'),
            '\\quad': I18N.spaceL.replace('{0}', '\\quad'),
            '\\qquad': I18N.spaceXL.replace('{0}', '\\qquad'),
            '\\\\': I18N.lineBreak.replace('{0}', '\\\\'),
        };
        const attrs = {
            class: className,
            'data-advance': this.advance,
            'data-tooltip': true,
            'data-tooltip-wrap': false,
            'aria-label': this.advance === '\\;' ? I18N.spaceM.replace('{0}', '\\;') : titleObj[this.advance] || this.advance,
            style: isBasic && { display: 'none' },
        };
        return <li {...attrs}>{this.iconClass?.length ? content : <aui-math-symbol latex={content}></aui-math-symbol>}</li>;
    }
}

class Matrix {
    constructor(tooltip, icon) {
        this.tooltip = tooltip;
        this.icon = icon;
    }
    createTemplate(isBasic) {
        const attrs = {
            class: 'matrix direct-display advance',
            'data-tooltip': true,
            'data-tooltip-wrap': false,
            'aria-label': this.tooltip,
            style: isBasic && { display: 'none' },
        };
        return isBasic ? (
            ''
        ) : (
            <li {...attrs}>
                <span className={this.icon}></span>
            </li>
        );
    }
}

function contentI18N(data) {
    Object.defineProperty(data, 'content', { get: () => I18N[data.name] });
    return data;
}

