/** @jsxImportSource @gui/aui-devops */
import { define, Widget, Types } from '../../widget/widget.js';

import stringFind from '../../util/string/find.js';

import style from './style.less';

const CharCountLimit = 100000;

/**
 * CJK Unicode RegExp
 * - `Han`: Chinese
 * - `Hiragana`: Japanese Hiragana
 * - `Katakana`: Japanese Katakana
 * - `Hangul`: Korean
 */
const CJKUnicode = /\p{Script=Han}|\p{Script=Hiragana}|\p{Script=Katakana}|\p{Script=Hangul}/gu;
const ValueGetter = {
    'aui-editor': (host) => PurifyHTML(host.method('getWordCount')),
    'aui-input': (host) => host.method('getValue'),
    input: (host) => host.value,
    textarea: (host) => host.value,
};

function PurifyHTML(html) {
    // eslint-disable-next-line unicorn/prefer-string-replace-all
    html = html.replaceAll(/\uFEFF/g, '').replaceAll(/\u200B/g, '');

    const parseCell = (html, content) => {
        const { firstElementChild: node } = Document.parseHTMLUnsafe(html).body;
        node.setHTMLUnsafe(content || '');
        return node.outerHTML;
    };
    // replace empty cell to real empty (delete nbsp for counting).
    for (const str of stringFind(html, '<t(d|h)><br/?></t(d|h)>')) {
        const cell = parseCell(str),
            content = parseCell(cell, '&nbsp;');
        html = html.replace(content, cell);
    }
    return html;
}
/** Filter ignores html elements, and return text content. */
function StripContent(html) {
    const tmp = document.createElement('div');
    tmp.setHTMLUnsafe(html);
    // ignore svg element.
    tmp.querySelectorAll('svg').forEach((svg) => svg.remove());
    return tmp.textContent || '';
}

/** @extends {Widget<typeof Wordcount.options>} */
@define('wordcount')
export class Wordcount extends Widget {
    static options = {
        countBy: Types.Selector,
        type: Types.Enum(['char', 'word'], 'char'),
        format: '{0}',
        max: -1,
        limit: -1,
        bufferLimit: false,
        onUpdate: Types.function,
    };
    static observers = ['type', 'max', 'limit', 'bufferLimit', 'format'];
    static styles = style;

    #getValue = null;
    #loaded = false;
    #timer = 0;
    init() {
        this.state = {
            status: 'normal',
            count: 0,
            lastCount: -1,
        };
    }
    didMount() {
        const { countBy } = this.options,
            countByTarget = this.parseElement(countBy),
            name = countByTarget?.localName,
            valueGetter = ValueGetter[name];
        if (valueGetter) {
            this.#getValue = () => valueGetter(countByTarget);
            this.updateStatus();
            countByTarget.addEventListener('input', $$.throttle(this.onInput));
        } else if (countByTarget) {
            this.console.error(`The countBy element isn't supported: `, name);
        } else {
            this.console.error(`The countBy element is not found: `, countBy);
        }
        this.#loaded = true;
    }
    onInput = () => {
        this.setState({ count: this.getCount() });
        if (this.options.max > 0) {
            const delay = this.nearLimits() ? 5 : 250;
            clearTimeout(this.#timer);
            this.#timer = setTimeout(this.updateStatus, delay);
        }
    };
    nearLimits() {
        const { bufferLimit, max, limit, type } = this.options,
            countMax = bufferLimit ? limit : max,
            nearCount = type === 'char' ? 20 : 5;
        return countMax > -1 && countMax - this.state.lastCount < nearCount;
    }
    getCount() {
        const content = this.#getValue();
        return this.countValue[this.options.type](content);
    }
    countValue = {
        /** @param {string} text */
        char: (text) => {
            const normalizedText = StripContent(text).replaceAll('\r', '').replaceAll('\n', '').replaceAll('\t', '').replaceAll('&nbsp;', ' ');
            // When includes `CJK characters` or `surrogate pairs unicode`(such as emoji), string.length may be greater than real count.
            return Array.from(normalizedText).length;
        },
        word: (text) => {
            let normalizedText = text.replaceAll(/(<([^>]+)>)/gi, ' '); // replace html tags with spaces for count words.
            normalizedText = StripContent(normalizedText)
                .replaceAll(/(\r\n|\r|\n|\u2028|\u2029|\t)/gm, ' ') // replace new lines(in many forms)
                .replaceAll('&nbsp;', ' ') // replace html entities indicating a space
                .trim();

            const CJKWordCount = (normalizedText.match(CJKUnicode) || []).length;
            if (CJKWordCount > 0) this.console.warn(`CJK characters typically don't apply to counting by words.`, 'Please check the logic.');
            normalizedText = normalizedText.replaceAll(CJKUnicode, ' ');

            const words = normalizedText.split(/\s+/);
            for (let wordIndex = words.length - 1; wordIndex >= 0; wordIndex--) {
                if (!words[wordIndex] || /^(\s*)$/.test(words[wordIndex])) {
                    words.splice(wordIndex, 1);
                }
            }

            return words.length + CJKWordCount;
        },
    };
    updateStatus = () => {
        const count = this.getCount(), // should get realtime data.
            { max, bufferLimit, limit } = this.options,
            { lastCount } = this.state;

        if (count === lastCount) {
            const countMax = bufferLimit ? limit : max;
            if (countMax > -1 && count <= max) return true;
        }
        const delta = count - lastCount;
        this.setState({ lastCount: count }, false);
        this.handleUpdate({
            enable: max > -1 || (bufferLimit && limit > -1),
            count,
            delta: delta >= 0,
        });
    };
    handleUpdate(data) {
        const { bufferLimit, limit, max, type } = this.options,
            { count, delta, enable } = data; // eslint-disable-line no-unused-vars
        let status = 'normal';
        if (enable) {
            if (bufferLimit && limit > -1 && count > limit) {
                status = 'limit';
            } else if (bufferLimit && limit > -1 && count === limit) {
                status = 'max';
            } else if (max > -1 && count > max) {
                status = bufferLimit ? 'over' : 'limit';
            } else if (max > -1 && count === max) {
                status = bufferLimit ? 'over' : 'max';
            }
        } else {
            /** The hard limit status. */
            status = type === 'char' && count > CharCountLimit ? 'limit' : 'normal';
        }
        this.setState({ status, count });
        this.triggerCallback({ status, count });
    }
    triggerCallback(...args) {
        const cb = () => this.callback('onUpdate', ...args);
        return this.#loaded ? cb() : setTimeout(cb);
    }
    formatCount(count) {
        const { format, max } = this.options;
        return format.replace('{0}', count).replace('{1}', max);
    }
    render() {
        const { status, count } = this.state;
        return (
            <span className="wordcount" data-status={status}>
                {this.formatCount(count)}
            </span>
        );
    }
}
