import arrayLike from '../../util/array/is-like.js';

import nodeList from './node-list.js';
import { getElementStrict } from './parse.js';

export function remove() {
    const node = this;
    // eslint-disable-next-line unicorn/prefer-dom-node-remove
    node.parentNode.removeChild(node);
}
export function setChildren(children) {
    const node = this;
    const nodes = nodeList(children);
    node.replaceChildren();
    node.append(...nodes);
}
export function append(...args) {
    const node = this;
    node.append(...nodeList(args));
}
export function prepend(...args) {
    const node = this;
    node.prepend(...nodeList(args));
}
function moveBefore(parent, target, reference) {
    try {
        parent.moveBefore(target, reference || null);
    } catch (e) {
        parent.insertBefore(target, reference || null);
    }
}
export function before(element) {
    const node = this;
    moveBefore(node.parentNode, getElementStrict(element), node);
}
export function after(element) {
    const node = this;
    moveBefore(node.parentNode, getElementStrict(element), node.nextElementSibling);
}
export function replace(nodes) {
    const parent = this.parentNode;
    let [node, ...restNodes] = arrayLike(nodes) ? nodes : arguments;
    parent.replaceChild(node, this);
    for (const n of restNodes) {
        parent.insertBefore(n, node.nextSibling || null);
        node = n;
    }
}
export function wrap(element) {
    const node = this;
    element = getElementStrict(element);
    before.call(node, element);
    element.append(node);
}
export function unwrap(box) {
    const node = this;
    box = getElementStrict(box) || node.parentNode;
    const [...children] = box.childNodes;
    for (const child of children) {
        before.call(box, child);
    }
    remove.call(box);
}

export function clone(deep) {
    const node = this;
    return node.cloneNode(!!deep);
}
