        BODY_CLASS: 'aui-basecalendar-body',
        CELL_CLASS: 'aui-basecalendar-cell',
        DATE_CLASS: 'aui-basecalendar-date',
        DATE_BOX_CLASS: 'aui-basecalendar-date-box',
        CONTENT_CLASS: 'aui-basecalendar-content',
        ACTIVE_CLASS: 'active',
        DISABLED_CLASS: 'disabled',
