import spaceReg from '../regexp/space.js';

/** @type {typeof $$.string.trim} */
export default function trim(str, mode) {
    const regStr = spaceReg(mode),
        trimBeginRegexp = new RegExp('^' + regStr),
        trimEndRegexp = new RegExp(regStr + '$');
    return String(str).replace(trimBeginRegexp, '').replace(trimEndRegexp, '');
}
