import { I18N } from '../../core/base/i18n.js';

import local from './local.js';

/** @type {typeof $$.number.separator} */
export default function separator(num, char = I18N.core.numberSeparator, digits = 3) {
    const data = String(num).split('.'),
        list = data[0].split(''),
        point = local(0.1).split('')[1];
    let index = 0;
    for (let i = list.length - 1; i >= 0; i--) {
        if (index > 0 && index % digits === 0) {
            list[i] = list[i] + char;
        }
        index++;
    }
    data[0] = list.join('');
    return data.join(point);
}
