import { elementGet, elementSet, elementMergeSet } from '../../../misc/element-storage.js';
import { config } from '../../base/config.js';
import { onload } from '../../base/onload.js';

import arrayDelete from '../../../util/array/delete.js';
import arrayLast from '../../../util/array/last.js';
import objectEmpty from '../../../util/object/empty.js';
import objectEntriesOrder from '../../../util/object/entries-order.js';
import objectExtendNull from '../../../util/object/extend-null.js';
import objectFilter from '../../../util/object/filter.js';
import objectForEach from '../../../util/object/for-each.js';
import objectMap from '../../../util/object/map.js';
import stringHash from '../../../util/string/hash-53.js';
import { isEmpty as typeIsEmpty } from '../../../util/type/types.js';

let uuid = 0;
function elementRect(el, reAssign) {
    let obj = el.getBoundingClientRect();
    if (reAssign !== false) {
        obj = objectMap(obj, true, false);
        delete obj.toJSON;
    }
    return obj;
}
function useDisconnect(key, observer, element) {
    return function () {
        observer.disconnect();
        elementSet(element, key, undefined);
    };
}

export const dom = (function () {
    const mapping = {};
    function getKey(name, args) {
        const _args = objectFilter(args, (k, v) => v && !typeIsEmpty(v));
        Object.assign(objectEmpty(args), _args);
        const key = stringHash(objectEntriesOrder(args));
        return `observer.${name}.${key}`;
    }
    function useDisconnect(key, element, callback) {
        return function () {
            const exists = elementGet(element, key);
            arrayDelete(exists, (fn) => fn === callback);
            if (!exists.length) {
                const observer = mapping[key];
                elementSet(element, key, undefined);
                observer.disconnect();
                delete mapping[key];
            }
        };
    }
    function useProxy(key, element) {
        return function (...args) {
            const list = elementGet(element, key);
            list.forEach((fn) => $$.fn(fn)(...args));
        };
    }
    return function (element, callback, args = {}) {
        const id = uuid++,
            key = id + getKey('dom', objectExtendNull(args, { attributes: false, childList: true, subtree: false }));
        elementMergeSet(element, key, [callback], function () {
            const observer = new MutationObserver(useProxy(key, element));
            observer.uuid = id;
            observer.observe(element, args);
            mapping[key] = observer;
        });
        return { disconnect: useDisconnect(key, element, callback) };
    };
})();

export const domRemove = (function () {
    const queue = {};
    function useDisconnect(id) {
        return () => delete queue[id];
    }
    onload(function () {
        function proxy([record]) {
            const nodes = Array.prototype.filter.call(record.removedNodes || [], (node) => node.nodeType === Node.ELEMENT_NODE);
            if (nodes.length) {
                objectForEach(queue, function (id, [element, selector, callback]) {
                    if (element && !element.isConnected) {
                        useDisconnect(id)(); // element un-exists in dom tree, remove its observer.
                    } else {
                        for (const node of nodes) {
                            if (!element || node.contains(element)) {
                                const box = element || node;
                                let results = [box];
                                if (selector) {
                                    results = Array.from(box.querySelectorAll(selector));
                                    if (box.matches(selector)) results.unshift(box);
                                }
                                if (results.length) callback(results);
                            }
                        }
                    }
                });
            }
        }
        dom(config.body, proxy, { childList: true, subtree: true });
    });
    return function (element, callback, selector) {
        const id = uuid++;
        queue[id] = [element, selector, callback];
        return { disconnect: useDisconnect(id) };
    };
})();

export const resize = (function () {
    const key = 'observer.resize.rect';
    function useProxy(args, callback) {
        return function ([entry]) {
            const el = entry.target,
                rect = elementRect(el),
                prevRect = elementGet(el, key);
            if (el.isConnected) {
                let widthChange = prevRect.width !== rect.width,
                    heightChange = prevRect.height !== rect.height;
                if (args) {
                    const { width: w, height: h, ifneed } = args;
                    widthChange = typeof w === 'number' ? Math.abs(prevRect.width - rect.width) > w : w && widthChange;
                    heightChange = typeof h === 'number' ? Math.abs(prevRect.height - rect.height) > h : h && heightChange;
                    const change = widthChange || heightChange;
                    if (change || ifneed === false) callback(rect, prevRect, !!change);
                } else if (widthChange || heightChange) {
                    callback(rect, prevRect);
                }
                Object.assign(prevRect, rect);
            }
        };
    }
    return function (element, callback, args) {
        const observer = new ResizeObserver(useProxy(args, callback));
        observer.uuid = uuid++;
        elementMergeSet(element, key, elementRect(element), () => observer.observe(element));
        return { disconnect: useDisconnect(key, observer, element) };
    };
})();

export const scroll = (function () {
    const key = 'observer.scroll.data';
    function thresholdArray(count) {
        const multiple = 100 / count,
            list = Array.from({ length: count }, (_, i) => Math.round(i * multiple) / 100);
        list.push(1);
        return list;
    }
    function data(element, ratio) {
        const { left, top } = element.getBoundingClientRect();
        return { x: left, y: top, ratio };
    }
    function useProxy(element, args, callback) {
        return function (entries) {
            const entry = arrayLast(entries),
                { target, isIntersecting, intersectionRatio } = entry;
            if (target.isConnected) {
                const current = data(target, intersectionRatio),
                    prev = elementGet(element, key);
                if (prev) {
                    // vertical
                    if (current.y < prev.y || (args.equalV && current.y === prev.y)) {
                        if (args.endV) callback(isIntersecting, true);
                    } else if (current.y > prev.y) {
                        if (args.startV) callback(isIntersecting, false);
                    }

                    // horizontal
                    if (current.x < prev.x || (args.equalH && current.x === prev.x)) {
                        if (args.endH) callback(isIntersecting, true);
                    } else if (current.x > prev.x) {
                        if (args.startH) callback(isIntersecting, false);
                    }
                    Object.assign(objectEmpty(prev), current);
                } else {
                    elementSet(element, key, current);
                }
            }
        };
    }
    return function (element, args, callback) {
        const target = $$.getUniqueElement(args.target);
        const observer = new IntersectionObserver(useProxy(element, args, callback), {
            root: element.nodeName === 'BODY' ? null : element,
            threshold: thresholdArray(args.rate || 1),
            rootMargin: args.rootMargin || '0px',
        });
        observer.uuid = uuid++;
        elementMergeSet(element, key, data(target, 0), () => observer.observe(target));
        return { disconnect: useDisconnect(key, observer, element) };
    };
})();

Object.assign($$, {
    observer: {
        dom,
        domRemove,
        resize,
        scroll,
    },
});
