import { throws } from '../../core/base/log.js';

import { isElement as typeIsElement } from '../../util/type/types.js';

const getInstance = (function () {
    /** @type {import('dompurify').DOMPurify} */
    let instance;
    return function () {
        if (!instance) {
            const DOMPurify = window.DOMPurify || window.top.DOMPurify;
            if (!DOMPurify) return throws("The DOMPurify library hasn't been imported correctly!");
            const ver = Number.parseFloat(DOMPurify.version);
            if (!ver || Number.isNaN(ver) || ver < 3) return throws('The DOMPurify version is not supported!');
            instance = DOMPurify(window);
            initHooks(instance);
        }
        return instance;
    };
})();

function initHooks(Purify) {
    Purify.addHook('uponSanitizeAttribute', function (node, data, config) {
        const { localName } = node,
            { attrName, attrValue } = data;
        if (attrName === 'class') {
            if (config.FORBID_ATTR?.includes('class')) {
                data.attrValue = attrValue
                    .split(' ')
                    .filter((c) => c.startsWith('aui-')) // force keep aui classNames.
                    .join(' ');
                node.setAttribute('class', data.attrValue);
                data.forceKeepAttr = true;
            }
        } else if (attrName === 'style') {
            // eslint-disable-next-line unicorn/no-lonely-if
            if (!config.FORBID_ATTR?.includes('style')) {
                config.FORBID_STYLE?.forEach((s) => (node.style[s] = null));
                if (node.getAttribute('style')) {
                    data.forceKeepAttr = true;
                } else {
                    node.removeAttribute('style');
                    data.keepAttr = false;
                }
            }
        }

        if (localName === 'input' || localName === 'button') {
            // eslint-disable-next-line unicorn/no-lonely-if
            if (attrName === 'type' && (attrValue === 'submit' || attrValue === 'reset')) {
                node.setAttribute('type', 'button');
                data.forceKeepAttr = true;
            }
        }
    });
    Purify.addHook('afterSanitizeAttributes', function (node) {
        if (node.localName === 'button' && !node.hasAttribute('type')) {
            node.setAttribute('type', 'button');
        }
    });
}

const DefaultConfig = {
    ADD_ATTR: ['target', 'href', 'contenteditable', 'rules'],
    FORBID_TAGS: ['form', 'style'],
};
const DefaultConfigMap = {
    ...DefaultConfig,
    ALLOWED_TAGS: [],
    ALLOWED_ATTR: [],
    FORBID_ATTR: [],
    ADD_TAGS: [],
    FORBID_STYLE: ['appearance', 'contentVisibility', 'float', 'inset', 'isolation', 'order', 'overflow', 'position', 'zIndex'],
};
const ConfigScheme = {
    Editor: {
        ADD_TAGS: ['iframe'],
        ADD_ATTR: ['allowfullscreen', 'allowTransparency', 'frameborder'],
        FORBID_STYLE: DefaultConfigMap.FORBID_STYLE,
    },
};

function combineConfigArray(...args) {
    const arr = args.flatMap((v) => (Array.isArray(v) ? v : []));
    return Array.from(new Set(arr));
}

/**
 * @typedef {true} useDefaultConfig using the DefaultConfigMap value.
 * @typedef {false} disableDefaultConfig disable DefaultConfig value.
 * @param {Record<string, useDefaultConfig|disableDefaultConfig|string[]>} args
 */
function serializeConfig(args) {
    const { scheme, ...config } = structuredClone(args || {}),
        schemeConfig = ConfigScheme[scheme] || {};
    for (const [k, v] of Object.entries(DefaultConfigMap)) {
        const val = config[k];
        if (val === true) {
            config[k] = v;
        } else if (val === false) {
            delete config[k];
        } else if (Array.isArray(v)) {
            config[k] = combineConfigArray(DefaultConfig[k], schemeConfig[k], val);
            if (!config[k].length) delete config[k];
        } else {
            config[k] = val ?? schemeConfig[k] ?? DefaultConfig[k];
            if (config[k] == null) delete config[k];
        }
    }
    return config;
}

export function purify(html, args) {
    if (!html || typeof html !== 'string') return '';
    const config = serializeConfig(args);
    return getInstance()?.sanitize(html, config) ?? '';
}

export function htmlPurify(html, args) {
    const content = purify(html, args);
    // eslint-disable-next-line aui/inner-html
    if (typeIsElement(this)) this.innerHTML = content;
    return content;
}
