import { error } from '../core/base/log.js';

import { isObject } from '../util/type/types.js';
import { getValue, setValue } from '../util/value-path.js';

const key = '__auiStorage';

export function elementGet(element, k) {
    if (!element[key]) {
        element[key] = {};
        return;
    }
    return getValue(element[key], k);
}

export function elementSet(element, k, v) {
    if (!element[key]) element[key] = {};
    setValue(element[key], k, v);
}

export function elementMergeSet(element, k, v, init) {
    const val = elementGet(element, k);
    if (val == null) {
        $$.fn(init)();
        elementSet(element, k, v); /// v ?? result
    } else if (v !== null) {
        if (Array.isArray(val)) {
            elementSet(element, k, val.concat(v));
        } else if (isObject(val)) {
            Object.assign(val, v);
        } else {
            return error('Only Array&Object is supported for merge!');
        }
    }
    return elementGet(element, k);
}
