/** @jsxImportSource @gui/aui-devops */
import $ from '../../core/element/index.js';
import { define, Widget, Types, registerValidation } from '../../widget/widget.js';

import length from '../../util/css/length.js';
import { initCapsLock, listenCapsLock } from '../../util/event/caps-lock.js';
import { keyName } from '../../util/event/key-name.js';
import stopEvent from '../../util/event/stop.js';
import numberClamp from '../../util/number/clamp.js';
import numberLocal from '../../util/number/local.js';
import pointFix from '../../util/number/point-fix.js';
import regexpSpace from '../../util/regexp/space.js';
import padStart from '../../util/string/pad-start.js';
import { isEmail as typeIsEmail } from '../../util/type/verify.js';

const I18N = $$.I18N.input;
const ValidationI18N = $$.I18N.validation;
const ClassName = {
    Target: 'aui-input-target',
    ActionBox: 'aui-input-action-box',
    Action: 'aui-input-action',
    Message: 'aui-input-message',
};
const PwdClassName = {
    tempShow: 'faui-eye',
    tempHide: 'faui-eye-slash',
};
const Pointer = numberLocal(0.1).split('')[1];
const iPhone = $$.browser.os.name === 'ios' && $$.browser.os.device === 'phone';
// Check virtualKeyboard IME done action.
let iPhoneDoneIME = false;
const Max_Safe_Digits_Int = 9,
    Max_Safe_Digits_Float = 15;
const BlankReg = new RegExp(regexpSpace(['tab', 'space'], ['\u3000']), 'g');
const API = {
    number: {
        value: Types.number,
        min: Types.number,
        max: Types.number,
        step: 1,
        float: 0,
        fixFloat: true,
        fixInt: 0,
        loop: false,
        hasControl: false,
    },
    password: {
        reveal: false,
        showCapsLock: false,
    },
    textarea: {
        rows: Types.number,
        resize: Types.string,
    },
    tel: {
        // countryCode: Types.boolean,
    },
};

/** @extends {Widget<typeof Input.options>} */
@define('input')
@registerValidation({ name: 'Input', changeEvent: 'change', sensitiveEvent: 'input', requireType: 'Editable' })
export class Input extends Widget {
    static options = {
        type: Types.Enum(['text', 'number', 'password', 'textarea', 'tel', 'email'], 'text'),
        name: Types.string,
        value: '',
        tooltip: Types.string,
        disabled: false,
        readonly: false,
        placeholder: Types.string,
        maxlength: Types.number,
        block: false,
        border: true,
        width: Types.Length,
        height: Types.Length,
        autocomplete: Types.Union([Types.boolean, Types.string], false),
        classify: Types.string,
        align: Types.Enum(['start', 'center', 'end'], 'start'),
        attrs: Types.object,
        onChange: Types.function,
        onFocus: Types.function,
        onInput: Types.function,
        onBlur: Types.function,
        onEnter: Types.function,
    };
    static observers = ['type', 'name', 'value', 'tooltip', 'disabled', 'readonly', 'placeholder', 'maxlength', 'width', 'height', 'classify', 'attrs', 'min', 'max', 'step'];
    static ariaTarget = '.' + ClassName.Target;
    static shadow = false; /// { delegatesFocus: true };
    // static formAssociated = true;

    /** @returns {ValueOf<typeof API>} */
    instanceOptions = () => API[this.options.type];
    create() {
        this.method = {
            getValue: this.getValue,
            setValue: (value) => {
                this.setValue(value, true);
            },
            checkValidation: () => {
                const value = this.method.getValue();
                if (value && this.options.type === 'email') {
                    return typeIsEmail(value) ? value : new EvalError(ValidationI18N.rules.isEmail);
                } else {
                    return value;
                }
            },
        };
    }
    init() {
        this.composition = false;
        this.state = {
            maxlength: this.setMaxLength(),
            dirty: false,
        };
        this.val = this.preprocessValue(this.options.value);
    }
    getValue = () => {
        return this.val;
    };
    preprocessValue = (value) => {
        const { type } = this.options;
        value = this.sliceValueByMaxLength(value);
        return type === 'number' ? this.checkNumber(value) : this.replaceAllBlankToSpace(value);
    };
    setMaxLength(value = this.options.maxlength) {
        const max = 255;
        switch (this.options.type) {
            case 'textarea':
                return value > 0 ? value : null;
            case 'number':
                return value > 0 ? value : this.options.float === 0 ? Max_Safe_Digits_Int : Max_Safe_Digits_Float;
            default:
                return value > 0 ? value : max;
        }
    }

    sliceValueByMaxLength(value) {
        const { maxlength } = this.state,
            str = String(value);
        if (maxlength && str.length > maxlength) {
            return str.slice(0, maxlength);
        }
        return value;
    }
    replaceAllBlankToSpace(value) {
        return value.replaceAll(BlankReg, (match) => String(' ').repeat(match.length));
    }
    verify() {
        const value = this.getValue(),
            valid = this.options.type !== 'email' || typeIsEmail(value) ? null : ValidationI18N.rules.isEmail;
        return [value, valid];
    }
    didMount() {
        const type = this.options.type,
            query = '.' + ClassName.Target;
        let onCapsLockChange;
        if (type === 'password' && this.options.showCapsLock) {
            const message = this.host.querySelector('.' + ClassName.Message);
            onCapsLockChange = (locked) => (message.textContent = locked ? I18N.capsLockOn : '');
            initCapsLock();
        }
        this.actionElement = this.host.querySelector('.' + ClassName.Target);
        /** change: fires after enter or blur. */
        this.$host.on('change', query, (e) => {
            const value = e.currentTarget.value;
            let val = this.preprocessValue(value);
            const _val = String(val);

            if (_val !== String(value)) this.setValue(val);
            if (type === 'number') val = _val.length ? Number(val.replace(Pointer, '.')) : '';
            if (type === 'email' && val) val = val.trim();
            this.setState({ dirty: true });
            this.callback('onChange', val, e);
        });

        this.lastEnterValue = null;
        this.$host.on('keyup', query, (e) => {
            const name = keyName(e);
            if (name === 'Control+Enter' || (name.endsWith('Enter') && type !== 'textarea')) {
                let value = e.currentTarget.value;
                if (type === 'number' && value) value = Number(value.replace(Pointer, '.'));
                if (type === 'email' && value) value = value.trim();
                if (this.lastEnterValue !== value) {
                    const result = this.callback('onEnter', value);
                    if (result != null && result !== value) {
                        this.setValue(result);
                        value = result;
                    }
                    this.lastEnterValue = value;
                }
            }
        });

        // input: fires on every key inputs; update state value.
        this.$host.on('input', query, (e) => {
            if (this.composition === true) return;
            this.onInput(e);
        });
        this.actionElement.addEventListener('focus', (e) => {
            if (onCapsLockChange) listenCapsLock(onCapsLockChange, true);
            this.callback('onFocus', e);
        });
        this.actionElement.addEventListener('blur', (e) => {
            if (onCapsLockChange) listenCapsLock(onCapsLockChange, false);
            if ((type === 'number' || type === 'email') && iPhoneDoneIME && e.relatedTarget === null) {
                let value = e.currentTarget.value;
                if (type === 'number' && value) value = Number(value.replace(Pointer, '.'));
                if (type === 'email' && value) value = value.trim();
                this.callback('onEnter', value);
            }
            this.callback('onBlur', e);
        });
        this.$host.on('compositionstart', query, (e) => {
            this.composition = true;
            this.compositionValue = null;
        });
        this.$host.on('compositionend', query, (e) => {
            this.composition = false;
            this.onInput(e, this.compositionValue);
            this.compositionValue = null;
        });
        if (type === 'number') {
            if (this.options.hasControl) {
                // number up&down key.
                this.$host.on('keydown', query, (e) => {
                    if (this.options.readonly) {
                        return;
                    }
                    const name = keyName(e);
                    switch (name) {
                        case 'ArrowUp':
                            this.setNumber(1);
                            return stopEvent(e);
                        case 'ArrowDown':
                            this.setNumber(-1);
                            return stopEvent(e);
                    }
                });
            }
            this.$host.on('compositionupdate', query, (e) => {
                this.compositionValue = e.currentTarget.value;
            });
        }
    }
    setOption(name, value, oldValue) {
        switch (name) {
            case 'value': {
                const val = this.preprocessValue(value ?? '');
                if (val === oldValue || String(this.val) === String(val)) return false;
                this.setValue(val, true);
                this.lastEnterValue = val;
                this.actionElement.dispatchEvent(new InputEvent('input', { bubbles: true, composed: true }));
                break;
            }
            case 'min':
            case 'max':
                this.setValue(this.checkNumber(this.val), true);
                break;
            case 'maxlength':
                this.setState({ maxlength: this.setMaxLength(value) }, false);
                break;
        }
    }
    render() {
        const { type, name, tooltip, disabled, readonly, placeholder, border, block, width, height, autocomplete, classify, align, attrs } = this.options,
            { maxlength } = this.state,
            arias = this.arias({ ariaLabel: tooltip }),
            _attrs = { name, disabled, readonly, placeholder, maxlength, ...attrs, ...arias, style: { ...attrs?.style } };
        Object.assign(_attrs, {
            className: [ClassName.Target, classify && 'aui-input-classify-' + classify, 'align-' + align],
            autocomplete: typeof autocomplete === 'string' ? autocomplete : autocomplete ? 'on' : 'off',
            enterkeyhint: type === 'textarea' ? 'enter' : 'done',
            dataClassify: classify,
            dataTooltip: tooltip ? 'true' : 'ifneed',
        });

        return (
            <div className={['aui-input', border && 'with-border', block && 'block']} data-dirty={this.state.dirty} style={{ width: length(width), height: length(height) }}>
                {this.renderInput(type, _attrs)}
                <div className={['empty-hidden', ClassName.ActionBox]} hidden={disabled || readonly} onClick={this.onAction}>
                    {this.renderAction(type)}
                </div>
                {type === 'password' && <div className={['empty-hidden', ClassName.Message]} />}
            </div>
        );
    }
    renderInput(type, attrs) {
        /* eslint-disable aui/require-autocomplete -- includes in attrs */
        // text, textarea, password, number
        switch (type) {
            case 'text':
            case 'email':
            case 'tel':
                return <input type={type} {...attrs} value={this.val} />;
            case 'textarea': {
                const { resize, rows } = this.options;
                attrs.style.resize = resize;
                if (rows > 0) attrs.rows = rows;
                return <textarea {...attrs}>{this.val}</textarea>;
            }
            case 'password': {
                const input = <input type="password" {...attrs} />;
                input.value = this.val;
                return input;
            }
            case 'number': {
                const { min, max, step, float } = this.options,
                    intOnly = float === 0,
                    positive = min > 0 || min === 0;
                Object.assign(attrs, {
                    type: 'text',
                    role: 'spinbutton',
                    value: String(this.val).replace('.', Pointer),
                    step,
                    inputmode: intOnly ? 'numeric' : 'decimal',
                    ...$$.arias({ ariaValueMin: min, ariaValueMax: max, ariaRoleDescription: I18N.number }),
                });
                if (iPhone && !positive) {
                    Object.assign(attrs, {
                        type: 'number',
                        inputmode: null,
                        onFocus: (e) => setTimeout(() => (e.target.type = 'text')),
                        onBlur: (e) => (e.target.type = 'number'),
                    });
                }
                return <input {...attrs} />;
            }
        }
        /* eslint-enable aui/require-autocomplete */
    }
    renderAction(type) {
        switch (type) {
            case 'number':
                if (!this.options.hasControl) return null;
                return (
                    <>
                        <div className={[ClassName.Action, 'faui-angle-up-s']} data-action="+1" />
                        <div className={[ClassName.Action, 'faui-angle-down-s']} data-action="-1" />
                    </>
                );
            case 'password': {
                if (!this.options.reveal) return null;
                const cb = this.onReveal;
                const args = $$.browser.touchable ? { onTouchStart: cb, onTouchMove: cb, onTouchEnd: cb, onTouchCancel: cb } : { onMouseDown: cb, onMouseUp: cb, onMouseLeave: cb };
                return (
                    <div className={ClassName.Action} {...args}>
                        <span className={PwdClassName.tempHide} />
                    </div>
                );
            }
        }
        return null;
    }
    setValue(val, force) {
        const { type } = this.options;
        val = this.sliceValueByMaxLength(val);
        this.val = val;
        val = String(val);
        if (type === 'number') val = val.replace('.', Pointer);
        if (type === 'email') val = val.trim();
        if (force || this.actionElement.value !== val) this.actionElement.value = val;
    }
    onAction = (e) => {
        const action = e.target?.dataset?.action;
        switch (action) {
            case '+1':
                return this.setNumber(1);
            case '-1':
                return this.setNumber(-1);
        }
    };
    #filterByType(value) {
        switch (this.options.type) {
            case 'number':
                return this.filterNumber(value);
            case 'email':
                return value.trim();
            case 'tel':
                return value.replaceAll(/[^\d\s\-()]/g, '').replaceAll(/\s{2,}/g, ' ');
        }
        return value;
    }
    onInput = (e, value) => {
        const input = e.currentTarget,
            oldValue = this.val,
            max = input.maxLength;
        value = value || input.value;
        if (max > 0 && value.length > max) value = value.slice(0, max);
        value = this.#filterByType(value);
        if (String(value) !== String(oldValue) && this.callback('onInput', value) === false) value = oldValue;
        this.setValue(value);
    };
    onReveal = (e) => {
        const icon = e.currentTarget.firstChild,
            input = this.actionElement;
        let { type } = e;
        if (type.startsWith('touch') && type !== 'touchstart') type = 'mouseleave';
        switch (type) {
            case 'mousedown':
            case 'touchstart':
                setTimeout(() => {
                    icon.setAttribute('class', PwdClassName.tempShow);
                    input.type = 'text';
                });
                break;
            case 'mouseup':
            case 'mouseleave':
                setTimeout(() => {
                    icon.setAttribute('class', PwdClassName.tempHide);
                    input.type = 'password';
                    if ($$.browser.touchable) {
                        $(input).trigger('change');
                    }
                });
                break;
        }
    };
    filterNumber(value) {
        const { min, float } = this.options,
            positive = min > 0 || min === 0;
        let arr = value.split(''),
            hasPointer = float === 0;
        arr = arr.map((char, i) => {
            switch (char) {
                case '-':
                    return !positive && i === 0 ? char : '';
                case Pointer:
                    if (!hasPointer) {
                        hasPointer = true;
                        return char;
                    }
                    return '';
                default:
                    return /\d/.test(char) ? char : '';
            }
        });
        return arr.join('');
    }
    float(value, pointer) {
        const { float, fixFloat } = this.options;
        let [intPart, decimalPart] = String(value).split(pointer);
        const negative = intPart.startsWith('-');
        intPart = intPart.replace(/^-/, '').replace(/^0+/, '') || '0';
        if (float === 0) {
            decimalPart = '';
        } else if (float > 0) {
            decimalPart = (decimalPart || '').slice(0, float);
            if (fixFloat) decimalPart = decimalPart.padEnd(float, '0');
        } else if (!decimalPart) {
            decimalPart = '0';
        }
        if (decimalPart && !fixFloat) {
            decimalPart = decimalPart.replace(/0+$/, ''); // eslint-disable-line aui/no-unsafe-regex
        }
        const v = decimalPart ? `${intPart}.${decimalPart}` : intPart;
        return negative && v !== '0' ? '-' + v : v;
    }
    checkNumber(value, checkLoop) {
        if (this.options.type !== 'number') return value;
        if ((!value && typeof value !== 'number') || Number.isNaN(value)) return '';
        let { min, max, fixInt, loop } = this.options;
        if (typeof value === 'number') value = String(value).replace('.', Pointer);
        let val = value.replaceAll(/[a-z]/gi, '');
        if (!val) return '';
        if (!checkLoop) loop = false;
        // fix float
        val = this.float(val, Pointer);
        // fix limit & loop
        if (max != null && val > max) {
            val = loop ? min : max;
            val = this.float(val, '.');
        } else if (min != null && val < min) {
            val = loop ? max : min;
            val = this.float(val, '.');
        }
        // fix float again
        val = this.float(val, '.');
        // fix int
        if (fixInt > 0) val = padStart(val, fixInt);
        // this.setValue(val);
        return String(val).replace('.', Pointer);
    }
    setNumber(addend) {
        const { min, max, step } = this.options,
            input = this.actionElement;
        let val = Number(this.actionElement.value);
        if (Number.isNaN(val)) val = numberClamp(min, 0, max);
        val = pointFix(val + addend * (step ?? 1));
        val = this.checkNumber(val, true);
        this.setValue(val);
        input.focus();
        this.callbackInterval(function () {
            $(input).trigger('change');
        });
    }

    callbackInterval(...args) {
        clearTimeout(this._callbackIntervalTimer);
        this._callbackIntervalTimer = setTimeout(() => {
            const first = args[0];
            if (args.length === 1 && typeof first === 'function') {
                // only callback argument.
                return first.call(this);
            }
            this.callback(...args);
        }, 150);
    }
}

if (iPhone) {
    let moved = false;
    document.addEventListener('touchstart', () => (iPhoneDoneIME = false));
    document.addEventListener('click', () => (iPhoneDoneIME = true));
    document.addEventListener('touchmove', () => {
        moved = true;
        iPhoneDoneIME = false;
    });
    document.addEventListener('touchend', () => {
        if (moved) {
            moved = false;
            iPhoneDoneIME = true;
        }
    });
}
