import { isDeferred } from '../../util/type/types.js';

import { error } from './log.js';

const noop = function () {};

/**
 * @template T
 * @param {T} result A sync/async return value.
 * @param {((value: T) => void) | ((value: false, err: Error) => void)} callback A callback function, the value is the sync result, or return value when async success, or false when async failed.
 * @returns {Promise<T>}
 */
export function callbackResult(result, callback) {
    if (typeof callback !== 'function') callback = noop;
    const resolve = (value) => {
        const v = callback(value);
        return v === undefined ? value : v;
    };
    const reject = (err) => {
        error(err);
        const v = callback(false, err);
        return v === undefined ? err : v;
    };

    if (isDeferred(result)) {
        return result.then(resolve).catch((err) => {
            throw reject(err);
        });
    } else if (Error.isError(result)) {
        return Promise.reject(reject(result));
    } else {
        return Promise.resolve(resolve(result));
    }
}
