/** @jsxImportSource @gui/aui-devops */
import { error } from '../../core/base/log.js';
import { widget } from '../../core/extend/widget.js';

import { concat } from '../../util/array/concat.js';
import clearTime from '../../util/date/clear-time.js';
import dateFormat from '../../util/date/format.js';
import { getDateFormat, getFormat, getYearMonthFormat, isHour12 } from '../../util/date/formats.js';
import parseByFormat from '../../util/date/parse-by-format.js';
import eventIsKey from '../../util/event/is-key.js';
import stringFormat from '../../util/string/format.js';
import { isDate, isEmpty } from '../../util/type/types.js';
import { isEqual } from '../../util/value-path.js';

import '../button/button.js';
import '../comboboxshell/comboboxshell.js';
import '../calendar/calendar.js';
import * as calendarUtil from '../calendar/calendarutil.js';
import '../timepicker/timepart.js';
import '../popup/popup.js';

const ComboboxShellArgs = { popupWidth: [0], scrollable: false, resetScroll: false };

(function () {
    const noop = $$.fn();
    const _constant = {
        DATE_PICKER: 'aui-datepicker',
        AUI_WIDGET: 'aui-widget',
        DISABLED: 'disabled',
        POPUP_CLASS: 'aui-datepicker-popup',
        CONTENT_CLASS: 'aui-comboboxshell-content',
        ICON_FONT_CLASS: 'faui-calendar-solid',
        EXTEND_CLASS: 'aui-datepicker-extend',
        ACTION_CLASS: 'aui-datepicker-action',
        ACTION_BORDER_CLASS: 'aui-datepicker-action-border',
        BUTTON_OK_CLASS: 'aui-datepicker-ok',
        TODAY_CLASS: 'aui-datepicker-today',
        ICON_CLASS: 'aui-comboboxshell-icon-box',
        INPUT_CLASS: 'aui-comboboxshell-input',
    };

    widget('aui5.datepicker', {
        calendarId: 'aui_datepicker_calendar_',
        clearId: 'aui_datepicker_clear_',
        timepartId: 'aui_datepicker_time_',
        descId: 'aui_datepicker_desc_',
        tabbtnId: 'aui-datepicker_tabbutton_',
        $popup: null,
        $calendar: null,
        hasOK: false,
        timepart: null,
        _isShow: false,
        optionOrder: ['selectedDate', 'dateTimeFormat', 'displayDate', 'enableDates'],
        options: {
            // Gets or sets a value that represents the format in which the date will be displayed in the Content area after the date is selected.The Settings are only valid when the control is initialized.
            dateTimeFormat: '',
            // Gets or sets a value indicating whether the user can interact with the control.
            disabled: false,
            titleFormat: null,
            placeholder: null,
            parameters: {},
            multiple: false,
            formatText: '',
            firstDayOfWeek: 0,
            selectedDate: null,
            enableDates: {
                start: new Date(1900, 0, 1),
            },
            editable: false,
            width: '100%',
            height: null,
            hasTimePicker: false,
            is24Hour: false,
            clearable: false,
            tooltip: null,
            prefix: '',
            hasToday: true,
            // Gets or sets a method that fires when the selected date changes.
            onChange: noop,
            // Gets or sets a method that fires when the calendar area is opened.
            onShow: noop,
            // Gets or sets a method that fires when the calendar area is closed.
            onHide: noop,
        },
        _create: function () {
            this._initMember()._createShell()._loaded()._initEvent();
        },
        _initMember: function () {
            this.calendarId += this.uuid;
            this.clearId += this.uuid;
            this.timepartId += this.uuid;
            this.tabbtnId += this.uuid;

            this._cloneSelectedDate();

            this.options = {
                ...this.options,
                selectDatesTemplate: $$.I18N.datepicker.selectedXDates,
            };

            this._multi = this.options.multiple === true;
            this._displayMode = Array.isArray(this.options.lockView) ? Math.min(...this.options.lockView) : 0;
            this._hasTimePicker = !this._multi && this._displayMode === 0 && this.options.hasTimePicker;
            this.hasOK = this._multi || this._hasTimePicker;
            this.editable = this.options.editable && !this._multi && !$$.mobileView;
            this.updateFormat();
            this.placeholder = this.editable ? this.format : (this.options.placeholder ?? $$.I18N.datepicker.placeholder);
            return this;
        },
        _isPopMobile: function () {
            return $$.mobileView && $$.browser.touchable;
        },
        updateFormat: function () {
            this.format = this.options.dateTimeFormat || (this._hasTimePicker ? getFormat() : getDateFormat());

            if (this._displayMode !== 0) {
                this.format = this.options.dateTimeFormat || getYearMonthFormat();
            }
            const [dateFormat, timeFormat] = this.format.split(/ (?=h)/i);
            this.dateFormat = dateFormat;
            this.timeFormat = timeFormat;
        },
        _createShell: function () {
            const { aria, disabled, height, width, zIndex, tooltip, clearable } = this.options,
                args = { aria, disabled, width, height, zIndex, editable: this.editable, tooltip };
            let clear = false;
            if (Array.isArray(this._selectedDate) ? this._selectedDate.length > 0 : this._selectedDate) {
                if (clearable === 'force') {
                    clear = true;
                } else if (clearable === true) {
                    let disabledDates = [];
                    disabledDates = this._checkDisabled(this._selectedDate);
                    clear = disabledDates?.filter((item) => item.disabled).length > 0 ? 'disabled' : true;
                }
            }
            const Buttons = this._getButtons();
            this.timepart = this._hasTimePicker && <aui-time-part hour12={isHour12(this.timeFormat)} preciseGap={this.options.minuteGap} />;
            this.$extendArea = <div className={_constant.EXTEND_CLASS} />;
            this.comboboxShell = (
                <aui-combobox-shell
                    part="combobox-shell"
                    {...ComboboxShellArgs}
                    clearable={clear}
                    {...args}
                    placeholder={this.placeholder}
                    popupWidth={['258px']}
                    icon={_constant.ICON_FONT_CLASS}
                    onClear={this._onClear.bind(this)}
                    onInput={this._onInput.bind(this)}
                    onKeyTrigger={this._onInputKeydown.bind(this)}
                    willShow={this._willShow.bind(this)}
                    onShow={this._showPopup.bind(this)}
                    onHide={this._hidePopup.bind(this)}
                >
                    <div className="aui-datepicker-popup">
                        <div className={`aui-datepicker-pop-content ${this._hasTimePicker ? 'has-time-picker' : ''}`}>
                            <section id={this.calendarId} />
                            <div id={this.timepartId} className="aui-timepart">
                                {this.timepart}
                            </div>
                            {this.$extendArea}
                        </div>
                    </div>
                    <span slot="footer"></span>
                    <span slot="buttons"></span>
                </aui-combobox-shell>
            );
            this.element.append(this.comboboxShell);
            this.$element.addClass(_constant.DATE_PICKER + ' ' + _constant.AUI_WIDGET).attr({
                'aria-expanded': false,
                role: 'combobox',
                'aria-haspopup': 'dialog',
            });
            this.$calendar = jQuery('#' + this.calendarId).calendar({
                selectedDate: null,
                enableDates: this.options.enableDates,
                displayDate: null,
                type: this._multi ? 'multiple' : 'single',
                titleFormat: this.options.titleFormat,
                hasToday: true,
                lockView: this.options.lockView,
                displayMode: this._displayMode,
                swipe: true,
                firstDayOfWeek: this.options.firstDayOfWeek,
                onChange: this._onCalendarChange.bind(this),
                doRangeChange: (args) => {
                    return this._callback('doRangeChange', args);
                },
            });

            return this;
        },
        _getButtons: function () {
            this.$element.find('span[slot="footer"]').empty();
            this.$element.find('span[slot="buttons"]').empty();
            const isMobile = this._isPopMobile();
            const { hasToday } = this.options;
            this.$ok = this.hasOK && (
                <aui-button
                    type={isMobile ? 'link' : 'button'}
                    class={_constant.BUTTON_OK_CLASS}
                    name="ok"
                    primary={!isMobile}
                    text={$$.I18N.datepicker.ok}
                    onClick={this._clickOk.bind(this)}
                />
            );
            this.$today = null;
            if (!$$.mobileView && this._displayMode === 0) {
                if (hasToday === 'withTime' && this._hasTimePicker) {
                    this.$today = (
                        <aui-button
                            type="link"
                            attrs={{ style: { color: 'var(--theme-6)' } }}
                            text={$$.I18N.calendar.todayAndTime}
                            onClick={() => {
                                this.$calendar.calendar('gotoToday');
                                this.timepart.setOption('value', new Time());
                                return false;
                            }}
                        />
                    );
                } else if (hasToday === true) {
                    this.$today = (
                        <aui-button
                            type="link"
                            attrs={{ style: { color: 'var(--theme-6)' } }}
                            text={$$.I18N.calendar.today}
                            onClick={() => {
                                this.$calendar.calendar('gotoToday');
                                return false;
                            }}
                        />
                    );
                }
            }
            this.$element.find('span[slot="footer"]').append(this.$today);
            this.$element.find('span[slot="buttons"]').append(this.$ok);
        },

        _loaded: function () {
            this.$content = this.$element.find('.' + _constant.CONTENT_CLASS);
            this.$icon = this.$element.find('.' + _constant.ICON_CLASS);
            this.$calendarToday = this.$calendar.find('.aui-calendar-today');
            this.$content.attr({ 'aria-hidden': true });
            this.$element.attr({ 'aria-roledescription': 'Datepicker' });
            this.$input = this.comboboxShell.shadowRoot.querySelector('input');
            const clz = this._multi ? ' aui-datepicker-multiple' : ' aui-datepicker-single';
            this.$element.addClass(clz);

            this._setOption('selectedDate', this.options.selectedDate);

            return this;
        },
        _initEvent: function () {
            const ns = this.eventNamespace;

            this.$calendar.on('ViewChange' + ns, this._onViewChange.bind(this));
            return this;
        },
        _onInput: function (value) {
            if (this._isShow === false) {
                this._isShow = true;
                this.comboboxShell.setOption('status', { show: this._isShow });
            }
            const date = parseByFormat(value, this.format, true);

            if (isDate(date)) {
                this._showPopup(null, date);
            }
        },
        _onInputKeydown: function (e) {
            if (!e.target || e.target.matches(':disabled')) return;
            const oldData = this._selectedDate,
                date = parseByFormat(e.target.value, this.format, true);

            if (eventIsKey(e, 'Enter')) {
                e.stopPropagation();
                this._isShow = !this._isShow;
                this.comboboxShell.setOption('status', { show: this._isShow });
                if (isDate(date) && !calendarUtil.checkDateDisabled(date.getTime(), this.options.enableDates)) {
                    this._clickOk(null, date, true);
                    return false;
                } else if (this.options.clearable && e.target.value === '') {
                    const newDate = null;
                    this._setOption('selectedDate', newDate);
                    this._onChange(oldData, newDate);
                } else {
                    this.setContent(this._checkDisabled(oldData));
                }
            } else if (eventIsKey(e, 'Escape')) {
                this.setContent(this._checkDisabled(oldData));
            }
        },
        _setOption: function (key, value, oldValue) {
            this.options[key] = value;

            switch (key) {
                case 'disabled':
                    this.comboboxShell.setAttribute('disabled', value);
                    break;
                case 'displayDate':
                    this.$calendar?.calendar('option', 'displayDate', isDate(value) ? new Date(value) : null);
                    break;
                case 'selectedDate':
                    this._setSelectedDate(value);
                    break;
                case 'dateTimeFormat':
                    this.updateFormat();
                    this.setContent();
                    break;
                case 'enableDates':
                    this.$calendar.calendar('option', 'enableDates', value);
                    this._setSelectedDate();
                    break;
                case 'tooltip':
                    this.comboboxShell.setAttribute('tooltip', value);
                    break;
                case 'hasToday':
                    this._getButtons();
                    break;
                default:
                    break;
            }
        },

        _cloneSelectedDate: function () {
            if (this._multi) {
                this._selectedDate = jQuery.extend(true, [], this.options.selectedDate);
            } else {
                this._selectedDate = this.options.selectedDate;
            }
        },
        _onViewChange: function (e, view) {
            this.$extendArea.hidden = view !== 0;
        },
        _onCalendarChange: function (args) {
            const disabled = this._checkCalendarData(args.newValue);
            if (disabled) {
                return;
            }
            if (!this.hasOK && this.$extendArea.innerHTML === '') {
                this._clickOk();
            }
        },

        _hidePopup: function () {
            this._isShow = false;
            this.setContent();
            this.$calendar.calendar('option', 'displayMode', Array.isArray(this.options.lockView) ? Math.min(...this.options.lockView) : 0);
            this.$calendar.calendar('selectedDate', null);
            this.$calendar.calendar('setDisplayDate', null);
            this.$calendar.calendar('resetView');
            if (this._hasTimePicker) {
                this.timepart.setOption('value', new Time(0));
            }
            this.options.onHide(null, {
                element: this.$element,
            });
        },
        _willShow: function () {
            this._getButtons();
            if (this._hasTimePicker) {
                this.timepart.setOption('size', this._isPopMobile() ? 3 : 7);
            }
            if (this._isPopMobile() && this.options.hasToday) {
                this.$calendarToday.show();
            } else {
                this.$calendarToday.hide();
            }
        },
        _showPopup: function (e, data) {
            this._isShow = true;

            data = this._setWidgetData(data);
            if (this._hasTimePicker) {
                this.timepart.setOption('value', Time.fromDate(data || new Date()));
                this.timepart.setOption('mobileView', this._isPopMobile());
            }
            this.comboboxShell.setOption('status', { show: this._isShow });
            window.setTimeout(() => {
                if (this.editable) {
                    this.$input.focus();
                } else {
                    this.$calendar.calendar('setFocus');
                }
            });
            this.options.onShow(null, {
                element: this.$element,
            });
        },
        _onClear: function () {
            let oldDate,
                newDate = this._selectedDateWithDisabled.filter((item) => this.options.clearable === true && item.disabled).map((d) => d.date);
            if (this._multi) {
                oldDate = this._selectedDate.length > 0 ? concat(this._selectedDate) : [];
            } else {
                oldDate = this._selectedDate ? new Date(this._selectedDate) : null;
                newDate = newDate.length > 0 ? newDate[0] : null;
            }
            if (this.editable) {
                this.$input.value = '';
            }
            this.$calendar.calendar('setDisplayDate', new Date());
            this._setOption('selectedDate', newDate);
            this._onChange(oldDate, newDate);
        },
        _setWidgetData: function (data) {
            let d = data || this._selectedDate;
            if (this.$calendar.calendar('selectedDate') !== d) {
                if (this._multi) {
                    d = jQuery.extend(true, [], d);
                } else {
                    if (isDate(d)) d = new Date(d);
                }
            }
            this.$calendar.calendar('option', 'selectedDate', d);
            this.$today?.setOption('disabled', this.$calendar.calendar('allMonthDisabled', new Date()));

            if (isDate(this.options.displayDate)) {
                this.$calendar.calendar('setDisplayDate', new Date(this.options.displayDate));
            } else {
                /**
                 * if: single mode & set enabledDate Range & the date of display Month not in enabledDate Range
                 * then: displayDate = enableDate.start || enableDate.end
                 */
                const { minDate, maxDate } = calendarUtil.calcEnableDate(this.options.enableDates),
                    { year, month, days } = this.$calendar.calendar('getDisplayDate'),
                    _displayDate = {
                        min: clearTime(new Date(year, month, 1)),
                        max: clearTime(new Date(year, month, days)),
                    };

                if (!this._multi && minDate && maxDate && (minDate > _displayDate.max || maxDate < _displayDate.min)) {
                    const date = this.options.enableDates.start || this.options.enableDates.end;
                    this.$calendar.calendar('setDisplayDate', date);
                } else if (!isDate(d)) {
                    this.$calendar.calendar('setDisplayDate', new Date());
                }
            }

            this._checkCalendarData(d); // check ok button disabled
            return d;
        },
        getValue: function () {
            return this.options.selectedDate;
        },
        verify: function () {
            const value = this.getValue();
            return [value];
        },
        setClearable: function () {
            if (this.options.clearable === false) return;
            let clear = false;
            if (Array.isArray(this._selectedDate) ? this._selectedDate.length > 0 : this._selectedDate) {
                if (this.options.clearable === 'force') {
                    clear = true;
                } else if (this.options.clearable === true) {
                    clear = this._selectedDateWithDisabled?.filter((item) => item.disabled).length > 0 ? 'disabled' : true;
                }
            }
            this.comboboxShell.setAttribute('clearable', clear);
        },
        setContent: function (data) {
            let value = '';

            data = data ?? this._selectedDateWithDisabled;

            if (data.length) {
                if (this._multi) {
                    value = stringFormat(this.options.selectDatesTemplate, data.length);
                } else if (Array.isArray(data)) {
                    value = this._formatDateString(data[0]?.date);
                }
            }
            if (this.options.prefix.length > 0) {
                const text = this.options.formatText || $$.I18N.combobox.format;
                value = text.replace('{1}', value);
                value = value.replace('{0}', this.options.prefix);
            }
            if (this.$input.value !== value) {
                this.comboboxShell.setOption('content', value);
                this.$element.triggerHandler('onChange');
                this.setClearable();
            } else if (!this.$input.value) {
                this.setClearable();
            }
        },
        _destroy: function () {
            delete this.comboboxShell;
        },
    });
    // Update Data
    Object.assign(jQuery.aui5.datepicker.prototype, {
        _setSelectedDate: function (date) {
            if (date !== undefined) {
                this._selectedDate = date;
            }
            this._selectedDateWithDisabled = this._checkDisabled(this._selectedDate);
            this.setContent();
        },
        _checkDisabled: function (data) {
            const enableDates = this.options.enableDates;
            let disabled = false;
            if (isEmpty(data)) return [];
            return concat(data).flatMap((d) => {
                if (!isDate(d)) return [];
                const _d = clearTime(d);
                disabled = calendarUtil.checkDateDisabled(_d.getTime(), enableDates);
                return { disabled: disabled, date: d };
            });
        },
        _formatDateString: function (date) {
            if (isDate(date)) {
                return dateFormat(date, this.format);
            } else {
                error('Invalid selectedDate, The selectedDate type must be "Date"');
            }
            return '';
        },
        _checkCalendarData: function (date) {
            let disabled = isEmpty(date);

            if (!disabled) {
                const items = this._checkDisabled(date);
                disabled = !items.some((d) => d.disabled === false);
            }

            this.$ok?.setOption?.('disabled', disabled);

            return disabled;
        },
        _onChange: function (old, date) {
            if (isEqual(old, date)) return false;
            this.options.selectedDate = date;
            this.$element[0].dataset.dirty = true;
            this._handler('onChange', {
                oldValue: old,
                newValue: date,
            });
        },
        _clickOk: function (e, data, notHide) {
            const oldDate = this._selectedDate ? new Date(this._selectedDate) : null;
            let d = data;

            if (!d) {
                d = this.$calendar.calendar('selectedDate');
                if (this._hasTimePicker) {
                    const time = this.timepart.getValue();
                    d = time.toDate(d);
                }
            }
            this._setSelectedDate(d);

            this._onChange(oldDate, d);
            if (!notHide) {
                this._isShow = false;
                this.comboboxShell.setOption('status', { show: this._isShow });
            }
            return true;
        },
    });
})();
