import { _parse } from './_parse.js';
import clamp from './clamp.js';

/** @type {typeof $$.number.loopAt} */
export default function loopAt(min, value, max) {
    min = _parse(min);
    value = _parse(value);
    max = _parse(max);

    const clamped = clamp(min, value, max);
    if (Number.isNaN(clamped)) return Number.NaN;
    if (value === clamped) return value;
    if (min === max) return min;

    const range = max - min + 1;
    let v = value;
    while (v < min || v > max) {
        v = v < min ? range + v : v - range;
    }
    return v;
}
