/** @jsxImportSource @gui/aui-devops */
import { idleLoad } from '../../core/base/onload.js';
import $ from '../../core/element/index.js';
import { addTooltip } from '../../core/module/tooltip.js';
import { define, Widget, Types } from '../../widget/widget.js';

import { keyName } from '../../util/event/key-name.js';
import { keyPressProps } from '../../util/event/key-press.js';
import stopEvent from '../../util/event/stop.js';

import { Overflow } from '../buttonfitbox/overflow.js';

import style from './style.less';
import tabStyle from './tab.less';

const I18N = $$.I18N.tabcontrol;

const Options = {
    type: Types.Enum(['underline', 'rectangle', 'arrow', 'vertical'], 'underline'),
    active: 0,
    maxWidth: Types.Enum([true, false, 'none'], true),
    shrink: true,
    doTabChange: Types.function,
};

@define('tablist-overflow')
class TablistOverflow extends Overflow {
    clearOnHide = false;
}

/** @extends {Widget<typeof Tablist.options>} */
@define('tablist')
export class Tablist extends Widget {
    static options = {
        ...Options,
        align: 'start',
        wrap: false,
        dynamic: false,

        willChange: Types.function,
        onChange: Types.function,
    };
    static observers = ['active'];
    static upcasts = ['type'];
    static downstreamContext = ['overwrite', ['tab'], Object.keys(Options)];
    static styles = style;

    /** @type {Map<number, Element>} */
    #tabList = new Map();
    optionsGetter = {
        active: (v) => this.state.active ?? v,
    };
    init() {
        const { type, active, align, maxWidth, shrink, wrap, dynamic } = this.options,
            isVertical = type === 'vertical';
        this.state = { type, active, align, maxWidth, shrink: shrink && !wrap, wrap, dynamic };
        Object.assign(this.state, {
            arrowList: isVertical ? ['ArrowUp', 'ArrowDown'] : ['ArrowLeft', 'ArrowRight'],
            scrollable: !shrink && !wrap && !isVertical,
        });
    }
    didMount() {
        this.setDynamicStyles(this.getActive(0));
        this.$element.find('.header slot').on('slotchange', (e) => {
            this.setTabList(e.currentTarget.assignedNodes({ flatten: true }));
            const active = this.getActive(0);
            if (active == null) {
                this.setActive(this.getActive(1) ?? this.getActive(-1), true);
            } else {
                this.setActive(active);
            }
        });
    }
    setOption(name, value) {
        if (name === 'active') {
            this.setActive(value);
            return false;
        }
    }

    tabDisabled(tab) {
        return !tab || tab.hasAttribute('hidden') || tab.getAttribute('disabled') === 'true';
    }
    tabFilter(el) {
        return el.closest('aui-tab');
    }
    setTabList(source) {
        this.#tabList.clear();
        $(source).forEach((el) => {
            const tab = this.tabFilter(el);
            if (tab) {
                const index = Number(tab.getAttribute('index'));
                this.#tabList.set(index, tab);
            }
        });
    }

    setDynamicStyles(index) {
        if (this.state.scrollable) {
            this.dynamicStyle(`#popup-slot::slotted([value="${index}"]) { font-weight:inherit; background:inherit; color:inherit!important; }`);
        }
    }
    setActive(active, triggerChange, triggerFocus) {
        const targetTab = this.#tabList.get(active);
        if (targetTab == null) return;
        this.setState({ active }, () => {
            this.setDynamicStyles(active);
            if (triggerFocus) {
                targetTab.focus({ preventScroll: true });
                $$.scrollTo(targetTab);
            }
            if (triggerChange) this.callback('onChange', active);
        });
    }
    changeActive(active) {
        if (active == null) return;
        this.callbackResult(this.callback('willChange', active)).then((result) => {
            if (result !== false) this.setActive(active, true, true);
        });
    }
    getActive(acc) {
        const list = this.#tabList;
        const checkDisabled = (i) => this.tabDisabled(list.get(i));
        let { active } = this.state,
            index;
        if (acc === 0) {
            index = active;
        } else {
            do {
                active += acc;
                if (!checkDisabled(active)) {
                    index = active;
                    break;
                }
            } while (active >= 0 && active < list.size);
        }
        if (index == null || checkDisabled(index)) return null;
        return active;
    }

    tabClick = (e) => {
        const tab = this.tabFilter(e.target);
        if (tab && !this.tabDisabled(tab)) {
            const index = Number(tab.getAttribute('index'));
            if (index !== this.state.active) this.changeActive(index);
        }
    };
    tabKeyDown = (e) => {
        const key = keyName(e);
        if (key === 'Space') return e.preventDefault();

        if (this.state.arrowList.includes(key)) {
            stopEvent(e);
            switch (key) {
                case 'ArrowLeft':
                case 'ArrowUp':
                    return this.changeActive(this.getActive(-1));
                case 'ArrowRight':
                case 'ArrowDown':
                    return this.changeActive(this.getActive(1));
            }
        }
    };
    onPopItemClick = (e) => {
        const button = e.target.closest('button'),
            index = $(button).index('button');
        if (index > -1) this.changeActive(index);
    };
    onAddTab = (e) => {
        const $newTab = $(this.#tabList.values()).filter(':state(editable)').eq(0);
        if ($newTab.length) {
            $newTab.find('#input', { crossShadow: true }).originFn('focus');
        } else {
            this.callbackResult(this.callback('doTabChange', { type: 'createNew' })).then(() => {
                idleLoad(() => this.setActive(this.#tabList.size - 1, false, false));
            });
        }
    };
    render() {
        const { align, scrollable, wrap, dynamic } = this.state,
            HeaderTag = scrollable ? 'aui-tablist-overflow' : 'div';
        return (
            <div className="tablist">
                <HeaderTag className={['overflow-scroll-x', 'header', 'align-' + align, wrap && 'wrap']} role="tablist">
                    <slot onClick={this.tabClick} onKeyDown={this.tabKeyDown} />
                    {dynamic && <aui-button-lite id="add-tab" type="bald" icon="faui-plus" tooltip={I18N.add} onClick={this.onAddTab} />}
                    {scrollable && (
                        <aui-pop slot="popup">
                            <aui-overflow-menu>
                                <slot id="popup-slot" name="popup" onClick={this.onPopItemClick} />
                            </aui-overflow-menu>
                        </aui-pop>
                    )}
                </HeaderTag>
                <div className="body">
                    <slot role="tabpanel" name={this.state.active} />
                </div>
            </div>
        );
    }
}

class DynamicTab extends Widget {
    #resetEditable() {
        this.setState({ editable: false, isEditing: false, textContent: '' });
    }
    #input() {
        return this.shadowRoot.getElementById('input');
    }
    #onKeyPress = (e, keyName) => {
        switch (keyName) {
            case 'Enter':
                return this.#onDynamicOk();
            case 'Escape':
                return this.#onDynamicCancel();
        }
    };
    #onDynamicOk = () => {
        const { isEditing } = this.state,
            value = this.#input().getValue();
        this.#resetEditable();
        this.callback('doTabChange', { type: isEditing ? 'edit' : 'add', index: this.options.index, tab: value });
    };
    #onDynamicCancel = () => {
        this.#resetEditable();
        this.callback('doTabChange', { type: 'cancelNew' });
    };
    #onDynamicEdit = () => {
        const textContent = $(this.shadowRoot.getElementById('content')).textContent();
        this.setState({ editable: true, isEditing: true, textContent }, () => {
            this.#input().focus();
        });
    };
    #onDynamicRemove = () => {
        this.#resetEditable();
        this.callback('doTabChange', { type: 'remove', index: this.options.index });
    };
    renderDynamic() {
        const buttonArgs = { type: 'plain', shrink: 'xs', text: '' };
        return this.state.editable ? (
            <>
                <aui-input-lite id="input" value={this.state.textContent} {...keyPressProps(['Escape', 'Enter'], this.#onKeyPress, { strict: false })} />
                <div id="edit-buttons-true">
                    <aui-button-lite id="ok" {...buttonArgs} icon="faui-ok" tooltip={I18N.ok} onClick={this.#onDynamicOk} />
                    <aui-button-lite id="cancel" {...buttonArgs} icon="faui-close" tooltip={I18N.cancel} onClick={this.#onDynamicCancel} />
                </div>
            </>
        ) : (
            <div id="edit-buttons-false">
                <aui-button-lite id="edit" {...buttonArgs} icon="faui-edit" tooltip={I18N.edit} onClick={this.#onDynamicEdit} />
                <aui-button-lite id="remove" {...buttonArgs} icon="faui-close" tooltip={I18N.close} onClick={this.#onDynamicRemove} />
            </div>
        );
    }
}

/** @extends {Widget<typeof Tab.options>} */
@define('tab')
export class Tab extends DynamicTab {
    static options = {
        ...Options,
        index: -1,
        disabled: Types.boolean,
        dynamic: false,
        editable: false,
    };
    static observers = ['active', 'index', 'disabled', 'dynamic', 'editable'];
    static upcasts = ['type', 'shrink', 'index'];
    static styles = tabStyle;

    init() {
        this.state = {
            editable: this.options.editable,
            isEditing: false,
            textContent: '',
        };
    }
    didMount() {
        addTooltip(this.host);
        const input = this.shadowRoot.getElementById('input');
        if (input) input.focus();
    }
    didRender() {
        this.customState('editable', this.state.editable);
    }
    setOption(name, value) {
        if (name === 'editable') {
            this.setState({ editable: value }, false);
        }
    }
    maxWidth() {
        switch (this.options.maxWidth) {
            case 'none':
                return null;
            case false:
                return 'clamp(min(100%, 496px), 50%, 100%)'; // 992/2=496
            case true: // eslint-disable-line unicorn/no-useless-switch-case
            default:
                return '160px';
        }
    }
    render() {
        const { active, disabled, dynamic, index } = this.options,
            isActive = active === index;
        return (
            <div
                id="tab"
                className={['tab', dynamic && 'dynamic']}
                role="tab"
                data-tooltip="ifneed"
                aria-selected={isActive}
                aria-disabled={disabled}
                tabIndex={isActive ? 0 : -1}
                style={{ '--max-width': this.maxWidth() }}
            >
                <aui-bold id="content" bold={isActive}>
                    <slot />
                </aui-bold>
                {dynamic && this.renderDynamic()}
            </div>
        );
    }
}
