import { error } from '../../core/base/log.js';

const ExtendPlugins = new Map();
const ModulePromises = new Map();
let dependencyLoaded = false;
let pluginLoadPromise = null;
let loaderQueue = Promise.resolve();

const loadMsg = 'Plugins must be added before the Editor is loaded.';

const entry = () => window.AuiEditor;

function findPath(file) {
    const rPath = '/' + file;
    for (const script of document.scripts) {
        const { src } = script;
        if (!src) continue;
        if (src.includes(rPath)) return [script, src];
    }
    return [false, $$.assets.jsPath + rPath];
}

function scriptPromise(script) {
    const { promise, resolve, reject } = Promise.withResolvers();
    script.addEventListener('load', () => queueMicrotask(() => resolve(entry())));
    script.addEventListener('error', reject, { once: true });
    return promise;
}

function scriptLoader(exists, path) {
    if (exists) return entry() ? Promise.resolve(entry()) : scriptPromise(exists);

    const script = document.createElement('script');
    script.src = path;
    const promise = scriptPromise(script);
    document.head.append(script);
    return promise;
}

export function loader(file) {
    const [exists, path] = findPath(file);
    if (ModulePromises.has(path)) return ModulePromises.get(path);

    const loadPromise = loaderQueue
        .then(() => scriptLoader(exists, path))
        .catch((e) => {
            ModulePromises.delete(path);
            throw e;
        });

    ModulePromises.set(path, loadPromise);
    loaderQueue = loadPromise.catch(() => {});

    return loadPromise;
}

export function addPlugin(name, pluginProto) {
    if (dependencyLoaded) throw new Error(loadMsg);
    ExtendPlugins.set(name, pluginProto);
}

export function addInternalPlugin(name, pluginProto) {
    addPlugin('AUI:' + name, pluginProto);
}

export function loadPlugins({ Plugin, Toolbar, Dialog }) {
    if (!pluginLoadPromise) {
        pluginLoadPromise = (async () => {
            if (!dependencyLoaded) {
                dependencyLoaded = true;

                const plugins = [...ExtendPlugins.entries()];
                ExtendPlugins.clear();

                for (const [name, pluginProto] of plugins) {
                    try {
                        const plugin = await pluginProto({ Plugin, Toolbar, Dialog });
                        Plugin.add(name, plugin);
                    } catch (e) {
                        error('Failed to add plugin: ', name, e);
                    }
                }
            } else if (ExtendPlugins.size) {
                const [...list] = ExtendPlugins.keys();
                error(`${loadMsg} The following plugins were not loaded: `, list);
                ExtendPlugins.clear();
            }
        })();
    }
    return pluginLoadPromise;
}
