/** @type {typeof $$.io.base64Encode} */
export function base64Encode(content, contentType) {
    const encoder = new TextEncoder(),
        encoded = encoder.encode(content),
        binaryString = String.fromCodePoint(...encoded),
        data = window.btoa(binaryString);
    if (!contentType) return data;
    const mime = typeof contentType === 'string' ? contentType : 'text/plain';
    return `data:${mime};base64,${data}`;
}

/** @type {typeof $$.io.base64Decode} */
export function base64Decode(content) {
    const splitter = ';base64,';
    if (content.startsWith('data:') && content.includes(splitter)) {
        content = content.split()[1];
    }
    const decoder = new TextDecoder(),
        data = window.atob(content),
        bytes = new Uint8Array([...data].map((c) => c.codePointAt(0)));
    return decoder.decode(bytes);
}
