import kebabCase from '../string/kebab-case.js';

/** @type {typeof $$.css.classRule} */
export default function classRule(name, rule, pseudo) {
    const el = document.createElement('div');
    el.className = name;
    $$.tempInsert(el);
    const styles = getComputedStyle(el, pseudo),
        t = typeof rule;
    const getter = (r) => styles.getPropertyValue(kebabCase(r));
    if (t === 'string') return getter(rule);

    const rules = rule;
    if (Array.isArray(rules)) return rules.map(getter);
    if (t === 'object') {
        for (const r of Object.keys(rules)) {
            rules[r] = getter(r);
        }
        return rules;
    }
    return null;
}
