/* global ABCJS,CKEDITOR */
import { addTooltip } from '../../../core/module/tooltip.js';
import { define, Widget, Types } from '../../../widget/widget.js';

import { keyName } from '../../../util/event/key-name.js';
import stopEvent from '../../../util/event/stop.js';
import numberInt from '../../../util/number/int.js';

import { confirm } from '../../messagedialog/messagedialog.js';
import '../../popup/pop.js';
import '../../tabbutton/tabbutton.js';
import '../../togglebutton/togglebutton.js';

import * as util from './music.base.js';
import './music.widget.js';

import togglebuttonStyle from '../../togglebutton/togglebutton.less';
import style from './style.less';

const I18N = $$.I18N.music;
const icons = ['faui-arrow-up-bold', 'faui-arrow-down-bold', 'faui-info-solid', 'faui-angle-down-s'];
const defaults = {
    title: I18N.defaultTitle,
    metre: '4/4',
    note: 'G', // base note for C-key
    rhythm: 'reel', /// undo
    key: 'C',
    keyMajor: 'C',
    keyMinor: 'A min',
    tempoBase: '1/4',
    bpm: 80,
};
const defaultHeaders = new Map([
    ['T', I18N.defaultTitle],
    ['M', '4/4'],
    ['K', 'C'],
    ['V', 'V1 clef=treble'],
    ['Q', null],
]);
const dottedButtons = [
    { checked: false, value: '.', icon: 'DotSingle', tooltip: I18N.dottedNote },
    { checked: false, value: '..', icon: 'DotDouble', tooltip: I18N.doubleDottedNote },
];

/** @extends {Widget<typeof Music.options>} */
@define('music')
export class Music extends Widget {
    static options = {
        showWarning: false,
        midiDownload: false,
        updateButtonStatus: Types.function,
        soundFontUrl: Types.string,
    };
    static observers = ['showWarning', 'midiDownload'];
    static shadow = true;
    static styles = [style, { togglebutton: togglebuttonStyle }];
    method = {
        hide: this.hide,
        setValue: this.setValue,
        getValue: this.getValue,
        initData: this.initData,
    };

    #inputModes = [I18N.insertMode, I18N.replaceMode];
    #keyModes = [I18N.keyMajor, I18N.keyMinor];
    #clefModes = [I18N.singleStave, I18N.greatStave];
    #tempoModes = [I18N.computedTempo, I18N.specificTempo];
    base = '[V:V1][|]';
    splitter = '`\n';
    ghostBar = '[|]';
    init() {
        this.state = {
            deleteLine: false,
            inputMode: 0,
            keyMode: 0,
            tempoMode: 0,
            clefMode: 0,
            showGlobalPopup: false,
            checkedClefs: ['treble'],
            major: defaults.keyMajor,
            minor: defaults.keyMinor,
            tempoCount: defaults.bpm,
            checkedTempo: defaults.tempoBase,
        };
        this.cache = {
            selectionType: null,
            beamNoteChecked: true,
            dottedNote: 0,
            selectedString: '',
            selection: [this.base, ''],
            metreNumber: defaults.metre.split('/', 1)[0],
            denominator: defaults.metre.split('/', 2)[1],
        };
        for (const name of icons) {
            this.fontIcon(name);
        }
    }
    didMount() {
        addTooltip(this.host);
    }
    hide() {
        for (const [k, v] of defaultHeaders) {
            this.restore(k, v, true);
        }
        this.refs.staveRegion.method('setValue', { val: true, body: this.base });
        this.cache.selection = [this.base, ''];
        this.setNoSelection();
        this.setMode(0);
    }
    restore(k, v, render) {
        const cache = this.cache;
        switch (k) {
            case 'T':
                this.state.title = v === defaults.title ? '' : v;
                break;
            case 'M': {
                const metre = v.split('/');
                cache.metreNumber = metre[0];
                cache.denominator = metre[1];
                break;
            }
            case 'K': {
                const isMajor = v.slice(-3) !== 'min';
                this.state.keyMode = isMajor ? 0 : 1;
                this.state.major = isMajor ? v : defaults.keyMajor;
                this.state.minor = isMajor ? defaults.keyMinor : v;
                break;
            }
            case 'V': {
                if (typeof v === 'string') v = [v];
                const value = v.map((c) => c.match(/V[1-9]\sclef=(\w+)/)?.[1] ?? c);
                const isGrand = value.length > 1 ? 1 : 0;
                this.state.checkedClefs = value.slice();
                if (this.state.clefMode !== isGrand) {
                    this.toggleGrand(isGrand);
                }
                this.state.clefMode = isGrand;
                break;
            }
            case 'Q': {
                const val = v == null ? [defaults.tempoBase, defaults.bpm] : v.split('=');
                this.state.tempoMode = v == null ? 0 : 1;
                this.state.checkedTempo = val[0];
                this.state.tempoCount = val[1];
                break;
            }
        }
        this.setState();
        if (render) this.refs.staveRegion.method('setEditorValue', { k: k, v: v });
    }
    setValue(val) {
        const voice = [];
        let note = val || '';
        if (typeof note === 'string') {
            note = note.replaceAll(';', '\n');
            note = note.split(this.splitter);
            for (const item of note[0].split('\n')) {
                const arr = item.split(':');
                if (arr[0] === 'V') {
                    voice.push(arr[1]);
                } else {
                    this.restore(...arr);
                }
            }
            this.restore('V', voice);
            this.refs.staveRegion.method('setValue', { val: note[0], body: note[1] });
            this.cache.selection[0] = note[1];
        }
    }
    getValue() {
        return { svg: this.refs.staveRegion.method('getValue', this.state.title), value: this.refs.staveRegion.method('getTextAreaValue') };
    }
    updateClef() {
        const clefs = this.state.checkedClefs,
            voices = [],
            val = this.refs.staveRegion.method('getTextAreaValue');
        let [header, body] = val.split(this.splitter);
        clefs.forEach(function (clef, index) {
            voices.push('V:V' + (index + 1) + ' clef=' + clef + '\n');
        });
        header = header.replaceAll(/V:[^\]\n]+\n/g, '') + voices.join('');
        this.refs.staveRegion.method('setValue', { val: header, body: body });
    }

    onSelectionChange = (args) => {
        const cache = this.cache,
            { type, elemType, headerLength, range, value } = args,
            selection = value.slice(...range);
        let obj = this.parse(selection),
            deleteLine = false;
        if (cache.waitingEnd) {
            const symbol = cache.waitingEnd.getAttribute('data-symbol').split(',');
            if (symbol.length === 2) {
                cache.selectedString = selection;
                cache.selection = [util.trim(value.slice(0, range[0])) + (cache.beamNoteChecked ? '' : ' '), util.trim(value.slice(range[1]))];
                obj = this.modify(obj, { SlurRight: symbol[1] });
                this.insertVal(this.stringify(obj));
                cache.waitingEnd.checked = false;
                cache.waitingEnd = false;
            }
        } else {
            if (selection && (type === 'note' || type === 'bar')) {
                if (obj['SlurLeft']) deleteLine = true;
                cache.selectedString = selection;
                cache.selection = [util.trim(value.slice(0, range[0])) + (cache.beamNoteChecked ? '' : ' '), util.trim(value.slice(range[1]))];
                this.setMode(1);
            } else {
                if (cache.selectedString) {
                    this.setRange(headerLength + 1);
                } else {
                    this.setNoSelection();
                }
            }
        }
        this.setState({ deleteLine: deleteLine, checkLine: false });
        cache.selectionType = type;
        cache.selectedElemType = elemType;
    };
    setNoSelection() {
        this.cache.selectionType = null;
        this.cache.selectedString = '';
    }
    #waitingCache() {
        const { cache } = this;
        if (cache.waitingEnd) {
            cache.waitingEnd.checked = false;
            cache.waitingEnd = false;
        }
        return cache;
    }
    onNotationClick = (e, symbol) => {
        const el = e.currentTarget,
            name = el.getAttribute('data-name'),
            cache = this.#waitingCache();
        this.state.checkLine = false;
        switch (name) {
            case 'rest':
            case 'note': {
                if (this.state.inputMode === 1 && cache.selectionType !== 'note') return;
                cache.selectedElemType = name;
                const obj = {
                    Note: name === 'rest' ? 'z' : defaults.note,
                    NoteLength: this.calcLength(el.getAttribute('data-denominator')),
                };
                this.insertVal(this.stringify(obj));
                break;
            }
            case 'pitch':
                this.changePitch(Number(el.getAttribute('data-val')));
                break;
            case 'symbol':
                cache.selectedElemType = name;
                this.symbolClick(e, el);
                break;
            case 'text':
                this.textClick(el.getAttribute('data-symbol'));
                break;
            case 'action': {
                const action = el.getAttribute('data-id'),
                    param = action === 'beam' ? el.getAttribute('data-attr') : '1';
                try {
                    this[action](param);
                } catch (e) {
                    this.console.error('No method in Music notation with name:' + action);
                }
                break;
            }
        }
        this.setState();
    };
    onNotationPopClick = ({ note, symbol, denominator }) => {
        const cache = this.#waitingCache();
        if (this.state.inputMode === 1 && cache.selectionType !== 'note') return;
        if (symbol) {
            // grace note
            const obj = this.grace(symbol, note);
            this.insertVal(this.stringify(obj), true);
        } else {
            this.updateGrandSelection(note, note.includes(',') ? 2 : 1);
            const obj = {
                Note: note, // include Note&&Octave
                NoteLength: this.calcLength(denominator),
            };
            this.insertVal(this.stringify(obj));
        }
    };
    textClick(symbol) {
        let obj;
        if (symbol) {
            const text = window.prompt(I18N.textInputMessage, I18N.text); // eslint-disable-line no-alert
            if (text) {
                const cur = this.parse(this.cache.selectedString);
                symbol = '"' + symbol + text + '"';
                if (cur.Text === symbol) return;
                obj = this.modify(cur, { Text: symbol });
                this.insertVal(this.stringify(obj), true);
            }
        } else {
            // no text;
            obj = this.modify(this.parse(this.cache.selectedString), { Text: '' });
            this.insertVal(this.stringify(obj), true);
        }
    }
    calcLength(denominator) {
        const length = Number(denominator),
            baseLength = '4',
            dottedNote = this.cache.dottedNote,
            div = Math.max(length, baseLength) / Math.min(length, baseLength),
            result = length > baseLength ? [1, div] : [div, 1];
        if (dottedNote > 0) {
            const dotted = util.dotted[dottedNote].split('/');
            result[0] = result[0] * dotted[0];
            result[1] = result[1] * dotted[1];
        }
        if (result.join('/') === '1/1') {
            return '';
        } else if (result[0] === 1) {
            return '/' + result[1];
        } else if (result[1] === 1) {
            return String(result[0]);
        }
        return result.join('/');
    }
    stringify(obj) {
        if (!obj) return;
        const arr = [];
        for (const item of util.order) {
            if (obj[item]) arr.push(obj[item]);
        }
        let result = arr.join('');
        if (!this.cache.beamNoteChecked) result = [' ', ' '].join(result);
        return result;
    }
    insertVal(str, forceModify) {
        if (!str) return;
        const cache = this.cache,
            headLength = this.getHeaderLength();
        let range;
        if (this.state.inputMode === 0 && cache.selectedString) {
            if (!forceModify) cache.selection[0] += cache.selectedString;
            cache.selectedString = str;
            range = [cache.selection[0].length + headLength + str.length, cache.selection[0].length + headLength + str.length];
        } else {
            cache.selectedString = str;
            range = [cache.selection[0].length + headLength + 1, cache.selection[0].length + str.length + headLength];
        }
        this.refs.staveRegion.method('updateVirtualEditor', cache.selection.join(str));
        this.setRange(range);
    }
    setRange(args, delay) {
        // args options:array,undefined,number
        let range;
        if (Array.isArray(args)) {
            range = args;
        } else {
            let point = this.getHeaderLength();
            point += this.cache.selection[0].length + (args ?? this.cache.selectedString.length);
            range = [point, point + 1];
        }
        this.refs.staveRegion.method('setRange', { range: range, delay: delay });
    }
    getHeaderLength() {
        const value = this.refs.staveRegion.method('getTextAreaValue');
        return value.split(this.splitter)[0].length + this.splitter.length;
    }
    setMode(val) {
        this.setState({ inputMode: val });
    }
    changePitch(num) {
        if (this.cache.selectedString) {
            const obj = this.calcPitch(this.cache.selectedString, num);
            this.insertVal(this.stringify(obj), true);
        }
    }
    calcPitch(str, modify) {
        const obj = this.parse(str);
        let note = obj['Note'] || '',
            level = obj['Octave'] || 0, // [A-Z] as 0;
            index = util.notes.indexOf(note.toUpperCase()) + modify;
        if (!note) return;
        if (level) level = level.length * (level[0] === util.pitchHigh ? 1 : -1);
        if (/[a-z]/.test(note)) level++;
        if (index < 0) {
            index += util.notes.length;
            note = util.notes[index];
            level--;
        } else if (index >= util.notes.length) {
            index -= util.notes.length;
            level++;
        }
        let char = util.notes[index],
            pitch = '';
        if (level > 0) {
            char = char.toLowerCase();
            if (level > 1) pitch = Array.from({ length: level }).join(util.pitchHigh);
        } else {
            char = char.toUpperCase();
            pitch = Array.from({ length: 1 - level }).join(util.pitchLow);
        }
        obj['Note'] = char;
        obj['Octave'] = pitch;
        return obj;
    }
    symbolClick(e, element) {
        const cache = this.cache,
            name = element.getAttribute('data-id'),
            groupName = element.getAttribute('data-group');
        let obj = {},
            symbol = element.getAttribute('data-symbol').split(',');
        if (this.state.inputMode === 1 && cache.selectionType && (groupName === 'BarLine' ? cache.selectionType !== 'bar' : cache.selectionType !== 'note')) return;
        if (symbol.length === 1) {
            symbol = symbol[0];
            if (util.order.includes(groupName)) {
                if (groupName === 'Grace') {
                    obj = this.grace(symbol);
                } else {
                    obj[groupName] = symbol;
                    obj = this.modify(this.parse(cache.selectedString), obj);
                }
                this.insertVal(this.stringify(obj), true);
            } else {
                this.insertVal(symbol);
            }
        } else if (symbol.length === 2) {
            // region modify, for ["Line"]
            if (this.state.inputMode === 0) {
                e.stopPropagation(); // input mode, do nothing, revert checked to false;
                element.checked = false;
            } else if (this.state.deleteLine) {
                e.stopPropagation();
                cache.selection[1] = cache.selection[1].replace(util.structure.SlurRight.reg, '');
                obj = this.modify(this.parse(cache.selectedString), { SlurLeft: '' });
                this.insertVal(this.stringify(obj));
                cache.waitingEnd = false;
                element.checked = false;
                this.setState({ deleteLine: false });
            } else {
                if (name === 'slurLine') {
                    this.state.checkLine = true;
                    obj = this.modify(this.parse(cache.selectedString), { SlurLeft: symbol[0] });
                    this.insertVal(this.stringify(obj));
                }
                cache.waitingEnd = element;
            }
        }
    }
    space() {
        const cache = this.cache,
            current = this.parse(cache.selectedString);
        let symbol = 'y';
        if (cache.selectedElemType === 'note') {
            symbol += current.NoteLength || '';
            cache.selection[0] += symbol;
            this.refs.staveRegion.method('setValue', { val: true, body: cache.selection.join(cache.selectedString) });
            this.setRange(symbol.length - 1, 300);
        }
    }
    enter() {
        const cache = this.cache;
        let body;
        if (this.state.clefMode) {
            this.grandEnter();
        } else {
            cache.selection[0] += cache.selectedString + '\n';
            body = cache.selection.join(this.ghostBar);
            cache.selectedString = this.ghostBar;
            cache.selectionType = null;
            this.refs.staveRegion.method('setValue', { val: true, body: body });
            this.setRange(this.ghostBar.length, 300);
        }
        this.setMode(0);
    }
    grandEnter() {
        const cache = this.cache,
            reg = /\[V:V\d\]/,
            before = cache.selection[0],
            after = cache.selection[1],
            current = Number(before.match(new RegExp(reg, 'g')).pop().match(/\d/)[0]);
        const start = before.lastIndexOf('[V:V1]'),
            end = after.indexOf('[V:V1]');
        let str = [before.slice(start), after.slice(0, end > -1 ? end : undefined)],
            count = str[0].match(new RegExp(util.barLineReg, 'g')).length + 1;
        if (current === 2) {
            const { index } = str[0].match(/\n\[V:V\d\]/) || {};
            count = str[0].slice(Math.max(0, index || 0)).match(new RegExp(util.barLineReg, 'g')).length + 1;
        }
        str = str.join(cache.selectedString).split('\n');
        const reg1 = new RegExp(util.barLineReg, 'g'),
            reg2 = new RegExp(util.barLineReg, 'g');
        for (let i = 0; i < count; i++) {
            reg1.exec(str[0]);
            reg2.exec(str[1]);
        }
        const stave = [
            '[V:V1]' + this.ghostBar + (reg1.lastIndex > 0 ? str[0].slice(reg1.lastIndex) : ''),
            '[V:V2]' + this.ghostBar + (reg2.lastIndex > 0 ? str[1].slice(reg2.lastIndex) : ''),
        ];
        cache.selection[0] = [before.slice(0, start) + str[0], str[1], stave[0]].join('\n');
        cache.selection[1] = '\n' + stave[1];
        if (end > -1) cache.selection[1] += '\n' + after.slice(end);
        cache.selectedString = '';
        this.refs.staveRegion.method('setValue', { val: true, body: cache.selection.join('') });
        this.setRange(0);
        this.setMode(0);
    }
    updateGrandSelection(str, voice, force) {
        // force: ignore inputMode;
        const cache = this.cache;
        if (!(this.state.clefMode === 1 && (this.state.inputMode === 0 || force))) return;
        const reg = /\[V:V\d\]/,
            before = cache.selection[0],
            after = cache.selection[1],
            current = Number(before.match(new RegExp(reg, 'g')).pop().match(/\d/)[0]),
            flag = '\n[V:V' + current + ']',
            isNext = current < voice,
            index = isNext ? after.indexOf(flag) : before.lastIndexOf(flag),
            isEndOfLine = after === '' || after.indexOf('\n') === 0 || (after.match(reg) && after.match(reg).index === 0);
        if (isEndOfLine && current !== voice) {
            if (isNext) {
                if (index > -1) {
                    cache.selection = [before + cache.selectedString + after.slice(0, index), after.slice(index)];
                } else {
                    cache.selection = [util.trim(cache.selection.join(cache.selectedString)), after.at(-1) === '\n' ? '\n' : ''];
                }
            } else {
                if (index > -1) {
                    cache.selection = [before.slice(0, index), before.slice(index) + cache.selectedString + after];
                } else {
                    this.console.warn('Nothing before?????'); ///
                }
            }
            cache.selectedString = '';
        }
    }
    delete(operate, isNext) {
        const cache = this.cache;
        if (this.deleteString(operate, isNext) === true) return;
        const val = cache.selection.join('');
        this.refs.staveRegion.method('highlightNearby', {
            operate: operate,
            selection: val,
            callback: (args) => {
                this.setMode(args.mode);
                if (args.mode === 0) this.setNoSelection();
            },
        });
    }
    deleteString(operate, isNext) {
        const cache = this.cache,
            current = cache.selectedString,
            spaceSelection = operate > 0 ? cache.selection[1] : cache.selection[0],
            enterSelection = operate > 0 ? (cache.selection[1] ? cache.selection[1] : cache.selection[0]) : cache.selection[0],
            spaceReg = operate > 0 ? /^(y\/?\d*\s*)/ : /(y\/?\d*\s*)$/,
            enterReg = /(\n(\[V:V\d\])?)(\n(\[V:V\d\])?)*$/; // operate > 0 ? (!cache.selection[1] ? /(\n(\[V:V\d\])?)(\n(\[V:V\d\])?)*$/ : /^(\n(\[V:V\d\])?)(\n(\[V:V\d\])?)/) :
        if (isNext) {
            /// support in future
        } else {
            if (spaceReg.test(spaceSelection)) {
                cache.selection[operate > 0 ? 1 : 0] = spaceSelection.replace(spaceReg, '');
                cache.selectedString = '';
                this.insertVal(current);
                return true;
            }
            if (enterReg.test(enterSelection)) {
                if (this.state.clefMode) {
                    ///
                } else {
                    cache.selection[operate > 0 ? (cache.selection[1] ? 1 : 0) : 0] = enterSelection.replace(enterReg, '');
                    cache.selectedString = '';
                    this.refs.staveRegion.method('setValue', { val: true, body: cache.selection.join('') });
                    setTimeout(() => {
                        this.highlightLast();
                    }, 300);
                    return true;
                }
            }
        }
    }
    beam(type) {
        const cache = this.cache,
            before = cache.selection[0],
            after = cache.selection[1],
            current = cache.selectedString || '';
        if (cache.selectionType !== 'note' || current.includes('z')) return;
        // Boolean, true->space, false->no-space;
        const left = type === 'start' || type === 'none',
            right = type === 'end' || type === 'none',
            reg = /^\s+/,
            regEnd = /\s+$/;
        if (left) {
            if (!(regEnd.test(before) || reg.test(current))) {
                cache.selection[0] += ' ';
            }
        } else {
            if (regEnd.test(before)) cache.selection[0] = before.replace(regEnd, '');
            if (reg.test(current)) cache.selectedString = current.replace(reg, '');
        }
        if (right) {
            if (!(regEnd.test(current) || reg.test(after))) {
                cache.selection[1] = ' ' + after;
            }
        } else {
            if (regEnd.test(current)) cache.selectedString = current.replace(regEnd, '');
            if (reg.test(after)) cache.selection[1] = after.replace(reg, '');
        }
        this.refs.staveRegion.method('updateVirtualEditor', cache.selection.join(cache.selectedString));
        this.setRange();
    }
    grace(symbol, val) {
        const obj = { Grace: '' },
            cur = this.parse(this.cache.selectedString),
            note = val || cur.Note || defaults.note;
        const grace = symbol.replace('$0', note);
        if ((val && cur.Grace === grace) || this.cache.selectedElemType === 'rest') return;
        if (val || !cur.Grace || cur.Grace.replace(/[a-g]/i, '$0') !== symbol) obj['Grace'] = grace;
        // this.cache.selectedElemType = null;
        return this.modify(cur, obj);
    }
    parse(str) {
        const obj = {};
        if (!str) return obj;
        for (const item of util.order) {
            const group = util.structure[item],
                reg = group.reg;
            let result = str.match(reg);
            if (!reg || !result || (result.length === 1 && !result[0])) {
                result = false;
                continue;
            }
            if (group.mutex) {
                if (result.length > 1) result = result.filter(Boolean);
                if (item === 'Note') result = result.pop().match(/[a-g]/i);
            } else {
                result = result.filter(function (i, index) {
                    return result.indexOf(i) === index;
                });
                result = [result.join('')];
            }
            if (result) {
                result = item === 'NoteLength' ? result.join('') : result[0];
                obj[item] = result;
            }
        }
        return obj;
    }
    modify(source, modify) {
        const obj = { ...source, ...modify };
        for (const x in obj) {
            if (typeof source[x] === 'string') {
                if (modify[x] && source[x].includes(modify[x])) {
                    // if exists, delete and toggle to none;
                    obj[x] = source[x].replace(modify[x], '');
                } else if (!util.structure[x].mutex) {
                    obj[x] = (source[x] || '') + (modify[x] || '') || undefined;
                }
            }
        }
        return obj;
    }
    staveKeydown = (e) => {
        const name = keyName(e, true),
            stop = stopEvent;
        switch (name) {
            case 'Space':
                this.space();
                return stop(e);
            case 'Enter':
                this.enter();
                return stop(e);
            case 'Backspace':
                this.delete(-1);
                return stop(e);
            case 'Delete':
                this.delete(1); /// true
                return stop(e);
            case 'ArrowLeft':
                this.move(-1);
                return stop(e);
            case 'ArrowRight':
                this.move(1);
                return stop(e);
            case 'ArrowUp':
                this.changePitch(e.ctrlKey ? 7 : 1);
                return stop(e);
            case 'ArrowDown':
                this.changePitch(e.ctrlKey ? -7 : -1);
                return stop(e);
        }
    };
    move(operate) {
        this.refs.staveRegion.method('highlightNearby', {
            direction: operate,
        });
    }
    highlightLast() {
        this.refs.staveRegion.method('highlightNearby', {
            toLast: true,
        });
    }
    onBeamNoteChange = (bool) => {
        this.cache.beamNoteChecked = bool;
    };
    onDottedChange = (checked, value) => {
        this.cache.dottedNote = checked === false ? 0 : value === '.' ? 1 : 2;
    };
    onModeChange = (index) => {
        this.setState({ inputMode: numberInt(index) });
        if (this.state.inputMode === 1) this.highlightLast();
    };

    onKeyModeChange = (index) => {
        this.setState({ keyMode: numberInt(index) });
        this.refs.staveRegion.method('setEditorValue', { k: 'K', v: this.state.keyMode === 0 ? this.state['major'] : this.state['minor'] });
    };
    onTempoModeChange = (index) => {
        const i = numberInt(index);
        this.setState({ tempoMode: i });
        this.refs.staveRegion.method('setEditorValue', { k: 'Q', v: i === 0 ? '' : this.state.checkedTempo + '=' + this.state.tempoCount });
    };
    onClefModeChange = (index) => {
        this.setState({ clefMode: numberInt(index), checkedClefs: [] });
        this.refs.globalSetting.setOptions({ offClose: true });
        confirm({
            classify: 'warn',
            content: I18N.grandToggleMessage,
            onClose: (bool) => {
                let i = numberInt(index);
                if (bool) {
                    this.toggleGrand(!!index);
                } else {
                    i = Math.abs(index - 1);
                }
                this.setState({ clefMode: i, checkedClefs: i ? util.grandClefs : [util.clefs[0].toLowerCase()] });
                this.refs.globalSetting.setOptions({ offClose: false });
            },
        });
    };
    toggleGrand(grand) {
        const cache = this.cache,
            selection = this.state.clefMode ? [this.base, '\n' + this.base.replace(/\d/, '2')] : [this.base, ''],
            value = this.refs.staveRegion.method('getTextAreaValue');
        let [header] = value.split(this.splitter);
        if (grand) {
            header = ['%%staves {V1 V2}\n', header.replace(/V:V1 clef=\w+\n/, 'V:V1 clef=treble\n'), 'V:V2 clef=bass\n'].join('');
        } else {
            header = header.replaceAll(/V:V\d clef=\w+\n/g, 'V:V1 clef=treble\n').replace('%%staves {V1 V2}\n', '');
        }
        cache.selectedString = '';
        cache.selection = selection.slice();
        if (this.state.inputMode === 1) this.setMode(0);
        this.refs.staveRegion.method('setValue', { val: header, body: selection.join('') });
    }
    onFormChange = (value, e) => {
        this.onFieldChange(e);
    };
    onFieldChange = (e, value, group) => {
        const name = e.currentTarget ? e.currentTarget.getAttribute('name') : group,
            val = e.currentTarget ? e.currentTarget.value : value;
        let k = '',
            v = val;
        switch (name) {
            case 'title':
                k = 'T';
                this.state.title = val;
                break;
            case 'key':
                k = 'K';
                this.setState({ [this.state.keyMode === 0 ? 'major' : 'minor']: val });
                break;
            case 'metreNumerator':
                this.cache.metreNumber = val;
                k = 'M';
                v = val + '/' + this.cache.denominator;
                break;
            case 'metreDenominator':
                this.cache.denominator = val;
                k = 'M';
                v = this.cache.metreNumber + '/' + val;
                break;
            case 'clef':
                if (this.state.clefMode === 1) return;
                this.setState({ checkedClefs: [val] });
                this.updateClef();
                break;
            case 'tempo':
                k = 'Q';
                v = val + '=' + this.state.tempoCount;
                this.setState({ checkedTempo: val });
                break;
            case 'bpm':
                k = 'Q';
                v = this.state.tempoMode === 0 ? false : this.state.checkedTempo + '=' + val;
                this.setState({ tempoCount: val });
                break;
        }
        if (k) this.refs.staveRegion.method('setEditorValue', { k: k, v: v });
    };
    onToggleClick = () => {
        this.state.showGlobalPopup = !this.state.showGlobalPopup;
        const dialog = CKEDITOR.dialog?.getCurrent();
        setTimeout(() => {
            if (dialog) {
                dialog._.buttons.ok[this.state.showGlobalPopup ? 'disable' : 'enable']();
            } else {
                $$.fn(this.options.updateButtonStatus)(this.state.showGlobalPopup);
            }
        });
    };
    groupToggle = (e) => {
        const name = e.target.getAttribute('data-name');
        this.cache[name + 'OpenState'] = e.target.hasAttribute('open');
    };

    preventWheel = (e) => {
        e.preventDefault();
        e.stopPropagation();
    };

    renderFieldGroup(name, isOpen, children) {
        const attr = { className: 'notation-group', 'data-name': name };
        if (this.cache[name + 'OpenState'] || isOpen) attr['open'] = true;
        return (
            <details onToggle={this.groupToggle} {...attr}>
                <summary>{I18N[name]}</summary>
                <section>{children}</section>
            </details>
        );
    }
    getButtons() {
        return (
            <>
                <aui-togglebutton value={I18N.beamNote} onClick={this.onBeamNoteChange} checked={true}>
                    <span className="button-beam-note">{I18N.beamNote}</span>
                </aui-togglebutton>
                <div>
                    {dottedButtons.map((item, index) => {
                        return (
                            <aui-togglebutton group="dotted" tooltip={item.tooltip} value={item.value} onClick={this.onDottedChange}>
                                {ABCJS.parseIcon(item.icon)}
                            </aui-togglebutton>
                        );
                    })}
                </div>
            </>
        );
    }

    getNoteChild() {
        return (
            <>
                <div className="note-header">
                    <aui-tabbutton name="inputMode" tooltip={I18N.modeTitle} items={this.#inputModes} active={this.state.inputMode} onChange={this.onModeChange} />
                    {$$.mobileView ? this.getButtons() : <div className="note-buttons">{this.getButtons()}</div>}
                </div>
                <div className="notes">{this.renderSymbolList('note', util.NoteList)}</div>
            </>
        );
    }
    renderBtn(obj, type, display, style, symbol, content) {
        return (
            <button type="button" {...obj} onClick={this.onNotationClick}>
                {display && ABCJS.parseIcon(display)}
                {content && <div className="content">{content}</div>}
                {obj['data-id'] === 'slurLine' && this.state.deleteLine && ABCJS.parseIcon('Delete')}
            </button>
        );
    }
    renderSymbolList(type, array) {
        return array.map((item) => {
            const { name, attr, group, attrs, symbol, className, val, display, style, content } = item;
            let title = name;
            if (attr) title += '_' + attr;
            const tooltip = I18N[title] || title || '';
            const symbolLength = symbol ? symbol.split(',').length : 0;

            const classList = [];
            classList.push('button');
            if ((type === 'symbol' || type === 'action') && symbolLength <= 1) classList.push('icon ');
            if (group === 'Note' || group === 'Grace') classList.push('pop-icon ');
            if (className) classList.push(className);

            let obj = {
                class: classList,
                'data-name': type,
                'data-id': name,
            };
            if (this.state.deleteLine || this.state.checkLine) obj['data-checked'] = true;
            if (group) obj['data-group'] = group;
            if (symbol) obj['data-symbol'] = symbol;
            if (val) {
                obj['data-val'] = val;
                obj['data-positive'] = val > 0;
            }

            if (attr) obj['data-attr'] = attr;
            if (item.denominator) obj['data-denominator'] = item.denominator;
            if (type === 'text') obj['data-text'] = I18N.text;
            if (tooltip) {
                if (group && (group === 'Grace' || group === 'Note')) {
                    obj['aria-label'] = tooltip;
                } else {
                    Object.assign(obj, { 'data-tooltip': true, 'aria-label': tooltip });
                }
            }
            obj = Object.assign(obj, attrs, this.options.attrs);

            return this.renderBtn(obj, type, display, style, symbol, content);
        });
    }
    render() {
        return (
            <div className={`aui-music ${$$.mobileView ? 'mobile' : ''}`}>
                <div className="notation">
                    {this.renderFieldGroup('notes', true, this.getNoteChild())}
                    {this.renderFieldGroup('rests', true, <div className="rests">{this.renderSymbolList('rest', util.RestList)}</div>)}
                    {this.renderFieldGroup('barlines', true, <div className="barlines">{this.renderSymbolList('symbol', util.BarLineList)}</div>)}
                    {this.renderFieldGroup('actions', false, <div className="actions">{this.renderSymbolList('action', util.ActionList)}</div>)}
                    {this.renderFieldGroup('pitches', false, <div className="pitches">{this.renderSymbolList('pitch', util.PitchList)}</div>)}
                    {this.renderFieldGroup('grace', false, this.renderSymbolList('symbol', util.GraceList))}
                    {this.renderFieldGroup(
                        'lines',
                        false,
                        <>
                            <div className="message">
                                <span className="faui-info-solid"></span>
                                <span>{I18N.intervalMessage}</span>
                            </div>
                            <div className="lines">{this.renderSymbolList('symbol', util.LineList)}</div>
                        </>
                    )}
                    {this.renderFieldGroup('ornaments', false, <div>{this.renderSymbolList('symbol', util.OrnamentList)}</div>)}
                    {this.renderFieldGroup('accidentals', false, <div>{this.renderSymbolList('symbol', util.AccidentalList)}</div>)}
                    {this.renderFieldGroup('dynamics', false, <div>{this.renderSymbolList('symbol', util.DynamicList)}</div>)}
                    {this.renderFieldGroup('repeats', false, <div>{this.renderSymbolList('symbol', util.RepeatList)}</div>)}
                    {this.renderFieldGroup('text', false, <div className="text">{this.renderSymbolList('text', util.TextList)}</div>)}
                    {this.renderFieldGroup('beam', false, <div>{this.renderSymbolList('action', util.BeamList)}</div>)}
                    <aui-music-stavepop notationClick={this.onNotationPopClick} />
                </div>
                <div className="aui-modal-content  aui-dialog-body-scroll">
                    <aui-button-lite id="global-setting" block>
                        <span slot="icon-end" className="faui-angle-down-s"></span>
                        <span slot="text">{I18N.globalSetting}</span>
                    </aui-button-lite>
                    <aui-pop
                        delegate="#global-setting"
                        width="100%"
                        eventScope="parent"
                        triggerEvent="click"
                        onShow={this.onToggleClick}
                        onHide={this.onToggleClick}
                        ref={this.ref('globalSetting')}
                    >
                        <div id="global-popup">
                            <div className="flex">
                                <fieldset className="col-md-6">
                                    <aui-input-lite name="title" value={this.state.title} placeholder={I18N.defaultTitle} onChange={this.onFormChange}>
                                        <legend slot="block-start">{I18N.title}</legend>
                                    </aui-input-lite>
                                </fieldset>
                                <fieldset className="col-md-6">
                                    <legend slot="block-start">{I18N.metre}</legend>

                                    <div className="metre">
                                        <aui-input-lite
                                            type="number"
                                            name="metreNumerator"
                                            value={this.cache.metreNumber}
                                            onChange={this.onFormChange}
                                            inputMode="numeric"
                                        ></aui-input-lite>
                                        <span className="span-between">/</span>
                                        <aui-select-lite
                                            name="metreDenominator"
                                            onChange={this.onFormChange}
                                            items={util.metreDenominatorList}
                                            value={this.cache.denominator}
                                        ></aui-select-lite>
                                    </div>
                                </fieldset>
                            </div>
                            <div className="flex">
                                <fieldset className="col-md-6">
                                    <legend>{I18N.key}</legend>
                                    <aui-tabbutton name="keyMode" items={this.#keyModes} active={this.state.keyMode} onChange={this.onKeyModeChange} />
                                    <section className="margin-block-start-s">
                                        <aui-select-lite
                                            name="key"
                                            onChange={this.onFormChange}
                                            items={this.state.keyMode === 0 ? util.keyMajor : util.keyMinor.join(';')}
                                            value={this.state[this.state.keyMode === 0 ? 'major' : 'minor']}
                                        ></aui-select-lite>
                                    </section>
                                </fieldset>
                                <fieldset className="col-md-6" name="grand">
                                    <legend>{I18N.clef}</legend>
                                    <aui-tabbutton name="clefMode" items={this.#clefModes} active={this.state.clefMode} onChange={this.onClefModeChange} />
                                    <section className="margin-block-start-s">
                                        {util.clefs.map((item, index) => {
                                            const value = item.toLowerCase();
                                            return (
                                                <aui-togglebutton
                                                    group={this.state.clefMode === 0 ? 'clef' : ''}
                                                    value={value}
                                                    checked={this.state.checkedClefs.includes(value)}
                                                    onClick={this.onFieldChange}
                                                    disabled={!!this.state.clefMode}
                                                >
                                                    <span className="clef-selector" data-tooltip="true" aria-label={value} data-grand={util.grandClefs.includes(value)}>
                                                        {ABCJS.parseIcon(item)}
                                                    </span>
                                                </aui-togglebutton>
                                            );
                                        })}
                                    </section>
                                </fieldset>
                            </div>
                            <div className="flex">
                                <fieldset className="col-md-12">
                                    <legend>{I18N.tempo}</legend>
                                    <aui-tabbutton name="tempoMode" items={this.#tempoModes} active={this.state.tempoMode} onChange={this.onTempoModeChange} />
                                    <section className="margin-block-start-s tempo">
                                        <div className="nowrap">
                                            {[2, 2, 4, 4, 8, 8].map((item, index) => {
                                                const dotted = index % 2,
                                                    val = (dotted ? 3 : 1) + '/' + item * (dotted ? 2 : 1);
                                                return (
                                                    <aui-togglebutton
                                                        group="tempo"
                                                        value={val}
                                                        checked={this.state.tempoMode === 0 ? false : val === this.state.checkedTempo}
                                                        onClick={this.onFieldChange}
                                                        disabled={this.state.tempoMode === 0}
                                                    >
                                                        <span className={['note', dotted ? 'dotted' : '']} data-denominator={item}>
                                                            {ABCJS.parseIcon('Note' + item)}
                                                        </span>
                                                    </aui-togglebutton>
                                                );
                                            })}
                                        </div>
                                        <span className="span-between">=</span>
                                        <aui-input-lite type="number" name="bpm" disabled={this.state.tempoMode === 0} value={this.state.tempoCount} onChange={this.onFormChange} />
                                    </section>
                                </fieldset>
                            </div>
                        </div>
                    </aui-pop>
                    <aui-music-staveecho
                        uid={this.uuid}
                        ref={this.ref('staveRegion')}
                        onSelectionChange={this.onSelectionChange}
                        staveKeyDown={this.staveKeydown}
                        midiDownload={this.options.midiDownload}
                    />
                </div>
            </div>
        );
    }
}
