import { I18N } from '../../core/base/i18n.js';
import { error } from '../../core/base/log.js';

import numberClamp from '../number/clamp.js';
import splitAt from '../string/split-at.js';

import { hour12to24 } from './hour-convert.js';
import maxMonthDays from './max-month-days.js';

const numReg = '[0-9]{1,2}';
// Don't change list order and name variable case. !!!
const list = [
    [/(yy+)/, '[0-9]{2,4}', 'year'],
    [/(ddd+)/, String.raw`\S+`, 'week'],
    [/(d+)/, numReg, 'day'],
    [/(h+)/, numReg, 'hour'],
    [/(H+)/, numReg, 'Hour'],
    [/(m+)/, numReg, 'minute'],
    [/(s+)/, numReg, 'second'],
    [/(M+)/, [numReg, String.raw`(?:\S|(?:[0-9]{1,2} \S))+`], ['Month', 'month'], (l) => (l > 2 ? 1 : 0)],
    [/(tt+)/, '(?:am|pm)'],
];

function clamp(strict) {
    return function (val, min, max) {
        if (val == null) return null;
        val = Number(val);
        if (strict) {
            if (val < min || val > max) return Number.NaN;
            return val;
        }
        return numberClamp(min, val, max);
    };
}

function parseRegexp(format, strict) {
    const length = {};
    let reg = format;

    for (const item of list) {
        let [pattern, char, name, condition] = item;
        const match = reg.match(pattern);
        if (match) {
            const m = match[0],
                l = m.length;
            if (condition) {
                const n = condition(l);
                char = char[n];
                name = name[n];
            }
            if (strict && char) {
                const quantityReg = /\{(\d+),(\d+)\}/,
                    [_m, _min, _max] = char.match(quantityReg) || [];
                if (_max && l === Number(_max)) char = char.replace(quantityReg, `{${l}}`);
            }
            length[name] = l;
            reg = reg.replace(m, `(?<${name || m}>${char})`);
        }
    }

    return { length, reg: new RegExp(String.raw`^\s*` + reg + String.raw`\s*$`, 'i') };
}

/** @type {typeof $$.date.parseByFormat} */
export default function parseByFormat(val, format, strict, sv) {
    const { length, reg } = parseRegexp(format, strict),
        match = val.match(reg),
        invalid = new Date(Number.NaN);
    if (!match) return invalid;

    const data = match.groups;
    if (sv) return { reg, ...data };

    const num = clamp(strict);
    let { year, Month, month, day, Hour, hour, minute, second, tt } = data;
    if (year && year.length <= 2) {
        let [pre, suf] = splitAt(String(new Date().getFullYear()), 2);
        if (Number(year) > Number(suf)) pre -= 1;
        year = String(pre) + year;
    }
    if (!Month && month) {
        const f = ['shortMonths', 'months'][length.month - 3],
            [...i18nMonths] = I18N.calendar[f];
        Month = i18nMonths.indexOf(month);
        if (Month < 0) {
            error('Parse month failed', month);
            return invalid;
        }
        Month += 1;
    }
    if (Month) {
        Month = num(Month, 1, 12) - 1;
        if (day) {
            day = num(day, 1, maxMonthDays(Month, year));
        }
    }
    if (Hour == null && hour) {
        Hour = tt ? hour12to24(hour, tt) : hour;
    }
    Hour = num(Hour, 0, 23);
    minute = num(minute, 0, 59);
    second = num(second, 0, 59);

    const args = [year, Month, day];
    if (args.join('')) {
        if (Hour != null) args.push(Hour);
        if (minute != null) args.push(minute);
        if (second != null) args.push(second);
        return new Date(...args);
    } else {
        return new Time(Hour, minute, second);
    }
}
