/** @jsxImportSource @gui/aui-devops */
import $ from '../../core/element/index.js';
import { define, Widget } from '../../widget/widget.js';

import { keyPress as eventKeyPress } from '../../util/event/key-press.js';

import { ModalWidget, Inherit } from './modal-widget.js';

import barStyle from './dialog-bar.less';
import style from './style.less';

const { options, observers, forwardOptions } = Inherit(['aspectRatio', 'closeable', 'compact', 'height', 'maximize', 'minimize', 'resizeable', 'width', 'onMinimize']);
const I18N = $$.I18N.dialog;

/** @extends {Widget<typeof Dialog.options>} */
@define('dialog')
export class Dialog extends ModalWidget {
    static options = {
        ...options,
        topLayer: false,
        dragable: false,
    };
    static observers = [...observers];
    static styles = style;
    static internals = { role: 'dialog' };

    #restoreMinimize = null;
    #minimizedBar() {
        const { $body } = $;
        let bar = $body.find('aui-dialog-bar').get();
        if (!bar) {
            bar = <aui-dialog-bar global />;
            $body.append(bar);
        }
        return bar;
    }
    onMinimize = (e, args) => {
        /** @type {DialogBar} */
        const bar = this.#minimizedBar();
        this.#restoreMinimize = bar.method('push', { ...args, uuid: this.uuid });
    };
    restoreMinimize() {
        $$.fn(this.#restoreMinimize)();
        this.#restoreMinimize = null;
    }
    doShow() {
        this.restoreMinimize();
    }
    doHide() {
        this.restoreMinimize();
    }
    onDragStart = (e) => {
        const { dialog } = this,
            styles = { margin: 0, left: dialog.offsetLeft + 'px', top: dialog.offsetTop + 'px' };
        $(dialog).css(styles);
    };
    willDrag = (e) => {
        this.$element.addClass('dragging');
    };
    onDragEnd = (e) => {
        const { left, top } = this.dialog.style;
        this.$element.removeClass('dragging');
        const styles = this.element.getState('styles');
        Object.assign(styles, { margin: 0, left, top });
    };
    render() {
        const { dragable, backdrop, topLayer, ...args } = this.options,
            modalOptions = forwardOptions(args);
        return (
            <aui-modal {...modalOptions} backdrop={backdrop && (topLayer || '_similar')} {...this.modalOptions} onMinimize={this.onMinimize}>
                <slot name="header" slot="header" />
                <slot name="actions" slot="actions" />
                <slot>
                    <div id="body-placeholder" />
                </slot>
                <slot name="footer" slot="footer" />
                <slot name="buttons" slot="buttons" onClick={this.onButtonClick} />
                {dragable && (
                    <aui-drag
                        eventScope=":parent(aui-modal)"
                        handle=".header>.contents"
                        target="dialog"
                        onDragStart={this.onDragStart}
                        willDrag={this.willDrag}
                        onDragEnd={this.onDragEnd}
                    />
                )}
            </aui-modal>
        );
    }
}

/** @extends {Widget<typeof DialogBar.options>} */
@define('dialog-bar')
class DialogBar extends Widget {
    static options = {
        global: false,
    };
    static styles = barStyle;
    create() {
        this.method = { push: this.push, topLayer: this.topLayer };
    }
    didMount() {
        eventKeyPress(this.element, 'Enter', 'li', (e) => e.currentTarget.click());
    }
    checkEllipsis = (e) => {
        const li = e.currentTarget;
        li.dataset.ellipsis = !!$(li).textOverflow();
    };
    #onClick(cb) {
        const instance = this;
        return function (e) {
            const target = arguments.length ? e.currentTarget : this;
            target.remove();
            cb();
            if (!instance.element.childElementCount) instance.topLayer(false);
        };
    }
    /** @returns {()=>void} `doRestore` A function to restore(remove DOM).  */
    push = ({ uuid, header, restoreMinimize, close }) => {
        const onClick = this.#onClick(restoreMinimize);
        const item = (
            <li role="tab" tabIndex={0} data-uuid={uuid} onClick={onClick} onMouseEnter={this.checkEllipsis}>
                <section>
                    <span>{header}</span>
                </section>
                <aui-button-lite type="bald" icon="faui-close" onClick={close} tooltip={I18N.close} />
            </li>
        );
        this.element.append(item);
        if (this.options.global) this.topLayer(true);
        item.focus();
        const doRestore = onClick.bind(item);
        return doRestore;
    };
    topLayer = (v) => {
        const el = this.element;
        return v ? el.showPopover() : el.hidePopover();
    };
    render() {
        return <ul className="empty-hidden" popover="manual" role="tablist" />;
    }
}
