/** @jsxImportSource @gui/aui-devops */
import { define, Widget, Types } from '../../widget/widget.js';

import groupStyle from './toolbar-group.less';

/** @extends {Widget<typeof ToolbarGroup.options>} */
@define('editor-toolbargroup')
export class ToolbarGroup extends Widget {
    static options = {
        name: Types.string,
        icon: Types.string,
    };
    static styles = groupStyle;
    render() {
        return (
            <dl>
                <dt>
                    <span className={this.options.icon} />
                    <p>{this.options.name}</p>
                </dt>
                <dd>
                    <slot />
                </dd>
            </dl>
        );
    }
}
