import React, { createRef, PureComponent } from 'react';

import { UIComponent } from '../../core/base/component.jsx';
import { error } from '../../core/base/log.js';
import { WR } from '../../widget/widget.jsx';

import { concat } from '../../util/array/concat.js';

import { Popup } from '../popup/popup.jsx';

const _constant = {
    WIDGET_CLASS: 'aui-widget',
    BREADCRUMB_CLASS: 'aui-breadcrumb',
    BREADCRUMB_BOX_CLASS: 'aui-breadcrumb-box',
    BREADCRUMB_ITEM_CLASS: 'aui-breadcrumb-item',
    BREADCRUMB_BUTTON_BOX_CLASS: 'aui-breadcrumb-button-box',
    BREADCRUMB_HIDDEN_ITEM_CLASS: 'aui-breadcrumb-hidden-item',
    BREADCRUMB_SIBLINGS_BUTTON_CLASS: 'aui-breadcrumb-siblings-button',
    BREADCRUMB_POPUP_CLASS: 'aui-breadcrumb-popup',
    BREADCRUMB_LINK_CLASS: 'aui-breadcrumb-link',
    BREADCRUMB_LINK_ICON_CLASS: 'aui-breadcrumb-link-icon',
    BREADCRUMB_LINK_TEXT_CLASS: 'aui-breadcrumb-link-text',
};

const dictionary = {};
let uuid = 0;

export class Breadcrumb extends UIComponent {
    widgetName = 'breadcrumb';

    static defaultProps = {
        items: [],
    };

    static setItems(id, items) {
        const instance = dictionary[id];
        if (!instance) return error('[breadcrumb]', `The Breadcrumb with id: ${id} doesn't exist!`);

        const oldItems = instance.props.items,
            oldItemsCopy = oldItems.slice();

        Array.prototype.splice.apply(oldItems, [0, oldItems.length, ...items]);
        instance.$element.breadcrumb('setItems', items, oldItemsCopy);
        instance.updateItems();
    }

    constructor(props) {
        super(props);
        dictionary[this.props.id] = this;
        this.state = {
            items: this.props.items,
        };

        this.itemsContainer = createRef();
    }
    componentDidUpdate(prevProps, prevState) {
        super.componentDidUpdate(prevProps, prevState);
        if (this.props.items !== prevProps.items) {
            this.updateItems();
        }

        const $itemsContainer = this.$element.find(`.${_constant.BREADCRUMB_BOX_CLASS}`);
        const $buttonBox = this.$element.find(`.${_constant.BREADCRUMB_BUTTON_BOX_CLASS}`);
        if ($buttonBox.is($itemsContainer.find('li:first-child'))) {
            $buttonBox.appendTo($itemsContainer);
            $buttonBox.insertAfter($itemsContainer.find('li:first-child'));
        }
    }

    handleItemsOnClick = (item, e) => {
        if (typeof this.props.onClick === 'function') {
            if (this.props.onClick(item) === false || !item.url) {
                e.preventDefault();
            }
        }
    };

    updateItems() {
        this.itemsContainer.current.removeAttribute('style');
        this.setState({
            items: concat(this.props.items || []),
        });
    }

    render() {
        const Link = this.props.Link || $$.fn($$.useRouter)()?.Link,
            { items } = this.state;

        return (
            <nav ref={this.ref} id={this.props.id} className={_constant.BREADCRUMB_CLASS}>
                <ol className={_constant.BREADCRUMB_BOX_CLASS} ref={this.itemsContainer}>
                    {this.state.items.map((item, index) => {
                        return (
                            <BreadcrumbItem
                                key={`${item.text}_${index}`}
                                item={item}
                                Link={Link}
                                isLast={items.length > 1 && index === items.length - 1}
                                onClick={this.handleItemsOnClick}
                            ></BreadcrumbItem>
                        );
                    })}
                </ol>
            </nav>
        );
    }
}

class BreadcrumbItem extends PureComponent {
    static defaultProps = {
        item: {},
        isLast: false,
        onClick: null,
    };

    constructor(props) {
        super(props);
        this.popupTriggerId = 'aui_breadcrumb_popup_trigger_' + uuid++;
    }

    content = (
        <>
            {this.props.item.icon && <div className={_constant.BREADCRUMB_LINK_ICON_CLASS + ' ' + this.props.item.icon} />}
            <div className={_constant.BREADCRUMB_LINK_TEXT_CLASS}>{this.props.item.text}</div>
        </>
    );

    handleItemOnClick = (e) => {
        this.props.onClick(this.props.item, e);

        const $popup = jQuery(e.target).closest(`.${_constant.BREADCRUMB_POPUP_CLASS}`);

        if ($popup.length) {
            $popup.popup('hide');
        }
    };
    renderLastSiblings(item) {
        return (
            <>
                <WR.ButtonLite
                    className={_constant.BREADCRUMB_SIBLINGS_BUTTON_CLASS}
                    id={this.popupTriggerId}
                    type="bald"
                    aria-expanded="false"
                    aria-haspopup="true"
                    data-tooltip={item.tooltip}
                >
                    {item.icon && <span slot="icon" className={item.icon} />}
                    <span slot="text">{item.text}</span>
                    <span slot="icon-end" className="faui-edit-solid"></span>
                </WR.ButtonLite>
                <Popup className={_constant.BREADCRUMB_POPUP_CLASS} of={`#${this.popupTriggerId}`} triggerEvent="click">
                    <ol>
                        {item.siblings.map((sibling) => {
                            return <BreadcrumbItem key={sibling.text} item={sibling} onClick={this.props.onClick}></BreadcrumbItem>;
                        })}
                    </ol>
                </Popup>
            </>
        );
    }

    renderItem = () => {
        const { item, Link } = this.props,
            url = item.url,
            { content } = this,
            attr = { className: _constant.BREADCRUMB_LINK_CLASS, 'aria-label': item.tooltip, 'data-tooltip': 'ifneed' };
        if (url) {
            attr.onClick = this.handleItemOnClick;
            if (url === true) {
                return (
                    <button {...attr} type="button">
                        {content}
                    </button>
                );
            }
            return Link ? (
                <Link {...attr} to={url}>
                    {content}
                </Link>
            ) : (
                <a {...attr} href={url}>
                    {content}
                </a>
            );
        } else {
            return <div {...attr}>{content}</div>;
        }
    };

    render() {
        const { item, isLast } = this.props;
        const classList = [_constant.BREADCRUMB_ITEM_CLASS];
        if (item.classify) classList.push('aui-breadcrumb-classify-' + item.classify);
        const className = classList.join(' ');
        if (isLast) {
            return (
                <li className={className}>
                    {item.siblings && this.renderLastSiblings(item)}
                    {!item.siblings && (
                        <div aria-current="page" data-tooltip="ifneed">
                            {this.content}
                        </div>
                    )}
                </li>
            );
        } else {
            return <li className={className}>{this.renderItem()}</li>;
        }
    }
}

$$.shell.define('Breadcrumb', Breadcrumb);
