import { _parse } from './_parse.js';

/** @type {typeof $$.number.round} */
export default function round(val, interval = 1, strategy = 'nearest') {
    val = _parse(val);
    if (Number.isFinite(val) && interval > 0) {
        const quotient = val / interval;
        switch (strategy) {
            case 'nearest':
                return Math.round(quotient) * interval;
            case 'up':
                return Math.ceil(quotient) * interval;
            case 'down':
                return Math.floor(quotient) * interval;
            case 'toZero':
                return Math.trunc(quotient) * interval;
        }
    }
    return Number.NaN;
}
