import { WR } from '../../widget/widget.jsx';

import '../editorecho/editorecho.jsx';

import { Editor as EditorWidget } from './editor.js';
import { autoTag } from './method.js';

const Editor = WR.Editor;
Object.assign(Editor, {
    autoTag,
    addPlugin(name, pluginProto) {
        return EditorWidget.addPlugin(name, pluginProto);
    },
    toolbarScheme(value) {
        if (value) {
            EditorWidget.toolbar = value;
        } else {
            return EditorWidget.toolbar;
        }
    },
    fontNames(value) {
        if (value) {
            EditorWidget.fontNames = value;
        } else {
            return EditorWidget.fontNames;
        }
    },
    fontSizes(value) {
        if (value) {
            EditorWidget.fontSizes = value;
        } else {
            return EditorWidget.fontSizes;
        }
    },
});

$$.shell.define('Editor', Editor);

export { Editor };
