/* eslint-disable perfectionist/sort-imports */
'use strict';
import Resolution from '../resolution.json';
import { getBrowser } from '../../misc/browser.js';
import merge from '../../util/object/merge.js';
import fixFloat from '../../util/number/fix-float.js';
import { AuiElementEntry as $ } from '../element/element.js';
import { GetEvent } from '../element/event.js';
import { onloading, onload, idleLoad } from './onload.js';
import { config, setConfig } from './config.js';
import _ from './create-element.js';
import * as logUtils from './log.js';

if (!window.jQuery) logUtils.throws("The jQuery library hasn't been imported correctly!");

// AUI system in global namespace.
export const $$ = {
    _: _,
    createElement: _,
    ...logUtils,
    onloading,
    onload,
    idleLoad,
};
const Extend = (v) => Object.assign($$, v);
window.$$ = $$;

(function () {
    let hideScrollbarCounter = 0;
    const browser = getBrowser();
    Extend({ browser });

    const cssVarGetter = (k) => getComputedStyle(config.root).getPropertyValue(k);
    const cssVarSetter = (k, v, flag = true) => config.root.style[(flag ? 'set' : 'remove') + 'Property'](k, v);

    (function () {
        browser.env = {
            animate: !window.matchMedia('(prefers-reduced-motion: reduce)').matches,
            highContrast: window.matchMedia('(forced-colors: active)').matches || window.matchMedia('(prefers-contrast: more)').matches,
        };

        browser.orient = getOrientation();
    })();

    onloading(function () {
        const dir = config.body.getAttribute('dir') || config.root.getAttribute('dir') || getComputedStyle(config.body, null).getPropertyValue('direction');
        browser.dir = dir === 'rtl' ? 'rtl' : 'ltr';

        if (browser.touchable) {
            config.root.classList.add('aui-touchable');
        } else if (browser.virtualKeyboardShown != null && window.chrome && !navigator.plugins?.length) {
            logUtils.error('[Chrome simulation] touchable state got error! exit the mode and try again.');
        }

        if (window.top === window.self) {
            $$.sameOrigin = true;
        } else {
            try {
                const win = window.top;
                $$.sameOrigin = !(!win.document || !win.localStorage);
            } catch (e) {
                $$.sameOrigin = false;
            }
        }
    });

    Extend({
        assets: (function getPath() {
            const sourceMap = { script: 'src', link: 'href' };
            const loop = (name, reg, cb) => {
                const elements = document.getElementsByTagName(name),
                    field = sourceMap[name];
                for (const el of elements) {
                    const source = el[field];
                    if (!source) continue;
                    const url = new URL(source),
                        paths = url.pathname.split('/'),
                        leaf = paths.pop();
                    if (reg.test(leaf)) return cb(url.origin + paths.join('/'), leaf);
                }
            };

            const result = {};
            loop('script', /^aui(\.(react))?(\.min)?\.js/, (path, leaf) => {
                result.jsName = leaf;
                result.jsPath = path;
                result.jsFullPath = path + '/' + leaf;
            });
            loop('link', /^aui(\.min)?\.css/, (path, leaf) => {
                result.cssName = leaf;
                result.cssPath = path;
                result.cssFullPath = path + '/' + leaf;
            });
            result.path = result.jsPath || result.cssPath;
            if (!result.jsPath) logUtils.error('Load AUI path failed!');
            return result;
        })(),

        dpi: {},
        dpr: 1,

        viewport: null,
        mobileEnv: 0,
        mobileView: false,
    });

    onloading(function () {
        const { deviceXDPI, deviceYDPI } = window.screen;
        let x, y;
        if (deviceXDPI == null) {
            const tmpNode = document.createElement('div');
            tmpNode.style.cssText = 'width:1in;height:1in;position:absolute;left:0px;top:0px;z-index:99;visibility:hidden';
            config.body.append(tmpNode);
            x = Number.parseInt(tmpNode.offsetWidth, 10);
            y = Number.parseInt(tmpNode.offsetHeight, 10);
            tmpNode.remove();
        } else {
            x = deviceXDPI;
            y = deviceYDPI;
        }
        Extend({ dpi: { x, y, val: (x + y) / 2 } });

        const { device, name } = browser.os;
        if (config.mobileViewEnable && device === 'phone' && name === 'ios') {
            const metaVP = document.head.querySelector('meta[name="viewport"]') || _('meta', { name: 'viewport' });
            let data = {};
            if (metaVP.content) {
                for (const item of metaVP.content.split(',')) {
                    const [k, v] = item.trim().split('=');
                    data[k] = v;
                }
            }
            data = { width: 'device-width', 'initial-scale': '1', 'minimum-scale': '1', ...data, 'maximum-scale': '1' };
            metaVP.content = Object.entries(data)
                .map(([k, v]) => `${k}=${v}`)
                .join(',');
        }
    });

    function getOrientation() {
        const { orientation } = window.screen;
        return orientation.type.startsWith('landscape') ? 'h' : 'v';
    }
    onloading(function responsiveViewport() {
        const resolutionASC = Object.entries(Resolution).sort((a, b) => a[1] - b[1]);
        function update() {
            const { root, mobileViewEnable } = config,
                [view] = resolutionASC.findLast(([k, v]) => root.clientWidth >= v) || []; // find the max one >= current width.

            if ($$.viewport !== view) {
                const prefix = 'aui-viewport-',
                    inited = $$.viewport != null,
                    { classList } = root,
                    list = Array.from(classList).filter((c) => !c.startsWith(prefix));
                $$.viewport = view;
                root.dataset.viewport = view;
                root.setAttribute('class', list.concat(prefix + view).join(' '));
                const inMobile = String(view).endsWith('s'),
                    mobileEnv = mobileViewEnable && inMobile ? 1 + (String(view).match(/x/g)?.length || 0) : 0;
                let mobileView = !!(browser.touchable && inMobile);
                if ($$.mobileEnv !== mobileEnv) {
                    $$.mobileEnv = mobileEnv;
                    classList.toggle('aui-mobile-env', !!mobileEnv);
                    mobileView = !!mobileViewEnable && mobileView;
                    if ($$.mobileView !== mobileView) {
                        $$.mobileView = mobileView;
                        classList.toggle('aui-mobile-view', mobileView);
                    }
                    if (inited) $(root).trigger('MobileToggle');
                }
                if (inited) $(root).trigger('ViewChange');
            }
        }

        window.addEventListener('orientationchange', function (e) {
            browser.orient = getOrientation();
            $$.closeAll();
        });

        // eslint-disable-next-line unicorn/consistent-function-scoping
        function setDpr(dpr) {
            if ($$.dpr !== dpr) cssVarSetter('--dpr', dpr, true);
            $$.dpr = dpr;
        }
        window.addEventListener('resize', (e) => {
            if (browser.os.device === 'desktop') {
                setDpr(window.devicePixelRatio);
                $$.closeAll();
            }
            update();
        });
        window.visualViewport.addEventListener('resize', (e) => {
            cssVarSetter('--window-height', Math.floor(visualViewport.height) + 'px', $$.mobileView);
            cssVarSetter('--window-width', Math.floor(visualViewport.width) + 'px', $$.mobileView);
            if (browser.touchable) setDpr(fixFloat(visualViewport.scale));
        });
        update();
        setDpr(browser.touchable ? visualViewport.scale : window.devicePixelRatio);
    });

    onload(function virtualKeyboard() {
        const { $root } = $;
        function toggleVK(isShow, height) {
            const vkHeight = fixFloat(height);
            if (vkHeight < 1) isShow = false; // height diff should be valid (1px at least).

            if (browser.virtualKeyboardShown !== isShow) {
                browser.virtualKeyboardShown = isShow;
                cssVarSetter('--vk', vkHeight + 'px', isShow);
                $root.toggleClass('vk-shown', isShow);
                $root.trigger('VKeyboardToggle');
                if (!isShow && browser.os.name === 'android') {
                    const _active = document.activeElement;
                    if (_active?.matches(':read-write')) _active.blur();
                }
            } else if (isShow) {
                cssVarSetter('--vk', vkHeight + 'px', true); // VK IME height changing during shown.
            }
        }
        try {
            navigator.virtualKeyboard.overlaysContent = true;
            navigator.virtualKeyboard.addEventListener('geometrychange', (e) => {
                const { height } = e.target.boundingRect;
                toggleVK(height > 0, height);
            });
        } catch (e) {
            let lastViewport,
                lastOrient = browser.orient;
            const setViewport = () => (lastViewport = merge({}, window.visualViewport, false));
            setViewport();
            window.visualViewport.addEventListener('resize', (e) => {
                if (lastViewport) {
                    // address: android 56.18       IOS 71
                    // VK IME: android SouGou 343.82     IOS 235
                    const diff = (a, b) => a * visualViewport.scale - b * lastViewport.scale,
                        diffH = diff(visualViewport.height, lastViewport.height),
                        absH = Math.abs(diffH);
                    if (absH > 0 && lastOrient === browser.orient) {
                        if (absH > 230) {
                            toggleVK(diffH < 0, absH);
                        } else if (absH > 50 && $root.is(':scrollable')) {
                            // address change.
                            $$.closeAll();
                        }
                    }
                    lastOrient = browser.orient;
                }
                setViewport();
            });
        }
    });

    // core util
    const noop = function () {};
    Extend({
        getClassBuiltIn: function (object) {
            if (typeof object?.$$typeof === 'symbol') {
                return object.$$typeof.description;
            }
            return Object.prototype.toString.call(object).match(/^\[object\s(.*)\]$/)[1];
        },

        fn: function (val, thisArg, delay) {
            const delayT = typeof delay,
                _delay = delayT === 'number' ? delay : null,
                _fallback = delayT === 'function' ? delay : null;
            if (typeof val !== 'function') return _fallback || noop;
            if (thisArg === undefined) thisArg = null;
            return function (...args) {
                if (_delay == null) return val.apply(thisArg, args);

                args = args.map((arg) => (arg instanceof Event ? GetEvent(arg) : args));
                return new Promise((resolve) => {
                    setTimeout(() => resolve(val.apply(thisArg, args)), _delay);
                });
            };
        },

        debounce: function (cb, delay) {
            let timer = null;
            if (delay == null) delay = 200;
            return function (...args) {
                const instance = this;
                clearTimeout(timer);
                timer = setTimeout(function () {
                    cb.apply(instance, args);
                }, delay);
            };
        },
        throttle: function (cb, delay) {
            let valid = true;
            if (delay == null) delay = 200;
            return function (...args) {
                const instance = this;
                if (!valid) return false;
                valid = false;
                setTimeout(function () {
                    cb.apply(instance, args);
                    valid = true;
                }, delay);
            };
        },

        // the empty bridge definition.
        _tempInsertBridge: function () {
            return false;
        },
        /**
         * insert a temporary element and delete it after callback.
         * @param {any} element The element to insert.
         * @param {Function} callback
         */
        tempInsert: function (value, callback, args) {
            const instance = $$.getUniqueElement(this),
                box = document.createElement('div'),
                el = document.createElement('div');
            Object.assign(box.style, { position: 'fixed', left: 0, top: 0, width: '1000vw', opacity: 0, zIndex: -9, pointerEvents: 'none' });

            if (typeof value === 'string') {
                if (value.trim()[0] === '<') {
                    const { body } = Document.parseHTMLUnsafe(value);
                    el.append(...body.children);
                } else {
                    el.setHTMLUnsafe(value);
                }
            } else if (value instanceof Text) {
                el.textContent = value.nodeValue;
            } else {
                el.append(...$(value).toArray());
            }
            if (el.childNodes.length > 1) {
                el.replaceChildren(el.firstElementChild || '');
                logUtils.error('Allow only one element as container, please wrap the elements into single element.');
            }

            const children = Array.prototype.slice.call(el.childNodes, 0, 1);
            if (!instance) {
                box.append(...children);
                $.$body.append(box);
            }
            function done() {
                if (instance) {
                    instance.append(...children);
                    return children[0] ?? null;
                }
                const element = box.children.length ? Array.prototype.filter.call(box.children, (c) => c.className !== 'temp' && !c.hidden).at(-1) : box.lastChild || null;
                if (typeof callback === 'function') callback(element);
                setTimeout(() => box.remove());
                return element;
            }
            // for using shell definition to deal with shell-element(like ReactElement).
            if ($$._tempInsertBridge(value, instance || box, instance ? noop : done, args) === false) {
                return done();
            }
        },
        fnExtends: function (child, parent) {
            try {
                const instance = new child({});
                return instance instanceof parent;
            } catch (e) {
                return false;
            }
        },
    });

    // scroll
    $$.scrollSize = { width: 0, height: 0, max: 0 };
    function getScrollSize() {
        const box = $$.tempInsert('<div><div style="height:100px;width:100px;overflow:auto;"><div style="height:200px;width:200px"></div></div></div>');
        const ruler = box.firstChild,
            w = ruler.offsetWidth - ruler.clientWidth,
            h = ruler.offsetHeight - ruler.clientHeight,
            cw = cssVarGetter('--scrollbar-w'),
            ch = cssVarGetter('--scrollbar-h');
        if (Number.parseInt(cw, 10) !== w) cssVarSetter('--scrollbar-w', w + 'px');
        if (Number.parseInt(ch, 10) !== h) cssVarSetter('--scrollbar-h', h + 'px');
        $$.scrollSize = { width: w, height: h, max: Math.max(w, h) };
    }
    onload(getScrollSize);

    Extend({
        hasScroll: (function () {
            const checkValues = new Set(['auto', 'scroll', 'overlay']);
            return function (element) {
                const result = { x: false, y: false },
                    { $root } = $,
                    $element = $(element),
                    _element = $element.get(0);
                let reference = _element;
                if (['body', 'html'].includes(_element.localName)) {
                    if ($element.hasClass('hide-scrollbar') || $element.is('.hide-scrollbar>body') || $element.hasClass('disabled-scroll')) return result;
                    reference = $root.get(0);
                }
                if (_element.nodeType === Node.ELEMENT_NODE) {
                    if (_element.scrollWidth > reference.clientWidth && checkValues.has($element.css('overflow-x'))) result.x = true;
                    if (_element.scrollHeight > reference.clientHeight && checkValues.has($element.css('overflow-y'))) result.y = true;
                }
                return result;
            };
        })(),
        // hide scrollbar and disable scroll of body.
        hideScrollbar: function (disable, force) {
            if (!arguments.length) return hideScrollbarCounter;
            const { $root } = $,
                { body } = config,
                _overflow = browser.touchable ? 'hidden' : body.scrollHeight > config.root.clientHeight ? 'scroll' : 'visible';
            if (disable && ++hideScrollbarCounter) {
                body.style.overflowY = _overflow;
                $root.addClass('hide-scrollbar');
            } else if (hideScrollbarCounter > 0 && (--hideScrollbarCounter === 0 || force)) {
                hideScrollbarCounter = 0;
                $root.removeClass('hide-scrollbar');
                body.style.overflowY = null;
            }
        },
    });

    Extend({
        config: function (obj) {
            /* eslint-disable aui/no-direct-$$ */
            if (obj) {
                const { lang, dateFormat, timeFormat, ...args } = obj;
                if (lang) $$.switchI18N(lang);
                if (dateFormat) $$.date.defaultFormat(dateFormat); ///
                if (timeFormat) $$.date.defaultFormat(null, timeFormat); ///

                for (const [k, v] of Object.entries(args)) {
                    setConfig(k, v, { quiet: true });
                }
            }

            return {
                ...config,
                lang: $$.I18N.lang,
                dateFormat: $$.date.getDateFormat(), ///
                timeFormat: $$.date.getTimeFormat(), ///
            };
            /* eslint-enable aui/no-direct-$$ */
        },
    });
})();
