import { error } from '../../core/base/log.js';

import clamp from '../../util/number/clamp.js';
import format from '../../util/string/format.js';
import hash from '../../util/string/hash-fnv1a.js';
import { isPrimitive } from '../../util/type/types.js';

export const I18N = $$.I18N.selection;

export function hashId(prefix, str, minLength = 4) {
    const hash32 = hash(str);
    return `${prefix}-${hash32.padStart(minLength, '0')}`;
}
export function itemId(item) {
    const prefix = 'sh', // s: selection; h: hash;
        params = new URLSearchParams(item);
    return hashId(prefix, params.toString());
}

/**
 * @typedef {ReturnType<typeof buildItem>} ItemEntity
 * @typedef {{[GroupMarkField]: true, group: string}} GroupItem
 */

export function buildItem(P, item, { fallbackValue, setChecked } = {}) {
    const obj = {
        /** @type {string} */
        text: item[P.textField] ?? '',
        /** @type {string} */
        value: String(item[P.valueField] ?? '').trim(),
        /** @type {boolean} */
        checked: setChecked ? Boolean(item[P.checkedField]) : false,
        /** @type {string} */
        tooltip: item[P.tooltipField] || '',
        /** @type {string|null} */
        status: item[P.statusField] || null,
        /** @type {boolean} */
        disabled: Boolean(item[P.disabledField]),
        /** @type {string} */
        icon: item[P.iconField] || '',
        /** @type {string} */
        group: item[P.groupField] || '',
        /** @type {Object<string, any>} */
        original: {},
    };
    if (fallbackValue && !obj.value.length) obj.value = itemId(obj);
    return obj;
}

export function createCheckedValueMatcher(P, value) {
    if (value == null) return null;
    value = Array.isArray(value) ? value : [value];

    const { valueField } = P,
        values = [],
        textValues = new Set(),
        itemValues = new Set();

    for (const v of value) {
        if (v == null) continue;
        values.push(v);
        if (typeof v === 'string') {
            textValues.add(v);
        } else if (Object.hasOwn(v, valueField)) {
            itemValues.add(buildItem(P, v).value);
        }
    }

    return {
        values,
        getCheckedByValue(item) {
            return item.disabled ? !!item.checked : textValues.has(item.text) || itemValues.has(item.value);
        },
    };
}

export function filterSearchItems(data, searchKey, matchFields) {
    const items = Array.from(data);
    let hasExactMatch = false;
    if (!searchKey) return [hasExactMatch, items];

    const entries = Object.entries(matchFields);
    const fuzzy = (v) => v.trim().replaceAll(/\s/g, ' ').toLowerCase();
    const result = items.filter((item) => {
        return entries.some(([field, matchType]) => {
            const fieldValue = String(item.original[field]), // field should find in original data
                exactMatch = fieldValue === searchKey;
            hasExactMatch = hasExactMatch || exactMatch;
            if (matchType === true) return exactMatch;
            return fuzzy(fieldValue).includes(fuzzy(searchKey)); // fuzzy match
        });
    });
    return [hasExactMatch, result];
}

export const singleFilter = {
    /** Filter and keep only the first selected item. Same logic as before (don't know why, maybe change in future?) @param {Set<Item>} selected */
    onlyFirst(selected) {
        if (selected.size <= 1) return;
        let index = 0;
        for (const item of selected) {
            if (index === 0) {
                item.checked = true;
            } else {
                item.checked = false;
                selected.delete(item);
            }
            index++;
        }
    },
    /** Filter and keep only the last selected item. @param {Set<Item>} selected */
    onlyLast(selected) {
        if (selected.size <= 1) return;
        let last = null;
        for (const item of selected) {
            item.checked = false;
            last = item;
        }
        if (last) {
            last.checked = true;
            selected.clear();
            selected.add(last);
        }
    },
};

const NullableGroupName = undefined;
/** @param {ItemEntity[]} items @returns {Map<string|NullableGroupName, ItemEntity[]>} */
export function toGroupItems(items, groupField) {
    const data = Map.groupBy(items, (item) => {
        const group = item[groupField];
        if (group == null) return NullableGroupName;
        if (typeof group !== 'string') return isPrimitive(group) ? String(group) : group;
        const str = group.trim();
        return str.length ? str : NullableGroupName;
    });
    const unGrouped = data.get(NullableGroupName); // move ungrouped to last.
    if (unGrouped) {
        error('Unexpected ungrouped items found.', unGrouped);
        data.delete(NullableGroupName);
        data.set(NullableGroupName, unGrouped);
    }
    return data;
}

function sortItemsToPin(items) {
    const checked = [],
        unchecked = [];
    for (const it of items) {
        (it.checked ? checked : unchecked).push(it);
    }
    return [...checked, ...unchecked];
}

const GroupMarkField = 'isGroup';
export function splitDataForRender({ lazyStep, pinSelected }) {
    const pageSize = Number.isFinite(lazyStep) ? clamp(1, lazyStep, 100) : Infinity;

    /** Split mapped data (after groupBy) into chunks list. @returns {Array<ItemEntity|GroupItem>[]} */
    return function (...data) {
        const result = [];
        let current = [],
            i = 0;
        for (const [group, items] of data) {
            current.push({ [GroupMarkField]: true, group }); // group header (not counted in pageSize)

            const list = pinSelected ? sortItemsToPin(items) : items;
            for (const item of list) {
                if (i >= pageSize) {
                    result.push(current);
                    current = [];
                    i = 0;
                }
                i++;
                current.push(item);
            }
        }
        if (current.length) result.push(current);
        return result;
    };
}

function loopData(data, lazyPageCount, onItem, onGroup) {
    for (let i = 0; i < lazyPageCount; i++) {
        const items = data[i];
        if (!items?.length) continue;

        for (const item of items) {
            if (item[GroupMarkField] === true) {
                if (onGroup) onGroup(item);
            } else {
                onItem(item);
            }
        }
    }
}

export function dataRender(itemRender, groupRender) {
    /** @param {{data:Array<ItemEntity|GroupItem>[]}} */
    return function ({ data, lazyPageCount }) {
        let firstChecked, firstItem, currentGroup;
        let hasGroup = false;
        const elements = [];
        loopData(
            data,
            lazyPageCount,
            (item) => {
                const el = itemRender(item);
                if (!firstItem) firstItem = el;
                if (item.checked && !firstChecked) firstChecked = el;
                return currentGroup ? currentGroup.append(el) : elements.push(el);
            },
            (item) => {
                hasGroup = hasGroup || item.group !== NullableGroupName;
                if (hasGroup) {
                    currentGroup = groupRender(item.group);
                    elements.push(currentGroup);
                }
            }
        );
        const defaultTarget = firstChecked || firstItem;
        if (defaultTarget) defaultTarget.querySelector('input').setAttribute('tabindex', 0);
        return elements;
    };
}

export function parseSelectAllState(checked, items, selected) {
    selected.clear();
    let disabled = true,
        matches = true,
        changed = false;
    if (items.size) {
        for (const item of items) {
            if (item.disabled) {
                if (item.checked !== checked) matches = false;
            } else {
                disabled = false;
                if (item.checked !== checked) {
                    item.checked = checked;
                    changed = true;
                }
            }
            if (item.checked) selected.add(item);
        }
    } else {
        checked = false;
    }
    return { changed, disabled, selectAllChecked: matches ? checked : 'mixed' };
}

export function noneMessage(searchKey, searchMinChars, P) {
    const length = searchKey?.length ?? 0;
    if ($$.mobileView) {
        const moreToSearch = searchMinChars > 1 && length < searchMinChars;
        if (moreToSearch) return format(I18N.minChars, searchMinChars);
    }
    return length ? P.noMatchText : P.noneText;
}
export function disableItemsForExceedMaxLength(items, selected, P) {
    for (let i = 0; i < items?.length; i++) {
        const Lists = items[i];

        for (const list of Lists) {
            list.disabled = selected.every((s) => s[P.valueField] !== list.value);
        }
    }
    return items;
}
