/** @jsxImportSource @gui/aui-devops */
import { define, Widget, Types } from '../../widget/widget.js';

import style from './style.less';

const GroupMap = {};

/** @extends {Widget<typeof Accordion.options>} */
@define('accordion')
export class Accordion extends Widget {
    static observers = ['header', 'toggleable', 'status'];
    static options = {
        group: Types.string,
        lazyLoad: true,
        level: Types.Enum([0, 1, 2], 1),
        header: Types.string,
        toggleable: true,
        triggerType: Types.Enum(['action', 'all'], 'all'),
        status: Types.Object({ show: [Types.boolean, false] }),
        onHide: Types.function,
        onShow: Types.function,
        willShow: Types.function,
    };
    static styles = style;
    static upcasts = ['level'];

    init() {
        const { lazyLoad, status } = this.options;
        const { show } = status;

        this.method = {
            toggle: this.toggle,
        };
        this.state = {
            contentLoaded: !lazyLoad || show,
            expanded: show,
            willLoad: false,
        };
    }

    didMount() {
        const { group } = this.options;

        if (!GroupMap[group]) GroupMap[group] = [];
        GroupMap[group].push(this.host);
        this.$host.on('Open', () => this.toggle(true, true));
        this.customState('box_partial', true);
    }

    didRender() {
        this.host.setAttribute('expanded', this.state.expanded);
    }

    setOption(name, value) {
        switch (name) {
            case 'status':
                this.toggle(value.show, true);
                break;
        }
    }

    toggle = (expanded, dataDriven = false) => {
        if (this.options.toggleable) {
            if (expanded) {
                if (!this.state.contentLoaded) {
                    this.setState({ willLoad: true });
                }
                if (this.callback('willShow', dataDriven) === false) return false;

                this.expand(dataDriven);
            } else {
                this.handleExpand(false, dataDriven);
            }
        }
    };

    expand(dataDriven) {
        const { group } = this.options;

        if (group) {
            const expandedSibling = GroupMap[group].filter((host) => host.getAttribute('expanded') === 'true');

            for (const host of expandedSibling) {
                host.method('toggle', false);
            }
        }

        this.state.contentLoaded = true;
        this.state.willLoad = false;

        this.handleExpand(true, dataDriven);
    }

    handleExpand(expanded, dataDriven) {
        this.setState({ expanded: expanded });
        this.callback(expanded ? 'onShow' : 'onHide', dataDriven);
    }

    handleClick = () => {
        this.toggle(!this.state.expanded);
    };

    render() {
        const { header, toggleable, triggerType } = this.options,
            { expanded, willLoad } = this.state;
        const iconClass = this.fontIcon('faui-angle-right-s'),
            triggerAttributes = { 'aria-expanded': expanded, onClick: this.handleClick };
        const headerContent = (
            <div id="header-box">
                {header && <div className="header-content">{header}</div>}
                <slot name="header" />
            </div>
        );

        return (
            <>
                {toggleable && triggerType === 'all' ? (
                    <button type="button" className={['header', 'trigger', 'toggleable']} {...triggerAttributes}>
                        <span className={['icon', iconClass]} />
                        {headerContent}
                    </button>
                ) : (
                    <div className={['header', toggleable && 'toggleable']}>
                        {toggleable && <button type="button" className={['icon', 'trigger', iconClass]} aria-labelledby="header-box" {...triggerAttributes} />}
                        {headerContent}
                    </div>
                )}
                <slot className={['body', willLoad && 'will-load']} name="body" />
            </>
        );
    }
}
