function operate(date, value, getter, setter) {
    if (value != null) {
        const operands = { '+': 1, '-': -1 },
            multiple = operands[value[0]];
        if (typeof value === 'string' && multiple) {
            const offset = Number.parseInt(value.slice(1), 10) * multiple;
            if (offset) date[setter](date[getter]() + offset);
        } else {
            const num = Number.parseInt(value, 10);
            if (!Number.isNaN(num)) {
                date[setter](num);
            }
        }
    }
}

/** @type {typeof $$.date.adjust} */
export default function adjust(date, year, month, day, hour, minute, second, ms) {
    operate(date, ms, 'getMilliseconds', 'setMilliseconds');
    operate(date, second, 'getSeconds', 'setSeconds');
    operate(date, minute, 'getMinutes', 'setMinutes');
    operate(date, hour, 'getHours', 'setHours');
    operate(date, day, 'getDate', 'setDate');
    operate(date, month, 'getMonth', 'setMonth');
    operate(date, year, 'getFullYear', 'setFullYear');
    return date;
}
