/** @jsxImportSource @gui/aui-devops */
import $ from '../../core/element/index.js';

const getOrCreateToaster = () => {
    const ID = 'aui-toaster';
    let toaster = document.getElementById(ID);

    if (!toaster) {
        toaster = <aui-tabloop id={ID} popover="manual" />;
        $.$body.append(toaster);
    }

    return toaster;
};

export { getOrCreateToaster };
