import { error } from '../../core/base/log.js';

import { isDate } from '../type/types.js';

import converter from './converter.js';

/** @type {typeof $$.date.convertTimeByZone} */
export default function convertTimeByZone(data) {
    if (isDate(data.date) && typeof data.zone == 'string') {
        const offsetHour = data.date.getTimezoneOffset() / 60 + Number.parseInt(data.zone.slice(4, 7), 10);
        return new Date(Date.parse(data.date) + offsetHour * converter.hour, 0);
    } else {
        error('format error');
    }
    return null;
}
