/** @jsxImportSource @gui/aui-devops */
import { resize as resizeObserver, scroll as scrollObserver } from '../../core/module/observer/observer.js';
import { define, Widget, Types } from '../../widget/widget.js';

import eventIsKey from '../../util/event/is-key.js';
import { keyName } from '../../util/event/key-name.js';
import stopEvent from '../../util/event/stop.js';
import padStart from '../../util/string/pad-start.js';

import style from './loop-list.less';

const ScrollEndSupport = Reflect.has(HTMLElement.prototype, 'onscrollend');
const AlignOffset = { center: 0.5, end: 1, start: 0 };

/** @extends {Widget<typeof LoopList.options>} */
@define('loop-list')
export class LoopList extends Widget {
    static options = {
        disabled: false,
        source: Types.string,
        max: Types.number,
        min: 0,
        step: 1,
        value: Types.Union([Types.string, Types.number]),
        size: 7,
        loop: true,
        align: Types.Enum(Object.keys(AlignOffset), 'center'),
        itemFormat: Types.function,
        onChange: Types.function,
    };
    static observers = ['disabled', 'source', 'max', 'min', 'value', 'size'];
    static upcasts = ['disabled', 'value'];
    static shadow = { delegatesFocus: true };
    static styles = style;

    #scrollBox = null;
    #main = null;
    #timer;
    focus = (args) => this.#scrollBox?.focus(args);

    create() {
        this.hostProto = { getValue: this.getValue };
    }
    init() {
        this.state = {
            items: [],
            index: -1,
            scrollStepper: 1,
            observerVisible: null,
            useEvent: false,
            useLoop: false,
            repeating: false,
            scrollDir: null,
            scrollTop: 0,
            resetScroll: false,
            scrolling: false,
        };
        this.updateBySource();
    }
    updateBySource() {
        const { loop, size, value, source, max, itemFormat } = this.options;
        let items, index;
        if (max == null) {
            const format = itemFormat ?? String;
            items = String.prototype.split.call(source ?? '', ';').map(format);
            index = items.indexOf(format(value));
        } else {
            const { min, step } = this.options,
                format = itemFormat ?? padStart;
            let validStep = step > 0 ? Math.round(step) : 1;
            if (validStep > 1) {
                while (validStep > 0) {
                    if (max % validStep === 0) break;
                    validStep--;
                }
            }
            if (validStep !== step) this.console.error(`The step "${step}" value can't be divided by the max "${max}" value!`);
            items = Array.from({ length: max / validStep }, (_, i) => {
                const v = Number.parseInt(min, 10) + i * validStep;
                if (v <= (value ?? 0)) index = i;
                return format(v);
            });
            const computedValue = items[index] ?? null;
            if (value != null && Number(computedValue) !== Number(value)) this.callback('onChange', computedValue, index);
        }
        this.setState({ items, index: index ?? -1, resetScroll: true, useEvent: items?.length > 1, useLoop: loop && items?.length >= size }, false);
    }
    didMount() {
        this.#scrollBox = this.element.querySelector(':scope > #box');
        this.#main = this.#scrollBox.querySelector(':scope > #main');
        // Defer to wait CSS box render finish: avoid error scroll position.
        setTimeout(this.initEvent);
    }
    initEvent = () => {
        const { useEvent, useLoop, items } = this.state,
            box = this.#scrollBox;
        this.state.observerVisible = this.#visible();
        const setStepper = () => {
            const { clientHeight } = this.#main.firstElementChild;
            if (clientHeight > 0) this.setState({ scrollStepper: clientHeight }, false);
        };
        const onResize = (rect) => {
            const visible = rect.height > 0;
            if (visible && !this.state.observerVisible) {
                setStepper();
                this.scrollByIndex();
            }
            this.state.observerVisible = visible;
        };
        resizeObserver(this.host, onResize, { width: false, height: true });

        this.scrollByIndex();

        if (useEvent) {
            this.$element.on('click', 'li', this.onItemClick);
            box.addEventListener('wheel', this.onWheel, { passive: false });
            this.addScrollListener();

            if (useLoop) {
                const args = { target: this.#main, startV: true, endV: true, rate: items.length - 1 };
                scrollObserver(box, args, (x, dir) => !x && this.doRepeat());
            }
            setStepper();
        }
    };
    didUpdate() {
        if (this.state.resetScroll) this.scrollByIndex();
    }
    setOption(name, value, oldValue) {
        switch (name) {
            case 'source':
            case 'max':
            case 'min':
            case 'value':
            case 'size':
                this.updateBySource();
                return true;
        }
    }
    getValue = () => {
        const { items, index } = this.state;
        return items[index] ?? null;
    };

    #visible() {
        return this.host.checkVisibility();
    }
    getCurrentElement() {
        const { align } = this.options,
            { x, y, height } = this.#scrollBox.getBoundingClientRect(),
            blockOffset = height * AlignOffset[align];
        return this.#visible() ? this.shadowRoot.elementFromPoint(x + 1, y + blockOffset) : null;
    }
    setActive(element) {
        const target = element || this.getCurrentElement();
        if (!target) return null;
        const index = target.ariaPosInSet - 1,
            items = this.#scrollBox.querySelectorAll('li');
        for (const x of items) {
            x.ariaSelected = x === target;
        }
        if (this.state.index !== index) {
            this.setState({ index }, false);
            this.callback('onChange', target.textContent, index);
        }
        return target;
    }
    scrollByElement(target, smooth) {
        if (target?.checkVisibility()) {
            if (this.state.useEvent) {
                const scrollArgs = { block: this.options.align, inline: false, scrollMode: 'always', bubbles: false, condition: { scrollPotential: true, includeHidden: true } };
                if (smooth) scrollArgs.behavior = 'smooth';
                if (!$$.scrollTo(target, scrollArgs)) {
                    this.scrolling(false);
                    this.onScrollEnd(this.#scrollBox);
                }
                this.state.scrollTop = this.#scrollBox.scrollTop;
            }
            if (!smooth) this.setActive(target);
        }
        this.state.resetScroll = false;
    }
    scrollByIndex(index, uiDriven) {
        const main = this.#main;
        if (main) {
            if (uiDriven) this.scrolling(true);
            const i = Math.max(0, index ?? this.state.index),
                target = main.children[i];
            this.scrollByElement(target, uiDriven);
            setTimeout(() => this.scrolling(false));
        }
    }
    scrollTo(dir, smooth) {
        if (this.options.disabled) return;
        const { scrollStepper } = this.state;
        // const behavior = $$.browser.touchable ? 'smooth' : 'instant';
        const behavior = smooth && ScrollEndSupport ? 'smooth' : 'instant';
        this.scrolling(smooth ? true : behavior);
        clearTimeout(this.#timer);
        this.#scrollBox.scrollBy({ top: dir ? scrollStepper : scrollStepper * -1, behavior });
        if (ScrollEndSupport) {
            this.#timer = setTimeout(() => this.scrolling(false), 20);
        } else {
            // https://bugs.webkit.org/show_bug.cgi?id=293227
            this.scrollByElement(this.getCurrentElement());
            this.scrolling(false);
        }
    }
    scrolling(v) {
        this.#scrollBox.dataset.scrolling = v !== false && v != null;
        this.state.scrolling = v;
    }
    doRepeat = () => {
        if (!this.state.repeating) {
            clearTimeout(this.state.repeating);
            const delay = $$.browser.touchable ? 0 : 9;
            this.state.repeating = setTimeout(() => {
                const element = this.getCurrentElement();
                if (element) {
                    const { ariaPosInSet } = element,
                        target = this.#main.querySelector(`:scope > [aria-posinset="${ariaPosInSet}"]`);
                    this.scrollByElement(target);
                    this.state.repeating = false;
                }
            }, delay);
        }
    };

    onWheel = (e) => {
        stopEvent(e);
        this.focus({ focusVisible: true });
        const dir = e.deltaY > 0;
        this.state.scrollDir = dir;
        this.scrollTo(dir, false);
    };
    onKeyScroll = (e) => {
        const name = keyName(e, true);
        switch (name) {
            case 'ArrowUp':
            case 'ArrowDown':
                stopEvent(e);
                this.scrollTo(name === 'ArrowDown', true);
                break;
            case 'Home':
            case 'End':
                e.preventDefault();
                break;
        }
    };
    onItemClick = (e) => {
        const { currentTarget } = e;
        if (currentTarget.ariaSelected !== 'true' && currentTarget.role && !this.options.disabled) {
            if (ScrollEndSupport) this.scrolling(currentTarget.ariaPosInSet - 1);
            this.scrollByElement(currentTarget, ScrollEndSupport);
        }
    };
    onScrollEnd = (scrollBox, recursive) => {
        const { scrolling } = this.state;
        if (scrolling !== true) {
            const { scrollTop, scrollHeight, clientHeight } = scrollBox,
                topRate = scrollTop / scrollHeight,
                bottomRate = (scrollTop + clientHeight) / scrollHeight;
            if (this.state.useLoop && (topRate < 0.1 || bottomRate > 0.9)) {
                this.console.omit('Using fallback loop list.');
                this.doRepeat(); // back up for scroll observer;
            } else if (recursive) {
                this.scrollByElement(this.getCurrentElement());
            }
        }
        if (typeof scrolling === 'number') {
            this.scrollByIndex(scrolling, false);
        }
    };
    addScrollListener = () => {
        const box = this.#scrollBox,
            { element } = this;
        if (ScrollEndSupport) {
            element.addEventListener('keydown', this.onKeyScroll);
            element.addEventListener('keyup', () => {
                if (this.state.scrolling) {
                    this.scrollByElement(this.getCurrentElement());
                    this.scrolling(false);
                }
            });
            box.addEventListener('scrollend', (e) => this.onScrollEnd(e.target, true));
        } else {
            const scrollKeys = ['ArrowUp', 'ArrowDown', 'Space', 'PageUp', 'PageDown', 'Home', 'End'];
            element.addEventListener('keydown', (e) => {
                if (eventIsKey(e, scrollKeys)) e.preventDefault();
            });
            element.addEventListener('keyup', this.onKeyScroll);
            if ($$.browser.touchable) {
                const onTouchEnd = (e) => {
                    window.removeEventListener('touchend', onTouchEnd);
                    window.removeEventListener('touchcancel', onTouchEnd);
                    requestAnimationFrame(() => this.scrollByElement(this.getCurrentElement()));
                };
                element.addEventListener('pointerdown', (e) => {
                    window.addEventListener('touchend', onTouchEnd);
                    window.addEventListener('touchcancel', onTouchEnd);
                });
            }
        }
    };

    replica(list) {
        if (this.state.useLoop) {
            const [prev, next] = [list.cloneNode(true), list.cloneNode(true)];
            if ($$.browser.touchable || prev.childElementCount < 25) {
                // another to scroll more smoothly.
                const [_prev, _next] = [prev.cloneNode(true), next.cloneNode(true)];
                prev.append(..._prev.children);
                next.append(..._next.children);
            }
            return [prev, next];
        } else {
            const fillCount = Math.floor(this.options.size / 2),
                fill = <ul className="filler" aria-hidden="true" />;
            fill.append(...Array.from({ length: fillCount }, () => <li />));
            return [fill, fill.cloneNode(true)];
        }
    }
    render() {
        const { size } = this.options,
            { items, index } = this.state;
        const contents = items.map((x, i, { length }) => {
            const args = $$.arias({ role: 'option', ariaPosInSet: i + 1, ariaSetSize: length, ariaSelected: false });
            return <li {...args}>{x}</li>;
        });
        const list = <ul role="group">{contents}</ul>,
            [prev, next] = this.replica(list),
            selected = list.children[index];
        if (selected) selected.ariaSelected = true;

        return (
            <div className="loop-list" style={{ '--size': size }}>
                <div className="highlight" />
                <div id="box" role="listbox" tabIndex={0} {...this.arias()} data-scrolling="false">
                    {Object.assign(prev, { id: 'prev', ariaHidden: true })}
                    {Object.assign(list, { id: 'main', part: 'main' })}
                    {Object.assign(next, { id: 'next', ariaHidden: true })}
                </div>
                <output className="highlight" name="value" />
            </div>
        );
    }
}
