import $ from '../../core/element/index.js';

/** @type {typeof $$.event.multiClick} */
export default function multiClick(callback, num) {
    return function (e) {
        const $element = $(e),
            delay = 400;
        let count = Number($element.data('multiClickCount')) || 0;
        const done = function () {
            $element.data('multiClickCount', 0);
            const event = $element.data('multiClickEvent', undefined);
            if (num == null || num === count) callback(Object.assign(event, { clickCount: count }));
        };
        clearTimeout($element.data('multiClickTimer'));
        $element.data({ multiClickCount: ++count, multiClickEvent: $.Event(e) });
        if (num == null) {
            $element.data('multiClickTimer', setTimeout(done, delay));
        } else if (num === count) {
            done();
        } else {
            $element.data(
                'multiClickTimer',
                setTimeout(() => $element.data('multiClickCount', 0), delay)
            );
        }
    };
}
