/** @type {typeof $$.string.splitJoin} */
export default function splitJoin(val, splitter, iterator, callback) {
    const [separator, joiner] = Array.isArray(splitter) ? splitter : [splitter];
    let arr = Array.isArray(val) ? val : val.split(separator);
    if (typeof iterator === 'function') arr = arr.flatMap(iterator);
    if (typeof callback === 'function') arr = callback(arr);
    return arr.join(joiner ?? separator);
}
