const uid = {};
const acc = (v) => v.reduce((a, b) => b - 0 + a, 0);

/** @type {typeof $$.string.xid} */
export default function xid(name, length = 5) {
    if (!uid[name]) uid[name] = 1;
    const arr = String(Date.now()).split('').reverse();
    let id = uid[name]++;
    id += acc(arr) + arr.join('');
    id = id.slice(0, Math.max(length, 5));
    return name + '-' + id;
}
