import { error } from '../core/base/log.js';
import { SetAttr, BoolAttrs, LowerAttrs } from '../core/element/attr.js';
import nodeList from '../core/element/node-list.js';

export { BoolAttrs, LowerAttrs };

const SingleNames = new Set(['br', 'hr', 'img', 'input', 'param', 'meta', 'link']);
const Namespace = {
    svg: 'http://www.w3.org/2000/svg',
    math: 'http://www.w3.org/1998/Math/MathML',
};

export function createElement(name, attrs, children) {
    let element, ns, attachRef;
    if (typeof name === 'string') {
        const i = name.indexOf(':');
        if (i > -1) {
            const nsKey = name.slice(0, i);
            name = name.slice(i + 1);
            ns = Namespace[nsKey] || error('Skip error namespace', nsKey);
        }
        if (ns) {
            element = document.createElementNS(ns, name);
        } else {
            element = document.createElement(name);
        }
    } else if (name == null) {
        element = document.createDocumentFragment();
    } else {
        return error('Error tag type', name);
    }

    if (arguments.length > 3) children = Array.prototype.slice.call(arguments, 2);
    if (typeof attrs === 'string') attrs = parseStringAttr(attrs);
    if (attrs != null) {
        for (const k in attrs) {
            const v = attrs[k];
            if (k === 'ref') {
                attachRef = v;
            } else if (k === 'children') {
                if (v != null && children == null) children = v;
            } else {
                let toSet = true;
                if (k[0] !== '_' && name) {
                    toSet = !SetAttr.call(ns, element, k, v, children);
                }
                if (toSet && typeof element.setOptions === 'function') {
                    element.setAttribute(k, v);
                }
            }
        }
    }

    setChildren(element, children);
    if (name === 'slot') initSlot(element);

    if (typeof attachRef === 'function') attachRef(element);
    return element;
}

/** Parse string value as selector, mapping to className(default behavior) or id. */
function parseStringAttr(attrs) {
    const selectors = attrs.match(/(\.|\#)[\w\-]+/g);
    if (!selectors) return attrs ? { class: attrs } : null;

    const mapping = { '.': 'class', '#': 'id' },
        data = {};
    selectors.forEach((s) => {
        const k = mapping[s[0]];
        if (k) data[k] = s.slice(1);
    });
    return data;
}

function setChildren(element, children) {
    if (typeof children === 'function' && element.parseChildren) children = element.parseChildren(children); /// for what?

    const childNodes = nodeList(children);
    if (childNodes.length > 0) {
        if (SingleNames.has(element.localName)) {
            // eslint-disable-next-line unicorn/dom-node-dataset
            element.setAttribute('data-children', childNodes[0]);
            // eslint-disable-next-line no-console
            console.error('void element received children, first child stored to data-children for dev!');
        } else {
            const box = element instanceof HTMLTemplateElement ? element.content : element;
            const l = childNodes.length;
            for (let i = 0; i < l; i++) {
                const child = childNodes[i];
                if (typeof child !== 'object' || child instanceof Node) {
                    box.append(child);
                } else {
                    element.setAttribute('async', true);
                    if (!element.promises) element.promises = [];
                    const resolvers = Promise.withResolvers();
                    $$._tempInsertBridge(child, element, resolvers, { usePortal: false });
                    element.promises.push(resolvers.promise);
                }
            }
        }
    }
}

/** polyfill for slot `:has-slotted`. Chrome ≥ null; Firefox ≥ 136; Safari ≥ null */
function initSlot(element) {
    if (element.onslotchange == null) {
        element.onslotchange = (e) => {
            const slot = e.currentTarget,
                assigned = slot.assignedNodes({ flatten: true }).filter((node) => node.parentNode !== slot);
            slot.classList.toggle('assigned', !!assigned.length);
        };
    }
}
