/* eslint-disable aui/no-unsafe-regex */

function DisplayName(val) {
    if (!val?.length) return '';
    const UNWANTED_ENCLOSURES_REGEX = /[\(\[\{\<][^\)\]\}\>]*[\)\]\}\>]/g,
        UNWANTED_CHARS_REGEX = /[\0-\u001F\!-/:-@\[-`\{-\u00BF\u0250-\u036F\uD800-\uFFFF]/g,
        MULTIPLE_WHITESPACES_REGEX = /\s+/g;
    val = val.replaceAll(UNWANTED_ENCLOSURES_REGEX, '');
    val = val.replaceAll(UNWANTED_CHARS_REGEX, '');
    val = val.replaceAll(MULTIPLE_WHITESPACES_REGEX, ' ');
    val = val.trim();
    return val;
}

export function name(val, allowPhoneInitials) {
    let initials = '';
    const displayName = DisplayName(val);
    if (!displayName) return initials;
    const UNSUPPORTED_TEXT_REGEX =
            /[\u0600-\u06FF\u0750-\u077F\u08A0-\u08FF\u1100-\u11FF\u3130-\u318F\uA960-\uA97F\uAC00-\uD7AF\uD7B0-\uD7FF\u3040-\u309F\u30A0-\u30FF\u3400-\u4DBF\u4E00-\u9FFF\uF900-\uFAFF]|[\uD840-\uD869][\uDC00-\uDED6]/,
        PHONENUMBER_REGEX = /^\d+[\d\s]*(:?ext|x|)\s*\d+$/i;
    if (UNSUPPORTED_TEXT_REGEX.test(displayName) || (!allowPhoneInitials && PHONENUMBER_REGEX.test(displayName))) return initials;

    const splits = displayName.split(' ');

    if (splits.length === 2) {
        initials += splits[0].charAt(0).toUpperCase();
        initials += splits[1].charAt(0).toUpperCase();
    } else if (splits.length === 3) {
        initials += splits[0].charAt(0).toUpperCase();
        initials += splits[2].charAt(0).toUpperCase();
    } else if (splits.length !== 0) {
        initials += splits[0].charAt(0).toUpperCase();
    }

    const isRtl = $$.browser.dir === 'rtl';
    if (isRtl && initials.length > 1) {
        return initials.charAt(1) + initials.charAt(0);
    }

    return initials;
}

export function color(displayName) {
    if (!displayName?.length) return null;

    const list1 = ['#4F6BED', '#0078D4', '#004E8C', '#038387', '#498205', '#0B6A0B', '#C239B3', '#E3008C', '#881798', '#5C2E91'],
        list2 = ['#CA5010', '#D13438', '#A4262C', '#8764B8', '#986F0B', '#750B1C', '#7A7574', '#005B70', '#8E562E', '#69797E'];
    const COLOR_SWATCHES_LOOKUP = [...list1, ...list2];
    const COLOR_SWATCHES_NUM_ENTRIES = COLOR_SWATCHES_LOOKUP.length;

    let hashCode = 0;
    for (let iLen = displayName.length - 1; iLen >= 0; iLen--) {
        const ch = displayName.codePointAt(iLen),
            shift = iLen % 8;
        hashCode ^= (ch << shift) + (ch >> (8 - shift));
    }
    const color = COLOR_SWATCHES_LOOKUP[hashCode % COLOR_SWATCHES_NUM_ENTRIES];
    return color;
}
