// cSpell:ignore xlink
import $ from '../../core/element/index.js';

function cleanData(el) {
    for (const k in el.dataset) {
        const name = k.split(/(?=[A-Z])/).join('-');
        el.removeAttribute('data-' + name.toLowerCase());
    }
}

/** @type {typeof $$.img.svgClean} */
export default function svgClean(svg) {
    const $svg = $(svg);
    cleanData(svg);
    $svg.findAll(':data').forEach(cleanData);
    svg.removeAttribute('xmlns:xlink');
    svg.removeAttribute('style');
    svg.removeAttribute('role');
    $svg.findAll('title').remove(); // svg title only for A11Y
    $svg.findAll('style').remove();
    $svg.findAll('[class]').attrs('class', undefined); /// Un-confirm effects.
    $svg.findAll('use').forEach(function (el) {
        const id = el.getAttribute('xlink:href') || el.getAttribute('href'),
            x = el.getAttribute('x'),
            y = el.getAttribute('y');
        let def = $svg.find(id).get() || $(id).get(),
            transform = el.getAttribute('transform') || '';
        if (def) {
            def = def.cloneNode(true);
            if (x && y) transform = (transform ? transform + ' ' : '') + 'translate(' + [x, y].join(',') + ')';
            if (transform) def.setAttribute('transform', transform);
            el.replaceWith(def);
        }
    });
    $svg.findAll('defs').remove();
    $svg.find('[id]').attrs('id', undefined);
    return svg;
}
