/** @jsxImportSource @gui/aui-devops */
import { define, Widget, Types } from '../../../widget/widget.js';

import { NS } from './utils.js';

import style from './identifier.less';

const identifierName = `${NS}-identifier`;
export const IdentifierNode = 'aui-' + identifierName;

/** @extends {Widget<typeof Identifier.options>} */
@define(identifierName)
export class Identifier extends Widget {
    static options = {
        type: Types.Enum(['rect', 'circle', 'solid', 'dashed'], 'rect'),
        name: Types.string,
        color: Types.string,
        value: Types.number,
        val: Types.string, // formatted value
        source: Types.string,
    };
    static observers = ['type', 'name', 'color', 'value', 'val', 'source'];
    static styles = style;

    init() {
        this.state = {
            overflow: !!this.host.dataset.tooltip,
        };
    }
    render() {
        const { type, name, color, value, val } = this.options,
            { overflow } = this.state,
            style = color ? { color } : {},
            displayValue = val ?? value;
        return (
            <dl>
                <dd className={['color', type]} style={style} />
                <dt className={['name', overflow && 'overflow']}>{name}</dt>
                <dd className="value empty-hidden">{displayValue}</dd>
            </dl>
        );
    }
}
