/** @jsxImportSource @gui/aui-devops */
import { define, Widget, Types } from '../../../widget/widget.js';

import minmax from '../../../util/css/minmax.js';

import { NS, TagObject } from './utils.js';

import style from './box.less';

/** @extends {Widget<typeof Charts.options>} */
@define(NS)
export class Charts extends Widget {
    static options = {
        height: Types.Lengths,
        justifyAlign: Types.Enum(['stretch', 'start'], 'stretch'),
        callbackGroupData: false,
        onDataClick: Types.function,
        onSeriesClick: Types.function,
    };
    static observers = ['height'];
    static styles = style;
    static unicomRealm = 'box';

    init() {
        this.state = {
            boxStyles: { ...this.parseHeight(this.options.height) },
        };
        this.useUnicom(['box', 'box'], this.dataReceiver);
    }
    setOption(name, value, oldValue) {
        if (name === 'height') {
            const styles = this.parseHeight(value);
            this.boxStyle(styles);
            return false;
        }
    }

    parseHeight(height) {
        return minmax('height', height);
    }
    callbackDataArgs(value) {
        if (!this.options.callbackGroupData || $$.getClassBuiltIn(value) === 'ChartItemGroup') return value;
        return TagObject('ChartItemGroup', { group: undefined, values: [].concat(value) });
    }
    boxStyle(style) {
        Object.assign(this.state.boxStyles, style);
        const box = this.shadowRoot.querySelector('.box');
        Object.assign(box.style, this.state.boxStyles);
    }
    dataReceiver = (action, from, ...args) => {
        const arg = args[0];
        switch (action) {
            case 'boxStyle':
                return this.boxStyle(arg);
            case 'onDataClick':
                return this.callback('onDataClick', this.callbackDataArgs(arg));
            case 'onSeriesClick':
                return this.callback('onSeriesClick', this.callbackDataArgs(arg));
            case 'getCallback':
                return { onDataClick: this.options.onDataClick, onSeriesClick: this.options.onSeriesClick };
        }
    };

    render() {
        const { justifyAlign } = this.options,
            { boxStyles } = this.state;
        return (
            <div className={['chart', 'justify-' + justifyAlign]}>
                <slot className="block" name="block-start" />
                <slot className="inline" name="inline-start" />
                <slot className="box" role="graphics-document" style={boxStyles} />
                <slot className="inline" name="inline-end" />
                <slot className="block" name="block-end" />
            </div>
        );
    }
}
