import { error } from '../../core/base/log.js';

/** @type {typeof $$.css.replaceSheet} */
export default function replaceSheet(sheet, styles) {
    if (!sheet) return error('Invalid style sheet!');
    while (sheet.cssRules.length) {
        sheet.deleteRule(0);
    }
    if (Array.isArray(styles)) styles.forEach((r) => sheet.insertRule(r));
}
