/** @jsxImportSource @gui/aui-devops */
import $ from '../../core/element/index.js';
import { addTooltip } from '../../core/module/tooltip.js';
import { define, Widget, Types } from '../../widget/widget.js';

import arrayLoop from '../../util/array/loop.js';
import swipe from '../../util/event/swipe.js';

import itemStyle from './item.less';
import style from './style.less';

const Orient = { h: 'horizontal', v: 'vertical' };

/** @extends {Widget<typeof Tabbutton.options>} */
@define('tabbutton')
export class Tabbutton extends Widget {
    static options = {
        active: 0,
        average: false,
        block: false,
        count: Types.number,
        disabled: false,
        items: Types.array,
        orient: Types.Enum(['h', 'v'], 'h'),
        onChange: Types.function,
    };
    static styles = style;
    static observers = ['active', 'disabled', 'items', 'count'];

    init() {
        this.state = {
            active: this.options.active,
        };
    }
    didMount() {
        addTooltip(this.host);
        this.$element.on('change', 'input[type=radio]', this.onChange);
        swipe(this.element, this.options.orient, this.onSwipe);
    }
    onSwipe = (e, offset, orient) => {
        if (!this.options.disabled) {
            const { active } = this.state;
            let index;
            if (offset > 0) {
                const { length } = $(e.currentTarget).children(null, { crossSlot: true });
                index = Math.min(length - 1, active + 1);
            } else {
                index = Math.max(0, active - 1);
            }
            if (index !== active) this.onChangeCallback(index);
        }
    };
    setOption(name, value, oldValue) {
        switch (name) {
            case 'active':
                this.setState({ active: value });
                return false;
            case 'items':
            case 'count':
                this.setState({ active: this.options.active }, false);
                return true;
        }
    }
    onChange = (e) => {
        const value = Number(e.target.value);
        this.onChangeCallback(value);
    };
    onChangeCallback(index) {
        this.setState({ active: index });
        this.callback('onChange', index);
    }
    item(disabled, active, index, item, children) {
        const checked = active === index;
        return (
            <label className="item" data-tooltip="diffneed" data-tooltip-reference="slot[name='tooltip']">
                <input type="radio" name="tabbutton" role="tab" value={index} disabled={disabled} checked={checked} aria-selected={checked} />
                <slot name={index}>{children}</slot>
            </label>
        );
    }
    items(disabled) {
        const { items, count } = this.options,
            { active } = this.state;
        if (Array.isArray(items)) {
            return items.flatMap((item, i) => {
                if (!item) return [];
                if (typeof item === 'string') item = { text: item };
                return this.item(disabled, active, i, item, <aui-tabbutton-item icon={item.icon} text={item.text} tooltip={item.tooltip} />);
            });
        } else if (count > 0) {
            return arrayLoop(count, (i) => this.item(disabled, active, i));
        }
        return this.console.warn('Item source invalid, did you forget to set items or count property?');
    }
    render() {
        const { average, block, disabled, orient } = this.options,
            arias = this.arias({ ariaDisabled: disabled, ariaOrientation: Orient[orient] });
        return (
            <div id="box" className={[average && 'average', block && 'block']} role="tablist" {...arias}>
                {this.items(disabled)}
            </div>
        );
    }
}

/** @extends {Widget<typeof TabbuttonItem.options>} */
@define('tabbutton-item')
export class TabbuttonItem extends Widget {
    static options = {
        icon: Types.string,
        text: Types.string,
        tooltip: Types.string,
    };
    static styles = itemStyle;
    static observers = ['icon', 'text', 'tooltip'];

    render() {
        const { icon, text, tooltip } = this.options;
        return (
            <>
                <slot name="icon">{icon && <div className={['icon', this.fontIcon(icon)]} />}</slot>
                <slot name="text">{text && <aui-bold className="content text-overflow">{text}</aui-bold>}</slot>
                <slot name="tooltip" data-tooltip="scope">
                    <div className="sr-only empty-hidden">{tooltip}</div>
                </slot>
            </>
        );
    }
}
