class ZIndexManager {
    #mapping = new Map();
    acc = 0;
    constructor(type) {
        this.min = cssZindex(type, 'min');
        this.max = cssZindex(type, 'max');
    }
    push(host) {
        this.acc++;
        const value = numberClamp(this.min, this.min + this.acc, this.max);
        this.#mapping.set(host, value);
        return value;
    }
    pop(host) {
        this.acc = Math.max(0, this.acc - 1);
        this.#mapping.delete(host);
    }
    setIndex(host, value) {
        host.setState({ zIndex: value }, true);
        this.#mapping.set(host, value);
    }
    switch(host, current) {
        const mapping = this.#mapping;
        if (mapping.size > 1) {
            const [...values] = mapping.values(),
                max = Math.max(...values);
            for (const [h, z] of mapping) {
                if (h === host) {
                    this.setIndex(h, max);
                } else if (z > current) {
                    this.setIndex(h, z - 1);
                }
            }
        }
    }
}
