/* eslint-disable aui/no-direct-$$ */
/** @jsxImportSource @gui/aui-devops */
import { callbackResult } from '../../core/base/internal.js';
import { warn } from '../../core/base/log.js';
import { widget } from '../../core/extend/widget.js';

import '../button/button.js';
import '../icon/icon.js';
import '../popup/popup.js';

(function () {
    const noop = $$.fn();
    let uuid = -1;
    const _constant = {
        AUI_WIDGET: 'aui-widget',
        COMBOBOXSHELL_CLASS: 'aui-comboboxshell',
        EDITABLE_CLASS: 'editable',
        ELLIPSIS_CLASS: 'aui-comboboxshell-ellipsis',
        COMBOBOXSHELL_FLEX_CLASS: 'aui-comboboxshell-flex',
        COMBOBOXSHELL_CONTAINER_CLASS: 'aui-comboboxshell-container',
        POPUP_CONTAINER_CLASS: 'aui-comboboxshell-popup-container',
        CONTENT_CLASS: 'aui-comboboxshell-content',
        INPUT_CLASS: 'aui-comboboxshell-input',
        ICON_BOX_CLASS: 'aui-comboboxshell-icon-box',
        ICON_CLASS: 'aui-comboboxshell-icon',
        ICON_DOWN_CLASS: 'aui-comboboxshell-icon-down',
        ICON_CLEAR_CLASS: 'aui-comboboxshell-icon-clear',
        POPUP_CLASS: 'aui-comboboxshell-popup',
        FOOTER_CLASS: 'aui-comboboxshell-footer',
        BUTTON_CLASS: 'aui-comboboxshell-button',
        LEFT_CLASS: 'aui-comboboxshell-left',
        RIGHT_CLASS: 'aui-comboboxshell-right',
        SELECTED_CLASS: 'aui-comboboxshell-selected',
        MINI_CLASS: 'aui-comboboxshell-mini',
        COMPACT_CLASS: 'aui-comboboxshell-compact',
        CENTER_CLASS: 'aui-comboboxshell-center',
        CLEAR_CLASS: 'aui-comboboxshell-clear',
        CLEAR_DISABLED_CLASS: 'aui-comboboxshell-clear-disabled',
        CLEAR_TOUCH_CLASS: 'aui-comboboxshell-clear-touch',
        CLEAR_DISABLED_TOUCH_CLASS: 'aui-comboboxshell-clear-disabled-touch',
        CLEAR_ICON_CLASS: 'faui-close-circle',
        INPUT_HIDDEN_CLASS: 'aui-comboboxshell-input-hidden',
        ICON_CLEAR_TOOLTIP: 'aui-comboboxshell-icon-clear-tooltip',
    };
    const attr = {
        tooltip: 'data-tooltip',
        label: 'aria-label',
        expanded: 'aria-expanded',
    };

    if ($$.mobileView && $$.browser.touchable) {
        // filter group scrollTo by touch on touchable env.
        $$.event.touch(document.body, '.aui-filter-group>.aui-comboboxshell', (e) => $$.scrollTo(e.currentTarget, { bubbles: false, inline: false }));
    }

    widget('aui5.comboboxshell', {
        section: true,
        options: {
            // Displays content within the control
            content: undefined,
            // If the control is a block, the default is inline-block
            block: false,
            // The icon on the right, ClassName, defaults to the lower triangle
            icon: 'faui-caret-down',
            // Width of the control, width: width/[width]/[minWidth, maxWidth]/[minWidth, width, maxWidth]
            width: undefined,
            // Control height, height: height/[height]/[minHeight, maxHeight]/[minHeight, height, maxHeight]
            height: undefined,
            // Control disabled
            disabled: false,
            // There are three types of popup triggered by clicking on content: "All" (click on the whole Content), "icon" (click on icon), and "None" (not triggered, can be triggered by custom)
            triggerType: 'all',
            // button
            // Object can contain properties such as name (button text), title, disabled, onClick (click event), className (button class separated by Spaces), where name and onClick must be set
            // When return false inside the onClick callback, the hiding will be prevented from being closed, and the willHide/ onHide callback method will be called upon success
            buttons: [],
            // The minimalist model
            mini: false,
            // Compact model
            compact: false,
            tooltip: undefined,
            aria: undefined,
            clearable: false,
            placeholder: '',
            editable: false,
            readonly: true,
            // The width of the popup is '100%', the same width as the ofElement
            popupWidth: 'auto',
            popupMinWidth: '100%',
            // Set the maximum width of the popup
            popupMaxWidth: 'auto',
            // Height of popup
            popupHeight: 'auto',
            // Maximum height of popup
            popupMaxHeight: 'auto',
            // Popup control status
            status: { show: false },
            // Set popup's Z-index, which is not recommended except in special cases
            zIndex: $$.css.zindex('popup', 'extend'),
            // When set to true, after popup displays and focuses, the focus will be moved to the element (of or ofElement) that triggers the popup display, for example, if the trigger element is input.
            focusBack: false,
            // Whether to disable Popup overall situation close monitor
            offClose: false,
            // Whether to bind events (for internal use only)
            dynamicSize: false,
            title: '',
            // for richcombobox
            hasPopup: true,
            willShow: noop,
            onShow: noop,
            willHide: noop,
            onHide: noop,
            onIcon: noop,
            onClear: noop,
            hasEvent: true,
            buttonEvent: true,
            customTrigger: false,
        },
        _create: function () {
            this.section = !this.options.mini;
            this._initId()._initMembers()._createComboboxshell()._updateComboboxshell()._updateDisabled()._updateClear()._initEvent();
            if (this.options.hasPopup === true) {
                this._createPopup()._updatePopup()._updateButtons();
            }
        },
        _initId: function () {
            this._uuid = ++uuid;
            this.comboboxshellId = this.$element.attr('id') || 'aui_comboboxshell_' + uuid;
            this.contentId = 'aui_comboboxshell_content_' + uuid;
            this.iconBoxId = 'aui_comboboxshell_box_icon_' + uuid;
            this.iconId = 'aui_comboboxshell_icon_' + uuid;
            this.clearIconId = 'aui_comboboxshell_clear_icon_' + uuid;
            this.popupId = 'aui_comboboxshell_popup_' + this.comboboxshellId;
            this.buttonContainerId = 'aui_comboboxshell_footer_' + uuid;
            return this;
        },
        _initMembers: function () {
            this.isShow = false;
            this.clearable = this.options.clearable;
            this.clearTooltip = '';
            this.editable = !$$.browser.touchable && this.options.editable && !this.options.readonly;
            this.$flex = jQuery(<div className={_constant.COMBOBOXSHELL_FLEX_CLASS} />);
            this.$content = jQuery(<div className={_constant.CONTENT_CLASS} id={this.contentId} />);
            this.$iconBox = jQuery(<div className={_constant.ICON_BOX_CLASS} id={this.iconBoxId} />);
            this.$input = jQuery(
                <input
                    className={[_constant.INPUT_CLASS, this.options.editable ? '' : _constant.INPUT_HIDDEN_CLASS]}
                    type="text"
                    autoComplete="off"
                    tabIndex={this.editable ? 0 : -1}
                    aria-hidden={!this.editable}
                    placeholder={this.options.placeholder}
                    readOnly={!this.editable}
                />
            );
            this.$icon = jQuery(<aui-icon />);
            this.$popup = jQuery(
                <div className={_constant.POPUP_CLASS} id={this.popupId}>
                    <div className={_constant.COMBOBOXSHELL_CONTAINER_CLASS}>
                        <div className={_constant.POPUP_CONTAINER_CLASS} />
                    </div>
                    <div className={_constant.FOOTER_CLASS} id={this.buttonContainerId}>
                        <div className={_constant.LEFT_CLASS} />
                        <div className={_constant.RIGHT_CLASS} />
                    </div>
                </div>
            );
            this.$popupContent = this.$element.children();
            return this;
        },
        _createComboboxshell: function () {
            const options = this.options;
            if (options.aria) {
                this.$element.attr($$.arias(options.aria));
            }
            this.$element.attr({
                role: 'combobox',
                'aria-controls': this.popupId,
                // 'aria-describedby': this.contentId,
            });
            this.$flex.append(this.$input);
            this.$element.append(this.$flex);
            if (options.customTrigger === false) {
                let icon = false,
                    tooltip = false;
                if (options.icon.constructor === Object) {
                    icon = options.icon.className;
                    tooltip = options.icon.tooltip;
                } else if (typeof options.icon === 'string') {
                    icon = options.icon;
                }
                if (!this.options.editable) {
                    this.$flex.append(this.$content);
                }
                if (icon === false) {
                    this.$content.css('paddingRight', 'var(--gap-s)');
                } else {
                    const settings = {
                        class: [_constant.ICON_CLASS, _constant.ICON_DOWN_CLASS],
                        id: this.iconId,
                        role: 'button',
                        [attr.label]: tooltip && tooltip.length > 0 ? tooltip : $$.I18N.comboboxshell.dropdown,
                        icon: icon,
                        [attr.tooltip]: tooltip && tooltip.length > 0,
                    };
                    this.$icon = jQuery(<aui-icon {...settings} />);
                    this.$iconBox.append(this.$icon);
                    this.$flex.append(this.$iconBox);
                }
            } else {
                this.$flex.append(options.customTrigger);
            }

            if (options.customTrigger === false) {
                this.setContent(options.content);
            }

            return this;
        },
        _createPopup: function () {
            const options = this.options;

            this.$element.append(this.$popup);
            this.$footer = this.$popup.find('.' + _constant.FOOTER_CLASS);
            const $popupContainer = this.$popup.find('.' + _constant.POPUP_CONTAINER_CLASS);
            this.$leftBox = this.$footer.find('.' + _constant.LEFT_CLASS);
            this.$rightBox = this.$footer.find('.' + _constant.RIGHT_CLASS);
            if (this.$popupContent.length > 0 && options.customTrigger === false) {
                $popupContainer.append(this.$popupContent);
            } else {
                $popupContainer.append(jQuery('#' + this.$element.data('popupid')).children());
            }

            return this;
        },
        _getElementSize: function (type, size) {
            const obj = {};

            if (Array.isArray(size)) {
                if (size.length === 1) {
                    if (size[0]) obj[type] = size[0];
                } else if (size.length === 2) {
                    if (size[0]) obj['min-' + type] = size[0];
                    if (size[1]) obj['max-' + type] = size[1];
                } else if (size.length === 3) {
                    if (size[0]) obj['min-' + type] = size[0];
                    if (size[1]) obj[type] = size[1];
                    if (size[2]) obj['max-' + type] = size[2];
                }
            } else if (size) {
                obj[type] = size;
            }

            return obj;
        },
        _updatePopup: function () {
            const options = this.options;

            this.$element.attr({
                [attr.expanded]: false,
                'aria-haspopup': 'dialog',
            });

            const size = this._getSize(),
                settings = {
                    zIndex: options.zIndex,
                    ofElement: options.customTrigger === false ? this.$element : options.customTrigger,
                    of: options.triggerType === 'all' ? this.$element : options.triggerType === 'icon' ? this.$icon : null,
                    width: size.width,
                    minWidth: size.minWidth,
                    maxWidth: size.maxWidth,
                    height: size.height,
                    maxHeight: size.maxHeight,
                    status: { show: options.status.show },
                    offClose: options.offClose,
                    focusBack: options.focusBack,
                    dynamicSize: options.dynamicSize,
                    willShow: () => {
                        this._onUpdate();
                        return options.willShow();
                    },
                    willHide: () => {
                        return options.willHide();
                    },
                    onShow: this._show.bind(this),
                    onHide: this._hide.bind(this),
                    buttons: options.buttons,
                    title: options.title,
                    className: options.className,
                    closeable: 'mobile',
                };

            this.$popup.popup(settings);
            this.$popup.attr({ role: 'dialog' });

            return this;
        },
        _updateComboboxshell: function () {
            const options = this.options,
                editClass = this.editable ? _constant.EDITABLE_CLASS : '';
            if (this.$element.attr('id')) {
                this.comboboxshellId = this.$element.attr('id');
            } else {
                this.$element.attr('id', this.comboboxshellId);
            }

            if (options.customTrigger === false) {
                const style = {
                    display: options.block ? 'block' : 'inline-block',
                    ...this._getElementSize('width', options.width),
                    ...this._getElementSize('height', options.height),
                };
                this.$element.addClass([_constant.AUI_WIDGET, _constant.COMBOBOXSHELL_CLASS, editClass]).css(style);
                if (options.mini === true) this.$element.addClass(_constant.MINI_CLASS);
                if (options.compact === true) this.$element.addClass(_constant.COMPACT_CLASS);
                if (options.icon.constructor === Object || typeof options.icon === 'string') {
                    this.$icon.height(this.$element.height() - (options.mini === true ? 1 : 2));
                }
            } else {
                this.$element.css({
                    display: 'contents',
                });
            }

            return this;
        },
        _updateClear: function () {
            const options = this.options,
                icon = options.icon,
                clearable = this.clearable;

            if (icon !== false && options.triggerType !== 'icon') {
                const clearClass = _constant.CLEAR_CLASS,
                    clearDisabledClass = _constant.CLEAR_DISABLED_CLASS;
                if (this.isShow === true || clearable === false) {
                    const $clearIcon = this.$element.find('#' + this.clearIconId);
                    this.$element.removeClass(clearClass);
                    this.$element.removeClass(clearDisabledClass);
                    if ($clearIcon && $clearIcon.length > 0) $clearIcon.remove();
                } else if (clearable === true || clearable === 'disabled') {
                    const ariaLabel = this.clearTooltip.length > 0 ? this.clearTooltip : $$.I18N.comboboxshell.clear;
                    let $clearIcon = this.$element.find('#' + this.clearIconId);
                    if (this.$element.find('#' + this.clearIconId).length === 0) {
                        $clearIcon = jQuery(
                            <aui-icon
                                className={[_constant.ICON_CLASS, _constant.ICON_CLEAR_CLASS]}
                                id={this.clearIconId}
                                role="button"
                                icon={_constant.CLEAR_ICON_CLASS}
                                data-interactive="focusable"
                                {...{ [attr.tooltip]: true, [attr.label]: ariaLabel }}
                            />
                        );
                        this.$icon.after($clearIcon);
                    } else {
                        $clearIcon.attr(attr.label, ariaLabel);
                    }
                    $clearIcon.removeAttr('aria-description');
                    this.$element.removeClass(clearDisabledClass);
                    if (!this.$element.hasClass(clearClass)) this.$element.addClass(clearClass);

                    $clearIcon.on('click', (e) => {
                        e.stopPropagation();
                        if (this.clearable === true) this._callback('onClear');
                    });
                    $clearIcon.height(this.$element.height() - (options.mini === true ? 1 : 2));

                    if (clearable === 'disabled') {
                        if (!this.$element.hasClass(clearDisabledClass)) this.$element.addClass(clearDisabledClass);
                    }
                    if (!this.$element.hasClass(clearDisabledClass) && this.$element.find(':read-write').length === 0) {
                        $clearIcon.attr({ 'aria-description': $$.I18N.comboboxshell.clearIconLabel });
                    }
                }
            }

            return this;
        },
        _getSize: function () {
            const options = this.options;

            return {
                width: options.popupWidth === '100%' ? this.$element.outerWidth() : options.popupWidth,
                minWidth:
                    options.popupWidth === 'auto'
                        ? options.popupMinWidth === '100%'
                            ? this.$element.outerWidth()
                            : options.popupMinWidth
                        : options.popupWidth === '100%'
                          ? this.$element.outerWidth()
                          : options.popupWidth,
                maxWidth: options.popupMaxWidth,
                height: options.popupHeight,
                maxHeight: options.popupMaxHeight,
            };
        },
        _initEvent: function () {
            if (this.options.triggerType !== 'none' && this.options.hasEvent === true) {
                this._on(this.options.triggerType === 'all' || this.options.customTrigger !== false ? this.$element : this.$icon, this._handleEvent(true));

                this._on(this.$element, {
                    keydown: function (e) {
                        const target = e.target;
                        if ($$.event.isKey(e, 'Backspace') || $$.event.isKey(e, 'Delete')) {
                            if (this.editable && target === this.$input.get(0)) {
                                return;
                            }
                            if (this.isShow !== true && this.clearable === true && (this.options.triggerType === 'all' || this.options.customTrigger !== false))
                                this._callback('onClear');
                        }
                    },
                });
            } else {
                this._on(this.$icon, this._handleEvent(false));
            }

            this.$element.on('Update', this._onUpdate.bind(this));

            return this;
        },
        _handleEvent(toggle) {
            return {
                click: function (e) {
                    e.stopPropagation();
                    this._callback('onIcon');
                    if (this.editable) {
                        if (!this.isShow) {
                            this.show();
                        }
                    } else if (toggle) {
                        this.popupToggle();
                    }
                },
                keydown: function (e) {
                    if ($$.event.isKey(e, 'Escape')) {
                        // ESC
                        e.stopPropagation();
                        this._callback('onIcon');
                        this.hide();
                    } else if ($$.event.isKey(e, 'Enter')) {
                        // Enter
                        this._callback('onIcon');
                        if (!this.isShow) {
                            this.show();
                        }
                    }
                },
            };
        },
        _onUpdate: function () {
            const size = this._getSize();

            this.$popup.css({
                width: size.width,
                'min-width': size.minWidth,
                'max-width': size.maxWidth,
                height: size.height,
                'max-height': size.maxHeight,
            });

            if (this.options.customTrigger === false) {
                if (this.options.icon.constructor === Object || typeof this.options.icon === 'string') {
                    this.$icon.height(this.$element.height() - (this.options.mini === true ? 1 : 2));
                }
            }

            this._updateClear();
        },
        _updateDisabled: function () {
            const disabled = this.options.disabled,
                $element = this.options.triggerType === 'all' || this.options.customTrigger !== false ? this.$element : this.$icon;

            if (disabled) {
                this.$element.addClass('disabled').attr({
                    disabled: disabled,
                    'aria-disabled': disabled,
                });

                $element.removeAttr('tabindex');
            } else {
                this.$element.removeClass('disabled').removeAttr('disabled');
                this.$element.attr({ 'aria-disabled': disabled });
                $element.attr({ tabindex: this.editable ? '-1' : '0' });
            }
            this.$input.prop('disabled', disabled);
            this._updateTooltip();
            return this;
        },
        _updateTooltip: function () {
            const disabled = this.options.disabled;
            const label = typeof disabled === 'string' ? disabled : this.options.tooltip !== undefined && this.options.tooltip;
            if (label) {
                this.$element.attr({ [attr.label]: label, [attr.tooltip]: true });
            } else {
                const content = this.options.content;
                if (this.options.customTrigger === false && content) {
                    if (typeof content === 'string' || typeof content === 'number') {
                        content ? this.$element.attr(attr.tooltip, this.options.tooltip === undefined ? 'ifneed' : 'diffneed') : this.$element.removeAttr(attr.tooltip);
                    }
                }
            }
        },
        _updateButtons: function (value) {
            const buttons = value || this.options.buttons;
            if (Array.isArray(buttons)) {
                const $rightBox1 = jQuery('<div class="first"/>');
                const $rightBox2 = jQuery('<div class="second" />');
                this.$leftBox.empty();
                this.$rightBox.empty().append($rightBox1).append($rightBox2);
                this.$popup.popup('option', 'buttons', buttons);
                let showable = true;
                buttons.forEach((item, index) => {
                    const onClick = item.onClick,
                        button = { ...item, onClick: undefined, name: item.name || item.text };
                    button.onClick = (e) => {
                        if (typeof onClick === 'function') {
                            callbackResult(onClick(e), (val) => {
                                if (val !== false && this.options.buttonEvent === true) this.popupToggle();
                            });
                        }
                    };
                    button.name = button.name?.toLowerCase();
                    if (button.direction === 'start') {
                        this.$leftBox.append(<aui-button {...button} direction={null} />);
                    } else {
                        if (button.name !== 'cancel' && showable) {
                            showable = false;
                            button['data-show'] = false;
                        }
                        if (button.name === 'cancel' || button['data-show'] === false) {
                            $rightBox1.append(<aui-button {...button} />);
                        } else {
                            $rightBox2.append(<aui-button {...button} />);
                        }
                    }
                });
            } else {
                warn('[comboboxshell]', 'Bad buttons argument');
            }

            return this;
        },
        _show: function () {
            const element = this.$element;

            this.options.status.show = true;
            this.isShow = true;
            this.addSelectedClass();
            this.$element.attr(attr.expanded, true);
            this._updateClear();
            this._callback('onShow', element);
        },
        _hide: function () {
            const element = this.$element;

            this.isShow = false;
            this.removeSelectedClass();
            this.$element.attr(attr.expanded, false);
            this._updateClear();
            this._callback('onHide', element);
        },
        _setOption: function (key, value) {
            const oldValue = this.options[key];
            if (value === oldValue) return false;
            this.options[key] = value;
            switch (key) {
                case 'buttons':
                    this._updateButtons(value);
                    break;
                case 'content':
                    if (this.options.customTrigger === false) this.setContent(value);
                    break;
                case 'disabled':
                    this._updateDisabled();
                    break;
                case 'status':
                    this.$popup.popup('option', 'status', { show: value.show });
                    break;
                case 'focusBack':
                case 'offClose':
                    this.$popup.popup('option', key, value);
                    break;
                case 'clearable':
                    this.clearable = value;
                    this._updateClear();
                    break;
                case 'title':
                    this.$popup.popup('option', 'title', this._isPopMobile() === true ? value : '');
                    break;
                default:
                    break;
            }
        },
        _isPopMobile: function () {
            return $$.mobileView && $$.browser.touchable;
        },
        getPopupElement: function () {
            return this.$popup;
        },
        popupToggle: function () {
            this.$popup.popup('toggle');
        },
        show: function () {
            this.$popup.popup('show');
        },
        hide: function () {
            this.$popup.popup('hide');
        },
        setContent: function (content) {
            let $content = this.$content;
            if (this.options.editable) {
                $content = this.$input;
                $content.attr('value', content);
                $content.val(content);
            } else {
                if (this.options.customTrigger === false && content) {
                    if (typeof content === 'string' || typeof content === 'number') {
                        $content.addClass(_constant.CENTER_CLASS).addClass(_constant.ELLIPSIS_CLASS);
                        $content.empty();
                        $content.append(<div />);
                        $content.children().eq(0).text(content);
                    } else {
                        $content.removeClass(_constant.CENTER_CLASS).removeClass(_constant.ELLIPSIS_CLASS);
                        $$.renderTemplate(content, {}).then((element) => {
                            this.$content.empty();
                            this.$content.append(element);
                        });
                    }
                }
            }

            let icon = false,
                tooltip = false;
            if (this.options.icon.constructor === Object) {
                icon = this.options.icon.className;
                tooltip = this.options.icon.tooltip;
            } else if (typeof this.options.icon === 'string') {
                icon = this.options.icon;
            }
            if (icon !== false) {
                this.$icon.attr(attr.label, tooltip && tooltip.length > 0 ? tooltip : $$.I18N.comboboxshell.dropdown);
                if (tooltip) this.$icon.attr(attr.tooltip, true);
            }
            this._updateTooltip();
            if (this.options.tooltip !== undefined) {
                $content.attr(attr.label, this.options.tooltip);
            }
        },
        setPopupContent: function (content) {
            this.$popup
                .find('.' + _constant.POPUP_CONTAINER_CLASS)
                .empty()
                .append(content);
        },
        addSelectedClass: function () {
            if (!this.$element.hasClass(_constant.SELECTED_CLASS)) this.$element.addClass(_constant.SELECTED_CLASS);
        },
        removeSelectedClass: function () {
            this.$element.removeClass(_constant.SELECTED_CLASS);
        },
        setClear: function (items, disabledField) {
            let isArray = Array.isArray(items);
            if (!isArray && items?.constructor === Object) {
                isArray = true;
                items = [items];
            }

            let length = 0,
                disabledLength = 0;
            if (isArray) {
                length = items.length;
                for (const _item of items) {
                    if (_item[disabledField] === true) disabledLength++;
                }
            }

            if (items === true || (isArray && items.length > 0 && length > disabledLength)) {
                this.clearable = true;
                this.clearTooltip = items === true || disabledLength === 0 ? $$.I18N.comboboxshell.clear : $$.I18N.comboboxshell.disableClearXSkip;
            } else if (items === false || items === undefined || items === null || (isArray && items.length < 1)) {
                this.clearable = false;
                this.clearTooltip = '';
            } else if (isArray && items.length > 0 && length === disabledLength) {
                this.clearable = 'disabled';
                this.clearTooltip = items.length === 1 ? $$.I18N.comboboxshell.disableClear : $$.I18N.comboboxshell.disableClearX;
            }

            this._updateClear();

            return this;
        },
        _destroy: function () {
            const instance = this.$popup.popup('instance');
            instance._destroy();
        },
    });
})();
