import getValue from '../css/get-value.js';

import { distance } from './_touch.js';

const MaxMoveDistance = Number.parseFloat(getValue('--widget-height-m')) / 2;

/** @type {typeof $$.event.pointerValid} */
export default function pointerValid(e1, e2, limit = MaxMoveDistance) {
    return distance(e1, e2) < limit;
}
