import React from 'react';

import { UIComponent } from '../../core/base/component.jsx';
import { error } from '../../core/base/log.js';

let deprecatedThrown = false;
export class Expander extends UIComponent {
    widgetName = 'expander';

    static defaultProps = {
        status: { show: false },
        lazyLoad: true,
    };
    componentCreate() {
        if (!deprecatedThrown) error('Expander is deprecated, please use Accordion instead.');
        deprecatedThrown = true;
        this.state = {
            shown: this.props.status.show,
        };
    }
    componentInit() {
        if (this.$element) this.$element.on('willShow', () => this.setState({ shown: true }));
    }
    render() {
        const { lazyLoad, children } = this.props,
            body = children.length === 2 ? children[1] : children;
        /**
         * Because the dom has changed in widget, so need to re-render the same node to avoid losing parent-child relationship.
         * Otherwise, it will throw error when changing: `Failed to execute 'removeChild' on 'Node': The node to be removed is not a child of this node.`
         */
        const BodyTag = body.type;
        return (
            <div ref={this.ref}>
                {children[0]}
                {!lazyLoad || this.state.shown ? body : <BodyTag />}
            </div>
        );
    }
}

$$.shell.define('Expander', Expander);
