import { error, throws } from '../../core/base/log.js';

import { isSucceedStatus, parseHeaders, useAbort } from './utils.js';
import { xhrUpload } from './xhr.js';

const DefaultOptions = {
    pretreat: 'json',
    useTimezone: false,
    timeout: null,
};

function fetchRequest(method, url, data, args) {
    const { pretreat, ..._args } = args || {},
        { headers, timeout, useTimezone, ..._options } = { ...DefaultOptions, ..._args };
    const abortError = (msg) => new DOMException(msg, 'AbortError'),
        controller = new AbortController();
    const options = {
        ..._options,
        method,
        signal: controller.signal,
        headers: {
            Accept: 'application/json',
            ...parseHeaders({ useTimezone }),
        },
    };
    if (data) {
        const dataType = $$.getClassBuiltIn(data);
        if (dataType !== 'FormData') {
            options.headers['Content-Type'] = 'application/json';
            if (dataType !== 'String') data = JSON.stringify(data);
        }
        options.body = data;
    } else {
        delete options.body;
    }
    Object.assign(options.headers, headers);

    let callback = pretreat;
    if (typeof callback !== 'function') {
        let _type = typeof pretreat === 'string' ? pretreat : null;
        callback = function (res) {
            let errorMessage;
            if (isSucceedStatus(res.status)) {
                try {
                    if (!res[_type]) _type = 'json';
                    return res[_type]();
                } catch (e) {
                    errorMessage = e;
                    error(`Convert data ${_type ? `to ${_type}` : ''} failed`, errorMessage);
                }
            } else {
                errorMessage = res.statusText;
                error('Request failed, status code: ' + res.status, errorMessage);
            }
            throw new Error(errorMessage);
        };
    }

    const abort = (reason) => controller.abort(abortError(reason ?? 'User aborted a request.'));
    let timer;
    if (timeout > 1) {
        timer = setTimeout(() => abort(`Request timeout after ${timeout}ms.`), timeout);
    }

    const attachAbort = useAbort(abort);
    const request = fetch(url, options)
        .finally(() => clearTimeout(timer))
        .then(callback);
    return attachAbort(request);
}

function optionalArgs(method, url, data, args) {
    if (data) {
        if (typeof data !== 'object' || Array.isArray(data)) {
            error('Unexpected data type will be ignored', data);
        } else {
            const args = String(new URLSearchParams(data));
            if (args.includes('%5Bobject+')) {
                // Encoded "[object <T>]" string, e.d. "[object Object]", "[object File]" ...
                // The `%5B` is encoded `[`, and `%5D` is `]`.
                // The `+` is the middle space encoded by URLSearchParams with 'application/x-www-form-urlencoded'.
                throws(`Nested object is not supported for ${method} request`, data);
            } else {
                url += (url.includes('?') ? '&' : '?') + args;
            }
        }
    }
    return fetchRequest(method, url, null, args);
}

/** @type {typeof $$.fetch.get} */
function get(url, data, args) {
    return optionalArgs('GET', url, data, args);
}
/** @type {typeof $$.fetch.post} */
function post(url, data, args) {
    return fetchRequest('POST', url, data, args);
}
/** @type {typeof $$.fetch.put} */
function put(url, data, args) {
    return fetchRequest('PUT', url, data, args);
}
/** @type {typeof $$.fetch.delete} */
function del(url, data, args) {
    return optionalArgs('DELETE', url, data, args);
}

const utils = Object.freeze({
    config: DefaultOptions,
    get,
    post,
    put,
    delete: del,
    xhrUpload,
});

export default utils;
