/** @jsxImportSource @gui/aui-devops */
import { scroll as scrollObserver } from '../../core/module/observer/observer.js';
import { define, Widget, Types } from '../../widget/widget.js';

import '../loading/dot.js';

import style from './style.less';

/** @extends {Widget<typeof Lazyload.options>} */
@define('lazyload')
export class Lazyload extends Widget {
    static options = {
        loading: true,
        offsetEnd: 0,
        axis: Types.Enum(['x', 'y'], 'y'),
        loopLoad: false,
        autoLoad: false,
        disabled: false,
        doLoad: Types.function,
    };
    static observers = ['disabled'];
    static styles = style;

    create() {
        this.method = {
            disconnect: this.disconnect,
            connect: this.connect,
            load: this.load,
        };
    }
    init() {
        this.state = {
            timeStart: null,
            timeDuration: null,
            withLoading: this.options.loading,
            hidden: true,
            status: -1, // {-1: not init/unmount; 0: disconnected; 1: mount start}
            lock: false,
        };
    }
    didMount() {
        this.observer = this.query('.observer');
        this.scrollElement = this.$element.scrollBox(false, true).get();
        this.connect();
    }
    setOption(name, value) {
        if (name === 'disabled') {
            return (value ? this.disconnect() : this.connect()) || false;
        }
    }
    didUnmount() {
        this.disconnect();
    }

    scrollable() {
        const status = $$.hasScroll(this.scrollElement);
        return status[this.options.axis] || false;
    }
    load() {
        this.setState({ lock: true, timeStart: Date.now(), timeDuration: null }, false);
        this.toggleLoading(true);
        this.callbackResult(this.callback('doLoad')).then((result) => {
            queueMicrotask(() => {
                const timeDuration = Date.now() - this.state.timeStart;
                this.setState({ timeStart: null, timeDuration }, false);
                if (result !== false && this.state.status > 0 && this.options.loopLoad && !this.scrollable()) {
                    this.load();
                } else {
                    this.setState({ lock: false }, false);
                    this.toggleLoading(false);
                }
            });
        });
    }
    toggleLoading(isShow) {
        if (this.state.withLoading) {
            this.setState({ hidden: !isShow });
        }
    }
    disconnect() {
        this.scrollObserver?.disconnect();
        this.scrollObserver = null;
        this.setState({
            status: 0,
            hidden: true,
        });
    }
    connect() {
        this.setState({ status: 1 });
        setTimeout(() => {
            if (!this.scrollObserver) {
                this.scrollObserver = this.startIntersectionObserver();
                if (this.options.autoLoad) this.load();
            }
        });
    }
    startIntersectionObserver() {
        const { axis, offsetEnd } = this.options,
            args = { target: this.observer };
        switch (axis) {
            case 'x':
                args.rootMargin = `0px ${offsetEnd}px 0px 0px`;
                args.endH = true;
                args.equalH = true;
                break;
            case 'y':
                args.rootMargin = `0px 0px ${offsetEnd}px 0px`;
                args.endV = true;
                args.equalV = true;
                break;
        }

        return scrollObserver(this.scrollElement, args, this.handleIntersectionObserver);
    }
    handleIntersectionObserver = (bool) => {
        if (bool && !this.state.lock && (this.options.autoLoad || this.scrollable())) {
            this.load();
        }
    };

    render() {
        const { hidden } = this.state;
        return (
            <>
                <slot></slot>
                {this.state.withLoading && (
                    <div className="loading-box" hidden={hidden} tabIndex={-1}>
                        {!hidden && <aui-loading-dot name={this.uuid} />}
                    </div>
                )}
                <div className="observer" hidden={this.state.status < 1}></div>
            </>
        );
    }
}
