import { getValue } from '../value-path.js';

/** @type {typeof $$.array.delete} */
export default function _delete(array, query, valuePath) {
    const type = $$.getClassBuiltIn(query);
    for (let i = 0; i < array.length; i++) {
        let match = false; // eslint-disable-line no-useless-assignment
        const value = getValue(array[i], valuePath);
        if (type === 'RegExp') {
            match = value.match(query);
        } else if (type === 'Function') {
            match = query(value);
        } else {
            match = value === query;
        }

        if (match) array.splice(i--, 1);
    }
    return array;
}
