/** @jsxImportSource @gui/aui-devops */
import { define, Widget, Types } from '../../widget/widget.js';

import numberClamp from '../../util/number/clamp.js';
import stringFormat from '../../util/string/format.js';

import style from './style.less';

const I18N = $$.I18N.pager,
    DefaultSizeSource = [10, 20, 50, 100],
    DisplayCount = 7;

/** @extends {Widget<typeof Pager.options>} */
@define('pager')
export class Pager extends Widget {
    static options = {
        pageSize: 10,
        selectedPage: 1,
        pageCount: 1,
        turnPage: true,
        showRows: Types.Union([Types.array, Types.boolean], true),
        type: Types.Enum(['default', 'simple'], 'default'),
        total: Types.number,
        onChange: Types.function,
    };
    static styles = style;
    static observers = ['pageSize', 'selectedPage', 'pageCount', 'showRows', 'total'];

    init() {
        const { selectedPage, pageSize } = this.options;
        this.state = {
            pageSize: pageSize,
            selectedPage: selectedPage,
            pageValue: selectedPage,
        };
        this.pageCount = this.getPageCount();
        this.oldSelectedPage = selectedPage;
        this.oldPageSize = pageSize;
    }
    getPageCount(num) {
        const { total, pageCount } = this.options;
        const { pageSize } = this.state;
        const size = num || pageSize;
        return Math.ceil(total / size || pageCount);
    }
    setOption(name, value) {
        let selectedPage = this.state.selectedPage,
            isChange = false;
        switch (name) {
            case 'selectedPage':
                isChange = true;
                selectedPage = value;
                break;
            case 'pageCount':
            case 'total':
                isChange = true;
                break;
            case 'pageSize':
                selectedPage = 1;
                isChange = true;
                this.setState({ pageSize: value });
                break;
        }
        if (isChange) {
            this.pageCount = this.getPageCount();
            this.onChange(numberClamp(1, selectedPage, this.pageCount));
        }
    }

    onChange(value, focused) {
        const { selectedPage, pageValue } = this.state;
        this.oldSelectedPage = selectedPage;
        if (this.oldSelectedPage !== value) {
            this.setState({ selectedPage: value, pageValue: value }, () => {
                this.changeCallback(focused);
            });
        } else if (pageValue !== value) {
            this.setState({ pageValue: value });
        }
    }
    changeCallback = (focused) => {
        const { selectedPage, pageSize } = this.state;
        this.element.setAttribute('data-dirty', true);
        this.callback('onChange', {
            oldValue: {
                selectedPage: this.oldSelectedPage,
                pageSize: this.oldPageSize,
            },
            newValue: {
                selectedPage: selectedPage,
                pageSize: pageSize,
            },
        });
        if (focused) this.$element.find('.active').get(0)?.focus();
    };
    onFirstOrLastClick = (e) => {
        const value = Number(e.currentTarget.value);
        this.onChange(value, true);
    };
    onPrevOrNextClick = (e) => {
        const { selectedPage } = this.state;
        const value = Number(e.currentTarget.value);
        const newValue = selectedPage + value;
        if (newValue > 0 && newValue <= this.pageCount) this.onChange(newValue);
    };
    onPagerClick = (e) => {
        const value = Number(e.currentTarget.value);
        if (!Number.isNaN(value)) this.onChange(value);
    };

    onInput = (value, e) => {
        const val = value.replaceAll(/\D/g, '');
        this.setState({ pageValue: val });
        e.target.value = val;
    };
    onEnter = () => {
        this.onGoClick();
    };
    onGoClick = (e) => {
        let { pageValue, selectedPage } = this.state;
        pageValue = pageValue === '0' ? 1 : Number(pageValue) || selectedPage || 1;
        this.setState({ pageValue: pageValue });
        if (pageValue > 0 && pageValue <= this.pageCount) {
            if (pageValue !== selectedPage) this.onChange(pageValue);
        } else if (pageValue > this.pageCount) {
            this.onChange(this.pageCount);
        } else {
            this.onChange(1);
        }
    };
    onPageSizeChange = (value) => {
        const { pageSize } = this.state;
        this.oldPageSize = pageSize;
        const newPageSize = Number(value);
        if (pageSize !== newPageSize) {
            this.pageCount = this.getPageCount(newPageSize);
            this.setState({ selectedPage: 1, pageValue: 1, pageSize: newPageSize }, this.changeCallback);
        }
    };
    renderRows() {
        const { showRows } = this.options;
        if (!showRows) return null;
        const { pageSize } = this.state;
        const sizeSource = Array.isArray(showRows) ? showRows : DefaultSizeSource;
        return (
            <div className="page-size">
                <aui-select-lite items={sizeSource.join(';')} value={String(pageSize)} onChange={this.onPageSizeChange}>
                    <span slot="inline-start">{I18N.showRows}:</span>
                </aui-select-lite>
            </div>
        );
    }
    renderPagination() {
        const { type } = this.options;
        if (type !== 'default') return null;
        const { selectedPage } = this.state;
        const total = this.pageCount,
            halfCount = Math.floor(DisplayCount / 2),
            list = [];
        let startPage, endPage;
        if (total < DisplayCount) {
            startPage = 1;
            endPage = total;
        } else {
            startPage = selectedPage - halfCount;
            startPage = startPage > 0 ? startPage : 1;
            startPage = startPage === 1 ? 1 : startPage + 2;
            endPage = startPage + (startPage === 1 ? DisplayCount - 1 : DisplayCount - 3);
            if (endPage > total) {
                startPage = startPage - (endPage - total);
                endPage = total;
                startPage = startPage > 3 ? startPage : 1;
            }
            endPage = endPage === total ? endPage : endPage - 2;
        }
        for (let i = startPage; i <= endPage; i++) {
            list.push(this.getPagination(i, selectedPage));
        }
        const hideBefore = startPage === 1,
            hideAfter = endPage === total;
        return (
            <div className="pagination">
                {this.getPagination(1, selectedPage, { id: 'page-first', hidden: hideBefore })}
                <div id="ellipsis-before" className="button-ellipsis" hidden={hideBefore} />
                {list}
                <div id="ellipsis-after" className="button-ellipsis" hidden={hideAfter} />
                {this.getPagination(total, selectedPage, { id: 'page-last', hidden: hideAfter })}
            </div>
        );
    }
    getPagination(num, selectedPage, { id, ...args } = {}) {
        const isActive = num === selectedPage;
        return (
            <aui-button-lite
                id={id}
                className={['main-button ', isActive && 'active']}
                type={isActive ? 'button' : 'bald'}
                primary={isActive}
                shrink="s"
                value={num}
                onClick={this.onPagerClick}
                {...args}
            >
                <span slot="text" className="light-text">
                    {num}
                </span>
            </aui-button-lite>
        );
    }
    renderInput(slot) {
        const { pageValue } = this.state;
        return <aui-input-lite className="jump-input" slot={slot} value={pageValue} align="center" aria={I18N.currentPage} onEnter={this.onEnter} onInput={this.onInput} />;
    }
    render() {
        const { total, type, turnPage } = this.options;
        const { selectedPage } = this.state;
        const isDefault = type === 'default',
            disabledPrev = selectedPage === 1 || this.pageCount <= 1,
            disabledNext = selectedPage === this.pageCount || this.pageCount <= 1;
        return (
            <div className="pager" style={{ '--count': String(this.pageCount).length }}>
                <slot>{total > 0 && (total > 1 ? <span>{stringFormat(I18N.totalItems, total)}</span> : <span>{I18N.totalItem}</span>)}</slot>
                <div className="page-container">
                    {this.renderRows()}
                    {isDefault && (
                        <aui-button-lite
                            type="bald"
                            className="main-button button-first"
                            icon="faui-angle-start"
                            tooltip={I18N.first}
                            disabled={disabledPrev}
                            value="1"
                            onClick={this.onFirstOrLastClick}
                        />
                    )}
                    <aui-button-lite
                        type="bald"
                        className="main-button previous"
                        icon="faui-angle-left"
                        tooltip={I18N.previous}
                        disabled={disabledPrev}
                        value="-1"
                        onClick={this.onPrevOrNextClick}
                    />
                    {this.renderPagination()}
                    <div className={['content-simple', type === 'simple' ? 'simple' : '']}>
                        <aui-i18n entry={I18N.simpleText}>
                            {this.renderInput(0)}
                            <span className="pagecount" slot="1">
                                {this.pageCount || 1}
                            </span>
                        </aui-i18n>
                    </div>
                    <aui-button-lite
                        type="bald"
                        className="main-button next"
                        icon="faui-angle-right"
                        tooltip={I18N.next}
                        disabled={disabledNext}
                        value="1"
                        onClick={this.onPrevOrNextClick}
                    />
                    {isDefault && (
                        <aui-button-lite
                            type="bald"
                            className="main-button button-last"
                            icon="faui-angle-end"
                            tooltip={I18N.last}
                            disabled={disabledNext}
                            value={this.pageCount}
                            onClick={this.onFirstOrLastClick}
                        />
                    )}
                    {isDefault && (
                        <div className="page-jump">
                            {this.renderInput()}
                            {turnPage && <aui-button-lite className="goto" text={I18N.go} tooltip={I18N.go} shrink="m" onClick={this.onGoClick} />}
                        </div>
                    )}
                </div>
            </div>
        );
    }
}
