/** @jsxImportSource @gui/aui-devops */
import { define, Types, Widget } from '../../widget/widget.js';

import cssGetValue from '../../util/css/get-value.js';

import { ModalWidget, Inherit } from '../dialog/modal-widget.js';

const { options, observers, forwardOptions } = Inherit(['global']);
const I18N = $$.I18N.panel;
const SizeOrient = { h: 'width', v: 'height' };
const LogicOrient = { h: 'inline', v: 'block' };

/** @extends {Widget<typeof Panel.options>} */
@define('panel')
export class Panel extends ModalWidget {
    static options = {
        ...options,
        actionType: Types.Enum(['close', 'back', 'none'], 'close'),
        orient: Types.Enum(['h', 'v'], 'h'),
        flow: Types.Enum(['start', 'end'], 'end'),
        size: Types.Length.value(400),
    };
    static observers = ['actionType', 'size', 'orient', 'flow', ...observers];
    static styles = `:host{display:contents;}`;
    static internals = { role: 'dialog' };

    doShow() {
        const { orient, flow } = this.options,
            logical = LogicOrient[orient],
            float = flow === 'end' ? 'start' : 'end';
        this.dynamicStyle(`::part(dialog){opacity:1;margin-${logical}-${float}:auto;}`);
        if (!this.options.global) {
            const box = this.host.parentElement;
            if (cssGetValue('position', box) === 'static') box.style.position = 'relative';
        }
    }
    render() {
        const { actionType, global, backdrop, orient, size, ...args } = this.options,
            modalOptions = forwardOptions(args);
        Object.assign(modalOptions, { width: 'auto', height: 'auto', [SizeOrient[orient]]: size });
        return (
            <aui-modal _type="panel" {...modalOptions} closeable={actionType === 'close'} backdrop={backdrop && '_similar'} global={global} {...this.modalOptions}>
                {actionType === 'back' && <aui-button-lite slot="action-start" type="bald" icon="faui-arrow-left font-bold" tooltip={I18N.back} onClick={this.close} />}
                <slot name="header" slot="header" />
                <slot name="actions" slot="actions" />
                <slot>
                    <div />
                </slot>
                <slot name="footer" slot="footer" />
                <slot name="buttons" slot="buttons" onClick={this.onButtonClick} />
            </aui-modal>
        );
    }
}
