import arrayLike from '../../util/array/is-like.js';
import { isElement as isElementType } from '../../util/type/types.js';

export const allowNodeTypes = [Node.ELEMENT_NODE, Node.DOCUMENT_NODE, Node.DOCUMENT_FRAGMENT_NODE];
export const isElement = (v) => isElementType(v, allowNodeTypes);

/** @returns {Array<Element> | null} */
export function getElementsStrict(source, filter) {
    const fn = filter || (() => true);
    if (isElement(source)) {
        return fn(source) ? [source] : [];
    } else if (arrayLike(source)) {
        const result = Array.from(source).reduce((a, b) => a.concat(b), []);
        return Array.prototype.filter.call(result, (el) => el && allowNodeTypes.includes(el.nodeType) && fn(el));
    }
    return null;
}

export function getElementStrict(source, filter) {
    const elements = getElementsStrict(source, filter);
    return elements?.[0] ?? null;
}
