/** @jsxImportSource @gui/aui-devops */
import { define, Widget, Types, inherit } from '../../widget/widget.js';

import arrayUnique from '../../util/array/unique.js';

import { loading } from '../loading/loading.js';

import { Detail } from './detail.js';
import { Echo } from './echo.js';
import './img.js';
import { Picker } from './picker.js';
import { findFile, DeleteService } from './utils.js';

import dropStyle from './drop-style.less';
import style from './style.less';

const { options: DetailOptions, observers: DetailObservers } = inherit(Detail),
    { options: EchoOptions, observers: EchoObservers } = inherit(Echo),
    { options: PickerOptions, observers: PickerObservers } = inherit(Picker),
    options = { ...DetailOptions, ...EchoOptions, ...PickerOptions },
    downstreamOptions = Object.keys(options),
    observers = arrayUnique([...DetailObservers, ...EchoObservers, ...PickerObservers]);

const I18N = $$.I18N.uploader;

class LoadingService {
    #showLoading = false;
    init(args) {
        if (typeof args.showLoading === 'boolean') this.#showLoading = args.showLoading;
        return this;
    }
    loading = (...args) => this.#showLoading && loading(...args);
}

/** @extends {Widget<typeof Uploader.options>} */
@define('uploader')
export class Uploader extends Widget {
    static options = {
        ...options,
        view: Types.Enum(['default', 'image', 'none'], 'default'),
        internalMessage: false,
    };
    static observers = [...observers];
    static upcasts = ['view'];
    static downstreamContext = ['extend', ['uploader-detail', 'uploader-echo', 'uploader-img', 'uploader-picker'], downstreamOptions];
    static styles = style;
    static unicomRealm = 'uploader';

    styles = { drop: dropStyle };

    init() {
        this.method = {
            checkValidation: this.checkValidation,
            clear: this.clear,
            getValue: this.getValue,
        };

        const loadingService = new LoadingService().init(this.options),
            deleteService = new DeleteService(loadingService).init(this.options);
        this.state = {
            dirty: false,
            /** @type {boolean|'overLimit'} */
            disabled: this.options.disabled,
            files: this.options.files,
            message: '',
            service: {
                loading: loadingService,
                delete: deleteService,
            },
        };
        this.optionsGetter = {
            disabled: () => this.state.disabled,
            files: () => this.state.files ?? undefined,
        };

        this.dispatcher = this.useUnicom(['uploader', 'uploader'], this.receiver);
    }
    /** Single mode only, for replace (delete) exists file. */
    #doDeleteFile = (file, errorMessage) => {
        const { service, files } = this.state;
        return service.delete.exec(files, file, errorMessage).then((files) => {
            this.updateFiles(files, false); // No need to trigger onChange.
        });
    };
    didMount() {
        this.dispatcher('echo', 'getFiles').then(
            (files) => this.updateFiles(files ?? this.options.files, false),
            () => this.updateFiles(this.options.files, false)
        );
        this.dispatcher('picker?', 'initDrop', this, 'drop');
    }
    setOption(name, value, oldValue) {
        switch (name) {
            case 'files':
                return this.updateFiles(value, false);
            case 'disabled':
                this.setState({ disabled: value }, false);
                return this.updateFiles(this.state.files, true); // force update files to check limit.
            default:
                break;
        }
    }
    receiver = (action, from, ...args) => {
        switch (action) {
            case 'getService':
                // Trigger by any, get service object.
                return this.state.service;
            case 'getFiles':
                // Trigger by any, get current files.
                return this.state.files ?? [];
            case 'uploadFiles': {
                // Trigger by picker, called when adding new files.
                const [files, maxLength] = args;
                return this.uploadFiles(files, maxLength);
            }
            case 'updateFiles': {
                // Trigger by Echo, called when updating files.
                const [files] = args;
                return this.updateFiles(files, true);
            }
            case 'replaceFile':
                // Trigger by picker, called when replacing file in single mode.
                return this.replaceFile();
            default:
                break;
        }
    };

    #filesChanged(files, exists = this.state.files) {
        if (files === exists) return false;
        // both empty: not changed
        return !!(files?.length || exists?.length);
    }
    updateFiles = (files, force) => {
        const isSameSource = !this.#filesChanged(files);
        if (isSameSource && !force) return;
        return Promise.try(() => {
            if (!files?.length) return this.setUploadFiles([]);
            return this.dispatcher('picker', 'sliceFiles', files).then(
                // Only valid multiple maxLength when picker exists.
                ([files, maxLength]) => this.setUploadFiles(files, maxLength),
                // Picker not exists, set files directly.
                () => this.setUploadFiles(files)
            );
        }).then((files) => {
            // Not same source (update disabled option).
            if (isSameSource) return;
            // And only trigger onChange when force is true.
            if (force) this.dispatcher('picker', 'onChange', files);
        });
    };
    uploadFiles(files, maxLength) {
        if (!files?.length) return [];
        const [...fileList] = this.state.files ?? [];
        for (const file of files) {
            const index = findFile(fileList, file);
            if (index == null) {
                fileList.push(file);
            } else {
                fileList[index] = file;
            }
        }
        return this.setUploadFiles(fileList, maxLength);
    }
    setUploadFiles(files, maxLength) {
        let { disabled, files: exists } = this.state;
        if (disabled !== true) disabled = maxLength > 1 && files.length === maxLength && 'overLimit';
        this.setState({ files, disabled }, () => {
            if (this.#filesChanged(files, exists)) this.$host.trigger('onChange');
        });
        return files;
    }

    replaceFile() {
        const { files } = this.state,
            results = files.map((file) => this.#doDeleteFile(file, I18N.overwriteFailed));
        return Promise.all(results)
            .then(this.clear)
            .finally(() => {
                const { files } = this.state;
                if (!files.length) return;
                // doDelete failed (file exists) fallback to update list.
                this.updateFiles([...files], false);
            });
    }

    checkValidation() {
        const { internalMessage } = this.options,
            { files } = this.state,
            value = [];
        for (const file of files) {
            if (file.isSucceed === false) return new Error((internalMessage && file.message) || '');
            if (file.status) return new Error(); /// [AUI-3447]
            value.push(file);
        }
        return value;
    }
    clear = () => {
        return this.updateFiles([], false);
    };
    getValue = () => {
        return this.state.files ?? [];
    };

    render() {
        const { disabled, message } = this.state;
        return (
            <>
                <slot className={['uploader', !!disabled && 'disabled']} />
                {message && <div className="message">{message}</div>}
            </>
        );
    }
}
