import clamp from './clamp.js';

/** @type {typeof $$.css.minmax} */
export default function minmax(key, value, processor) {
    const result = {};
    const k = (name) => name + '-' + key;
    const [min, v, max] = clamp(value, processor);

    if (min != null) result[k('min')] = min;
    if (v != null) result[key] = v;
    if (max != null) result[k('max')] = max;

    return result;
}
