/** @jsxImportSource @gui/aui-devops */
import { error } from '../../core/base/log.js';
import { widget } from '../../core/extend/widget.js';

import stringFormat from '../../util/string/format.js';

import '../selection/selection-old.js';
import * as _$ from '../selection/dataset-old.js';
import '../comboboxshell/comboboxshell.js';

const ComboboxShellArgs = { popupWidth: [0], scrollable: false, resetScroll: false };

(function () {
    const noop = $$.fn();
    const ClassName = {
        Widget: 'aui-multicombobox',
        Content: 'aui-multicombobox-content',
        Filter: 'aui-multicombobox-filter',
        Ellipsis: 'aui-multicombobox-ellipsis',
        None: 'aui-multicombobox-none',
        Listbox: 'aui-selection-listbox',
        Listbox_Container: 'aui-selection-listbox-container',
    };
    widget('aui5.multicombobox', {
        options: {
            // data
            items: [],
            // Properties that display content
            textField: 'text',
            // value properties
            valueField: 'value',
            // Whether the property is selected or not
            checkedField: 'checked',
            // tooltip properties
            tooltipField: 'tooltip',
            // Whether to disable the property
            disabledField: 'disabled',
            // Grouping attributes
            groupField: undefined,
            matchFields: undefined,
            // Whether search is enabled or not
            searchable: true,
            // Searchbox watermark text
            searchPlaceholder: $$.I18N.multicombobox.placeholder,
            // backward-compatible alias, prefer searchPlaceholder
            createNewText: undefined,
            // Whether to display the full marquee
            hasSelectAll: true,
            // Maximum number of displays per page
            lazyStep: 50,
            // For check options, assignments
            value: undefined,
            // Whether to weight based on a textField
            unique: false,
            // The width of a popup, by default or when set to "100%", is the same width as the control
            popupWidth: 'auto',
            // The maximum height of popup
            popupMaxHeight: 410,
            // width
            width: 220,
            // height
            height: undefined,
            // Control disabled
            disabled: false,
            // Control readonly
            readonly: false,
            // Select at least one, otherwise you can't click OK
            required: true,
            // Displays all selected item names (for multiple or all selected status)
            allNames: false,
            // Displays text when not selected
            noneText: '',
            // Display text when selecting all
            allText: '',
            // Select multiple display templates
            selectedItemsTemplate: '',
            // Select a display template when
            selectedItemTemplate: '',
            formatText: '',
            prefix: '',
            // The minimalist model
            mini: false,
            // Compact model
            compact: false,
            template: '',
            groupTemplate: '',
            contentTemplate: '',
            filter: false,
            clearable: false,
            groupToggleable: false,
            icon: 'faui-caret-down',
            tooltip: undefined,
            customTrigger: false,
            maxlength: 255,
            pinSelected: true,
            searchDelay: 350,
            searchMinChars: 0,
            // A callback when search/lazyLoad
            doLoad: noop,
            doCreateNew: noop,
            willChange: noop,
            // This callback is triggered when the selected middle item changes
            onChange: noop,
            willShow: noop,
            willHide: noop,
            onShow: noop,
            onHide: noop,
        },
        _initMember: function () {
            this._deepcopy = _$.deepcopy;
            this._getCheckValue = _$.getCheckValue;
            this._uniqueData = _$.uniqueData;
            this._formatItems = _$.formatItems;
            this._doLoad = this.options.doLoad !== noop;
            this._isChange = false;
            this._items = [];
            this._oldItems = [];
            this._oldValue = [];
            this._changeResult = {};
            this._min = 1;
            this.contentTemplate = this.options.contentTemplate;

            return this;
        },
        _create: function () {
            this._initMember();
            this._items = this._deepcopy(this.options.items);
            this._items = this._formatItems(this.options, this._items);

            if (this._items.length > this._uniqueData(this._items, this.options.valueField).length) {
                error('Value cannot be repeated.');
            }
            this._updateRequired()._initPopup()._initList()._initEvent();
        },
        _updateRequired: function () {
            const required = this.options.required;

            if (required === true) {
                this._min = 1;
            } else if (required === false) {
                this._min = 0;
            } else if (Array.isArray(required) && required.length > 0) {
                this._min = required[0];
            }

            return this;
        },
        _initPopup: function () {
            const { aria, compact, customTrigger, disabled, filter, icon, height, width, mini, popupWidth, popupMaxHeight, tooltip } = this.options,
                args = { aria, compact, disabled, icon, height, width, mini, tooltip };
            this.comboboxShell = (
                <aui-combobox-shell
                    part="combobox-shell"
                    {...ComboboxShellArgs}
                    {...args}
                    popupHeight={[, popupMaxHeight]} // eslint-disable-line no-sparse-arrays
                    popupWidth={[, popupWidth, '50vw']} // eslint-disable-line no-sparse-arrays
                    dynamicSize={this._doLoad !== false}
                    onClear={this.onClearClick.bind(this)}
                    willShow={this.willShow.bind(this)}
                    willHide={() => this._callback('willHide') !== false}
                    onShow={this.onShow.bind(this)}
                    onHide={this.onHide.bind(this)}
                >
                    <div id={'aui_multicombobox_' + this.uuid}></div>
                    <div slot="content" id={'aui_multicombobox_content_' + this.uuid} className={ClassName.Content}></div>
                    {customTrigger && <div slot="trigger">{this.$element.children().eq(0)}</div>}
                    <aui-button-lite id="clear" type="link" name="clear" slot="footer" text={$$.I18N.multicombobox.clear} hidden onClick={this._clearSelection.bind(this)} />
                    <aui-button-lite
                        id="cancel"
                        name="cancel"
                        slot="buttons"
                        text={$$.I18N.multicombobox.cancel}
                        value="close"
                        disabled={false}
                        onClick={this._onCancelClick.bind(this)}
                    />
                    <aui-button-lite id="ok" name="ok" slot="buttons" text={$$.I18N.multicombobox.ok} value="ok" primary disabled={true} onClick={this._onOKClick.bind(this)} />
                </aui-combobox-shell>
            );
            this.$element.addClass(ClassName.Widget);
            this.element.append(this.comboboxShell);
            if (filter === true) this.$element.addClass(ClassName.Filter);

            return this;
        },
        willShow: function () {
            if (this.options.willShow !== noop && this._callback('willShow') === false) {
                return false;
            } else {
                // this.$popup.css('min-width', this.$element.outerWidth());
                this.$listElement.selection('option', { status: { show: true } });
                return true;
            }
        },
        _initList: function () {
            const options = this.options,
                id = 'aui_multicombobox_' + this.uuid;

            this.$listElement = this.$element.find(`#${id}`);
            this.$listElement.selection({
                type: 'multiple',
                focus: true,
                items: this._items,
                textField: options.textField,
                checkedField: options.checkedField,
                tooltipField: options.tooltipField,
                disabledField: options.disabledField,
                valueField: options.valueField,
                groupField: options.groupField,
                matchFields: options.matchFields,
                searchable: options.searchable,
                searchPlaceholder: options.searchPlaceholder,
                createNewText: options.createNewText,
                hasSelectAll: options.filter === true || this._doLoad === true ? false : options.hasSelectAll,
                filter: options.filter,
                readonly: options.readonly,
                lazyStep: options.lazyStep,
                searchDelay: options.searchDelay,
                searchMinChars: options.searchMinChars,
                value: options.value,
                unique: options.unique,
                excludeChecked: false,
                defaultActive: false,
                maxlength: options.maxlength,
                template: options.template,
                groupTemplate: options.groupTemplate,
                groupToggleable: options.groupToggleable,
                status: { show: false },
                forceMatchStep: options.forceMatchStep,
                required: options.required,
                pinSelected: options.pinSelected,
                singleMode: false,
                doLoad: options.doLoad,
                doCreateNew: options.doCreateNew,
                onChange: this._onChange.bind(this),
            });

            this.$listElement.attr('tabindex', '-1');
            this._items = this.$listElement.selection('getAllItems');
            this._oldItems = this._items;
            this._oldValue = this.getValue();
            this._updateContent(this._items);
            this._updateButton(this._items);

            return this;
        },
        onShow: function (e) {
            this.$listElement.find('.' + ClassName.Listbox).height('auto');
            this._updateButton(this._oldItems);
            this.$listElement.selection('handleLoading');
            this.comboboxShell.setAttribute('status', { show: true });
            const timer = setTimeout(() => {
                if ($$.browser.touchable !== true) {
                    if (this.options.searchable === true) {
                        this.$listElement.find('aui-searchbox').focus();
                    } else {
                        this.$listElement.focus();
                    }
                }
                const $listbox = this.$listElement.find('.' + ClassName.Listbox_Container);
                if ($listbox && $listbox.length > 0) {
                    $listbox[0].scrollLeft = 0;
                    $listbox[0].scrollTop = 0;
                }
                clearTimeout(timer);
            });
            this._callback('onShow');
        },
        onHide: function (e) {
            if (this.options.searchable === true) this.$listElement.selection('updateSearchboxValue', '');
            this.$listElement.selection('setStatus', false);
            if (this._isChange) {
                this._isChange = false;
                this.$listElement.selection('option', 'value', this._deepcopy(this._oldValue ?? []));
                this._updateContent(this._oldItems);
                this._updateButton(this._oldItems);
            }
            this.$element.focus();
            this._callback('onHide');
        },
        _clearSelection: function (clearDisabled) {
            this.$listElement.selection('clearSelection', true, !!clearDisabled);
            const items = this.$listElement.selection('getAllItems');
            this._updateContent(items);
            this._updateButton(items);
        },
        onClearClick: function (e) {
            this._clearSelection(this.options.clearable === 'force');
            this._onOKClick();
        },
        _getChangedData: function (arr1, arr2) {
            const items = (arr1 || []).filter((item, index) => {
                if (!(arr2 || []).some((ele) => ele[this.options.valueField] === item[this.options.valueField])) {
                    return item;
                }
                return false;
            });
            return items;
        },
        _onOKClick: function (e) {
            const isChange = this._isChange,
                disabled = this.options.filter === false && this.getValue()?.length < this._min,
                _oldValue = this._deepcopy(this._oldValue),
                newValue = this._changeResult.newValue,
                allValue = this._changeResult.all;
            if (isChange === true) {
                this._items = this._deepcopy(allValue);
                this._oldItems = this._deepcopy(allValue);
                this._oldValue = this._deepcopy(this.getValue());
                this._updateContent(allValue);
            }
            if (!disabled) this.comboboxShell.setAttribute('status', { show: false });
            if (isChange === true && this.options.onChange !== noop) {
                this.$element[0].dataset.dirty = true;
                const unCheckedItem = this._deepcopy(this._getChangedData(_oldValue, newValue)),
                    checkedItem = this._getChangedData(newValue, _oldValue);
                unCheckedItem.forEach((item) => {
                    item[this.options.checkedField] = false;
                });
                const changedValue = checkedItem.concat(unCheckedItem);
                this._handler('onChange', {
                    isSelectAll: this.options.filter && newValue.length === 0 ? true : newValue.length === allValue.length && this._doLoad === false,
                    current: changedValue,
                    newValue: this._deepcopy(newValue),
                    oldValue: this._deepcopy(_oldValue),
                });
            }
        },
        _onCancelClick: function () {
            this.onHide();
            this.comboboxShell.setAttribute('status', { show: false });
        },
        _onChange: function (args) {
            this._isChange = true;
            this._changeResult = this._deepcopy(args);
            this._updateContent(this._changeResult.all);
            this._updateButton(this._changeResult.all);
        },
        _updateButton: function (items) {
            const okDisabled = this.options.readonly || (this.options.filter === false && this.getValue()?.length < this._min);
            const okButton = this.comboboxShell.querySelector('#ok');
            if (okButton) okButton.setAttribute('disabled', okDisabled);
            // clear
            let checks = this.getValue();
            if (checks?.constructor === Object) {
                checks = [checks];
            }

            this.setClear(checks, this.options.disabledField);
            if (this.options.clearable !== false) {
                this.comboboxShell.setAttribute('clearable', checks?.length > 0 ? (this.options.clearable === 'force' ? true : this.clearable) : false);
                this.comboboxShell.setAttribute('clearTooltip', this.options.clearable === 'force' ? $$.I18N.comboboxshell.clear : this.clearTooltip);
            }
        },
        setClear: function (items, disabledField) {
            if (items === false || items == null || items?.length < 1) {
                this.clearable = false;
                this.clearTooltip = '';
            } else {
                const length = items?.length;
                let disabledLength = 0;
                for (let i = 0; i < items?.length; i++) {
                    if (items[i][disabledField] === true) disabledLength++;
                }

                if (items === true || (items?.length > 0 && length > disabledLength)) {
                    this.clearable = true;
                    this.clearTooltip = items === true || disabledLength === 0 ? $$.I18N.comboboxshell.clear : $$.I18N.comboboxshell.disableClearXSkip;
                } else if (items.length > 0 && length === disabledLength) {
                    this.clearable = 'disabled';
                    this.clearTooltip = items.length === 1 ? $$.I18N.comboboxshell.disableClear : $$.I18N.comboboxshell.disableClearX;
                }
            }
        },

        _isPopMobile: function () {
            return $$.mobileView && $$.browser.touchable;
        },
        _updateContent: function (items) {
            if (this.options.customTrigger === false) {
                this.$element.find(`#aui_multicombobox_content_${this.uuid}`).empty();
                const allNames = this.options.allNames === true ? ', ' : this.options.allNames,
                    checks = this.getValue(),
                    count = items == null || checks === undefined ? 0 : checks.length,
                    names = [],
                    length = items == null ? 0 : items.length;
                let text = '',
                    isNone = false;
                for (let i = 0; i < count; i++) {
                    if (this._doLoad === true || checks[i][this.options.checkedField] === true) names.push(checks[i][this.options.textField]);
                }
                this.allNames = names.join(', ');
                const allTextValue = this.options.allText || $$.I18N.multicombobox.allText;
                const allNameText = allNames ? this._format(allTextValue, names.join(allNames)) : allTextValue;
                if (count === 0) {
                    text = this.options.filter === true ? allNameText : this.options.noneText || $$.I18N.multicombobox.none;
                    isNone = this.options.filter === false;
                } else {
                    if (this._doLoad === false && count === length) {
                        text = allNameText;
                    } else if (count === 1) {
                        text = this.options.selectedItemTemplate || checks[0][this.options.textField];
                    } else {
                        text = allNames ? names.join(allNames) : this._format(this.options.selectedItemsTemplate || $$.I18N.multicombobox.selectedXItems, count);
                    }
                }
                if (this.options.prefix?.length > 0) {
                    const formatTextValue = this.options.formatText || $$.I18N.multicombobox.format;
                    text = formatTextValue.replace('{1}', text);
                    text = text.replace('{0}', this.options.prefix);
                }
                const content = (
                    <div data-placeholder={isNone} className={isNone ? ClassName.None : ClassName.Ellipsis}>
                        {this.contentTemplate || text}
                    </div>
                );
                this.$element.find(`#aui_multicombobox_content_${this.uuid}`).append(content);
            }
        },
        _format: function (str, arg) {
            return stringFormat(str, arg);
        },
        getValue: function () {
            const value = this.$listElement.selection('getSelectedItems');
            return value instanceof jQuery ? null : value;
        },
        verify: function () {
            const value = this.getValue();
            return [value];
        },
        clear: function () {
            this._clearSelection(true);
            this._onOKClick();

            return this;
        },

        _setOption: function (key, value) {
            const oldValue = this.options[key];
            if (value === oldValue) return false;
            this.options[key] = value;
            switch (key) {
                case 'items':
                    if (this._doLoad === false) {
                        const newVal = this._getCheckValue(value, this.options);
                        this.$listElement.selection('option', { value: this._deepcopy(newVal) });
                        this.$listElement.selection('option', { items: this._deepcopy(value) });
                        this._items = this._deepcopy(this.$listElement.selection('getAllItems'));
                        this._oldItems = this._deepcopy(this._items);
                        this._oldValue = this._deepcopy(this.getValue());
                        this._updateContent(this._oldItems);
                        this._updateButton(this._oldItems);

                        if (this._items.length > this._uniqueData(this._items, this.options.valueField).length) {
                            error('Value cannot be repeated.');
                        }
                    } else if (this._doLoad === true && this.options.items.length > 0) {
                        error('After the doLoad is configured, the items are invalid.');
                    }
                    break;
                case 'disabled':
                    this.comboboxShell.setAttribute('disabled', !!value);
                    break;
                case 'readonly':
                    this.comboboxShell.setAttribute('readonly', !!value);
                    this.$listElement.selection('option', { readonly: !!value });
                    break;
                case 'tooltip':
                    this.comboboxShell.setAttribute('tooltip', value ?? null);
                    break;
                case 'prefix':
                    this._updateContent(this._oldItems);
                    break;
                case 'value':
                    this.$listElement.selection('option', { value: this._deepcopy(value) });
                    this._items = this._deepcopy(this.$listElement.selection('getAllItems'));
                    this._oldItems = this._deepcopy(this._items);
                    this._oldValue = this._deepcopy(this.getValue());
                    this._updateContent(this._oldItems);
                    this._updateButton(this._oldItems);
                    break;
                case 'contentTemplate':
                    this.contentTemplate = value;
                    this._updateContent(this._oldValue);
                    break;
                case 'searchPlaceholder':
                    this.$listElement.selection('option', { searchPlaceholder: value });
                    break;
                default:
                    break;
            }
        },
    });
})();
