/** @jsxImportSource @gui/aui-devops */
import { define, Widget, Types } from '../widget.js';

import style from './bold.less';

/** @extends {Widget<typeof Bold.options>} */
@define('bold')
export class Bold extends Widget {
    static options = {
        bold: Types.boolean,
        value: Types.string,
    };
    static observers = ['bold', 'value'];
    static upcasts = ['bold'];
    static styles = style;

    #observer = new MutationObserver(() => this.refreshContent());
    didMount() {
        this.doObserve();
    }
    setOption(name, value) {
        if (name === 'value') {
            this.refreshContent(value);
        }
    }
    doObserve() {
        const observer = this.#observer;
        observer.disconnect();
        const nodes = this.element.assignedNodes({ flatten: true });
        for (const node of nodes) {
            if (node.nodeType === Node.TEXT_NODE) {
                observer.observe(node, { characterData: true });
            } else if (node.nodeType === Node.ELEMENT_NODE) {
                observer.observe(node, { subtree: true, childList: true, attributes: true, characterData: true });
            }
        }
        this.refreshContent();
    }
    refreshContent(value) {
        let content = value || this.$element.textContent() || this.options.value || '';
        content = content.match(/^[^\r\n\u0085\u2028\u2029]*/)?.[0];
        this.dynamicStyle(`:host { --content: ${content ? JSON.stringify(content) : ''} }`);
    }
    onSlotChange = () => {
        this.doObserve();
    };
    render() {
        return (
            <slot part="box" onSlotChange={this.onSlotChange}>
                {this.options.value}
            </slot>
        );
    }
}
