import load from './load.js';
import svg2base64 from './svg2base64.js';

/** @type {typeof $$.img.svg2base64Png} */
export default function svg2base64Png(svg, size) {
    const canvas = document.createElement('canvas'),
        ctx = canvas.getContext('2d');
    let base64 = typeof svg === 'string' ? svg : svg2base64(svg),
        [w, h] = size || [];
    return load(base64).then((img) => {
        if (!w) w = img.width;
        if (!h) h = img.height;
        canvas.width = w;
        canvas.height = h;
        ctx.drawImage(img, 0, 0, w, h);
        base64 = canvas.toDataURL('image/png');
        // eslint-disable-next-line unicorn/new-for-builtins
        const result = new String(base64);
        result.width = w;
        result.height = h;
        return result;
    });
}
