/** @jsxImportSource @gui/aui-devops */
import { Widget, inherit } from '../../widget/widget.js';

import { Modal } from './modal.js';

export function Inherit(whiteList) {
    const commonOption = ['backdrop', 'colorScheme', 'header', 'lightDismiss', 'resetScroll', 'scrollable', 'status', 'zIndex'],
        commonCallback = ['onClose', 'onHide', 'onShow', 'willHide', 'willShow'];
    return inherit(Modal, [...commonOption, ...commonCallback, ...whiteList]);
}

export class ModalWidget extends Widget {
    static shadow = Modal.shadow;

    modalOptions = {};
    create() {
        const methods = { show: this.show, hide: this.hide, loading: this.loading };
        this.hostProto = methods;
        this.method = methods;
        this.state = { isShow: false };
        Object.assign(this.modalOptions, { onToggle: this.#onToggle });
        for (const fn of ['show', 'hide', 'close', 'loading', 'onButtonClick']) {
            this[fn] = this[fn].bind(this);
        }
    }
    didMount() {
        this.customState('modal_box', true);
        const $dialog = this.$element.find('dialog', { crossShadow: true });
        this.dialog = $dialog.get();
    }
    show() {
        this.element.method('show');
    }
    hide() {
        this.element.method('hide');
    }
    close() {
        this.element.method('close');
    }
    loading(...args) {
        this.element.method('loading', ...args);
    }
    onButtonClick(e) {
        let [target] = e.composedPath();
        target = target?.closest('button');
        if (target?.value === 'close') this.element.hide();
    }
    #onToggle = (isShow) => {
        return isShow ? this.#onShow() : this.#onHide();
    };
    doShow() {}
    #onShow() {
        this.doShow();
    }
    doHide() {}
    #onHide() {
        this.doHide();
    }
}
