const SeparatorChars = ' _.';

/** @type {typeof $$.string.kebabCase} */
export default function kebabCase(val, effectFirst) {
    let result = '',
        needDash = false;

    for (let i = 0; i < val.length; i++) {
        const char = val[i];

        if (SeparatorChars.includes(char)) {
            needDash = true;
        } else if (char >= 'A' && char <= 'Z') {
            if (effectFirst || i) result += '-';
            result += char.toLowerCase();
            needDash = false;
        } else {
            if (needDash && result) {
                result += '-';
                needDash = false;
            }
            result += char;
        }
    }

    return result;
}
