/** @jsxImportSource @gui/aui-devops */
import $ from '../../core/element/index.js';
import { addTooltip } from '../../core/module/tooltip.js';
import { define, Widget, Types } from '../../widget/widget.js';

import stringKebabCase from '../../util/string/kebab-case.js';

import '../backdrop/backdrop.js';

import style from './style.less';

const I18N = $$.I18N.navpanel;
const { parser: ClassifyParser } = Types.Classify(true);
const KebabCase = (v) => (typeof v === 'string' ? stringKebabCase(v) : 'xid-' + v);

const Skins = {
    Apollo: {
        ArrowSize: true, // use pop default size
        Toggle: 'faui-toggle-right',
        Expand: 'faui-angle-down-s',
    },
    Allure: {
        ArrowSize: 8,
        Toggle: 'faui-toggle-right-round',
        Expand: 'faui-caret-down',
    },
};
const Icons = function (skin) {
    const data = {
        Close: 'faui-cancel',
        Threshold: 'faui-caret-down',
        Placeholder: 'placeholder',
        SubItem: 'faui-arrow-right',
    };
    return Object.assign(data, Skins[skin]);
};
const PopOptions = {
    classify: 'var(--bg)',
    triggerEvent: 'hover:0',
    ofElement: 'parent',
    my: 'left top',
    at: 'right top',
    scrollable: false,
    stacking: false,
    tabloop: false,
    mobileView: false,
    modalable: false,
};

class NavPanelView extends Widget {
    checkInstance(refresh) {
        const lastInstance = this.$host.is(':last-of-type'),
            onlyInstance = this.$host.is(':only-of-type'),
            useMobileClose = this.state.mobileViewEnable && lastInstance && (!onlyInstance || this.options.toggleable);
        if (useMobileClose !== this.state.useMobileClose) this.setState({ useMobileClose }, refresh);
        return useMobileClose;
    }
    #scrollTo(target) {
        const $body = this.$element.find('.body');
        // goto the last active item, use sub item at first.
        const $target = target ? $(target, this.element) : this.$element.findAll('.item.active'),
            active = $target.get(-1);
        if (active) $$.scrollTo(active, { bubbles: $body.get(), offsetY: 300, block: 'center', inline: false });
    }
    setActive(id, cb) {
        if (id) this.state.activeId = KebabCase(id);
        this.setState(null, () => {
            this.#scrollTo();
            if (cb) cb();
        });
    }
    onToggle(v, cb) {
        if (v === undefined) v = !this.state.expanded;
        const callback = () => {
            if (v) {
                this.#scrollTo();
            } else if (!CSS.supports('selector(::details-content)')) {
                this.$element.findAll('details').toggleAttr('open', true);
            }
            if (cb) cb();
        };
        if (this.state.expanded === v) return callback();
        this.setState({ expanded: v }, () => {
            callback();
            this.callback('onToggle', v);
        });
    }
    #onToggle = (e) => {
        this.onToggle();
    };
    #onClose = () => {
        this.onToggle(null);
    };
    #onItemClick = (e) => {
        const node = e.currentTarget,
            $target = $(e.target);
        // click on additional element scope, do nothing.
        if ($target.closest('.aui-scope-click', node).length) return null;

        const { inGroup, expanded, mobileView } = this.state,
            toggleButton = node.localName === 'button' && node.dataset.interactive,
            k = node.parentNode.id || node,
            item = this.state.cache.get(k);
        if (expanded && toggleButton) {
            // toggle button for lv1 item, toggle its expanded state.
            const $button = $(e).toggleAttr('aria-expanded'),
                expanded = $button.origin('ariaExpanded'),
                icon = $button.child('.icon').get();
            if (icon) icon.dataset.expanded = expanded;
            item.expanded = expanded;
        } else if (inGroup && !expanded && mobileView) {
            e.preventDefault();
            // in group mode, switch to expanded, and try to expend event path detail elements.
            this.onToggle(true, () => $(node).parents('details', '.body').toggleAttr('open', true));
        } else if (!toggleButton && !item.disabled && !item.inactive) {
            // only enable click handler for interactive item.
            const mainItem = node.classList.contains('main-item'),
                _item = mainItem ? item.original : item,
                cb = this.options.onChange,
                result = cb ? cb(_item, e) : true;
            if (typeof result === 'boolean') e.preventDefault();
            if (result !== false) {
                // after update selected, need to update instance state(lastChild or not), for update action.
                this.setActive(item.id, () => mobileView && this.onToggle(this.checkInstance() && inGroup ? null : false));
            }
        }
    };
    #onMirrorClick(e) {
        const node = e.currentTarget,
            item = node.closest('.box').firstElementChild;
        item.click();
    }
    #onPopShow = ({ ofElement: box }) => {
        const [button, pop] = box.children,
            _pop = pop.firstElementChild,
            popInfo = _pop.getBoundingClientRect(),
            boxInfo = box.getBoundingClientRect();

        if (this.options.arrow) {
            /** update arrow position */
            // const offset = boxInfo.top - popInfo.top + boxInfo.height / 2;
            // pop.style.setProperty('--block-offset', offset + 'px');
        } else {
            /** update pop flip state */
            if (boxInfo.top > popInfo.top) {
                pop.dataset.flip = true;
            }

            _pop.style.setProperty('--item-height', button.clientHeight + 'px');
        }
    };
    #onPopHide = ({ ofElement: box }) => {
        const [_button, pop] = box.children;
        pop.setOption('stacking', false);
    };
    #onShowPop = (e) => {
        if (!this.state.expanded && !this.state.mobileView) {
            const box = e.currentTarget,
                [button, pop] = box.children;
            if (pop.getAttribute('stacking', true) === false) {
                pop.setOption('stacking', true);
                pop.toggle(true, box, button);
            }
        }
    };
    #onHidePop = (e) => {
        if (!this.state.expanded) {
            const box = e.currentTarget,
                [_button, pop] = box.children;
            pop.toggle(false);
        }
    };
    #onFocusIn = (e) => {
        const { firstElementChild: item } = e.currentTarget;
        if (item.matches(':focus-visible')) this.#onShowPop(e);
    };
    #onFocusOut = (e) => {
        if (!this.state.expanded) {
            const $body = $(e.currentTarget),
                current = e.relatedTarget;
            if (document.hasFocus() && !$body.contains(current)) {
                const pop = $body.find(':popover-open', { crossShadow: true }).get();
                if (pop) pop.hidePopover();
            }
        }
    };
    #itemIcon({ icon, classify }) {
        if (!icon) return false;
        const style = { '--color': ClassifyParser(classify)?.color };
        // identifier char.
        if (!String(icon).startsWith('.')) return <span className={['item-icon', 'item-classify']} aria-description={icon} style={style} />;
        // icon.
        return <span className={[this.fontIcon(icon).split('.'), 'item-icon', classify && 'item-classify']} style={style} />;
    }
    // eslint-disable-next-line complexity
    #item(item) {
        const { Icon, activeId, expanded, cache, mobileView } = this.state,
            enable = !(item.disabled || item.inactive),
            { url, tooltip, ellipsis, attrs = {} } = item,
            active = activeId ? activeId === item.id : item.active,
            href = (enable && url) || null,
            hasChild = item.children?.length > 0,
            Tag = enable ? (href ? 'a' : 'button') : 'span',
            interactive = enable && (href || hasChild),
            toggleable = hasChild && enable && !href,
            arias = {
                'data-tooltip': 'ifneed',
                'data-tooltip-anchor': attrs.part === 'main-item' ? 'element(at=left bottom;my=left+4 top+4)' : null,
                'aria-disabled': !enable,
                'data-disabled': item.disabled,
                'data-inactive': item.inactive,
                'data-interactive': interactive ? 'focusable' : null,
            };
        if (tooltip && typeof tooltip === 'string') Object.assign(arias, { 'data-tooltip': 'diffneed', [interactive ? 'aria-label' : 'aria-description']: tooltip });
        if (interactive) {
            const v = (Tag === 'a' || toggleable) && (!!href || (item.expanded ?? true));
            if (mobileView || expanded) {
                if (toggleable) arias['aria-expanded'] = v;
            } else {
                arias['aria-haspopup'] = v;
            }
        }
        if (toggleable) arias['aria-controls'] = item.id;
        const node = (
            <Tag className={['item', item.className, active && 'active']} role={href ? 'link' : null} href={href} onClick={this.#onItemClick} {...attrs} {...arias}>
                {this.#itemIcon(item)}
                <div className={['item-content', ellipsis && 'ellipsis']}>{item.content}</div>
                {toggleable && <div className={['icon', 'icon-expanded', Icon.Expand]} data-expanded={arias['aria-expanded']} />}
            </Tag>
        );
        cache.set(item.id || node, item);
        return node;
    }
    #onGroupToggle = (e) => {
        const el = e.currentTarget;
        this.state.groupToggleable[el.dataset.index] = el.open;
    };
    #group(items, [group, toggleable, index]) {
        const children = this.#groupContent(items);
        // don't show by no-group, or invisible group header.
        if (group == null || /^--group-(\d+)$/.test(group)) return children;

        const className = 'group-header';
        const label = (
            <span className="ellipsis" data-tooltip="ifneed">
                {group}
            </span>
        );

        // non-toggleable group.
        if (!toggleable) return [<div className={className}>{label}</div>, children];

        const { Icon } = this.state,
            expanded = children.querySelector(':scope>[data-active="true"]') ? true : toggleable && toggleable[index] !== false;
        return (
            <details data-index={index} open={expanded} onToggle={this.#onGroupToggle}>
                <summary className={[className, 'button']}>
                    {label}
                    <span className={['icon', 'icon-expanded', this.fontIcon(Icon.Expand)]} />
                </summary>
                {children}
            </details>
        );
    }
    #groupContent(items) {
        const { childrenThreshold, arrow, iconClassify = '' } = this.options,
            iconTheme = 'icon-' + iconClassify,
            { Icon } = this.state;
        const activeIcon = (el) => iconClassify && el && $(el).child('.item-icon').addClass(iconTheme);

        return (
            <ul className="group-content">
                {items.map((item) => {
                    const { children } = item,
                        useThreshold = childrenThreshold > 0 && children?.length > childrenThreshold;
                    const subItems = (
                        <ul className="sub empty-hidden">
                            {children?.flatMap((child, i) => {
                                if (!child) return [];
                                const icon = (child.icon ?? '.' + Icon.SubItem) || '.' + Icon.Placeholder,
                                    className = useThreshold && i + 1 === childrenThreshold && 'sub-threshold';
                                return (
                                    <li id={child.id} className={className}>
                                        {this.#item({ ...child, icon, ellipsis: true })}
                                    </li>
                                );
                            })}
                        </ul>
                    );
                    const subActive = subItems.querySelector('.active');
                    const mainItem = this.#item({
                        ...item,
                        className: ['main-item', subActive && 'sub-active'],
                        expanded: subActive ? true : item.expanded,
                        attrs: { part: 'main-item' },
                    });
                    const itemActive = subActive || mainItem.className.includes('active');
                    if (subActive) activeIcon(subActive);
                    if (itemActive) activeIcon(mainItem);
                    return (
                        <li
                            id={item.id}
                            className="box"
                            part="box"
                            data-active={itemActive ? true : null}
                            onMouseEnter={this.#onShowPop}
                            onMouseLeave={this.#onHidePop}
                            onFocusIn={this.#onFocusIn}
                        >
                            {mainItem}
                            <aui-pop
                                id={item.id + '_pop'}
                                className="layout"
                                arrow={(arrow && Icon.ArrowSize) || null}
                                tryAnchor={item.id || true}
                                {...PopOptions}
                                onShow={this.#onPopShow}
                                onHide={this.#onPopHide}
                            >
                                <div className="layout-box">
                                    <button
                                        type="button"
                                        className={['item-mirror', itemActive && !arrow && 'active']}
                                        tabIndex={-1}
                                        data-interactive={arrow ? null : 'focusable'}
                                        onClick={arrow ? null : this.#onMirrorClick}
                                    >
                                        {item.content}
                                    </button>
                                    {subItems}
                                </div>
                                {useThreshold && <aui-navpanel-threshold item={item} icon={Icon.Threshold} expanded={item.thresholdExpand} />}
                            </aui-pop>
                        </li>
                    );
                })}
            </ul>
        );
    }
    render() {
        const { toggleable, colorScheme, classify } = this.options,
            { Icon, mobileViewEnable, useMobileClose, inGroup, expanded, groupToggleable, mobileView } = this.state,
            data = Array.from(Map.groupBy(this.state.items, ({ group }) => group));
        const className = [colorScheme && 'color-scheme-' + colorScheme, inGroup && 'in-group', mobileView && 'mobile-view'];

        return (
            <nav role="application" className={className} aria-expanded={!!expanded} data-classify={classify}>
                {mobileViewEnable && <aui-backdrop part="none" view="mobile" global="_similar" hidden={!expanded} onClick={this.#onClose} />}
                <div className="navpanel">
                    <div className="header">
                        <slot name="header" />
                        {useMobileClose && (
                            <aui-button-lite id="close" type="plain" tooltip={I18N.close} hidden={!mobileView} onClick={this.#onClose}>
                                <span slot="icon" className={['icon', 'icon-action', Icon.Close]} />
                            </aui-button-lite>
                        )}
                        {toggleable && (
                            <aui-button-lite
                                id="toggle"
                                type="plain"
                                tooltip={expanded ? I18N.collapse : I18N.expand}
                                hidden={useMobileClose && mobileView}
                                aria={{ ariaExpanded: !!expanded }}
                                onClick={this.#onToggle}
                            >
                                <span slot="icon" className={['icon', 'icon-action', Icon.Toggle]} data-expanded={!!expanded} />
                            </aui-button-lite>
                        )}
                    </div>
                    <div className="body" onFocusOut={this.#onFocusOut}>
                        {data.map(([group, items], i) => (
                            <div className="group" role="group">
                                {this.#group(items, [group, groupToggleable, i])}
                            </div>
                        ))}
                    </div>
                    <div className="footer">
                        <slot name="footer" />
                    </div>
                </div>
            </nav>
        );
    }
}

/** @extends {Widget<typeof NavPanelThreshold.options>} */
@define('navpanel-threshold')
export class NavPanelThreshold extends Widget {
    static options = {
        expanded: false,
        icon: Types.string,
        item: Types.object,
    };
    static observers = ['item', 'expanded'];
    static shadow = false;

    init() {
        this.state = {
            expanded: this.options.item.thresholdExpand,
        };
    }
    didRender() {
        this.host.setAttribute('expanded', this.state.expanded);
    }
    setOption(name, value, oldValue) {
        if (name === 'item') {
            this.setState({ expanded: value.thresholdExpand }, false);
        }
    }
    onClick = (e) => {
        const expanded = !this.state.expanded;
        this.options.item.thresholdExpand = expanded;
        this.setState({ expanded });
    };
    render() {
        const { icon, item } = this.options,
            expanded = !!this.state.expanded;

        return (
            <aui-button-lite className="sub-threshold-button" type="link" aria={{ expanded, controls: item.id }} onClick={this.onClick}>
                <span slot="text">{I18N[expanded ? 'showLess' : 'showMore']}</span>
                <span slot="icon-end" className={['icon', 'icon-expanded', icon]} data-expanded={expanded} />
            </aui-button-lite>
        );
    }
}

/** @extends {Widget<typeof NavPanel.options>} */
@define('navpanel')
export class NavPanel extends NavPanelView {
    static options = {
        items: [],
        activeId: Types.string,
        expanded: true,

        colorScheme: Types.Enum(['normal', 'light', 'dark']),
        toggleable: true,
        groupToggleable: Types.Union([Types.boolean, Types.array], false),
        arrow: false,
        classify: Types.Enum(['theme', 'ai']),
        iconClassify: 'unset',
        childrenThreshold: Types.number,
        /** @private */
        skin: Types.string,
        /** @private Enable mobile view when config enabled.  */
        mobileView: true,

        onChange: Types.function,
        onToggle: Types.function,
    };
    static upcasts = ['skin'];
    static observers = ['items', 'activeId', 'expanded'];
    static styles = style;

    init() {
        const { mobileViewEnable, skin } = $$.config(),
            attrSkin = this.host.getAttribute('skin', true),
            _skin = Skins[attrSkin] ? attrSkin : skin;
        const Icon = Icons(_skin);
        for (const x of Object.values(Icon)) {
            if (typeof x === 'string') this.fontIcon(x);
        }

        const { toggleable, mobileView, expanded } = this.options,
            _mobileViewEnable = mobileViewEnable && mobileView && (toggleable || expanded),
            _mobileView = _mobileViewEnable && $$.mobileView;
        this.state = {
            skin: _skin === skin ? null : _skin,
            Icon,
            inGroup: this.$host.closest('.aui-navpanel-groups').get(),
            useMobileClose: false,
            items: null,
            cache: new Map(),
            expanded: !_mobileView && expanded,
            groupToggleable: this.groupToggleable(),
            mobileViewEnable: _mobileViewEnable,
            mobileView: _mobileView,
            mobileEnv: !!$$.mobileEnv,
        };

        this.setItems();
    }

    setItems(value = this.options.items) {
        const { activeId } = this.options;
        this.state.cache.clear();

        let index = 0;
        const idPrefix = 'navpanel-item-',
            itemId = (i = index++) => idPrefix + i;
        let lastActive; // if activeId==null, use the last active item.
        const refreshActive = (item) => {
            if (item.active) {
                const last = lastActive || {};
                last.active = false;
                lastActive = item;
            } else if (activeId) {
                delete item.active;
            } else {
                item.active = false;
            }
            if (item.id) {
                item.id = KebabCase(item.id);
            } else {
                item.id = itemId();
            }
        };

        this.state.items = value.map((item) => {
            const data = {
                expanded: true,
                ...item,
                disabled: item.disabled || false,
                inactive: item.inactive || false,
                thresholdExpand: false,
                original: item,
            };
            refreshActive(data);
            data.children?.forEach(refreshActive);
            return data;
        });
    }
    groupToggleable() {
        const v = this.options.groupToggleable;
        if (!v) return false;
        if (Array.isArray(v)) return v;
        return [];
    }

    didMount() {
        const { mobileViewEnable, expanded } = this.state,
            { parentNode } = this.host;
        if ($(parentNode).css('position') === 'static') parentNode.style.position = 'relative';

        if (mobileViewEnable) {
            this.addGlobalEventListener('ViewChange', () => {
                const v = !!$$.mobileEnv;
                if (this.state.mobileEnv !== v) {
                    this.state.mobileView = $$.mobileView;
                    this.state.mobileEnv = v;
                    if (this.options.toggleable) this.onToggle(!v);
                }
            });
            this.checkInstance(false);
        }
        addTooltip(this.host);
        this.setActive(this.options.activeId);

        if (expanded !== this.options.expanded) {
            setTimeout(() => this.callback('onToggle', expanded)); // defer to wait parent mounted finish.
        }
    }
    didRender() {
        const { skin } = this.state;
        if (skin) this.host.setAttribute('skin', skin);
    }
    setOption(name, value) {
        switch (name) {
            case 'items':
                this.setItems(value);
                return true;
            case 'activeId':
                this.setActive(value);
                return false;
            case 'expanded':
                return this.onToggle(value);
        }
    }
}
