/** @jsxImportSource @gui/aui-devops */
import $ from '../../core/element/index.js';
import { define, Widget, Types } from '../../widget/widget.js';

import stopEvent from '../../util/event/stop.js';
import { splitFiles } from '../../util/io/split-file.js';
import { percentValue } from '../../util/number/percent.js';
import ObjectMerge from '../../util/object/merge.js';

import { alert, confirm } from '../messagedialog/messagedialog.js';

import { defaultFileMaxSize, byte2Size, maxLengthByMultiple, callbackFallback, checkFileType, checkFileSize, FileEntity } from './utils.js';

import style from './picker.less';

const I18N = $$.I18N.uploader;

/** @extends {Widget<typeof Picker.options>} */
@define('uploader-picker')
export class Picker extends Widget {
    static ariaTargetRoot = 'aui-uploader';
    static options = {
        accept: Types.string,
        droppable: Types.Union([Types.string, Types.boolean]),
        fileTypes: ['DOC', 'DOCX', 'HTML', 'PDF', 'PPTX', 'TXT', 'WPD', 'WPS', 'XLS', 'XLSX', 'XML'],
        maxSize: defaultFileMaxSize,
        multiple: Types.Union([Types.boolean, Types.Integer([1])], false),
        pieceSize: Types.Union([Types.number, Types.string], '20MB'),
        showLoading: false,
        skipVerify: Types.EnumList(['sameName', 'fileType', 'zeroSize', 'fileSize', 'overwrite'], []),

        disabled: Types.boolean,
        text: Types.string,
        type: Types.Enum(['button', 'link'], 'link'),

        doUpload: Types.function,
        onChange: Types.function,
        onUpload: Types.function,
        willUpload: Types.function,
    };
    static privateOptions = ['text', 'type'];
    static observers = ['accept', 'disabled', 'fileTypes', 'maxSize'];
    static downstreamContext = ['extend', ['button', 'button-lite'], ['disabled']];
    static styles = style;

    #loading = () => null;
    optionsGetter = {
        disabled: (v) => !!v,
    };
    init() {
        const { multiple } = this.options;
        this.state = {
            uploadingFiles: [],
            currentRequest: new Map(),
            maxLength: maxLengthByMultiple(multiple),
            onUploadHandlers: [],
        };

        this.dispatcher = this.useUnicom(['uploader', 'picker'], this.receiver);
    }
    didMount() {
        this.dispatcher('uploader', 'getService').then((service) => {
            const { loading } = service.loading.init(this.options);
            this.#loading = loading;
        });
    }
    setOption(name, value) {
        switch (name) {
            case 'accept':
            case 'disabled':
                return true;
            case 'fileTypes':
            case 'maxSize':
            case 'multiple':
                this.dispatcher('detail?', 'setDetails', this.options);
                return false;
        }
        return false;
    }

    receiver = (action, from, ...args) => {
        switch (action) {
            case 'initDrop': {
                // Trigger by uploader, called when didMount, for dealing with drop files.
                const [instance, key] = args;
                return this.initDrop(instance, key);
            }
            case 'sliceFiles': {
                // Trigger by uploader, called when files option updated.
                const [files] = args;
                return this.sliceFiles(files);
            }
            case 'abortUpload': {
                // Trigger by Echo, called when delete a uploading file.
                const [file] = args;
                return this.abortUpload(file);
            }
            case 'addOnUploadHandler': {
                // Trigger by any, add a onUpload event listener.
                const [handler] = args;
                return this.state.onUploadHandlers.push(handler);
            }
            case 'onChange': {
                const [files] = args;
                return this.callback('onChange', files);
            }
        }
    };

    /** @param {Widget} instance  */
    initDrop(instance, key) {
        /** matching the query selector in `style.less` of uploader */
        const stateName = 'drag_over',
            { host, $host } = instance;
        //#region DragDrop styles.
        const { droppable } = this.options,
            selector = droppable === true ? 'section' : droppable || null,
            /** @type {CSSStyleSheet} */
            sheet = host.adoptedStyleSheets('styles', key);
        if (!sheet) return this.console.error('StyleSheet not found for drop styles.');
        if (!selector) return sheet.deleteRule(0);
        sheet.cssRules[0].selectorText = `::slotted(${selector})`;
        //#endregion

        //#region DragDrop events.
        let isDragEnter = false;
        const setDragState = (isActive, e) => {
            if (e) stopEvent(e);
            isDragEnter = isActive;
            instance.customState(stateName, isActive);
        };
        /** Drop target element must be direct child of Uploader widget, and match the droppable selector. */
        const dragValid = ({ target, delegateTarget }) => target.parentElement === delegateTarget && $(target).is(selector);

        /**
         * Prevent dragOver default behavior to allow drop file
         * @see {@link https://developer.mozilla.org/en-US/docs/Web/API/HTML_Drag_and_Drop_API#define_a_drop_zone}
         */
        $host.on('dragover', selector, (e) => e.preventDefault());
        $host.on('dragenter', selector, (e) => {
            if (this.options.disabled || !dragValid(e)) return;
            const [...items] = e.dataTransfer.items,
                isFile = items.some((item) => item.kind === 'file');
            if (isFile) setDragState(true);
        });
        $host.on('dragleave', selector, (e) => {
            if (!isDragEnter) return;
            /**
             * - `relatedTarget==null`: drag cancel in descendant element.
             * - `relatedTarget not descendant of target`: drag leave from target element.
             */
            const validLeave = !e.relatedTarget || (dragValid(e) && !$(e.target).contains(e.relatedTarget));
            if (validLeave) setDragState(false, e);
        });
        $host.on('drop', selector, (e) => {
            setDragState(false, e);
            if (this.options.disabled) return;
            const { files } = e.dataTransfer;
            if (files.length) this.uploadNewFiles([...files]);
        });
        //#endregion
    }
    /** @returns {[files: Array<File>, maxLength: number]} */
    sliceFiles(files, start = 0) {
        const { maxLength } = this.state,
            length = maxLength - start,
            list = length > 0 ? files.slice(0, length) : [];
        return [list, maxLength];
    }
    #filterSameName(files, existsFiles) {
        /// For [TPESMS-93222]
        // if ($$.browser.os.name === 'ios' && files.length === 1) {
        //     const file = files[0],
        //         now = Date.now();
        //     if (file.name === 'image.jpg' && now - file.lastModified < 1000) {
        //         return [new File([file], `image-${now}.jpg`, file)];
        //     }
        // }
        return files.filter((file) => existsFiles.every((f) => f.fileName !== file.name));
    }
    uploadNewFiles(files) {
        if (!files?.length || this.options.disabled) return;

        const { multiple, skipVerify } = this.options;
        this.dispatcher('uploader', 'getFiles').then((existsFiles) => {
            const filteredFiles = skipVerify.includes('sameName') ? files : this.#filterSameName(files, existsFiles);
            if (!filteredFiles.length) return alert(true, { classify: 'warn', content: I18N.sameFileName });

            const currentCount = existsFiles.length;
            if (multiple === false) {
                const files = filteredFiles.slice(0, 1);
                /// TD: filter files with all validations
                // (using the first valid file when drop multiple files), But it's no need in other cases.
                return currentCount ? this.doReplace(files, existsFiles) : this.doUpload(files, existsFiles);
            } else {
                const [files] = this.sliceFiles(filteredFiles, currentCount);
                this.doUpload(files, existsFiles);
            }
        });
    }
    handleChange = ({ target }) => {
        const { files } = target;
        this.uploadNewFiles([...files]);
        setTimeout(() => (target.value = ''));
    };

    doReplace(files, existsFiles) {
        const doReplace = () => {
            this.dispatcher('uploader', 'replaceFile', existsFiles).then(() => {
                // Here existsFiles has been replaced(deleted), so real existsFiles is empty.
                this.doUpload(files, []);
            });
        };

        const { skipVerify } = this.options;
        if (skipVerify.includes('overwrite') || existsFiles.every((f) => f.isSucceed === false)) return doReplace();

        const args = { title: I18N.changeFileTitle, content: I18N.changeFileMsg };
        confirm(true, args).then((value) => value && doReplace());
    }
    fileValidation(file) {
        const { skipVerify, fileTypes, maxSize } = this.options;
        if (!skipVerify.includes('zeroSize') && !file.size) return I18N.notZeroKB;
        if (!skipVerify.includes('fileType') && !checkFileType(file, fileTypes)) return I18N.notSupported;
        if (!skipVerify.includes('fileSize')) {
            const valid = checkFileSize(file, maxSize, I18N.exceedMaxFileSize);
            if (typeof valid === 'string') return valid;
        }
        return true;
    }
    abortUpload(file) {
        const { currentRequest } = this.state,
            request = currentRequest.get(file);
        if (!request) return this.console.warn('No uploading request found to abort for file:', file);
        if (typeof request.abort === 'function') {
            currentRequest.delete(file);
            return request.abort();
        }
        const { promise, resolve } = Promise.withResolvers();
        currentRequest.set(file, resolve);
        return promise;
    }
    updateFileProgress(fileData, percent) {
        this.dispatcher('echo?', 'fileProgress', fileData, percent);
    }
    // #parallelUpload() {}
    /** @template T @param {T} fileEntity @param {()=>T|Promise<T>} doUpload */
    async #serialUpload(fileEntity, doUpload) {
        const { pieceSize } = this.options,
            { currentRequest } = this.state,
            pieceList = splitFiles(fileEntity.file, pieceSize),
            totalCount = pieceList.length;

        let fileData = { ...fileEntity }; // break the reference 1.
        const onFailed = (...args) => {
            currentRequest.delete(fileEntity);
            return ObjectMerge(fileData, ...args, { isSucceed: false });
        };
        const checkStatus = () => {
            if (fileEntity.status !== 'uploading') {
                const abortPromise = currentRequest.get(fileEntity);
                if (typeof abortPromise !== 'function') return this.console.throws(fileEntity.status);
                currentRequest.delete(fileEntity);
                abortPromise();
                throw new DOMException('User aborted a request.', 'AbortError');
            }
        };

        for (let i = 0; i < totalCount; i++) {
            checkStatus();

            const filePiece = pieceList[i],
                order = i + 1,
                isLast = order === totalCount;
            if (i > 0) filePiece.set('fileId', fileData.fileId);

            const request = doUpload(filePiece, this.updateFileProgress.bind(this, fileData));
            currentRequest.set(fileEntity, request);
            let result;
            try {
                const data = await this.callbackResult(request),
                    { file } = data; // data maybe contains only isSucceed field.
                if (file?.isSucceed === false && !file.message) file.message = data.message || I18N.uploadFailed;
                result = { ...fileData, ...file }; // break the reference 2.
            } catch (e) {
                if (e.name === 'AbortError') throw e;
                return onFailed({ message: e.message });
            }
            if (isLast && result.isSucceed === false) return onFailed(result);

            fileData = result;
            this.updateFileProgress(fileData, percentValue(order / totalCount));
        }
        checkStatus();
        currentRequest.delete(fileEntity);
        return fileData;
    }
    async #batchUpload(fileEntity, oldFiles) {
        const doUpload = this.options.doUpload || callbackFallback;
        fileEntity.status = 'uploading';
        const result = await this.#serialUpload(fileEntity, doUpload);

        result.status = null;
        const [...uploadedFiles] = oldFiles;
        if (result.isSucceed !== false) {
            result.isSucceed = true;
            result.fileSize = byte2Size(result.size ?? result.fileSize);
            uploadedFiles.push(result);
        }
        return await this.onUpload(result, uploadedFiles);
    }
    doUpload(files, existsFiles) {
        if (!files?.length) return this.console.warn('Non available files.');

        const newFiles = files.map((file) => {
            const valid = this.fileValidation(file),
                { isSucceed, ...entity } = new FileEntity(file);
            if (valid === true) return entity;
            return Object.assign(entity, { isSucceed: false, message: valid });
        });
        this.callbackResult(this.callback('willUpload', newFiles, existsFiles), (willResult) => {
            if (willResult === false) return;

            this.setState({ uploadingFiles: newFiles }, false);
            this.#loading(true);
            const requests = newFiles.map((fileEntity) => {
                if (fileEntity.isSucceed === false) return fileEntity;
                return this.#batchUpload(fileEntity, existsFiles);
            });
            const { maxLength } = this.state;
            this.dispatcher('uploader', 'uploadFiles', newFiles, maxLength).then(() => {
                Promise.allSettled(requests).then((results) => {
                    const fileList = results.flatMap(({ status, value, reason }) => {
                        if (status === 'fulfilled') return value;
                        this.console.error('Upload file failed.', reason);
                        return [];
                    });
                    this.dispatcher('uploader', 'uploadFiles', fileList, maxLength).then((files) => {
                        this.callback('onChange', files);
                        this.#loading(false);
                        this.setState({ uploadingFiles: [] }, false);
                    });
                });
            });
        });
    }
    async onUpload(fileEntity, uploadedFiles) {
        const handlers = this.state.onUploadHandlers;
        let result = fileEntity;
        for (const fn of handlers) {
            result = await this.callbackResult(fn(result) ?? result);
        }
        this.callback('onUpload', { ...result, files: uploadedFiles });
        return result;
    }

    onButtonClick = (e) => {
        stopEvent(e);
        const input = this.renderBox.querySelector('input[type="file"]');
        input.click();
    };

    render() {
        const { accept, droppable, text, type } = this.options,
            disabled = Boolean(this.options.disabled),
            { maxLength } = this.state,
            { touchable } = $$.browser;
        const arias = this.arias({ 'aria-describedby': 'aui-uploader-description' }),
            entry = !droppable || touchable ? '{0}' : maxLength > 1 ? I18N.dragFiles : I18N.dragFile;

        return (
            <aui-i18n entry={entry}>
                <label slot="0">
                    <input type="file" name="file" tabIndex={-1} accept={accept} disabled={disabled} multiple={maxLength > 1} {...arias} onChange={this.handleChange} />
                    <slot onClickCapture={this.onButtonClick}>
                        <aui-button-lite id="button" disabled={disabled} type={type}>
                            <span slot="text">{text || I18N.browse}</span>
                        </aui-button-lite>
                    </slot>
                </label>
            </aui-i18n>
        );
    }
}
