import { warn, error } from '../base/log.js';
import { onload } from '../base/onload.js';
import $ from '../element/index.js';
import { WidgetBase } from '../extend/widget.js';

import arrayDelete from '../../util/array/delete.js';

(function () {
    const { $root } = $;
    const attrName = 'data-aui-close';

    if ($$.browser.os.device === 'desktop' || !$$.browser.touchable) {
        $root.on(`pointerdown wheel`, closeEvent);
        onload(() => {
            const body = $.$body.get();
            body.addEventListener('scroll', (e) => e.target === body && closeEvent(e), true);
        });
    } else if ($$.browser.touchable) {
        $root.on('touchstart', closeEvent);
    }

    const closeCollection = {},
        closeList = [];

    $$.close = function (source) {
        const $source = $(source),
            /** The target is a dialog host widget or not. */
            withinHost = $source.is(':widget') && $source.origin('_')?.role === 'dialog';

        const query = `dialog,[role="dialog"]`,
            $target = withinHost ? $source.find(query, { crossShadow: true }) : $source.closest(query),
            target = $target.get();
        if (target?.localName === 'dialog') {
            const modal = $target.closest('aui-modal').get();
            (modal || target).close();
            return true;
        } else if (target?.hasAttribute('popover')) {
            try {
                target.hidePopover();
                return true;
            } catch (e) {
                error(e);
                return false;
            }
        }
        warn(`Can't find the close target for: `, source);
        return false;
    };
    $$.closeAll = function (includeModal) {
        closeEvent({});
        $root.trigger('CloseAll', false, !!includeModal);
        if (includeModal) {
            $('.aui-modal-box').trigger('Close'); // Compat with CK Editor dialog.
        }
    };

    function closeEvent(e) {
        const $triggers = $(e.target).closest(`[${attrName}]`).filter(':visible'),
            $popup = $triggers.filter('[role="dialog"]');
        let i = 0,
            wheelable = true;

        if (e.type === 'wheel' && $triggers.length > 0) {
            const scrollBox = $(e.target).scrollBox($triggers.get(0)).get();
            wheelable = $$.event.wheelable(scrollBox, e);
        }
        if (wheelable && $triggers.length > 0) {
            const closeId = ($popup.length > 0 ? $popup : $triggers).get().getAttribute(attrName);
            if (closeId) i = closeList.indexOf(closeId);
            if (i < 0) return error('Close execute error, the element disappear in stack!');
            i++;
        }

        for (; i < closeList.length; i++) {
            if (closeItem(closeList[i]) !== false) {
                i--;
            }
        }
    }

    function closeItem(ns, deleteOnly) {
        const obj = closeCollection[ns];
        let result;
        if (!obj) return false;
        if (!deleteOnly && $.$body.contains(obj.$element)) result = obj.$element[obj.name](obj.fnName, false);
        if (result === false) return false;
        obj.popup.removeAttr(attrName);
        obj.source.removeAttr(attrName);
        delete closeCollection[ns];
        arrayDelete(closeList, ns);
    }

    Object.assign(WidgetBase.extends, {
        /** Close callback function name, such as: "hide", set false to disable close system. */
        CloseFn: false,
        /** Call this function when the close-needed element shown. */
        CloseShow: function (popupElement, source) {
            const ns = this.widgetName + this.uuid;
            if (!this.CloseFn || !!closeCollection[ns]) return;
            closeCollection[ns] = {
                name: this.widgetName,
                fnName: this.CloseFn,
                source: (source || this.$element).attr(attrName, ns),
                $element: this.$element,
                popup: popupElement.attr(attrName, ns),
            };
            if (closeList.includes(ns)) arrayDelete(closeList, ns);
            closeList.push(ns);
        },
        CloseHide: function () {
            const ns = this.widgetName + this.uuid;
            if (!this.CloseFn || !closeCollection[ns]) return;
            closeItem(ns, true);
        },
    });
})();
