/** @jsxImportSource @gui/aui-devops */
import { listenConfig } from '../../core/base/config.js';
import { log, throws } from '../../core/base/log.js';
import { define, Widget, Types } from '../../widget/widget.js';

import absoluteColor from '../../util/css/absolute-color.js';
import blobUrl from '../../util/io/blob-url.js';

import dotWorker from './dot.worker.js';

import style from './dot.less';

const ColorEffects = 6;
function ColorMap(host, count) {
    const style = getComputedStyle(host);
    let invalid = false;
    const colorMap = Array.from({ length: ColorEffects + 1 }, (_, i) => {
        const color = absoluteColor(style.getPropertyValue(`--color-${i}`), 'hex');
        if (color.startsWith('#')) {
            if (color.length === 7) return color;
            const [_, r, g, b] = color;
            return '#' + r + r + g + g + b + b;
        }
        invalid = true;
        return '';
    });
    if (invalid) {
        log(host, style);
        throws('Color mapping calculation failed.');
    }

    const startColor = colorMap[0],
        defaultColor = colorMap[1];
    /** Using 2/3 items to animate, max count is count-2 (one for startColor, one for defaultColor). */
    const length = Math.min(ColorEffects, Math.floor((count * 2) / 3), count - 2),
        colors = Array.from({ length }, (_, i) => colorMap[ColorEffects - i]); // from ColorEffects(6) to 1
    return { defaultColor, colors: [startColor, ...colors] };
}

const WorkerMap = new Map(),
    workerUrl = blobUrl(dotWorker);

listenConfig(true, function (k, v) {
    if (k === 'theme') {
        for (const data of WorkerMap.values()) setTheme(data);
    }
});

function setTheme({ worker, host, args }) {
    const { colors, defaultColor } = ColorMap(host, args.count);
    worker.postMessage({ type: 'theme', colors, defaultColor });
}
function GetOrNewWorker(name, uuid, host, args) {
    if (WorkerMap.has(name)) {
        const { worker, store } = WorkerMap.get(name);
        store.add(uuid);
        return worker;
    }
    const worker = new Worker(workerUrl, { name: `loading-animation-${name}` }),
        data = { worker, host, args, store: new Set([uuid]) };
    setTheme(data);
    worker.postMessage({ type: 'create', size: 8, gap: 8, ...args });
    WorkerMap.set(name, data);
    return worker;
}
function PopWorker(name, uuid) {
    if (!WorkerMap.has(name)) return;
    const { worker, store } = WorkerMap.get(name);
    store.delete(uuid);
    if (!store.size) {
        worker.terminate();
        WorkerMap.delete(name);
    }
    if (!WorkerMap.size) {
        URL.revokeObjectURL(workerUrl);
    }
}

/**
 * Important: need a explicit `hidden` attribute toggle when the loading is shown/hidden.
 * @extends {Widget<typeof LoadingDot.options>}
 */
@define('loading-dot')
export class LoadingDot extends Widget {
    static options = {
        name: Types.string,
        count: Types.Integer([3], 9),
        duration: Types.Integer([0], 2000),
    };
    static styles = style;

    #timer = null;
    init() {
        const { name, count, duration } = this.options,
            _name = name || this.uuid,
            worker = GetOrNewWorker(_name, this.uuid, this.host, { count, duration });
        this.state = { name: _name, worker };
    }
    didMount() {
        const { worker } = this.state,
            canvas = this.element.transferControlToOffscreen();
        worker.postMessage({ type: 'init', canvas, uid: this.uuid }, [canvas]);
        this.onHiddenToggle(this.host.hasAttribute('hidden'));
    }
    didUnmount() {
        PopWorker(this.state.name, this.uuid);
        this.state.worker = null;
    }
    onHiddenToggle(v) {
        return v ? this.#stopAnimation() : this.#startAnimation();
    }
    #startAnimation() {
        clearTimeout(this.#timer);
        this.state.worker.postMessage({ type: 'start', uid: this.uuid });
    }
    #stopAnimation() {
        clearTimeout(this.#timer);
        // Add a timer to wait for main thread idle (The loading hidden finished).
        this.#timer = setTimeout(() => this.state.worker.postMessage({ type: 'stop', uid: this.uuid }));
    }
    render() {
        return <canvas width="1" height="1" />;
    }
}
