import { log, error } from '../../core/base/log.js';

import getData from './get-data.js';

const { find } = Array.prototype;

export default function realClassRule(selector, prop) {
    const sheet = this instanceof RegExp ? this : /aui(\.min)?\.css(\?.+)?$/,
        styleSheet = find.call(document.styleSheets, (s) => s.href?.match(sheet));
    if (!styleSheet) return log(`The query regexp sheet isn't exists.`);

    try {
        const rules = styleSheet.cssRules,
            rule = find.call(rules, (r) => r.selectorText?.split(',').includes(selector));
        if (!rule?.style) return null;
        if (prop) return rule.style[prop] || null;
        return getData(rule.style);
    } catch (e) {
        error(e);
    }
}
