/** @type {typeof $$.string.size2px} */
export default function size2px(size) {
    const { x: dpiX, y: dpiY } = $$.dpi,
        dpi = dpiX === dpiY ? dpiX : (dpiX + dpiY) / 2;
    let num = Number.parseFloat(size);
    // eslint-disable-next-line eqeqeq
    if (num != size) {
        if (size.endsWith('in')) {
            num *= dpi;
        } else if (size.endsWith('pt')) {
            num *= dpi / 72;
        }
    }
    return Number.isNaN(num) ? null : num + 'px';
}
