/** @jsxImportSource @gui/aui-devops */
import { addTooltip, tooltipAttr } from '../../core/module/tooltip.js';
import { define, Widget, Types, inherit } from '../../widget/widget.js';

import cssZindex from '../../util/css/zindex.js';

import { Avatar } from '../avatar/avatar.js';

import style from './style.less';

const { options, observers, forwardOptions } = inherit(Avatar, null, ['tooltip']);

/** @extends {Widget<typeof Profile.options>} */
@define('profile')
export class Profile extends Widget {
    static options = {
        ...options,
        tooltip: Types.Union([Types.string, Types.boolean]),

        sub: Types.string,
        popup: Types.string,
    };
    static styles = style;
    static observers = [...observers, 'sub', 'tooltip'];
    static requires = ['name'];
    static useOptionsStore = true;

    didMount() {
        setTimeout(() => this.initPopup(this.options.popup));
        addTooltip(this.host);
    }
    didUnmount() {
        if (this.host.isConnected) this.reset();
    }
    reset = () => {};
    initPopup(popup) {
        if (!popup) return null;
        const target = $$.getUniqueElement(popup);
        if (!target) return this.console.error(`The popup with id: ${popup} isn't exists!`);
        const invoke = (...args) => jQuery(target).popup(...args),
            { triggerEvent, willShow } = invoke('instance').options;
        let isShow = false;
        const reset = (_x) => invoke('option', { willShow });
        this.reset = reset;
        const show = (method) => {
            invoke('option', 'willShow', () => {
                reset();
                willShow(this._stores);
            });
            invoke('hide');
            invoke(method, this.host);
            isShow = true;
        };
        const hide = (method) => {
            invoke(method);
            reset();
            isShow = false;
        };
        invoke('option', { dynamicSize: true, zIndex: cssZindex('popup', 'extend') });
        if ((!triggerEvent || triggerEvent === 'hover') && !$$.browser.touchable) {
            invoke('option', { focusable: false });
            this.host.addEventListener('mouseenter', (e) => show('hoverShow'));
            target.addEventListener('mouseleave', (e) => reset(invoke('hide')));
            this.host.addEventListener('mouseleave', (e) => hide('hoverHide'));
            this.host.addEventListener('pointerdown', (e) => reset(invoke('hide')));
        } else {
            this.host.addEventListener('click', (e) => (isShow ? hide('hide') : show('show')));
        }
    }

    render() {
        const { name, sub, size, popup, tooltip, ...args } = this.options,
            _size = size || (sub ? 'm' : 's'),
            avatarOptions = forwardOptions(args);
        return (
            <>
                <section id="avatar">
                    <aui-avatar name={name} {...avatarOptions} size={_size} />
                </section>
                <div id="name" data-size={_size} {...tooltipAttr(!popup && (tooltip || 'ifneed'))}>
                    {name}
                </div>
                {sub && (
                    <div id="sub" data-tooltip="ifneed">
                        {sub}
                    </div>
                )}
            </>
        );
    }
}
