import isLike from './is-like.js';

function loop(array, cb) {
    if (isLike(array)) {
        let o = 0;
        for (const item of array) {
            const i = o++;
            cb(item, i, o);
        }
    }
}

/** @type {typeof $$.array.map} */
export function map(array, callback) {
    const arr = [];
    loop(array, (item, i, o) => {
        const result = callback(item, i, o);
        arr.push(result);
    });
    return arr;
}
/** @type {typeof $$.array.flatMap} */
export function flatMap(array, callback) {
    let arr = [];
    loop(array, (item, i, o) => {
        const result = callback(item, i, o);
        arr = arr.concat(result);
    });
    return arr;
}
