import { log, info, error } from '../../core/base/log.js';

import fileByte2Size from '../string/file-byte2size.js';
import fileSize2Byte from '../string/file-size2byte.js';

const byte2Size = (v) => fileByte2Size(v, 2, ' ');
const vMB = 1024 * 1024;

/** @returns {number} uint(B) */
function convertSize(pieceSize) {
    let value = pieceSize ?? (window.CommonUtil?.uploadFileSplitCount || 20);
    value = typeof value === 'number' ? value * vMB : fileSize2Byte(value);
    if (Number.isSafeInteger(value)) return value;
    error('Incorrect pieceSize.', pieceSize);
    return 0;
}

function verifyArgs(file, pieceSize) {
    if (file) {
        const blockSize = convertSize(pieceSize),
            totalCount = (blockSize > 0 && Math.ceil(file.size / blockSize)) || 1;
        return { blockSize, totalCount };
    } else {
        error('Incorrect file (index), it must not be null.');
    }
    return {};
}

function fileData(file, blockSize, index, totalCount) {
    const { name, size, type } = file;
    // Calculate start and end positions of each piece
    const multiple = totalCount > 1,
        start = index * blockSize,
        end = multiple ? Math.min(size, start + blockSize) : size;
    // Slice the file into smaller pieces by Blob.prototype.slice
    const piece = file.slice(start, end, type);

    if (index === 0) {
        const fn = multiple ? info : log;
        fn(`Splitting file into <${totalCount}> pieces:`, name, `fileSize: <${byte2Size(size)}>`, `pieceSize: <${byte2Size(blockSize)}>`);
    }
    const data = new FormData();
    // The slice method is used to cut out part of a file
    data.append('file', piece, name);
    data.append('fileName', name);
    data.append('fileId', '');
    data.append('totalCount', totalCount);
    data.append('index', index);
    data.append('order', index + 1);
    return data;
}

/** @type {typeof $$.io.splitFile} */
export function splitFile(file, fileIndex, pieceSize, fileId) {
    const { blockSize, totalCount } = verifyArgs(file, pieceSize);
    if (!totalCount || fileIndex < 0 || fileIndex >= totalCount) return null;

    const data = fileData(file, blockSize, fileIndex, totalCount);
    if (fileId) data.set('fileId', fileId);
    return data;
}

/** @type {typeof $$.io.splitFiles} */
export function splitFiles(file, pieceSize) {
    const { blockSize, totalCount } = verifyArgs(file, pieceSize);
    if (!totalCount) return [];

    return Array.from({ length: totalCount }).map((_, index) => fileData(file, blockSize, index, totalCount));
}
