/** @jsxImportSource @gui/aui-devops */
import { Options as ButtonOptions } from '../../widget/form/button-util.js';
import { define, Widget, Types, inherit } from '../../widget/widget.js';

import objectFilter from '../../util/object/filter.js';

import { Pop } from '../popup/pop.js';

import style from './style.less';

const { options: popOptions } = inherit(Pop, ['classify', 'position', 'width', 'height']);

/** @extends {Widget<typeof Popover.options>} */
@define('popover')
export class Popover extends Widget {
    static options = {
        ...popOptions,
        triggerEvent: Types.Enum(['click', 'hover'], 'click'),
        disabled: false,
    };
    static observers = ['classify', 'disabled'];
    static styles = style;
    // static internals = { role: 'dialog' };

    initPopup(popup) {
        const { width, height, position, disabled } = this.options,
            { classify, triggerEvent } = this.eventAttrs(disabled),
            args = { width, height, position, classify, triggerEvent };
        popup.setOptions({ delegate: 'slot[name="trigger"]', eventScope: 'parent', arrow: !disabled, mobileView: false, modalable: false, ...args });
    }
    eventAttrs(disabled) {
        if (disabled) return { triggerEvent: 'hover:0', classify: 'gray' };
        let { classify, triggerEvent } = this.options;
        if (triggerEvent === 'hover') triggerEvent = 'hover:0';
        return { classify, triggerEvent };
    }
    updatePopup(...args) {
        const { popup } = this.refs;
        if (popup) {
            popup.setOptions(...args);
        } else {
            this.console.error(...args);
        }
    }
    didMount() {
        const trigger = this.shadowRoot.querySelector('slot[name="trigger"]').assignedNodes();
        if (!trigger?.length) this.console.error('Popover needs a slot="trigger" element at least.');
    }
    setOption(name, value) {
        switch (name) {
            case 'width':
            case 'height':
            case 'classify':
                this.updatePopup({ [name]: value });
                return false;
            case 'disabled': {
                const { classify, triggerEvent } = this.eventAttrs(value);
                this.updatePopup({ classify, triggerEvent, arrow: !value }, true);
                return false;
            }
        }
    }
    render() {
        return (
            <aui-popover-button style={{ display: 'contents' }}>
                <slot name="trigger" />
                <aui-pop ref={this.ref('popup', this.initPopup)}>
                    <slot className="content" />
                </aui-pop>
            </aui-popover-button>
        );
    }
}

const ControlledButtonOptions = ['align', 'block', 'type', 'weight'],
    buttonOptions = objectFilter(ButtonOptions, ControlledButtonOptions);
@define('popover-button')
export class PopoverButton extends Widget {
    static options = {
        ...buttonOptions,
    };
    static shadow = false;
    static ownContents = false;
    static observers = ControlledButtonOptions;
    static downstreamContext = ['inherit', ['button'], ControlledButtonOptions];
}
