import classRule from '../css/class-rule.js';
import getValue from '../css/get-value.js';

/** @type {typeof $$.img.cssBase64Value} */
export default function cssBase64Value(name) {
    let img = name.indexOf('--') === 0 ? getValue(name) : classRule(name, 'content', '::before');
    img = img.replace(/\s*url\(("|')?\s*/, '').replace(/("|')?\)\s*$/, '');
    return img.trim();
}
