import { customStateMatch } from '../../util/css/custom-state.js';
import { emptyObject } from '../../util/type/types.js';

export const state = customStateMatch;

export const dir = (function (dirSupport) {
    return function (element, arg) {
        if (dirSupport) return element.matches(`:dir(${arg})`);
        return arg !== 'rtl';
    };
})(CSS.supports('selector(:dir(rtl))'));

export function data(element) {
    return !emptyObject(element.dataset);
}

/** @param {Element} element */
export function widget(element) {
    return element.localName.startsWith('aui-') && element.matches(':defined');
}

export function visible(element, args) {
    if (typeof args !== 'object') args = null;
    /** @param {Element} node */
    const checkVisibility = (node) => {
        if (node.nodeType === Node.TEXT_NODE) return node.isConnected;
        if (node.nodeType !== Node.ELEMENT_NODE) return false;
        return node.checkVisibility(args) || element.dataset.interactive === 'visible';
    };
    if (element.localName === 'slot') {
        const assigned = Array.from(element.assignedNodes({ flatten: true }));
        if (assigned.length) return assigned.some(checkVisibility);
    }
    return checkVisibility(element);
}

/** @param {Element} element */
export function disable(element) {
    return (
        element.ariaDisabled === 'true' ||
        element.dataset.disabled === 'true' ||
        element.classList.contains('disabled') ||
        element.matches(':disabled') ||
        !['false', null].includes(element.getAttribute('disabled')) ||
        customStateMatch(element, 'disabled')
    );
}

export function toplayer(element) {
    return element.matches(':modal, :popover-open, dialog.global');
}

/**
 * Rules come from HTML specification, and:
 * - draggable elements are not focusable.
 * - Extends audio and video, they maybe focusable by testing.
 * @see {@link https://html.spec.whatwg.org/multipage/interaction.html#attr-tabindex}
 * @param {HTMLElement} element
 */
function isFocusable(element, tabIndex, disabledCheck) {
    switch (element.localName) {
        case 'a':
            // valid link or with tabindex
            return !!element.href || (tabIndex != null && tabIndex >= 0);
        case 'input':
            // input[type="hidden"] is not focusable, other types may be focusable
            if (element.type === 'hidden') return false;
        // fallthrough
        case 'button':
        case 'select':
        case 'textarea':
            // form elements, disabled (or disable by fieldset) ones are not focusable
            return disabledCheck === false || (!element.disabled && !element.closest('fieldset')?.disabled);
        case 'summary':
            // only non-empty first-child of details is focusable
            return element.matches('details>summary:first-child:not(:empty)');
        case 'iframe': // Navigable containers
        case 'object':
            // pass through focus to content
            return true;
        case 'area':
            // only valid area is focusable
            return element.matches('map[name]>area[href]');
        case 'audio':
        case 'video':
            // only with controls media elements is focusable, and the source must be valid (no error)
            return !!element.controls && !element.error;
        default:
            // Editing hosts or hasTabindex for other elements
            return element.isContentEditable || tabIndex != null;
    }
}
export function focusable(element, disabledCheck) {
    const tabIndex = element.getAttribute('tabindex');
    if (tabIndex < -1) return false;
    return element.dataset.interactive === 'focusable' || customStateMatch(element, 'focusable') || isFocusable(element, tabIndex, disabledCheck);
}

export function tabbable(element, disabledCheck) {
    if (!visible(element)) return false;
    const tabIndex = element.getAttribute('tabindex');
    if (tabIndex < 0) return false;
    return element.dataset.interactive === 'tabbable' || customStateMatch(element, 'tabbable') || isFocusable(element, tabIndex, disabledCheck);
}

/** Whether the element contains arrow key interactions (includes editable elements and other elements which has arrow key interactions). */
export const moveable = (function (moveableTypes) {
    return function (element) {
        if (element.matches(':read-write')) return true;
        if (element.localName !== 'input' || element.disabled || element.readOnly) return false;
        return moveableTypes.has(element.type);
    };
})(new Set(['radio', 'range']));

export function scrollable(element, scrollPotential, includeHidden) {
    const root = document.scrollingElement || document.documentElement,
        isRoot = element === root;
    const cssOverflow = (v) => v === 'auto' || v === 'scroll' || (includeHidden && v === 'hidden') || (isRoot && v === 'visible');
    /** @returns {boolean} */
    function check(el, isRoot) {
        if (!el) return false;
        if ((scrollPotential && el.nodeName !== 'BODY') || el.clientHeight < el.scrollHeight || el.clientWidth < el.scrollWidth) {
            if (isRoot) return true;
            const { overflowX, overflowY } = getComputedStyle(el);
            return cssOverflow(overflowY) || cssOverflow(overflowX) || check(el.ownerDocument?.defaultView?.frameElement, true);
        }
        return false;
    }
    return check(element, isRoot);
}

// only for debug and testing, don't use in production code.
export const uid = function (element, arg) {
    const v = Element.prototype.getAttribute.call(element, 'u:id');
    return arg == null || arg === '' ? v != null : String(arg) === v;
};

