import { Widget, Types } from '../widget.js';

import eventIsKey from '../../util/event/is-key.js';
import stopEvent from '../../util/event/stop.js';

const CommonOptions = {
    classify: Types.Enum(['default', 'theme', 'alt', 'blank', 'info', 'warn', 'error', 'success', 'ai'], 'default'),
    primary: false,
    icon: Types.string,
    text: Types.string,
    tooltip: Types.string,

    disabled: false,
    readonly: false,
    name: Types.string,
    value: Types.string,
};
export const Options = {
    ...CommonOptions,
    type: Types.Enum(['button', 'submit', 'bald', 'link', 'plain', 'round', 'icon'], 'button'),
    attrs: Types.object,

    align: Types.Enum(['start', 'center', 'end'], 'center'),
    block: false,
    ghost: false,
    round: false,
    shrink: Types.Enum(['xs', 's', 'm']),
    size: Types.string,
    weight: Types.Enum(['light', 'regular', 'semibold', 'bold', 'extrabold'], 'semibold'),

    onClick: Types.function,
};

export class ButtonWidget extends Widget {
    static observers = ['type', 'classify', 'primary', 'icon', 'text', 'tooltip', 'disabled', 'readonly', 'name', 'value', 'attrs'];
    static upcasts = ['block'];
    static ariaTarget = 'button';

    #enterPressed = false;
    #pseudoActive(v) {
        this.customState('button_pseudo_active', v);
    }
    onKeyDown = (e) => {
        const isEnter = eventIsKey(e, 'Enter');
        this.#enterPressed = isEnter;
        this.#pseudoActive(isEnter);
        if (isEnter) {
            e.preventDefault();
        }
    };
    onKeyUp = (e) => {
        this.#pseudoActive(false);
        if (this.#enterPressed && eventIsKey(e, 'Enter')) {
            this.#enterPressed = false;
            this.element.click();
        }
    };
    onClick = (e) => {
        if (this.options.disabled) return stopEvent(e);
        this.callback('onClick', e);
    };

    #getClassName() {
        const { type, primary, ghost, round } = this.options;
        return ['button', `button-${type}`, ghost && 'button-ghost', primary && 'button-primary', round && 'button-round'];
    }
    attributes() {
        const OriginalTypes = ['button', 'submit', 'reset'];
        const { type, classify, text, tooltip, disabled, readonly, name, value, attrs, align, shrink, size, weight } = this.options,
            iconOnly = type === 'icon',
            label = tooltip || (iconOnly && text) || null;
        const data = { shrink, size, classify, tooltip: iconOnly && label ? true : tooltip ? 'diffneed' : 'ifneed' },
            style = { ...attrs?.style, '--align-inline': iconOnly ? null : align, '--font-weight': `var(--font-${weight})` };
        return {
            name,
            value,
            disabled,
            type: OriginalTypes.includes(type) ? type : 'button',
            ...attrs,
            className: this.#getClassName(),
            tabIndex: readonly ? -1 : 0,
            data,
            ...this.arias({ label, disabled }),
            style,
            onClick: this.onClick,
            onKeyDown: this.onKeyDown,
            onKeyUp: this.onKeyUp,
        };
    }
}
