/** @jsxImportSource @gui/aui-devops */
import $ from '../../core/element/index.js';
import { define, Widget, Types, AttrIdName } from '../../widget/widget.js';

import { Overflow } from './overflow.js';

/** @extends {Widget<typeof ButtonFitbox.options>} */
@define('button-fitbox')
export class ButtonFitbox extends Overflow {
    static options = {
        align: Types.Enum(['start', 'end'], 'start'),
    };

    init() {
        super.init();
        Object.assign(this.state, {
            hiddenStart: -1,
            translate: 0,
        });
    }

    clearOverflow() {
        const { align } = this.options;
        this.dynamicStyle(`.box{justify-content:${align};}`);
    }
    setOverflow(boxSize, mainSize) {
        const { gap, moreSize } = this.state,
            available = boxSize - moreSize,
            children = this.getChildren();
        let hiddenStart = 0,
            sizeSum = 0;
        for (const child of children) {
            const currentSum = sizeSum;
            sizeSum += this.getSize(child);
            if (sizeSum > available) {
                const translate = available - currentSum;
                return this.doChange(hiddenStart, translate);
            }
            sizeSum += gap;
            hiddenStart++;
        }
    }
    doChange(hiddenStart, translate) {
        const selector = hiddenStart === 0 ? '*' : `:nth-child(n+${hiddenStart + 1})`,
            styles = [];
        styles.push(`.main::slotted(${selector}){${this.hiddenItemStyle}}`);
        if (translate > 0 && this.options.align === 'end') styles.push(`.box{padding-inline-start:${translate}px !important;}`);

        this.dynamicStyle(styles.join(' '));
        this.setState({ hiddenStart, translate, overflow: true }, !this.state.overflow);
    }

    onMenuItemClick(eventPath) {
        const $eventPath = $(eventPath),
            $active = $eventPath.filter(':focusable');
        if (!$active.length) return false;
        const $nested = $eventPath.filter('aui-popover,aui-button-group');
        return !$nested.length;
    }

    onMoreClick() {
        const { hiddenStart } = this.state;
        if (hiddenStart < 0) return false;

        const children = this.getChildren(),
            list = [];
        for (let i = Math.max(0, hiddenStart); i < children.length; i++) {
            const cloned = this.cloneChild(children[i]);
            list.push(this.menuItem(cloned, i));
        }
        this.setMenuList(...list);
        return true;
    }

    /** @see [CloneChild](README.md) in `README.md` for details. */
    cloneChild(child) {
        const copy = child.cloneNode(true),
            mapping = new Map(),
            cloneIdAttr = 'data-clone-of';
        const loop = (el, cb) => $(el).findAll(':widget', { matchSelf: true }).forEach(cb);
        loop(copy, (el) => {
            const id = el.getAttribute(AttrIdName);
            mapping.set(id, el);
            el.setAttribute(cloneIdAttr, id);
            el.removeAttribute(AttrIdName);
        });
        const cloned = copy.cloneNode(true);
        loop(cloned, (el) => {
            const id = el.getAttribute(cloneIdAttr),
                source = mapping.get(id);
            el.mergeWith(source);
            el.removeAttribute(cloneIdAttr);
        });
        return cloned;
    }
}
