import { I18N } from '../../core/base/i18n.js';
import { error } from '../../core/base/log.js';

import converter from './converter.js';

/** @type {typeof $$.date.parseDuration} */
export default function parseDuration(d) {
    const _I18N = I18N.core.duration;
    let ms = 0;
    try {
        const num = Number.parseFloat(d),
            unit = d.split(num)[1].trim();
        switch (unit) {
            case _I18N.ms:
                ms = num;
                break;
            case _I18N.second:
                ms = num * converter.second;
                break;
            case _I18N.min:
                ms = num * converter.min;
                break;
            case _I18N.hour:
                ms = num * converter.hour;
                break;
            case _I18N.day:
                ms = num * converter.day;
                break;
            case _I18N.week:
                ms = num * converter.week;
                break;
        }
    } catch (e) {
        error('parseDuration error:', e);
    }

    return ms;
}
