import kebabCase from '../string/kebab-case.js';
import { isNumber } from '../type/types.js';

const NumberProps = new Set([
    'animation-iteration-count',
    'column-count',
    'fill-opacity',
    'flex',
    'flex-grow',
    'flex-shrink',
    'font-weight',
    'grid-area',
    'grid-column',
    'grid-column-end',
    'grid-column-start',
    'grid-row',
    'grid-row-end',
    'grid-row-start',
    'line-height',
    'opacity',
    'order',
    'orphans',
    'widows',
    'z-index',
    'zoom',
]);

/** @param {string} value */
function parseValue(k, value, useComputed) {
    const { style } = document.createElement('div');
    style[k] = value;
    const computed = style.getPropertyValue(k);
    if (computed == null || computed === '') return null;
    if (value === computed) return value;
    if (!useComputed) return value;
    if (/^calc\((\d{1,10}(?:\.\d{1,9})?(?:px|%))\)$/.test(computed)) return RegExp.$1;
    return computed;
}

/** @type {typeof $$.css.valid} */
export default function valid(prop, value, args = {}) {
    if (value == null || value === '' || value === false) return null;

    const { checkValue = true, useComputed = false, useVariable = true } = args;
    if (useVariable !== false && /^var\(--[a-z][a-z\d\-]*\)$/.test(String(value))) return value;
    const k = kebabCase(prop),
        nonNumberProp = !NumberProps.has(k);
    if (nonNumberProp && isNumber(value)) value += 'px';

    const result = checkValue ? parseValue(k, value, useComputed) : value;
    if (result == null) return null;
    if (nonNumberProp) return result;
    const num = Number(result);
    return Number.isNaN(num) ? null : num;
}
