/** @jsxImportSource @gui/aui-devops */
import { resize as resizeObserver } from '../../core/module/observer/observer.js';
import { tooltipAttr, addTooltip } from '../../core/module/tooltip.js';
import { define, Widget, Types } from '../../widget/widget.js';

import style from './style.less';

const I18N = $$.I18N.ellipsis;

/** @extends {Widget<typeof Ellipsis.options>} */
@define('ellipsis')
export class Ellipsis extends Widget {
    static options = {
        row: 3,
        tooltip: Types.Union([Types.boolean, Types.string]),
        action: false,
        fixedSize: false,
    };
    static styles = style;
    static observers = ['row', 'tooltip'];

    init() {
        this.state = {
            showAll: false,
            overflow: false,
        };
    }
    didMount() {
        const { action, fixedSize, tooltip } = this.options;
        if (action) {
            this.update();
            if (!fixedSize) this.resizeObserver();
            this.slotContentObserver();
        }
        if (tooltip !== false) addTooltip(this.host);
    }

    update = () => {
        if (!this.state.showAll) {
            this.setState({ overflow: this.$element.textOverflow() });
        }
    };

    resizeObserver() {
        resizeObserver(this.element, this.update, { width: true });
    }

    slotContentObserver = () => {
        this.observer = new MutationObserver(() => {
            this.setState({ showAll: false });
            this.update();
        });
        this.observer.observe(this.host, { childList: true, characterData: true, subtree: true });
    };

    toggle = () => {
        const { showAll } = this.state;
        this.setState({ showAll: !showAll });
    };

    render() {
        const { row, tooltip, action } = this.options,
            { showAll, overflow } = this.state;
        const args = showAll ? {} : { tabIndex: -1, style: { '--ellipsis-row': row } };
        return (
            <>
                <div className="box" {...tooltipAttr(tooltip ?? 'ifneed', 'description')}>
                    <slot {...args} />
                </div>
                {action && (
                    <div className="text-end">
                        {overflow && (
                            <button type="button" onClick={this.toggle}>
                                {showAll ? I18N.showLess : I18N.showMore}
                            </button>
                        )}
                    </div>
                )}
            </>
        );
    }
}
