import React, { PureComponent } from 'react';
import { createPortal } from 'react-dom';

import { UIComponent } from '../../core/base/component.jsx';
import { error } from '../../core/base/log.js';

import objectFilter from '../../util/object/filter.js';

const Events = (events) => objectFilter(events, /^on[A-Z][a-zA-Z]+$/);
export class Popup extends UIComponent {
    static defaultProps = {
        status: { show: false },
    };
    widgetName = 'popup';
    hideControl = 'onHide';

    widgetArgs() {
        return {
            asyncRender: this.props.destroy === true,
            toggleStatus: (status) => {
                this.setState({ status: { show: status } });
            },
        };
    }
    componentCreate() {
        this.state = {
            status: { show: false },
        };
    }
    show(ofElement) {
        return this.method('show', ofElement);
    }
    hide() {
        return this.method('hide');
    }
    hoverShow(ofElement) {
        return this.method('hoverShow', ofElement);
    }
    hoverHide() {
        return this.method('hoverHide');
    }
    toggle(isShow, ofElement) {
        return this.method('toggle', isShow, ofElement);
    }
    setPosition() {
        return this.method('setPosition');
    }
    doRender(element) {
        return this.props.global === false ? element : createPortal(element, document.body);
    }
    render() {
        const { children, events } = this.props;
        return this.doRender(<div {...Events(events)}>{children}</div>);
    }
    destroyRender() {
        let body = $$.shell.flatArray(this.props.children);
        if (body.length !== 1) return error('Popup root children must be only one element');

        body = body[0];
        const { events } = this.props,
            isShow = this.state.status.show !== false,
            { children, ...args } = body.props,
            BodyTag = body.type;
        return this.doRender(
            <div {...Events(events)}>
                <BodyTag {...args} data-destroy={isShow ? null : true}>
                    {isShow && children}
                </BodyTag>
            </div>
        );
    }
}

class PopupContent extends PureComponent {
    render() {
        const { children, ...args } = this.props;
        return (
            <div className="aui-popup-content" {...args}>
                {children}
            </div>
        );
    }
}

$$.shell.define('Popup', Popup);
$$.shell.define('PopupContent', PopupContent);
