/** @jsxImportSource @gui/aui-devops */
import { onloading, idleLoad } from '../../core/base/onload.js';
import $ from '../../core/element/index.js';
import '../../core/extend/focus.js';
import { FocusPush, FocusPop } from '../../core/module/stack-focus/stack-focus.js';
import { addTopLayerListener } from '../../core/module/stack-focus/toplayer.js';
import { define, Widget, Types } from '../../widget/widget.js';

import { map as arrayMap } from '../../util/array/map.js';
import cssZindex from '../../util/css/zindex.js';
import { keyName } from '../../util/event/key-name.js';
import stopEvent from '../../util/event/stop.js';
import objectExtendScope from '../../util/object/extend-scope.js';
import { isElement as typeIsElement, isNumber as typeIsNumber } from '../../util/type/types.js';

import '../backdrop/backdrop.js';

import './dot.js';

import style from './style.less';

/** @see [extended:focus](../../core/extend/focus.js) */
const IOS = $$.browser.touchable && $$.browser.name === 'safari';
const I18N = $$.I18N.loading;
const GlobalLoading = <aui-loading />;
onloading(() => $.$body.get().append(GlobalLoading));
const DefaultShowArgs = { text: null, delay: false, focus: true, focusScroll: false, zIndex: null },
    DefaultHideArgs = { delay: false, focusScroll: false, focusBack: false, force: false, destroy: false },
    DefaultArgs = { ...DefaultShowArgs, ...DefaultHideArgs };

function parseArgs(isShow, args) {
    const { ...data } = isShow ? DefaultShowArgs : DefaultHideArgs;
    if (typeof args === 'string') {
        data.text = args;
    } else if (args) {
        objectExtendScope(data, args);
    }
    return data;
}

export function loading(isShow, args) {
    return GlobalLoading.method('toggle', isShow, parseArgs(isShow, args));
}

export function elementLoading(query, isShow, args) {
    const element = $$.getUniqueElement(query);
    if (element) {
        const $element = $(element);
        let loading = $element.is('aui-loading') || $element.child('aui-loading').get();
        if (!loading) {
            loading = <aui-loading />;
            if ($element.css('position') === 'static') $element.css('position', 'relative');
            $element.append(loading);
        }
        return loading.method('toggle', isShow, parseArgs(isShow, args));
    }
}

Object.assign($$, { loading, elementLoading });

/** @extends {Widget<typeof Loading.options>} */
@define('loading')
export class Loading extends Widget {
    static options = {
        persistent: Types.string,
    };
    static styles = style;
    static shadow = { delegatesFocus: true };

    #cache = {
        $inertList: null,
        ariaTarget: null,
        ariaState: null,
    };
    #timer = null;
    #idleTimer = null;
    init() {
        const $parent = this.$host.parent(),
            global = $.$body.equal($parent);
        this.state = {
            global,
            persistent: global ? 'global' : this.options.persistent || null,
            preventTab: global || $parent.is('dialog,[role="dialog"]'),
            isShow: false,
            index: 0,
            ...DefaultArgs,
        };
        this.method = { toggle: this.toggle, show: (args) => this.toggle(true, args), hide: (args) => this.toggle(false, args) };
    }
    didMount() {
        if (this.state.global) {
            addTopLayerListener(true, this.#onTopLayerPush);
        }
    }
    didUnmount() {
        this.#toggleScrollbar(false);
        addTopLayerListener(false, this.#onTopLayerPush);
    }

    /** re-show to keep on top of the topLayer. */
    #onTopLayerPush = ({ current }) => {
        if (this.state.isShow && current !== this.element) {
            this.element.close();
            this.element.showModal();
        }
    };
    #toggleScrollbar(v) {
        if (this.state.global) $$.hideScrollbar(v);
    }
    #storeInert() {
        if (!this.state.global) {
            const $list = this.$host.siblings(':visible'),
                cache = this.#cache;
            $list.toggleAttr('inert', true);
            cache.$inertList = $list.add(cache.$inertList || []);
        }
    }
    #restoreInert() {
        if (!this.state.global) {
            const cache = this.#cache;
            cache.$inertList?.toggleAttr('inert', false);
            cache.$inertList = null;
        }
    }
    #zIndex() {
        if (this.state.global) return cssZindex('global');
        let zIndex = null;
        const list = arrayMap(
            this.host.parentNode.querySelectorAll('[data-zindex]'),
            (el) => Number(el.dataset.zindex || $(el).css('z-index')),
            (v) => !Number.isNaN(v)
        );
        if (list.length > 0) zIndex = Math.max(...list) + 1;
        return zIndex;
    }
    #tryTimer(delay, callback) {
        const timeout = delay === true ? 300 : typeIsNumber(delay) ? Number(delay) : null;
        clearTimeout(this.#timer);
        cancelIdleCallback(this.#idleTimer);
        if (timeout == null) return true;

        this.#timer = setTimeout(() => {
            this.#idleTimer = idleLoad(callback);
        }, timeout);
        return false;
    }
    toggle = (isShow, args) => {
        this[isShow ? 'willShow' : 'willHide']();
        const cb = () => {
            if (this.state.isShow === isShow) return;
            this.setState(args ?? DefaultArgs, false);
            this[isShow ? 'show' : 'hide'](args);
        };
        if (this.#tryTimer(args?.delay, cb)) cb();
    };
    willShow() {
        this.state.index++;
    }
    show(args = DefaultShowArgs) {
        this.setState({ isShow: true, zIndex: args.zIndex ?? this.#zIndex() }, () => {
            const { element } = this,
                focusElement = (args.focus !== null && this.stackFocus(args.focus, true)) || element;
            if (this.state.global) element.showModal();
            this.#toggleScrollbar(true);
            this.#storeInert();
            this.doFocus(focusElement, args.focus);
        });
    }
    willHide() {
        this.state.index--;
        if (this.state.index < 0) {
            this.state.index = 0;
            this.console.error('Hide cannot be called more than show!');
        }
    }
    hide(args = DefaultHideArgs) {
        if (this.state.index > 0 && !args.force) return;
        let focusBack = args?.focusBack;
        if (this.state.global) {
            try {
                this.element.showModal();
            } catch (e) {
                /* empty */
            }
            this.element.close();
            if (!focusBack && IOS) {
                focusBack = $.$activeElement().get();
                focusBack?.blur();
            }
        }
        this.setState({ index: 0, isShow: false });
        this.#toggleScrollbar(false);
        this.#restoreInert();
        this.doFocus(this.stackFocus(focusBack));
        if (!this.state.global && args?.destroy) setTimeout(() => this.host.remove(), 9);
    }
    stackFocus(focus, isShow) {
        const focusElement = typeIsElement(focus) ? focus : null;

        if (isShow) {
            this.#cacheAria(FocusPush(this, focusElement));
        } else {
            FocusPop(this, focusElement);
            this.#resetAria();
        }
        return focusElement;
    }

    doFocus(element, focusable) {
        if (element && (this.state.global || (focusable !== false && focusable != null))) {
            element.focus({ preventScroll: !this.state.focusScroll });
        }
    }
    #cacheAria(element) {
        if (!element) return null;
        const cache = this.#cache,
            busy = element.getAttribute('aria-busy');
        Object.assign(cache, { ariaState: busy || null, ariaTarget: element });
        element.setAttribute('aria-busy', true);
    }
    #resetAria() {
        const cache = this.#cache,
            { ariaTarget: element, ariaState } = cache;
        Object.assign(cache, { ariaState: null, ariaTarget: null });
        if (!element) return null;
        return ariaState ? element.setAttribute('aria-busy', cache.ariaState) : element.removeAttribute('aria-busy');
    }
    onKeyDown = (e) => {
        const name = keyName(e, true);
        if (name === 'Escape' || (this.state.preventTab && name === 'Tab')) stopEvent(e);
    };

    render() {
        const { global, persistent, isShow, text, zIndex } = this.state,
            hidden = !isShow,
            args = global
                ? { role: 'alertdialog', className: 'loading global', 'aria-labelledby': 'content', tabIndex: 0 }
                : { className: 'loading', tabIndex: -1, style: { zIndex } },
            Tag = global ? 'dialog' : 'div';
        return (
            <Tag hidden={hidden} {...args} onKeyDown={this.onKeyDown}>
                <aui-backdrop hidden={hidden} global={global} colorScheme={global ? null : 'light'} />
                <div role="status" className="content-box">
                    <div id="content" className="text empty-hidden">
                        {text ?? I18N.message}
                    </div>
                    {(persistent || isShow) && <aui-loading-dot name={persistent} hidden={hidden} />}
                </div>
            </Tag>
        );
    }
}
