import { addInternalPlugin } from '../loader.js';

import { getFileTypesByType, tooltipContents, Upload } from './upload.js';

export function RegUploadPlugin(name, init) {
    addInternalPlugin(name, ({ Plugin, Toolbar, Dialog }) => {
        class UploadButton extends Toolbar.Selector {
            split = true;

            willMount() {
                this.uploadInstance = new Upload({
                    ...this.options,
                    type: this.type,
                    name: this.name,
                    onUpload: (args) => {
                        const { html, data } = args;
                        this.setValue(html, data);
                    },
                    notification: this.notify,
                });

                const { options } = this.uploadInstance;
                options.fileTypes = getFileTypesByType(this.type, options.fileTypes);
                this.tooltip.push(...tooltipContents(options));
            }
            onClick() {
                this.uploadInstance.filePicker();
            }
            onItemClick(value) {
                switch (value) {
                    case 'upload_local':
                        return this.onClick();
                    default: {
                        const file = this.uploadInstance.getFileById(value);
                        if (file) {
                            const { html, data } = file;
                            this.setValue(html, data);
                        }
                    }
                }
            }
            menuMapping(item) {
                return item;
            }
            doLoad(menuMapping = this.menuMapping) {
                const uploadActions = [
                    { content: $$.I18N.uploader.localSource, icon: 'UploadLocal', value: 'upload_local' },
                    // { content: $$.I18N.uploader.onlineSource, icon: 'UploadOnline', value: 'upload_online' },
                ];
                let items = this.uploadInstance.fileItems();
                if (!items.length) return uploadActions;
                uploadActions.push({ separator: $$.I18N.uploader.recentFiles });
                items = items.map(menuMapping);
                return uploadActions.concat(items);
            }
        }

        return class extends Plugin {
            static toolbar = init(UploadButton, $$.I18N.richeditor);
            optionName = 'upload';
        };
    });
}
