/* eslint-disable unicorn/consistent-function-scoping */

export default function () {
    function colorMix(color1, color2, ratio) {
        if (ratio === 0) return color1;
        if (ratio === 1) return color2;
        const parse = (c) => Number.parseInt(c, 16),
            rgb1 = [parse(color1.slice(1, 3)), parse(color1.slice(3, 5)), parse(color1.slice(5, 7))],
            rgb2 = [parse(color2.slice(1, 3)), parse(color2.slice(3, 5)), parse(color2.slice(5, 7))];
        const linearInterpolation = (a, b) => Math.round(a + (b - a) * ratio),
            hex = (v) => v.toString(16).padStart(2, '0'),
            r = hex(linearInterpolation(rgb1[0], rgb2[0])),
            g = hex(linearInterpolation(rgb1[1], rgb2[1])),
            b = hex(linearInterpolation(rgb1[2], rgb2[2]));
        return `#${r}${g}${b}`;
    }

    let running = false,
        fpsTimer = null,
        startTime = null;
    let colors = [],
        defaultColor;

    function theme(data) {
        colors = data.colors;
        defaultColor = data.defaultColor;
    }

    onmessage = function (e) {
        const { type } = e.data;
        if (type === 'init') return globalThis.init(e.data);
        if (type === 'start') return globalThis.start(e.data);
        if (type === 'stop') return globalThis.stop(e.data);
        if (type === 'theme') return theme(e.data);
        if (type === 'create') {
            const { count, duration, size, gap } = e.data,
                total = count + colors.length;
            const width = size * count + gap * (count - 1),
                height = size,
                r = size / 2,
                cx = (i) => r + size * i + gap * i,
                cy = r;
            const canvasMap = new Map();
            let currentCanvas, currentCtx;

            function drawByFPS(timestamp) {
                if (!running) return;
                const elapsed = timestamp - startTime,
                    progress = (elapsed % duration) / duration;
                render(progress);

                fpsTimer = requestAnimationFrame(drawByFPS);
            }
            function render(progress) {
                currentCtx.clearRect(0, 0, currentCanvas.width, currentCanvas.height);
                const currentFloat = progress * total,
                    currentIndex = Math.floor(currentFloat),
                    ratio = currentFloat - currentIndex;
                for (let i = 0; i < count; i++) {
                    const currentColor = colors[currentIndex - i],
                        nextColor = colors[currentIndex + 1 - i];
                    currentCtx.beginPath();
                    currentCtx.arc(cx(i), cy, r, 0, Math.PI * 2); // draw a full circle
                    currentCtx.fillStyle = colorMix(currentColor || defaultColor, nextColor || defaultColor, ratio);
                    currentCtx.fill();
                }
            }

            globalThis.init = ({ canvas, uid }) => {
                currentCanvas = canvas;
                currentCanvas.width = width;
                currentCanvas.height = height;
                currentCtx = currentCanvas.getContext('2d');
                canvasMap.set(uid, [currentCanvas, currentCtx]);
                render(0);
            };
            globalThis.start = ({ uid }) => {
                if (running) return;
                const [canvas, ctx] = canvasMap.get(uid);
                currentCanvas = canvas;
                currentCtx = ctx;
                running = true;
                startTime = performance.now();
                drawByFPS(startTime);
            };
            globalThis.stop = () => {
                if (!running) return;
                running = false;
                startTime = null;
                cancelAnimationFrame(fpsTimer);
            };
        }
    };
}
