import float from '../number/float.js';

/** @type {typeof $$.string.fileByte2Size} */
export default function fileByte2Size(byteLength, digits, separator, forceFloat) {
    const list = ['B', 'KB', 'MB', 'GB', 'TB'];
    let index = 0;
    if (byteLength == null) byteLength = 0;
    if (separator == null) separator = '';
    while (byteLength >= 1024) {
        index++;
        byteLength = byteLength / 1024;
    }

    let number = Number.parseFloat(byteLength);
    if (digits != null) {
        const arr = String(number).split('.');
        if (!forceFloat) {
            digits = arr.length < 2 || arr[0].length > digits ? 0 : digits - arr[0].length + 1;
            digits = Math.max(digits, 0);
        }
        number = float(number, digits);
    }
    return number + separator + list[index];
}
