/** @jsxImportSource @gui/aui-devops */
import { error } from '../../core/base/log.js';
import { widget } from '../../core/extend/widget.js';

import { isInteger as typeIsInteger } from '../../util/type/verify.js';

(function () {
    const noop = $$.fn();
    const panelGroups = {},
        _constant = {
            EXPANDER_CLASS: 'aui-expander',
            EXPANDER_MINI_CLASS: 'aui-expander-mini',
            EXPANDER_MINI_TITLE_CLASS: 'aui-expander-mini-title',
            EXPANDER_MINI_TITLE_BG_CLASS: 'aui-expander-mini-title-bgcolor',
            AUI_WIDGET: 'aui-widget',
            BOX_CLASS: 'aui-box aui-box-partial',
            EXPANDER_EXPAND_CLASS: 'aui-expander-expand',
            TOP_NONE_CLASS: 'aui-expander-top-none',
            TITLE_CLASS: 'aui-expander-title',
            TITLE_FONT_CLASS: 'aui-expander-title-font',
            ACTION_CLASS: 'aui-expander-action',
            // TITLE_BG_CLASS: 'aui-expander-title-bgcolor',
            TITLE_TEMPLATE_CLASS: 'aui-expander-title-template',
            TITLE_TEMPLATE_CONTENT_CLASS: 'aui-expander-title-content',
            AUI_SCOPE_CLASS: 'aui-scope',
            PANEL_CLASS: 'aui-expander-panel aui-box-partial-content',
            ICON_DOWN_CLASS: 'faui-angle-down-s',
            Toggleable: 'aui-expander-toggleable',
        };

    widget('aui5.expander', {
        section: true,
        // The ID of the input widget
        titleId: 'aui-expander-title-',
        panelId: 'aui-expander-panel-',
        actionId: 'aui-expander-logo-',
        templateId: 'aui-expander-header-template-',
        iconClass: _constant.ICON_DOWN_CLASS,
        options: {
            status: {
                show: true,
            },
            groupName: null,
            bgColor: null,
            active: -1,
            togglable: true,
            mini: false,
            onShow: noop,
            onHide: noop,
            triggerType: 'all', // "all"/"action",
            level: '1',
            title: '',
        },
        _create: function () {
            this._initMembers()._createExpander()._loaded()._initEvent();

            if (this._isGrouped) this._initGroup();

            if (this.options.active !== -1) {
                setTimeout(() => {
                    this._setSelectedIndex();
                }, 0);
            }
        },
        _setOption: function (key, value, oldValue) {
            if (this.options[key] === value) return;
            this.options[key] = value;

            switch (key) {
                case 'status': {
                    let group = {};
                    if (value.show) {
                        if (this._isGrouped) {
                            // The mutex mode
                            group = panelGroups[this._groupName];
                            if (!this._expand && group.active > -1) {
                                group.titles[group.active].click();
                            }
                            group.active = this._index;
                        }
                        this._onShow({ dataDrived: true });
                    } else {
                        if (this._isGrouped) {
                            // The mutex mode
                            group = panelGroups[this._groupName];
                            group.active = -1;
                        }
                        this._onHide({ dataDrived: true });
                    }
                    break;
                }
                case 'togglable':
                    this._setToggleable(value);
                    break;
                case 'bgColor':
                    this.$title.css({
                        background: value,
                        // 'border-color': value,
                    });
                    break;
                case 'title':
                    this._resetTitle();
                    break;
                default:
                    break;
            }
        },
        // Initializing member
        _initMembers: function () {
            this._initId();

            this._isGrouped = !!this.options.groupName;
            this._groupName = this.options.groupName;
            // Panel is closed on initialization
            this._expand = false;

            return this;
        },
        _initId: function () {
            this.titleId += this.uuid;
            this.panelId += this.uuid;
            this.actionId += this.uuid;
            this.templateId += this.uuid;
        },
        // create combobox
        _createExpander: function () {
            const options = this.options;
            const titleClass = options.mini === true ? _constant.EXPANDER_MINI_TITLE_CLASS : _constant.TITLE_CLASS;
            const titleBgColor = options.mini === true ? _constant.EXPANDER_MINI_TITLE_BG_CLASS : '';
            const isAction = options.triggerType === 'action';
            const isToggleable = isAction && options.togglable;

            if (this.$element.children().length > 2) {
                error("expander's children is more than 2.");
            }
            this.$panelTemplate = this.$element.children().length === 1 ? jQuery(this.$element.children()[0]) : jQuery(this.$element.children()[1]);

            const expanderTitle = jQuery(<div className={_constant.TITLE_FONT_CLASS}>{options.title}</div>);
            if (this.$element.children().length === 2) {
                const titleTemplateContent = <div className={_constant.TITLE_TEMPLATE_CONTENT_CLASS} />;
                const template = jQuery(this.$element.children()[0]).css('flex', '1 1 auto').wrap(titleTemplateContent);
                this.$titleTemplate = template.parent().prepend(expanderTitle);
            } else {
                this.$titleTemplate = expanderTitle;
                this.$element.prepend(this.$titleTemplate[0]);
            }

            const titleContent = (
                <div
                    className={[titleClass, titleBgColor, options.togglable && _constant.Toggleable]}
                    id={this.titleId}
                    data-triggertype={this.options.triggerType}
                    role={isToggleable ? null : 'button'}
                    aria-expanded={isToggleable ? null : 'false'}
                    tabIndex={isToggleable ? null : 0}
                />
            );
            const titleTemplate = <div className={_constant.TITLE_TEMPLATE_CLASS} id={this.templateId} />;
            // let autoCursor = this.options.triggerType == 'action' ? 'auto' : '';
            this.$titleTemplate.wrap(titleContent).wrap(titleTemplate); // style="cursor:' + autoCursor + '"

            const panel = <div className={_constant.PANEL_CLASS} id={this.panelId} />;
            this.$panelTemplate.wrap(panel);

            this.$title = this.$element.find('#' + this.titleId);

            // let pointorCursor = this.options.triggerType == 'action' ? 'pointer' : 'auto';
            const actionHtml = (
                <div
                    className={this.iconClass}
                    id={this.actionId}
                    aria-expanded={isToggleable ? 'false' : null}
                    role={isToggleable ? 'button' : null}
                    tabIndex={isToggleable ? 0 : null}
                    aria-labelledby={isToggleable ? this.titleId : null}
                />
            );
            this.$title.prepend(actionHtml);
            this.$action = isAction ? jQuery(actionHtml) : this.$title;
            return this;
        },
        // Triggered after part creation is successful
        _loaded: function () {
            const options = this.options;
            this.$element.addClass(
                _constant.EXPANDER_CLASS + ' ' + _constant.BOX_CLASS + ' ' + _constant.AUI_WIDGET + (options.mini === true ? ' ' + _constant.EXPANDER_MINI_CLASS : '')
            );
            this.$element.attr('level', options.level).attr('role', 'group');
            this.$logo = this.$title.children('#' + this.actionId).addClass(_constant.ACTION_CLASS);
            this.$panel = this.$element.find('#' + this.panelId);

            if (options.bgColor) {
                this.$title.css({
                    background: options.bgColor,
                    // 'border-color': options.bgColor,
                    // 'border-color': options.bgColor,
                });
            }

            if (options.status.show) this._onShow({ dataDrived: true });

            return this;
        },
        _setToggleable: function (value) {
            this.$title.toggleClass(_constant.Toggleable, value);
            this.$action.attr({
                tabindex: value ? 0 : null,
                role: value ? 'button' : null,
                'aria-expanded': value ? this._expand : null,
                'aria-labelledby': this.$action.attr('id') === this.actionId && value ? this.titleId : null,
            });
        },
        _initGroup: function () {
            const group = panelGroups[this._groupName] || {};

            group.titles = group.titles || [];
            group.widgets = group.widgets || [];

            // Expand the serial number of the panel
            group.active = group.active >= 0 ? group.active : -1;
            this._index = group.titles.length;
            group.titles[group.titles.length] = this.$title;
            group.widgets[group.widgets.length] = this;

            this.$title.data('index', this._index);

            panelGroups[this._groupName] = group;
        },
        _resetTitle: function () {
            const options = this.options;
            const templateDom = this.$element.find('.' + _constant.TITLE_FONT_CLASS);
            templateDom[0].textContent = options.title;
        },
        _initEvent: function () {
            const current = this.options.triggerType === 'action' ? this.$logo : this.$title;

            this._on(current, 'keypress', this._onTitleKeypress);

            this._on(current, 'click', this._onTitleClick);

            this._on('Open', function (e) {
                this._onShow({ dataDrived: false });
            });

            return this;
        },
        _onTitleKeypress: function (e) {
            if ((e.keyCode === 13 || e.keyCode === 32) && e.target === e.currentTarget) {
                e.preventDefault();
                this._onTitleClick(e);
            }
        },
        _onTitleClick: function (e, force) {
            let group;

            if ((force || this.options.togglable === true) && jQuery(e.target).closest('.' + _constant.AUI_SCOPE_CLASS).length === 0) {
                if (this._isGrouped) {
                    // The mutex mode
                    group = panelGroups[this._groupName];

                    if (this._expand) {
                        group.active = -1;
                    } else {
                        if (group.active > -1) {
                            group.titles[group.active].click();
                        }
                        group.active = this._index;
                    }
                } else {
                    this._index = 0;
                }

                if (this._expand) {
                    this._onHide({ dataDrived: false });
                } else {
                    this._onShow({ dataDrived: false });
                }
            }
        },
        _onHide: function (args) {
            const old = this._expand;
            this._updateLogo(this.$logo, false);
            this._expand = false;
            this.$panel.hide();
            if (this._expand === old) return;
            this._callback('onHide', args);
        },
        _onShow: function (args) {
            const old = this._expand;
            if (this._callback('willShow', args) === false) return false;
            this.$element.triggerHandler('willShow');
            this._updateLogo(this.$logo, true);
            this._expand = true;
            this.$panel.show();
            for (let i = 0; i < this.$element.find('.aui-widget').length; i++) {
                this.$element.find('.aui-widget').eq(i).triggerHandler('Update');
            }
            if (this._expand === old) return;
            this._callback('onShow', args);
            this.$panel.scrollTop(0);
        },
        _updateLogo: function (logo, isExpand) {
            const current = this.options.triggerType === 'action' ? this.$logo : this.$title;
            setTimeout(() => current.attr({ 'aria-expanded': this.options.togglable ? isExpand : null }));
            this.$element.toggleClass(_constant.EXPANDER_EXPAND_CLASS, isExpand);
        },
        expandByIndex: function (index) {
            if (!this._expand) {
                this.options.active = index;
                this._setSelectedIndex();
            }
        },
        closeByIndex: function (index) {
            if (this._expand) {
                this.$title.click();
            }
        },
        _setSelectedIndex: function () {
            const index = this.options.active;

            if (typeIsInteger(index)) {
                if (this._isGrouped) {
                    const group = panelGroups[this._groupName];

                    if (index > -1 && index < group.titles.length && index !== group.active) {
                        this._onTitleClick(
                            {
                                target: group.titles[index],
                            },
                            true
                        );
                    }
                } else if (index === 0) {
                    this._onTitleClick({ target: this.$title }, true);
                }
            }

            return this;
        },
        _updateGroup: function () {
            const group = panelGroups[this._groupName],
                titles = group.titles,
                widgets = group.widgets,
                c = titles.length;
            for (let i = 0; i < c; i++) {
                if (titles[i].attr('id') === this.titleId) {
                    if (titles[i].data('index') === group.active) {
                        group.active = -1;
                    }
                    titles.splice(i, 1);
                    widgets.splice(i, 1);
                    break;
                }
            }
            widgets.forEach((t, i) => {
                t._index = i;
            });
        },
        _destroy: function () {
            if (this._isGrouped) {
                this._updateGroup();
            }
        },
    });
})();
