import cssValid from '../../util/css/valid.js';
import objectForEach from '../../util/object/for-each.js';
import camelCase from '../../util/string/camel-case.js';
import kebabCase from '../../util/string/kebab-case.js';

import { ToggleAttr, SetAttr } from './attr.js';
import classList from './class-list.js';
import { getElementStrict } from './parse.js'; // eslint-disable-line no-unused-vars
import { visible as checkVisible } from './pseudo.js';

export function addClass(...args) {
    const node = this;
    const list = classList(...args);
    node.classList.add(...list);
}
export function removeClass(...args) {
    const node = this;
    const list = classList(...args);
    node.classList.remove(...list);
}
export function toggleClass(name, force) {
    const node = this,
        list = classList(name);
    for (const val of list) {
        const op = typeof force === 'boolean' ? force : !hasClass.call(node, val),
            fn = op ? addClass : removeClass;
        fn.call(node, val);
    }
}
export function hasClass(name) {
    const node = this;
    const [...list] = node.classList;
    return list.includes(name);
}
export function attr(name, value) {
    const node = this;
    if (arguments.length > 1) return attrs.apply(node, arguments);
    return node.getAttribute(name);
}
export function attrs(obj) {
    const node = this;
    if (arguments.length > 1) {
        SetAttr(node, ...arguments);
    } else if (obj) {
        objectForEach(obj, (k, v) => SetAttr(node, k, v));
    }
}
export function toggleAttr(name, force) {
    const node = this;
    name = kebabCase(name);
    if (!ToggleAttr(node, name, force)) {
        const current = () => node.getAttribute(name) !== 'true';
        const val = force == null ? current() : !!force;
        node.setAttribute(name, val);
    }
}
export function css(a, b) {
    const node = this;
    const type = $$.getClassBuiltIn(a);
    const fn = (k, v) => {
        if (v != null) {
            if (!k.startsWith('--')) v = cssValid(k, v);
            node.style.setProperty(kebabCase(k), v);
        }
    };
    if (type === 'Object') {
        objectForEach(a, fn);
    } else if (type === 'String') {
        if (arguments.length > 1) {
            fn(a, b);
        } else {
            return window.getComputedStyle(node)[camelCase(a)];
        }
    }
}

export function visible(visibilityProperty = false, opacityProperty = false) {
    const node = this;
    return checkVisible(node, { visibilityProperty, opacityProperty });
}

export function toggleVisible(value) {
    const node = this;
    if (value == null) {
        const cur = css.call(node, 'visibility');
        value = cur !== 'visible';
    }
    css.call(node, 'visibility', value ? 'visible' : 'hidden');
}

export function origin(k, v) {
    const node = this;
    if (v === undefined) {
        const val = node[k];
        return typeof val === 'function' ? val.bind(node) : val;
    }
    node[k] = v;
}
export function originFn(name, ...args) {
    const node = this,
        fn = node[name];
    if (typeof fn === 'function') return fn.apply(node, args);
}

export function reset(clear) {
    const node = this;
    switch (node.nodeName) {
        case 'INPUT':
            if (node.type === 'radio' || node.type === 'checkbox') {
                node.checked = clear ? false : node.hasAttribute('checked');
            } else {
                node.value = clear ? '' : node.getAttribute('value');
            }
            break;
        case 'TEXTAREA':
            node.value = clear ? '' : node.innerHTML;
            break;
        case 'SELECT': {
            const arr = Array.prototype.slice.call(node.children),
                selected = clear ? null : arr.findLast((el) => el.hasAttribute('selected'));
            node.selectedIndex = selected ? selected.index : 0;
            break;
        }
    }
}
