/** @jsxImportSource @gui/aui-devops */
import { define, Types, Widget, inherit } from '../../widget/widget.js';

import format from '../../util/string/format.js';

import { Echo } from './echo.js';
import { Picker } from './picker.js';
import { fileTypeSplitter, formatFileTypes, formatMaxSize, maxLengthByMultiple } from './utils.js';

import style from './detail.less';

const { options: pickerOptions, observers: pickerObservers } = inherit(Picker, ['disabled', 'fileTypes', 'maxSize', 'multiple']);
const I18N = $$.I18N.uploader;

/** @extends {Widget<typeof Detail.options>} */
@define('uploader-detail')
export class Detail extends Widget {
    static options = {
        ...pickerOptions,
        files: Echo.options.files,
        description: Types.string,
        maxSizeEntry: Types.string,
        showMaxSize: false,
        showTypes: false,
    };
    static observers = [...pickerObservers, 'files', 'description', 'maxSizeEntry', 'showMaxSize', 'showTypes'];
    static styles = style;

    #deriveOption2State(options = this.options) {
        const { fileTypes, maxSize, multiple } = options,
            maxLength = maxLengthByMultiple(multiple);
        return { fileTypes, maxSize, maxLength, showMaxLength: Number.isSafeInteger(multiple) && multiple > 0 };
    }
    optionsGetter = {
        disabled: (v) => !!v,
    };
    init() {
        this.state = {
            ...this.#deriveOption2State(),
        };
        this.dispatcher = this.useUnicom(['uploader', 'detail']);
    }
    didMount() {
        // Check dependency.
        this.dispatcher('picker').catch((err) => {
            this.console.error(err);
            this.customState('hidden', true);
        });
    }
    setOption(name, value, oldValue) {
        switch (name) {
            case 'fileTypes':
            case 'maxSize':
                this.setState(this.#deriveOption2State(), false);
                return true;
            default:
                break;
        }
    }
    receiver = (action, from, data) => {
        switch (action) {
            case 'setDetails':
                this.setState(this.#deriveOption2State(data));
                break;
            default:
                break;
        }
    };

    renderTypes(disabled) {
        const { fileTypes, showTypes } = this.options,
            l = fileTypes?.length;
        if (!l) return null;

        const maxTypes = 3,
            showMore = l > maxTypes;

        const description = formatFileTypes(fileTypes, true) || '',
            /** @example (JPG, PNG, GIF, {0}) || (JPG, PNG, GIF)  */
            displayDescription = showMore ? `(${formatFileTypes(fileTypes.slice(0, maxTypes))}${fileTypeSplitter}{0})` : `(${formatFileTypes(fileTypes)})`;

        return (
            <>
                <span className="sr-only">{description}</span>
                {showTypes && (
                    <aui-i18n entry={` ${displayDescription}`}>
                        {showMore && (
                            <aui-popover slot="0">
                                <aui-button-lite disabled={disabled} slot="trigger" text={I18N.more} type="link" />
                                <span>{description}</span>
                            </aui-popover>
                        )}
                    </aui-i18n>
                )}
            </>
        );
    }

    render() {
        const { files, description, showMaxSize, maxSize, maxSizeEntry } = this.options,
            disabled = Boolean(this.options.disabled),
            { maxLength, showMaxLength } = this.state;

        return (
            <div className={['description', disabled && 'disabled']}>
                <slot>
                    {showMaxSize && <span>{formatMaxSize(maxSize, maxSizeEntry)}</span>}
                    {this.renderTypes(disabled)}
                    {showMaxLength && <div>{format(I18N.maxFileCount, files?.length || 0, maxLength)}</div>}
                    {!!description && <div>{description}</div>}
                </slot>
            </div>
        );
    }
}
