import svgClean from './svg-clean.js';

/** @type {typeof $$.img.svg2base64} */
export default function svg2base64(svg) {
    let base64;
    const element = svgClean(svg.cloneNode(true));
    base64 = element.outerHTML
        .replaceAll(/(ns\d{1,2}:)*xmlns((:ns\d{1,2})|(:xlink))?="(http[^"]*)?"/gi, '')
        .replaceAll(/ +/g, ' ')
        .replace('<svg', '<svg xmlns="http://www.w3.org/2000/svg"');
    base64 = base64.replaceAll(`"`, `'`).replaceAll('%', '%25').replaceAll('#', '%23').replaceAll('{', '%7B').replaceAll('}', '%7D').replaceAll('<', '%3C').replaceAll('>', '%3E');
    base64 = 'data:image/svg+xml,' + base64;
    return base64;
}
