/** @jsxImportSource @gui/aui-devops */
import { Options as ButtonOptions } from '../../widget/form/button-util.js';
import { define, Widget, Types } from '../../widget/widget.js';

import filter from '../../util/object/filter.js';

import style from './overflow-menu.less';

const ControlledButtonOptions = ['align', 'block', 'type', 'weight'],
    buttonOptions = filter(ButtonOptions, ControlledButtonOptions);

/** @extends {Widget<typeof OverflowMenu.options>} */
@define('overflow-menu')
export class OverflowMenu extends Widget {
    static options = {
        ...buttonOptions,
        nested: Types.object,
    };
    static ownContents = false;
    static observers = ControlledButtonOptions;
    static downstreamContext = ['overwrite', ['button', 'button-group'], [...ControlledButtonOptions, 'nested']];
    static internals = { role: 'menu' };
    static styles = style;

    buttonGroupNestedPosition = { width: [80, 500], my: 'left top', at: 'right+8 top' }; // 8 matches box padding.
    optionsGetter = {
        align: () => 'start',
        block: () => true,
        type: () => 'bald',
        weight: () => 'regular',

        nested: () => this.buttonGroupNestedPosition,
    };
    render() {
        return <slot />;
    }
}
