/** @jsxImportSource @gui/aui-devops */
import { define, inherit, Widget } from '../../widget/widget.js';

import fileReader from '../../util/io/file-reader.js';

import { Avatar } from '../avatar/avatar.js';
import '../imgcrop/imgcrop.js';

import { Echo } from './echo.js';

import style from './img.less';

const { options: AvatarOptions } = inherit(Avatar, ['shape', 'radius']);
const { options, observers } = inherit(Echo, ['deleteable', 'files', 'onDelete']);

const I18N = $$.I18N.uploader;

/** @extends {Widget<typeof Img.options>} */
@define('uploader-img')
export class Img extends Echo {
    static options = {
        ...AvatarOptions,
        ...options,
        userName: '',
    };
    static observers = [...observers, 'userName'];
    static styles = style;

    didMount() {
        super.didMount();
        this.dispatcher('picker', 'addOnUploadHandler', this.onUpload);
    }

    onUpload = (fileEntity) => {
        if (fileEntity.isSucceed === false) return fileEntity;

        return fileReader(fileEntity.file)
            .then((base64) => {
                fileEntity.base64 = base64;
                return fileEntity;
            })
            .catch((err) => {
                fileEntity.isSucceed = false;
                fileEntity.message = err.message;
                throw err;
            });
    };
    onDelete = () => {
        this.doDeleteFile(this.options.files[0]);
    };

    render() {
        const { deleteable, disabled, files, userName, shape, radius } = this.options,
            { base64, isSucceed, message } = files?.[0] || {},
            invalid = isSucceed === false,
            showDelete = invalid || (deleteable && !!base64);

        /** @see EchoItem.render */
        return (
            <div className={['box', 'aui-validation']} data-valid={!invalid}>
                <div className="img">
                    <aui-avatar
                        size="stretch"
                        shape={shape}
                        radius={radius}
                        name={invalid ? '' : userName}
                        placeholder={invalid ? 'faui-image-broken' : null}
                        avatar={base64 || null}
                    />
                    {showDelete && (
                        <button
                            id="delete"
                            className={this.fontIcon('faui-close-circle')}
                            type="button"
                            tabIndex={0}
                            disabled={disabled}
                            aria-label={I18N.delete}
                            data-tooltip={true}
                            onClick={this.onDelete}
                        />
                    )}
                </div>
                <div className="content">
                    <div />
                    <slot />
                    <div className="message-box">
                        <div id="validation-message">{invalid && (message || I18N.uploadFailed)}</div>
                    </div>
                </div>
            </div>
        );
    }
}
