import { isCustomElement } from '../../util/type/types.js';

import { flatChildren } from './flat-children.js';
import { getElementStrict } from './parse.js';

// content<padding<border(include scrollbar)<margin
// default border-box; ///get hidden element size?
export function size(box) {
    const node = this;
    let { width, height } = node.getBoundingClientRect();
    if (box === 'margin') {
        const style = getComputedStyle(node);
        width += Number.parseFloat(style.marginInlineStart) + Number.parseFloat(style.marginInlineEnd);
        height += Number.parseFloat(style.marginBlockStart) + Number.parseFloat(style.marginBlockEnd);
    } else if (box === 'padding' || box === 'content') {
        const { offsetWidth, clientWidth, offsetHeight, clientHeight } = node;
        width -= offsetWidth - clientWidth;
        height -= offsetHeight - clientHeight;

        if (box === 'content') {
            const style = getComputedStyle(node);
            width -= Number.parseFloat(style.paddingInlineStart) + Number.parseFloat(style.paddingInlineEnd);
            height -= Number.parseFloat(style.paddingBlockStart) + Number.parseFloat(style.paddingBlockEnd);
        }
    }
    return { width, height };
}

export function offset(other) {
    const node = this;
    const { top, left } = node.getBoundingClientRect();
    other = getElementStrict(other);
    if (other) {
        const { top: top1, left: left1 } = other.getBoundingClientRect();
        return { top: top - top1, left: left - left1 };
    } else {
        return { top, left };
    }
}

export const textOverflow = (function () {
    function overflowH({ lineHeight, fontSize }, quotient) {
        // for check element: line-height < normal;
        return lineHeight === 'normal' || quotient > 1.4 || Number.parseFloat(lineHeight) / Number.parseFloat(fontSize) > quotient;
    }
    function checkInput(element) {
        const ph = element.getAttribute('placeholder');
        if (!ph) return false;

        const doc = element.ownerDocument,
            el = doc.createElement('div'),
            { font } = window.getComputedStyle(element, ':placeholder');
        el.textContent = ph;
        el.style.cssText = `font:${font}; position:fixed; display:inline-block; white-space:nowrap; visibility:hidden; pointer-events:none;`;
        doc.body.append(el);
        const w = el.clientWidth,
            { width } = size.call(element, 'content');
        el.remove();
        return w > width ? ph : false;
    }
    function checkElement(element) {
        const IgnoreDisplay = ['none', 'contents'],
            EnablePosition = ['static', 'relative'],
            style = getComputedStyle(element);
        if (IgnoreDisplay.includes(style.display) || String(style.opacity) === '0' || !EnablePosition.includes(style.position)) return false;

        let { clientWidth: width, clientHeight: height } = element;
        if (width + height === 0) ({ width, height } = element.getBoundingClientRect());
        const overW = element.scrollWidth > width && width > 0,
            overH = element.scrollHeight > height && height > 0;
        return overW || (overH && overflowH(style, element.scrollHeight / height));
    }
    function checkOverflow(element, force) {
        const name = element.localName;
        if (force || !isCustomElement(element)) {
            switch (name) {
                case 'input':
                    return !element.value && checkInput(element);
                case 'svg':
                    return false;
                case 'slot':
                    if (element.assignedNodes({ flatten: true }).length && checkElement(element)) return true;
                    break;
                default:
                    if (checkElement(element)) return true;
                    break;
            }
        }
        const [...children] = flatChildren(element, { crossShadow: true, crossSlot: true });
        for (const child of children) {
            if (checkOverflow(child, force) === true) return true;
        }
        return false;
    }

    return function () {
        const node = this;
        return checkOverflow(node, true);
    };
})();
