import React from 'react';

import RouterPrompt from './router.jsx';

// Global namespace for the React components.
if (!window.R) window.R = {};

class Core extends React.Component {
    render() {
        return <RouterPrompt />;
    }
}

function Scope(props) {
    return <span className="aui-scope">{props.children}</span>;
}

R.RouterPrompt = RouterPrompt;
R.Core = Core;
R.Scope = Scope;
