import isLike from './is-like.js';

function flatMap(list, filter) {
    const result = [];
    for (const v of list) {
        if (filter?.(v) === false) continue;
        if (isLike(v)) {
            result.push(...v);
        } else {
            result.push(v);
        }
    }
    return result;
}

/** @type {typeof $$.array.concat} */
export function concat(...args) {
    return flatMap(args);
}

/** @type {typeof $$.array.concatIfneed} */
export function concatIfneed(...args) {
    return flatMap(args, (v) => v != null);
}
