/** @type {typeof $$.object.forEach} */
export default function forEach(object, callback, checkProp) {
    if (object) {
        for (const k in object) {
            if (checkProp === false || Object.hasOwn(object, k)) {
                const result = callback(k, object[k]);
                if (result === false) break;
            }
        }
    }
}
