/** @jsxImportSource @gui/aui-devops */
import { addTooltip } from '../../core/module/tooltip.js';
import { define, Widget, Types } from '../../widget/widget.js';

import arrayAt from '../../util/array/at.js';
import arrayLoop from '../../util/array/loop.js';
import { map as arrayMap } from '../../util/array/map.js';
import { keyPressProps } from '../../util/event/key-press.js';
import minmax from '../../util/number/minmax.js';
import { percent, percentValue, percentUnit } from '../../util/number/percent.js';
import round from '../../util/number/round.js';
import key4Map from '../../util/string/key4map.js';

import { TooltipNode } from './modules/index.js';
import { NS, Colors, TooltipClassName, Format, Action, TabloopArgs, OrientSwap, TagObject } from './modules/utils.js';

import style from './grid.less';

const DefaultAxisCount = 4;
const PercentDigits = 4; // for safe rendered layout size precise.

/** @typedef {Object} Item */

class GridData extends Widget {
    #percent = 0;
    #buildDataMaps(items) {
        const { groupField, nameField, valueField, colorField } = this.options,
            { isLine, groupMode } = this.state;
        const unGroupedName = undefined,
            groupData = new Map(),
            nameData = new Map();
        // 1n: create group data (groupBy).
        for (const item of items) {
            let value = item[valueField],
                range = false;
            let min, max;
            if (Array.isArray(value)) {
                range = true;
                [min, max] = minmax(...value);
                value = [min, max];
            } else {
                [min, max] = minmax(0, value);
            }
            if (Number.isFinite(min) && Number.isFinite(max)) {
                const name = item[nameField],
                    color = item[colorField],
                    group = key4Map(item[groupField]) ?? unGroupedName,
                    obj = { name, value, min, max, range, next: null, color, group, type: isLine ? item.type || 'solid' : 'rect', original: item };
                groupData.getOrInsert(group, []).push(obj);
                nameData.getOrInsert(name, []).push(obj);
            } else {
                this.console.error('Non-numeric data value will be ignored.', item);
            }
        }

        let result = isLine ? nameData : groupData;
        let useGroupMode = true;
        let tooltipField = isLine ? 'group' : 'name';
        // check whether to use group mode.
        if (groupData.size === 1 && (isLine || !groupMode)) {
            result = nameData;
            useGroupMode = false;
            tooltipField = 'name';
        }

        Object.assign(this.state, { useGroupMode, tooltipField });
        return { groupData, nameData, result };
    }
    #parseColor(legends) {
        const colors = Colors(this.options.color),
            mapping = new Map();
        let index = 0;
        return (item, colorKey) => {
            if (!mapping.has(colorKey)) {
                legends.push(Object.assign(item, { val: this.state.valueFormatter(item.value) })); // every color mapping to a legend.
                mapping.set(colorKey, item.color || arrayAt(colors, index++, true)); // item.color > (options.color > default color)
            }
            item.color = mapping.get(colorKey);
        };
    }
    #dataStats(groupData) {
        const { isLine, groupMode } = this.state,
            legends = [],
            colorParser = this.#parseColor(legends);
        let total = 0,
            maxGroupSize = 0,
            maxValue = 0,
            minValue = 0;
        // 2n: get max value from group (stack maybe).
        for (const [group, arr] of groupData) {
            if (!arr?.length) continue;
            const list = new Map();
            let stackValue = 0,
                lastItem;
            for (const item of arr) {
                const { name, group, min, max } = item;
                if (list.has(name)) {
                    this.console.error('Duplicate name item in group will be ignored.', item);
                    continue;
                }
                if (groupMode === 'stack') {
                    if (min < 0) {
                        this.console.error('Stacking negative values will be ignored.', item);
                        continue;
                    }
                    stackValue += max;
                } else {
                    maxValue = Math.max(maxValue, max);
                    minValue = Math.min(minValue, min);
                }
                total += max;
                colorParser(item, isLine ? group : name);
                if (lastItem) lastItem.next = max;
                lastItem = item;
                list.set(name, item);
            }
            maxValue = Math.max(maxValue, stackValue);
            groupData.set(group, [...list.values()]);
            maxGroupSize = Math.max(maxGroupSize, list.size);
        }

        return { legends, total, maxGroupSize, ...this.#calcAxis(minValue, maxValue) };
    }
    #calcAxis(_minValue, _maxValue) {
        const { axisInterval, axisHeaderInterval, axisCount } = this.options,
            maxValue = Number(this.options.maxValue),
            minValue = Number(this.options.minValue);
        let axisMax = Math.max(Number.isFinite(maxValue) ? maxValue : 0, _maxValue, 0),
            axisMin = Math.min(Number.isFinite(minValue) ? minValue : 0, _minValue, 0);
        let tickCount,
            headerStep = 1,
            tickInterval;
        // part3: adjust max value by interval;
        if (axisInterval) {
            if (axisMax === 0 && axisMin === 0) {
                axisMax = maxValue ? round(maxValue, axisInterval, 'up') : axisInterval;
            } else {
                axisMax = axisMax > 0 ? round(axisMax, axisInterval, 'up') : 0;
                axisMin = axisMin < 0 ? round(axisMin, axisInterval, 'down') : 0;
            }
            tickInterval = axisInterval;
            tickCount = (axisMax - axisMin) / axisInterval;
            if (axisHeaderInterval > 0) {
                headerStep = Math.max(1, Math.floor(axisHeaderInterval / axisInterval));
            }
        } else {
            const rawRange = axisMax - axisMin;
            if (rawRange === 0) {
                tickCount = axisMin = axisMax = 0;
            } else {
                tickInterval = Math.max(1, round(rawRange / axisCount, 1, 'up'));
                axisMax = round(axisMax, tickInterval, 'up');
                axisMin = round(axisMin, tickInterval, 'down');
                tickCount = (axisMax - axisMin) / tickInterval;
            }
            if (axisHeaderInterval > 0) {
                headerStep = Math.max(1, Math.floor(axisHeaderInterval / tickInterval));
            }
        }
        tickInterval ||= (axisMax - axisMin) / Math.max(1, tickCount);
        if (headerStep > 1 && tickInterval > 0) {
            const headerInterval = tickInterval * headerStep;
            if (axisMax > 0) {
                axisMax = round(axisMax, headerInterval, 'up');
            }
            if (axisMin < 0) {
                axisMin = round(axisMin, headerInterval, 'down');
            }
            tickCount = (axisMax - axisMin) / tickInterval;
        }
        return { minValue: axisMin, maxValue: axisMax, tickCount, tickInterval, headerStep };
    }
    /** main entrance */
    parseData() {
        const { items } = this.options,
            { legendField, valueFormatter } = this.state;
        const { groupData, result } = this.#buildDataMaps(items ?? []),
            { legends, total, maxGroupSize, minValue, maxValue, tickCount, tickInterval, headerStep } = this.#dataStats(groupData),
            range = maxValue - minValue;
        this.#percent = range > 0 ? 1 / range : 0;

        this.state.data = result;
        this.dispatcher('legend?', 'setData', [total, valueFormatter(total)], legends, legendField);
        const styles = {
            '--columns': Math.max(1, result.size),
            '--rows': Math.max(1, tickCount),
            '--stack-count': maxGroupSize,
            '--zero-index': groupData.size ? maxValue / tickInterval : null,
        };
        return { data: result, minValue, maxValue, tickCount, tickInterval, headerStep, styles };
    }

    /** Util: get percentage relative to the range */
    percentRelative(v, unit) {
        return this.percentAbsolute(this.#percent * v, unit);
    }
    /** Util: get absolute percentage */
    percentAbsolute(v, unit) {
        const val = Math.abs(v);
        return unit ? percent(val, PercentDigits) : percentValue(val, PercentDigits);
    }
}

function tabloopMaybe(condition, args) {
    return condition ? ['aui-tabloop', { ...TabloopArgs, ...args }] : ['div', {}];
}
function referenceStyle(minValue, maxValue, value, revert) {
    const range = Math.max(maxValue - minValue, 1),
        p = (v, invert) => percent(invert ? 1 - v : v, 2),
        n = (v) => (v - minValue) / range,
        [start, end] = Array.isArray(value) ? value : [value];
    return [p(n(start), revert), (end != null && p(n(end), true)) || null];
}

/** @extends {Widget<typeof Grid.options>} */
@define(`${NS}-grid`)
export class Grid extends GridData {
    static options = {
        items: Types.array,

        dimension: Types.Enum(['start', 'end', 'nested'], 'start'),
        type: Types.Enum(['bar', 'line'], 'bar'),
        orient: Types.Enum(['h', 'v'], 'h'),
        groupMode: Types.Enum(['group', 'stack', true, false], false),

        color: Types.Union([Types.array, Types.Color]),
        minValue: Types.number,
        maxValue: Types.number,
        axisCount: DefaultAxisCount,
        axisInterval: Types.number,
        axisHeaderInterval: Types.number,
        axisLabelFormat: Types.Union([Types.string, Types.function]),

        axisHeader: Types.string,
        seriesHeader: Types.string,
        valueFormat: Types.Union([Types.string, Types.function]),
        showValue: false,
        showPoint: false,

        groupField: 'group',
        nameField: 'name',
        valueField: 'value',
        colorField: 'color',
    };
    static observers = ['items', 'color', 'minValue', 'maxValue', 'axisInterval', 'axisHeader', 'axisHeaderInterval', 'seriesHeader', 'showValue'];
    static styles = style;

    #reference = new Map();
    init() {
        const { dimension, type, orient, groupMode, axisLabelFormat, valueFormat, showValue, showPoint } = this.options,
            { host } = this,
            isLine = type === 'line',
            _groupMode = (!isLine && (groupMode === true ? 'group' : groupMode)) || null;
        this.state = {
            isRtl: this.isRtl(),
            Graph: this['graph_' + type],
            data: null,
            dimension: host.parentElement?.nodeName === host.nodeName ? 'nested' : dimension,
            orient,
            isLine,
            groupMode: _groupMode,
            useGroupMode: !!_groupMode,
            showValue: showValue && _groupMode !== 'group',
            showPoint,
            axisLabelFormatter: Format(axisLabelFormat),
            valueFormatter: Format(valueFormat),
            legendField: isLine ? 'group' : 'name',
            tooltipField: 'name',
            callback: {},
            useSeriesClick: false,
        };
        this.dispatcher = this.useUnicom(['box', 'grid:' + dimension], this.dataReceiver);
        this.dispatcher('box', 'boxStyle', { containerType: 'inline-size' });
        this.dispatcher('box', 'getCallback').then((callback) => this.setState({ callback, useSeriesClick: !!callback.onSeriesClick }));
    }
    didMount() {
        addTooltip(this.host);
        this.action = Action(this.$element, 'key');
    }
    setOption(name, value, oldValue) {
        if (name === 'items') {
            this.dispatcher('legend?', 'clearData');
        }
    }

    dataReceiver = (action, from, ...args) => {
        if (action === 'setReference') {
            this.setReference(from, ...args);
        } else if (this.action?.[action]) {
            this.action[action](...args);
        }
    };
    setReference(from, data) {
        const cache = this.#reference;
        if (data) {
            cache.set(from, data);
        } else {
            cache.delete(from);
        }
        this.setState();
    }

    onDataClick(item) {
        return (e) => {
            const { original } = item;
            this.dispatcher('box', 'onDataClick', original);
        };
    }
    onSeriesFocus = ({ currentTarget }) => {
        const graph = currentTarget.previousElementSibling;
        graph?.classList.add('hover');
    };
    onSeriesBlur = ({ currentTarget }) => {
        if (!currentTarget.matches(':focus-within')) {
            const graph = currentTarget.previousElementSibling;
            graph?.classList.remove('hover');
        }
    };
    onSeriesClick = (e) => {
        if (!this.state.useSeriesClick) return;
        const content = e.target.textContent,
            { useGroupMode, data } = this.state;
        const cache = data.get(content);
        let result;
        if (Array.isArray(cache)) {
            if (useGroupMode) {
                const list = cache.flatMap((item) => item?.original || []);
                result = TagObject('ChartItemGroup', { group: content, values: list });
            } else {
                result = cache[0]?.original;
            }
        }
        if (!result) return this.console.error('No data found for series:', content);
        this.dispatcher('box', 'onSeriesClick', result);
    };

    referenceInset(minValue, maxValue, value, series) {
        const revert = this.state.orient === 'h',
            block = referenceStyle(minValue, maxValue, value, revert);
        // const inline = referenceStyle(maxValue, series);
        const inline = [0, 0];
        return { 'inset-block-start': block[0], 'inset-block-end': block[1] ?? 'auto', 'inset-inline-start': inline[0], 'inset-inline-end': inline[1] ?? 'auto' };
    }
    graph_bar = (group, { count, index, minValue, maxValue }) => {
        const { orient, groupMode, useGroupMode, showValue, valueFormatter } = this.state,
            reverse = orient === 'h',
            { length } = group;
        const layout = groupMode === 'stack' ? () => 0 : (min, max) => this.percentRelative(reverse ? maxValue - max : min - minValue);
        let sumMin = 0,
            sumMax = 0,
            hasRange = false,
            maxSize = length > 0 ? Number.MIN_SAFE_INTEGER : 0,
            maxOffset = length > 0 ? Number.MIN_SAFE_INTEGER : 0;
        const bars = group.map((item, i) => {
            const { name, value, min, max, range, color, group, type } = item,
                size = this.percentRelative(max - min),
                offset = layout(min, max);
            sumMin += min;
            sumMax += max;
            if (range) hasRange = true;
            maxSize = Math.max(maxSize, size);
            maxOffset = Math.max(maxOffset, offset);
            return (
                <div
                    className={['item', TooltipClassName.Item, TooltipClassName.FocusTarget]}
                    tabIndex={index + i ? -1 : 0}
                    data={{ name, group, value, type, key: name, stack: group, val: valueFormatter(value) }}
                    style={{ color, '--size': size + '%', '--offset': offset + '%' }}
                    onClick={this.onDataClick(item)}
                />
            );
        });
        const valueNode = (name, value, colorIndex) => {
            const { color } = group.at(colorIndex),
                offsetStart = percentUnit(maxOffset, PercentDigits),
                offsetEnd = percentUnit(maxOffset + maxSize, PercentDigits);
            return (
                <section id={`value-${name}-${index}`} className={['current-value', name]} style={{ '--color': color, '--offset-s': offsetStart, '--offset-e': offsetEnd }}>
                    <div className="overflow">{valueFormatter(value)}</div>
                </section>
            );
        };
        if (showValue) {
            if (sumMax !== sumMin && (sumMin < 0 || hasRange)) {
                const node = valueNode('min', sumMin, 0);
                node.classList.add(this.percentRelative(sumMin - minValue) < 100 / count ? 'inside' : 'outside');
                bars.unshift(node);
            }
            if (hasRange || sumMax > 0 || sumMax === sumMin) bars.push(valueNode('max', sumMax, -1));
        }
        return (
            <div className={['graph-box', 'bar', useGroupMode && groupMode, TooltipClassName.Stack]} style={{ '--count': length > 1 ? length : null }}>
                {bars}
            </div>
        );
    };
    graph_line = (group, { count, index, minValue, maxValue }) => {
        const { isRtl, valueFormatter, showPoint } = this.state,
            cx = isRtl ? '100%' : '0',
            focusVisibility = `var(--axis-pointer-visible, ${showPoint ? 'visible' : 'hidden'})`,
            pointVisibility = `var(--axis-pointer-visible, ${showPoint ? 'hidden' : 'visible'})`;
        let i = 0;
        return (
            <div className={['graph-box', 'line', TooltipClassName.Stack]}>
                {group.map((item) => {
                    const { name, value, color, group, next, type } = item,
                        nonLast = next != null,
                        diff = nonLast ? value - next : 0,
                        args = diff === 0 ? { y1: 0, y2: 0 } : diff > 0 === isRtl ? { y1: '100%', y2: '0' } : { y1: '0', y2: '100%' },
                        cy = isRtl ? args.y2 : args.y1,
                        _percent = this.percentRelative((nonLast ? Math.min(value, next) : value) - minValue, true),
                        _diff = this.percentRelative(Math.abs(diff), true);
                    return (
                        <svg:svg
                            className={['item', TooltipClassName.Item]}
                            tabIndex={index + i++ ? -1 : 0}
                            data={{ name, group, value, type, key: group, stack: name, val: valueFormatter(value) }}
                            style={{ color, bottom: _percent, '--diff': _diff }}
                        >
                            {nonLast && <svg:line x1="0" x2="100%" {...args} />}
                            <svg:circle className={TooltipClassName.FocusTarget} cx={cx} cy={cy} style={{ visibility: focusVisibility }} />
                            <svg:circle className="point" cx={cx} cy={cy} r="0.5" style={{ visibility: pointVisibility }} />
                        </svg:svg>
                    );
                })}
            </div>
        );
    };
    axisStop(order, className, content) {
        return (
            <div className={['axis-stop', className]} style={{ '--order': order + 1 }}>
                <div className="axis-label">
                    <span className="overflow empty-hidden">{content}</span>
                </div>
                <div className="axis-line" />
            </div>
        );
    }
    render() {
        /** @type { {data: Map<string, Item[]>} } */
        const { data, minValue, maxValue, tickCount, tickInterval, headerStep, styles } = this.parseData(),
            { axisHeader, seriesHeader } = this.options,
            { Graph, orient, dimension, useGroupMode, groupMode, tooltipField, showValue, axisLabelFormatter, valueFormatter, useSeriesClick } = this.state,
            reverse = orient === 'h',
            mainDimension = dimension !== 'nested',
            count = data.size;
        const [Box, boxArgs] = tabloopMaybe(mainDimension, { arrowMode: orient }),
            [StackGraph, stackGraphArgs] = tabloopMaybe(useGroupMode, { bubbles: false, arrowMode: OrientSwap[orient], arrowReverse: reverse && groupMode === 'stack' });

        // 3n: create dom
        // Set axis at last to keep sticky context order.
        return (
            <>
                <Box className={['grid', 'orient-' + orient]} {...boxArgs} style={styles}>
                    <div className="reference-box">
                        {arrayMap(this.#reference, ([name, item]) => {
                            const { value, series, color, header, type, fillOpacity } = item,
                                inset = this.referenceInset(minValue, maxValue, value, series);
                            return (
                                <div className="reference-item" data={{ name, type }} style={{ ...inset, '--color': color, '--opacity': fillOpacity }}>
                                    {header && <div className="reference-header">{header}</div>}
                                </div>
                            );
                        })}
                    </div>
                    <div className="contents-only">
                        {arrayMap(data, ([label, group], index) => (
                            <div className="stack-box" style={{ '--order': index + 1 }}>
                                <StackGraph className="stack-graph" {...stackGraphArgs}>
                                    {Graph(group, { count, index, minValue, maxValue })}
                                </StackGraph>
                                <div
                                    className="series-label"
                                    data-tooltip="ifneed"
                                    onFocusIn={this.onSeriesFocus}
                                    onFocusOut={this.onSeriesBlur}
                                    onMouseEnter={this.onSeriesFocus}
                                    onMouseLeave={this.onSeriesBlur}
                                    onClick={this.onSeriesClick}
                                    {...keyPressProps('Enter', this.onSeriesClick)}
                                >
                                    <div className="overflow ellipsis" tabIndex={useSeriesClick ? (index ? -1 : 0) : null} data-loop-group="series-content">
                                        {label}
                                    </div>
                                </div>
                            </div>
                        ))}
                    </div>
                    <div className="series">
                        <div className="header empty-hidden">{seriesHeader}</div>
                    </div>
                    <slot />
                    {mainDimension && (
                        <div className="axis" data-dimension={dimension}>
                            <div id="axis-filler" className="axis-stop">
                                <div className="axis-header">
                                    <div className="empty-hidden">{axisHeader}</div>
                                </div>
                                <div className="axis-label" aria-hidden="true">
                                    {axisLabelFormatter(maxValue)}
                                </div>
                                {showValue && (
                                    <div className="axis-label" aria-hidden="true">
                                        {valueFormatter(maxValue)}
                                    </div>
                                )}
                            </div>

                            {tickCount > 0 ? (
                                arrayLoop(tickCount + 1, (i) => {
                                    const value = minValue + tickInterval * (tickCount - i),
                                        order = reverse ? i + 1 : tickCount - i;
                                    return this.axisStop(order, value === 0 && 'origin', i % headerStep === 0 ? axisLabelFormatter(value) : null);
                                })
                            ) : (
                                <>
                                    {this.axisStop(1, 'shim')}
                                    {this.axisStop(reverse ? 2 : 0, 'origin', axisLabelFormatter(0))}
                                </>
                            )}
                        </div>
                    )}
                </Box>
                {mainDimension && <TooltipNode field={tooltipField} groupMode={useGroupMode} />}
            </>
        );
    }
}
