import pointFix from './point-fix.js';

function calc(val, digits) {
    let num = pointFix(val);
    if (digits == null) return num;
    let [a, b = ''] = String(num).split('.');
    b = b.slice(0, digits);
    if (b.length) {
        num = a + '.' + b;
        num = num.replace(/\.0+$/, '');
    } else {
        num = a;
    }
    return Number(num);
}

export function percentUnit(num, digits) {
    return calc(num, digits) + '%';
}

/** @type {typeof $$.number.percentValue} */
export function percentValue(val, digits) {
    return calc((val || 0) * 100, digits);
}

/** @type {typeof $$.number.percent} */
export function percent(val, digits) {
    const num = percentValue(val, digits);
    return num + '%';
}
