/* eslint-disable aui/no-this-alias */
import { info, warn, error } from '../base/log.js';
import { onload } from '../base/onload.js';
import { domRemove as domRemoveObserver } from '../module/observer/observer.js';

import getDetail from '../../util/event/get-detail.js';
import objectForEach from '../../util/object/for-each.js';
import objectMerge from '../../util/object/merge.js';
import stringSplitJoin from '../../util/string/split-join.js';
import { isJQueryElement as typeIsJQueryElement } from '../../util/type/jquery.js';
import { isObject as typeIsObject } from '../../util/type/types.js';

/**
 * Create a synthetic event, and dispatch the event if e.dispatch==true.
 * @param {Event} e The real event.
 * @param {string} e Custom event name.
 * @param {object} e Custom event object, {name, bubbles, cancelable, composed}.
 */
function SyntheticEvent(e) {
    e = e || '';
    const element = $$.getUniqueElement(this),
        eventName = (typeof e === 'string' ? e : e.type) || e.name || 'event',
        { dispatch = false, bubbles = false, cancelable = false, composed = false } = e,
        args = { detail: element, bubbles, cancelable, composed };

    if (!(typeof e === 'object' && e.type)) e = new CustomEvent(eventName, args);
    if (dispatch) element.dispatchEvent(e);

    return e;
}

let widgetUuid = 0;
const className = 'aui-widget';

onload(function () {
    domRemoveObserver(
        null,
        function (elements) {
            for (const element of elements) {
                objectForEach(jQuery.data(element), function (k, instance) {
                    if (instance && typeof instance.destroy === 'function') {
                        queueMicrotask(() => element.isConnected || instance.destroy());
                    }
                });
            }
        },
        '.' + className
    );
});

export function widget(name, prototype) {
    const base = WidgetBase;
    let existingConstructor, constructor, basePrototype;

    const namespace = name.split('.', 1)[0];
    name = name.split('.', 2)[1];
    const fullName = namespace + '-' + name;

    jQuery[namespace] = jQuery[namespace] || {};
    existingConstructor = jQuery[namespace][name];
    constructor = jQuery[namespace][name] = function (options, element) {
        // eslint-disable-next-line no-proto
        Object.assign(this.__proto__.__proto__, WidgetBase.extends);

        // Allow instantiation without "new" keyword
        if (!this || !this._createWidget) {
            return new constructor(options, element);
        }

        // Allow instantiation without initializing for simple inheritance
        // must use "new" keyword (the code above always passes args)
        if (arguments.length) {
            this._createWidget(options, element);
        }
    };

    // Extend with the existing constructor to carry over any static properties
    Object.assign(constructor, existingConstructor, {
        // Copy the object used to create the prototype in case we need to
        // redefine the widget later
        _proto: { ...prototype },

        // Track widgets that inherit from this widget in case this widget is
        // redefined after a widget inherits from it
        _childConstructors: [],
    });

    basePrototype = new base();

    // We need to make the options hash a property directly on the new instance
    // otherwise we'll modify the options hash on the prototype that we're
    // inheriting from
    basePrototype.options = objectMerge({}, basePrototype.options, false);
    constructor.prototype = objectMerge(basePrototype, prototype, {
        constructor: constructor,
        namespace: namespace,
        widgetName: name,
        widgetFullName: fullName,
    });

    // If this widget is being redefined then we need to find all widgets that
    // are inheriting from it and redefine all of them so that they inherit from
    // the new version of this widget. We're essentially trying to replace one
    // level in the prototype chain.
    if (existingConstructor) {
        jQuery.each(existingConstructor._childConstructors, function (i, child) {
            const childPrototype = child.prototype;

            // Redefine the child widget using the same prototype that was
            // originally used, but inherit from the new version of the base
            widget(childPrototype.namespace + '.' + childPrototype.widgetName, constructor);
        });

        // Remove the list of existing child constructors from the old constructor
        // so the old child constructors can be garbage collected
        delete existingConstructor._childConstructors;
    } else {
        base._childConstructors.push(constructor);
    }

    jQuery.fn[name] = function (options, ...args) {
        if (!this.length) {
            info(`Cannot call widget "${name}" on empty element collection!`);
            return this;
        }
        // Only executes for the first element.
        const element = this.get(0),
            instance = jQuery.data(element, fullName),
            isMethodCall = typeof options === 'string';
        if (isMethodCall) {
            if (instance) {
                if (options === 'instance') {
                    return instance;
                } else if (options === 'option') {
                    const [k, v] = args;
                    if (v === undefined) {
                        const type = $$.getClassBuiltIn(k);
                        if (type === 'Object') {
                            instance._setOptions(k);
                        } else if (type === 'String') {
                            return instance.options[k];
                        }
                    } else {
                        instance._setOptions({ [k]: v });
                    }
                } else if (typeof instance[options] !== 'function' || options.charAt(0) === '_') {
                    error(`No such method "${options}" for ${name} widget instance!`);
                } else {
                    return instance[options](...args);
                }
            } else {
                error(`Cannot call methods on ${name} prior to initialization; attempted to call method "${options}"!`);
            }
        } else {
            // Allow multiple hashes to be passed on init
            if (args.length) {
                options = objectMerge(options, ...args);
            }
            if (instance) {
                instance._setOptions(options);
                if (instance._init) {
                    instance._init();
                }
            } else {
                jQuery.data(this, fullName, new constructor(options, element));
            }
        }
        return this;
    };

    return constructor;
}

export class WidgetBase {
    static extends = {};
    static _childConstructors = [];
    static method(widget, fnName, ...args) {
        const constructor = WidgetBase._childConstructors.find((c) => c.prototype.widgetName === widget);
        if (constructor) {
            const proto = constructor.prototype,
                fn = proto[fnName];
            if (typeof fn === 'function') {
                return fn.apply(proto, args);
            } else if (fn && args.length === 0) {
                return fn;
            }
        }
        return undefined;
    }
    widgetName = 'widget';
    defaultElement = '<div>';
    bindings = jQuery();
    created = true;
    section = false;
    optionOrder = [];
    options = {
        disabled: false,
    };

    _createWidget(options, element) {
        this.$element = jQuery(element || this.defaultElement || this);
        this.element = this.$element.get(0);
        if (this.element.nodeName !== 'BODY') this.$element.addClass(this.className ?? className);
        this.uuid = widgetUuid++;
        this.eventNamespace = '.' + this.widgetName + this.uuid;
        this.defaultId = this.namespace.replace(/\d+$/, '') + '-' + this.widgetName + '-' + this.uuid;

        if (element !== this) {
            jQuery.data(element, this.widgetFullName, this);
        }
        if (!element.isConnected) error('The element which called widget: [' + this.widgetName + '] does not exist');

        this.options = objectMerge({}, this.options, options, false);
        this._create();
        if (this.section) {
            this.element.dataset.section = this.section;
        }
        this.created = true;
        this._init();
    }

    _create() {}

    _init() {}

    _initMember() {}

    _initEvent() {}

    destroy() {
        if (this.created) {
            this._destroy();
            this.created = false;
            // We can probably remove the unbind calls in 2.0
            // all event bindings should go through this._on()
            this.$element.off(this.eventNamespace).removeData(this.widgetFullName).removeAttr('aria-disabled');

            // Clean up events and states
            this.bindings.off(this.eventNamespace);
        }
    }

    _destroy() {}

    _ShellBridge(element, fn, ...args) {
        if (!$$.shell.getInstance) return warn('No Shell!');
        if (!element) element = this.element;
        if (typeIsJQueryElement(element)) element = element.get(0);
        const instance = $$.shell.getInstance(element);
        if (!fn) return instance;
        return $$.fn(instance[fn], instance)(...args);
    }

    _setOptions(options = {}) {
        const list = this.optionOrder || [],
            queue = [];
        objectForEach(options, (k, v) => {
            const index = list.indexOf(k);
            if (index > -1) {
                queue[index] = { k, v };
            } else if (!Object.is(this.options[k], v)) {
                const oldValue = this.options[k];
                this._setOption(k, v, oldValue);
            }
        });
        for (const option of queue) {
            const { k, v } = option || {};
            const oldValue = this.options[k];
            if (k !== undefined && !Object.is(oldValue, v)) {
                this._setOption(k, v, oldValue);
            }
        }
    }

    _setOption(key, value) {
        this.options[key] = value;
        return this;
    }

    _off(element, eventName) {
        eventName = (eventName || '').split(' ').join(this.eventNamespace + ' ') + this.eventNamespace;
        jQuery(element).off(eventName);

        // Clear the stack to avoid memory leaks (#10056)
        this.bindings = jQuery(this.bindings.not(element).get());
    }

    /**
     * Add event listener to an element.
     * @param {Element} element [Optional] One or more space-separated event types.
     * @param {String} types The event types that splitted by space.
     * @param {String} selector [Optional] A selector string to filter the descendants of the selected elements that trigger the event.
     * @param {Function} handler A function to execute when the event is triggered.
     * @example this._on('click', function(e){} );
     * @example this._on('click', 'li', function(e){} );
     * @example this._on(this.$box, 'click', function(e){} );
     * @example this._on({ click: function(e){}, focus: function(e){} });
     * @example this._on(this.box, { click: function(e){}, focus: function(e){} });
     */
    _on(element, types, selector, handler) {
        const self = this;
        if (typeof element === 'string' || typeIsObject(element)) {
            // types, selector, handler
            handler = selector;
            selector = types;
            types = element;
            element = this.element;
        }
        const $element = jQuery(element);
        if ($element.length === 0) return;
        if ($element.get(0) !== this.element) this.bindings = this.bindings.add($element);
        if (typeIsObject(types)) {
            return objectForEach(types, (k, handler) => {
                const [type, selector] = k.split(' ');
                this._on($element, type, selector, handler);
            });
        }
        if (typeof selector === 'function') {
            // element, types, handler
            handler = selector;
            selector = '';
        }
        // split types & add namespace.
        const events = stringSplitJoin(types, ' ', (e) => e + this.eventNamespace);

        function handlerProxy(e) {
            const args = [...arguments],
                $element = jQuery(this),
                detail = getDetail(e),
                fn = typeof handler === 'string' ? self[handler] : handler;
            SyntheticEvent.call(self.element, e);
            if (self.options.disabled === true || $element.is(':disable')) return;
            if (detail != null) args.push(detail);
            return fn.apply(self, args);
        }

        const args = [events, handlerProxy];
        if (selector) args.splice(1, 0, selector);
        $element.on(...args);
    }

    _callback(name, ...args) {
        if (typeof name === 'function') return name(...args);

        const fn = this.options[name];
        if (typeof fn === 'function') return fn(...args);

        return undefined;
    }

    /**
     * Call the handlerFunction.
     * @param {string} name The handler function name in options.
     * @param {Array<any>} args Callback arguments.
     */
    _handler(name, ...args) {
        this.$element.triggerHandler(name);
        return this._callback(name, ...args);
    }

    /**
     * Similar with Handler, applies when a event triggered high frequently, the callback will called only once.
     */
    _handlerInterval(...args) {
        const self = this;
        clearTimeout(this._handlerIntervalTimer);
        this._handlerIntervalTimer = setTimeout(function () {
            const first = args[0];
            if (args.length === 1 && typeof first === 'function') {
                return first.call(self);
            }
            self._handler(...args);
        }, 100);
    }
}
