import { dev } from './base/log.js';

export function ErrorBoundary(createElement) {
    return function ErrorReport(errorDetail) {
        const onDev = dev();
        if (!onDev) return createElement('div');
        return createElement(
            'div',
            { style: { color: 'var(--error-color)', border: '3px solid currentcolor', padding: '8px 16px' } },
            createElement('h1', { style: { color: 'inherit' } }, 'There is something wrong crashed, please check your code!'),
            createElement('pre', { style: { whiteSpace: 'pre-wrap', overflow: 'auto' } }, errorDetail)
        );
    };
}
