import mime2ext from './mime2ext.js';

/** @type {typeof $$.io.blobFile} */
export default function blobFile(blob, fileName) {
    const mime = blob.type || 'text/plain',
        ext = mime2ext(mime);
    if (!fileName) {
        fileName = 'temp.' + ext;
    } else if (fileName.startsWith('.')) {
        fileName = 'temp' + fileName;
    } else if (!fileName.includes('.')) {
        fileName = fileName + '.' + ext;
    }
    return new File([blob], fileName, { type: mime });
}
