/** @jsxImportSource @gui/aui-devops */
import { define, Widget, Types } from '../../widget/widget.js';

import { keyName } from '../../util/event/key-name.js';
import formatString from '../../util/string/format.js';

import style from './quick-table.less';

/** @extends {Widget<typeof Quicktable.options>} */
@define('editor-quicktable')
export class Quicktable extends Widget {
    static options = {
        size: 10,
        caption: Types.string,
        onChange: Types.function,
    };
    static styles = style;
    method = { getPosition: this.getPosition };
    create() {
        this.state = { row: 1, col: 1 };
    }
    didMount() {
        this.setValue();
    }
    getValue(e) {
        const { row, col } = { ...this.state, ...e.target.dataset };
        return [row, col];
    }
    setValue(row = 1, col = 1) {
        if (arguments.length) this.setState({ row, col });
        this.dynamicStyle(`tr:nth-child(-n + ${row}) td:nth-child(-n + ${col}) {background: var(--selected-color)}`);
    }

    onClick = (e) => {
        if (!$$.mobileView) {
            this.callback('onChange', ...this.getValue(e));
        }
    };
    cellNavigation(e, [offsetRow, offsetCol]) {
        e.stopPropagation();
        const { size } = this.options;
        let { row, col } = this.state;
        row += offsetRow;
        col += offsetCol;
        if (row > 0 && row <= size && col > 0 && col <= size) {
            this.setValue(row, col);
        }
    }
    onKeyDown = (e) => {
        switch (keyName(e)) {
            case 'ArrowUp':
                return this.cellNavigation(e, [-1, 0]);
            case 'ArrowDown':
                return this.cellNavigation(e, [1, 0]);
            case 'ArrowLeft':
                return this.cellNavigation(e, [0, -1]);
            case 'ArrowRight':
                return this.cellNavigation(e, [0, 1]);
            case 'Enter':
                return this.onClick(e);
        }
    };
    onPointerLeave = (e) => {
        this.setValue(1, 1);
    };
    onPointerEnter = (e) => {
        this.setValue(...this.getValue(e));
    };
    onTouchMove = (e) => {
        e.stopPropagation();
        this.move = true;
        const [row, col] = this.getValue(e);
        const current = { x: e.touches[0].pageX, y: e.touches[0].pageY };
        const x = (current.x - this.origin.x) / e.target.offsetWidth,
            y = (current.y - this.origin.y) / e.target.offsetHeight;
        this.row = Math.round(y + Number.parseInt(row, 10));
        this.col = Math.round(x + Number.parseInt(col, 10));
        this.setValue(this.row, this.col);
    };
    onTouchStart = (e) => {
        this.origin = { x: e.touches[0].pageX, y: e.touches[0].pageY };
    };
    onTouchEnd = (e) => {
        if (this.move) {
            this.move = false;
        } else {
            [this.row, this.col] = this.getValue(e);
        }
        this.setValue(this.row, this.col);
    };
    getPosition() {
        return [this.row ?? 1, this.col ?? 1];
    }
    render() {
        const { row, col } = this.state,
            { size, caption } = this.options,
            captionData = caption.includes('{1}') ? [row, col] : [`${row}×${col}`],
            arr = Array.from({ length: size });
        return (
            <table onTouchMove={this.onTouchMove} onTouchStart={this.onTouchStart} onTouchEnd={this.onTouchEnd}>
                <caption>{formatString(caption, ...captionData)}</caption>
                <tbody tabIndex={0} onClick={this.onClick} onKeyDown={this.onKeyDown} onPointerLeave={this.onPointerLeave}>
                    {arr.map((_, i) => (
                        <tr>
                            {arr.map((_, j) => (
                                <td data-row={i + 1} data-col={j + 1} onPointerEnter={this.onPointerEnter} />
                            ))}
                        </tr>
                    ))}
                </tbody>
            </table>
        );
    }
}
