import $ from '../../element/index.js';

import { isElement } from '../../../util/type/types.js';

const stack = new Map();
let timer, willFocus;

function getNext(key) {
    if (stack.size > 0) {
        const iterator = stack[Symbol.iterator]();
        let item = iterator.next();
        while (item.done !== true) {
            const [k, _v] = item.value,
                next = iterator.next();
            if (k === key && !next.done) {
                return next.value;
            }
            item = next;
        }
    }
    return null;
}

function focus(element) {
    if (element) {
        const type = $$.getClassBuiltIn(element);
        if (/^Widget\(\w+\)$/.test(type) && element.host) element = element.host;
        if (isElement(element)) {
            if (!element.isConnected) element = $.$body.get();
            const editable = $$.browser.touchable && element.matches(':read-write');
            if (editable) tempDisable(true);
            element.focus({ preventScroll: true });
            if (editable) tempDisable(false);
        } else {
            $$.fn(element.focus, element)();
        }
    }
    // prevent virtual keyboard on focusBack.
    function tempDisable(disabled) {
        const editable = element.hasAttribute('contenteditable');
        $(element).toggleAttr(editable ? 'contenteditable' : 'readonly', disabled !== editable);
    }
}

function $activeElement() {
    return $.$activeElement();
}

function hasBackdrop(element) {
    if (!element) return false;
    if ($(element).find('aui-backdrop', { crossShadow: true }).length) return true;
    const style = getComputedStyle(element, '::backdrop'),
        { pointerEvents, backgroundColor } = style || {};
    // Ignored when pointerEvents=none, it's penetrable.
    return pointerEvents !== 'none' && backgroundColor && !/rgba?\(0(\,\s?0){2,3}\)/.test(backgroundColor);
}

/** Called before current element shown(focused). */
export function FocusPush(instance, inElement) {
    if (!inElement) inElement = willFocus || $activeElement().get();
    if (instance != null) {
        stack.set(instance, inElement);
        clearTimeout(timer);
        willFocus = null;
    }
    return inElement;
}
export function FocusPop(instance, outElement) {
    if (instance == null) return null;
    if (!outElement) outElement = stack.get(instance);
    const next = getNext(instance);
    stack.delete(instance);
    if (next != null) {
        const [k, v] = next,
            active = $activeElement().is(':tabbable');
        let shouldFocus = !active,
            element = instance.host || instance.element || instance;
        if (!isElement(element)) element = null;
        if (element === v || !$.is(v, ':visible') || hasBackdrop(element)) {
            shouldFocus = true;
            stack.set(k, outElement);
        }
        if (shouldFocus) focus(k);
        return active || k;
    } else if (outElement != null) {
        // last one => focus back.
        willFocus = outElement;
        timer = setTimeout(() => {
            if (!$activeElement().is(':tabbable')) focus(outElement);
            willFocus = null;
        }, 100);
        return outElement;
    }
}
