/** @jsxImportSource @gui/aui-devops */
import { inherit } from '../../widget/widget.js';

import kebabCase from '../../util/string/kebab-case.js';

import { Avatar } from '../avatar/avatar.js';
import { Profile } from '../profile/profile.js';

/** @typedef {ReturnType<typeof import('./utils.js').buildItem>} ItemEntity */

/**
 * @typedef {(item: ItemEntity) => Element} ItemTemplate
 * @param {Widget} proto
 * @param {(forwardOptions: ReturnType<typeof inherit>['forwardOptions']) => ItemTemplate} cb
 */
const buildTemplate = (proto, cb) => cb(inherit(proto).forwardOptions);

const Templates = {
    avatar: buildTemplate(Avatar, (forwardOptions) => ({ original, text, ...item }) => {
        const args = forwardOptions({ ...original, ...item });
        return <aui-avatar {...args} name={text} role="none" />;
    }),
    profile: buildTemplate(Profile, (forwardOptions) => ({ original, text, ...item }) => {
        const args = forwardOptions({ ...original, ...item });
        return <aui-profile {...args} name={text} role="none" />;
    }),
};

const AnyTemplate = function (t) {
    if (typeof t !== 'function') return null;
    return ({ original }) => t(original);
};

export default function parseTemplate(console) {
    const { error } = console || $$;
    return function (t) {
        if (typeof t === 'string') {
            const _t = kebabCase(t.replace(/^aui\-/, ''));
            if (Object.hasOwn(Templates, _t)) {
                const x = Templates[_t];
                return x;
            }
            error('Unsupported template:', t);
        }
        return AnyTemplate(t);
    };
}
