import { error } from '../../core/base/log.js';
import $ from '../../core/element/index.js';

import load from './load.js';

/** @type {typeof $$.img.img2base64} */
export default function img2base64(element, callback) {
    let src = element.src;
    const canvas = document.createElement('canvas'),
        { width, height } = $(element).size();
    canvas.width = width;
    canvas.height = height;
    src = src + (src.includes('?') ? '&' : '?') + 'd=' + Date.now();
    load(src).then((img) => {
        let url;
        const ctx = canvas.getContext('2d');
        ctx.drawImage(img, 0, 0, width, height);
        try {
            // eslint-disable-next-line unicorn/new-for-builtins
            url = new String(canvas.toDataURL());
        } catch (e) {
            // eslint-disable-next-line unicorn/new-for-builtins
            url = new String('');
            error(e);
        }
        url.width = width;
        url.height = height;
        callback(url);
    });
}
