import valid from '../../util/css/valid.js';
import forEach from '../../util/object/for-each.js';
import camelCase from '../../util/string/camel-case.js';
import kebabCase from '../../util/string/kebab-case.js';
import { isCustomElement, isPrimitive } from '../../util/type/types.js';

import classList from './class-list.js';

const lowers = {
    global: ['accessKey', 'autoCapitalize', 'autoFocus', 'contentEditable', 'itemID', 'itemProp', 'itemRef', 'itemScope', 'itemType', 'spellCheck', 'tabIndex'],
    form: ['acceptCharset', 'autoComplete', 'dateTime', 'encType', 'enterKeyHint', 'inputMode', 'maxLength', 'minLength', 'noValidate', 'readOnly'],
    submit: ['formMethod', 'formAction', 'formEncType', 'formNoValidate', 'formTarget'],
    media: ['allowFullScreen', 'autoPlay', 'controlsList', 'disablePictureInPicture', 'disableRemotePlayback', 'playsInline'],
    sources: ['crossOrigin', 'fetchPriority', 'noModule', 'referrerPolicy', 'useMap', 'frameBorder', 'srcDoc', 'srcLang', 'srcSet'],
    table: ['cellPadding', 'cellSpacing', 'colSpan', 'rowSpan'],
    link: ['imageSizes', 'imageSrcSet', 'hrefLang'],
    others: ['charSet', 'httpEquiv'],
};
export const LowerAttrs = new Set(Object.values(lowers).flat());

const booleans = {
    global: ['open', 'autofocus', 'hidden', 'inert', 'itemscope', 'reversed'],
    form: ['checked', 'selected', 'multiple', 'readonly', 'disabled', 'required', 'formnovalidate', 'novalidate'],
    media: ['autoplay', 'controls', 'loop', 'muted', 'playsinline', 'disablepictureinpicture', 'disableremoteplayback'],
    sources: ['async', 'defer', 'nomodule'],
};
export const BoolAttrs = new Set(Object.values(booleans).flat());
const BoolAttrsGlobal = new Set(booleans.global);

export const AttrMapping = { className: 'class', htmlFor: 'for' };
export const BoolException = { checked: ['mixed'] };

export function ToggleAttr(element, name, force) {
    if (!BoolAttrs.has(name)) return false;
    force = force === 'true' ? true : force === 'false' ? false : force;
    const exception = BoolException[name];
    if (exception?.includes(force)) {
        element.setAttribute(name, force);
    } else {
        force = !!force;
        if (isCustomElement(element)) {
            element.setAttribute(name, BoolAttrsGlobal.has(name) ? force : String(force));
        } else {
            element.toggleAttribute(name, force);
        }
    }
    return true;
}

export function AttrName(name) {
    if (AttrMapping[name]) return AttrMapping[name];
    if (LowerAttrs.has(name)) return name.toLowerCase();
    return kebabCase(name);
}

function setAttrFunction(element, k, v, customElement) {
    const captureIndex = k.indexOf('Capture'),
        useCapture = captureIndex > -1,
        _k = useCapture ? k.slice(0, captureIndex) : k;
    const handler = _k.toLowerCase();
    if (!customElement && !useCapture && element[handler] !== undefined) {
        element[handler] = v;
        return true;
    } else if (/^on([a-zA-Z]+)$/.test(_k)) {
        let name = RegExp.$1;
        if (customElement || _k.startsWith('SVG')) {
            name = _k;
        } else if (name.endsWith('Event')) {
            name = name[0].toLowerCase() + name.slice(1);
        } else {
            name = name.toLowerCase();
        }
        element.addEventListener(name, v, useCapture);
        return true;
    }
    return false;
}

function setAttr(element, k, _k, v, children) {
    const type = typeof v,
        customElement = isCustomElement(element);
    switch (k) {
        case 'class':
            element.classList.add(...classList(v));
            return true;
        case 'classify': {
            const color = String(v);
            if (customElement || !color) return false;
            const bg = v.bg,
                name = v.name;
            element.style.setProperty('--classify', String(v));
            if (bg) element.style.setProperty('--classify-bg', bg);
            if (name) element.dataset.classify = name;
            return true;
        }
        case 'style':
            if (type === 'object') {
                for (const key of Object.keys(v)) {
                    const value = v[key];
                    if (value == null) continue;
                    if (key.startsWith('--')) {
                        element.style.setProperty(key, value);
                    } else {
                        element.style[camelCase(key)] = valid(key, value, { checkValue: false });
                    }
                }
            } else {
                element.style.cssText = v;
            }
            return true;
        case 'data':
            if (type === 'object') {
                forEach(v, (key, val) => {
                    if (val != null) element.dataset[key] = val;
                });
            }
            return true;
    }
    if (type === 'function') {
        return setAttrFunction(element, k, v, customElement);
    } else if (isPrimitive(0, type)) {
        if (_k.indexOf('on-') === 0) return false;
        if (!ToggleAttr(element, _k, v)) element.setAttribute(_k, v);
        return true;
    } else if (Reflect.has(element, k)) {
        // eslint-disable-next-line unicorn/no-lonely-if
        if (/^aria[A-Z]/.test(k)) element[k] = v;
    }
    return false;
}

/**
 * set element "attribute", undefined value will remove attribute, onXXX will addEventListener.
 * @param children only for internal reference.
 */
export function SetAttr(element, k, v, children) {
    const ns = typeof this === 'string' ? this : null;
    if (AttrMapping[k]) k = AttrMapping[k];
    let _k = LowerAttrs.has(k) ? k.toLowerCase() : k;
    if (!ns) _k = kebabCase(_k);

    if (v != null) return setAttr(element, k, _k, v, children);
    if (arguments.length > 2 && v === undefined) {
        element.removeAttribute(_k);
        return true;
    }
    return false;
}
