import $ from '../../core/element/index.js';

const callbackQueue = new Set(),
    { promise, resolve } = Promise.withResolvers();
let init = false;
let isLock = null;

function updateState(e) {
    const locked = $$.fn(e.getModifierState, e)('CapsLock');
    if (locked != null && isLock !== locked) {
        for (const cb of callbackQueue) cb(locked);
        resolve(locked);
        isLock = locked;
    }
}

export function initCapsLock() {
    if (!init) {
        const { $body } = $;
        $body.on('keyup', updateState);
        $body.on('pointerdown', updateState);
        init = true;
    }
}

export function listenCapsLock(callback, toggle) {
    if (!callback || typeof callback !== 'function') return;
    if (toggle) {
        callbackQueue.add(callback);
        callback(isLock);
    } else {
        callbackQueue.delete(callback);
        callback(null);
    }
}

/** @type {typeof $$.event.getCapsLock} */
export function getCapsLock(...args) {
    initCapsLock();
    listenCapsLock(...args);
    return isLock == null ? promise : Promise.resolve(isLock);
}
