import sort from '../array/sort.js';

/** @type {typeof $$.string.splitAt} */
export default function splitAt(val, ...indices) {
    const arr = [],
        l = val.length;
    let i = 0;
    indices = sort(indices, true);
    for (let j = 0; j < l; j++) {
        if (j === indices[0]) {
            i++;
            indices.shift();
        }
        if (!arr[i]) arr[i] = '';
        arr[i] += val[j];
    }
    return arr;
}
