import gcd from './gcd.js';
import pointFix from './point-fix.js';

/** @type {typeof $$.number.float2fraction} */
export default function float2fraction(num) {
    if (!Number.isFinite(num)) return null;
    let x = pointFix(num);
    const l = String(x).split('.', 2)[1]?.length ?? 0;
    let y = Math.pow(10, l);
    x *= y;
    const divisor = gcd(x, y);
    x /= divisor;
    y /= divisor;
    return x + '/' + y;
}
