import getValue from './get-value.js';
import valid from './valid.js';

const colorFunctions = new Set(['rgb', 'rgba', 'hsl', 'hsla', 'hwb', 'lab', 'lch', 'oklab', 'oklch']);
/** @param {string} v */
export const colorLike = (v) => typeof v === 'string' && (/#[0-9a-f]{3,8}$/i.test(v) || (v.endsWith(')') && colorFunctions.has(v.slice(0, v.indexOf('(')))));

function parseSuffix(suffix) {
    if (suffix === 'color' || suffix === 'bg') return suffix;
    if (Number.isInteger(suffix) && suffix >= 1 && suffix <= 10) return String(suffix);
    return null;
}

/** @type {typeof $$.css.classifyColor} */
export function classifyColor(value, allowColor, suffix, classifies) {
    if (value) {
        const accurate = Array.isArray(classifies),
            classify = !accurate || classifies.includes(value) ? value : null;
        if (classify) {
            const validSuffix = parseSuffix(suffix),
                property = `--${classify}-${validSuffix ?? 'color'}`,
                classifyColor = `--classify-${classify}`;
            if (accurate) return `var(${property})`;

            if (!colorLike(value)) {
                const cssVar = validSuffix ? property : classifyColor;
                if (getValue(cssVar)) return `var(${cssVar})`;
            }
        }
        if (allowColor) return valid('color', value);
    }
    return null;
}
