import { warn, error } from "../base/log.js";

import { getValue } from "../../util/value-path.js";

(function () {
    function replaceTemplateH(text, option) {
        /// How to using HTML template.
        const regexp = /\{props\.([a-z]+(\.\w+)?)\}/gi;
        if (regexp.test(text)) {
            text = text.replaceAll(regexp, function (match, name) {
                const val = getValue(option, name, true);
                return val;
            });
        }
        return text;
    }
    function renderCustomTemplate(element, option) {
        const clone = element.content.cloneNode(true),
            template = document.createElement('aui-t');
        template.append(clone);
        const [...nodes] = template.childNodes;
        for (const node of nodes) {
            if (node.nodeType === Node.ELEMENT_NODE) {
                for (const { name, value } of node.attributes) {
                    node.setAttribute(name, replaceTemplateH(value, option));
                }
                nodes.push(...node.childNodes);
            } else if (node.nodeType === Node.TEXT_NODE) {
                const text = replaceTemplateH(node.nodeValue, option);
                if (text !== node.nodeValue) node.parentNode.replaceChild(document.createTextNode(text), node);
            }
        }
        return template;
    }

    function renderTemplate(template, option) {
        if (!template) {
            this.html('');
            return '';
        }
        while (typeof template === 'function' && !$$.fnExtends(template, $$.shell?.proto)) {
            template = template(option);
        }
        let element;
        const type = $$.getClassBuiltIn(template);
        return new Promise((resolve, reject) => {
            const doReject = (err) => error(err, template, option) || reject();
            if (type === 'Function') {
                // Shell definition, class or function, Create element instance.
                if ($$.fnExtends(template, $$.shell?.proto)) {
                    element = $$.shell?.createElement(template, option);
                }
            } else if (/^HTML[a-zA-Z]*Element$/.test(type) || $$.type.isShellElement(template)) {
                element = template;
            } else if (type === 'String') {
                if (/^(\.|#)[a-z]/.test(template)) {
                    // Element query, Get Element Object.
                    try {
                        element = document.querySelector(template);
                        if (element instanceof HTMLTemplateElement) {
                            element = renderCustomTemplate(element, option);
                        }
                    } catch (err) {
                        element = null;
                        error(err);
                    }
                }
                if (!element) {
                    if (template[0] === '<' && template.slice(-1) === '>') {
                        // html string;
                        element = document.createElement('div');
                        warn('Pay attention to security bomb by using html string to create element!');
                        element.setHTMLUnsafe(template);
                        element = element.firstChild;
                    } else {
                        let auiTemplate = window.customElements.get(template);
                        if (!auiTemplate) {
                            auiTemplate = window.customElements.get('aui-' + template);
                            if (auiTemplate) template = 'aui-' + template;
                        }
                        if (auiTemplate) {
                            // build-in custom element templates.
                            element = auiTemplate.CreateElement(option);
                        } else if (option) {
                            return void doReject('Template not found!');
                        } else {
                            // plain text.
                            element = document.createTextNode(template);
                        }
                    }
                }
            }
            if (element) {
                $$.tempInsert.call(this, element, resolve);
            } else {
                doReject('Template invalid!');
            }
        });
    }

    Object.assign($$, {
        renderTemplate: function (template, source, ...args) {
            const single = !Array.isArray(source),
                items = single ? [source] : source.slice(),
                list = items.map((item) => renderTemplate.apply(item?.element || this, [template, item, ...args]));
            return Promise.allSettled(list).then((results) => {
                const values = results.map((result) => (result.status === 'fulfilled' ? result.value : null));
                return single ? values[0] : values;
            });
        },
    });
})();
