/** @jsxImportSource @gui/aui-devops */
import { define, Widget, Types } from '../widget.js';

import style from './checkbox.less';

/** @extends {Widget<typeof Checkbox.options>} */
@define('checkbox-lite')
export class Checkbox extends Widget {
    static options = {
        name: Types.string,
        value: Types.Union([Types.string, Types.number, Types.boolean]),
        checked: Types.Enum(['mixed', true, false], false),
        disabled: false,
        readonly: false,
        required: false,
        onChange: Types.function,
        willChange: Types.function,
    };
    static observers = ['name', 'value', 'checked', 'disabled', 'readonly'];
    static shadow = { delegatesFocus: true, referenceTarget: 'input' };
    static ariaTarget = '#input';
    static formAssociated = true;
    static styles = style;

    actionElement = null;
    init() {
        this.state = { checked: this.options.checked };
    }
    didMount() {
        this.actionElement = this.shadowRoot.getElementById('input');
        this.updateByEvent();
    }
    didRender() {
        queueMicrotask(() => {
            this.actionElement.indeterminate = this.state.checked === 'mixed';
        });
    }
    setOption(name, value) {
        if (name === 'checked') {
            if (this.state.checked === value) return false;
            this.state.checked = value;
        }
    }
    updateByEvent() {
        this.actionElement.dispatchEvent(new InputEvent('input', { bubbles: true, composed: true }));
    }
    onChange = (e) => {
        const { checked: lastChecked, onChange, value } = this.options;
        let { checked } = e.target;
        if (lastChecked === 'mixed') checked = true;
        const willChecked = this.callback('willChange', checked, value) ?? checked;

        if (willChecked !== lastChecked) {
            if (onChange) {
                this.callback('onChange', willChecked, value);
            } else {
                this._setOption('checked', willChecked);
            }
        }
        if (e.target.checked !== willChecked) {
            e.target.checked = willChecked;
            this.state.checked = willChecked;
            this.updateByEvent();
        }
    };
    render() {
        const { name, value, disabled, readonly, required } = this.options,
            { checked } = this.state,
            args = { name, value, checked: !!checked, readonly: readonly || null, disabled: disabled || readonly, required },
            arias = this.arias({ checked, disabled });
        return (
            <label>
                <slot className="block start" name="block-start" />
                <slot className="inline start" name="inline-start" />
                <input type="checkbox" id="input" className="action" {...args} {...arias} onChange={this.onChange} />
                <slot className="inline end" name="inline-end" />
                <slot className="block end" name="block-end" />
            </label>
        );
    }
}
