/** @type {typeof $$.io.base64Blob} */
export default function base64Blob(data, contentType) {
    const parts = data.split(';base64,'),
        raw = window.atob(parts.at(-1)),
        length = raw.length,
        arr = new Uint8Array(length);
    if (!contentType && parts.length > 1) contentType = parts[0].split(':', 2)[1];
    for (let i = 0; i < length; i++) {
        arr[i] = raw.codePointAt(i);
    }
    const args = {};
    if (contentType) args.type = contentType;
    return new Blob([arr], args);
}
