import { fileType, typeIcons, iconMapping } from './file-type.js';

function union(...args) {
    const [...arr] = new Set(args.flat());
    return arr;
}

/** @type {typeof $$.io.fileTypeExtend} */
export default function fileTypeExtend(list) {
    for (const { type, suffix, icon } of list) {
        if (!typeIcons.includes(type)) typeIcons.push(type);
        fileType[type] = union(fileType[type] || [], suffix);
        iconMapping[type] = icon;
    }
}
