/// undo: additional.
import { error } from '../../base/log.js';
import $ from '../../element/index.js';

import stop from '../../../util/event/stop.js';

const DefaultOptions = {
    filterQuery: null,
};
function focus(el, e) {
    stop(e);
    if (el) {
        el.focus({ focusVisible: true });
        if (el.selectionDirection && el.select) el.select(); // select input&textarea content.
    }
}

export class Tabloop {
    #enable = false;
    constructor(element, options = {}) {
        this.$element = $(element);
        this.doc = element.ownerDocument;
        const args = { ...DefaultOptions, ...options };
        this.options = args;
        this.$element.on('keydown', this.onAction);
    }
    onAction = (e) => {
        /// temp public for compat.
        if (this.#enable && e.key === 'Tab') {
            this.#onTab(e);
        }
    };
    #onTab(e) {
        this.#tabLoop(e, e.shiftKey ? -1 : 1);
    }
    #queryAcross(query, $scope = this.$element) {
        return $scope.findAll(query, { crossShadow: true, crossSlot: true });
    }
    #getList() {
        const { $element } = this,
            { filterQuery } = this.options,
            radios = {},
            $radios = this.#queryAcross('input[type="radio"]');
        let $elements = this.#queryAcross(':tabbable');
        $radios.forEach(function (el) {
            if (!el.disabled && !radios[el.name]) radios[el.name] = el.checked ? el : false;
        });

        $elements = $elements.filter(function (el) {
            const $el = $(el);
            if ($el.is('input[type="radio"]') && el.name) {
                const checked = radios[el.name];
                if (checked === false) {
                    delete radios[el.name];
                } else if (!checked || !el.checked) {
                    return false;
                }
            }
            if ($el.equal($element) || !$el.visible(true) || $el.parents(':read-write', $element).length) return false;
            if (el.localName === 'iframe') {
                const doc = el.contentDocument;
                if (doc) return $(doc.documentElement).findAll(':tabbable');
                error('Get frame content failed.');
            }
            return true;
        });
        if (filterQuery) $elements = $elements.filter(filterQuery);
        return $elements.toArray();
    }
    #nextTarget(list, current, increment) {
        /// firstSkip: for compat with old usage.
        const { firstSkip } = this.options,
            { $element } = this;

        const count = list.length,
            $current = $(current);
        let index = list.indexOf(current);
        if (index < 0 && !$current.is(':tabbable') && $current.is(':focusable')) {
            // reverse find to get the closest container element.
            const scope = list.findLast((el) => el.contains(current)),
                item = this.#nextScopeTarget(scope, current, increment);
            if (item != null) return item;
        }
        const start = index - count,
            end = index + count;
        index += increment;

        while (index > start && index <= end) {
            const item = list.at(index);
            if (!$element.equal(item)) {
                // eslint-disable-next-line unicorn/no-lonely-if
                if (!$element.equal(current) || !firstSkip || !firstSkip(item)) {
                    return item;
                }
            }
            index += increment;
        }
    }
    #nextScopeTarget(scope, current, increment) {
        if (!scope) return null;
        const list = this.#queryAcross('*', $(scope)).toArray(),
            count = list.length,
            index = list.indexOf(current);
        if (index < 0) return null;
        for (let i = index; i >= 0 && i < count; i += increment) {
            const item = list.at(i);
            if ($.is(item, ':tabbable')) return item;
        }
    }
    #tabLoop(e, increment) {
        const list = this.#getList(),
            next = list.length > 1 ? this.#nextTarget(list, e.target, increment) : list.at(-1);
        focus(next, e);
    }
    enable() {
        this.#enable = true;
    }
    disable() {
        this.#enable = false;
    }
}
