/** @type {typeof $$.date.clearTime} */
export default function clearTime(date) {
    try {
        date = new Date(date);
        const year = date.getFullYear(),
            month = date.getMonth(),
            day = date.getDate();
        return new Date(year, month, day, 0, 0);
    } catch (error) {
        return null;
    }
}
