/**
 * Parse a value into a number. If the value cannot be converted, returns NaN.
 * @param {string | number} value
 */
export function _parse(value) {
    switch (typeof value) {
        case 'number':
            return value;
        case 'string': {
            const trimmed = value.trim();
            return trimmed ? Number(trimmed) : Number.NaN;
        }
    }
    return Number.NaN;
}
