import { onload } from '../../base/onload.js';
import $ from '../../element/index.js';

const topLayerStack = new Set(),
    listeners = new Set();
function stackOP(target, isPush) {
    if (isPush) {
        topLayerStack.add(target);
        listeners.forEach((fn) => fn({ stack: topLayerStack, current: target }));
    } else {
        topLayerStack.delete(target);
    }
}

onload(function () {
    // TopLayers includes: modal dialog, popover, fullscreen element, but excludes tooltip.
    $.$body.on('Toggle', { capture: true }, function (e) {
        const { target } = e,
            { host } = target.getRootNode();
        stackOP(target, target.matches(':modal, :popover-open') && host?.id !== 'tooltip');
    });
    document.addEventListener('fullscreenchange', function (e) {
        const [target] = e.composedPath();
        stackOP(target, !!document.fullscreenElement);
    });
});

/** add or remove listener for top layer element pushes. */
export function addTopLayerListener(isAdd, listener) {
    return isAdd ? listeners.add(listener) : listeners.delete(listener);
}
