/** @type {typeof $$.string.format} */
export default function format(formatter, ...args) {
    let result;
    if (typeof formatter === 'function') {
        result = formatter(...args);
    } else if (formatter === '{0}') {
        return String(args[0] ?? formatter);
    } else {
        result = String(formatter);
        for (let i = 0; i < args.length; i++) {
            if (args[i] != null) {
                const reg = new RegExp('({)' + i + '(})', 'g');
                result = result.replace(reg, () => args[i]);
            }
        }
    }
    return result || '';
}
