/** @jsxImportSource @gui/aui-devops */
import { error } from '../../core/base/log.js';
import { widget } from '../../core/extend/widget.js';

import clearTime from '../../util/date/clear-time.js';
import dateFormat from '../../util/date/format.js';
import { getDateFormat, getTimeFormat } from '../../util/date/formats.js';
import { isDate as typeIsDate, isEmpty as typeIsEmpty } from '../../util/type/types.js';
import { isEqual } from '../../util/value-path.js';

import '../button/button.js';
import '../calendar/calendar.js';
import '../comboboxshell/comboboxshell.js';

const ComboboxShellArgs = { popupWidth: [0], scrollable: false, resetScroll: false };

(function () {
    const noop = $$.fn();
    const _constant = {
        DATE_PICKER: 'aui-rangepicker',
        AUI_WIDGET: 'aui-widget',
        DISABLED: 'disabled',
        POPUP_CLASS: 'aui-rangepicker-popup',
        CONTENT_CLASS: 'aui-comboboxshell-content',
        ICON_FONT_CLASS: 'faui-calendar-solid',
        EXTEND_CLASS: 'aui-rangepicker-extend',
        ACTION_CLASS: 'aui-rangepicker-action',
        ACTION_BORDER_CLASS: 'aui-rangepicker-action-border',
        BUTTON_OK_CLASS: 'aui-rangepicker-ok',
    };

    widget('aui5.rangepicker', {
        calendarId: 'aui_rangepicker_calendar_',
        contentId: 'aui_rangepicker_content_',
        clearId: 'aui_rangepicker_clear_',
        descId: 'aui_rangepicker_desc_',
        tabbtnId: 'aui-rangepicker_tabbutton_',
        $calendar: null,
        hasOK: false,
        showpopup: false,
        optionOrder: ['selectedDate', 'displayDate', 'enableDates'],
        options: {
            // Gets or sets a value that represents the format in which the date will be displayed in the Content area after the date is selected.The Settings are only valid when the control is initialized.
            dateTimeFormat: '',
            // Gets or sets a value indicating whether the user can interact with the control.
            disabled: false,
            titleFormat: null,
            parameters: {},
            formatText: '',
            firstDayOfWeek: 0,
            selectedDate: null,
            enableDates: null,
            width: '100%',
            height: null,
            is24Hour: false,
            clearable: false,
            tooltip: null,
            prefix: '',
            placeholder: null,
            verifyMsg: null,
            // Gets or sets a method that fires when the selected date changes.
            onChange: noop,
            // Gets or sets a method that fires when the calendar area is opened.
            onShow: noop,
            // Gets or sets a method that fires when the calendar area is closed.
            onHide: noop,
        },
        _create: function () {
            this.options.placeholder = this.options.placeholder ?? { start: $$.I18N.rangepicker.ariaStart, end: $$.I18N.rangepicker.ariaEnd };
            this.options.verifyMsg = this.options.verifyMsg ?? { start: $$.I18N.rangepicker.startInvalid, end: $$.I18N.rangepicker.endInvalid };
            this._initMembers()._createShell()._loaded()._initEvent();
        },
        _initMembers: function () {
            this.calendarId += this.uuid;
            this.clearId += this.uuid;
            this.contentId += this.uuid;
            this.tabbtnId += this.uuid;

            this._selectedDate = jQuery.extend(true, {}, this.options.selectedDate);

            this.options = {
                selectDatesTemplate: $$.I18N.datepicker.selectedXDates,
                ...this.options,
            };
            return this;
        },
        _createPopup: function () {
            const className = 'aui-rangepicker-pop-content';
            const _content = (
                <div className={className} aria-label="Calendar" role="dialog">
                    <div id={this.calendarId} />
                    <div className={_constant.EXTEND_CLASS} />
                    <div className="aui-rangepicker-actions" />
                </div>
            );

            return _content;
        },
        _createShell: function () {
            const { placeholder } = this.options;
            this.$extendArea = <div className={_constant.EXTEND_CLASS} />;
            this.comboboxShell = (
                <aui-combobox-shell
                    part="combobox-shell"
                    {...ComboboxShellArgs}
                    {...this.options}
                    placeholder={`${placeholder?.start} - ${placeholder?.end}`}
                    popupWidth={['258px', '380px']}
                    icon={_constant.ICON_FONT_CLASS}
                    onClear={this._onClear.bind(this)}
                    willShow={this._updateButton.bind(this)}
                    onShow={this._showPopup.bind(this)}
                    onHide={this._hidePopup.bind(this)}
                >
                    <div className="aui-rangepicker-range">
                        <section id={this.calendarId} />
                        {this.$extendArea}
                    </div>
                    <span slot="buttons"></span>
                </aui-combobox-shell>
            );
            this.$element
                .addClass(_constant.DATE_PICKER + ' ' + _constant.AUI_WIDGET)
                .attr({
                    'aria-expanded': false,
                    role: 'combobox',
                    'aria-haspopup': 'dialog',
                })
                .append(this.comboboxShell);

            this.$calendar = jQuery('#' + this.calendarId).calendar({
                selectedDate: null,
                enableDates: this.options.enableDates,
                displayDate: null,
                type: 'range',
                titleFormat: this.options.titleFormat,
                hasToday: false,
                swipe: true,
                firstDayOfWeek: this.options.firstDayOfWeek,
                onChange: this._onCalendarChange.bind(this),
                doRangeChange: (args) => {
                    return this._callback('doRangeChange', args);
                },
                onMouseChange: this._onCalendarMouseChange.bind(this),
            });

            return this;
        },
        _loaded: function () {
            this.$content = this.$element.find('.' + _constant.CONTENT_CLASS);
            this.$content.attr({
                id: this.contentId,
                'aria-hidden': true,
            });
            this.$element.attr({ 'aria-describedby': this.contentId, 'aria-roledescription': 'rangepicker' });

            this._setSelectedDate(null, this.options.selectedDate);
            return this;
        },
        _initEvent: function () {
            const ns = this.eventNamespace;

            this.$calendar.on('ViewChange', this._onViewChange.bind(this));
            return this;
        },
        _setOption: function (key, value) {
            const oldValue = this.options[key];
            this.options[key] = value;

            switch (key) {
                case 'disabled':
                    this.comboboxShell.setAttribute('disabled', value);
                    break;
                case 'displayDate':
                    this.$calendar?.calendar('option', 'displayDate', typeIsDate(value) ? new Date(value) : null);
                    break;
                case 'selectedDate':
                    this._selectedDate = value;
                    this._setSelectedDate(oldValue, value);
                    break;
                case 'dateTimeFormat':
                    this._setSelectedDate(null, this.options.selectedDate);
                    break;
                case 'enableDates':
                    this.$calendar.calendar('option', 'enableDates', value);
                    break;
                case 'tooltip':
                    this.comboboxShell.setAttribute('tooltip', value);
                    break;
                default:
                    break;
            }
        },
        _updateButton: function () {
            this.$element.find('span[slot="buttons"]').empty();
            const isMobile = this._isPopMobile();

            this.$ok = (
                <aui-button
                    type={isMobile ? 'link' : 'button'}
                    class={_constant.BUTTON_OK_CLASS}
                    name="ok"
                    primary={!isMobile}
                    text={$$.I18N.datepicker.ok}
                    onClick={this._clickOk.bind(this)}
                />
            );
            this.$element.find('span[slot="buttons"]').append(this.$ok);
        },
        _isPopMobile: function () {
            return $$.mobileView && $$.browser.touchable;
        },
        _onViewChange: function (e, view) {
            this.$extendArea.hidden = view !== 0;
        },
        _onCalendarChange: function (args) {
            this._checkCalendarData(args.newValue);

            this._setContent(args.newValue);
        },
        _onCalendarMouseChange: function (args) {
            this._setContent(args);
        },
        _hidePopup: function () {
            this.$element.attr('aria-expanded', false);
            this.$calendar.calendar('option', 'displayMode', 0);
            this.$calendar.calendar('setDisplayDate', null);
            this.$calendar.calendar('resetView');
            if (this._selectedDate) {
                this._setSelectedDate(null, this._selectedDate);
            }
            this.options.onHide(null, {
                element: this.$element,
            });
        },
        _showPopup: function () {
            this.$element.attr('aria-expanded', true);
            if (!this.showpopup) {
                this.showpopup = true;
                if (!this.options.timeFormat) {
                    this.options.timeFormat = getTimeFormat();
                }
            }
            this._setDate();
            this.comboboxShell.setOption('status', { show: true });
            window.setTimeout(
                function () {
                    this.$calendar.calendar('setFocus');
                }.bind(this)
            );
            this.options.onShow(null, {
                element: this.$element,
            });
        },
        _onClear: function () {
            const oldDate = this.options.selectedDate,
                newDate = null;
            this._setOption('selectedDate', newDate);
            this._onChange(oldDate, newDate, true);
        },
        _setDate: function () {
            let d = this.options.selectedDate;
            d = jQuery.extend(true, {}, d);

            this.$calendar.calendar('option', 'selectedDate', d);
            if (typeIsDate(this.options.displayDate)) {
                this.$calendar.calendar('setDisplayDate', new Date(this.options.displayDate));
            }
            this._checkCalendarData(d);

            return this;
        },
        getValue: function () {
            return this.options.selectedDate;
        },
        _destroy: function () {
            delete this.comboboxShell;
        },
    });
    // Update Data
    Object.assign(jQuery.aui5.rangepicker.prototype, {
        _setSelectedDate: function (old, date) {
            this.options.selectedDate = date;
            date = this._setContent(date, true);
            this.comboboxShell.setAttribute('clearable', !!(this.options.clearable && date?.start && date?.end));
            return this;
        },
        _setContent: function (date, changeContent) {
            const { placeholder } = this.options;
            let value = '';
            this.$element.removeClass('aui-combobox-none');
            if (!date || typeIsEmpty(date)) {
                this.$element.addClass('aui-combobox-none');
            } else {
                date.start = date.start ? new Date(date.start) : null;
                date.end = date.end ? this._calcEndDate(date.end) : null;

                let start = date.start,
                    end = date.end;
                if ((changeContent && start && !end) || (!start && end)) {
                    error('[rangepicker]', 'rangepicker set selectedDate error');
                    return;
                }

                start = this._getContentText(start, changeContent) || placeholder?.start || '';
                end = this._getContentText(end, changeContent) || placeholder?.end || '';
                value = start + ' - ' + end;
            }

            if (this.options.prefix.length > 0) {
                const formatTextValue = this.options.formatText || $$.I18N.combobox.format;
                value = formatTextValue.replace('{1}', value);
                value = value.replace('{0}', this.options.prefix);
            }
            if (!changeContent) {
                this.$element.addClass('aui-combobox-none');
            }
            this.comboboxShell.setOption('content', value);
            this.$element.triggerHandler('onChange');
            return date;
        },
        _calcEndDate: function (date) {
            if (!(date instanceof Date)) return null;
            if (this.options.hasTimePicker) {
                date = new Date(date.getFullYear(), date.getMonth(), date.getDate(), date.getHours(), date.getMinutes() + 1);
                date = new Date(date - 1);
            } else {
                date = clearTime(date);
                date.setDate(date.getDate() + 1);
                date = new Date(date - 1);
            }
            return date;
        },
        _getContentText: function (date, changeContent) {
            const dateTimeFormat = this.options.dateTimeFormat || getDateFormat(),
                // eslint-disable-next-line unicorn/prefer-number-properties
                _isNaN = isNaN(Date.parse(date));

            if (date && !_isNaN) {
                return dateFormat(date, dateTimeFormat.trim());
            } else {
                if (_isNaN && changeContent) {
                    error('Invalid selectedDate, The selectedDate type must be "Date"');
                }
                return '';
            }
        },
        _checkCalendarData: function (date) {
            const disabled = !date || !typeIsDate(date.start) || !typeIsDate(date.end);

            this.$ok.setOption('disabled', disabled);
            return disabled;
        },
        _onChange: function (old, date, force) {
            if (isEqual(old, date)) return false;
            const disabled = !force && this._checkCalendarData(date);
            if (!disabled || (this.options.clearable && typeIsEmpty(date)) || force) {
                this.options.selectedDate = date;
                this._selectedDate = date;

                this.$element[0].dataset.dirty = true;
                this._handler('onChange', {
                    oldValue: old,
                    newValue: date,
                });
            }
        },
    });
    // Logic related to the button region
    Object.assign(jQuery.aui5.rangepicker.prototype, {
        _clickOk: function (e) {
            const oldDate = jQuery.extend(true, {}, this._selectedDate),
                d = this.$calendar.calendar('selectedDate');
            // Even if the date is invalid, the year, month and day section should be updated
            this._selectedDate = d;
            this._setSelectedDate(oldDate, d);
            this._onChange(oldDate, d);
            this.comboboxShell.setOption('status', { show: false });
            return true;
        },
        checkValidation: function () {
            const selectedDate = this.options.selectedDate;

            if (!selectedDate || (!selectedDate.start && !selectedDate.end)) return null;
            if (!selectedDate.start) return new EvalError(this.options.verifyMsg.start);
            if (!selectedDate.end) return new EvalError(this.options.verifyMsg.end);
            return selectedDate;
        },
    });
})();
