/** @jsxImportSource @gui/aui-devops */
import $ from '../../core/element/index.js';
import { define, Widget, Types } from '../widget.js';

import arrayAt from '../../util/array/at.js';
import arraySort from '../../util/array/sort.js';
import { keyName } from '../../util/event/key-name.js';
import extendIfneed from '../../util/object/extend-ifneed.js';
import objectMap from '../../util/object/map.js';

import style from './tabloop.less';

const ArrowMapping = (function () {
    const h = { ArrowUp: null, ArrowDown: null, ArrowLeft: -1, ArrowRight: 1 },
        v = { ArrowUp: -1, ArrowDown: 1, ArrowLeft: null, ArrowRight: null },
        mapping = { h, v, all: extendIfneed({}, h, v) };
    /** @returns {Record<'ArrowUp'|'ArrowDown'|'ArrowLeft'|'ArrowRight', 1|-1|null>} */
    return (mode, reverse) => {
        const data = mapping[mode];
        return reverse ? objectMap(data, (k, v) => (v == null ? null : v * -1)) : data;
    };
})();

/** @extends {Widget<typeof Tabloop.options>} */
@define('tabloop')
export class Tabloop extends Widget {
    static options = {
        eventScope: Types.Selector.value('host'),
        query: Types.Enum(['tabbable', 'focusable'], 'tabbable'),
        disabled: false,
        bubbles: true,
        tabMode: true,
        arrowMode: Types.Enum(['h', 'v', 'all']),
        arrowLoop: true,
        arrowFlipPrevent: false,
        arrowReverse: false,
        filterQuery: Types.Union([Types.string, Types.function]),
        orderAttr: Types.string,
        skipFirst: '',
        doFocus: Types.function,
        willArrow: Types.function,
    };
    static observers = ['filterQuery', 'disabled'];
    static styles = style;

    init() {
        const { eventScope, query, bubbles, tabMode, arrowLoop, arrowFlipPrevent, orderAttr, skipFirst } = this.options,
            state = { query, bubbles, tabMode, arrowLoop, arrowFlipPrevent, orderAttr, skipFirst };
        this.method = { additional: this.additional };
        this.state = {
            eventScope: this.parseElement(eventScope),
            ...state,
            asc: true,
            skipFirstEnabled: false,
            hostParent: null,
            arrowMapping: {},
            $additional: [],
        };
    }
    /** Set additional element(s) to tab loop list. */
    additional = (before, after) => {
        const $before = $(before),
            $after = $(after),
            $current = this.state.$additional;
        $($current).forEach((el) => el.removeEventListener('keydown', this.onKeydown));
        $([$before, $after]).forEach((el) => el.addEventListener('keydown', this.onKeydown));
        this.state.$additional = [$before, $after];
    };

    didMount() {
        const { tabMode, arrowMode, arrowReverse } = this.options;
        if (tabMode || arrowMode) {
            this.state.arrowMapping = ArrowMapping(arrowMode, arrowReverse) || {};
            $(this.state.eventScope).on('keydown', this.onKeydown);
        }
        this.state.hostParent = this.$host.parent({ crossSlot: true }).get();
    }
    setOption() {
        return false;
    }

    onKeydown = (e) => {
        if (this.options.disabled) return;
        const key = keyName(e, true);
        if (key === 'Tab') {
            if (this.state.tabMode) this.onTab(e);
        } else if (key.startsWith('Arrow')) {
            this.onArrow(e, key);
        }
    };
    onTab(e) {
        if (!this.state.bubbles) e.stopPropagation();
        const { target } = e,
            { eventScope, hostParent } = this.state,
            onSelf = target === eventScope || target === hostParent;
        this.state.asc = !e.shiftKey;
        if (onSelf || target.parentNode === this.host.shadowRoot || !this.$host.contains(target, true)) {
            this.setSkip(onSelf);
            this.goFocus(e);
        }
    }
    onArrow(e, key) {
        const increment = this.state.arrowMapping[key];
        if (increment) {
            e.preventDefault();
            if (!this.state.bubbles) e.stopPropagation();
            const $list = this.getList();
            if ($list.length) {
                const prev = e.target,
                    { loopGroup } = prev.dataset,
                    [...list] = loopGroup ? $list.filter(`[data-loop-group="${loopGroup}"]`) : $list.not('[data-loop-group]');
                const index = list.indexOf(prev),
                    target = arrayAt(list, Math.max(index + increment, -1), this.state.arrowLoop);
                if (this.callback('willArrow', key, target, prev) !== false) this.focus(target);
            }
        } else if (increment === null && this.state.arrowFlipPrevent) {
            e.preventDefault();
        }
    }
    queryAcross(query) {
        const $scope = this.$host;
        return $scope.findAll(query, { crossShadow: true, crossSlot: true });
    }
    setSkip(enable) {
        this.state.skipFirstEnabled = (enable && this.state.skipFirst) || false;
    }
    getList(exclude) {
        const { $element } = this,
            { filterQuery } = this.options,
            { query, orderAttr } = this.state,
            [$before, $after] = this.state.$additional,
            ignores = [];
        let $elements = this.queryAcross(`:${query}`);
        $elements = $elements.filter((el) => {
            const $el = $(el);
            if ($el.is('.skip') || $el.parents(':read-write', $element).length) return false;
            if (this.state.skipFirstEnabled && $el.closest(this.state.skipFirst).length) {
                ignores.push(el);
                return false;
            }
            return true;
        });
        this.setSkip(false);
        if (filterQuery) $elements = $elements.filter(filterQuery);
        if (orderAttr) {
            const elements = $elements.toArray(),
                items = new Map(),
                orders = [];
            elements.forEach((el, i) => {
                if (el.hasAttribute(orderAttr)) {
                    items.set(el, i);
                    orders.push(i);
                }
            });
            if (items.size) {
                const [...list] = items.keys();
                arraySort(list, true, null, (el) => el.getAttribute(orderAttr));
                for (const item of list) {
                    const index = orders.shift();
                    elements[index] = item;
                }
                $elements = $(elements);
            }
        }
        /// Consider the order of next two lines.
        if (!$elements.length) $elements = $(ignores);
        $elements = $([$before, $elements, $after]).not(exclude);
        return $elements;
    }
    focus(element) {
        if (!element?.focus) return;
        const { doFocus } = this.options;
        return doFocus ? doFocus(element) : element.focus({ focusVisible: true });
    }
    goFocus(e) {
        e.preventDefault();
        const index = this.state.asc ? 0 : -1,
            $list = this.getList(e.currentTarget),
            $target = $list.eq(index),
            target = $target.get();
        if (!target) {
            this.focus(this.state.eventScope);
        } else if (target.localName === 'iframe') {
            let root;
            try {
                root = target.contentDocument.documentElement;
            } catch (e) {
                this.console.omit('Get frame content failed.');
                return this.focus(target);
            }
            const _target = $(root).find(':tabbable').get() || target;
            this.focus(_target);
        } else {
            this.focus(target);
        }
    }
    onFocus = (e) => {
        const { relatedTarget } = e,
            { eventScope } = this.state;
        if (!relatedTarget || $(eventScope).contains(relatedTarget, true)) {
            this.setSkip(false);
            return this.goFocus(e);
        } else {
            this.setSkip(true);
        }
    };

    render() {
        const { tabMode } = this.state;
        return (
            <>
                {tabMode && <div className="skip" tabIndex={0} onFocusIn={this.onFocus} />}
                <slot part="box" />
                {tabMode && <div className="skip" tabIndex={0} onFocusIn={this.onFocus} />}
            </>
        );
    }
}
