/** @jsxImportSource @gui/aui-devops */
import { addTooltip } from '../../core/module/tooltip.js';
import { define, Widget, Types } from '../../widget/widget.js';

import arrayDelete from '../../util/array/delete.js';

import style from './style.less';

const groupElements = {};

/** @extends {Widget<typeof Togglebutton.options>} */
@define('togglebutton')
export class Togglebutton extends Widget {
    static options = {
        checked: false,
        classify: Types.Enum(['theme', 'alt', 'info', 'warn', 'success', 'error'], 'theme'),
        disabled: false,
        group: Types.string,
        interactive: true,
        tooltip: Types.string,
        value: Types.string,
        onChange: Types.function,
        onClick: Types.function,
    };
    static shadow = { delegatesFocus: true };
    static styles = style;
    static observers = ['checked', 'classify', 'disabled', 'interactive', 'value', 'group'];

    init() {
        this.state = {
            checked: this.options.checked,
        };
    }
    didMount() {
        addTooltip(this.host);
        const { group } = this.options;
        if (group) {
            if (!groupElements[group]) groupElements[group] = [];
            groupElements[group].push(this.host);
        }
    }
    didUnmount() {
        const { group } = this.options;
        if (group && groupElements[group]) {
            arrayDelete(groupElements[group], this.host);
        }
    }
    setOption(name, value, oldValue) {
        switch (name) {
            case 'value':
                return false;
            case 'checked':
                this.setState({ checked: value });
                break;
        }
    }
    onChange = (e) => {
        const { interactive, group, value } = this.options;
        const { checked } = this.state;
        let status = checked;
        if (interactive) {
            if (group && !checked) {
                for (const item of groupElements[group]) {
                    if (item !== this.host) item.setState({ checked: false });
                }
            }
            status = !checked;
            this.setState({ checked: status });
            this.callback('onChange', status, value, group);
        }
        this.callback('onClick', status, value, group);
    };

    render() {
        const { classify, disabled, group, interactive, tooltip, onClick } = this.options,
            { checked } = this.state,
            readonly = !interactive;
        return (
            <label className={[checked && 'checked', 'classify-' + classify, readonly && 'readonly', readonly && onClick && 'clickable']} aria-disabled={disabled}>
                <input
                    type="checkbox"
                    role="button"
                    checked={checked}
                    readOnly={readonly}
                    disabled={disabled}
                    name={group}
                    aria-pressed={checked}
                    aria-label={tooltip}
                    data-tooltip={!!tooltip}
                    onChange={this.onChange}
                />
                <slot />
            </label>
        );
    }
}
