/** @type {typeof $$.array.split} */
export default function split(array, ...indices) {
    const result = [];
    let [...arr] = array,
        last = 0;
    for (const index of indices) {
        result.push(arr.slice(0, index - last));
        arr = arr.slice(index - last);
        last = index;
    }
    result.push(arr);
    return result;
}
