/** @jsxImportSource @gui/aui-devops */
import { addTooltip } from '../../core/module/tooltip.js';
import { define, Widget } from '../widget.js';

import { ButtonWidget, Options } from './button-util.js';

import style from './button.host.less';

/** @extends {Widget<typeof Button.options>} */
@define('button-lite')
export class Button extends ButtonWidget {
    static options = {
        ...Options,
    };
    static shadow = { delegatesFocus: true, referenceTarget: 'button' };
    static styles = style;

    didMount() {
        addTooltip(this.host);
    }
    didRender() {
        const prefix = 'button_expanded',
            { ariaExpanded } = this.element;
        this.customState(`${prefix}_true`, false);
        this.customState(`${prefix}_false`, false);
        if (ariaExpanded != null) this.customState(`${prefix}_${ariaExpanded}`, true);
    }
    render() {
        const { icon, text } = this.options,
            attrs = this.attributes();
        return (
            // eslint-disable-next-line react/button-has-type
            <button id="button" {...attrs} part="button">
                <slot name="icon" className={['button-icon-part', text != null && 'with-content']} aria-hidden="true">
                    {icon && <span className={this.fontIcon(icon)} />}
                </slot>
                <slot name="text" className="button-text-part">
                    {text || null}
                </slot>
                <slot name="icon-end" className="button-icon-part" aria-hidden="true" />
                <slot />
            </button>
        );
    }
}
