import morphdom from 'morphdom';

import { isCustomElement } from '../util/type/types.js';

const IgnoreElements = new Set(['iframe', 'template']);

// from: exists element; to: new element.
const DoMergeDom = function (fromNode, toNode) {
    morphdom(fromNode, toNode, {
        childrenOnly: true,
        onBeforeElUpdated: (fromEl, toEl) => {
            const name = fromEl.localName;
            if (name === 'slot') {
                if (fromEl.classList.contains('assigned')) toEl.classList.add('assigned');
            } else if (name === 'input' || name === 'textarea') {
                fromEl.value = toEl.value;
            } else if (isCustomElement(fromEl) && isCustomElement(toEl)) {
                $$.fn(fromEl.mergeWith, fromEl)(toEl);
            }
            return !fromEl.isEqualNode(toEl);
        },
        onBeforeElChildrenUpdated: (fromEl, toEl) => {
            if (IgnoreElements.has(fromEl.localName)) return false;

            const isCustom = isCustomElement(fromEl) && isCustomElement(toEl);
            if (!isCustom || fromEl.shadowRoot) return true;
            return !fromEl.ownContents || toEl.innerHTML || !fromEl.innerHTML;
        },
    });
};

export default function mergeDom(fromNode, toNode) {
    let asyncList = [];
    // [async] & [[promises]]: match the extends in $$.createElement.
    for (const el of toNode.querySelectorAll('[async]')) {
        if (Array.isArray(el.promises)) {
            el.removeAttribute('async');
            asyncList = asyncList.concat(el.promises);
        }
    }
    if (asyncList.length) {
        // contains shell elements, merge dom after it rendered done.
        return Promise.all(asyncList).then(() => DoMergeDom(fromNode, toNode));
    } else {
        DoMergeDom(fromNode, toNode);
        return true;
    }
}
