import { error } from '../core/base/log.js';

import types from './type/index.js';
import { isObject } from './type/types.js';

/** @type {typeof $$.getValue} */
export function getValue(obj, valuePath, parser) {
    let val = obj;
    if (valuePath != null) {
        if (val && typeof val === 'object') {
            for (const attr of valuePath.split('.')) {
                val = val?.[attr];
            }
        } else {
            error("Cannot get prop's value by valuePath:" + valuePath);
        }
    }
    if (typeof parser === 'function') {
        val = parser(val);
    } else if (parser === true && typeof val === 'object') val = '';
    return val;
}

/** @type {typeof $$.setValue} */
export function setValue(obj, valuePath, value) {
    let val = obj;
    if (valuePath) {
        if (isObject(val)) {
            valuePath.split('.').forEach(function (attr, i, arr) {
                if (i === arr.length - 1) {
                    if (value === undefined) {
                        delete val[attr];
                    } else {
                        val[attr] = value;
                    }
                } else {
                    if (val[attr] === undefined) val[attr] = {};
                    val = val[attr];
                }
            });
        } else {
            error("Cannot set prop's value by valuePath:" + valuePath);
        }
    }
    return obj;
}

/** @type {typeof $$.isEqual} */
export function isEqual(val, other, valuePath) {
    if (val && other && typeof val === 'object') {
        if (valuePath) {
            return getValue(val, valuePath) === getValue(other, valuePath);
        }
        if (types.isShellElement && types.isShellElement(val)) {
            return val.type === other.type && val.key === other.key;
        }
        try {
            return JSON.stringify(val) === JSON.stringify(other);
        } catch (e) {
            error(e);
        }
    }
    return val === other;
}
