/** @type {typeof $$.number.pointFix} */
export default function pointFix(num) {
    let str = String(num).replace(/0{4,20}[0-1]?[1-9]$/, '');
    if (/9{4,20}[1-9]$/.test(str)) {
        str = str.replace(/9{4,20}[1-9]$/, '');
        const list = str.split('');
        let l = list.length - 1;
        if (list[l] === '.') list.pop(l--);
        const acc = list[l] - 0 + 1;
        if (acc < 10) {
            list[l] = acc;
        } else {
            list[l] = acc - 10;
            if (l > 0) {
                list[l - 1] = list[l - 1] - 0 + 1;
            } else {
                list.splice(0, 0, 1);
            }
        }
        str = list.join('');
    }
    return Number.parseFloat(str);
}
