/** @jsxImportSource @gui/aui-devops */
import { define, Widget, Types } from '../../widget/widget.js';

import arrayLoop from '../../util/array/loop.js';
import { classifyColor } from '../../util/css/classify-color.js';
import numberClamp from '../../util/number/clamp.js';
import numberFixFloat from '../../util/number/fix-float.js';
import { percent as numberPercent } from '../../util/number/percent.js';
import numberRound from '../../util/number/round.js';
import stringFormat from '../../util/string/format.js';
import { isEmpty } from '../../util/type/types.js';

import config from './config.json';

import style from './style.less';

const I18N = $$.I18N.progressbar;
const Templates = new Set(['percent', 'numeric']);
const MaxSection = config['max-section']; // It should equal to the max-section in style.less.

/** @extends {Widget<typeof ProgressBar.options>} */
@define('progressbar')
export class ProgressBar extends Widget {
    static options = {
        value: Types.number,
        max: 100,
        type: Types.Enum(['line', 'circle', 'semicircle'], 'line'),
        section: Types.number,
        sectionMode: Types.Enum(['nearest', 'up', 'down', 'exact'], 'down'),
        sectionColor: Types.Union([Types.PlainArray, Types.PlainObject]),
        classify: Types.Classify(true, 'extends', 'theme'),
        template: Types.Union([Types.boolean, Types.string]),
        animated: true,
        weight: Types.Enum(['xs', 's', 'm', 'l'], 'm'),
    };
    static styles = style;
    static observers = ['classify', 'value', 'max'];
    static upcasts = ['type', 'weight'];

    init() {
        const { max, type, section, sectionMode, sectionColor, template, animated } = this.options;
        this.state = {
            animate: animated && $$.browser.env.animate,
            section: type === 'line' && Number.isSafeInteger(section) && section > 1 && section <= MaxSection ? section : 0,
            sectionMode,
            sectionColor: null,
            template: (Templates.has(template) ? I18N[template] : template === true && I18N[max === 100 ? 'percent' : 'numeric']) || null,
        };
        if (this.state.section) {
            this.state.animate = false;
            if (!isEmpty(sectionColor)) this.state.sectionColor = sectionColor;
        } else if (section != null) {
            this.console.error('Invalid section value or out of valid range.');
        }
    }
    parseSection(section, value, step) {
        const { sectionMode, sectionColor } = this.state;
        if (sectionMode !== 'exact') value = numberRound(value, step, sectionMode);

        const size = numberPercent(1 / section),
            count = value / step,
            countCeil = Math.ceil(count),
            countColor = sectionColor?.[`count:${countCeil}`];
        const list = arrayLoop(section, (i, o) => {
            const start = step * i,
                end = step * o,
                color = classifyColor((o === countCeil && sectionColor?.active) || countColor || sectionColor?.[i], true, 'color'),
                rate = value >= end ? '100%' : value < start ? '0%' : numberPercent(count - i);
            return <div style={{ color, '--rate': rate }} />;
        });
        return (
            <div className="sections" style={{ '--size': size }}>
                {list}
            </div>
        );
    }
    args() {
        let { value, max } = this.options;
        const data = {},
            style = {};
        max = Math.max(0, max);
        value = numberClamp(0, value, max);

        const fix = (v) => numberFixFloat(v, 4),
            rate = fix(value / max),
            args = { value: fix(value), max: fix(max), data, style: { '--rate': rate, ...style } };
        data.status = args.value === 0 ? 'empty' : args.value === args.max ? 'full' : undefined;
        return args;
    }
    render() {
        const { value, classify } = this.options,
            { section, template, animate } = this.state,
            determinate = value != null,
            useSection = determinate && section > 0,
            { data, style, ...args } = determinate ? this.args() : { 'aria-busy': true };
        return (
            <div className="box" classify={classify}>
                <div className="track" data={data} style={style}>
                    <progress className={[animate && 'animate']} {...this.arias()} {...args} />
                    {useSection && this.parseSection(section, value, args.max / section)}
                </div>
                {determinate && template && <slot className="text">{stringFormat(template, args.value, args.max)}</slot>}
            </div>
        );
    }
}
