import { error } from '../../core/base/log.js';

/** @type {Record<string, string>} */
const Mapping = {
    'octet-stream': 'bin',
    msword: 'doc',
    'application/vnd.ms-word.template.macroEnabled.12': 'docm',
    'vnd.openxmlformats-officedocument.wordprocessingml.document': 'docx',
    'vnd.ms-fontobject': 'eot',
    'x-msdownload': 'exe',
    gzip: 'gz',
    'x-icon': 'ico',
    jpeg: 'jpg',
    pjpeg: 'jpg',
    javascript: 'js',
    markdown: 'md',
    mpeg: 'mp3',
    'application/pdf': 'pdf',
    'vnd.ms-powerpoint': 'ppt',
    'application/vnd.ms-powerpoint.presentation.macroEnabled.12': 'pptm',
    'vnd.openxmlformats-officedocument.presentationml.presentation': 'pptx',
    'vnd.rar': 'rar',
    'svg+xml': 'svg',
    'x-tar': 'tar',
    plain: 'txt',
    'x-woff': 'woff',
    'font-woff2': 'woff2',
    'vnd.ms-excel': 'xls',
    'vnd.ms-excel.sheet.macroEnabled.12': 'xlsm',
    'vnd.openxmlformats-officedocument.spreadsheetml.sheet': 'xlsx',
    'x-zip-compressed': 'zip',
    'x-7z-compressed': '7z',
};

/** @type {typeof $$.io.mime2ext} */
export default function mime2ext(mime, defaults = 'txt') {
    if (mime && typeof mime === 'string') {
        const ext = mime.split('/').at(-1);
        if (ext && /^[a-z0-9+.-]+$/.test(ext)) {
            const mapped = Mapping[ext] || Mapping['x-' + ext]; // some mime includes 'x-' prefix and some not.
            if (mapped) return mapped; // mapping ext
            const match = ext.match(/\w{3,}/); // mime extension is at least 3 chars
            if (match) return match[0];
        } else {
            error('Invalid MIME type');
        }
    }
    return defaults || 'txt';
}
