import $ from '../../core/element/index.js';

import { keyName } from './key-name.js';
import stop from './stop.js';

const arrowOffset = {
    ArrowUp: [-1, 0],
    ArrowDown: [1, 0],
    ArrowLeft: [0, -1],
    ArrowRight: [0, 1],
};
function getVisibleNextElement(next, offset) {
    while (next && !next.checkVisibility({ visibilityProperty: true, opacityProperty: true })) {
        next = next[offset[1] > 0 ? 'nextElementSibling' : 'previousElementSibling'];
    }
    return next;
}
function getNextElement(domList, target, offset) {
    let next;
    const found = domList.find((row) => row.includes(target));

    if (found) {
        const rowIndex = domList.indexOf(found),
            columnIndex = found.indexOf(target);

        if (rowIndex !== -1 && columnIndex !== -1) {
            let row = Number(offset[0]) + Number(rowIndex),
                col = Number(offset[1]) + Number(columnIndex);
            row = row > -1 ? Math.min(row, domList.length - 1) : 0;
            col = col > -1 ? Math.min(col, domList[row].length - 1) : 0;
            next = domList[row][col];
        }
    }
    return next;
}

/** @type {typeof $$.event.navigation} */
export function navigation(e, scrollBox) {
    const name = keyName(e);
    if (!name.startsWith('Arrow')) return null;
    stop(e);
    let $target = $(e),
        next;
    const target = $target.get(0);
    if (scrollBox == null) {
        scrollBox = $target.parent().get();
    } else {
        while (!$target.parent().equal(scrollBox)) {
            $target = $target.parent();
        }
    }
    const { children } = scrollBox,
        offset = arrowOffset[name];

    if (offset[0] === 0) {
        const index = Array.from(children).indexOf(target);
        next = children[index + offset[1]];
    } else {
        const domListMap = Array.from(children)
            .map((d) => ({ element: d, top: d.offsetTop }))
            .reduce((acc, item) => {
                if (!acc[item.top]) acc[item.top] = [];
                acc[item.top].push(item.element);
                return acc;
            }, {});
        const domList = Object.values(domListMap);
        next = getNextElement(domList, target, offset);
    }
    next = getVisibleNextElement(next, offset);

    if (next && next.ariaDisabled !== 'true') {
        next.focus({ focusVisible: true });
        return next;
    }
    return null;
}

/** @type {typeof $$.event.navigation2D} */
export function navigation2D(e, attrSelector = 'data-cell', scrollBox = null) {
    const name = keyName(e),
        selector = `[${attrSelector}]`,
        offset = arrowOffset[name],
        target = e.target.closest(selector);
    if (!offset || !target) return null;
    if (scrollBox == null) {
        // eslint-disable-next-line unicorn/better-dom-traversing
        scrollBox = target.parentElement.parentElement;
    }

    const domList = {},
        nodeList = scrollBox.querySelectorAll(selector);
    for (const node of nodeList) {
        const data = node.getAttribute(attrSelector)?.split(',');
        const row = data[0],
            cell = data[1];
        if (!domList[row]) {
            domList[row] = {};
        }
        domList[row][cell] = node;
    }

    const coord = target.getAttribute(attrSelector)?.split(','),
        row = Number(offset[0]) + Number(coord[0]),
        col = Number(offset[1]) + Number(coord[1]);
    let next = domList[row] ? domList[row][col] : null;
    if (domList[row] && !next) {
        const rowsArray = Object.values(domList).map((d) => Object.values(d));
        const colCount = Math.max(...rowsArray.map((d) => d.length)),
            dir = offset[1] > 0 ? 1 : -1;
        for (let i = col; i > 0 && i <= colCount; i += dir) {
            next = domList[row][i];
            if (next) break;
        }
    }
    next = getVisibleNextElement(next, offset);
    if (next && next.ariaDisabled !== 'true') {
        next.focus({ focusVisible: true });
        return next;
    }
    return null;
}
