/** @jsxImportSource @gui/aui-devops */
import { warn, error } from '../../core/base/log.js';
import { onloading } from '../../core/base/onload.js';
import $ from '../../core/element/index.js';
import mergeDom from '../../widget/merge-dom.js';

import objectExtendScope from '../../util/object/extend-scope.js';

import '../dialog/modal.js';
import '../button/button.js';

const ID = 'aui-message-dialog';
const DefaultOptions = {
    title: '',
    content: '',
    classify: '',
    width: null,
    height: null,
    buttons: [],
    willClose: null,
    onClose: null,
};
const Icon = {
    question: 'faui-question-solid icon-blue',
    info: 'faui-comment icon-info',
    warn: 'faui-warning-solid icon-warn',
    error: 'faui-error-solid icon-error',
    success: 'faui-finish-solid icon-success',
};

const I18N = $$.I18N.messagedialog,
    ClassifyI18N = $$.I18N.core.classify;

function DefaultButtons(type) {
    switch (type) {
        case 'alert':
            return [{ text: I18N.ok, name: 'ok', primary: true }];
        case 'confirm':
            return [
                { text: I18N.cancel, name: 'cancel' },
                { text: I18N.ok, name: 'ok', primary: true },
            ];
        case 'message':
            return undefined;
        default:
            return undefined;
    }
}

class MessageDialog {
    #modal = null;
    #options = {};
    #promise = null;
    #update = (options = DefaultOptions, type = null) => {
        const { $body } = $,
            { width, height } = options;
        let current = $body.children('#' + ID).get();
        const dom = this.render(options, type);
        if (current) {
            mergeDom(current, dom);
        } else {
            dom.setState({ role: 'alertdialog' });
            dom.setOptions({ closeable: false, onHide: this.#update, willClose: this.#willModalClose, onClose: this.#onModalClose });
            $body.append(dom);
            current = dom;
        }
        this.#modal = current;
        if (type) current.setOptions({ width, height });
    };
    #willModalClose = (e) => {
        const { willClose } = this.#options;
        return $$.fn(willClose)(false);
    };
    #onModalClose = (e) => {
        const { onClose } = this.#options;
        $$.fn(onClose)(false);
        this.#promise.resolve(false);
    };
    show(type, args) {
        const options = args ? objectExtendScope({ ...DefaultOptions }, args) : DefaultOptions;
        if (!options.buttons) options.buttons = DefaultOptions.buttons;
        this.#options = options;
        this.#update(options, type);
        this.#modal.show();
        this.#promise = Promise.withResolvers();
        return this.#promise.promise;
    }
    hide() {
        this.#modal.hide();
    }
    onClick(value, [onClick, willClose, onClose], e) {
        if ($$.fn(willClose)(value) !== false && $$.fn(onClick)(e) !== false) {
            this.hide();
            $$.fn(onClose)(value);
            this.#promise.resolve(value);
        }
    }
    #button({ onClick, ...args }, limit, callback) {
        const button = <aui-button slot="buttons" />;
        let value = args.name;
        if (limit) value = value === 'ok';
        button.setOptions(args);
        button.setOptions({ onClick: this.onClick.bind(this, value, [onClick, ...callback]) });
        return button;
    }
    #buttons(buttons, type, callback) {
        const defaults = DefaultButtons(type) || [],
            limit = defaults.length || undefined;
        buttons = Array.from(buttons).concat(defaults).slice(0, limit);
        if (limit && buttons.length !== limit) error('Buttons count not match.');
        return buttons.map((button) => this.#button(button, limit, callback));
    }
    render(options, type) {
        const { title, content, classify, buttons, willClose, onClose } = options,
            icon = Icon[classify],
            // use default title for known classify.
            _title = !title && icon ? ClassifyI18N[classify] : title;
        return (
            <aui-modal id={ID} useWillToggle={false}>
                <h3 slot="header">
                    {icon && <span className={[type && icon, 'font-regular', 'padding-inline-end-xs']} />}
                    {type && (_title || I18N[type])}
                </h3>
                <div>{type && content}</div>
                {type && this.#buttons(buttons, type, [willClose, onClose])}
            </aui-modal>
        );
    }
}

let Dialog;
onloading(function () {
    Dialog = new MessageDialog();
});
function util(type) {
    return function (isShow, args) {
        if (isShow) {
            if (!args) {
                args = typeof isShow === 'object' ? isShow : {};
            } else if (typeof args === 'string') {
                args = { content: args };
            }
            if (type === 'message') warn('The messagedialog is only for special cases, use alert/confirm or Dialog instead in most cases.');
            return Dialog.show(type, args);
        } else {
            Dialog.hide();
        }
    };
}

export const alert = util('alert');
export const confirm = util('confirm');
export const messagedialog = util('message');

Object.assign($$, { alert, confirm, messagedialog });
