import { widget } from '../../extend/widget.js';

import { Tabloop } from './tabloop.js';

(function () {
    widget('aui5.tabloop', {
        // additional elements to loop list.
        additional: [],
        options: {
            instance: null,
            enable: false,
            filterQuery: null,
        },
        _create: function () {
            const { filterQuery, enable } = this.options;
            this.tabloop = new Tabloop(this.element, { filterQuery, firstSkip: this._firstSkip });
            if (enable) this.tabloop.enable();
        },
        focus: function () {
            let { instance } = this.options;
            if (typeof instance === 'function') instance = instance();
            if (typeof instance?.focus === 'function') {
                instance.focus();
            } else {
                this.element.focus();
            }
        },
        _firstSkip: function (element) {
            return element.getAttribute('name') === 'tabskip-close';
        },
        _onKeydown: function (e) {
            this.tabloop.onAction(e);
        },
        show: function (additional = []) {
            this.tabloop.enable();
            this.additional = this.additional.concat(additional);
            if (additional) {
                const $el = jQuery(additional);
                this._on($el, 'keydown', this._onKeydown);
                this._on($el, 'blur', function (e) {
                    if (!this.element.contains(e.relatedTarget)) this._off($el, 'keydown', this._onKeydown);
                });
            }
        },
        hide: function () {
            this.tabloop.disable();
            this.additional = [];
        },
    });
})();
