/** @jsxImportSource @gui/aui-devops */
import { error } from '../../core/base/log.js';
import { idleLoad } from '../../core/base/onload.js';
import $ from '../../core/element/index.js';
import { define, Widget, Types } from '../../widget/widget.js';

import stopEvent from '../../util/event/stop.js';
import touchZoom from '../../util/event/touch-zoom.js';
import blobFile from '../../util/io/blob-file.js';
import clamp from '../../util/number/clamp.js';
import numberFixFloat from '../../util/number/fix-float.js';

import { loading } from '../loading/loading.js';
import { alert } from '../messagedialog/messagedialog.js';
import '../slider/slider.js';

import style from './style.less';

const I18N = $$.I18N.imgCrop;
const LoadingDelay = 100,
    LoadingOptions = { persistent: 'ImgCrop' };
const noop = $$.fn();
const ErrorReport = (entry, log, ...args) => {
    error('[ImgCrop]', log || entry || ' ', ...args);
    return entry ? alert(true, { classify: 'error', content: entry }) : null;
};

const SourceParser = {
    /** @param {HTMLInputElement} element */
    input: (element, resolvers) => {
        const { promise, resolve, reject } = resolvers || Promise.withResolvers();
        if (element.type !== 'file') return reject(ErrorReport(null, 'Element source invalid')) || promise;
        const [file] = element.files;
        if (!file) return reject(ErrorReport(null, 'File not provided')) || promise;
        if (!String(file.type).startsWith('image/')) return reject(ErrorReport(I18N.fileTypeUnsupport)) || promise;

        loading(true, { delay: LoadingDelay });
        const img = new Image(),
            blobUrl = URL.createObjectURL(file);
        img.onerror = () => {
            loading(false);
            reject(ErrorReport(I18N.fileLoadFailed));
        };
        img.onload = () => {
            loading(false);
            resolve([blobUrl, file.type, img.naturalWidth, img.naturalHeight]);
        };
        img.src = blobUrl;
        return promise;
    },
    /** @param {HTMLCanvasElement} element */
    canvas: (element, resolvers) => {
        const { promise, resolve, reject } = resolvers || Promise.withResolvers();
        loading(true, { delay: LoadingDelay });
        try {
            /** Using default mime type [image/png|https://html.spec.whatwg.org/multipage/canvas.html#dom-canvas-toblob-dev] */
            element.toBlob((blob) => {
                if (!blob) return reject(ErrorReport(I18N.fileContentInvalid)) || promise;
                loading(false);
                const url = URL.createObjectURL(blob);
                resolve([url, blob.type, element.width, element.height]);
            });
        } catch (e) {
            loading(false);
            reject(ErrorReport(I18N.fileLoadFailed, null, e.message));
        }
        return promise;
    },
    /** @param {HTMLImageElement} element */
    img: (element, resolvers) => {
        const { promise, resolve, reject } = resolvers || Promise.withResolvers();
        if (!element.src) return reject(ErrorReport(null, 'Image has no source')) || promise;
        function loadSource() {
            const { img, width, height } = CheckImgPixels(element);
            if (!img) return reject();
            const canvas = document.createElement('canvas'),
                ctx = canvas.getContext('2d');
            Object.assign(canvas, { width, height });
            ctx.drawImage(element, 0, 0, width, height);
            return SourceParser.canvas(canvas, { promise, resolve, reject });
        }
        if (element.complete) {
            loadSource();
        } else {
            const timeout = 2000;
            element.addEventListener('load', loadSource);
            setTimeout(() => {
                element.removeEventListener('load', loadSource);
                if (!element.complete) reject(ErrorReport(I18N.fileLoadFailed, 'Image loading timed out'));
            }, timeout);
        }
        return promise;
    },
};

/**
 * - For valid data, image pixels must > 1 (0px image is invalid).
 * - For better performance, scale down image pixels if value > max resolution.
 */
function CheckImgPixels(img) {
    const maxWidth = 1920,
        maxHeight = 1080,
        maxPixels = maxWidth * maxHeight;
    const { naturalWidth, naturalHeight } = img,
        pixels = naturalWidth * naturalHeight;
    if (pixels <= 1) return ErrorReport(I18N.fileContentInvalid, pixels ? 'Image has no pixels' : 'Invalid image data.') || {};

    let width = naturalWidth,
        height = naturalHeight;
    if (pixels > maxPixels) {
        const scale = Math.max(naturalWidth / maxWidth, naturalHeight / maxHeight);
        width = numberFixFloat(naturalWidth / scale);
        height = numberFixFloat(naturalHeight / scale);
    }
    return { img, width, height };
}

function Translate(x, y) {
    return `${numberFixFloat(x, 4)}px ${numberFixFloat(y, 4)}px`;
}

const MimeList = ['image/png', 'image/jpeg', 'image/webp'],
    MimeDefault = 'image/png';
const ZoomFactor = 2,
    ZoomValue = 100, // 100 based = percent values.
    ZoomStep = ZoomValue / ZoomFactor;
const DefaultState = {
    status: { show: false },
    data: null,
    src: null,
    mime: MimeDefault,
    naturalWidth: null,
    naturalHeight: null,
    zoomFactor: null,
    imgWidth: null,
    imgHeight: null,
    offsetX: 0,
    offsetY: 0,
    useDrag: false,
    useZoom: false,
};

/** @extends {Widget<typeof ImgCrop.options>} */
@define('img-crop')
export class ImgCrop extends Widget {
    static options = {
        shape: Types.Enum(['circle', 'square', 'rect'], 'circle'),
        width: Types.number.value(240),
        height: Types.number,
        sourceBy: Types.Union([Types.Selector, Types.Element]),
        mime: Types.Enum([true, ...MimeList], true),
        dataType: Types.Enum(['blob', 'file', 'base64'], 'blob'),
        header: Types.string,
        onChange: Types.function,
    };
    static observers = ['width', 'height'];
    static downstreamContext = ['inherit', ['uploader-picker'], ['skipVerify']];
    static styles = style;

    instanceOptions = () => ({ skipVerify: ['overwrite', 'sameName'] });
    #dragState = {};
    #defaultState() {
        const { shape, width, height } = this.options;
        return {
            ...DefaultState,
            width,
            height: (shape === 'rect' && height) || width,
        };
    }
    #zoomState(useZoom, zoomFactor) {
        if (!useZoom) return { zoomValue: null, zoomStep: null, zoomMin: null, zoomMax: null };
        return {
            zoomValue: ZoomValue,
            zoomStep: ZoomStep,
            zoomMin: ZoomValue,
            zoomMax: Math.ceil(zoomFactor * ZoomFactor) * (100 / ZoomFactor),
        };
    }
    init() {
        this.state = { ...this.#defaultState(), ...this.#zoomState() };
    }
    setOption() {
        return false;
    }
    didMount() {
        const $slot = $(this.shadowRoot).child('slot');
        if (this.options.sourceBy) {
            $slot.on('click', this.handleOuterSource);
        } else {
            $slot.on('input', 'input[type="file"]', this.handleFileSource);
        }

        const img = this.element.querySelector('#img');
        if ($$.browser.touchable) {
            this.useTouchZoom();
        } else {
            img.addEventListener('wheel', this.onWheelZoom);
        }
    }
    /** @param {Event} e Bubbles `change` event by `input[type="file"]` */
    handleFileSource = (e) => {
        const input = e.target;
        this.#parseSource(input, 'input');
    };
    /** @param {PointerEvent} e Bubbles `click` event by `button` or other elements */
    handleOuterSource = (e) => {
        const element = this.parseElement(this.options.sourceBy);
        this.#parseSource(element?.nodeType === Node.ELEMENT_NODE && element);
    };
    #mimeByType(type) {
        const { mime } = this.options;
        if (mime !== true) return mime;

        if (type?.includes('jpg')) return 'image/jpeg';
        if (MimeList.includes(type)) return type;
        return MimeDefault;
    }
    #parseSource(element, type) {
        if (!element) return ErrorReport(null, 'Element not provided');
        const sourceGetter = SourceParser[type || element.localName];
        if (!sourceGetter) return ErrorReport(null, 'Element type invalid');

        const onLoad = ([source, type, naturalWidth, naturalHeight]) => {
            if (!source) return ErrorReport(null, I18N.fileContentInvalid);
            if (typeof source === 'string') {
                this.setState({ mime: this.#mimeByType(type) }, false);
                this.setSource(source, naturalWidth, naturalHeight);
            }
        };
        // no need to handle catch, errors already output with ErrorReport.
        sourceGetter(element).then(onLoad, noop);
    }

    setSource(blobURL, naturalWidth, naturalHeight) {
        const { width, height } = this.#defaultState(),
            naturalRatio = naturalWidth / naturalHeight,
            boxRatio = width / height,
            ratioW = naturalWidth / width,
            ratioH = naturalHeight / height,
            useZoom = ratioW > 1 && ratioH > 1,
            zoomFactor = naturalRatio > boxRatio ? ratioH : ratioW,
            imgWidth = naturalWidth / zoomFactor,
            imgHeight = naturalHeight / zoomFactor,
            diffW = imgWidth - width,
            diffH = imgHeight - height,
            useDrag = diffW > 0 || diffH > 0,
            offsetX = diffW > 0 ? diffW / -2 : 0,
            offsetY = diffH > 0 ? diffH / -2 : 0;
        // Adjust the image size to match the container: set height value for fitVertical(naturalRatio > boxRatio) image, otherwise set width value.
        // And translate the img to center it in x and y axis.
        const states = { naturalWidth, naturalHeight, zoomFactor, imgWidth, imgHeight, offsetX, offsetY, useZoom, ...this.#zoomState(useZoom, zoomFactor) };
        this.setState({ src: blobURL, useDrag, ...states }, false);
        this.doShow();
    }

    useTouchZoom() {
        const scaleData = (v) => {
            const stepFactor = 2;
            if (!v || v === 1) return [0, true];
            if (v > 1) return [Math.round(stepFactor * v), true];
            if (v < 1) return [Math.round(stepFactor / v), false];
        };
        const reset = () => (touchData.scale = 0);
        const touchData = touchZoom(
            this.element,
            reset,
            (e, scale) => {
                const [scaleValue, isZoomIn] = scaleData(scale);
                if (scaleValue) {
                    const [prevScale] = scaleData(touchData.scale);
                    if (scaleValue !== prevScale) {
                        touchData.scale = scale;
                        return isZoomIn ? this.onZoomIn(e, scaleValue) : this.onZoomOut(e, scaleValue);
                    }
                }
            },
            reset
        );
    }
    onWheelZoom = (e) => {
        if (!this.state.useZoom) return null;
        e.preventDefault();
        const stepFactor = 2;
        return e.deltaY > 0 ? this.onZoomOut(e, stepFactor) : this.onZoomIn(e, stepFactor);
    };
    #doZoom(value) {
        if (value === this.state.zoomValue) return;
        const { width, height, zoomFactor, naturalWidth, naturalHeight, imgWidth, imgHeight, offsetX, offsetY } = this.state,
            cx = width / 2,
            cy = height / 2;
        const doClamp = (v) => {
            const baseSize = v / zoomFactor;
            return clamp(baseSize, (baseSize * value) / 100, v);
        };
        const newWidth = doClamp(naturalWidth),
            newHeight = doClamp(naturalHeight),
            scaleX = newWidth / imgWidth,
            scaleY = newHeight / imgHeight,
            offsetDx = cx - (cx - offsetX) * scaleX,
            offsetDy = cy - (cy - offsetY) * scaleY,
            // min offset to left/top (0,0); max offset to right/bottom (boxW-imgW,boxH-imgH);
            offsetNewX = clamp(width - newWidth, offsetDx, 0),
            offsetNewY = clamp(height - newHeight, offsetDy, 0);
        this.setState({ zoomValue: value, imgWidth: newWidth, imgHeight: newHeight, offsetX: offsetNewX, offsetY: offsetNewY });
    }
    onZoomIn = (e, stepFactor = 1) => {
        const { zoomValue, zoomMax, zoomStep } = this.state;
        this.#doZoom(Math.min(zoomMax, zoomValue + zoomStep * stepFactor));
    };
    onZoomOut = (e, stepFactor = 1) => {
        const { zoomValue, zoomMin, zoomStep } = this.state;
        this.#doZoom(Math.max(zoomMin, zoomValue - zoomStep * stepFactor));
    };
    onZoom = (value) => {
        this.#doZoom(value);
    };

    #dragMove(e, syncState) {
        const img = e.currentTarget,
            { width, height, offsetX, offsetY } = this.state,
            { clientX, clientY } = this.#dragState,
            dx = e.clientX - clientX,
            dy = e.clientY - clientY,
            x = clamp(width - img.width, offsetX + dx, 0),
            y = clamp(height - img.height, offsetY + dy, 0);
        img.style.translate = `${x}px ${y}px`;
        if (syncState) this.setState({ offsetX: x, offsetY: y }, false);
        return img;
    }
    /** @param {PointerEvent} e */
    onDragStart = (e) => {
        if (this.#dragState.isDragging || e.button !== 0 || !e.target.draggable) return;
        e.preventDefault();
        const { currentTarget: img, pointerId, clientX, clientY } = e;
        Object.assign(this.#dragState, { isDragging: true, pointerId, clientX, clientY });
        img.setPointerCapture(pointerId);
    };
    /** @param {PointerEvent} e */
    onDragging = (e) => {
        if (!this.#dragState.isDragging || e.pointerId !== this.#dragState.pointerId) return;
        this.#dragMove(e);
    };
    /** @param {PointerEvent} e */
    onDragEnd = (e) => {
        e.stopPropagation();
        if (!this.#dragState.isDragging || e.pointerId !== this.#dragState.pointerId) return;
        const img = this.#dragMove(e, true);
        img.releasePointerCapture(e.pointerId);
        this.#dragState = {};
    };
    /** @param {PointerEvent} e */
    onDragCancel = (e) => {
        if (e.pointerId === this.#dragState.pointerId) {
            const img = e.currentTarget;
            img.releasePointerCapture(e.pointerId);
            this.#dragState = {};
        }
    };

    doShow = () => {
        this.setState({ status: { show: true } });
    };
    doHide = () => {
        this.setState({ status: DefaultState.status });
    };
    onHide = () => {
        idleLoad(() => {
            URL.revokeObjectURL(this.state.src);
            this.setState(DefaultState);
        });
    };
    #cropCanvas({ ctx, width }) {
        const { shape } = this.options;
        // Only circle need to clip, rect is canvas default shape (square is a kind of rectangle).
        if (shape === 'circle') {
            const r = width / 2;
            ctx.beginPath();
            ctx.arc(r, r, r, 0, Math.PI * 2);
            ctx.closePath();
            ctx.clip();
        }
    }
    #canvasToData({ canvas, mime }, cb) {
        const { dataType } = this.options;
        if (dataType === 'base64') {
            idleLoad(() => {
                const result = canvas.toDataURL(mime);
                cb(result);
            });
        } else {
            canvas.toBlob((blob) => {
                const result = dataType === 'file' ? blobFile(blob) : blob;
                cb(result);
            }, mime);
        }
    }
    onSave = () => {
        const { width, height, mime, naturalWidth, naturalHeight, imgWidth, imgHeight, offsetX, offsetY } = this.state,
            canvas = document.createElement('canvas'),
            ctx = canvas.getContext('2d');
        Object.assign(canvas, { width, height });
        this.element.method('loading', true);

        this.#cropCanvas({ canvas, ctx, width, height });
        const img = this.element.querySelector('#img'),
            scaleX = naturalWidth / imgWidth,
            scaleY = naturalHeight / imgHeight;
        ctx.drawImage(img, -offsetX * scaleX, -offsetY * scaleY, width * scaleX, height * scaleY, 0, 0, width, height);

        this.#canvasToData({ canvas, mime }, (data) => {
            this.element.method('loading', false);
            $$.fn(this.options.onChange)(data);
            this.doHide();
        });
    };
    render() {
        const { shape, header } = this.options,
            { status, width, height, src, imgWidth, imgHeight, offsetX, offsetY, useDrag, useZoom, zoomValue, zoomMin, zoomMax, zoomStep } = this.state;
        return (
            <>
                <aui-modal status={status} loadingOptions={LoadingOptions} onHide={this.onHide} onPointerUp={this.onDragCancel}>
                    <h3 slot="header">{header || I18N.header}</h3>
                    <div className="main">
                        <slot name="start" />
                        <section style={{ width, height }}>
                            <div className="box">
                                <img
                                    id="img"
                                    alt=""
                                    width={imgWidth}
                                    height={imgHeight}
                                    src={src}
                                    hidden={!src}
                                    draggable={useDrag}
                                    data-zoom={useZoom}
                                    style={{ translate: Translate(offsetX, offsetY) }}
                                    onPointerDown={this.onDragStart}
                                    onPointerMove={this.onDragging}
                                    onPointerUp={this.onDragEnd}
                                    onContextMenu={$$.mobileView ? stopEvent : null}
                                />
                            </div>
                            <aui-avatar id="placeholder" name="" size="stretch" shape={shape} hidden={!!src} />
                            <div className="hollow" />
                        </section>
                        {useZoom && (
                            <div className="zoom">
                                <aui-button-lite id="zoom-out" type="bald" icon="faui-min" tooltip={I18N.zoomOut} disabled={zoomValue === zoomMin} onClick={this.onZoomOut} />
                                <aui-slider id="zoom-slider" format="{0}%" aria={I18N.zoom} min={zoomMin} max={zoomMax} step={zoomStep} value={zoomValue} onChange={this.onZoom} />
                                <aui-button-lite id="zoom-in" type="bald" icon="faui-plus" tooltip={I18N.zoomIn} disabled={zoomValue === zoomMax} onClick={this.onZoomIn} />
                            </div>
                        )}
                        <slot name="end" />
                    </div>
                    <aui-button-lite slot="buttons" id="cancel" text={I18N.cancel} onClick={this.doHide} />
                    <aui-button-lite slot="buttons" id="ok" primary classify="theme" text={I18N.ok} disabled={!src} onClick={this.onSave} />
                </aui-modal>
                <slot />
            </>
        );
    }
}
