import React, { cloneElement } from 'react';

import split from '../../util/array/split.js';

const maxCount = 5;

export function Group(props) {
    const { children, ...args } = props,
        [items, rests] = split($$.shell.flatArray(children), maxCount);
    return (
        <aui-avatar-group {...args} max={maxCount}>
            {items.map((item, i) => cloneElement(item, { slot: i }))}
            {rests}
        </aui-avatar-group>
    );
}
