export default String.raw`:host {
  --position: fixed;
  z-index: unset
}
dialog {
  flex-direction: column;
  color: inherit;
  background: var(--section-bg);
  width: fit-content;
  height: fit-content;
  max-width: calc(100dvw - (var(--inset-inline) * 2));
  max-height: calc(100dvh - (var(--inset-block) * 2));
  padding: 0;
  border: 0;
  position: var(--position);
  z-index: inherit;
  --inset-block: var(--gap-xl);
  --inset-inline: var(--gap-xl);
  inset-block: var(--inset-block);
  inset-inline: var(--inset-inline);
  --scrollbar-edge: var(--gap-xxs);
  --inline-gap-padding: var(--gap-xl);
  --block-gap-between: var(--gap-m);
  --terminal-color: transparent;
  --terminal-border-gap: calc(var(--block-gap-between) / 2)
}
dialog[open] {
  display: flex
}
dialog.resizeable {
  overflow: hidden
}
@media screen and (height <= 628px) {
  dialog {
    --inset-block: var(--gap-m)
  }
}
@media screen and (height <= 498px) {
  dialog {
    --inset-block: var(--gap-xs)
  }
}
@media screen and (height <= 368px) {
  dialog {
    --inset-block: var(--gap-xxs);
    --block-gap-between: var(--gap-s)
  }
}
@media screen and (width <= 992px) {
  dialog {
    --inset-inline: var(--gap-m);
    --inline-gap-padding: var(--gap-l)
  }
}
@media screen and (width <= 768px) {
  dialog {
    --inset-inline: var(--gap-xs);
    --inline-gap-padding: var(--gap-m)
  }
}
@media screen and (width <= 360px) {
  dialog {
    --inset-inline: var(--gap-xxs);
    --inline-gap-padding: var(--gap-s)
  }
}
dialog[data-type=dialog] {
  min-height: min(max(25%,240px),240px);
  min-width: min(max(25%,360px),360px);
  border-radius: var(--radius-l);
  box-shadow: var(--shadow-size-xl) var(--shadow-color)
}
@media screen and (width >= 992px) {
  dialog[data-type=dialog] {
    width: 464px;
    min-width: 464px
  }
}
dialog[data-type=panel] {
  --inset-inline: 0px;
  --inset-block: 0px;
  margin: 0;
  opacity: 0;
  box-shadow: var(--shadow-size-l) var(--shadow-color)
}
dialog.color-scheme-dark {
  --terminal-color: var(--gray-9);
  background: color-mix(in srgb,var(--gray-9) 24%,var(--alt-10));
  --body-color: var(--alt-1);
  --button-color: var(--body-color);
  --active-bg: var(--gray-10);
  --normal-border: var(--gray-7)
}
dialog.color-scheme-dark hr {
  height: 0
}
dialog.compact {
  --scrollbar-edge: 0px;
  --terminal-border-gap: 0px;
  --block-gap-between: var(--gap-s);
  --inline-gap-padding: var(--gap-m)
}
dialog.maximized {
  width: auto!important;
  height: auto!important;
  border-radius: 0;
  --inset-block: var(--gap-xxs);
  --inset-inline: var(--gap-xxs)
}
dialog.minimized {
  display: none!important
}
:where(.terminal) {
  background: var(--terminal-color);
  padding-inline: var(--inline-gap-padding);
  display: flex;
  flex-direction: row;
  flex: 0 0 auto;
  align-items: center;
  justify-content: space-between;
  gap: 0 var(--gap-s)
}
:where(.terminal) > :empty,
:where(.terminal) > slot:not(.assigned) {
  display: none
}
:where(.terminal) > slot.assigned {
  display: flex
}
:where(.terminal) > * {
  flex: 0 0 auto
}
:where(.terminal) > .contents {
  flex: 1 1 auto;
  min-width: 1rem;
  max-width: 100%
}
.header {
  position: relative;
  border-top: var(--terminal-border-gap) solid transparent;
  padding-block: var(--block-gap-between);
  background-clip: border-box;
  --action-translate: min(var(--inline-gap-padding), calc((var(--widget-height-m) - 1rem) / 2))
}
.header > hr {
  display: block;
  position: absolute;
  inset: auto 0 0;
  height: var(--border-m);
  padding-block: 0;
  padding-inline: inherit;
  margin: 0;
  border: 0;
  background-color: var(--normal-border);
  background-clip: content-box
}
.compact .header > hr {
  background-clip: padding-box
}
:where(.header):has(slot[name=header]:empty) {
  display: none
}
.header:has(slot.assigned),
.header:has(slot:not(:empty)) {
  display: flex
}
.header slot[name=header] {
  display: flex;
  align-items: center;
  flex-wrap: wrap;
  gap: var(--gap-s)
}
.header slot[name=header] > section,
.header slot[name=header]::slotted(*) {
  max-width: 100%;
  flex: 1 0 auto;
  color: var(--body-color)
}
.header slot[name=header]::slotted(.br) {
  flex-basis: 100%
}
.header slot[name=header] > section,
.header slot[name=header]::slotted(:is(h3,h1,h2)) {
  font-weight: var(--font-bold)!important;
  font-size: var(--font-xl)!important;
  flex-shrink: 1;
  margin: 0;
  overflow: hidden;
  text-overflow: ellipsis;
  white-space: nowrap
}
.header slot[name=header].assigned > section {
  display: none
}
.header slot[name=header]::slotted(span) {
  flex-grow: 0
}
.header .contents {
  cursor: default
}
.header .contents:has(+ .actions > .assigned[name=action-buttons]) {
  text-align: center
}
.header slot[name=action-start].assigned {
  min-width: var(--action-translate)
}
.header slot[name=action-start].assigned::slotted([type=bald]:first-of-type) {
  margin-inline-start: calc(var(--action-translate) * -1)
}
.header .actions {
  display: flex;
  gap: 0;
  min-width: var(--action-translate);
  margin-inline-end: calc(var(--action-translate) * -1)
}
.header .actions:has(> .assigned[name=action-buttons]) {
  --action-translate: 0
}
.header .actions slot {
  display: inline-flex
}
.header .actions ::slotted(hr),
.header .actions hr {
  margin: 0 var(--gap-xs);
  border: 0;
  width: var(--border-m);
  height: auto;
  background: var(--normal-border)
}
.header .actions slot[name=actions]:not(.assigned) + hr {
  display: none
}
.footer {
  border-bottom: var(--terminal-border-gap) solid transparent;
  background-clip: border-box
}
.footer .contents:not(:has(> .assigned)) {
  display: none
}
.footer .contents:not(:has(> .assigned)) + slot {
  width: 100%
}
.footer slot[name=buttons] {
  justify-content: end;
  gap: var(--gap-s)
}
.footer:has(slot.assigned) {
  padding-block: 0 var(--block-gap-between)
}
.body {
  flex: 1 1 auto;
  position: relative;
  display: flex;
  flex-direction: column;
  min-height: 1rem;
  padding: var(--block-gap-between) var(--inline-gap-padding);
  overscroll-behavior: contain
}
.scrollable .body {
  overflow: auto;
  --scrollbar-edge-block: calc(var(--scrollbar-edge) * 2);
  margin-block: var(--scrollbar-edge-block);
  padding-block: calc(var(--block-gap-between) - var(--scrollbar-edge-block))
}
.scrollable .body ::slotted(*) {
  max-height: unset
}
@supports (scrollbar-gutter:stable) {
  .scrollable:not(.compact) .body {
    scrollbar-gutter: stable;
    margin-inline-end: var(--scrollbar-edge);
    padding-inline-end: calc(var(--inline-gap-padding) - var(--scrollbar-edge) - var(--scrollbar-w))
  }
}
.compact .body ::slotted(section) {
  margin-block: calc(var(--block-gap-between) * -1);
  margin-inline: calc(var(--inline-gap-padding) * -1);
  max-width: calc(100% + (var(--inline-gap-padding) * 2));
  max-height: calc(100% + (var(--block-gap-between)) * 2)
}
.body ::slotted(*) {
  flex: 1 1 auto;
  max-width: 100%;
  max-height: 100%;
  color: var(--body-color)
}`;