import { getValue } from '../value-path.js';

/** @type {typeof $$.array.unique} */
export default function unique(array, valuePath) {
    const arr = [];
    return array.filter(function (item, i) {
        if (valuePath) {
            const v = getValue(item, valuePath);
            if (arr.includes(v)) return false;
            /// NaN?
            arr.push(v);
            return true;
        } else {
            return array.indexOf(item) === i;
        }
    });
}
