/** @type {typeof $$.number.iteratorRange} */
export default function iteratorRange(min, val, max) {
    const range = max - min;
    if (range <= 0) return [Number.NaN, Number.NaN];

    let acc = 0;
    if (val < min) {
        do {
            val += range;
            acc--;
        } while (val < min);
    } else if (val >= max) {
        do {
            val -= range;
            acc++;
        } while (val >= max);
    }
    return [val, acc];
}
