/** @jsxImportSource @gui/aui-devops */
import { addInternalPlugin } from '../loader.js';
import '../math/math.js';

addInternalPlugin('Math', ({ Plugin, Toolbar, Dialog }) => {
    const I18N = $$.I18N.math;

    class MathButton extends Toolbar.Button {
        icon = true;
        willMount() {
            this.tooltip = I18N.tooltip;
        }
        onClick() {
            this.showDialog(true);
        }
    }

    class MathDialog extends Dialog {
        header = I18N.title;
        width = 1040;
        resizeable = true;

        didMount() {
            this.math = this.element;
        }
        onShow = (data) => {
            this.math.method('willShow');
            if (data) {
                // update when echo logic updated
                this.math.method('setFontSize', data.fontSize);
                this.math.method('setValue', data.latex);
            }
            this.submitter.disabled = !data?.latex;
            this.math.method('show');
        };
        onHide = () => {
            this.math.method('hide');
            this.setVerifyMsg();
        };
        onSubmit = () => {
            const verify = this.math.method('checkFormula');
            this.setVerify(verify);
            if (verify === true) {
                const instance = this.math.method('getInstance'),
                    html = instance.formulaDom.outerHTML ?? '';
                this.setValue(html, {
                    latex: instance.latex,
                    fontSize: instance.fontSizeValue,
                });
            } else {
                return false;
            }
        };
        onOkClick = () => {
            if (!this.submitter.disabled) {
                this.submit();
                this.hide();
            }
        };
        updateButtonStatus = (string) => {
            this.submitter.disabled = !string;
        };
        setVerifyMsg = (string) => {
            this.setVerify(string || true);
        };
        render() {
            return <aui-math okClick={this.onOkClick} updateButtonStatus={this.updateButtonStatus} setVerifyMsg={this.setVerifyMsg} />;
        }
    }

    return class Math extends Plugin {
        static toolbar = MathButton;
        partable = true;

        create() {
            this.addDialog(MathDialog);
        }
        onData(data) {
            this.showDialog(true, data);
        }
    };
});
