import { parse, stringify } from 'css-what';

import * as pseudos from './pseudo.js';

const universal = () => ({ type: 'universal', namespace: null });
const createTrueToken = () => ({ type: 'pseudo', name: 'is', data: [[universal()]] });
const createFalseToken = () => ({ type: 'pseudo', name: 'not', data: [[universal()]] });

function resolveCustomPseudos(group, element) {
    const resolved = [];

    for (const token of group) {
        if (token.type === 'pseudo' && pseudos[token.name]) {
            resolved.push(pseudos[token.name](element, token.data) ? createTrueToken() : createFalseToken());
            continue;
        }

        if (Array.isArray(token.data)) {
            resolved.push({
                ...token,
                data: token.data.map((subGroup) => resolveCustomPseudos(subGroup, element)),
            });
            continue;
        }

        resolved.push(token);
    }

    return resolved;
}

export default function matchSelector(element, selector) {
    if (element?.nodeType !== Node.ELEMENT_NODE || !selector) return false;
    const ast = parse(selector),
        resolvedAST = ast.map((group) => resolveCustomPseudos(group, element)),
        resolvedSelector = stringify(resolvedAST);

    return !!resolvedSelector && element.matches(resolvedSelector);
}
