import { concat } from '../../util/array/concat.js';

export function autoTag(html = '') {
    let { body } = Document.parseHTMLUnsafe(html);

    const DeleteList = [];
    const ReplaceList = [
        {
            name: 'audio',
            selector: 'audio',
            text: $$.I18N.richeditor.audioTag,
        },
        {
            name: 'code',
            selector: 'pre[data-pbcklang]',
            text: $$.I18N.richeditor.codeTag,
        },
        {
            name: 'math',
            selector: '.cke_widget_math',
            text: $$.I18N.richeditor.mathTag,
        },
        {
            name: 'music',
            selector: '.cke_widget_music',
            text: $$.I18N.richeditor.musicTag,
        },
        {
            name: 'picture',
            selector: 'img, svg, picture',
            text: $$.I18N.richeditor.pictureTag,
        },
        {
            name: 'picture',
            selector: '.cke_widget_mediabox[data-cke-display-name="img"]',
            text: $$.I18N.richeditor.pictureTag,
        },
        {
            name: 'table',
            selector: 'table',
            text: $$.I18N.richeditor.tableTag,
        },
        {
            name: 'video',
            selector: 'video',
            text: $$.I18N.richeditor.videoTag,
        },
    ];

    for (const item of DeleteList) {
        const { selector } = item;

        for (const element of body.querySelectorAll(selector)) {
            element.remove();
        }
    }

    for (const item of ReplaceList) {
        const { name, selector, text } = item;

        for (const element of body.querySelectorAll(selector)) {
            const span = document.createElement('span');
            span.classList.add('aui-richeditor-tag');
            span.setAttribute('data-name', name);
            span.textContent = text;

            element.replaceWith(span);
        }
    }

    const linkKey = 'aui-richEditor-link-\\d+-key',
        tagKey = 'aui-richEditor-tag-\\d+-key',
        tagList = [],
        linkList = [];

    for (const a of body.querySelectorAll('a')) {
        const key = linkKey.replace('\\d+', linkList.length);
        linkList.push(a.outerHTML);
        a.replaceWith(key);
    }

    for (const tag of body.querySelectorAll('.aui-richeditor-tag')) {
        const key = tagKey.replace('\\d+', tagList.length);
        tagList.push(tag.outerHTML);
        tag.replaceWith(key);
    }

    for (const element of body.querySelectorAll('br, div, p, pre, li, h1, h2, h3, h4, h5, h6, address')) {
        element.parentNode.insertBefore(document.createTextNode(' '), element);
        element.parentNode.insertBefore(document.createTextNode(' '), element.nextElementSibling);
    }

    body = Document.parseHTMLUnsafe(
        `<span>${body.innerText
            .replaceAll('<', '&lt;')
            .replaceAll('>', '&gt;')
            .replaceAll(new RegExp(linkKey, 'g'), function (name) {
                return linkList[name.match(/\d+/)[0]];
            })}</span>`
    ).body;

    body = Document.parseHTMLUnsafe(
        `<span>${body.innerHTML.replaceAll(new RegExp(tagKey, 'g'), function (name) {
            return tagList[name.match(/\d+/)[0]];
        })}</span>`
    ).body;

    return body.innerHTML;
}

export function normalizeContent(body, mode = 'editor') {
    const scope = mode === 'editor' ? ['br', 'table'] : ['table'];
    const bodyClone = mode === 'editor' ? body.cloneNode(true) : Document.parseHTMLUnsafe(body.innerHTML).body;
    let changed = false;

    if (scope.includes('br')) {
        for (const br of bodyClone.querySelectorAll('br:not([data-mce-bogus="1"], p > br, li > br, th > br:only-child, td > br:only-child)')) {
            const box = br.closest('td, th, p, body > *');

            box.replaceWith(...splitElement(box, br));

            changed = true;
        }
    }

    if (scope.includes('table')) {
        for (const table of bodyClone.querySelectorAll('table[class=""]')) {
            table.setAttribute('rules', 'all');
            table.style.tableLayout = 'fixed';
            table.style.border = null;
            table.setAttribute('border', table.style.getPropertyValue('--border-width') ? Number.parseInt(table.style.getPropertyValue('--border-width'), 10) : 1);
            table.style.borderStyle = table.style.getPropertyValue('--border-style') || 'solid';
            table.style.borderColor = '#000';
            table.setAttribute('data-mce-style', table.getAttribute('style'));

            for (const node of table.querySelectorAll('thead, tbody, tr, th, td')) {
                node.style.border = 'inherit';
                node.setAttribute('data-mce-style', node.getAttribute('style'));
            }

            changed = true;
        }
    }

    if (changed) {
        body.replaceChildren(...bodyClone.childNodes);
    }

    return changed;
}

/** @param {Element} box @param {Element} splitter  */
function splitElement(box, splitter) {
    let before, after;
    let current = splitter;
    while (current !== box) {
        const parent = current.parentElement,
            node = parent.cloneNode(false),
            [...children] = parent.childNodes;
        if (after) node.append(after);
        let index;
        // eslint-disable-next-line no-loop-func
        children.forEach((child, i) => {
            if (child === current) {
                index = i;
                if (child === splitter) child.remove();
            } else if (index != null && i > index) {
                node.append(child);
            }
        });
        current = parent;
        after = node;
    }
    before = current;
    if (before.matches(':empty')) {
        // eslint-disable-next-line aui/inner-html
        before.innerHTML = '<br data-mce-bogus="1"/>';
    } else if (before.matches('td,th')) {
        const list = [],
            blocks = /(p|div|ol|ul|table|h[1-6]|d[ltd])/i;
        let current;
        for (const node of before.childNodes) {
            if (node.nodeType === Node.ELEMENT_NODE && blocks.test(node.nodeName)) {
                if (current) {
                    list.push(current);
                    current = null;
                }
                list.push(node);
            } else {
                if (!current) current = document.createElement('p');
                current.append(node);
            }
        }
        if (current) list.push(current);
        before.replaceChildren(...list);
        before.append(...after.childNodes);
        after = null;
    }
    // eslint-disable-next-line aui/inner-html
    if (after?.matches(':empty')) after.innerHTML = '<br data-mce-bogus="1"/>';

    return concat(before, after || []);
}
