  input:is([type=checkbox],[type=radio]):not(:checked) {
    content-visibility: visible;
    font-size: 0
  }
}
input:is([type=checkbox]) {
  border-radius: var(--widget-radius-m)
}
input:is(:disabled,[readonly]) {
  background-color: var(--disabled-bg)
}
input.check-mark {
  margin-inline-start: auto;
  border: none;
  background: 0 0
}
input.check-mark:not(:checked) {
  width: 0
}
.text-overflow {
  flex: 1 1 auto
}
.selection {
  display: flex;
  flex-direction: column;
  width: 100%;
  padding: var(--gap-s);
  gap: var(--gap-s) 0
}
.top {
  flex: 0 0 auto
}
.box {
  flex: 1 1 auto;
  display: flex;
  flex-direction: column;
  min-height: 1em;
  position: relative
}
.box footer,
.box header {
  flex: 0 0 auto
}
.box:has(> #scroll-box > #lazyload:empty) header {
  display: none
}
.box:has(> #scroll-box > #lazyload:empty) .message {
  display: block
}
#scroll-box {
  flex: 1 1 auto;
  display: block;
  overflow: hidden auto;
  overscroll-behavior: contain
}
