  border-radius: var(--radius-s);
  background: var(--alt-bg);
  font-weight: var(--font-semibold)
}
.group-header:not(:empty) {
  position: sticky;
  top: 0;
  z-index: 1
}
.group-header > * {
  flex: 1 1 auto
}
summary.group-header {
  cursor: pointer;
  --rotate: 0deg
}
[open] > summary.group-header {
  --rotate: 180deg
}
summary.group-header::marker {
  display: none
}
