/** @jsxImportSource @gui/aui-devops */
import $ from '../../core/element/index.js';
import { define, Widget } from '../../widget/widget.js';

import { ItemOptions, ItemObservers, GroupOptions, GroupObservers, ClassName, Render, Group } from '../checkbox/choice.js';

/** @extends {Widget<typeof Radio.options>} */
@define('radio')
export class Radio extends Widget {
    static options = {
        ...ItemOptions,
    };
    static shadow = false; /// { delegatesFocus: true };
    // static formAssociated = true;
    static observers = [...ItemObservers];
    static upcasts = ['separate'];

    init() {
        this.state = { checked: this.options.checked };
        this.method = { getValue: this.getValue };
    }
    didMount() {
        this.target = this.host.querySelector('input');
    }
    getValue = () => {
        return this.state.checked;
    };
    onChange = (e) => {
        const last = this.refreshGroup(true);
        if (last) e.relatedTarget = last;
        this.callback('onChange', this.options.value);
        this.setState({ checked: true, dirty: true });
    };
    refresh(target, checked) {
        if (target.ariaChecked !== String(checked)) {
            const $target = $(target),
                element = $target.closest('.aui-radio').get();
            element.setAttribute('checked', checked);
            target.checked = checked;
            $target.toggleAttr('checked', checked).attrs('aria-checked', checked);
            return true;
        }
    }
    refreshGroup(checked) {
        let last;
        if (checked) {
            const group = document.querySelectorAll(`.${ClassName.Input}[name="${this.options.name}"]`);
            group.forEach((el) => el !== this.target && this.refresh(el, false) && (last = el));
        }
        this.refresh(this.target, checked);
        return last;
    }
    setOption(name, value) {
        if (name === 'checked' && this.state.checked !== value) {
            this.state.checked = value;
            this.refreshGroup(value);
        }
    }
    render() {
        return Render('radio', this, this.onChange);
    }
}

/** @extends {Widget<typeof RadioGroup.options>} */
@define('radio-group')
export class RadioGroup extends Group {
    static options = {
        ...GroupOptions,
    };
    static observers = [...GroupObservers];
    static requires = ['name', 'items'];
    static upcasts = ['block'];
    static shadow = false;

    onChange = (value) => {
        let newValue = '';
        for (const item of this.state.items) {
            const current = String(item.value) === String(value);
            if (current) newValue = item.value;
            item.checked = current;
        }
        this.setState({ dirty: true });
        this.callback('onChange', newValue, this.oldValue);
        this.oldValue = newValue;
    };
    getValue() {
        for (const item of this.state.items) {
            if (item.checked) this.oldValue = item.value;
        }
        return this.oldValue;
    }
    verify = () => {
        const value = this.getValue();
        return [value];
    };
    render() {
        return super.render('aui-radio', { role: 'radiogroup' });
    }
}
