import $ from '../../core/element/index.js';

import forEach from '../object/for-each.js';

export const touchable = $$.browser.touchable;

export const touchList = (e) => (e.type?.endsWith('start') ? e.touches : e.changedTouches);

/// TD: split
export function distance(e1, e2 = $$.event.mouseMove) {
    const { pageX: x1, pageY: y1 } = touchList(e1)?.[0] || e1,
        { pageX: x2, pageY: y2 } = touchList(e2)?.[0] || e2;
    return Math.hypot(x1 - x2, y1 - y2);
}

export function touchEvent(element, options, events) {
    if (typeof options === 'string') options = { key: options };
    let { selector, key: dataKey, ...args } = options;
    if (selector) dataKey += '_' + selector;
    const $element = $(element);
    /** @type object */
    let data = $element.data(dataKey);
    if (data && data.selector === selector) return data;
    data = { selector };
    $element.data(dataKey, data);
    forEach(events, function (event, callback) {
        if (selector) {
            $element.on(event, selector, { checkDisabled: true, ...args }, callback);
        } else {
            $element.on(event, { checkDisabled: true, passive: false, ...args }, callback);
        }
    });
    return data;
}
