/** @type {typeof $$.string.htmlEncode} */
export default function htmlEncode(val, allFields) {
    val = val.replaceAll('<', '&lt;').replaceAll('>', '&gt;');
    if (allFields) {
        const List = { '&': '&amp;', '"': '&#34;', "'": '&#39;', '`': '%backtick;' };
        for (const [k, v] of Object.entries(List)) {
            val = val.replaceAll(k, v);
        }
    }
    return val;
}
