export function child(query, options) {
    const node = this;
    const list = flatChildren(node, options);
    if (query == null || query === '*') return list[0];
    if (typeof query == 'number') return arrayAt(list, query, false);
    return list.find((element) => is.call(element, query)) || null;
}
export function children(query, options) {
    const node = this;
    const list = flatChildren(node, options);
    if (query == null || query === '*') return list;
    return list.filter((element) => is.call(element, query));
}
export function slots(name) {
    const node = this;
    const query = !name || name === 'children' ? ':not([slot])' : `[slot="${name}"]`;
    return children.call(node, query);
}

function _flatSubtree(acc, element, options) {
    const list = flatChildren(element, options);
    for (const el of list) {
        acc.push(el);
        _flatSubtree(acc, el, options);
    }
}
