/** @jsxImportSource @gui/aui-devops */
import { ButtonWidget, Options } from '../../widget/form/button-util.js';
import { define, Widget } from '../../widget/widget.js';

/** @extends {Widget<typeof Button.options>} */
@define('button')
export class Button extends ButtonWidget {
    static options = {
        ...Options,
    };
    static shadow = false;
    static observers = [...ButtonWidget.observers];

    render() {
        const { type, icon, text } = this.options,
            showText = type !== 'icon' && text,
            attrs = this.attributes();
        return (
            // eslint-disable-next-line react/button-has-type
            <button {...attrs}>
                {icon && <span className={['button-icon-part', icon]} aria-hidden="true" />}
                {showText && <span className="button-text-part">{text}</span>}
            </button>
        );
    }
}
