import language from '../../misc/find-lang.js';

import objectEmpty from '../../util/object/empty.js';
import objectForEach from '../../util/object/for-each.js';
import objectMerge from '../../util/object/merge.js';
import { isObject, nonEmptyObject } from '../../util/type/types.js';

import getI18N from '../../i18n/entries.js';

import { warn, throws } from './log.js';

const { findLang, getSource } = language();
export const I18N = {};

const defaultLanguage = findLang();
$$.switchI18N = function (lang, data) {
    if (arguments.length === 1 && isObject(lang)) {
        data = lang;
        lang = undefined;
    }
    if (typeof lang === 'string' && lang.length > 0) {
        const [a, b] = lang.split('-');
        try {
            lang = a + '-' + b.toUpperCase();
        } catch (e) {
            /* empty */
        } finally {
            lang = findLang(lang);
        }
    }

    if (!lang) lang = defaultLanguage;
    if (I18N.lang !== lang || data) {
        document.documentElement.setAttribute('lang', lang);
        mergeI18N(lang.toLowerCase(), data);
        I18N.lang = lang;
    }
};

function mergeI18N(lang, data) {
    const entries = getI18N();
    if (nonEmptyObject(data)) {
        objectMerge(entries, data);
    }

    function getValue(key) {
        const entry = getSource(I18N.lang)[key] || warn('No such I18N entry: ', key) || '';
        return entry.replaceAll(new RegExp('&nbsp;', 'g'), ' ');
    }
    const setter = () => {
        throws('Cannot set I18N entries via assignment operator, use $$.switchI18N() instead.');
    };
    const value = (v) => (v.endsWith('_Entry') || v.endsWith('_Message') ? { get: () => getValue(v), set: setter } : { value: v });
    const _define = (obj, k, v) => Object.defineProperty(obj, k, { configurable: true, enumerable: true, ...value(v) });

    $$.I18N = objectEmpty(I18N);
    objectForEach(entries, (name, entries) => {
        if (isObject(entries)) {
            objectForEach(entries, (k, v) => {
                const _obj = {};
                if (Array.isArray(v)) {
                    v.forEach((val, i) => _define(_obj, i, val));
                    Object.defineProperty(_obj, 'length', { configurable: false, enumerable: false, value: v.length });
                    _obj[Symbol.iterator] = function* (index = 0) {
                        while (index < _obj.length) {
                            yield _obj[index++];
                        }
                    };
                    I18N[name][k] = _obj;
                } else if (isObject(v)) {
                    objectForEach(v, _define.bind(null, _obj));
                    I18N[name][k] = _obj;
                } else {
                    if (!I18N[name]) I18N[name] = {};
                    _define(I18N[name], k, v);
                }
            });
        }
    });
}

$$.switchI18N();
