/** @jsxImportSource @gui/aui-devops */
import $ from '../../core/element/index.js';
import { addTooltip } from '../../core/module/tooltip.js';
import { define, Widget, Types } from '../../widget/widget.js';

import eventIsKey from '../../util/event/is-key.js';
import { keyPress as eventKeyPress } from '../../util/event/key-press.js';
import stringFormat from '../../util/string/format.js';
import { nonEmptyObject as typeNonEmptyObject } from '../../util/type/types.js';

import '../lazyload/lazyload.js';
import { elementLoading } from '../loading/loading.js';
import '../searchbox/searchbox.js';

import parseTemplate from './templates.js';
import * as utils from './utils.js';

import styles from './style.less';

/** @typedef {ReturnType<typeof utils.buildItem>} ItemEntity */

const { I18N } = utils;
const CheckMarkIcon = 'faui-ok';
const DefaultLazyStep = 50;
const TabloopArgs = { query: 'focusable', bubbles: false, tabMode: false, arrowMode: 'v', arrowLoop: false, arrowFlipPrevent: true, filterQuery: 'input:visible' };
Object.assign(TabloopArgs, {
    doFocus(el) {
        el.focus({ focusVisible: true, preventScroll: true });
        $$.scrollTo(el.closest('.item'));
    },
    onArrow(current, previous) {
        current.tabIndex = 0;
        previous.tabIndex = -1;
    },
});

@define('selection')
export class Selection extends Widget {
    static options = {
        type: Types.Enum(['single', 'multiple', 'rich'], 'single'),
        disabled: false,
        readonly: false,
        minHeight: Types.number,
        maxHeight: Types.number,

        items: Types.array,
        value: Types.Union([Types.string, Types.object, Types.array]),
        createNewText: Types.Union([Types.boolean, Types.string]),
        lazyStep: Types.Union([Types.number, Types.boolean], DefaultLazyStep),

        template: Types.Union([Types.string, Types.Component]),
        groupTemplate: Types.Union([Types.string, Types.Component]),
        groupToggleable: false,
        matchFields: Types.PlainObject,

        //#region Search options
        searchable: false, // true for Comboboxes by default
        searchPlaceholder: I18N.placeholder,
        searchMinChars: 0,
        searchDelay: 350,
        //#endregion

        //#region Single mode options
        excludeChecked: false,
        clearable: false,
        //#endregion

        //#region Multiple mode options
        hasSelectAll: true,
        filter: false,
        pinSelected: false, // true for MultiCombobox by default
        required: Types.Union([Types.array, Types.boolean], true),
        //#endregion

        //#region Field options
        textField: 'text',
        valueField: 'value',
        checkedField: 'checked',
        tooltipField: 'tooltip',
        statusField: 'status',
        disabledField: 'disabled',
        iconField: Types.string,
        groupField: Types.string,
        //#endregion

        //#region I18N Texts
        selectAllText: I18N.selectAllText,
        selectAllSearchText: I18N.selectAllSearchResults,
        noneText: I18N.noneMessage,
        noMatchText: I18N.noMatches,
        //#endregion

        //#region Callbacks
        doLoad: Types.function,
        doCreateNew: Types.function,
        onChange: Types.function,

        /** @todo @private for RC */
        willSearch: Types.function,
        /** @todo @private for RC */
        onSearch: Types.function,
        /** @todo @private for RC */
        willSelected: Types.function,
        /** @todo @private for C */
        onSelected: Types.function,
        /** @todo @private for RC */
        onGetSelected: Types.function,
        /** @todo @private for RC */
        onCreateNew: Types.function,
        //#endregion
    };
    static observers = ['items', 'disabled', 'readonly', 'searchPlaceholder', 'value']; // 'searchBox'
    static styles = styles;

    /** @type {Map<ID, ItemEntity>} */
    #cache = new Map();
    /** @type {Set<ItemEntity>} */
    #items = new Set();
    /** @type {Set<ItemEntity>} */
    #knownItems = new Set();
    /** @type {Set<ItemEntity>} */
    #selected = new Set();
    /** @type {Map<ID, boolean>} */
    #groupExpanded = new Map();

    create() {
        this.method = {
            clear: this.clearSearch, /// rename to clearSearch
            load: this.load,
        };
        this.fontIcon(CheckMarkIcon);
    }
    init() {
        const P = this.options,
            { excludeChecked, lazyStep, matchFields, searchable, searchDelay } = P,
            isInfinityData = P.doLoad != null,
            createNewText = P.createNewText === true ? I18N.createNew : typeof P.createNewText === 'string' ? P.createNewText : '',
            createNewBySearch = createNewText.includes('{0}'),
            templateValid = parseTemplate(this.console);

        const state = {
            isMultiple: P.type === 'multiple',
            isInfinityData,
            excludeChecked,
            template: templateValid(P.template),
            groupTemplate: templateValid(P.groupTemplate),
            groupToggleable: P.groupToggleable,
            createNewText,
            createNewBySearch,
            hasCreateNew: !!createNewText,
            hasSearch: searchable || createNewBySearch,
            searchKey: '',
            hasExactMatch: false,
            matchFields: typeNonEmptyObject(matchFields) ? matchFields : { [P.textField]: false },
            lazyStep: lazyStep === true ? DefaultLazyStep : Number.isInteger(lazyStep) && lazyStep > 0 ? lazyStep : Infinity,
            lazyPageCount: 1,
            lazyLoadDisabled: false,
            isResettingData: false,
            hasSelectAll: false,
            selectAllChecked: false,
            selectAllDisabled: false,
            pinSelected: false,
            minItemsLength: 0,
            maxItemsLength: Infinity,
            enableLoading: false,
            data: [],
        };

        if (Number.isInteger(searchDelay) && searchDelay > 0) {
            this.#onSearchAsync = $$.debounce(this.#doSearchAsync, searchDelay);
        }
        if (isInfinityData) {
            this.#onSearch = this.#onSearchAsync;
            state.groupToggleable = false;
        } else {
            const { items } = P;
            if (items?.length) queueMicrotask(() => this.setState({ data: this.parseData(items) }));
        }

        if (state.isMultiple) {
            const { hasSelectAll, required } = P;
            if (required === true) {
                state.minItemsLength = 1;
            } else if (Array.isArray(required)) {
                const [min, max] = required;
                if (Number.isInteger(min) && min > 0) state.minItemsLength = min;
                if (Number.isInteger(max) && max > 0) state.maxItemsLength = Math.max(max, state.minItemsLength);
            }
            state.excludeChecked = false;
            state.hasSelectAll = hasSelectAll && !isInfinityData && state.maxItemsLength === Infinity;
            state.pinSelected = P.pinSelected || P.filter;
            this.#renderItem = this.#renderMultiple;
        }

        this.state = state;
    }
    didMount() {
        addTooltip(this.host);
        const { type } = this.options;
        this.initEvent();
        return type === 'multiple' ? this.initMultipleEvent() : this.initSingleEvent();
    }
    didRender() {
        if (this.state.isResettingData) {
            const scrollBox = this.shadowRoot.getElementById('scroll-box');
            scrollBox.scrollTo(0, 0);
            this.state.isResettingData = false;
        }
    }
    #updateData(items) {
        const data = this.parseData(items);
        if (data == null) return false;
        this.setState({ data }, false);
        return true;
    }
    setOption(name, value, oldValue) {
        switch (name) {
            case 'items':
                return this.#updateData(value);
            case 'value':
                return this.#updateData(this.options.items);
        }
    }
    initEvent() {}
    initSingleEvent() {
        this.$element.on('click', '#scroll-box .item', this.onSingleItemClick);
        this.$element.on('keydown', '#scroll-box .item', (e) => {
            if (eventIsKey(e, 'Space')) e.preventDefault();
        });
        eventKeyPress(this.element, 'Enter', '#scroll-box .item', this.onSingleItemClick);
    }
    initMultipleEvent() {
        this.$element.on('click', '#scroll-box .item', this.onMultipleItemClick);
        eventKeyPress(this.element, 'Space', '#scroll-box .item', this.onMultipleItemClick);
    }

    /** @returns {Array<ItemEntity>} */
    #parseItems = (items, clearCache, clearSelected) => {
        const { options: P, state } = this,
            optionValue = P.value,
            cache = this.#cache,
            itemsCache = this.#items,
            selected = this.#selected,
            selectedList = new Set();
        if (clearCache) {
            cache.clear();
            itemsCache.clear();
            this.#groupExpanded.clear();
            state.lazyPageCount = 1;
            state.lazyLoadDisabled = false;
        }
        if (clearSelected) {
            selected.clear();
        } else {
            for (const item of selected) {
                if (item.value != null) selectedList.add(item.value);
            }
        }
        const valueList = new Set(),
            data = [],
            valueData = [];
        const checkedValue = utils.createCheckedValueMatcher(P, optionValue),
            duplicate = ({ value }) => cache.has(value) || valueList.has(value);
        const commitItem = (item) => {
            cache.set(item.value, item);
            itemsCache.add(item);
            if (item.checked && !selectedList.has(item.value)) selected.add(item);
        };
        for (const item of items) {
            const obj = utils.buildItem(P, item, { fallbackValue: true, setChecked: !state.isInfinityData });
            if (duplicate(obj)) {
                this.console.error('Item discarded due to duplicate value:', obj.value, item);
                continue;
            }
            obj.original = item;
            obj.checked = checkedValue ? checkedValue.getCheckedByValue(obj) : clearSelected ? obj.checked : selectedList.has(obj.value);
            valueList.add(obj.value);
            data.push(obj);
        }
        if (clearCache && checkedValue?.values?.length) {
            for (const val of checkedValue.values) {
                const obj = utils.buildItem(P, val, { setChecked: false });
                if (!obj.value.length || duplicate(obj)) continue;
                Object.assign(obj, { checked: true, original: val });
                valueData.push(obj);
                commitItem(obj);
            }
        }
        for (const obj of data) commitItem(obj);

        if (!state.isMultiple) {
            utils.singleFilter.onlyFirst(selected);
        }
        if (clearCache) {
            const result = valueData.length ? [...valueData, ...data] : data; // for better performance.
            if (state.hasSelectAll) {
                this.setState({ selectAllChecked: selected.size === 0 ? false : selected.size === result.length ? true : 'mixed' }, false);
            }
            return result;
        }
        return Array.from(itemsCache);
    };
    #doParseData(items) {
        const { groupField } = this.options,
            { lazyStep, pinSelected } = this.state,
            splitData = utils.splitDataForRender({ lazyStep, pinSelected }),
            nullishName = undefined;
        if (!groupField) return splitData([nullishName, items]);
        const data = utils.toGroupItems(items, groupField);
        return splitData(...data);
    }
    #parseData(items, clearCache, clearSelected) {
        this.state.isResettingData = clearCache;
        return this.#doParseData(this.#parseItems(items, clearCache, clearSelected));
    }
    parseData(items) {
        if (this.state.isInfinityData) return this.console.error('Discarded items property in doLoad mode.');
        return this.#parseData(items, true, true);
    }

    load() {
        if (this.state.isInfinityData) {
            this.doLazyLoad();
        }
    }
    clearSearch() {
        this.#onSearch('');
    }
    loading(isShow) {
        if (this.state.enableLoading) {
            const target = this.shadowRoot.getElementById('loading');
            elementLoading(target, isShow, { text: false });
            if (!isShow) this.setState({ enableLoading: false }, false);
        }
    }
    setChecked(id, checked) {
        const item = this.#cache.get(id);
        if (!item || item.checked === checked) return false;

        item.checked = checked;
        item.original[this.options.checkedField] = checked;
        if (checked) {
            if (this.#selected.size) {
                this.#selected.clear();
                for (const it of this.#cache.values()) {
                    if (it.checked) this.#selected.add(it);
                }
            } else {
                this.#selected.add(item);
            }
        } else {
            this.#selected.delete(item);
        }
        return item;
    }
    /** @returns {ReturnType<typeof this.setChecked>} */
    doChangeItem(target, single) {
        const input = target.querySelector('input'),
            box = target.parentElement;
        const setChecked = (el, checked) => {
            const action = $(el).find('input', { matchSelf: true }).get();
            action.checked = checked;
            action.toggleAttribute('checked', checked);
            action.ariaSelected = checked;
        };
        let checked = true,
            changed = false;
        if (single) {
            if (this.options.clearable && input.checked) checked = false;
            if (checked) {
                const last = this.#getSingleSelected();
                if (last) last.checked = false;
            }
            for (const el of box.querySelectorAll('.item')) {
                if (el.id === target.id) {
                    setChecked(el, checked);
                    changed = this.setChecked(el.id, checked);
                } else {
                    setChecked(el, false);
                    this.setChecked(el.id, false);
                }
            }
        } else {
            checked = !input.checked;
            changed = this.setChecked(target.id, checked);
        }
        if (!changed) return false;

        input.tabIndex = checked ? 0 : -1;
        setChecked(input, checked);

        /**
         * `[tabindex="0"]`: The old tabbable items(if exists) and the new one(if checked).
         * Add the first checked item to list, it maybe the newly checked one, or another checked item in multiple mode.
         * Maybe replace with original focusgroup API in the future. (Chrome≥150).
         */
        const xItems = new Set(box.querySelectorAll('[tabindex="0"]'));
        xItems.add(box.querySelector(':checked'));
        let hasTabbable = false;
        for (const x of xItems) {
            if (!x) continue;
            if (x.checked && !hasTabbable && x.checkVisibility()) {
                x.tabIndex = 0;
                hasTabbable = true;
            } else {
                x.tabIndex = -1;
            }
        }
        if (!hasTabbable) {
            box.querySelector('.item input')?.setAttribute('tabindex', 0);
        }
        return changed;
    }
    #getSingleSelected() {
        return this.#selected.values().next().value;
    }
    #onSingleChange(current, oldValue, newValue) {
        const args = { current, oldValue: oldValue || null, newValue: newValue || null };
        this.callback('onChange', args);
    }
    onSingleItemClick = (e) => {
        e.preventDefault();
        const oldValue = this.#getSingleSelected(),
            current = this.doChangeItem(e.currentTarget, true);
        if (current) this.#onSingleChange(current.original, oldValue, current.checked && current.original);
    };
    #getMultipleSelected() {
        return Array.from(this.#selected, (item) => item.original);
    }
    #onMultipleChange(current, oldValue, updateMode) {
        const { data, isInfinityData, maxItemsLength } = this.state,
            newValue = this.#getMultipleSelected(),
            { length } = newValue,
            isSelectAll = this.options.filter && length === 0 ? true : !isInfinityData && length === this.#items.size,
            state = { selectAllChecked: isSelectAll ? true : length > 0 ? 'mixed' : false },
            args = { isSelectAll, current, oldValue, newValue };
        if (length >= maxItemsLength) {
            state.data = utils.disableItemsForExceedMaxLength(data, newValue, this.options);
        }
        this.setState(state, updateMode);
        this.callback('onChange', args);
    }
    onMultipleItemClick = (e) => {
        e.preventDefault();
        const oldValue = this.#getMultipleSelected(),
            current = this.doChangeItem(e.currentTarget, false);
        if (current) this.#onMultipleChange(current.original, oldValue);
    };
    willSelectAllChange = (checked) => {
        const searched = this.state.searchKey.length > 0,
            selected = this.#selected,
            oldValue = this.#getMultipleSelected();
        let items = this.#items;
        if (searched) {
            items = new Set(this.#knownItems);
            for (const item of selected) {
                if (item.disabled) items.add(item);
            }
        }
        const { changed, disabled, selectAllChecked } = utils.parseSelectAllState(checked, items, selected);
        this.setState({ oldValue: null, selectAllDisabled: disabled, selectAllChecked }, false);
        if (changed || (searched && selectAllChecked)) {
            this.setState({ oldValue: changed }, false);
            this.#onMultipleChange(null, oldValue, false);
        }
        this.setState();
        return selectAllChecked;
    };
    refreshSelectAllState(data) {
        const [...items] = data || this.#items;
        let isAll = false,
            disabled = true,
            hasChecked = false;
        if (items.length) {
            isAll = disabled = true;
            for (const item of items) {
                if (item.checked) {
                    hasChecked = true;
                } else {
                    isAll = false;
                }
                if (!item.disabled) disabled = false;
            }
        }
        this.setState({ selectAllDisabled: disabled }, false);
        return isAll ? true : hasChecked ? 'mixed' : false;
    }
    #doSearchAsync = (key, searchChanged) => {
        this.setState({ searchKey: key, lazyPageCount: 1, lazyLoadDisabled: false, enableLoading: true }, false);
        this.doLazyLoad(true);
    };
    #onSearchAsync = this.#doSearchAsync;

    #doSearchSync = (key, searchChanged) => {
        const { matchFields } = this.state,
            [hasExactMatch, items] = utils.filterSearchItems(this.#items, key, matchFields),
            data = this.#doParseData(items);
        this.#knownItems = new Set(items);
        if (this.state.hasSelectAll) {
            if (!key) {
                const selected = this.#selected;
                for (const item of this.#items) {
                    item.checked = selected.has(item);
                }
            }
            const isAll = this.refreshSelectAllState(items);
            if (searchChanged) this.setState({ selectAllChecked: key ? false : isAll }, false);
        }
        this.setState({ searchKey: key, hasExactMatch, data });
    };
    #onSearchSync = this.#doSearchSync;
    /** @alias `#onSearchSync`|`#onSearchAsync` */
    #onSearch = this.#onSearchSync;
    onSearch = (key) => {
        const searchChanged = Boolean(this.state.searchKey) !== Boolean(key);
        if (!key) return this.#onSearch('', searchChanged);
        const { searchMinChars } = this.options;
        if (key.length >= searchMinChars) return this.#onSearch(key, searchChanged);
        return null;
    };

    refreshLazyState(isFinished, nextCount) {
        this.setState(isFinished ? { lazyLoadDisabled: true } : { lazyLoadDisabled: false, lazyPageCount: nextCount });
    }
    /** lazy load items for render */
    doLazyRender = () => {
        const { data, lazyPageCount } = this.state,
            count = lazyPageCount + 1;
        this.refreshLazyState(count > data.length, count);
    };
    /** lazy load with doLoad */
    doLazyLoad = (reset = false) => {
        const { lazyPageCount, lazyStep, searchKey } = this.state,
            start = (lazyPageCount - 1) * lazyStep,
            // end = start + lazyStep,
            args = { key: searchKey, start, count: lazyStep };
        if (!reset) this.element.querySelector('.message').toggleAttribute('hidden', true);
        this.loading(true);
        return this.callbackResult(this.callback('doLoad', args)).then((items) => {
            const data = this.#parseData(items, reset);
            this.setState({ data }, false);
            this.refreshLazyState(items.length < lazyStep, lazyPageCount + 1);
            this.loading(false);
        });
    };
    onCreateNew = async (e) => {
        const { textField, valueField, doCreateNew } = this.options,
            { searchKey } = this.state,
            { error } = this.console;
        let result = {};

        if (doCreateNew) {
            result = await this.callbackResult(this.callback('doCreateNew', { key: searchKey }));
            if (!result) return;
            const content = String(result[textField] ?? '');
            for (const item of this.#items) {
                if (String(item[textField] ?? '') === content && item[valueField] === result[valueField]) {
                    return error('The created item is discarded due to duplicate text field with existing items:', content, result);
                }
            }
        }
        const text = result[textField] ?? searchKey;
        return text ? this.#addDataToItems(result, text) : error('The created item is discarded due to invisible text content:', text, result);
    };
    #addDataToItems = (data, key) => {
        const { textField, valueField, checkedField } = this.options,
            { isMultiple } = this.state;
        let mapping, oldValue;
        if (isMultiple) {
            mapping = (item) => ({ ...item.original });
            oldValue = this.#getMultipleSelected();
        } else {
            mapping = (item) => ({ ...item.original, [checkedField]: false });
            oldValue = this.#getSingleSelected();
        }
        const sourceItems = Array.from(this.#items, mapping);
        const item = {
            [textField]: key,
            [valueField]: utils.itemId({ [textField]: key, timestamp: Date.now() }),
            [checkedField]: true,
            ...data,
        };
        sourceItems.push(item);
        const parsedData = this.parseData(sourceItems);
        if (parsedData != null) this.setState({ data: parsedData, searchKey: '', hasExactMatch: false }, true);
        this.callback('onCreateNew', item);
        return isMultiple ? this.#onMultipleChange(item, oldValue) : this.#onSingleChange(item, oldValue, item);
    };
    onGroupToggle = (e) => {
        this.#groupExpanded.set(e.target.id, e.newState === 'open');
    };
    renderGroup = (group, args = {}) => {
        const className = 'group-header',
            attrs = { className: 'group-box', ...args };
        let content;
        if (group) {
            const { groupTemplate, groupToggleable } = this.state;
            content = groupTemplate ? $$.fn(groupTemplate)({ text: group, original: { [this.options.textField]: group } }) : group;
            Object.assign(attrs, { id: utils.hashId('group', group), 'data-group': group });

            if (groupToggleable) {
                const expanded = this.#groupExpanded.get(attrs.id) ?? true;
                return (
                    <details {...attrs} open={expanded} onToggle={this.onGroupToggle}>
                        <summary className={className}>{content}</summary>
                    </details>
                );
            }
        }
        return (
            <div {...attrs} role="group">
                <div className={className}>{content}</div>
            </div>
        );
    };
    #itemContent(item) {
        const { template } = this.state;
        if (template) return $$.fn(template)(item);
        return (
            <>
                {item.icon && <span className={['icon', this.fontIcon(item.icon)]} aria-hidden="true" />}
                <div className="text-overflow">{item.text}</div>
            </>
        );
    }
    #renderSingle(item, args) {
        return (
            <>
                {this.#itemContent(item)}
                <input type="radio" className={['check-mark', CheckMarkIcon]} {...args} />
            </>
        );
    }
    #renderMultiple(item, args) {
        return (
            <>
                <input type="checkbox" className={CheckMarkIcon} {...args} />
                {this.#itemContent(item)}
            </>
        );
    }
    /** @alias #renderSingle|#renderMultiple */
    #renderItem = this.#renderSingle;
    renderItem = (item, args = {}) => {
        const { disabled, readonly } = this.options,
            attrs = { tabIndex: -1, ...args, role: 'option', checked: item.checked, disabled: disabled || item.disabled, readonly: readonly || null };
        attrs['aria-selected'] = attrs.checked;
        return (
            <label
                id={item.value}
                className="item"
                data-tooltip="ifneed"
                data-interactive="focusable"
                data-disabled={disabled || item.disabled}
                data-readonly={readonly || null}
                data-group={item.group || null}
            >
                {this.#renderItem(item, attrs)}
            </label>
        );
    };
    dataRender = utils.dataRender(this.renderItem, this.renderGroup);
    render() {
        const { options, state } = this,
            { disabled, readonly, minHeight, maxHeight, searchMinChars, searchPlaceholder } = options,
            { excludeChecked, isMultiple, isInfinityData, searchKey } = state;
        const searched = searchKey.length > 0,
            aria = this.arias({ label: isMultiple ? I18N.multipleList : I18N.singleList, 'aria-multiselectable': isMultiple, disabled, readonly });
        return (
            <div className="selection" role="group" style={{ minHeight, maxHeight }}>
                <div className="top empty-hidden">
                    {state.hasSearch && <aui-searchbox block sync placeholder={searchPlaceholder} disabled={disabled} value={searchKey} onSearch={this.onSearch} />}
                </div>
                <div className="box">
                    <header className="empty-hidden">
                        {state.hasSelectAll && !isInfinityData && (
                            <aui-checkbox-lite
                                id="select-all"
                                className="item"
                                block
                                checked={state.selectAllChecked}
                                disabled={disabled || state.selectAllDisabled}
                                readonly={readonly}
                                willChange={this.willSelectAllChange}
                            >
                                <div slot="inline-end">{searched ? options.selectAllSearchText : options.selectAllText}</div>
                            </aui-checkbox-lite>
                        )}
                    </header>
                    <aui-tabloop id="scroll-box" className={[excludeChecked && 'exclude-checked']} {...TabloopArgs}>
                        <aui-lazyload
                            id="lazyload"
                            role="listbox"
                            {...aria}
                            loopLoad
                            autoLoad
                            offsetEnd={10}
                            disabled={state.lazyLoadDisabled || disabled}
                            doLoad={isInfinityData ? this.doLazyLoad : this.doLazyRender}
                        >
                            {this.dataRender(state)}
                        </aui-lazyload>
                    </aui-tabloop>
                    <div className="message">{utils.noneMessage(searchKey, searchMinChars, options)}</div>
                    <footer className="empty-hidden">
                        {state.hasCreateNew && (
                            <aui-button-lite
                                id="create-new"
                                type="bald"
                                classify="theme"
                                block
                                align="start"
                                weight="regular"
                                disabled={disabled || readonly}
                                hidden={state.createNewBySearch && (state.hasExactMatch || !searched)}
                                onClick={this.onCreateNew}
                            >
                                <div slot="icon" className={this.fontIcon('faui-plus-solid')} />
                                <div slot="text">{stringFormat(state.createNewText, searchKey)}</div>
                            </aui-button-lite>
                        )}
                    </footer>
                    {isInfinityData && <aui-loading id="loading" />}
                </div>
            </div>
        );
    }
}
