import React, { PureComponent, createRef, Children, cloneElement } from 'react';

import { WR } from '../../widget/widget.jsx';

export class Splitter extends PureComponent {
    ref = createRef();
    resizeTo(numA, numB) {
        this.ref.current.method('resizeTo', numA, numB);
    }
    render() {
        return (
            <WR.Splitter {...this.props} ref={this.ref}>
                {Children.map(this.props.children, (child, index) => cloneElement(child, { slot: index ? 'b' : 'a' }))}
            </WR.Splitter>
        );
    }
}

$$.shell.define('Splitter', Splitter);
