import { config } from '../base/config.js';
import { omit } from '../base/log.js';
import { onloading } from '../base/onload.js';

import * as Attribute from './attribute.js';
import * as Box from './box.js';
import * as DomOperating from './dom-operating.js';
import * as DomTraversal from './dom-traversal.js';
import { AuiElement, AuiElementEntry } from './element.js';
import * as EventUtil from './event.js';
import { isElement } from './parse.js';

const { GetEvent, ...Events } = EventUtil;
// return {NaN} for a falsy value meaning (except false), such as NotFound/Abort etc.
const methods = { ...Attribute, ...Box, ...DomOperating, ...DomTraversal, ...Events };

for (const k in methods) {
    const fn = methods[k];
    AuiElement.prototype[k] = function (...args) {
        const source = this.toArray();
        let hasResult = false,
            _isElement = true;
        let results = source.flatMap(function (el) {
            const result = fn.apply(el, args);
            if (result === undefined) return [];
            hasResult = true;
            if (result != null && _isElement) {
                if (Array.isArray(result)) {
                    const first = result[0];
                    if (first) _isElement = isElement(first);
                } else {
                    _isElement = isElement(result);
                }
            }
            return result;
        });
        if (!hasResult) results = this;
        return (k === 'is' || !_isElement ? results[0] : AuiElementEntry(results)) ?? null;
    };
}

Object.assign(AuiElementEntry, {
    $root: new AuiElement(config.root),
    $body: new AuiElement(config.body),
    $activeElement: () => new AuiElement(getActiveElement(document)),
    is(element, query) {
        return !!DomTraversal.is.call(element, query);
    },
    parse(html) {
        const t = document.createElement('template');
        t.setHTMLUnsafe(html ?? '');
        return new AuiElement(t.content.childNodes);
    },
    Event: GetEvent,
});
onloading(() => {
    if (!AuiElementEntry.$body.length) AuiElementEntry.$body.set(config.body);
});
function getActiveElement(context) {
    const node = context.activeElement;
    if (!node) return null;
    if (node.shadowRoot) {
        return getActiveElement(node.shadowRoot);
    } else if (node.localName === 'iframe') {
        const doc = node.contentDocument;
        if (doc) return getActiveElement(doc);
        omit('Get frame content failed.');
        return node;
    } else {
        return node;
    }
}

// main util
Object.assign($$, {
    $: AuiElementEntry,
});

export default AuiElementEntry;
