/** @type {typeof $$.cookie.set} */
export default function set(key, value, options) {
    if (!key || /^(?:expires|max\-age|path|secure)$/i.test(key)) return false;
    if (!options) options = {};
    let cookie = encodeURIComponent(key) + '=' + encodeURIComponent(value),
        expires = '';
    if (options.expires) {
        switch ($$.getClassBuiltIn(options.expires)) {
            case Number:
                expires = options.expires === Infinity ? '; expires=Fri, 31 Dec 9999 23:59:59 GMT' : '; max-age=' + options.expires;
                break;
            case String:
                expires = '; expires=' + options.expires;
                break;
            case Date:
                expires = '; expires=' + options.expires.toUTCString();
                break;
        }
    }

    if (expires) cookie += expires;
    if (options.path) cookie += ';path=' + options.path;
    if (options.secure) cookie += ';secure=' + options.secure;

    document.cookie = cookie;

    return true;
}
