import { RegUploadPlugin } from '../module/upload.plugin.js';

RegUploadPlugin('Audio', (UploadButton, I18N) => {
    return class AudioSplitButton extends UploadButton {
        icon = true;
        internal = true;
        type = 'Audio';
        name = I18N.audioTag;
        tooltip = [I18N.audioTag];

        menuMapping(item) {
            return { ...item, icon: this.icon };
        }
    };
});
