import { I18N } from '../../core/base/i18n.js';
import { error } from '../../core/base/log.js';

const Formats = {
    defaultFormat: I18N.core.defaultDateTime,
    defaultDate: I18N.core.defaultDate,
    defaultYearMonth: I18N.core.defaultYearMonth,
    defaultMonthDay: I18N.core.defaultMonthDay,
    defaultTime: I18N.core.default24Time,
    defaultTime12: I18N.core.defaultTime,
};

const checkTimeFormat = (f) => (f.includes('tt') ? f.includes('H') : f.includes('h')) && error(`Time format irrational`, `The hour format doesn't match the dayPeriod.`);
/** @type {typeof $$.date.defaultFormat} */
export function defaultFormat(date, time, dateTime) {
    let change = false;
    if (date && typeof date === 'string') {
        Formats.defaultDate = date;
        change = true;
    }
    if (time && typeof time === 'string') {
        checkTimeFormat(time);
        Formats.defaultTime = time;
        change = true;
    }
    if (dateTime && typeof dateTime === 'string') {
        checkTimeFormat(dateTime);
        Formats.defaultFormat = dateTime;
    } else if (change) {
        Formats.defaultFormat = Formats.defaultDate + ' ' + Formats.defaultTime;
    }
}

/** @type {typeof $$.date.getFormat} */
export function getFormat() {
    return Formats.defaultFormat;
}

/** @type {typeof $$.date.getDateFormat} */
export function getDateFormat() {
    return Formats.defaultDate;
}

/** @type {typeof $$.date.getYearMonthFormat} */
export function getYearMonthFormat() {
    return Formats.defaultYearMonth;
}

/** @type {typeof $$.date.getMonthDayFormat} */
export function getMonthDayFormat() {
    return Formats.defaultMonthDay;
}

/** @type {typeof $$.date.getTimeFormat} */
export function getTimeFormat() {
    return Formats.defaultTime;
}

/** @type {typeof $$.date.isHour12} */
export function isHour12(format) {
    return String(format ?? Formats.defaultTime).includes('tt');
}
