/** @jsxImportSource @gui/aui-devops */
import { addTooltip } from '../../core/module/tooltip.js';
import { define, Widget, Types } from '../../widget/widget.js';

import length from '../../util/css/length.js';
import { keyNamePure } from '../../util/event/key-name.js';
import { keyPress } from '../../util/event/key-press.js';

import style from './style.less';

const I18N = $$.I18N.searchbox;

/** @extends {Widget<typeof Searchbox.options>} */
@define('searchbox')
export class Searchbox extends Widget {
    static options = {
        block: false,
        disabled: false,
        height: Types.Length,
        multiple: false,
        placeholder: Types.string,
        round: false,
        size: Types.Enum(['m', 'l'], 'm'),
        sync: false,
        tooltip: Types.string,
        value: Types.string,
        width: Types.Length,
        onEnter: Types.function,
        onSearch: Types.function,
    };
    static observers = ['disabled', 'placeholder', 'value'];
    static upcasts = ['size'];
    static shadow = { delegatesFocus: true, referenceTarget: 'input' };
    static formAssociated = true;
    static styles = style;
    static ariaTarget = '#input';

    #compositionIME = false;
    create() {
        this.method = {
            clear: () => {
                this.setValue(null, false);
            },
            getValue: (live) => {
                return live ? this.state.value : this.state.searchKey;
            },
            setValue: (value) => this.setValue(value),
        };
    }
    init() {
        const { multiple, sync, value, height, width } = this.options;
        this.state = {
            canSearch: !value, // Whether the icon is "faui-search".
            isSearching: !!value, // Whether in the searched state (currently searching, but maybe can search again).
            enterKeyHint: 'search',
            searchKey: value ?? '', // current searched text.
            sync: !multiple && sync,
            value: value ?? '', // current input text.
            height: length(height),
            width: length(width),
        };
        if (this.state.sync) this.state.enterKeyHint = 'enter';
        if (multiple) this.toggleScrollbar = this.#toggleScrollbar;
    }
    didMount() {
        addTooltip(this.host);

        this.input = this.shadowRoot.querySelector('.input');
        this.button = this.shadowRoot.querySelector('.button');

        keyPress(this.element, ['Escape', 'Enter'], '.input', this.onKeyPress, { strict: false });
        if (this.options.sync) {
            this.shadowRoot.addEventListener('compositionstart', (e) => {
                this.#compositionIME = true;
            });
            this.shadowRoot.addEventListener('compositionend', (e) => {
                this.#compositionIME = false;
                this.onInput(e);
            });
        }
        this.toggleScrollbar();
    }
    didRender() {
        this.toggleScrollbar();
    }
    setOption(key, value) {
        if (key === 'value') {
            this.setValue(value);
            return false;
        }
    }

    toggleScrollbar() {}
    #toggleScrollbar() {
        if (this.input) this.element.style.setProperty('--has-scrollbar', $$.hasScroll(this.input).y ? 1 : 0);
    }

    setValue(value, isSearching) {
        let updateMode = null;
        if (isSearching == null) {
            updateMode = true;
            isSearching = !!value;
        }
        value = String(value ?? '').trim();
        this.setState({ searchKey: isSearching ? value : '', value, isSearching, canSearch: !isSearching }, updateMode);
        return value;
    }
    search() {
        const value = this.setValue(this.state.value, true);
        this.callback('onSearch', value);
    }
    stop() {
        this.setValue('', false);
        this.callback('onSearch', '');
    }

    onInput = (e) => {
        if (this.options.multiple) this.toggleScrollbar();

        const { sync, isSearching, searchKey } = this.state,
            { value } = e.target;
        if (sync) {
            if (this.#compositionIME === true || value === this.state.value) return;
            this.setState({ value }, false);
            return value ? this.search() : this.stop();
        } else {
            this.setState({ value }, false);
            if (isSearching) {
                const canSearch = value !== searchKey && !!value;
                this.setState({ canSearch }, true);
            }
        }
    };
    onKeyPress = (e, keyName) => {
        if (keyName === 'Escape') {
            if (!this.state.canSearch) {
                this.stop();
            } else if (!this.state.isSearching) {
                this.setState({ value: '' });
            }
        } else {
            const { searchKey, sync, value } = this.state,
                pureName = keyNamePure(keyName);
            // allow `Ctrl+Enter` in all mode, and `Enter` non-strict in single mode.
            if (pureName === 'Enter' && (e.controlKey || !this.options.multiple)) {
                if (this.state.canSearch) {
                    if (value) this.search();
                } else if (!value) {
                    this.stop();
                }
                if (sync && searchKey && !value) {
                    this.callback('onEnter', value, this.input);
                }
            }
        }
    };

    onClick = () => {
        if (this.state.canSearch) {
            if (this.state.value) this.search();
        } else {
            this.stop();
        }
    };

    render() {
        const { block, disabled, multiple, placeholder, round, tooltip } = this.options,
            { canSearch, enterKeyHint, isSearching, sync, value, height, width } = this.state;
        const inputArgs = {
            id: 'input',
            className: ['input', round && 'round'],
            disabled,
            placeholder,
            ...this.arias({ label: tooltip, busy: isSearching }),
            dataTooltip: tooltip ? true : 'ifneed',
            onInput: this.onInput,
        };
        const buttonArgs = canSearch ? { icon: 'faui-search', tooltip: I18N.searchAction } : { icon: 'faui-close', tooltip: I18N.clearSearch };

        return (
            <div part="box" className={['box', block && 'block']} style={{ height, width }}>
                {multiple ? (
                    <textarea autoComplete="on" role="searchbox" onBlur={this.#toggleScrollbar} onFocus={this.#toggleScrollbar} {...inputArgs}>
                        {value}
                    </textarea>
                ) : (
                    <input autoComplete="on" enterKeyHint={enterKeyHint} type="search" value={value} {...inputArgs} />
                )}
                <aui-button-lite className="button" disabled={disabled} readonly={sync} round={round} type="plain" {...buttonArgs} onClick={this.onClick} />
            </div>
        );
    }
}
