import React, { createRef, useImperativeHandle, forwardRef } from 'react';

import { warn, throws } from '../core/base/log.js';

import objectFilter from '../util/object/filter.js';
import objectForEach from '../util/object/for-each.js';

import customElementRegistry from './registry.js';

const ReactBuiltinProps = new Set(['propTypes', 'prototype', 'contextType', 'contextTypes', 'getDefaultProps', 'defaultProps', 'getDerivedStateFromProps', 'childContextTypes']);

function publicMethods(name, host) {
    const proto = Object.create(host, {
        [Symbol.toStringTag]: { value: name },
        element: { value: host },
        method: { value: host.method.bind(host) },
    });
    const result = Object.create(proto),
        { Widget: widget } = host._,
        methods = new Set();
    objectForEach(widget.method, (k, v) => {
        if (typeof v === 'function') {
            methods.add(k);
            result[k] = $$.fn(v, widget);
        }
    });
    if (!methods.has('focus')) Object.defineProperty(proto, 'focus', { value: host.focus.bind(host) });
    Object.freeze(proto);
    return Object.freeze(result);
}

export function filterProps(props, upcasts) {
    const attributes = ['id', 'hidden', 'itemscope', 'part', 'role', 'slot', 'tabIndex', 'title', 'style'];
    return objectFilter(props, attributes.concat(upcasts || []), true);
}

function forwardComponent(name, Tag, { Upcasts }) {
    function Component({ children, className, ...props }, ref) {
        const widgetRef = createRef();
        useImperativeHandle(ref, () => publicMethods(name, widgetRef.current), []);
        const [attrs, forwardProps] = filterProps(props, Upcasts);
        if (className) attrs.class = className; // Not sure using class or className, keep class logic as before for now.
        return (
            <Tag {...attrs} ref={widgetRef} props={forwardProps}>
                {children}
            </Tag>
        );
    }
    const displayName = 'WR.' + name;
    const value = forwardRef(Object.defineProperty(Component, 'name', { value: displayName }));
    Object.assign(value, { displayName, defaultProps: {} });
    return value;
}

const Cache = Object.create(null);
function getComponent(name) {
    let tag = name.replaceAll(/([A-Z])/g, '-$1').toLowerCase();
    if (tag[0] === '-') tag = tag.slice(1);
    if (!tag.startsWith('aui-')) tag = 'aui-' + tag;

    const constructor = customElementRegistry.get(tag);
    if (!constructor) return warn('[Widget] Using undefined component: ', name);

    if (!Object.hasOwn(Cache, tag)) Cache[tag] = forwardComponent(name, tag, constructor);
    return Cache[tag];
}

export const WR = new Proxy(Cache, {
    get: function (target, prop, receiver) {
        switch (prop) {
            case 'displayName':
                return target.name;
            case 'toString':
                return () => 'Proxy';
        }
        if (!prop || ReactBuiltinProps.has(prop)) return undefined;
        return getComponent(prop);
    },
});
if (!window.WR) window.WR = WR;

function I18N(props) {
    const Tag = WR['i18n'],
        { children, ...args } = props,
        { flatArray, isValidElement } = $$.shell;
    return (
        <Tag {...args}>
            {flatArray(children, (child, i) => {
                if (isValidElement(child)) return child.props.slot == null ? { slot: String(i) } : child;
                return throws('Not supported child node of I18N: ', child);
            })}
        </Tag>
    );
}

queueMicrotask(function () {
    $$.shell.define('I18N', I18N, { pure: true });
});
