import { parseValue } from './hash-util.js';

/** @param {string} value @param {2|8|10|16|36} [radix=36] */
export default function hash53(value, radix = 36) {
    const str = parseValue(value);
    const seed = Number.isSafeInteger(this) ? this : 0; // Future api: allow seed as this
    let h1 = 0xdeadbeef ^ seed;
    let h2 = 0x41c6ce57 ^ seed;

    for (let i = 0; i < str.length; i++) {
        const ch = str.codePointAt(i);
        h1 = Math.imul(h1 ^ ch, 2654435761);
        h2 = Math.imul(h2 ^ ch, 1597334677);
    }

    h1 = Math.imul(h1 ^ (h1 >>> 16), 2246822507) ^ Math.imul(h2 ^ (h2 >>> 13), 3266489909);
    h2 = Math.imul(h2 ^ (h2 >>> 16), 2246822507) ^ Math.imul(h1 ^ (h1 >>> 13), 3266489909);

    const result = (h2 >>> 0) * 0x100000000 + (h1 >>> 0);
    return result.toString(radix);
}
