import { error } from '../base/log.js';

import isLike from '../../util/array/is-like.js';

const indexable = (v) => Array.isArray(v) || v instanceof HTMLCollection || v instanceof NodeList || Object.prototype.toString.call(v) === '[object Arguments]';

const validNode = (v) => {
    if (v == null || v === false || v === '') return false;
    if (Error.isError(v)) return error('Unexpected error child node!', v);
    return true;
};

function appendNodes(result, value) {
    if (indexable(value)) {
        const l = value.length;
        for (let i = 0; i < l; i++) {
            appendNodes(result, value[i]);
        }
    } else if (isLike(value)) {
        for (const node of value) {
            appendNodes(result, node);
        }
    } else if (validNode(value)) {
        result.push(value);
    }
}

/**
 * filter, flat and return valid node list.
 * @param {Element | Array<Element>} value
 * @returns {Array<Element>}
 */
export default function nodeList(value) {
    if (!validNode(value)) return [];
    if (value.nodeType === Node.DOCUMENT_NODE) return Array.from(value.body.childNodes);
    if (value.nodeType === Node.DOCUMENT_FRAGMENT_NODE) return Array.from(value.childNodes);

    const result = [];
    appendNodes(result, value);
    return result;
}
