/**
 * @description Get jQuery objects' width.
 * @param $Objects {Array:jQuery object}
 * @param isIncludeMargin {boolean}
 * @param isHandleHiddenObject {boolean}
 * @returns {Array:number} objectsWidth
 */
export function getObjectsWidth($Objects, isIncludeMargin = false, isHandleHiddenObject = true, gap = 0) {
    const objectsWidth = [];

    for (let i = 0; i < $Objects.length; i++) {
        const $object = $Objects.eq(i),
            objectWidth = $object.outerWidth(isIncludeMargin);

        if ($object.is(':visible')) {
            objectsWidth.push(i === 0 ? objectWidth : objectWidth + gap);
        } else {
            if (isHandleHiddenObject) {
                objectsWidth.push(0);
            } else {
                $object.css({ display: 'block', position: 'absolute', 'z-index': '-999999' });
                objectsWidth.push(objectWidth);
            }
        }
    }

    return objectsWidth;
}
/**
 * @description Calc overflow index
 * @param maxSum {number}
 * @param values {Array:number}
 * @param isReverseCalculation {boolean}
 * @returns {number}
 */
export function calcOverflowIndex(maxSum, values, isReverseCalculation = false) {
    let i, step;
    if (isReverseCalculation) {
        i = values.length - 1;
        step = -1;
    } else {
        i = 0;
        step = 1;
    }

    let sum = 0;
    for (let index = i; index >= 0 && index < values.length; index += step) {
        sum += values[index];

        if (sum > maxSum) {
            return index;
        }
    }
}
