/** @type {typeof $$.string.htmlDecode} */
export default function htmlDecode(val) {
    const List = { '&lt;': '<', '&gt;': '>', '&amp;': '&', '&#34;': `"`, '&quot;': `"`, '&#39;': `'`, '%backtick;': '`' };
    let regStr = '(' + Object.keys(List).toString() + ')';
    regStr = regStr.replaceAll(',', ')|(');
    return val.replaceAll(new RegExp(regStr, 'g'), (match) => List[match]);
}
