import $ from '../../core/element/index.js';

import isKey from './is-key.js';
import origin from './origin.js';

/** @type {typeof $$.event.combineKeydown} */
export default function combineKeydown(keyName, callback, stopPropagation, preventDefault) {
    let timeout;
    const delay = 100,
        firstDelay = 500;
    return function (e) {
        if (isKey(e, keyName)) {
            if (stopPropagation) e.stopPropagation();
            if (preventDefault) e.preventDefault();
            e = $.Event(origin(e));
            if (!timeout) {
                $(e).on('keyup', { once: true }, function () {
                    clearTimeout(timeout);
                    timeout = undefined;
                    callback(e);
                });
            }
            clearTimeout(timeout);
            timeout = setTimeout(
                function () {
                    callback(e);
                    timeout = undefined;
                },
                timeout ? delay : firstDelay
            );
        }
    };
}
