import forEach from './for-each.js';

/** @type {typeof $$.object.extendIfneed} */
export default function extendIfneed(target, ...sources) {
    for (const obj of sources) {
        if (!obj) continue;
        forEach(obj, function (k, v) {
            if (v != null) target[k] = v;
        });
    }
    return target;
}
