/** @jsxImportSource @gui/aui-devops */
import { addTooltip, tooltipAttr } from '../../core/module/tooltip.js';
import { define, Widget, Types } from '../../widget/widget.js';

import './group.js';
import * as identity from './avatar.identity.js';

import style from './style.less';

const Sizes = ['stretch', 'xs', 's', 'm', 'l', 'xl'];

/** @extends {Widget<typeof Avatar.options>} */
@define('avatar')
export class Avatar extends Widget {
    static options = {
        name: Types.string,
        size: Types.Enum(Sizes),
        shape: Types.Enum(['circle', 'square', 'rect'], 'circle'),
        radius: Types.Enum([0, 'round', 'm', 'l', 'xl']),
        status: Types.Enum(['invalid', 'unknown']),
        avatar: Types.string,
        placeholder: 'faui-user-solid',
        tooltip: Types.Union([Types.string, Types.boolean]),
        icon: Types.string,
    };
    static styles = style;
    static observers = ['name', 'size', 'avatar', 'status', 'placeholder', 'tooltip', 'icon'];
    static upcasts = ['name', 'size', 'shape', 'radius'];
    static requires = ['name'];

    instanceOptions = () => ({ size: Types.Enum(Sizes, 's') });
    didMount() {
        addTooltip(this.host);
    }

    content(status, avatar, name) {
        if (status) return <div className={['status', status]} />;
        if (avatar) return <img role="none" alt="" src={avatar} crossOrigin="anonymous" />;

        const content = identity.name(name);
        return content?.length ? <span className="identity">{content}</span> : <span className={['user', this.fontIcon(this.options.placeholder)]} />;
    }
    render() {
        const { name, avatar, status, tooltip, icon } = this.options,
            className = ['avatar', !name && 'placeholder'],
            role = name || avatar ? 'img' : null,
            arias = tooltipAttr(!status && tooltip, role ? 'label' : 'description'),
            color = status || avatar ? null : identity.color(name);

        return (
            <div className="box">
                <div className={className} role={role} aria-label={name} {...arias} style={{ backgroundColor: color }}>
                    {this.content(status, avatar, name)}
                    {icon && <div className={['icon', this.fontIcon(icon, true)]} />}
                </div>
            </div>
        );
    }
}
