/** @jsxImportSource @gui/aui-devops */
import { define, Widget, Types } from '../../../widget/widget.js';

import clamp from '../../../util/number/clamp.js';
import { percent } from '../../../util/number/percent.js';

import { NS } from './utils.js';

/** @extends {Widget<typeof Reference.options>} */
@define(`${NS}-reference`)
export class Reference extends Widget {
    static options = {
        name: Types.string,
        dimension: Types.Enum(['start', 'end', 'nested'], 'start'),

        value: Types.Union([Types.number, Types.array]),
        series: Types.Union([Types.string, Types.array]),

        color: Types.Color,
        header: Types.string,

        type: Types.Enum(['solid', 'dashed'], 'solid'),
        fillOpacity: 0.2,
    };
    static observers = ['value', 'series', 'color', 'header', 'type', 'fillOpacity'];
    static styles = `:host{display:none}`;
    static ownContents = false;

    #setData(data) {
        this.dispatcher(this.state.source, 'setReference', data);
    }
    init() {
        const { name, dimension } = this.options;
        let _name = 'reference';
        if (name) _name += ':' + name;
        this.state = { name: _name, source: 'grid:' + dimension };
        this.dispatcher = this.useUnicom(['box', _name], this.dataReceiver);
    }
    dataReceiver = (action, from, ...args) => {
        $$.fn(this[action], this)(from, ...args);
    };
    didRender() {
        const { value, series, color, header, type, fillOpacity } = this.options,
            opacity = clamp(0, fillOpacity, 1);
        this.#setData({ value, series, color, header, type, fillOpacity: opacity ? percent(opacity) : null });
    }
    didUnmount() {
        this.#setData(null);
    }
}
