/** @type {typeof $$.type.isInteger} */
export function isInteger(value) {
    // int MaxValue = 2147483647;
    return String(value).length <= 10 && Math.floor(value) === value - 0;
}

/** @type {typeof $$.type.isFloat} */
export function isFloat(value) {
    return String(value).length <= 15 && Number.parseFloat(value) === value - 0;
}

/** @type {typeof $$.type.isNegative} */
export function isNegative(value) {
    return value < 0;
}

/** @type {typeof $$.type.isPositive} */
export function isPositive(value) {
    return value > 0;
}

/** @type {typeof $$.type.isNegativeInteger} */
export function isNegativeInteger(value) {
    return /-[1-9]\d*$/.test(value);
}

/** @type {typeof $$.type.isPositiveInteger} */
export function isPositiveInteger(value) {
    return /^[1-9]\d*$/.test(value);
}

/** @type {typeof $$.type.isNonnegativeInteger} */
export function isNonnegativeInteger(value) {
    return /^([1-9]\d*|0)$/.test(value);
}

/** @type {typeof $$.type.isNonpositiveInteger} */
export function isNonpositiveInteger(value) {
    return /^(-[1-9]\d*|0)$/.test(value);
}

/** @type {typeof $$.type.isEmail} */
export function isEmail(value) {
    return /^\w+([-+.]\w+)*@\w+([-.]\w+)*\.\w+([-.]\w+)*$/.test(value);
}

/** @type {typeof $$.type.isFilePath} */
export function isFilePath(value) {
    return /^[a-zA-Z]:(?:(?:\\(?!\s)[^\\/:*?"<>|\x00-\x1F]+)+\\?|\\?)(?<!\s)$/.test(value);
}

/** @type {typeof $$.type.isLetters} */
export function isLetters(value) {
    return /^[A-Za-z]+$/.test(value);
}

/** @type {typeof $$.type.isSpecialCharacters} */
export function isSpecialCharacters(value) {
    return /[@*+=<>?:",|/;'[\]\\]/im.test(value);
}

/** @type {typeof $$.type.isUNCPath} */
export function isUNCPath(value) {
    return /\\\\[\w.-]+\\[^\\?<>*:|/]+/.test(value);
}

/** @type {typeof $$.type.isUrl} */
export function isUrl(value) {
    return /^(ht|f)tp(s?):\/\/[^\s]+$/.test(value);
}

/** @type {typeof $$.type.isUserName} */
export function isUserName(value) {
    return isEmail(value) || /^[a-z][a-z0-9-_]*$/im.test(value);
}

/** @type {typeof $$.type.hasDigit} */
export function hasDigit(value) {
    return /\d+/.test(value);
}

/** @type {typeof $$.type.hasLetters} */
export function hasLetters(value) {
    return /[A-Za-z]+/.test(value);
}

/** @type {typeof $$.type.hasSpecialCharacters} */
export function hasSpecialCharacters(value) {
    return /[\~\!\@\#\$\%\^\&\*\(\)\-\_\+\=\[\]\{\}\|\\\:\;\"\'\<\,\>\.\?\/]+/.test(value);
}
