import $ from '../../core/element/index.js';

import isKey from './is-key.js';
import { keyName } from './key-name.js';

/** @type {typeof $$.event.keyPressProps} */
export function keyPressProps(key, callback, options = {}) {
    const { preventDefault = true, stopPropagation, strict = true, onKeyDown } = options;
    let active = false,
        lastKey = null;

    return {
        onKeyDown(e) {
            lastKey = keyName(e);
            active = isKey(lastKey, key, strict);
            if (active) {
                if (preventDefault) e.preventDefault();
                if (stopPropagation) e.stopPropagation();
                if (onKeyDown) onKeyDown(e);
            }
        },
        onKeyUp(e) {
            if (active) {
                const key = keyName(e);
                if (key === lastKey) {
                    if (preventDefault) e.preventDefault();
                    if (stopPropagation) e.stopPropagation();
                    callback(e, key);
                }
            }
            active = false;
            lastKey = null;
        },
    };
}

/** @type {typeof $$.event.keyPress} */
export function keyPress(element, key, selector, callback, options) {
    const { onKeyDown, onKeyUp } = keyPressProps(key, callback, options);
    $(element).on('keydown', selector, onKeyDown);
    $(element).on('keyup', selector, onKeyUp);
}
