/* eslint-disable aui/require-autocomplete */
import { Types, Widget } from '../../widget/widget.js';

import { isEqual } from '../../util/value-path.js';

const CommonOptions = {
    name: Types.string,
    disabled: false,
    readonly: false,
    separate: false,
    solid: false, /// TD radio ↓
    onChange: Types.function,
};
export const ItemOptions = {
    ...CommonOptions,
    text: Types.Content,
    value: Types.Union([Types.string, Types.number, Types.boolean]),
    checked: Types.boolean,
    classify: Types.Classify(true, null), // ↑
    tooltip: Types.string,
};
export const ItemObservers = ['name', 'text', 'value', 'checked', 'disabled', 'readonly', 'separate', 'tooltip'];

export const GroupOptions = {
    ...CommonOptions,
    block: false,
    items: Types.array,
};
export const GroupObservers = ['name', 'disabled', 'readonly', 'items', 'separate'];

export const ClassName = {
    Choice: 'aui-choice',
    Input: 'aui-choice-input',
    Content: 'aui-choice-content empty-hidden',
    Solid: 'aui-choice-input-solid',
    Inline: 'aui-choice-inline',
    Classify: 'aui-choice-input-classify',
};

export function Render(type, instance, onChange) {
    const { options, state } = instance,
        { disabled, readonly, tooltip, solid, value, name, text, classify, separate, dirty } = options,
        { checked } = state;
    const labelAttrs = {
        class: ['aui-' + type, ClassName.Choice],
        tabindex: -1,
        dataTooltip: 'diffneed',
        ariaLabel: tooltip,
        separate,
    };
    const attrs = {
        type: type,
        value,
        name,
        checked: !!checked,
        readonly: readonly || null,
        disabled: disabled || readonly,
        classify,
        'data-dirty': dirty,
        ...instance.arias({ ariaChecked: checked || false, ariaDisabled: disabled }),
    };
    attrs.class = [ClassName.Input, solid && ClassName.Solid, classify && ClassName.Classify];
    return (
        <label {...labelAttrs} onChange={onChange}>
            <input {...attrs} />
            <span className={ClassName.Content}>{text}</span>
        </label>
    );
}

export class Group extends Widget {
    init() {
        this.state = { items: this.options.items };
        this.method = { getValue: this.getValue };
    }
    didMount() {
        this.oldValue = this.getValue();
    }
    setOption(name, value) {
        if (name === 'items' && !isEqual(value, this.state.items)) {
            this.state.items = value;
            this.oldValue = this.getValue();
        }
    }
    onChange() {}
    getValue() {}

    render(Tag, groupArgs) {
        const { name, separate, disabled, readonly, solid, aria } = this.options,
            _name = name || `choice-group-${this.uuid}`,
            arias = this.arias(aria),
            itemArias = {};
        if (arias['aria-required'] === 'true') itemArias['aria-required'] = 'true';
        Reflect.deleteProperty(arias, 'aria-required');
        return (
            <div className="aui-choice-group" {...groupArgs} data-dirty={this.state.dirty} {...arias}>
                {this.state.items.map((item) => {
                    const args = {
                        ...item,
                        separate,
                        solid,
                        name: _name,
                        checked: item.checked ?? false,
                        disabled: disabled || item.disabled || false,
                        readonly: readonly || item.readonly || false,
                    };
                    return <Tag {...args} aria={itemArias} _inGroup onChange={this.onChange} />;
                })}
            </div>
        );
    }
}
