// don't need scroll to element in most cases.
if ($$.browser.touchable) {
    const focus = HTMLElement.prototype.focus;
    /**
     * - https://bugs.webkit.org/show_bug.cgi?id=247416
     * - ~~https://bugs.webkit.org/show_bug.cgi?id=278019~~ : 27(TP/243)
     * - https://bugs.webkit.org/show_bug.cgi?id=281995
     */
    const args = $$.browser.name === 'safari' ? { focusVisible: false } : {};
    HTMLElement.prototype.focus = function (options) {
        if (options == null) {
            options = { preventScroll: true, ...args };
        } else if (typeof options === 'object') {
            options = { ...options, ...args };
            if (options.preventScroll == null) options.preventScroll = true;
        }
        focus.call(this, options);
    };
}
