import fixFloat from '../../../util/number/fix-float.js';
import format from '../../../util/string/format.js';

/** Widget namespace name. */
export const NS = 'charts';

/** Predefined color list with sorted. */
export const DefaultColors = [
    '#6DA2F6', // Blue-havelock
    '#58D6CD', // Teal-persian
    '#AC6BE6', // Purple-lilac
    '#E63D2E', // Red-error
    '#28CC74', // Green-success
    '#2C8BFF', // Blue-sky
    '#FF763E', // Orange
    '#CF2984', // Red-magenta
    '#7D848B', // Gray-silver
    '#E6E7E8', // Neutrals-02
    '#F7A100', // Yellow-warning
];
/** Create color array by optional color option. */
export const Colors = (value) => {
    if (Array.isArray(value)) return value;
    if (value && typeof value === 'string') return [value];
    return DefaultColors;
};

export const TooltipClassName = {
    Stack: 'tooltip-stack',
    Item: 'tooltip-item',
    /** The of element for tooltip when focus. */
    FocusTarget: 'focus-target',
};

/** Common tabloop options. */
export const TabloopArgs = { tabMode: false, arrowMode: 'all', arrowFlipPrevent: true, query: 'focusable' };

/** Swapped orient value. */
export const OrientSwap = { h: 'v', v: 'h' };

/**
 * Actions associate with other modules; or common actions.
 * @param {AuiElement} $context Widget instance $element.
 * @param {string} key Associated key name.
 */
export const Action = ($context, key) => {
    return {
        /** Highlight focus element. */
        focus(name) {
            const $targets = $context.findAll(`.item[data-${key}="${name}"]`);
            $targets.addClass('focus');
        },
        /** Undo the focus highlight. */
        blur() {
            $context.findAll('.item.focus').removeClass('focus');
        },
    };
};

/** Format value with formatter option to display. */
export const Format = (formatter) => {
    const fn = (v) => format(formatter || '{0}', v);
    return (v) => (Array.isArray(v) ? v.map(fn).join(' ~ ') : fn(v));
};
/** Transform from Plane-CoordinateSystem to CSS-CoordinateSystem. */
export const CoordPlane2CSS = ([x, y], R = 0) => [fixFloat(y + R), fixFloat(R - x)];
/** Set toStringTag value. */
export const TagObject = (tag, v) => {
    const proto = Object.create(null, { [Symbol.toStringTag]: { value: tag } });
    return Object.assign(Object.create(proto), v);
};
