/** @jsxImportSource @gui/aui-devops */
import { define, Widget, Types } from '../../widget/widget.js';

import cssGetValue from '../../util/css/get-value.js';
import imgCssBase64Value from '../../util/img/css-base64-value.js';
import img2base64 from '../../util/img/img2base64.js';
import svg2base64Png from '../../util/img/svg2base64-png.js';
import { isUrl as typeIsUrl } from '../../util/type/verify.js';

import '../ellipsis/ellipsis.js';
import { normalizeContent } from '../editor/method.js';
import { htmlPurify } from '../htmlpurify/purify.js';

import style from './style.less';

/** @extends {Widget<typeof EditorEcho.options>} */
@define('editor-echo')
export class EditorEcho extends Widget {
    static options = {
        autoTag: false,
        ellipsis: false,
        mode: Types.Enum(['default', 'print']).value('default'),
        overflow: Types.Enum(['limitWidth', 'scroll', 'visible']).value('scroll'),
        purifyConfig: {}, // SAGCC
        row: 3,
        tooltip: Types.Union([Types.boolean, Types.string]).value(''),
        value: '',
    };
    static observers = ['ellipsis', 'value'];
    static upcasts = ['overflow'];
    static styles = style;

    didRender() {
        const { mode, value } = this.options;
        // eslint-disable-next-line aui/inner-html
        this.host.innerHTML = this.purify(value);

        normalizeContent(this.host, 'echo');

        if (mode === 'print' && value) {
            setTimeout(() => {
                this.convertContent();
            }, 200);
        }
    }

    convertContent() {
        /**
         * 1. picture math music convert to base64
         * 2. table wrap table
         * 3. audio / video convert link with image
         * 4. file change url with origin
         */
        return new Promise((resolve) => {
            const { host } = this;

            for (const element of host.querySelectorAll('[data-cke-widget-data]')) {
                element.removeAttribute('data-cke-widget-data');
            }

            for (const img of host.querySelectorAll('img')) {
                if (!img.getAttribute('src').includes('data:image/png;base64')) {
                    this.convertImgToBase64(img);
                }
            }

            for (const table of host.querySelectorAll('table')) {
                this.wrapTable(table);
            }

            for (const file of host.querySelectorAll('a[data-type="RichEditorAttachment"]')) {
                this.converterFileHref(file);
            }

            const audios = host.querySelectorAll('audio');
            const svgs = host.querySelectorAll('svg');
            const videos = host.querySelectorAll('video');

            if (audios.length > 0 || svgs.length > 0 || videos.length > 0) {
                const height = Number.parseFloat(cssGetValue('font-size')) * 2;
                const promises = [svg2base64Png(imgCssBase64Value('fi-file-audio'), [height, height]), svg2base64Png(imgCssBase64Value('fi-file-video'), [height, height])];

                for (const svg of svgs) {
                    const width = Math.ceil(Number.parseFloat(cssGetValue('width', svg))),
                        height = Math.ceil(Number.parseFloat(cssGetValue('height', svg)));
                    promises.push(svg2base64Png(svg, [width, height]));
                }

                Promise.all(promises).then((callback) => {
                    for (const audio of audios) {
                        this.convertMediaToLink(audio, callback[0]);
                    }

                    for (const video of videos) {
                        this.convertMediaToLink(video, callback[1]);
                    }

                    for (const [index, svg] of svgs.entries()) {
                        const src = callback[index + 2];

                        if (src) {
                            this.convertSvgToBase64(svg, src);
                        }
                    }

                    resolve();
                });
            } else {
                resolve();
            }
        });
    }

    convertImgToBase64(img) {
        img2base64(img, function (base64) {
            if (base64) {
                img.src = base64;
                img.setAttribute('data-base64', 'true');
            }
        });
    }

    wrapTable(table) {
        const { body } = Document.parseHTMLUnsafe('<table class="aui-richeditor-inner-table" style="width:100%"><tbody><tr><td></td></tr></tbody></table>');
        const wrapper = body.querySelector('table');
        const td = body.querySelector('td');

        // eslint-disable-next-line aui/inner-html
        td.innerHTML = table.outerHTML;

        table.replaceWith(wrapper);
    }

    converterFileHref(file) {
        const href = file.getAttribute('href');

        file.setAttribute('href', this.getFileUrl(href));
    }

    getFileUrl(href) {
        return typeIsUrl(href) ? href : window.location.origin + href;
    }

    convertMediaToLink(media, callback) {
        const sources = [];

        for (const source of media.querySelectorAll('source')) {
            sources.push(source.getAttribute('src'));
        }

        if (sources.length >= 1) {
            const a = document.createElement('a');
            a.setAttribute('target', '_blank');
            a.setAttribute('rel', 'noopener noreferrer');
            a.setAttribute('href', this.getFileUrl(sources[0]));
            a.style.display = 'inline-block';

            const img = document.createElement('img');
            img.setAttribute('src', callback);

            a.append(img);

            media.replaceWith(a);
        } else {
            media.replaceWith('');
        }
    }

    convertSvgToBase64(svg, src) {
        const wrapper = svg.closest('.cke_widget_wrapper, .plugin_part_wrapper');
        const element = wrapper.querySelector('.cke_widget_element, .plugin_part_element');
        const widget = element.getAttribute('data-widget') || element.getAttribute('data-name').toLowerCase();
        const img = new Image();

        img.className = 'cke_widget_' + widget;
        img.src = src.toString();

        if (widget === 'math') {
            // Calculate height of 'X' based on baseline.
            const height = src.height;
            const fontSize = wrapper.parentNode.style.fontSize;
            const baseHeight = (Number.parseFloat(fontSize) * 2) / 3;

            img.style.verticalAlign = height > baseHeight ? (baseHeight - height) / 2 + 'px' : baseHeight / 6 + 'px';
        }

        wrapper.replaceWith(img);
    }

    purify(value) {
        const { autoTag, purifyConfig } = this.options,
            args = { scheme: 'Editor', ...purifyConfig };
        if (!autoTag) return htmlPurify(this.convertTitleToTooltip(value), args);
        return htmlPurify(R.Editor.autoTag(this.convertTitleToTooltip(value)), { ...args, FORBID_ATTR: ['class', 'style'] });
    }

    convertTitleToTooltip(value) {
        const { body } = Document.parseHTMLUnsafe(value);

        for (const element of body.querySelectorAll('[title]')) {
            if (element.getAttribute('title')) {
                element.setAttribute('data-tooltip', true);
            }
        }

        return body.innerHTML;
    }

    render() {
        const { ellipsis, row, tooltip } = this.options;

        if (!ellipsis) return <slot />;
        return (
            <aui-ellipsis row={row} tooltip={tooltip}>
                <slot />
            </aui-ellipsis>
        );
    }
}
