import pointFix from './point-fix.js';

/** @type {typeof $$.number.float} */
export default function float(val, digits) {
    let num = Number.parseFloat(val);
    if (digits === 0) {
        num = Math.trunc(num);
    } else if (digits > 0 && digits <= 20) {
        const multiple = Math.pow(10, digits);
        num = Math.trunc(pointFix(num * multiple));
        num /= multiple;
        num = num.toFixed(digits);
    }
    return num;
}
