import base64Url from './base64-url.js';

function download(url, name) {
    const a = document.createElement('a');
    a.setAttribute('target', '_blank');
    a.setAttribute('rel', 'noopener noreferrer');
    a.setAttribute('href', url);
    if (name) {
        a.setAttribute('download', name);
    } else {
        a.toggleAttribute('download', true);
    }
    a.click();
}

/** @type {typeof $$.io.downloadFile} */
export default function downloadFile(source, fileName) {
    if (!source) return null;

    if (typeof source === 'string') {
        let url = source;
        if (url.startsWith('data:') && url.includes(';base64,')) url = base64Url(url);
        download(url, fileName);
    } else if (source instanceof Blob) {
        const url = URL.createObjectURL(source);
        download(url, fileName || source.name);
        setTimeout(() => URL.revokeObjectURL(url));
    }
}
