                unmatchedClass = obj[this.options.statusField] === 'invalid' ? _constant.UNMATCHED_ITEM_CLASS + ' ' : '',
                conflictClass = obj[this.options.statusField] === 'conflict' ? _constant.CONFLICT_CLASS + ' ' : '';

            const settings = {
                role: 'listitem',
                class:
                    unmatchedClass +
                    conflictClass +
                    _constant.SELECTED_ITEM_CONTENT_CLASS +
                    ' ' +
                    (isUndeleteable ? _constant.SELECTED_ITEM_UNDELETABLE_CLASS : _constant.SELECTED_ITEM_DELETABLE_CLASS) +
                    (this.options.itemTemplate ? ' with-template' : '') +
                    (this.options.classField === undefined ? '' : ' ' + obj[this.options.classField]),
                'aria-invalid': !!obj[this.options.statusField],
                'data-value': this._getValueField(obj, this.options.valueField),
            };
