/** @type {typeof $$.regexp.quotation} */
export function quotation(flags) {
    return new RegExp(`(^['"])|(['"]$)`, flags);
}

/** @type {typeof $$.regexp.ghostSpace} @see [ghostSpace](../string/ghost-space.js) */
export function ghostSpace(flags) {
    return new RegExp('\u200B', flags); // 8203=u200B;
}
