import { throws } from '../../core/base/log.js';

import { _parse } from './_parse.js';

/** @type {typeof $$.number.clamp} */
export default function clamp(min, prefer, max) {
    prefer = _parse(prefer);
    if (Number.isFinite(prefer)) {
        min = _parse(min);
        max = _parse(max);
        if (Number.isNaN(min)) min = Number.MIN_SAFE_INTEGER;
        if (Number.isNaN(max)) max = Number.MAX_SAFE_INTEGER;

        if (min < max) return Math.max(min, Math.min(prefer, max));
        if (min === max) return min;

        throws(`The minmax is not a valid range.`, RangeError);
    } else {
        throws(`The prefer argument is not a valid number.`, TypeError);
    }
    return Number.NaN;
}
