export default String.raw`:host {
  flex: 1 1 auto;
  border: var(--border-m) solid var(--focusable-border)
}
.editor {
  flex: inherit;
  grid-area: inherit;
  place-self: inherit;
  overflow: hidden;
  display: flex;
  flex-direction: column;
  border: inherit;
  background: var(--section-bg)
}
.editor > textarea {
  flex: 1 1 auto;
  opacity: 0
}
.editor.readonly {
  background: var(--readonly-bg)
}
.editor.readonly .editor-toolbar {
  pointer-events: none
}
.editor.disabled {
  background: var(--disabled-bg);
  color: var(--disabled-color)
}
.editor.disabled .editor-toolbar {
  display: none
}
.header {
  flex: 0 0 auto;
  display: flex;
  justify-content: flex-end;
  align-items: center;
  border-block-end: var(--border-m) solid var(--normal-border);
  padding: var(--gap-xxs) var(--gap-s);
  height: var(--widget-height-l);
  background-color: var(--body-bg)
}
.body {
  flex: 1 1 auto;
  overflow: auto;
  padding: var(--gap-s);
  user-select: all
}
.footer {
  display: flex;
  flex-wrap: wrap;
  align-items: center;
  padding-inline: var(--gap-xxs) var(--gap-s);
  border-top: var(--border-m) solid var(--focusable-border);
  height: var(--widget-height-xxs);
  background-color: var(--body-bg);
  color: var(--body-color)
}
.resizeable {
  resize: vertical
}
[class^=aui-editor-file]::before {
  display: inline-block;
  width: 1em;
  height: 1em;
  vertical-align: middle
}
