const NewSyntaxSupport = CSS.supports('selector(:state(a))');
let OldSyntaxSupport;
if (!NewSyntaxSupport) {
    try {
        /** Chrome old css syntax(90≤ ver <125). */
        document.querySelector(':--a');
        OldSyntaxSupport = true;
    } catch (e) {
        OldSyntaxSupport = false;
    }
}

export function customStateName(name = '') {
    if (NewSyntaxSupport) return name;
    if (OldSyntaxSupport) return `--${name}`;
    return null;
}
export function customStateQuery(name = '') {
    if (NewSyntaxSupport) return `:state(${name})`;
    if (OldSyntaxSupport) return `:--${name}`;
    return null;
}
/** @param {Element} element */
export function customStateMatch(element, name) {
    const query = customStateQuery(name);
    return query ? element.matches(query) : false;
}
