// Data come from 'es5-shim';

// 09:<ctrl>CHARACTER TABULATION, 0A:<ctrl>LINE FEED, 0B:<ctrl>LINE TABULATION, 0C:<ctrl>FORM FEED, 0D:<ctrl>CARRIAGE RETURN, 20:SPACE, A0:NO-BREAK SPACE;
// 1680:OGHAM SPACE MARK, 180E:MONGOLIAN VOWEL SEPARATOR, 2000:EN QUAD, 2001:EM QUAD, 2002:EN SPACE, 2003:EM SPACE, 2004:THREE-PER-EM SPACE, 2005:FOUR-PER-EM SPACE;
// 2006:SIX - PER - EM SPACE, 2007:FIGURE SPACE, 2008:PUNCTUATION SPACE, 2009:THIN SPACE, 200A:HAIR SPACE, 200B:ZERO WIDTH SPACE, 2028:LINE SEPARATOR;
// 2029:PARAGRAPH SEPARATOR, 202F:NARROW NO-BREAK SPACE, 205F:MEDIUM MATHEMATICAL SPACE, 3000:IDEOGRAPHIC SPACE, \uFEFF:ZERO WIDTH NO-BREAK SPACE;
/** @type {typeof $$.regexp.space} */
export default function space(mode, excludes) {
    const tab = '\x09\x0B',
        lineBreak = '\x0A\x0C\x0D\u2028\u2029',
        space = '\x20\xA0\u1680\u180E\u2000\u2001\u2002\u2003\u2004\u2005\u2006\u2007\u2008\u2009\u200A\u200B\u202F\u205F\u3000\uFEFF';
    let ws = '';
    if (mode) {
        if (mode.includes('tab')) ws += tab;
        if (mode.includes('lineBreak')) ws += lineBreak;
        if (mode.includes('space')) ws += space;
    } else {
        ws = tab + lineBreak + space;
    }
    if (Array.isArray(excludes)) excludes.forEach((s) => (ws = ws.replace(s, '')));
    ws = '[' + ws + ']';
    return ws + ws + '*';
}
