/** @jsxImportSource @gui/aui-devops */
import { addTooltip } from '../../../core/module/tooltip.js';
import { define, Widget, Types } from '../../../widget/widget.js';

import { IdentifierNode } from './identifier.js';
import { NS, TabloopArgs } from './utils.js';

import style from './legend.less';

const I18N = $$.I18N.chart;

/** @extends {Widget<typeof Legend.options>} */
@define(`${NS}-legend`)
export class Legend extends Widget {
    static options = {
        showTotal: Types.Union([Types.boolean, Types.string], false),
        showValue: false,
    };
    static upcasts = ['showValue'];
    static styles = style;

    #total = new Map();
    #data = new Map();
    init() {
        this.state = { total: null, items: [], field: undefined };
        this.dispatcher = this.useUnicom(['box', 'legend'], this.dataReceiver);
    }
    dataReceiver = (action, from, ...args) => {
        $$.fn(this[action], this)(from, ...args);
    };
    didMount() {
        addTooltip(this.host);
    }

    setData(from, total, data, nameField) {
        const legends = data.map((item) => ({ ...item, source: from })),
            [totalValue, totalVal] = Array.isArray(total) ? total : [total];
        this.#total.set(from, totalValue);
        this.#data.set(from, legends);

        const [...items] = this.#data.values(),
            sum = this.#total.size === 1 ? totalVal : Array.from(this.#total.values()).reduce((acc, v) => acc + v, 0);
        this.setState({ total: sum, items: items.flat(), field: nameField });
    }
    clearData(from) {
        this.#data.delete(from);
        this.#total.delete(from);
    }

    attrs(source) {
        const el = source.currentTarget || source,
            [...attrs] = el.attributes;
        return Object.fromEntries(attrs.map(({ name, value }) => [name, value]));
    }
    onFocus = (e) => {
        const { source, name } = this.attrs(e);
        this.dispatcher(source, 'focus', name);
    };
    onBlur = (e) => {
        const { source, name } = this.attrs(e);
        this.dispatcher(source, 'blur', name);
    };

    render() {
        if (!this.host.hasAttribute('slot')) return this.console.error(`Must set the slot attribute to define legend position.`);
        const { showTotal, showValue } = this.options,
            { total, items, field = 'name' } = this.state;
        return (
            <aui-tabloop {...TabloopArgs} className="legend" role="list">
                {showTotal && (
                    <slot name="total" id="total" className="item" part="total" role="heading" aria-level="1">
                        <span className="total-header">{typeof showTotal === 'string' ? showTotal : I18N.total}</span>
                        <span className="total-value" part="total-value">
                            {total}
                        </span>
                    </slot>
                )}
                {items.map((item, i) => {
                    const { type, color, value, val, source } = item,
                        args = { type, color, value, source };
                    return (
                        <IdentifierNode
                            className="item"
                            {...args}
                            name={item[field]}
                            val={showValue ? val : ''}
                            tabIndex={i ? -1 : 0}
                            role="listitem"
                            data-tooltip="ifneed"
                            onFocus={this.onFocus}
                            onBlur={this.onBlur}
                        />
                    );
                })}
            </aui-tabloop>
        );
    }
}
