/** @jsxImportSource @gui/aui-devops */
import { widget } from '../../core/extend/widget.js';

import '../popup/popup.js';

import { getObjectsWidth, calcOverflowIndex } from './calcoverflowindex.js';

const I18N = $$.I18N.breadcrumb;
const _constant = {
    WIDGET_CLASS: 'aui-widget',
    BREADCRUMB_CLASS: 'aui-breadcrumb',
    BREADCRUMB_BOX_CLASS: 'aui-breadcrumb-box',
    BREADCRUMB_ITEM_CLASS: 'aui-breadcrumb-item',
    BREADCRUMB_BUTTON_BOX_CLASS: 'aui-breadcrumb-button-box',
    BREADCRUMB_HIDDEN_ITEM_CLASS: 'aui-breadcrumb-hidden-item',
    BREADCRUMB_MORE_BUTTON_CLASS: 'aui-breadcrumb-more-button',
    BREADCRUMB_MORE_ICON_CLASS: 'faui-ellipsis-dot',
    BREADCRUMB_POPUP_CLASS: 'aui-breadcrumb-popup',
};

(function () {
    widget('aui5.breadcrumb', {
        componentWidth: 0,
        itemsContainerWidth: 0,
        // @type Array:jQuery object
        $items: jQuery(),
        // @type Array:number
        itemsWidth: [],
        // @type number
        itemsWidthSum: 0,
        /**
         * @type number
         * @description The index of the last hidden item.
         * @description -1: There is no hidden items in the component.
         */
        lastHiddenIndex: -1,
        moreItemsBoxWidth: 0,
        itemsNumber: 0,

        options: {
            items: [],
        },
        _create: function () {
            this._initMember()._initEvent()._initResizeObserver();
        },
        _initMember: function () {
            this.$itemsContainer = this.$element.find(`.${_constant.BREADCRUMB_BOX_CLASS}`);

            if (this.options.items.length > 2) {
                this._createMoreItemsBox();
            }

            return this;
        },
        _initEvent: function () {
            this.$element.on('click', `.${_constant.BREADCRUMB_MORE_BUTTON_CLASS}`, () => {
                this.$morePopupList.empty();

                for (let i = 1; i <= this.lastHiddenIndex; i++) {
                    const $item = this.$items.eq(i);
                    const $itemCopy = $item.clone(true).removeAttr('style').attr('data-index', i);
                    $itemCopy.appendTo(this.$morePopupList);
                    $itemCopy.css('margin-inline-start', 16 * (i - 1) + 'px');
                }
            });

            this.$morePopupList?.on('click', 'a, button', (e) => {
                e.preventDefault();

                const currentTarget = e.currentTarget,
                    { index } = currentTarget.parentNode.dataset,
                    tagName = currentTarget.tagName;

                this.$items.eq(index).children(tagName)[0].click();
                this.$morePopup.popup('hide');
            });

            return this;
        },
        _setOption: function (key, value, oldValue) {
            switch (key) {
                case 'items':
                    this._updateItems(value, this.options.items);
                    break;
            }
        },
        setItems: function (value, oldValue) {
            this._updateItems(value, oldValue);
        },
        _updateItems: function (value, oldValue) {
            this.$itemsContainer.removeAttr('style');
            this.prevItemsNumber = oldValue.length;
            this.itemsNumber = value.length;
            const $moreItemsContainer = this.$element.find('.' + _constant.BREADCRUMB_BUTTON_BOX_CLASS);
            if (this.itemsNumber <= 2 && $moreItemsContainer.length > 0) {
                $moreItemsContainer?.empty().remove();
                this.$morePopup?.empty().remove();
            } else if (this.itemsNumber > 2 && $moreItemsContainer.length === 0) {
                this._createMoreItemsBox();
            }
        },
        _initResizeObserver: function () {
            this.itemsContainerResizeObserver = new ResizeObserver((entries) => {
                entries.forEach((entry) => {
                    this.itemsContainerWidth = entry.contentRect.width;

                    this._updateData();
                    this._updateDOM();
                });
            });
            this.itemsContainerResizeObserver.observe(this.$itemsContainer[0]);
            this.componentResizeObserver = new ResizeObserver((entries) => {
                entries.forEach((entry) => {
                    this.componentWidth = entry.contentRect.width;

                    this._updateDOM();
                });
            });
            this.componentResizeObserver.observe(this.$element[0]);
        },
        _createMoreItemsBox: function () {
            const moreBox = (
                <li className={[_constant.BREADCRUMB_ITEM_CLASS, _constant.BREADCRUMB_BUTTON_BOX_CLASS, _constant.BREADCRUMB_HIDDEN_ITEM_CLASS]}>
                    <aui-button className={_constant.BREADCRUMB_MORE_BUTTON_CLASS} type="bald" icon={_constant.BREADCRUMB_MORE_ICON_CLASS} tooltip={I18N.more} />
                    <div className={_constant.BREADCRUMB_POPUP_CLASS} tabIndex="0" />
                </li>
            );
            if (this.prevItemsNumber === 0) {
                jQuery(moreBox).appendTo(this.$itemsContainer);
            } else {
                jQuery(moreBox).insertAfter(this.$itemsContainer.find('li:first-child'));
            }

            this.$moreButton = this.$element.find('.' + _constant.BREADCRUMB_MORE_BUTTON_CLASS);
            this.$morePopup = this.$element.find('.' + _constant.BREADCRUMB_POPUP_CLASS).popup({
                of: this.$moreButton,
                triggerEvent: 'click',
            });
            this.$morePopupList = jQuery(<ol />);
            this.$morePopupList.appendTo(this.$morePopup.find('.aui-popup-body'));
        },
        _updateData: function () {
            const $moreItemsContainer = this.$element.find('.' + _constant.BREADCRUMB_BUTTON_BOX_CLASS);
            if ($moreItemsContainer.length) {
                this.moreItemsBoxWidth = $moreItemsContainer.outerWidth(true);
            } else {
                this.moreItemsBoxWidth = 0;
            }

            this.$items = this.$itemsContainer.children().not(`[class~=${_constant.BREADCRUMB_BUTTON_BOX_CLASS}]`);

            this.itemsWidth = getObjectsWidth(this.$items, true, false);

            this.itemsWidth.pop();
            this.itemsWidth.push(
                this.$items
                    .eq(this.$items.length - 1)
                    .removeAttr('style')
                    .outerWidth(true)
            );

            this.itemsWidthSum = 0;
            for (const itemWidth of this.itemsWidth) {
                this.itemsWidthSum += itemWidth;
            }
        },
        _updateDOM: function () {
            const $moreItemsContainer = this.$element.find('.' + _constant.BREADCRUMB_BUTTON_BOX_CLASS);
            if (this.itemsWidthSum > this.componentWidth) {
                let basicWidth = this.itemsWidth[0];
                if (this.itemsNumber > 1) {
                    basicWidth += this.moreItemsBoxWidth + this.itemsWidth.at(-1);
                }

                if (basicWidth > this.componentWidth) {
                    this.lastHiddenIndex = this.$items.length - 2;

                    this.$itemsContainer.css('width', '100%');
                    this.$items.filter(`:lt(${this.lastHiddenIndex + 1}):gt(0)`).hide();
                    this.$items.first().removeAttr('style');
                    this.$items.last().removeAttr('style').css('flex', 'auto');
                } else {
                    this.$itemsContainer.removeAttr('style');

                    this.$items.filter(`:lt(${this.$items.length}):gt(0)`).removeAttr('style');
                    const itemsWidthCopy = jQuery.extend(true, [], this.itemsWidth);
                    itemsWidthCopy.shift();
                    itemsWidthCopy.pop();

                    this.lastHiddenIndex = 1 + calcOverflowIndex(this.componentWidth - this.itemsWidth[0] - this.moreItemsBoxWidth - this.itemsWidth.at(-1), itemsWidthCopy, true);

                    this._displayItems([this.lastHiddenIndex + 1, this.$items.length - 1], true);
                    this._displayItems([1, this.lastHiddenIndex + 1], false);
                }

                $moreItemsContainer?.removeClass(_constant.BREADCRUMB_HIDDEN_ITEM_CLASS);
            } else {
                this.lastHiddenIndex = -1;
                this.$itemsContainer.removeAttr('style');
                this.$items.filter(`:lt(${this.$items.length}):gt(0)`).removeAttr('style');

                this.$items.removeClass(_constant.BREADCRUMB_HIDDEN_ITEM_CLASS);
                $moreItemsContainer?.addClass(_constant.BREADCRUMB_HIDDEN_ITEM_CLASS);
            }
        },

        /**
         * @description Display or hide items.
         * @param range {Array:[number,number]}
         * @param isDisplay {Array:[number,number]}
         */
        _displayItems: function (range, isDisplay = true) {
            this.$items.filter(`:lt(${range[1]}):gt(${range[0] - 1})`).toggleClass(_constant.BREADCRUMB_HIDDEN_ITEM_CLASS, !isDisplay);
        },

        _destroy: function () {
            this.itemsContainerResizeObserver.unobserve(this.$itemsContainer[0]);
            this.componentResizeObserver.unobserve(this.$element[0]);

            this.$morePopup?.popup('destroy');
        },
    });
})();
