/** @jsxImportSource @gui/aui-devops */
import { define, Widget, Types } from '../../widget/widget.js';

import style from './style.less';

const Role = {
    info: 'log',
    warn: 'status',
    error: 'alert',
    success: 'status',
};
const Icon = {
    info: 'faui-comment',
    warn: 'faui-warning-solid',
    error: 'faui-error-solid',
    success: 'faui-finish-solid',
};
const DefaultClassify = 'info';
const classifyI18N = $$.I18N.core.classify;

/** @extends {Widget<typeof Messagebar.options>} */
@define('messagebar')
export class Messagebar extends Widget {
    static options = {
        status: Types.Object({ show: [Types.boolean, false] }),
        classify: Types.Classify(true, 'types', DefaultClassify),
        hasClose: true,
        icon: Types.string,
        message: Types.Content,
    };
    static observers = ['message', 'hasClose', 'status', 'classify'];
    static shadow = { delegatesFocus: true };
    static styles = style;

    init() {
        Object.values(Icon).forEach((icon) => this.fontIcon(icon));
    }
    onClose = (e) => {
        this.options.status.show = false;
        this.setState();
        $$.fn(this.options.onClose)(e);
    };

    render() {
        const { classify, hasClose, icon, message, status } = this.options;
        if (!status.show) return false;
        const classifyName = classify?.name;

        return (
            <div
                className="messagebar empty-hidden"
                tabIndex={0}
                role="alert"
                classify={classify}
                aria-roledescription={classifyI18N[classifyName] ?? classifyI18N[DefaultClassify]}
            >
                <div className="box" aria-live="polite">
                    <div className={['icon', icon ?? Icon[classifyName] ?? Icon[DefaultClassify]]}></div>
                    <slot className="message" role={Role[classifyName] ?? Role[DefaultClassify]}>
                        {message}
                    </slot>
                    {hasClose !== false && <aui-button-lite type="plain" tooltip={$$.I18N.messagebar.close} icon="faui-close" className="close" onClick={this.onClose} />}
                </div>
            </div>
        );
    }
}
