import is from './is.js';

/** @param {HTMLElement} element  */
export function flatChildren(element, args = {}) {
    const { crossSlot, crossShadow, directChildren, until } = args;
    if (crossSlot && element.localName === 'slot') return flatSlot(element, args);
    if (crossShadow && element.shadowRoot) return flatShadow(element, args);
    if (element.contentEditable === 'true' && !directChildren) return [];
    const children = Array.from(element.children);
    if (!until) return children;
    return children.filter((el) => !is.call(el, until));
}

/** @param {HTMLSlotElement} element  */
export function flatSlot(element, args) {
    const assigned = element.assignedNodes().length > 0;
    if (!assigned) return Array.from(element.children);
    const list = element.assignedElements({ flatten: false });
    return list;
}

/** @param {HTMLElement} element  */
export function flatShadow(element, { directChildren }) {
    const list = Array.from(element.shadowRoot.children);
    return directChildren ? Array.from(element.children).concat(list) : list;
}
