import React from 'react';

import { WR } from '../../widget/widget.jsx';

import { Badge } from '../badge/badge.jsx';
import { Button } from '../button/button.jsx';
import { Popup } from '../popup/popup.jsx';

const ComponentName = 'aui-notification';
const ClassNames = {
    Widget: ComponentName,
    Trigger: `${ComponentName}-trigger`,
    TriggerIcon: 'faui-notification',
    Popup: `${ComponentName}-popup`,
    Header: `${ComponentName}-header`,
    Actions: `${ComponentName}-actions`,
    List: `${ComponentName}-list`,
    Item: `${ComponentName}-item`,
    Empty: `${ComponentName}-empty`,
};
const I18N = $$.I18N.notification;

export class Notification extends R.Component {
    componentCreate() {
        this.triggerId = `${ClassNames.Trigger}-${this.uuid}`;

        this.state = {
            badge: this.getBadge(),
        };
    }

    componentUpdate() {
        this.setState({ badge: this.getBadge() });
    }

    handlePopupHide = () => {
        const { items } = this.props;

        for (const item of items) {
            item.state = 'read';
        }

        this.setState({ badge: this.getBadge() });
    };

    getBadge() {
        const { items } = this.props;

        return items.filter((item) => {
            return item.state === 'unread';
        }).length;
    }

    handleToastTitleClick = (item, onLink) => {
        return () => {
            onLink(item);
        };
    };

    render() {
        const { id, actions, status, slot, items = [], onLink = null } = this.props;
        const { badge } = this.state;

        return (
            <div slot={slot} id={id} className={ClassNames.Widget}>
                <Badge classify="theme" mode="nav" value={badge} type="number">
                    <Button className={ClassNames.Trigger} id={this.triggerId} aria={I18N.header} icon={ClassNames.TriggerIcon} type="plain" />
                </Badge>
                <Popup
                    className={ClassNames.Popup}
                    arrow
                    at="right bottom"
                    closeable
                    destroy
                    flip={false}
                    maxHeight={500}
                    modalable
                    my="right top"
                    of={`#${this.triggerId}`}
                    status={status}
                    title={
                        <div className={ClassNames.Header}>
                            <span>{I18N.header}</span>
                            {actions && <section className={ClassNames.Actions}>{actions}</section>}
                        </div>
                    }
                    triggerEvent="click"
                    width={480}
                    onHide={this.handlePopupHide}
                >
                    <ul className={ClassNames.List}>
                        {items.length ? (
                            items.map((item, index) => {
                                const { classify, className, description, link, ...args } = item;

                                return (
                                    <li key={`${ClassNames.Item}-${index}`} className={`${ClassNames.Item} ${className || ''}`} aria-description={description}>
                                        <WR.Toast {...args} classify={classify} closeable={false} focusable={false} timeout={0}>
                                            {classify === 'bell' && link && (
                                                <WR.ButtonLite slot="title" type="link" onClick={this.handleToastTitleClick(item, onLink)}>
                                                    <span slot="text">{link}</span>
                                                </WR.ButtonLite>
                                            )}
                                        </WR.Toast>
                                    </li>
                                );
                            })
                        ) : (
                            <div className={ClassNames.Empty}>{I18N.empty}</div>
                        )}
                    </ul>
                </Popup>
            </div>
        );
    }
}

$$.shell.define('Notification', Notification);
